PROVA_GUSCIO = ("/", "/miniapp.html", "/manifest.json", "/sw.js",
                "/offline.html", "/robots.txt")
PROVA_GUSCIO_PREFISSI = ("/assets/", "/vendor/")
PROVA_GUSCIO_MAI = ("/assets/og/",)
# IL COOKIE D'AMMISSIONE: chi ha dimostrato di essere in lista (firma
# dell'initData o sessione web) lo riceve, e con lui passano anche le
# chiamate del client che partono senza identita'. La chiave nasce dal
# BOT_TOKEN della prova (nessun segreto nuovo da custodire: cambia il
# token, cadono i cookie), la lista si riguarda a ogni richiesta.
PROVA_COOKIE = "barattolo_prova"
PROVA_COOKIE_GIORNI = 30


def _prova_esente(percorso: str) -> bool:
    """PURA: questa rotta resta aperta a tutti anche sulla prova?"""
    return (percorso in PROVA_PORTE_APERTE
            or percorso.startswith(PROVA_PREFISSO_LOGIN))


def _prova_guscio(percorso: str) -> bool:
    """PURA: e' un pezzo del guscio (la pagina vuota e i suoi file)?"""
    if percorso in PROVA_GUSCIO:
        return True
    return (percorso.startswith(PROVA_GUSCIO_PREFISSI)
            and not percorso.startswith(PROVA_GUSCIO_MAI))


def _prova_decide(chi, ammessi: set) -> bool:
    """PURA: passa solo chi ha DIMOSTRATO un id che sta in lista. Senza
    identita' non si passa (il guscio e le porte aperte li decide il
    middleware prima di chiedere qui)."""
    return chi is not None and chi in ammessi


def _prova_chiave_cookie() -> bytes:
    return hashlib.sha256(b"barattolo-prova-ammesso:"
                          + str(BOT_TOKEN).encode()).digest()


def _prova_cookie_nuovo(tg_id: int, ora: int, chiave: bytes) -> str:
    """PURA: «id.scadenza.firma»."""
    scade = int(ora) + PROVA_COOKIE_GIORNI * 86400
    firma = hmac.new(chiave, f"{int(tg_id)}.{scade}".encode(),
                     hashlib.sha256).hexdigest()[:32]
    return f"{int(tg_id)}.{scade}.{firma}"


def _prova_cookie_chi(valore: str, ora: int, chiave: bytes):
    """PURA: l'id che il cookie porta, o None (forma storta, firma che non
    torna — a tempo costante —, scaduto)."""
    m = re.fullmatch(r"(-?[0-9]{1,20})\.([0-9]{1,12})\.([0-9a-f]{32})",
                     str(valore or ""))
    if not m:
        return None
    attesa = hmac.new(chiave, f"{m.group(1)}.{m.group(2)}".encode(),
                      hashlib.sha256).hexdigest()[:32]
    if not hmac.compare_digest(attesa, m.group(3)):
        return None
    if int(m.group(2)) <= int(ora):
        return None
    return int(m.group(1))


def _prova_ignora_update(aggiornamento, ammessi: set) -> bool:
    """PURA: il bot di prova lascia cadere questo update? (19 ott 2026,
    decisione di Andrea: chi non e' in lista non riceve NIENTE, nemmeno
    la risposta al /start, e non finisce scritto nel database.)
    Lista vuota = la produzione: non si lascia cadere nulla. Il mittente
    e' il `from` del messaggio, del tocco su un bottone o (dal 10 nov
    2026, solo sulla prova) del tocco dentro un widget: i tipi che il
    webhook chiede (`aggiornamenti_chiesti`). Senza un mittente
    leggibile l'update cade: sulla prova si sbaglia dal lato chiuso."""
    if not ammessi:
        return False
    if not isinstance(aggiornamento, dict):
        return True
    for chiave in ("message", "edited_message", "callback_query",
                   "widget_query"):
        corpo = aggiornamento.get(chiave)
        if isinstance(corpo, dict):
            mittente = corpo.get("from")
            try:
                return int(mittente["id"]) not in ammessi
            except (TypeError, KeyError, ValueError):
                return True
    return True


async def _prova_chi(request) -> tuple:
    """(id, come, perche'): l'id che la richiesta DIMOSTRA e da dove.
    `come`: 'firma' (initData, lo stesso giudice delle rotte, che non
    scrive), 'sessione' (il cookie del login web), 'cookie' (quello
    d'ammissione), '' (nessuno), 'rotta' (un initData presente ma
    sbagliato o scaduto: `perche'` e' la frase del suo 401)."""
    init = request.headers.get("x-tg-init-data", "")
    if init:
        try:
            return int(_utente_da_initdata(init)["id"]), "firma", ""
        except HTTPException as e:
            return None, "rotta", str(e.detail)
        except Exception:
            return None, "rotta", "Autenticazione Telegram non valida"
    token = request.cookies.get("barattolo_sessione", "")
    if token:
        try:
            u = await asyncio.to_thread(utente_da_sessione, token)
        except Exception:
            u = None
        if u:
            return int(u["id"]), "sessione", ""
    chi = _prova_cookie_chi(request.cookies.get(PROVA_COOKIE, ""),
                            int(time.time()), _prova_chiave_cookie())
    if chi is not None:
        return chi, "cookie", ""
    return None, "", ""


@app.middleware("http")
async def solo_chi_prova(request, call_next):
    """Registrato DOPO gli altri, quindi gira PRIMA di tutti: chi non e'
    ammesso non arriva nemmeno a scrivere il suo utente nel database.
    Chi non e' ammesso: il guscio si', le API 403 (401 se l'initData e'
    scaduto: il client lo sa dire), ogni altra pagina torna a `/`, dove
    c'e' la copertina col login."""
    if not PROVA_SOLO_IDS or PROVA_APERTA or _prova_esente(request.url.path):
        return await call_next(request)
    percorso = request.url.path
    chi, come, perche = await _prova_chi(request)
    if _prova_decide(chi, PROVA_SOLO_IDS):
        risposta = await call_next(request)
        if come in ("firma", "sessione"):
            ora = int(time.time())
            gia = _prova_cookie_chi(request.cookies.get(PROVA_COOKIE, ""),
                                    ora, _prova_chiave_cookie())
            if gia != chi:
                risposta.set_cookie(
                    PROVA_COOKIE,
                    _prova_cookie_nuovo(chi, ora, _prova_chiave_cookie()),
                    max_age=PROVA_COOKIE_GIORNI * 86400, httponly=True,
                    secure=cookie_sicuro(), samesite="lax", path="/")
        return risposta
    no_cache = {"Cache-Control": "no-store"}
    if _prova_guscio(percorso):
        if percorso == "/":
            request.scope["path"] = "/miniapp.html"
        return await call_next(request)
    if percorso.startswith("/api/"):
        if come == "rotta":
            return JSONResponse({"detail": perche}, status_code=401,
                                headers=no_cache)
        return JSONResponse({"detail": MSG_PROVA_PRIVATA}, status_code=403,
                            headers=no_cache)
    return RedirectResponse("/", status_code=303, headers=no_cache)


def su_onion() -> bool:
    """La richiesta corrente e' arrivata dal servizio nascosto?

    Si guarda l'HOST, che dietro Caddy e' affidabile — lo dice gia'
    `guardia_csrf`, che sullo schema invece non conta. Scartato un
    header messo da Caddy sul blocco onion: dipenderebbe da una riga
    di configurazione che qualcuno puo' togliere, e andrebbe
    CANCELLATO sul blocco clearnet, o chiunque potrebbe fingersi
    onion da fuori mettendoselo da se'.

    FAIL-CLOSED verso il mondo di ieri, due volte: senza ONION_HOST
    configurato, e con un contextvar mai scritto (le prove che
    chiamano le funzioni della pagina direttamente, uno script a
    mano), la risposta e' NO — cioe' la pagina esce esattamente com'e'
    sempre stata. Per accendere qualcosa serve che tutt'e due i lati
    dicano di si'."""
    if not ONION_HOST:
        return False
    # La porta non fa parte dell'identita' dell'host, e Tor puo'
    # inoltrare su una porta qualunque.
    arrivato = _HOST_RICHIESTA.get("").split(":")[0].strip().lower()
    return bool(arrivato) and arrivato == ONION_HOST.strip().lower()


def dal_tunnel() -> bool:
    """La richiesta corrente e' arrivata dal servizio nascosto E lo
    conferma il blocco onion di Caddy? Tutt'e due, o e' no (il perche'
    sta sopra `_SEGNALE_RICHIESTA`)."""
    if not ONION_SEGNALE or not su_onion():
        return False
    return hmac.compare_digest(_SEGNALE_RICHIESTA.get("").encode(),
                               ONION_SEGNALE.encode())


def cookie_sicuro(collaudo: bool = MODALITA_COLLAUDO) -> bool:
    """L'attributo Secure dei cookie di sessione e portachiavi: sempre,
    salvo in collaudo (in locale siamo su http) e sul tunnel Tor
    (`dal_tunnel`). E' l'UNICA cosa che cambia: HttpOnly, SameSite,
    durata e percorso restano identici su ogni porta."""
    if collaudo:
        return False
    return not dal_tunnel()


# ------------------------- DATABASE --------------------------------
# QUANTO ASPETTA UNA CONNESSIONE SUL LUCCHETTO (1 ott 2026, «database is
# locked»). Sqlite ha UNO scrittore alla volta su tutto il file, e una
# connessione che trova il lucchetto preso aspetta fino a questo tempo
# prima di alzare «database is locked». Il default di Python sono 5
# secondi, e NON ERA SCRITTO: il 1 ott 2026 il giro di un negozio
# collegato ha tenuto il lucchetto per minuti (le foto scaricate dentro
# la transazione, curato in `importa_negozio`) e ogni rotta che
# scriveva moriva dopo i suoi 5 secondi. Adesso le scritture del giro
# sono brevi per costruzione; i 15 secondi coprono quel che resta
# lungo per natura — il backup con l'API di sqlite (pre-deploy e
# giornaliero) tiene il file in lettura per tutta la copia, e un
# commit che gli capita addosso aspetta invece di morire. Lo stesso
# numero di `importa_nostr`, per la stessa ragione. Il prezzo e'
# dichiarato: le rotte parlano con sqlite nel ciclo principale, quindi
# un'attesa qui e' un'attesa di TUTTO il server — e proprio per
# questo la cura vera sono le transazioni brevi, non il numero.
try:
    from config import DB_BUSY_TIMEOUT
except ImportError:
    DB_BUSY_TIMEOUT = 15


def db():
    con = sqlite3.connect(DB, timeout=DB_BUSY_TIMEOUT)
    con.row_factory = sqlite3.Row
    return con


# ------------- IL CANALE TELEGRAM, DECISO DAL BOT -------------------
# Fino all'ago 2026 il canale del mercatino viveva SOLO in
# `TELEGRAM_CANALE_ID`, cioe' cambiarlo voleva dire entrare nel VPS,
# ritoccare il config e riavviare. Adesso lo si dice al bot
# (`/canale @nome`) e la scelta finisce nella tabella `impostazioni`,
# che vince sul config.
#
# PERCHE' IL CONFIG NON BASTA PIU', e perche' questa NON e' una deroga
# alla regola «le leve si guardano e basta» del pannello admin: quella
# regola difende gli interruttori che muovono denaro — ASTA_ABILITATA,
# IMPORT_NOSTR_APERTO, AUTO_SBLOCCO_ATTIVO nascono spenti apposta
# perche' accenderli costi un gesto dal VPS. Un id di canale non
# accende niente: dice DOVE il bot parla, e sbagliarlo si vede subito
# e si corregge con un altro comando. Il config resta il valore di
# PARTENZA (e quindi il modo di ripulire: si svuota la riga e si
# torna a lui).
#
# La cache in memoria e' un tantum all'avvio: `_CANALE` = None vuol
# dire «non ancora letto», e da li' in poi si rilegge solo quando
# qualcuno lo cambia. Il processo e' uno solo (uvicorn mono-processo,
# lo stesso patto di SFIDE_LOGIN e CODICI_FUSIONE), quindi non esiste
# una seconda copia da tenere allineata.

_CANALE = None          # None = mai letto; str = il valore che vale
_CANALE_RIEPILOGO = None   # idem, ma per il post del lunedi'
_CANALE_VETRINA = None     # e per il canale della comunita'


def impostazione(chiave: str, ripiego: str = "") -> str:
    """Legge una riga di `impostazioni`. Fail-open: al primo avvio la
    tabella puo' non esistere ancora e vale il ripiego."""
    try:
        con = db()
        r = con.execute("SELECT valore FROM impostazioni WHERE chiave=?",
                        (chiave,)).fetchone()
        con.close()
        return r["valore"] if r else ripiego
    except sqlite3.OperationalError:
        return ripiego


def scrivi_impostazione(chiave: str, valore: str):
    """Scrive (o riscrive) una riga di `impostazioni`."""
    con = db()
    con.execute("INSERT INTO impostazioni(chiave, valore) VALUES(?,?) "
                "ON CONFLICT(chiave) DO UPDATE SET valore=excluded.valore",
                (chiave, valore))
    con.commit()
    con.close()


def canale_id() -> str:
    """IL GIUDICE UNICO di «dove parla il bot». Vuoto = nessun canale,
    e allora i post automatici semplicemente non escono (fail-open di
    sempre). Da qui passano TUTTI i punti che scrivono, editano o
    cancellano nel canale: se un giorno divergessero, il ✅ Venduto
    finirebbe in un canale e il post originale in un altro."""
    global _CANALE
    if _CANALE is None:
        _CANALE = impostazione("canale_telegram", TELEGRAM_CANALE_ID)
    return _CANALE


def canale_riepilogo() -> str:
    """DOVE VA IL RIEPILOGO DEL LUNEDI' (ago 2026, decisione di
    Andrea): un canale SUO — il racconto della settimana e la sfilza
    degli annunci nuovi hanno due pubblici, e chi segue la vetrina non
    deve per forza leggere i conti.

    IL RIPIEGO E' `canale_id()` E NON IL SILENZIO: senza una riga
    scritta da nessuna parte il riepilogo esce dov'e' sempre uscito —
    un canale non configurato non deve poter far sparire un post
    settimanale senza che nessuno se ne accorga. Per spegnerlo
    davvero c'e' la leva `RIEPILOGO_SETTIMANALE`, che e' il posto
    dove si va a cercare quando il lunedi' non arriva niente."""
    global _CANALE_RIEPILOGO
    if _CANALE_RIEPILOGO is None:
        _CANALE_RIEPILOGO = impostazione("canale_riepilogo",
                                         TELEGRAM_CANALE_RIEPILOGO)
    return _CANALE_RIEPILOGO or canale_id()

def imposta_canale_riepilogo(valore: str) -> str:
    """Cambia il canale del riepilogo e riallinea la cache. Vuoto =
    torna al ripiego, cioe' il canale degli annunci: qui la stringa
    vuota NON e' lo spegnimento (a spegnere c'e' la leva), ed e' la
    differenza con `imposta_canale` — li' il vuoto e' un gesto di chi
    vuole il silenzio, qui e' «rimettili dove stanno gli altri»."""
    global _CANALE_RIEPILOGO
    valore = (valore or "").strip()
    scrivi_impostazione("canale_riepilogo", valore)
    _CANALE_RIEPILOGO = valore
    return valore

def canale_vetrina() -> str:
    """DOVE ANDIAMO OSPITI (ago 2026, decisione di Andrea): un canale
    della comunita' — oggi @subito_crypto_vetrina, con 700 membri —
    dove i nostri annunci nuovi compaiono per farci conoscere.

    NIENTE RIPIEGO, ed e' la differenza col riepilogo: li' il vuoto
    rimette il post dove vanno gli altri, perche' sono tutti CASA
    NOSTRA e perdere un post settimanale sarebbe peggio. Qui il
    canale e' di qualcun ALTRO: vuoto vuol dire «non ci andiamo», e
    ripiegare sul nostro vorrebbe dire mandare in un posto un
    messaggio pensato per un altro. Un'assenza non e' una bugia.

    E CHI CI ENTRA E' PIU' STRETTO di chi entra nel nostro (vedi
    `_posta_promo_singolo`): li' vale l'@username, che e' la maniglia
    che quel pubblico si aspetta."""
    global _CANALE_VETRINA
    if _CANALE_VETRINA is None:
        _CANALE_VETRINA = impostazione("canale_vetrina",
                                       TELEGRAM_CANALE_VETRINA)
    return _CANALE_VETRINA


def imposta_canale_vetrina(valore: str) -> str:
    """Cambia il canale della comunita' e riallinea la cache. Vuoto =
    non ci si posta piu': qui la stringa vuota E' lo spegnimento (il
    contrario del riepilogo), perche' non esiste nessun altro posto
    dove quei messaggi debbano andare."""
    global _CANALE_VETRINA
    valore = (valore or "").strip()
    scrivi_impostazione("canale_vetrina", valore)
    _CANALE_VETRINA = valore
    return valore


_CANALE_BITCOIN_PODCAST = None


def canale_bitcoin_podcast() -> str:
    """Canale secondario BitcoinPodcastTelegram (ott 2026)."""
    global _CANALE_BITCOIN_PODCAST
    if _CANALE_BITCOIN_PODCAST is None:
        _CANALE_BITCOIN_PODCAST = impostazione(
            "canale_bitcoin_podcast", TELEGRAM_CANALE_BITCOIN_PODCAST)
