MAX_WIDGET_ORDINI = 8          # quanti ne entrano in 600 px d'altezza
BYTE_WIDGET_ORDINI = 1000      # sotto i 1024 di `chat_data` e della risposta
ALTEZZA_WIDGET_ORDINI = 540    # fissa: elenco e pagina dell'ordine ci stanno

