def _riga_widget_ordini(o, tg_id: int) -> list:
    """PURA: un ordine stretto nei sei campi della scheda — numero,
    stato (l'indice in `STATI_WIDGET_ORDINI`), ruolo di chi guarda
    («b» compra, «s» vende), consegna (s/r/d/v), sats, titolo corto."""
    stato = o["stato"] if o["stato"] in STATI_WIDGET_ORDINI else "locked"
    tipo = {"ritiro": "r", "digitale": "d", "servizio": "v"}.get(
        _campo(o, "consegna_scelta"), "s")
    titolo = _campo(o, "titolo") or (
        f"Carrello di {_campo(o, 'pezzi', 0)} oggetti"
        if _campo(o, "pezzi", 0) else "Ordine")
    titolo = " ".join(str(titolo).split())
    if len(titolo) > 30:
        titolo = titolo[:29].rstrip() + "…"
    return [int(o["id"]), STATI_WIDGET_ORDINI.index(stato),
            "b" if o["compratore_id"] == tg_id else "s", tipo,
            int(o["prezzo_sats"] or 0), titolo]


def elenco_widget_ordini(righe: list, tg_id: int) -> str:
    """PURA: il JSON che viaggia nella scheda. Prima gli attivi, poi i
    conclusi, in ciascun gruppo dal piu' mosso di recente; al piu'
    `MAX_WIDGET_ORDINI`, e mai oltre `BYTE_WIDGET_ORDINI` byte (si
    toglie dal fondo: un JSON tagliato a meta' non si leggerebbe). `a` e
    `n` contano TUTTI gli ordini, anche quelli che non entrano. La
    fattura annullata e pagata non esce a chi vende (`_nascosto_a`), e
    nemmeno l'ordine che quella parte ha nascosto dalla sua lista."""
    miei = []
    for o in righe:
        compra = o["compratore_id"] == tg_id
        if not compra and o["venditore_id"] != tg_id:
            continue      # non e' suo: la query lo dice gia', qui si ripete
        if _nascosto_a(o, tg_id) or _campo(
                o, "nascosto_compratore" if compra else "nascosto_venditore", 0):
            continue
        miei.append(o)
    miei.sort(key=lambda o: (o["stato"] in CONCLUSI_WIDGET_ORDINI,
                             -int(_campo(o, "aggiornato", 0) or _campo(o, "creato", 0) or 0),
                             -int(o["id"])))
    attivi = sum(o["stato"] not in CONCLUSI_WIDGET_ORDINI for o in miei)
    scelti = [_riga_widget_ordini(o, tg_id) for o in miei[:MAX_WIDGET_ORDINI]]
    while True:
        testo = json.dumps({"a": attivi, "n": len(miei), "o": scelti},
                           ensure_ascii=False, separators=(",", ":"))
        if len(testo.encode("utf-8")) <= BYTE_WIDGET_ORDINI or not scelti:
            return testo
        scelti.pop()


def _leggi_widget_ordini(tg_id: int) -> str:
    """L'elenco di `tg_id`, letto adesso dal database (sola lettura)."""
    con = db()
    try:
        righe = con.execute(
            "SELECT o.*, a.titolo, (SELECT COALESCE(SUM(r.quantita),0) "
            "FROM ordine_righe r WHERE r.ordine_id=o.id) AS pezzi "
            "FROM ordini o LEFT JOIN annunci a ON a.id=o.annuncio_id "
            "WHERE o.compratore_id=? OR o.venditore_id=?",
            (tg_id, tg_id)).fetchall()
    finally:
        con.close()
    return elenco_widget_ordini(righe, tg_id)


def html_widget_ordini() -> str:
    """La paginetta col suo indirizzo di casa: «Apri in Barattolo» vuole
    un https (`openLink` non apre altro), e senza il bottone non c'e'."""
    url = str(URL_PUBBLICO or "").rstrip("/")
    return HTML_WIDGET_ORDINI.replace(
        "__URL__", url if url.startswith("https://") and '"' not in url else "")


async def comando_ordini(mittente: dict):
    """`/ordini` — la scheda coi propri ordini del mercatino. Solo
    sull'istanza di prova (altrove e' un comando che non esiste), per
    chiunque ci sia ammesso: ognuno vede i suoi."""
    chat = mittente["id"]
    if not widget_prova_acceso():
        return await _comando_sconosciuto(chat)
    r = await bot_api("sendWidget", {
        "chat_id": chat, "html": html_widget_ordini(),
        "width": 0, "height": ALTEZZA_WIDGET_ORDINI,
        "chat_data": _leggi_widget_ordini(chat), "allow_queries": True,
        "caption": "🫙 I tuoi ordini del mercatino. La scheda si "
                   "aggiorna da sola; tocca un ordine per vederne i passi."})
    await _riferisci_widget(chat, "sendWidget", r)


async def comando_dove(msg: dict, mittente: dict):
    """`/dove` — «in che gruppo e in che argomento siamo?». Solo admin.

    Serve a trovare i numeri da scrivere in `ADMIN_CANALE_ID` e in
    `ADMIN_CANALE_ARGOMENTI` senza far entrare nel gruppo il bot di un
    estraneo: si scrive `/dove` dentro ogni argomento e la risposta
    porta i due numeri. PER QUESTO RISPONDE IN QUALUNQUE GRUPPO, e non
    solo in quello gia' scritto nel config: il giorno che serve, il
    config quel numero non ce l'ha ancora. A chi non e' admin, in un
    gruppo, non risponde niente (e in privato quel che risponde a ogni
    comando che non esiste). Dice dove siamo e nient'altro."""
    chat = msg.get("chat") or {}
    privata = chat.get("type") == "private"
    if not e_admin_bot(mittente):
        if privata:
            return await _comando_sconosciuto(mittente["id"])
        return
    if privata:
        return await bot_api("sendMessage", {
            "chat_id": mittente["id"], "parse_mode": "HTML",
            "text": "📍 Qui siamo in privato, io e te.\n\nScrivi "
                    "<code>/dove</code> nel gruppo degli admin, dentro ogni "
                    "argomento: ti rispondo lì coi numeri da mettere nel "
                    "config."})
    stanza = (int(msg.get("message_thread_id") or 0)
              if msg.get("is_topic_message") else 0)
    righe = ["📍 <b>Dove siamo</b>", "",
             f"Gruppo: <code>{int(chat.get('id') or 0)}</code>"]
    if chat.get("type") != "supergroup" or not chat.get("is_forum"):
        righe.append("⚠️ Qui gli argomenti non sono accesi: accendili dalle "
                     "impostazioni del gruppo e riscrivi <code>/dove</code> "
                     "— accendendoli il numero del gruppo può cambiare.")
    elif stanza:
        righe.append(f"Argomento: <code>{stanza}</code>")
    else:
        righe.append("Argomento: Generale — non ha un numero, nel config "
                     "non si scrive.")
    if gruppo_admin_id() and chat.get("id") == gruppo_admin_id():
        qui = [ADMIN_ARGOMENTI[n] for n, s in _GRUPPO_ADMIN["stanze"].items()
               if stanza and s == stanza]
        righe += ["", "✅ È il gruppo scritto in <code>ADMIN_CANALE_ID</code>."
                  + (f" Qui arrivano: {', '.join(qui)}." if qui else "")]
    dati = {"chat_id": chat.get("id"), "parse_mode": "HTML",
            "text": "\n".join(righe)}
    if stanza:
        dati["message_thread_id"] = stanza
    return await bot_api("sendMessage", dati)


async def _comando_nel_gruppo(msg: dict, mittente: dict, testo: str):
    """Un messaggio arrivato da un GRUPPO (12 ott 2026). Fino a ieri il
    bot ascoltava le sole chat private; adesso i comandi di servizio
    valgono anche nel gruppo degli admin. TRE PORTE, in fila:
     · e' un comando (comincia per `/`)? Il resto, in un gruppo, il bot
       non lo legge e non gli risponde: li' la gente parla fra se';
     · chi scrive e' in `ADMIN_IDS`? Lo dice Telegram col MITTENTE del
       messaggio, come in privato. Essere nel gruppo non basta: nel
       gruppo si puo' invitare chiunque, in ADMIN_IDS no. Un admin che
       scrive da «anonimo» non ha mittente, e non passa;
     · il gruppo e' QUELLO di `ADMIN_CANALE_ID`? Solo `/dove` risponde
       altrove (vedi li' il perche').
    A chi non passa non si risponde NIENTE: il silenzio di
    `_comando_sconosciuto`, senza nemmeno i bottoni. La risposta esce
    nel gruppo e nell'argomento dove e' stato scritto il comando
    (`_RISPOSTA_NEL_GRUPPO`). `/start`, `/sfoglia` e la fusione restano
    cose da chat privata."""
    if not testo.startswith("/") or not e_admin_bot(mittente):
        return
    comando = testo.split()[0].split("@")[0].lower()
    if comando == "/dove":
        return await comando_dove(msg, mittente)
    chat = (msg.get("chat") or {}).get("id")
    if not gruppo_admin_id() or chat != gruppo_admin_id():
        return
    fa = {"/anteprima": comando_anteprima, "/canale": comando_canale,
          "/sponsor": comando_sponsor, "/vetrina": comando_vetrina,
          "/punti": comando_punti, "/canali": comando_canali}.get(comando)
    if not fa:
        return
    stanza = (int(msg.get("message_thread_id") or 0)
              if msg.get("is_topic_message") else 0)
    gettone = _RISPOSTA_NEL_GRUPPO.set(
        {"da": mittente["id"], "chat": chat, "stanza": stanza})
    try:
        return await fa(mittente, testo)
    finally:
        _RISPOSTA_NEL_GRUPPO.reset(gettone)


