@app.post("/api/admin/leve-storia/{sid}/annulla")
async def leve_storia_annulla(sid: int, x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: rimette una leva com'era PRIMA di quel cambio. Se prima
    veniva dal config, «annullare» e' tornare al config."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    _frena("leva_pannello", user["id"])
    con = db()
    try:
        _leve_storia_tabella(con)
        r = con.execute("SELECT * FROM leve_pannello_storia WHERE id=?",
                        (sid,)).fetchone()
    finally:
        con.close()
    if not r:
        raise HTTPException(404, "Swap non trovato")
    try:
        if r["prima_dal_pannello"]:
            return _leva_scrivi(r["chiave"], _leva_leggibile(_leva_da_json(r["prima"])),
                                chi=user["id"], come="annulla")
        return _leva_scrivi(r["chiave"], al_config=True, chi=user["id"],
                            come="annulla")
    except KeyError:
        raise HTTPException(404, "Questa leva si cambia solo dal VPS")
    except ValueError as e:
        raise HTTPException(400, str(e))


# ============ IL BACKUP DELLE LEVE (27 ott 2026, stesso cantiere) ============
# Il backup e' la tabella `leve_pannello` com'e' adesso: la fotografia di
# tutto quel che il pannello ha deciso sopra il config. Esce in due modi
# — come testo da copiare, e come file mandato dal bot nella chat di chi
# lo chiede, che e' il posto dove dal telefono un file resta —, e
# rientra col ripristino: prima un'anteprima di ogni cambio, poi la
# conferma. Rimettere un backup vuol dire rendere il pannello UGUALE a
# lui: le leve che il pannello ha cambiato dopo e che il backup non
# conosce tornano al config. La tabella sta anche dentro il backup
# cifrato del database, di ogni notte e di prima di ogni deploy.
def _leve_backup() -> dict:
    con = db()
    try:
        _leve_pannello_tabella(con)
        righe = con.execute("SELECT chiave, valore FROM leve_pannello "
                            "ORDER BY chiave").fetchall()
    finally:
        con.close()
    leve = {}
    for r in righe:
        if r["chiave"] in LEVE_SCRIVIBILI:
            leve[r["chiave"]] = _leva_leggibile(leva_scrivibile(r["chiave"]))
        else:
            try:
                leve[r["chiave"]] = _leva_leggibile(_leva_da_json(r["valore"]))
            except ValueError:
                continue
    return {"barattolo_leve": 1, "sito": URL_PUBBLICO,
            "creato": int(time.time()), "leve": leve}


@app.get("/api/admin/leve-backup")
def leve_backup_admin(x_tg_init_data: str = Header(""),
                      barattolo_sessione: str = Cookie("")):
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    return _leve_backup()


@app.post("/api/admin/leve-backup/telegram")
async def leve_backup_telegram(x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: il backup come file, dal bot, nella chat di chi lo chiede."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    _frena("leva_pannello", user["id"])
    b = _leve_backup()
    # in collaudo il bot non e' il bot vero: niente Telegram (il patto
    # degli altri indirizzi, vedi prove «in collaudo si ferma prima»)
    if MODALITA_COLLAUDO:
        return {"ok": False, "collaudo": True, "leve": len(b["leve"])}
    nome = time.strftime("leve-barattolo-%Y-%m-%d-%H%M.json", time.localtime(b["creato"]))
    try:
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.post(f"https://api.telegram.org/bot{BOT_TOKEN}/sendDocument",
                             data={"chat_id": str(user["id"]),
                                   "caption": f"⚙️ Backup delle leve: {len(b['leve'])} "
                                              "decise dal pannello. Per rimetterlo: "
                                              "pagina delle leve → 💾 Backup → Ripristina."},
                             files={"document": (nome, json.dumps(
                                 b, ensure_ascii=False, indent=1).encode("utf-8"),
                                 "application/json")})
        ok = r.status_code == 200 and r.json().get("ok")
    except Exception:
        ok = False
    if not ok:
        raise HTTPException(502, "Telegram non ha preso il file: usa «Copia il testo»")
    return {"ok": True, "leve": len(b["leve"])}


@app.post("/api/admin/leve-ripristina")
async def leve_ripristina_admin(req: Request, x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: {backup, applica}. Senza `applica` dice e basta cosa
    cambierebbe; con `applica` lo fa. Una leva del backup che oggi non
    si apre, o che il giudice non accetta, si salta e si dice."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    d = await leggi_json(req)
    b = d.get("backup")
    if not isinstance(b, dict) or b.get("barattolo_leve") != 1 \
            or not isinstance(b.get("leve"), dict):
        raise HTTPException(400, "Non è un backup delle leve di Barattolo")
    adesso = _leve_backup()["leve"]
    cambi, saltate = [], []
    for k, v in b["leve"].items():
        if k in LEVE_SCRIVIBILI:
            motivo = LEVE_SCRIVIBILI[k]["giudice"](v)[1]
        elif (_leva_apribile_di_nome(k) and k in globals()
              and k in _leve_lette_dal_codice()["dal_config"]
              and _tipo_leva(globals()[k])):
            motivo = _giudice_generico(k, globals()[k], v)[1]
        else:
            motivo = "si cambia solo dal VPS"
        if motivo:
            saltate.append({"chiave": k, "motivo": motivo})
        elif adesso.get(k, None) != v or k not in adesso:
            cambi.append({"chiave": k, "adesso": _leva_leggibile(_leva_valore_vivo(k)),
                          "dopo": v, "al_config": False})
    for k in adesso:
        if k not in b["leve"]:
            cambi.append({"chiave": k, "adesso": adesso[k], "dopo": None,
                          "al_config": True})
    if d.get("applica"):
        _frena("leva_pannello", user["id"])
        for c in cambi:
            try:
                _leva_scrivi(c["chiave"], c["dopo"], al_config=c["al_config"],
                             chi=user["id"], come="ripristino")
            except (KeyError, ValueError) as e:
                saltate.append({"chiave": c["chiave"], "motivo": str(e)})
    return {"cambi": cambi, "saltate": saltate, "applicato": bool(d.get("applica"))}


@app.post("/api/admin/utenti/{tg_id}/messaggio")
async def messaggio_utente_admin(tg_id: int, req: Request,
                                 x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: un messaggio a UN utente, dal bot. Nato da un caso
    vero (ago 2026): una venditrice senza username Telegram ne' npub
    scrive «contattami per i colori» — e nessuno puo' scriverle,
    moderatori compresi. Passa da notifica(), che rispetta la
    preferenza di canale e copre anche i nativi Nostr col DM cifrato.
    E' A SENSO UNICO per costruzione — il bot non ci inoltra le
    risposte — e lo dicono sia l'interfaccia del moderatore sia la
    coda del messaggio, con la strada giusta per risponderci (il
    canale del rodaggio, quello che c'e' gia': nessun secondo
    contatto da tenere aggiornato). Ogni invio resta nel registro
    moderazione con chi l'ha mandato."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    d = await leggi_json(req)
    testo = str(d.get("testo") or "").strip()
    if not testo:
        raise HTTPException(400, "Il messaggio è vuoto")
    if len(testo) > 1500:
        raise HTTPException(400, "Massimo 1500 caratteri")
    con = db()
    u = con.execute("SELECT nome FROM utenti WHERE tg_id=?",
                    (tg_id,)).fetchone()
    con.close()
    if not u:
        raise HTTPException(404, "Utente non trovato")
    # Le notifiche parlano HTML: il testo del moderatore si scappa, o
    # un «<» spegnerebbe il messaggio in silenzio (la lezione dei
    # promemoria). La coda dice al destinatario COME risponderci:
    # scrivere al bot non serve, quella strada non torna indietro.
    coda = ("\n\n<i>Questo messaggio è a senso unico: se rispondi al "
            "bot, la risposta non ci arriva.")
    if (BANNER_TEST_LINK or "").startswith("http"):
        coda += f" Per scriverci: {BANNER_TEST_LINK}"
    coda += "</i>"
    await notifica(tg_id,
                   "🛡 <b>Messaggio dai moderatori di Barattolo</b>\n\n"
                   + html.escape(testo) + coda)
    registra_moderazione("admin", "messaggio", testo, "", 0, tg_id,
                         user["id"])
    return {"ok": True}


# ------------------------- API: LA RICERCA --------------------------
# LA RICERCA E' UNA SOLA (ago 2026, decisione di Andrea: «l'AI nella
# ricerca eliminala proprio»). Fino a ieri erano DUE, e rispondevano
# diverso alla stessa domanda: per gli anonimi un LIKE sulla FRASE
# INTERA in titolo/descrizione/zona — quindi «bici da corsa» non
# trovava «bicicletta da corsa», e «collezionismo» non trovava la
# categoria Collezionismo, che il LIKE nemmeno guardava — e per chi
# era dentro Telegram Haiku, cioe' l'unica rotta del progetto dove UNA
# richiesta di un utente qualunque era UNA chiamata al modello, con un
# prompt di dimensione massima FISSA: la shortlist si riempiva fino a
# 300 annunci anche quando la domanda non trovava niente, quindi ogni
# ricerca costava uguale, tanto.
# Adesso e' un indice full-text di casa: deterministico, senza rete,
# senza credito, uguale per tutti — e PROVABILE IN CI, che di un'AI
# non si puo' dire. Il ripiego dell'AI (il match sulla frase intera)
# era per giunta la strada che si vedeva proprio quando le cose
# andavano male, cioe' la peggiore da lasciare zoppa.
# DOVE VIVE: dentro `/api/listings`, cioe' nella VETRINA — ed e' quel
# che la rende componibile con categoria, prezzo, regione e filtri, e
# paginata come tutto il resto, senza una riga in piu'. `/api/search`
# resta come guscio per i client vecchi rimasti in cache.

# La ricetta dell'indice. Alzarla di uno fa reindicizzare TUTTO al
# primo avvio: e' la leva da girare quando cambia lo stemmer, o i
# campi, o i sinonimi che ci entrano dentro.
VERSIONE_RICERCA = 1

# Il tetto dei risultati di una ricerca. Oltre non si pagina: chi
# scorre mille risultati non li guarda, e a stringere c'e' il resto
# del pannello Filtri.
TETTO_RICERCA = 500

# LO STEMMER E' SNOWBALL, e non una tabella di desinenze fatta in casa
# (decisione di Andrea: «ci vuole un sistema gia' collaudato, non per
# forza le prime 5 lettere»). `snowballstemmer` e' Python puro, ~100
# KB, zero dipendenze, ed e' l'algoritmo che sta sotto Lucene,
# Elasticsearch e PostgreSQL: le regole dell'italiano le ha scritte
# qualcun altro vent'anni fa e sono state pestate da mezzo mondo.
# Import FAIL-OPEN come Pillow e coincurve — ma DICHIARATO all'avvio,
# il patto della chiave dei contenuti digitali: un fail-open che non
# si vede nemmeno da chi guarda il server non e' dichiarato, e'
# soltanto silenzio.
try:
    import snowballstemmer
    _STEMMER = snowballstemmer.stemmer("italian")
except Exception:
    _STEMMER = None
    print("⚠️  snowballstemmer non c'è: la ricerca lavora a troncamento "
          "invece che a radici (più grossolana, mai muta). "
          "pip install snowballstemmer")


def radice(parola: str) -> str:
    """La radice di una parola italiana: 'collezione', 'collezionismo'
    e 'collezionista' diventano tutte 'collezion'; 'biciclette' e
    'bicicletta' diventano 'biciclett'. E' questo a far trovare l'una
    cercando l'altra.

    VALE A INDICE E A DOMANDA INSIEME, ed e' la riga da non
    ammorbidire: se le due parti stemmassero in modo diverso non si
    incontrerebbero mai, e la ricerca tornerebbe vuota senza un errore
    e senza una riga di journal.

    Le parole di due lettere si lasciano stare: sotto non c'e'
    desinenza da togliere, e accorciarle impasterebbe cose diverse.

    SENZA lo stemmer si ripiega sul TRONCAMENTO, che sulla famiglia
    che conta ottiene lo stesso ('collezione' e 'collezionismo'
    finiscono tutt'e due su 'collez'): piu' grossolano — impasta anche
    parole che non c'entrano — ma mai muto.
    """
    p = (parola or "").strip()
    if len(p) < 3:
        return p
    if _STEMMER is None:
        return p[:6]
    return _STEMMER.stemWord(p) or p


def termini(parola: str) -> tuple[str, ...]:
    """I termini con cui una parola entra nell'indice — e con cui la
    si cerca. Sono DUE: la radice, e il TRONCAMENTO a cinque lettere.

    IL TRONCAMENTO NON E' UN RIPIEGO, e' la toppa a un difetto vero
    dello stemmer, MISURATO e non temuto: su 28 coppie
    singolare/plurale di un mercatino ne sbaglia 4 — «tastiera →
    tastier» ma «tastiere → tast», e cosi' telefono/telefoni,
    cassettiera, caffettiera (Snowball tratta '-iera' come una
    desinenza da togliere, e sul plurale arriva prima un'altra
    regola). Chi cerca «tastiere» non troverebbe «tastiera»: il 14%
    delle coppie, e dentro ci sono le parole che la gente scrive
    davvero.
    Su tutti e quattro i casi le due radici divergenti hanno le prime
    CINQUE lettere in comune, ed e' da li' che esce la cura: si
    indicizzano tutt'e due le forme e si cercano in «o». Cinque e non
    quattro perche' quattro impasta cose diverse ('coll' prende
    collana, collo, collega); cinque discrimina quanto una parola
    corta.
    Il prezzo dichiarato e' un indice piu' grosso — al piu' il doppio
    dei termini — e qualche accostamento in piu' nel giro largo, che
    BM25 ricaccia in fondo perche' pesa quante volte una parola
    combacia davvero."""
    p = (parola or "").strip()
    if len(p) < 3:
        return (p,) if p else ()
    r = radice(p)
    corto = p[:5]
    return (r,) if r == corto else (r, corto)


def radici(testo: str) -> list[str]:
    """Il testo ridotto ai termini dell'indice. Passa da `normalizza`,
    che e' il setaccio di casa (minuscole, accenti sciolti,
    punteggiatura in spazi) — lo STESSO del filtro parole, degli
    avvisi di ricerca e del motore geografico: un secondo setaccio
    direbbe 'citta' di qua e 'città' di la', e i due lati non si
    incontrerebbero mai."""
    return [t for p in normalizza(testo).split() if len(p) >= 2
            for t in termini(p)]


# I SINONIMI ENTRANO NELL'INDICE, NON NELLA DOMANDA (ago 2026), ed e'
# la scelta che tiene veloce la ricerca: espandere la DOMANDA vuol
# dire una query che si allunga con quante parole conosciamo — e la
# domanda si fa a ogni tasto —, espandere l'INDICE costa una volta
# sola, quando l'annuncio si scrive. Cosi' «pc» trova gli annunci di
# Informatica e «hifi» quelli di Audio e video, e i due cataloghi di
# sinonimi che il progetto ha gia' — quello delle categorie e quello
# delle sottocategorie — si mettono a servire anche la ricerca senza
# una riga di dizionario nuova da tenere in pari.
_SINONIMI_DI_CATEGORIA: dict[str, list[str]] = {}
for _parola_sin, _cat_sin in SINONIMI_CATEGORIA.items():
    _SINONIMI_DI_CATEGORIA.setdefault(_cat_sin, []).append(_parola_sin)


def _campi_indice(r) -> tuple[str, str, str, str]:
    """I quattro campi che finiscono in `annunci_fts`, gia' in radici.

    Il quarto NON e' solo la categoria: ci stanno anche l'etichetta
    della sottocategoria e i sinonimi di tutt'e due. E' un campo suo e
    non un pezzo del titolo perche' BM25 lo possa pesare per conto
    proprio — deve valere piu' di una parola persa in descrizione e
    meno del titolo, che e' quello che il venditore ha scelto."""
    cat = r["categoria"] or ""
    chiavi = r.keys() if hasattr(r, "keys") else r
    sotto = (r["sottocategoria"] or "") if "sottocategoria" in chiavi else ""
    voci = [cat] + _SINONIMI_DI_CATEGORIA.get(cat, [])
    if sotto:
        voci += [e for i, e in SOTTOCATEGORIE.get(cat, ()) if i == sotto]
        voci += list(SINONIMI_SOTTOCATEGORIA.get(cat, {}).get(sotto, ()))
    return (" ".join(radici(r["titolo"])),
            " ".join(radici(r["descrizione"])),
            " ".join(radici(r["zona"])),
            " ".join(radici(" ".join(voci))))


def _indicizza(con, r) -> None:
    """Riscrive la riga nell'indice. Prima si toglie e poi si rimette:
    in FTS5 non esiste un UPDATE per rowid, e due copie della stessa
    riga farebbero contare due volte ogni parola nel punteggio."""
    con.execute("DELETE FROM annunci_fts WHERE rowid=?", (r["id"],))
    con.execute("INSERT INTO annunci_fts"
                "(rowid, titolo, descrizione, zona, categoria) "
                "VALUES(?,?,?,?,?)", (r["id"],) + _campi_indice(r))
    con.execute("UPDATE annunci SET ricerca_v=? WHERE id=?",
                (VERSIONE_RICERCA, r["id"]))


def riallinea_ricerca(con, tetto: int = 0) -> int:
    """Rifa' l'indice delle righe che il trigger ha invalidato (o che
    non ci sono mai entrate). Idempotente, e si puo' interrompere a
    meta': quel che resta lo prende il giro dopo.

    E' un SISTEMA AUTO-RIPARANTE e non una catena di ganci da
    ricordare — il pattern di `riallinea_quantita_max` e della passata
    dei distintivi: chi scrive un annuncio non deve sapere che esiste
    una ricerca, e il giorno che nasce l'ottavo posto che riscrive un
    titolo l'indice lo segue da solo.

    `tetto` limita quanto si lavora in un colpo: sulla strada calda
    della ricerca si ripara un po' per volta invece di far aspettare
    chi cerca dietro a un import da 500 righe. Torna quante righe ha
    rifatto."""
    sql = ("SELECT id, titolo, descrizione, zona, categoria, sottocategoria "
           "FROM annunci WHERE ricerca_v<>?")
    if tetto:
        sql += f" LIMIT {int(tetto)}"
    # FAIL-OPEN COME `cerca_ids`, e questo `try` e' arrivato da una
    # prova e non da una rilettura: su un SQLite senza FTS5 il server
    # partiva (l'indice non si crea, e lo si dice) ma la prima ricerca
    # dava 500 — perche' la riparazione SCRIVE nell'indice, e a
    # guardarsi le spalle era solo chi legge. Qui non c'e' niente da
    # salvare: se l'indice non c'e' non si ripara, e la ricerca
    # ripiega sul LIKE di ieri.
    try:
        righe = con.execute(sql, (VERSIONE_RICERCA,)).fetchall()
        for r in righe:
            _indicizza(con, r)
        if righe:
            con.commit()
        return len(righe)
    except sqlite3.Error as e:
        print(f"⚠️  Indice di ricerca non riparato ({e})", flush=True)
        return 0


def _domanda_fts(q: str, prefisso: bool = True) -> tuple[str, str]:
    """La domanda dell'utente tradotta in due query FTS5: la STRETTA
    (tutte le parole) e la LARGA (almeno una).

    SI PROVA PRIMA LA STRETTA E POI LA LARGA, ed e' il compromesso che
    regge a tutti i volumi: «tastiera meccanica» deve dare le tastiere
    meccaniche e non tutte le tastiere del mercatino, ma su un
    catalogo piccolo l'intersezione e' spesso vuota — e una vetrina
    vuota, quando qualcosa da mostrare c'era, e' peggio di una vetrina
    imprecisa.

    OGNI PAROLA E' UN GRUPPO, non un termine: dentro ci stanno la sua
    radice e il suo troncamento in «o» (vedi `termini`), e sono i
    GRUPPI a legarsi in «e». Cosi' «tastiera meccanica» vuole tutt'e
    due le parole, ma ognuna nella forma che combacia.

    L'ULTIMA PAROLA E' UN PREFISSO perche' chi digita ce l'ha quasi
    sempre a meta': cercando «collezio» si vede gia' qualcosa. I
    termini escono da `normalizza`, quindi sono solo lettere e cifre e
    non possono contenere la virgoletta che chiuderebbe la stringa —
    si virgoletta lo stesso, che una guardia che oggi non serve e' la
    guardia che regge domani."""
    parole = [p for p in normalizza(q).split() if len(p) >= 2]
    if not parole:
        return ("", "")
    gruppi = []
    for i, p in enumerate(parole):
        coda = "*" if prefisso and i == len(parole) - 1 else ""
        voci = [f'"{t}"{coda}' for t in termini(p)]
        gruppi.append(voci[0] if len(voci) == 1
                      else "(" + " OR ".join(voci) + ")")
    return (" AND ".join(gruppi), " OR ".join(gruppi))


def cerca_ids(con, q: str, tetto: int = TETTO_RICERCA,
              prefisso: bool = True) -> list[int] | None:
    """Gli id degli annunci che rispondono alla domanda, DAL PIU'
    PERTINENTE. Torna `None` — e non una lista vuota — quando l'indice
    non c'e': sono due cose diverse, e chi chiama deve poter ripiegare
    sul LIKE di ieri invece di dire «nessun risultato», che sarebbe
    una bugia.

    I PESI di BM25 sono l'ordine delle cose: il titolo e' quello che
    il venditore ha scelto per farsi trovare, la categoria e' un fatto
    dichiarato, la descrizione e' prosa e la zona e' un luogo — una
    parola nel titolo vale cinque volte la stessa parola in
    descrizione. Il punteggio di BM25 e' NEGATIVO e piu' basso vuol
    dire meglio: l'ORDER BY crescente non e' un refuso.

    Lo STATO non si guarda qui: l'indice tiene tutti gli annunci e a
    dire quali si mostrano restano le WHERE della vetrina, che quelle
    regole le sanno gia' tutte (venduti, ferie, revisione...)."""
    stretta, larga = _domanda_fts(q, prefisso)
    if not stretta:
        return []
    try:
        for domanda in (stretta, larga):
            righe = con.execute(
                "SELECT rowid FROM annunci_fts WHERE annunci_fts MATCH ? "
                "ORDER BY bm25(annunci_fts, 10.0, 2.0, 1.0, 4.0) LIMIT ?",
                (domanda, tetto)).fetchall()
            if righe:
                return [r[0] for r in righe]
        return []
    except sqlite3.Error as e:
        # FTS5 assente (un SQLite molto vecchio) o indice rotto: la
        # ricerca non deve sparire, torna quella di ieri.
        print(f"⚠️  Indice di ricerca non disponibile ({e}): uso il LIKE")
        return None


@app.on_event("startup")
async def scalda_ricerca():
    """La passata d'avvio: indicizza tutto quel che manca — al primo
    deploy sono TUTTI gli annunci (la colonna nasce a zero), poi solo
    quel che e' cambiato mentre il server era spento, che di solito e'
    niente.

    NON e' in `init_db`, ed e' una ragione di ordine e non di gusto:
    quella gira all'import del modulo, quando lo stemmer e i giudici
    di qui non sono ancora stati definiti. Qui invece si e' dopo, e
    prima che uvicorn accetti la prima richiesta — la stessa finestra
    di `scalda_cambio`.

    Fail-open: se qualcosa va storto la ricerca ripara comunque un po'
    per volta a ogni domanda, e il server parte."""
    try:
        con = db()
        quante = riallinea_ricerca(con)
        con.close()
        if quante:
            print(f"🔎 Indice di ricerca: {quante} annunci indicizzati "
                  f"(stemmer {'sì' if _STEMMER else 'NO, a troncamento'})",
                  flush=True)
    except Exception as e:
        print(f"⚠️  Indice di ricerca non scaldato: {e}", flush=True)


# IL FRENO DEI CODICI SCONTO (ago 2026), gemello del precedente. Serve
# contro chi prova a indovinare i codici altrui — e siccome un codice
# vale su un negozio solo, indovinarne uno vuol dire regalarsi lo
# sconto che il venditore aveva dato a qualcun altro.
# SI CONSUMA SOLO SUI TENTATIVI FALLITI, ed e' la riga che decide: il
# preventivo si rilancia a ogni ± dello stepper e il client rimanda il
# codice ogni volta, quindi un gettone per chiamata brucerebbe la
# quota di chi ha un codice VALIDO solo cambiando quantita'. Chi non
# digita mai un codice non tocca il freno.
CODICE_QUOTA: dict[int, list] = {}      # tg_id -> [ora, tentativi falliti]


def _codice_quota_libera(tg_id: int) -> bool:
    """C'e' ancora un gettone per provare un codice? GUARDA E BASTA.

    Sta separata dal consumo perche' il gettone si spende solo sui
    tentativi FALLITI: consumare-e-restituire direbbe la stessa cosa
    peggio, con una finestra in cui il conto e' falso e un ramo di
    restituzione da non dimenticare.
    A quota finita si risponde con lo STESSO messaggio di sempre e MAI
    con un 429 — un 429 confermerebbe l'esistenza del freno e ne
    farebbe tarare il ritmo — e soprattutto NON SI INTERROGA IL
    DATABASE: il freno e' anche un freno di costo."""
    if not CODICI_SCONTO_TENTATIVI_ORA:     # 0 = nessun freno
        return True
    voce = CODICE_QUOTA.get(tg_id)
    return (not voce or voce[0] != time.strftime("%Y-%m-%d %H")
            or voce[1] < CODICI_SCONTO_TENTATIVI_ORA)


def _codice_tentativo_speso(tg_id: int) -> None:
    """Un gettone in meno: si chiama SOLO quando il codice non valeva.

    Chi non digita mai un codice non tocca il freno, e chi ne ha uno
    buono nemmeno — il preventivo si rilancia a ogni ± dello stepper e
    il client rimanda il codice ogni volta, quindi un gettone per
    chiamata brucerebbe la quota di chi non ha sbagliato niente."""
    if not CODICI_SCONTO_TENTATIVI_ORA:
        return
    ora = time.strftime("%Y-%m-%d %H")
    voce = CODICE_QUOTA.get(tg_id)
    if not voce or voce[0] != ora:
        voce = [ora, 0]
        CODICE_QUOTA[tg_id] = voce
    voce[1] += 1


@app.get("/api/search")
def cerca(q: str, busta: int = 0, x_tg_init_data: str = Header(""),
          barattolo_sessione: str = Cookie("")):
    """Il GUSCIO della ricerca di ieri, per i client rimasti in cache.

    Da quando la ricerca vive in `/api/listings` questa rotta non ha
    piu' un motore suo: chiama lo stesso giudice e risponde nella
    forma di sempre. `busta=1` continua a rispondere `{annunci, ai}`
    con `ai` a FALSO — che adesso e' semplicemente vero per tutti, e
    il client vecchio lo dice con la sua riga «ricerca veloce per
    parole», che e' onesta.
    Resta AUTENTICATA com'era: non e' piu' credito da difendere, ma
    aprire una superficie che non serve piu' a nessuno sarebbe solo
    superficie (la lezione di `/api/comuni`)."""
    verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    riallinea_ricerca(con, 300)
    ids = cerca_ids(con, q)
    if ids is None:                     # indice assente: il LIKE di ieri
        parole = [p for p in re.findall(r"\w+", q.lower()) if len(p) >= 3][:6]
        cond = " OR ".join("(a.titolo LIKE ? OR a.descrizione LIKE ? "
                           "OR a.categoria LIKE ? OR a.zona LIKE ?)"
                           for _ in parole) or "0"
        righe = con.execute(
            f"SELECT a.id FROM annunci a WHERE a.stato='attivo' AND ({cond}) "
            "ORDER BY a.creato DESC LIMIT ?",
            [f"%{p}%" for p in parole for _ in range(4)] + [TETTO_RICERCA])
        ids = [r[0] for r in righe]
    annunci = _righe_per_id(con, CAMPI_VETRINA, ids, "a.stato='attivo'")
    con.close()
    return {"annunci": annunci, "ai": False} if busta else annunci


def _righe_per_id(con, campi: str, ids: list[int],
                  dove: str = "1=1") -> list[dict]:
    """Le righe di vetrina degli id dati, NELL'ORDINE IN CUI ARRIVANO.

    Quell'ordine e' il punteggio della ricerca, e SQL non lo conosce:
    si rimette in fila in Python, o `IN (...)` servirebbe le righe
    nell'ordine che gli pare — cioe' la pertinenza si perderebbe
    proprio nell'ultimo passo, che e' il modo piu' silenzioso in cui
    una ricerca puo' smettere di funzionare (i risultati ci sono
    tutti, solo nell'ordine sbagliato)."""
    if not ids:
        return []
    segni = ",".join("?" * len(ids))
    righe = {r["id"]: dict(r) for r in con.execute(
        f"SELECT {campi} FROM annunci a "
        "JOIN utenti u ON u.tg_id = a.venditore_id "
        f"WHERE {dove} AND a.id IN ({segni})", ids)}
    return arricchisci_righe_vetrina([righe[i] for i in ids if i in righe])


# ------------------------- API: OFFERTE -----------------------------
# La contrattazione sul prezzo (lug 2026, modello Vinted): proposta ->
# risposta -> acquisto alla cifra pattuita. NON e' una chat: e' una
# macchina a stati con al massimo UNA controproposta del venditore.
# L'annuncio non si blocca mai durante la trattativa: vince chi paga
# per primo, e le offerte rimaste vive decadono con garbo. L'accordo
# riguarda il SOLO articolo: spedizione e protezione si sommano sopra
# al momento dell'acquisto, come per ogni altro ordine.

STATI_OFFERTA_VIVI = ("proposta", "controproposta", "accettata")


def _importo_accordo(off) -> tuple[int, float]:
    """La cifra pattuita: la controproposta se c'e' (solo il compratore
    puo' accettarla, quindi se c'e' l'accordo e' quello), altrimenti la
    proposta. In (sats, eur): uno dei due e' sempre 0, come in colonna."""
    if off["contro_sats"] > 0 or off["contro_eur"] > 0:
        return off["contro_sats"], off["contro_eur"]
    return off["importo_sats"], off["importo_eur"]


def _cifra_da_payload(valuta: str, grezzo) -> tuple[int, float, float]:
    """La cifra che arriva dal client, nella valuta del LISTINO.

    Torna `(sats, eur, numero)`: due colonne — una delle quali resta
    sempre 0, come in tabella — e il valore su cui si confronta. Gli
    euro accettano la virgola, che e' come si scrive un prezzo qui.
    Una cifra illeggibile vale ZERO e cade da sola sul pavimento del
    chiamante: non c'e' un ramo d'errore da ricordarsi.

    Estratta dalla controproposta quando e' nato il rilancio: leggono
    lo stesso genere di numero, e tenerne due copie sarebbe il posto
    da cui un domani divergono."""
    grezzo = str(grezzo if grezzo is not None else "").strip()
    if valuta == "eur":
        try:
            eur = round(float(grezzo.replace(",", ".")), 2)
        except ValueError:
            eur = 0.0
        return 0, eur, eur
    try:
        sats = int(float(grezzo))
    except ValueError:
        sats = 0
    return sats, 0.0, sats


def _spazio_rilancio(valuta: str, imp_sats: int, imp_eur: float,
                     contro_sats: int, contro_eur: float) -> bool:
    """C'e' posto per una cifra IN MEZZO fra l'offerta e la richiesta?

    E' la domanda della FORBICE: `importo_*` e' il pavimento (quel che
    offre chi compra), `contro_*` il soffitto (quel che chiede chi
    vende), e ogni mossa stringe da un lato solo. Quando i due si
    toccano non c'e' piu' niente da proporre: si accetta o si rifiuta,
    e il bottone del rilancio non deve nemmeno comparire.

    IN CENTESIMI E MAI IN FLOAT: 0.01 non e' rappresentabile, e un
    `contro_eur - imp_eur > 0.01` direbbe di si' dove spazio non ce
    n'e' — aprendo un campo che poi rifiuta ogni numero, che e' peggio
    di un campo che non c'e'."""
    if valuta == "eur":
        return round(contro_eur * 100) - round(imp_eur * 100) > 1
    return contro_sats - imp_sats > 1


def _cifra_offerta(valuta: str, sats: int, eur: float) -> str:
    """«80.000 sats» oppure «15,50 €»: la valuta del listino.
    Le due cifre passano dai formattatori di casa (_fmt_sats,
    _fmt_eur), che vivono piu' in basso ma si risolvono alla chiamata:
    in tutta l'app un euro si scrive in un modo solo."""
    return (f"{_fmt_eur(eur)} €" if valuta == "eur"
            else f"{_fmt_sats(sats)} sats")


def _cifra_accordo(valuta: str, sats: int, eur: float, quantita: int) -> str:
    """La cifra di un'offerta detta senza equivoci, e il punto dove si
    toglie l'unico malinteso che qui costa soldi veri.

    Con UN pezzo solo — o con la quantita' non dichiarata (0: le offerte
    nate prima del cantiere) — e' la cifra e basta: non c'e' ambiguita',
    e aggiungere sarebbe rumore. Con PIU' pezzi dice ENTRAMBE le facce:
    l'unitario, che e' quello che si confronta col listino, e il totale,
    che e' quello che si incassa. Mai una sola delle due.

    IL TOTALE VIENE PRIMA (decisione di Andrea): «120.000 sats per 3
    pezzi (40.000 sats al pezzo)». La forma di prima — «40.000 al pezzo
    × 3 = 120.000» — si leggeva come un CALCOLO, e chi legge vuole
    sapere per prima cosa quanto paga (o quanto incassa) in tutto.
    L'unitario resta, in coda e fra parentesi, perche' e' la cifra che
    si confronta col listino.

    PURA e coi CAMPI, non con la riga (il patto di in_ferie): cosi' la
    stessa funzione serve la riga di `offerte`, il payload appena letto
    e la prova in CI. Il totale in euro e' round(eur*q, 2): una
    moltiplicazione esatta, mai una conversione."""
    unitaria = _cifra_offerta(valuta, sats, eur)
    if quantita <= 1:
        return unitaria
    totale = _cifra_offerta(valuta, sats * quantita,
                            round(eur * quantita, 2))
    return (f"{totale} per {_fmt_sats(quantita)} pezzi "
            f"({unitaria} al pezzo)")


# ------------------ IL CONTO D'ACQUISTO: matematica pura -------------
# (ago 2026, pagina d'acquisto). Il giudice UNICO del conto: lo usano
# compra(), _compra_set() e il preventivo della pagina d'acquisto — se
# il preventivo facesse i conti per conto suo, prima o poi direbbe una
# cifra diversa dalla invoice. La SOTTRAZIONE dello sconto carrello sta
# dentro _conto_ordine e in nessun altro posto (chi legge il conto usa
# `netto`); la DECISIONE — scatta o no — sta in _sconto_pacco, che il
# ramo mono non chiama mai, e dal cantiere del CRITERIO sta li' anche
# per il gemello in euro, che non decide piu' da solo: a valore la
# porta si apre guardando i SATS, che l'euro non ha.
# Funzioni PURE come quelle dell'asta:
# niente config, niente database, niente rete — le percentuali arrivano
# per parametro e il cambio dal chiamante, che decide anche cosa fare
# quando manca (503 in compra, strada spenta con motivo nel
# preventivo). Sono il «modulo» che prove.py estrae con pezzo() e
# tortura in CI: chi le rifattorizza le tenga autosufficienti.

def _unitario_effettivo(a, off, adesso: int, cambio: float) -> int:
    """L'unitario in sats di UN annuncio: listino, accordo accettato
    (_importo_accordo) e lampo viva col MIN — chi paga paga sempre il
    meglio dei due, mai una lampo che peggiora l'accordo. Sul listino
    EUR converte al cambio dato (che il chiamante garantisce >0 quando
    serve), max(1, round(...)): si arrotonda l'UNITARIO prima di
    moltiplicare, cosi' la divisione a ritroso di chi legge l'ordine
    e' esatta.
    L'ACCORDO PARLA LA SUA VALUTA, NON QUELLA DEL LISTINO DI OGGI (14
    nov 2026, cantiere audit-offerte, dal primo audit di sicurezza).
    Un'offerta accettata sopravvive a un cambio di valuta dell'annuncio
    (decisione scritta), e delle sue due colonne ne vive una sola. Fino
    a ieri la colonna si sceglieva guardando il LISTINO: un accordo in
    sats su un annuncio passato agli euro leggeva la colonna euro, che
    e' zero, e faceva 1 sat al pezzo; all'inverso faceva zero. Ora ogni
    cifra si converte dalla valuta in cui E' NATA (l'accordo dalla sua
    colonna viva, la lampo dal listino) e il MIN si fa in sats. A
    valute uguali il numero e' quello di prima, perche' la conversione
    e' monotona: il minimo dei convertiti e' il convertito del minimo.
    Il cambio >0 il chiamante lo garantisce anche per un accordo in
    euro su un listino in sats (`_accordo_vuole_cambio`)."""
    listino_eur = a["valuta"] == "eur" and a["prezzo_eur"] > 0

    def in_sats(sats, eur, nata_in_eur):
        if nata_in_eur:
            return max(1, round(eur / cambio * 100_000_000))
        return sats

    if off:
        o_sats, o_eur = _importo_accordo(off)
        prezzo = in_sats(o_sats, o_eur, o_eur > 0)
    else:
        prezzo = in_sats(a["prezzo_sats"], a["prezzo_eur"], listino_eur)
    if a["lampo_percento"] > 0 and a["lampo_scadenza"] > adesso:
        l_sats, l_eur = _prezzo_lampo(a, a["lampo_percento"])
        prezzo = min(prezzo, in_sats(l_sats, l_eur, listino_eur))
    return prezzo


def _accordo_vuole_cambio(*accordi) -> bool:
    """Uno di questi accordi e' nato in EURO: per farne sats serve il
    cambio, anche se l'annuncio oggi e' in sats e di suo non lo
    chiederebbe (14 nov 2026, cantiere audit-offerte). PURA: guarda la
    colonna viva dell'accordo, come `_unitario_effettivo`."""
    return any(_importo_accordo(o)[1] > 0 for o in accordi if o)


async def _cambio_dell_accordo(cambio: float, *accordi) -> float:
    """Il cambio con cui `_unitario_effettivo` converte: quello che il
    chiamante ha gia' (il listino in euro l'ha chiesto, ed e' lo stesso
    numero: la funzione ha una cache), oppure, se manca e un accordo e'
    nato in euro, quello di adesso. In una variabile SUA e mai in
    quella del chiamante: il metro della conversione del listino resta
    zero finche' il listino non si converte davvero. 0.0 con un accordo
    in euro = il cambio non risponde, e il chiamante da' il suo 503."""
    if cambio > 0 or not _accordo_vuole_cambio(*accordi):
        return cambio
    return await cambio_btc_eur()


def _eur_effettivo(a, off, adesso: int) -> float:
    """L'euro NATIVO effettivo dell'articolo (ago 2026, il giudice del
    «≈»): per un listino EUR e' la cifra su cui il ≈ NON va — la
    valuta in cui il prezzo e' nato — col MIN lampo/accordo calcolato
    sull'euro, specchio di _unitario_effettivo. Listino sats = 0.0
    (li' il nativo sono i sats, e l'euro e' sempre una conversione)."""
    if a["valuta"] != "eur" or a["prezzo_eur"] <= 0:
        return 0.0
    p_eur = a["prezzo_eur"]
    if off:
        o_sats, o_eur = _importo_accordo(off)
        if o_eur <= 0 and o_sats > 0:
            # un accordo nato in SATS su un listino passato agli euro:
            # il suo nativo sono i sats, e un euro esatto da mostrare
            # non c'e' (14 nov 2026, audit-offerte). Prima usciva
            # l'euro del LISTINO accanto ai sats dell'accordo.
            return 0.0
        p_eur = o_eur or p_eur
    if a["lampo_percento"] > 0 and a["lampo_scadenza"] > adesso:
        l_eur = _prezzo_lampo(a, a["lampo_percento"])[1]
        p_eur = min(p_eur, l_eur) if p_eur > 0 else l_eur
    return round(p_eur, 2)


# -------------------- L'INDIRIZZO DI CASA (ago 2026) -----------------
# Il gemello SPECULARE della busta di consegna: li' e' il venditore a
# depositare per il compratore, qui il compratore per il venditore.
# Barattolo non lo CONSERVA, lo TRASPORTA: vive quanto l'ordine, e poi
# pulisci_indirizzi lo cancella. Fino a ieri passava in chat privata,
# e chi non ha uno username Telegram ne' una npub non poteva darlo a
# NESSUNO — lo stesso caso vero che ha fatto nascere la busta.
#
# I CAMPI SONO SEPARATI PER IL TELEFONO, non per il database: il
# riempimento automatico sa compilare solo campi con RUOLI distinti
# (autocomplete="postal-code" e compagnia), mentre un campo unico lo
# lascia indifferente. In colonna finiscono comunque insieme, in un
# JSON cifrato: vedi il commento dello schema.
CAMPI_INDIRIZZO = (
    # campo,    come si chiama nel 400,   tetto, obbligatorio
    ("nome",      "il nome e il cognome",   80,  True),
    ("via",       "la via e il civico",     120, True),
    ("cap",       "il CAP",                 10,  True),
    ("citta",     "la citta",               60,  True),
    ("provincia", "la provincia",           20,  False),
    ("telefono",  "il telefono",            30,  False),
    # il campo che i corrieri chiedono sempre e che nessun modulo
    # prevede mai: citofono, scala, interno, orari
    ("note",      "le note per il corriere", 120, False),
    # IL PAESE (set 2026, col cantiere delle zone): finche' si
    # spediva solo in Italia era sottinteso, e un campo sottinteso non
    # si scrive. Da quando la destinazione puo' essere Lisbona, senza
    # questa riga il venditore ha in mano un indirizzo che non sa
    # indirizzare — cioe' la funzione intera non sta in piedi.
    # FACOLTATIVO NEL CATALOGO e obbligatorio dove SERVE: sull'Italia
    # non si chiede niente a nessuno (lo scrive il server dal codice
    # paese), e il solo caso in cui lo scrive chi compra e' il paese
    # fuori elenco — vedi il gate in fondo a _indirizzo_da_payload.
    # Cosi' gli ordini di ieri, che la chiave non ce l'hanno, restano
    # leggibili: `_indirizzo_letto` usa .get e non trova niente.
    ("paese",     "il paese",               56,  False),
)


def _indirizzo_confermato(d, ind: str) -> int:
    """QUANDO chi compra ha confermato l'indirizzo, o 0.

    Vale solo `True` scritto dal client insieme a un indirizzo che c'e'
    (`ind`, il blob gia' cifrato): una conferma senza indirizzo non
    conferma niente, e una stringa «true» non e' un gesto. NIENTE 400
    quando manca, ed e' la tolleranza di `tipo_punto_da_payload`: la
    regola — la casella obbligatoria prima di «Paga» — vive nel
    CLIENT, e una pagina rimasta aperta da prima il campo non ce l'ha.
    Per quegli ordini il moderatore legge «nessuna conferma», che e'
    la verita'."""
    return int(time.time()) if (ind and d.get("indirizzo_confermato")
                                is True) else 0


def _indirizzo_da_payload(d, paese: str = "") -> tuple:
    """(blob CIFRATO, atteso) dall'indirizzo scritto dal compratore.

    ATTESO E' LA PRESENZA DELLA CHIAVE, mai il suo valore (il patto di
    spedizione_punto_dichiarata): un client di ieri non la manda, e i
    suoi ordini restano nel mondo di ieri senza nessun gate addosso.

    CIFRA QUI, e non nei chiamanti: sono tre (i due compratori e la
    correzione dall'ordine) e basta che uno se ne dimentichi perche' un
    indirizzo di casa finisca in chiaro nel database. Un posto solo,
    e la sentinella lo conta.

    IL PAESE LO SCRIVE IL SERVER, NON IL CLIENT (set 2026): arriva il
    CODICE gia' validato da `_paese_da_payload`, e il nome sulla
    busta esce dal catalogo. E' quel che impedisce di mandare 'FR' e
    farsi scrivere «Italia» accanto — la tariffa e l'indirizzo
    direbbero due paesi diversi, e a spedire sarebbe il venditore.
    L'UNICA ECCEZIONE E' IL PAESE FUORI ELENCO ('ZZ'), dove il nome
    non ce l'ha nessuno: li' lo scrive chi compra ED E' OBBLIGATORIO —
    un ordine per «un altro paese» senza dire quale e' un pacco che
    non parte, e il no si da' PRIMA di prendere i sats.

    I 400 sono STATICI e non rimandano mai il valore: quei messaggi
    finiscono nei log di uvicorn, e un CAP dentro un log e' un CAP
    fuori dalla promessa. Nessun controllo di FORMA sul CAP (la
    lezione di FORME_TRACKING: un'euristica nostra non ferma una
    spedizione vera) — il client chiede, il server non impedisce."""
    if "indirizzo" not in d:
        return "", 0
    grezzo = d.get("indirizzo") or {}
    if not isinstance(grezzo, dict):
        raise HTTPException(400, "Indirizzo non leggibile: riapri l'app "
                                 "e riprova")
    dati = {}
    for campo, _etichetta, tetto, _serve in CAMPI_INDIRIZZO:
        # normalizzato come il punto: spazi collassati, mai troncato in
        # silenzio (la lezione della busta: un dato mozzato e' un dato
        # rotto, e chi l'ha scritto non lo sa)
        valore = " ".join(str(grezzo.get(campo) or "").split())
        if len(valore) > tetto:
            raise HTTPException(400, f"{_etichetta.capitalize()} e' troppo "
                                     f"lungo: al massimo {tetto} caratteri")
        dati[campo] = valore
    if not any(dati.values()):
        # dichiarato ma ancora vuoto: l'ordine nasce «in attesa
        # dell'indirizzo» e il gate di segna_spedito fa il resto.
        # IL PAESE SI SCRIVE DOPO QUESTA RIGA, mai prima: iniettarlo
        # sopra renderebbe `any(dati.values())` vero su un indirizzo
        # vuoto, e lo stato «in attesa» — che e' un pezzo del flusso,
        # non un incidente — sparirebbe in silenzio.
        return "", 1
    if paese and paese != "ZZ":
        dati["paese"] = nome_paese(paese)
    elif paese == "ZZ" and not dati["paese"]:
        raise HTTPException(400, "Scrivi anche il paese di destinazione: "
                                 "senza, chi vende non può scrivere "
                                 "l'indirizzo sul pacco")
    for campo, etichetta, _tetto, serve in CAMPI_INDIRIZZO:
        if serve and not dati[campo]:
            raise HTTPException(400, f"Per la spedizione a un "
                                     f"indirizzo serve anche {etichetta}")
    if not CHIAVE_CONTENUTI_DIGITALI or Fernet is None:
        # IL FAIL-OPEN SI FERMA QUI, ed e' l'unica differenza vera con
        # la busta: un PIN di ritiro in chiaro e' una degradazione
        # accettabile, il nome e la via di una persona no. Senza chiave
        # NON si scrive: si risponde 503 e chi compra ripiega sulla
        # chat, che e' quel che fa gia' oggi. In collaudo si scrive
        # 'plain:' come tutto il resto, o il mercatino di prova non
        # potrebbe piu' vendere niente a casa.
        if not MODALITA_COLLAUDO:
            raise HTTPException(503, "La spedizione a un indirizzo non è "
                                     "disponibile in questo momento: "
                                     "scegli un'altra strada o riprova "
                                     "più tardi")
    return _cifra_contenuto(json.dumps(dati, ensure_ascii=False)), 1


def _indirizzo_letto(blob: str):
    """Il dizionario dell'indirizzo, o None se non si legge.

    IL PARSE E' DIFENSIVO, ed e' il prezzo — pagato in un posto solo —
    della colonna unica: _decifra_contenuto e' fail-open per
    costruzione e su una chiave mancante o cambiata restituisce una
    FRASE, che per la busta si stampa al posto del PIN e qui invece
    non e' JSON. Senza questo try, riaprire un ordine 'locked' dopo un
    cambio di chiave sarebbe un 500 per tutte e due le parti."""
    if not blob:
        return None
    try:
        dati = json.loads(_decifra_contenuto(blob))
    except Exception:
        return None
    return dati if isinstance(dati, dict) else None


# ------- LE DOMANDE DEL VENDITORE AL COMPRATORE (6 nov 2026) -------
# Chi vende un bene a consegna digitale (un biglietto, un corso, una
# licenza intestata) puo' chiedere a chi compra dei dati: nome,
# cognome, email, una scelta da un elenco. Nasce per i biglietti di
# BitCare (FooEvents manda il biglietto all'email del compratore), ma
# e' una funzione generale: le domande le decide il venditore, quante
# ne vuole e ognuna obbligatoria o facoltativa (decisione di Andrea).
# IL MONDO DI IERI NON SI TOCCA: `annunci.domande` vuota = nessuna
# domanda, e la cassa resta byte per byte quella di prima.
# LE RISPOSTE SONO DATI PERSONALI e fanno la strada dell'indirizzo:
# cifrate in colonna, lette SOLO dalle due parti dalla loro rotta
# (il moderatore mai, nemmeno in disputa: gli escono i fatti), e via
# con la scopa a ordine chiuso — «le trasportiamo, non le conserviamo».
# ⚠️ IL TELEFONO NON SI CHIEDE: vincolo permanente di Andrea (ago
# 2026, «L'EMAIL PER IL CORRIERE»), e vale anche qui — una domanda che
# lo nomina e' un 400 che lo dice.
MAX_DOMANDE = 30            # «quante ne vuole»: il tetto e' solo tecnico
MAX_TESTO_DOMANDA = 80
MAX_OPZIONI_DOMANDA = 20
MAX_TESTO_OPZIONE = 60
MAX_RISPOSTA = 200
TIPI_DOMANDA = ("testo", "scelta", "email", "sino")
_RE_TELEFONO = re.compile(r"telefon|cellular|\bcell\b|whats ?app|\btel\b"
                          r"|\bcel\b|\bphone\b|\bmobile\b", re.I)


def _una_riga(x, tetto: int) -> str:
    """Gli spazi collassati e gli a-capo via (il patto della nota):
    e' quel che fa bastare esc() alla resa. Il tetto lo controlla il
    chiamante, col 400 che nomina il campo."""
    return " ".join(str(x if x is not None else "").split())[:tetto * 4]


def domande_da_payload(d: dict, consegna: str, anche_digitale) -> str | None:
    """Il giudice unico delle domande di un annuncio (pubblica e
    modifica): il JSON da scrivere in colonna, '' per «nessuna», None
    se la chiave NON c'e' (in modifica = conserva quelle di prima: il
    patto dello stock, la dichiarazione e' la PRESENZA della chiave).

    VIVONO SOLO DOVE C'E' IL DIGITALE: l'annuncio deve offrire il codice
    online, da solo o accanto a una consegna fisica (`anche_digitale`).
    Altrove si forzano a '' in silenzio, come `anche_digitale` col suo
    giudice: il client di ieri non deve rompersi.

    Ogni domanda e' {"t": testo, "k": tipo, "o": [opzioni], "obb": bool}.
    IL 400 E NON IL TRONCAMENTO (la regola della nota): una domanda
    tagliata a meta' non e' una domanda piu' corta."""
    if "domande" not in d:
        return None
    if consegna != "digitale" and not anche_digitale:
        return ""
    grezze = d.get("domande") or []
    if not isinstance(grezze, list):
        raise HTTPException(400, "Le domande per chi compra non si "
                                 "leggono: riprova")
    if len(grezze) > MAX_DOMANDE:
        raise HTTPException(400, f"Al massimo {MAX_DOMANDE} domande per "
                                 f"annuncio")
    pulite = []
    for g in grezze:
        if not isinstance(g, dict):
            raise HTTPException(400, "Una domanda per chi compra non si "
                                     "legge: riprova")
        testo = _una_riga(g.get("t"), MAX_TESTO_DOMANDA)
        if not testo:
            # la riga lasciata vuota nel modulo: si toglie, non e' un
            # errore (chi scrive cinque domande e ne cancella una non
            # deve sentirsi dire di no)
            continue
        if len(testo) > MAX_TESTO_DOMANDA:
            raise HTTPException(400, f"La domanda «{testo[:30]}…» è troppo "
                                     f"lunga (massimo {MAX_TESTO_DOMANDA} "
                                     f"caratteri)")
        if _RE_TELEFONO.search(testo):
            raise HTTPException(400, "Il numero di telefono non si può "
                                     "chiedere su Barattolo: chiedi "
                                     "l'email")
        tipo = g.get("k") if g.get("k") in TIPI_DOMANDA else "testo"
        opzioni = []
        if tipo == "scelta":
            for o in (g.get("o") or [])[:MAX_OPZIONI_DOMANDA * 2]:
                o = _una_riga(o, MAX_TESTO_OPZIONE)
                if not o or o in opzioni:
                    continue
                if len(o) > MAX_TESTO_OPZIONE:
                    raise HTTPException(400, f"La scelta «{o[:30]}…» è "
                                             f"troppo lunga (massimo "
                                             f"{MAX_TESTO_OPZIONE} caratteri)")
                opzioni.append(o)
            if len(opzioni) > MAX_OPZIONI_DOMANDA:
                raise HTTPException(400, f"Al massimo {MAX_OPZIONI_DOMANDA} "
                                         f"scelte per domanda")
            if len(opzioni) < 2:
                raise HTTPException(400, f"«{testo}»: scrivi almeno due "
                                         f"scelte nell'elenco")
        pulite.append({"t": testo, "k": tipo, "o": opzioni,
                       "obb": bool(g.get("obb"))})
    return json.dumps(pulite, ensure_ascii=False) if pulite else ""


def domande_lette(colonna) -> list:
    """La lista delle domande di un annuncio, difensiva: una colonna
    vuota o storta e' «nessuna domanda», mai un 500 alla cassa."""
    try:
        v = json.loads(colonna or "[]")
    except Exception:
        return []
    return [x for x in v if isinstance(x, dict) and x.get("t")] \
        if isinstance(v, list) else []


# ---- L'ETICHETTA DEGLI ALIMENTI (17 nov 2026, cantiere etichetta-alimenti)
# Da Luca, via Andrea: per l'art. 14 del Regolamento UE 1169/2011 chi
