@app.post("/api/me/avvisi-nuovi-p2p")
async def scegli_avvisi_nuovi_p2p(req: Request, x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """«🔔 Avvisami dei nuovi ordini P2P» (9 ott 2026, richiesta di
    Andrea): le TRE preferenze in una rotta sola — l'interruttore, i tipi
    di ordine che vuole (vendita BTC, acquisto BTC, Barattozon, almeno
    uno) e la soglia di convenienza ('' = tutti, oppure 0 / 2 / 5 punti
    almeno a suo favore). Le salvano uguali il bottone della testata del
    libro e il cassetto Avvisi del Profilo, e tornano come le legge
    /api/me (`_pref_avvisi_nuovi_p2p`): due viste, uno stato.
    Il canale (Telegram, DM Nostr) resta quello di `canale_notifiche`:
    questa dice SE e QUALI, quella dice DOVE. E l'interruttore grande
    degli avvisi P2P (`avvisi_p2p`) sta sopra: spento quello, non parte
    nemmeno questo. Solo per chi il P2P ce l'ha (409 agli altri, come la
    sveglia), e solo con la leva globale accesa."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    if not P2P_AVVISI_NUOVI_ORDINI:
        raise HTTPException(409, "Gli avvisi dei nuovi ordini sono spenti")
    d = await leggi_json(req)
    attivo = 1 if d.get("attivo") else 0
    grezzi = d.get("tipi")
    if grezzi is None:
        tipi = list(TIPI_AVVISI_NUOVI_P2P)
    else:
        if not isinstance(grezzi, list):
            raise HTTPException(400, "Tipi in formato sbagliato")
        tipi = [t for t in TIPI_AVVISI_NUOVI_P2P if t in grezzi]
        if not tipi:
            raise HTTPException(400, "Scegli almeno un tipo di ordine")
    soglia = str(d.get("soglia") if d.get("soglia") is not None else "").strip()
    if soglia not in ("",) + SOGLIE_AVVISI_NUOVI_P2P:
        raise HTTPException(400, "Soglia sconosciuta: tutti, -10, -5, -2, 0, 2 o 5")
    con = db()
    # LA RETE (30 ott 2026): '' = tutte, 'onchain', 'ln'. Un telefono di
    # ieri non la manda, e allora resta quella scritta
    if "rete" in d:
        rete = str(d.get("rete") or "").strip()
        if rete not in ("",) + RETI_AVVISI_NUOVI_P2P:
            con.close()
            raise HTTPException(400, "Rete sconosciuta: tutte, on-chain o Lightning")
    else:
        r = con.execute("SELECT avvisi_nuovi_rete FROM utenti WHERE tg_id=?",
                        (user["id"],)).fetchone()
        rete = str(r[0] or "") if r else ""
    # LA VALUTA (2 nov 2026): '' = tutte, 'EUR', 'USDT'. Un telefono di
    # ieri non la manda, e allora resta quella scritta
    if "valuta" in d:
        valuta = str(d.get("valuta") or "").strip().upper()
        if valuta not in ("",) + VALUTE_AVVISI_NUOVI_P2P:
            con.close()
            raise HTTPException(400, "Valuta sconosciuta: tutte, euro, USDT o franchi")
    else:
        r = con.execute("SELECT avvisi_nuovi_valuta FROM utenti WHERE tg_id=?",
                        (user["id"],)).fetchone()
        valuta = str(r[0] or "") if r else ""
    con.execute("UPDATE utenti SET avvisi_nuovi_p2p=?, avvisi_nuovi_tipi=?, "
                "avvisi_nuovi_soglia=?, avvisi_nuovi_rete=?, avvisi_nuovi_valuta=? "
                "WHERE tg_id=?",
                (attivo, "|" + "|".join(tipi) + "|", soglia, rete, valuta, user["id"]))
    con.commit()
    con.close()
    return {"ok": True, "avvisi_nuovi_p2p": _pref_avvisi_nuovi_p2p(
        {"avvisi_nuovi_p2p": attivo, "avvisi_nuovi_tipi": "|" + "|".join(tipi) + "|",
         "avvisi_nuovi_soglia": soglia, "avvisi_nuovi_rete": rete,
         "avvisi_nuovi_valuta": valuta})}


# I MOTIVI DELLO SCONOSCIUTO (12 ott 2026, chi-e-l-altro): quando
# l'altra parte non ha un volto da mostrare, la pagina deve dire SOLO
# quel che e' vero. `esterno` = il coordinatore l'ha nominata e la sua
# chiave non e' di nessuno dei nostri (un altro client Mostro);
# `anonimo_prima` = e' dei nostri ma la presa non e' annotata: uno
# scambio di prima del 12 ott 2026, quando chi entrava da Nostr restava
# anonimo di serie — la promessa di allora vale sul passato; `ignota` =
# il coordinatore non ha ancora detto niente, o chi chiede non e' una
# delle due parti. (Il caso «ha scelto di restare anonimo» non esiste:
# l'interruttore e' uscito, e l'anonimato e' una chiave Nostr nuova.) La
# sola fonte e' quel che il server gia' sa (`p2p_scambi` + `chiavi_p2p`):
# niente di nuovo si scrive, e niente esce verso chi non e' della partita.
MOTIVI_SCONOSCIUTO_P2P = ("esterno", "anonimo_prima", "ignota")


def _motivo_sconosciuto_p2p(con, ordine: str, io: int) -> str:
    """Uno dei `MOTIVI_SCONOSCIUTO_P2P`, per chi chiede `io`."""
    parti = _parti_scambio_p2p(con, ordine)
    if parti.get("fonte") != "mostro":
        return "ignota"
    io = int(io or 0)
    compra, vende = int(parti["compratore"] or 0), int(parti["venditore"] or 0)
    if io and io == compra:
        altro = vende
    elif io and io == vende:
        altro = compra
    else:
        return "ignota"
    if not altro:
        return "esterno"
    return "anonimo_prima"


def _motivi_controparti_p2p(con, ordini, io: int, serviti) -> dict:
    """{ordine: motivo} per gli ordini chiesti di cui NON e' uscito un
    volto; `serviti` sono quelli col volto. Pura sulla connessione."""
    fuori = {}
    for o in ordini:
        if o in serviti:
            continue
        m = _motivo_sconosciuto_p2p(con, o, io)
        if m != "ignota":
            fuori[o] = m
    return fuori


@app.post("/api/me/classifica-nascosta")
async def scegli_classifica_nascosta(req: Request,
                                     x_tg_init_data: str = Header(""),
                                     barattolo_sessione: str = Cookie("")):
    """«Non mostrarmi in classifica» (set 2026, ritocchi piccoli,
    decisione di Andrea): un si' o un no, come gli avvisi. Nascosto, il
    nome esce dalla classifica pubblica — e anche dalla riga «la tua
    posizione», che senza una classifica in cui stare non ha niente da
    dire. Il LIVELLO resta sul profilo: serve a chi scambia con lui per
    fidarsi, ed e' un'altra cosa dalla gara.
    Vale SUBITO: la cache di un minuto della classifica si butta, o chi
    si nasconde si rivedrebbe li' ancora per sessanta secondi.
    E VALE ANCHE SU NOSTR (secondo giro, set 2026): nascosto, il suo
    30382 si ritira e non si pubblica piu'; riacceso, torna. Lo fa il
    giudice di tutti i ganci, `premia_reputazione_nostr`, e qui si
    ASPETTA come alla verifica della npub: il client ha il suo velo, e
    quando risponde il giro e' fatto (fail-open: se i relay tacciono, la
    scelta e' salvata lo stesso e il prossimo gancio riprova)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    nascosta = 1 if d.get("nascosta") else 0
    con = db()
    con.execute("UPDATE utenti SET classifica_nascosta=? WHERE tg_id=?",
                (nascosta, user["id"]))
    con.commit()
    con.close()
    _classifica_cache["quando"] = 0.0
    await premia_reputazione_nostr(user["id"])
    return {"ok": True, "nascosta": bool(nascosta)}


@app.post("/api/me/avviso-trasporto")
async def timbra_avviso_trasporto(x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """«L'ho visto»: il foglio sul rischio del trasporto e' stato
    aperto, e non si riapre mai piu' (vedi #trasportoSheet nel client).

    Niente body e niente da validare: e' un timbro, e l'unico valore
    possibile e' 1 — non esiste il verso opposto, perche' un avviso
    letto non si puo' slettere. Il client lo scrive quando il foglio SI
    APRE e non quando si chiude, il patto delle campagne: un errore di
    rete puo' perdere un avviso di cortesia, mai raddoppiarlo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    con.execute("UPDATE utenti SET avvisato_trasporto=1 WHERE tg_id=?",
                (user["id"],))
    con.commit()
    con.close()
    return {"ok": True}


@app.post("/api/me/invito-corrieri")
async def timbra_invito_corrieri(x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """«Il foglio dei corrieri si e' aperto»: il contatore sale di uno.

    Gemello del timbro qui sopra, con UNA differenza che e' tutto il
    cantiere: quello e' un interruttore (visto/non visto), questo e' un
    CONTATORE, perche' l'invito e' insistente e non una-tantum — e a
    fermarlo e' INVITO_CORRIERI_MAX, non il primo sguardo.

    Sale quando il foglio SI APRE e non quando si legge: il patto di
    #trasportoSheet e del tour, «chiuderlo senza leggere e' una
    scelta». Nessun body: l'unica cosa che si puo' dire e' «e'
    successo»."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    con.execute("UPDATE utenti SET invito_corrieri=invito_corrieri+1 "
                "WHERE tg_id=?", (user["id"],))
    con.commit()
    con.close()
    return {"ok": True}


BIGLIETTI_FIRMA_NOSTR: dict[str, dict] = {}
MAX_RITIRI_IN_UNA_FIRMA = 150   # eventi in un kind 5 solo (vedi firme_nostr_da_fare)


@app.get("/api/me/firme-nostr")
async def firme_nostr_da_fare(x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """Cosa aspetta la firma di questo utente. Per ogni annuncio in
    coda si prepara l'evento GIA' PRONTO ma NON firmato, col suo
    biglietto: il client firma (bunker, estensione o nsec in pagina —
    mai qui), pubblica sui relay e torna con {biglietto, pubkey, sig}.
    Se l'utente non ha piu' una chiave provata la coda si svuota da
    sola: senza chiave quelle firme non arriveranno mai."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    u = con.execute("SELECT npub, npub_verificata, npub_accesso "
                    "FROM utenti WHERE tg_id=?", (user["id"],)).fetchone()
    sua = chiave_nostr_provata(u)
    if not sua:
        con.execute("DELETE FROM firme_nostr WHERE tg_id=?", (user["id"],))
        con.commit()
        con.close()
        return {"firme": []}
    # Stesso patto una riga piu' su, per un'altra ragione (ago 2026, il
    # tappo delle «due teste»): una firma su una riga diventata
    # IMPORTATA non ha piu' dove atterrare — il POST rifiuta di
    # scriverle una testa — e finche' resta in coda il browser la
    # rifirma e la ripubblica sui relay a OGNI apertura, piu' il nag di
    # sollecita_firme_nostr. La 'ritira' resta: toglie una testa, non
    # ne mette una.
    con.execute("DELETE FROM firme_nostr WHERE tg_id=? AND azione<>'ritira' "
                "AND annuncio_id IN (SELECT id FROM annunci "
                "WHERE contatto_nostr<>'')", (user["id"],))
    # E CON «NO» SUL SUO PROFILO (20 ott 2026, cantiere nostr-da-
    # telefono) non resta niente da pubblicare a nome suo: in coda
    # restano solo le cancellazioni.
    if not annunci_sul_suo_profilo(con, user["id"]):
        con.execute("DELETE FROM firme_nostr WHERE tg_id=? "
                    "AND azione<>'ritira'", (user["id"],))
    con.commit()
    righe = con.execute(
        "SELECT f.annuncio_id, f.azione, a.* FROM firme_nostr f "
        "JOIN annunci a ON a.id=f.annuncio_id "
        "WHERE f.tg_id=? AND f.azione<>'ritira' "
        "ORDER BY f.creato LIMIT 20",
        (user["id"],)).fetchall()
    # LE CANCELLAZIONI IN UNA FIRMA SOLA (20 ott 2026, cantiere nostr-da-
    # telefono, decisione di Andrea): un kind 5 con dentro tutti gli
    # eventi da ritirare, invece di uno per annuncio — chi sceglie «no»
    # con quaranta annunci approva UNA volta nell'app che firma, non
    # quaranta. Il tetto tiene l'evento sotto i limiti dei relay
    # (~170 byte per annuncio); oltre, il resto al giro dopo.
    ritiri = con.execute(
        "SELECT a.id, a.titolo, a.nostr_event_id FROM firme_nostr f "
        "JOIN annunci a ON a.id=f.annuncio_id "
        "WHERE f.tg_id=? AND f.azione='ritira' AND a.nostr_event_id<>'' "
        "ORDER BY f.creato LIMIT ?",
        (user["id"], MAX_RITIRI_IN_UNA_FIRMA)).fetchall()
    # IL TOTALE, oltre ai 20 di questo giro (ott 2026): il client rigira
    # finche' la coda si svuota, e il Profilo dice «Firma i tuoi N
    # annunci» col numero vero, non col tetto del LIMIT.
    # ...E LE CANCELLAZIONI A PARTE (23 ott 2026, cantiere firme-giuste,
    # decisione di Andrea): «Firma i tuoi N annunci» contava anche i
    # ritiri, e a chi ha scelto «no» diceva che restano solo qui. Il
    # totale sono le PUBBLICAZIONI; i ritiri che si possono firmare
    # (con un evento da cancellare) hanno il loro numero e la loro frase.
    totale = con.execute("SELECT COUNT(*) FROM firme_nostr WHERE tg_id=? "
                         "AND azione<>'ritira'",
                         (user["id"],)).fetchone()[0]
    ritiri_in_coda = con.execute(
        "SELECT COUNT(*) FROM firme_nostr f JOIN annunci a "
        "ON a.id=f.annuncio_id WHERE f.tg_id=? AND f.azione='ritira' "
        "AND a.nostr_event_id<>''", (user["id"],)).fetchone()[0]
    con.close()

    adesso = time.time()
    for b in [b for b, v in BIGLIETTI_FIRMA_NOSTR.items()
              if v["scade"] < adesso]:
        BIGLIETTI_FIRMA_NOSTR.pop(b, None)
    while len(BIGLIETTI_FIRMA_NOSTR) >= 1000:
        BIGLIETTI_FIRMA_NOSTR.pop(next(iter(BIGLIETTI_FIRMA_NOSTR)))

    fuori = []
    if ritiri:
        ids = [r["id"] for r in ritiri]
        tags = ([["e", r["nostr_event_id"]] for r in ritiri]
                + [["a", f"30402:{sua}:barattolo-{r['id']}"] for r in ritiri]
                + [["k", "30402"]])
        evento = evento_non_firmato(
            sua, 5, tags, "Annuncio rimosso da Barattolo" if len(ids) == 1
            else "Annunci rimossi da Barattolo", int(time.time()))
        biglietto = secrets.token_urlsafe(32)
        BIGLIETTI_FIRMA_NOSTR[biglietto] = {
            "annuncio_id": ids[0], "annuncio_ids": ids, "tg_id": user["id"],
            "azione": "ritira", "kind": 5, "tags": evento["tags"],
            "content": evento["content"],
            "created_at": evento["created_at"], "scade": adesso + 600}
        fuori.append({"biglietto": biglietto, "annuncio_id": ids[0],
                      "titolo": ritiri[0]["titolo"] if len(ids) == 1
                      else f"{len(ids)} annunci", "azione": "ritira",
                      "quanti": len(ids), "evento": evento})
    for r in righe:
        a = dict(r)
        # 'pubblica' rilegge lo stato di ADESSO: fra l'accodamento
        # e la firma l'annuncio puo' essere stato venduto, e
        # nascere «attivo» sarebbe una bugia in piazza.
        stato = a["azione"] if a["azione"] in ("sold", "active") else (
            "sold" if a["stato"] == "venduto" else "active")
        # Si riusa evento_annuncio per non avere DUE posti che
        # costruiscono i tag NIP-99 di un annuncio (divergerebbero
        # al primo campo nuovo, ed e' anche cio' che la sentinella
        # del «punto» sorveglia). Firma con la chiave nostra e la
        # firma si butta: qui servono solo tags e content, che poi
        # l'utente firma con la SUA. Uno spreco dichiarato, in
        # cambio di un posto solo — e la coda si riempie solo dopo
        # il gate _NOSTR, quindi la chiave c'e' di sicuro.
        base = evento_annuncio(a, stato)
        evento = evento_non_firmato(sua, 30402, base["tags"],
                                    base["content"], base["created_at"])
        biglietto = secrets.token_urlsafe(32)
        BIGLIETTI_FIRMA_NOSTR[biglietto] = {
            "annuncio_id": a["id"], "tg_id": user["id"],
            "azione": a["azione"], "kind": evento["kind"],
            "tags": evento["tags"], "content": evento["content"],
            "created_at": evento["created_at"], "scade": adesso + 600}
        fuori.append({"biglietto": biglietto, "annuncio_id": a["id"],
                      "titolo": a["titolo"], "azione": a["azione"],
                      "evento": evento})
    return {"firme": fuori, "totale": totale, "ritiri": ritiri_in_coda,
            "relays": _relays_import(),
            "collaudo": MODALITA_COLLAUDO}


@app.post("/api/me/firme-nostr")
async def firma_nostr_fatta(req: Request, x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """Il client ha firmato e messo l'evento sui relay: qui si
    verifica la firma sull'evento RICOSTRUITO dal biglietto (una
    divergenza e' impossibile per costruzione) e si registra chi l'ha
    firmato. Da quel momento la piattaforma NON tocca piu' quell'evento
    — e' proprio il punto di tutto questo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    b = BIGLIETTI_FIRMA_NOSTR.pop(str(d.get("biglietto") or ""), None)
    if not b or b["scade"] < time.time() or b["tg_id"] != user["id"]:
        raise HTTPException(400, "La firma ha aspettato troppo: "
                                 "la richiesta tornerà da sola")
    pubkey = str(d.get("pubkey") or "").lower()
    sig = str(d.get("sig") or "").lower()
    if not RE_HEX_64.fullmatch(pubkey) or not RE_HEX_128.fullmatch(sig):
        raise HTTPException(400, "Firma malformata")
    if ChiavePubblicaNostr is None:
        raise HTTPException(503, "Firma Nostr non disponibile: sul server "
                                 "manca il pacchetto coincurve")
    con = db()
    u = con.execute("SELECT npub, npub_verificata, npub_accesso "
                    "FROM utenti WHERE tg_id=?", (user["id"],)).fetchone()
    # La chiave si rilegge FRESCA: fra il biglietto e adesso l'utente
    # puo' aver cambiato npub, e un evento firmato da una chiave che
    # non e' piu' sua non e' suo.
    if pubkey != chiave_nostr_provata(u):
        con.close()
        raise HTTPException(400, "La firma non è della tua chiave Nostr")
    ev = evento_non_firmato(pubkey, b["kind"], b["tags"], b["content"],
                            b["created_at"])
    try:
        buona = ChiavePubblicaNostr(bytes.fromhex(pubkey)).verify(
            bytes.fromhex(sig), bytes.fromhex(ev["id"]))
    except Exception:
        buona = False
    if not buona:
        con.close()
        raise HTTPException(400, "Firma non valida")
    imp = con.execute("SELECT contatto_nostr FROM annunci WHERE id=?",
                      (b["annuncio_id"],)).fetchone()
    vecchio = None       # il nostro evento da seppellire, se c'e'
    # la cancellazione in una firma sola ne porta tanti (firme_nostr_da_fare)
    ids = list(b.get("annuncio_ids") or [b["annuncio_id"]])
    if b["azione"] == "ritira":
        # Ritirato: la riga torna com'era prima di Nostr, e nessun
        # gancio la ripubblichera' piu' (sono tutti solo_aggiornamento).
        # Qui NON si guarda `contatto_nostr`, ed e' l'asimmetria che
        # conta: ritirare TOGLIE una testa, non ne mette una — su una
        # riga diventata importata e' anzi una delle strade di
        # guarigione.
        con.executemany("UPDATE annunci SET nostr_event_id='', "
                        "nostr_autore='' WHERE id=?", [(i,) for i in ids])
    elif imp and imp["contatto_nostr"]:
        # La riga e' diventata IMPORTATA mentre la firma era per strada
        # (ago 2026, la cintura del tappo delle «due teste»): scriverle
        # addosso il filo dell'evento la farebbe dire due cose
        # incompatibili, e il venditore perderebbe Modifica e
        # rifornimento. L'evento e' gia' in piazza e resta suo — qui si
        # rinuncia al filo, e la firma esce comunque dalla coda qui
        # sotto, o il browser la rifirmerebbe a ogni apertura.
        print(f"⚠️ Firma su annuncio #{b['annuncio_id']}, diventato "
              f"importato: nessuna testa scritta")
    else:
        # IL TRASLOCO, il passaggio di consegne: se quell'annuncio era
        # in piazza a nome NOSTRO, adesso che il suo evento e' nato il
        # nostro va cancellato — e l'id da cancellare si legge QUI,
        # nell'unico istante in cui esiste ancora, perche' la riga sotto
        # sta per sovrascriverlo.
        vecchio = con.execute(
            "SELECT nostr_event_id FROM annunci WHERE id=? "
            "AND nostr_autore='' AND nostr_event_id<>''",
            (b["annuncio_id"],)).fetchone()
        con.execute("UPDATE annunci SET nostr_event_id=?, nostr_autore=? "
                    "WHERE id=?", (ev["id"], pubkey, b["annuncio_id"]))
        if vecchio:
            # Si SCRIVE e non si azzera mai da qui: una lapide gia' in
            # attesa non deve poter sparire per una seconda firma, o
            # quell'evento resterebbe nostro e vivo per sempre.
            con.execute("UPDATE annunci SET nostr_event_vecchio=? "
                        "WHERE id=?",
                        (vecchio["nostr_event_id"], b["annuncio_id"]))
    con.executemany("DELETE FROM firme_nostr WHERE annuncio_id=?",
                    [(i,) for i in ids])
    con.commit()
    con.close()
    if b["azione"] == "ritira":
        # Chi ha scelto «no» li ritrova col nome di Barattolo, ADESSO
        # che il suo evento e' cancellato e non fanno due teste
        asyncio.create_task(_ripubblica_col_nome_nostro(ids, dopo_ritiro=True))
    if vecchio:
        # Subito, senza aspettare il giro dell'orologio: il doppione in
        # piazza dura quanto questa riga. Fail-open come ogni gancio
        # Nostr — se non riesce, `trasloca_annunci_nostr` riprova.
        asyncio.create_task(_seppellisci_vecchio(
            b["annuncio_id"], vecchio["nostr_event_id"]))
    return {"ok": True, "evento": ev["id"]}


async def _ripubblica_col_nome_nostro(ids, dopo_ritiro: bool = False) -> int:
    """Gli annunci di chi ha scelto «no» (annunci_sul_suo_profilo)
    tornano in piazza col nome di Barattolo — solo quelli vivi (attivi o
    venduti), nati qui, e senza piu' un evento. Di chi ha detto «si'»
    non si ripubblica niente. Fail-open come ogni gancio Nostr. Torna
    quanti ne ha mandati.
    `dopo_ritiro` (23 ott 2026, firme-giuste): la chiamata dopo una
    cancellazione firmata. Allora rinascono SOLO quelli che il «no» ha
    accodato (`ritiri_per_scelta`), e l'elenco si consuma: un doppione
    ritirato a mano col «si'» e firmato dopo un «no» resta fuori dalla
    piazza, come il suo padrone aveva chiesto."""
    fatti = 0
    try:
        con = db()
        segni = ",".join("?" * len(ids))
        filtro = (" AND id IN (SELECT annuncio_id FROM ritiri_per_scelta)"
                  if dopo_ritiro else "")
        righe = con.execute(
            "SELECT id, venditore_id, stato FROM annunci WHERE id IN (%s) "
            "AND stato IN ('attivo','venduto') AND contatto_nostr='' "
            "AND nostr_event_id=''%s" % (segni, filtro),
            [int(i) for i in ids]).fetchall() if ids else []
        da_fare = [(r["id"], "sold" if r["stato"] == "venduto" else "active")
                   for r in righe
                   if not annunci_sul_suo_profilo(con, r["venditore_id"])]
        if dopo_ritiro and ids:
            con.execute("DELETE FROM ritiri_per_scelta WHERE annuncio_id "
                        "IN (%s)" % segni, [int(i) for i in ids])
            con.commit()
        con.close()
    except Exception as e:
        print(f"⚠️ Ripubblicazione col nome di Barattolo saltata: {e}")
        return 0
    for annuncio_id, status in da_fare:
        await annuncio_su_nostr(annuncio_id, status)
        fatti += 1
    return fatti


@app.post("/api/me/nostr/annunci-sul-profilo")
async def scegli_annunci_sul_profilo(req: Request,
                                     x_tg_init_data: str = Header(""),
                                     barattolo_sessione: str = Cookie("")):
    """«Pubblica i miei annunci anche sul mio profilo Nostr» (20 ott 2026,
    cantiere nostr-da-telefono, decisione di Andrea).
    SI': il bivio di sempre. Le cancellazioni accodate da un «no» di
    prima e non ancora firmate su annunci vivi si buttano (cancellerebbero
    un annuncio che lui ora vuole), e il trasloco porta a nome suo quel
    che e' uscito col nostro.
    NO: in coda non resta niente da pubblicare a nome suo; gli eventi
    gia' FIRMATI DA LUI si accodano tutti per la cancellazione NIP-09,
    che firma lui UNA volta (firme_nostr_da_fare li mette in un kind 5
    solo); firmata quella, `_ripubblica_col_nome_nostro` li rimette in
    piazza col nostro nome. Quelli che un evento non l'hanno ancora
    escono col nostro nome subito. Si dice onesto quel che la NIP-09 e':
    una richiesta ai relay, che possono tenerne una copia."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    si = 1 if d.get("si") else 0
    con = db()
    u = con.execute("SELECT npub, npub_verificata, npub_accesso "
                    "FROM utenti WHERE tg_id=?", (user["id"],)).fetchone()
    sua = chiave_nostr_provata(u)
    con.execute("UPDATE utenti SET annunci_su_profilo_nostr=? WHERE tg_id=?",
                (si, user["id"]))
    da_ritirare, subito, accodati = 0, [], 0
    if si:
        # solo le cancellazioni che il «no» aveva accodato: un doppione
        # ritirato a mano, o un annuncio tolto, resta da cancellare
        con.execute(
            "DELETE FROM firme_nostr WHERE tg_id=? AND azione='ritira' "
            "AND annuncio_id IN (SELECT annuncio_id FROM ritiri_per_scelta)",
            (user["id"],))
        con.execute(
            "DELETE FROM ritiri_per_scelta WHERE annuncio_id IN "
            "(SELECT id FROM annunci WHERE venditore_id=?)", (user["id"],))
        accodati = _accoda_trasloco_di(con, user["id"]) if sua else 0
    else:
        # quelli che aspettavano di NASCERE a nome suo nascono col nostro
        # (solo loro: un annuncio tolto da Nostr apposta, come il ritiro
        # di un doppione, non ha una riga qui e non rinasce)
        subito = [r["annuncio_id"] for r in con.execute(
            "SELECT annuncio_id FROM firme_nostr WHERE tg_id=? "
            "AND azione<>'ritira'", (user["id"],)).fetchall()]
        con.execute("DELETE FROM firme_nostr WHERE tg_id=? "
                    "AND azione<>'ritira'", (user["id"],))
        for r in con.execute(
                "SELECT a.id, f.azione FROM annunci a "
                "LEFT JOIN firme_nostr f ON f.annuncio_id=a.id "
                "WHERE a.venditore_id=? AND a.nostr_autore<>'' "
                "AND a.nostr_event_id<>'' AND a.contatto_nostr=''",
                (user["id"],)).fetchall():
            da_ritirare += 1
            if r["azione"] == "ritira":
                continue     # gia' da cancellare per un'altra ragione:
                             # non e' del «no», e non rinascera'
            accoda_firma(con, r["id"], user["id"], "ritira")
            con.execute("INSERT OR IGNORE INTO ritiri_per_scelta"
                        "(annuncio_id, creato) VALUES(?,?)",
                        (r["id"], int(time.time())))
    con.commit()
    con.close()
    if subito:
        asyncio.create_task(_ripubblica_col_nome_nostro(subito))
    return {"ok": True, "si": bool(si), "da_ritirare": da_ritirare,
            "accodati": accodati}


@app.post("/api/me/titolo")
async def scegli_titolo(req: Request,
                        x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """Il titolo che si porta sotto il nome. Si accetta SOLO un titolo
    davvero sbloccato — il pattern di canale-notifiche e
    avatar-scelta: si accetta solo una sorgente che esiste — e il
    giudice e' titoli_disponibili, lo stesso che compila l'elenco nel
    Profilo, o si potrebbe indossare qualcosa che l'elenco non offre.
    Stringa vuota = nessun titolo, ed e' sempre lecita."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    scelto = (d.get("titolo") or "").strip()
    con = db()
    try:
        if scelto and scelto not in titoli_disponibili(con, user["id"]):
            raise HTTPException(400, "Questo titolo non l'hai ancora "
                                     "sbloccato")
        con.execute("UPDATE utenti SET titolo=? WHERE tg_id=?",
                    (scelto, user["id"]))
        con.commit()
    finally:
        con.close()
    return {"ok": True, "titolo": scelto}


@app.post("/api/me/nip05")
async def scegli_nip05(req: Request,
                       x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """IL NOME VERIFICATO SU NOSTR (17 nov 2026, cantiere nip05-utenti):
    `{"nome": "mario"}` lo prende, `{"nome": ""}` lo lascia. Gratis,
    niente fattura. Le guardie in fila: la leva (404 a leva spenta,
    come le sorelle), una chiave Nostr PROVATA, il livello, la forma,
    nessun altro col nome. LASCIARLO non chiede ne' chiave ne' livello:
    chi non ne ha piu' il diritto deve poter sempre togliere il suo.
    Il controllo «libero» e la scrittura stanno nello STESSO lock, o due
    persone che scelgono lo stesso nome nello stesso istante lo
    prenderebbero tutte e due. La risposta e' lo stato intero, riletto."""
    if not NIP05_UTENTI_ATTIVO:
        raise HTTPException(404, "Funzione non attiva")
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    grezzo = str((d or {}).get("nome") or "").strip()
    con = db()
    try:
        con.execute("BEGIN IMMEDIATE")
        u = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                        (user["id"],)).fetchone()
        if not u:
            raise HTTPException(404, "Profilo non trovato")
        if not grezzo:
            con.execute("UPDATE utenti SET nip05_nome='' WHERE tg_id=?",
                        (user["id"],))
        else:
            st = nip05_stato(u)
            if not st["chiave"]:
                raise HTTPException(400, "Prima collega la tua chiave "
                                         "Nostr con una firma")
            if not st["sblocca"]:
                raise HTTPException(400, "Si sblocca dal livello «"
                                         f"{st['livello_nome']}»")
            nome, motivo = _nip05_nome_forma(grezzo)
            if not nome:
                raise HTTPException(400, motivo)
            if not _nip05_nome_libero(con, nome, user["id"]):
                raise HTTPException(400, "Questo nome è già preso: "
                                         "scegline un altro")
            con.execute("UPDATE utenti SET nip05_nome=? WHERE tg_id=?",
                        (nome, user["id"]))
        con.commit()
        u = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                        (user["id"],)).fetchone()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return {"ok": True, "nip05": nip05_stato(u)}


@app.post("/api/me/serie")
async def passa_serie(x_tg_init_data: str = Header(""),
                      barattolo_sessione: str = Cookie("")):
    """LA SERIE DEI GIORNI 🔥 quando l'app NON si riapre (17 nov 2026):
    una PWA o una Mini App lasciata in tasca torna in primo piano senza
    rifare /api/me, e chi la guarda ogni giorno cosi' non conterebbe
    mai. Il client bussa qui al ritorno, solo se in Italia e' cambiato
    il giorno. Stesso timbro e stessa busta di /api/me (`timbra_serie`):
    due porte, un giudice. A leva spenta risponde 404, come le sorelle.
    Niente corpo: non c'e' niente che il client possa dichiarare — il
    giorno lo decide l'orologio del server."""
    if not SERIE_GIORNI_ATTIVA:
        raise HTTPException(404, "Funzione non attiva")
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    try:
        if not con.execute("SELECT 1 FROM utenti WHERE tg_id=?",
                           (user["id"],)).fetchone():
            raise HTTPException(404, "Profilo non trovato")
        serie = timbra_serie(con, user["id"])
        con.commit()
    finally:
        con.close()
    return {"ok": True, "serie": serie}


