@app.post("/api/me/avatar-scelta")
async def scegli_avatar(req: Request,
                        x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """Il selettore «La tua foto» del cassetto Identita': da quale
    social prendere il francobollo — '' = automatico (la catena
    Telegram → Nostr → iniziale), 'telegram' | 'nostr' espliciti per
    chi ha entrambe le sorgenti, 'nessuna' = iniziale ovunque per il
    pubblico (reversibile: il file resta in dispensa e il CASE nelle
    SELECT lo tiene in casa). Si accetta solo una sorgente che esiste
    davvero — il pattern di canale-notifiche."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    scelta = (d.get("scelta") or "").strip().lower()
    if scelta not in ("", "telegram", "nostr", "nessuna"):
        raise HTTPException(400, "Scelta sconosciuta: telegram, nostr, "
                                 "nessuna o vuoto (automatico)")
    con = db()
    u = con.execute(
        "SELECT npub, npub_verificata, npub_accesso FROM utenti "
        "WHERE tg_id=?", (user["id"],)).fetchone()
    if not u:
        con.close()
        raise HTTPException(404, "Profilo non trovato")
    if scelta == "telegram" and user["id"] < 0:
        con.close()
        raise HTTPException(400,
            "Questo account non ha una chat Telegram: collegala dal "
            "blocco «Le tue identita'»")
    ha_nostr = bool(u["npub_accesso"] or
                    (u["npub"] and u["npub_verificata"]))
    if scelta == "nostr" and not ha_nostr:
        con.close()
        raise HTTPException(400,
            "Prima verifica la tua npub (o entra con Nostr): la foto si "
            "prende solo da una chiave di cui hai dimostrato il possesso")
    con.execute("UPDATE utenti SET avatar_scelta=? WHERE tg_id=?",
                (scelta, user["id"]))
    con.commit()
    con.close()
    # LA SORGENTE E' CAMBIATA, E QUI SI ASPETTA (ago 2026, decisione
    # di Andrea): era un `create_task` — la risposta non aspettava — e
    # andava bene finche' la propria faccia si vedeva comunque. Da
    # quando «Nessuna» la spegne anche per lui, riaccendendo il client
    # non ha PIU' NESSUN nome in mano: senza l'attesa resterebbe
    # l'iniziale fino al prossimo /api/me, cioe' lo stesso «il bottone
    # non fa niente» rovesciato — e per giunta il rinfresco cancella il
    # file vecchio (i nomi sono versionati), quindi non basterebbe
    # rimettere quello di prima.
    # IL PREZZO E' DICHIARATO: il bottone ci mette quanto ci mette il
    # social (due chiamate a Telegram, quattro relay per Nostr). Vale
    # per un gesto raro, e a dirlo c'e' il velo del cassetto.
    # Con 'nessuna' non si aspetta NIENTE: li' non c'e' niente da
    # scaricare, e spegnere resta istantaneo.
    if scelta != "nessuna":
        await aggiorna_profilo_social(user["id"])
    # Il nome del francobollo torna col si': e' quello che permette al
    # client di rimettere la faccia SUBITO, senza ricaricare. Si
    # rilegge DOPO il rinfresco, o si direbbe il nome di ieri — e passa
    # dal giudice, che con 'nessuna' risponde ''.
    # IL NOME VERO torna qui accanto (set 2026): 'nostr' puo' averlo
    # appena riscritto (aggiorna_profilo_social, qui sopra), e senza
    # questa chiave il client restava fermo al nome di prima finche' non
    # si ricaricava tutta la Mini App — la stessa attesa che questo giro
    # esiste per togliere alla foto.
    con = db()
    r = con.execute("SELECT avatar, nome FROM utenti WHERE tg_id=?",
                    (user["id"],)).fetchone()
    con.close()
    return {"ok": True, "scelta": scelta,
            "avatar": avatar_da_mostrare(r["avatar"] if r else "",
                                         scelta),
            "nome": r["nome"] if r else ""}


# --- Avvisi di ricerca: «dimmi quando esce quello che cerco» ---------
# L'utente salva fino a 5 ricerche (categorie, comune+raggio, prezzo
# max, parole chiave) e il matching alla pubblicazione lo avvisa via
# notifica() multi-canale. Il motore vive accanto ai post automatici.

MAX_AVVISI_UTENTE = 5
RAGGI_AMMESSI = (10, 25, 50, 100)
def _avviso_pubblico(r) -> dict:
    """La riga del DB come la vede il frontend: categorie da
    '|A|B|' a lista, il resto com'e'."""
    return {"id": r["id"],
            "categorie": [c for c in r["categorie"].split("|") if c],
            "comune": r["comune"], "raggio_km": r["raggio_km"],
            "prezzo_max_sats": r["prezzo_max_sats"],
            "prezzo_max_eur": r["prezzo_max_eur"],
            "parole": r["parole"], "attivo": r["attivo"]}


@app.get("/api/comuni")
async def cerca_comuni(q: str = "",
                       x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """Suggerimenti per i campi comune (la Zona di Vendi e il comune
    degli avvisi di ricerca): primi 10 comuni per prefisso — del nome
    («gub» -> Gubbio), del nome con la sigla («gubbio pg», la forma
    che questa stessa tendina propone e che finisce in colonna) o del
    nome senza preposizioni («reggio emilia»). Sono le tre forme che
    la zona sa riconoscere: il perche' sta su _comuni_prefisso.
    Autenticato come tutto cio' che non e' vetrina. E' stata PUBBLICA
    per due giorni, per il filtro «Vicino a me» che viveva anche nella
    vetrina anonima: morto quello, e' tornata dov'era — non perche'
    aprirla facesse danno (e' l'elenco ISTAT committato in chiaro), ma
    perche' una superficie pubblica senza piu' un motivo e' solo
    superficie."""
    verifica_utente(x_tg_init_data, barattolo_sessione)
    prefisso = normalizza(q)
    if len(prefisso) < 2:
        return {"comuni": []}
    trovati = []
    for nome, con_sigla, senza_prep, voce in _comuni_prefisso():
        if (nome.startswith(prefisso) or con_sigla.startswith(prefisso)
                or senza_prep.startswith(prefisso)):
            trovati.append(voce)
            if len(trovati) == 10:
                break
    return {"comuni": trovati}


@app.get("/api/zona-controlla")
async def zona_controlla(testo: str = "",
                         x_tg_init_data: str = Header(""),
                         barattolo_sessione: str = Cookie("")):
    """La validazione MORBIDA della zona di Vendi (lug 2026): se nel
    testo libero c'e' un comune riconoscibile (anche «provincia di
    Pavia»: gli n-grammi lo pescano) va tutto bene; se non c'e' NULLA
    ma un quasi-comune si' («Pvia» -> Pavia), il client mostra
    «intendevi...?». Mai bloccante: e' solo un consiglio. Dataset
    assente = sempre riconosciuto (la funzione si spegne in silenzio,
    come tutta la geografia)."""
    verifica_utente(x_tg_init_data, barattolo_sessione)
    testo = (testo or "").strip()[:120]
    if not testo or not COMUNI:
        return {"riconosciuto": True, "suggerimento": ""}
    lat, lon = coordinate_da_zona(testo)
    if lat or lon:
        return {"riconosciuto": True, "suggerimento": ""}
    return {"riconosciuto": False, "suggerimento": suggerisci_comune(testo)}


