@app.post("/api/me/avvisi-mercatino")
async def scegli_avvisi_mercatino(req: Request, x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """«🆕 Avvisami dei nuovi annunci» (9 ott 2026, richiesta di Andrea):
    le preferenze in una rotta sola — l'interruttore, le categorie che
    vuole (nessuna = tutte) e il prezzo massimo nella sua valuta (0 =
    nessun tetto). Le salva il blocco «Mercatino» del cassetto Avvisi e
    tornano come le legge /api/me (`_pref_avvisi_mercatino`): una vista,
    uno stato. A differenza di «Avvisami se arriva» qui l'avviso vuoto e'
    LEGITTIMO: «tutti i nuovi annunci» e' proprio quel che chiede, ed e'
    il raggruppamento a tenerlo gentile. Il canale (Telegram, DM Nostr)
    resta quello di `canale_notifiche`: questa dice SE e QUALI, quella
    dice DOVE. Solo con la leva globale accesa (409 altrimenti)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not MERCATINO_AVVISI_NUOVI:
        raise HTTPException(409, "Gli avvisi del mercatino sono spenti")
    d = await leggi_json(req)
    attivo = 1 if d.get("attivo") else 0
    grezze = d.get("categorie") or []
    if not isinstance(grezze, list):
        raise HTTPException(400, "Categorie in formato sbagliato")
    scelte = [c for c in CATEGORIE if c in grezze]
    valuta = "eur" if d.get("valuta") == "eur" else "sats"
    try:
        prezzo = float(str(d.get("prezzo_max") or 0).replace(",", "."))
    except ValueError:
        raise HTTPException(400, "Prezzo massimo non valido")
    if prezzo < 0 or prezzo != prezzo or prezzo == float("inf"):
        raise HTTPException(400, "Prezzo massimo non valido")
    prezzo = int(prezzo) if valuta == "sats" else round(prezzo, 2)
    colonne = {"avvisi_mercatino": attivo,
               "avvisi_mercatino_categorie": ("|" + "|".join(scelte) + "|") if scelte else "",
               "avvisi_mercatino_prezzo": prezzo,
               "avvisi_mercatino_valuta": valuta}
    con = db()
    con.execute("UPDATE utenti SET avvisi_mercatino=?, avvisi_mercatino_categorie=?, "
                "avvisi_mercatino_prezzo=?, avvisi_mercatino_valuta=? WHERE tg_id=?",
                (attivo, colonne["avvisi_mercatino_categorie"], prezzo, valuta, user["id"]))
    con.commit()
    con.close()
    return {"ok": True, "avvisi_mercatino": _pref_avvisi_mercatino(colonne)}


@app.post("/api/negozio/{chi}/segui")
async def segui_venditore(chi: str, req: Request, x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """«🔔 Segui» sulla pagina di un venditore (9 ott 2026, richiesta di
    Andrea): {segui: true} segue, {segui: false} smette — dal bottone del
    negozio e dall'elenco «Venditori che segui» del cassetto Avvisi. Il
    venditore si trova come lo trova /api/negozio (slug, username,
    codice: mai col tg_id, che in pubblico non esce), mai se stessi, con
    un tetto di buon senso. Risponde con lo stato e con l'elenco intero,
    cosi' il cassetto si ridisegna senza una seconda domanda. Solo con
    la leva globale accesa (409)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not MERCATINO_AVVISI_NUOVI:
        raise HTTPException(409, "Gli avvisi del mercatino sono spenti")
    d = await leggi_json(req)
    con = db()
    try:
        v = _venditore_da_chi(con, chi)
        if not v:
            raise HTTPException(404, "Negozio non trovato")
        if int(v["tg_id"]) == int(user["id"]):
            raise HTTPException(400, "Il tuo negozio lo conosci gia': non puoi seguirti")
        if d.get("segui"):
            quanti = con.execute("SELECT COUNT(*) AS n FROM venditori_seguiti WHERE tg_id=?",
                                 (user["id"],)).fetchone()["n"]
            gia = con.execute("SELECT 1 FROM venditori_seguiti WHERE tg_id=? AND venditore_id=?",
                              (user["id"], v["tg_id"])).fetchone()
            if not gia and quanti >= TETTO_VENDITORI_SEGUITI:
                raise HTTPException(400, f"Segui gia' {TETTO_VENDITORI_SEGUITI} venditori: "
                                         "smetti di seguirne uno per seguirne altri")
            con.execute("INSERT OR IGNORE INTO venditori_seguiti(tg_id, venditore_id, creato) "
                        "VALUES(?,?,?)", (user["id"], v["tg_id"], int(time.time())))
            seguito = True
        else:
            con.execute("DELETE FROM venditori_seguiti WHERE tg_id=? AND venditore_id=?",
                        (user["id"], v["tg_id"]))
            seguito = False
        con.commit()
    finally:
        con.close()
    return {"ok": True, "seguito": seguito, "seguiti": _seguiti_di(user["id"])}


# --- I codici sconto del venditore -----------------------------------
# Il modello e' `avvisi_ricerca` e NON i due cassetti delle promesse:
# li' c'e' UNA regola con UN bottone che salva e uno che spegne, qui
# una LISTA con un tetto. Tutta la grammatica di renderScontoPacco
# (bozza unica, pillole che scelgono, sogliaMancante) e' la grammatica
# sbagliata per una lista.


def _codice_pubblico(r, usi: int, adesso: int) -> dict:
    """La riga come la legge il SUO venditore.

    `vale` lo dice lo STESSO _codice_vale che gira alla cassa: e' il
    posto in cui il venditore scopre che il suo codice e' morto, e con
    due giudici leggerebbe «valido» su un codice che alla cassa non
    scatta — la divergenza che nessuno scopre finche' non protesta un
    compratore."""
    return {"id": r["id"], "codice": r["codice"], "percento": r["percento"],
            "scadenza": r["scadenza"], "usi_max": r["usi_max"],
            "attivo": r["attivo"], "creato": r["creato"], "usi": usi,
            # IL TIPO E LA SUA CIFRA (ago 2026): escono NORMALIZZATI dal
            # giudice — mai le colonne grezze — o la riga del cassetto
            # direbbe «−0%» su un codice a valore, cioe' la stessa cosa
            # che la lista esiste per non far indovinare al venditore.
            # Le due colonne dell'altra unita' escono comunque: sono la
            # cifra che ha scritto lui, e il toggle del cassetto le
            # CONSERVA — il patto delle due soglie a valore.
            "tipo": _tipo_codice(r["tipo"]) or "percento",
            "valore_sats": r["valore_sats"], "valore_eur": r["valore_eur"],
            "valore_valuta": _valuta_soglia(r["valore_valuta"]) or "eur",
            # si somma agli altri sconti, o vince il maggiore (ott 2026)
            "cumulabile": bool(r["cumulabile"]),
            "vale": bool(_codice_vale(r["tipo"], r["percento"],
                                      r["valore_sats"], r["valore_eur"],
                                      r["valore_valuta"], r["scadenza"],
                                      r["usi_max"], r["attivo"],
                                      r["venditore_id"], r["venditore_id"],
                                      adesso, usi))}


@app.get("/api/me/codici-sconto")
async def lista_codici_sconto(x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    righe = con.execute("SELECT * FROM codici_sconto WHERE venditore_id=? "
                        "ORDER BY creato DESC, id DESC",
                        (user["id"],)).fetchall()
    # IL CONTEGGIO E' UNA QUERY SOLA e non N chiamate a _usi_codice —
    # e passa dallo STESSO frammento costante della cassa, o la lista
    # e il conto direbbero due numeri diversi sullo stesso codice.
    usi = {}
    if righe:
        segni = ",".join("?" * len(righe))
        for u in con.execute(
                f"SELECT codice_sconto_id AS cid, COUNT(*) AS n FROM ordini "
                f"WHERE codice_sconto_id IN ({segni}) AND {USI_CODICE_DOVE} "
                f"GROUP BY codice_sconto_id",
                [r["id"] for r in righe] + [int(time.time()) - 1800]):
            usi[u["cid"]] = u["n"]
    con.close()
    adesso = int(time.time())
    return {"codici": [_codice_pubblico(r, usi.get(r["id"], 0), adesso)
                       for r in righe],
            "max": CODICI_SCONTO_MAX_PER_VENDITORE,
            "attivo": bool(CODICI_SCONTO_ATTIVI),
            "sconti": list(CODICI_SCONTO_PERCENTI),
            "durate": list(CODICI_SCONTO_DURATE_GIORNI),
            "min_percento": CODICI_SCONTO_MIN_PERCENTO,
            "max_percento": CODICI_SCONTO_MAX_PERCENTO,
            # la gemella della busta di /api/me: le due si tengono in
            # pari o il cassetto direbbe due cose secondo la strada
            "valori_eur": list(CODICI_SCONTO_VALORI_EUR),
            "valori_sats": list(CODICI_SCONTO_VALORI_SATS),
            "max_valore_eur": CODICI_SCONTO_MAX_VALORE_EUR,
            "max_valore_sats": CODICI_SCONTO_MAX_VALORE_SATS,
            "valute": list(VALUTE_SOGLIA),
            "max_usi": CODICI_SCONTO_MAX_USI,
            **_leve_inviti_codice()}


@app.post("/api/me/codici-sconto")
async def salva_codice_sconto(req: Request,
                              x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """Crea un codice sconto, o lo aggiorna se il payload porta un id.

    NIENTE `_impegni_aperti` e NIENTE `guardia_ferie_venditore`, per le
    due ragioni gia' scritte per esteso in imposta_sconto_pacco: qui
    non si toglie niente a nessuno — gli ordini gia' nati portano il
    loro sconto fotografato e la loro escrow e' gia' scontata — e
    sistemare il listino mentre si e' via e' esattamente cio' che si fa
    in ferie."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not CODICI_SCONTO_ATTIVI:
        raise HTTPException(400, "I codici sconto non sono attivi")
    d = await leggi_json(req)
    cid = int(d.get("id") or 0)

    codice = _codice_normalizza(d.get("codice"))
    if len(codice) < CODICE_SCONTO_MIN_LEN:
        raise HTTPException(400, f"Un codice sconto vuole almeno "
                                 f"{CODICE_SCONTO_MIN_LEN} caratteri fra "
                                 f"lettere e numeri: gli spazi e la "
                                 f"punteggiatura non contano.")
    try:
        percento = int(d.get("percento") or 0)
        valore = int(d.get("valore") or 0)
        usi_max = int(d.get("usi_max") or 0)
        giorni = int(d.get("giorni") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "Numeri del codice non leggibili")
    # IL TIPO (ago 2026). Assente = 'percento', ed e' il client di ieri
    # che non sa che esiste: mandava `percento` e basta, e continua a
    # creare codici a percentuale come sempre — la retrocompatibilita'
    # a costo zero, lo stesso DEFAULT della colonna.
    tipo = _tipo_codice(d.get("tipo"))
    if not tipo:
        raise HTTPException(400, "Tipo di sconto non previsto")
    valuta = _valuta_soglia(d.get("valuta")) if tipo == "valore" else ""
    if tipo == "valore" and not valuta:
        raise HTTPException(400, "Valuta non prevista per un codice sconto")
    if tipo == "percento":
        # IL PAVIMENTO AL POSTO DEL `< 1` (ago 2026, col campo libero).
        # SCESO A 1 col tetto salito a 100 (decisione di Andrea: «devo
        # poter decidere arbitrariamente quando scontare»): la riga
        # resta una cintura — a zero il codice non scontera' mai
        # niente — ma non giudica piu' se il regalo sia abbastanza
        # generoso, che e' una cosa che sa solo chi lo fa.
        if not (CODICI_SCONTO_MIN_PERCENTO <= percento
                <= CODICI_SCONTO_MAX_PERCENTO):
            raise HTTPException(400, f"Lo sconto di un codice va dal "
                                     f"{CODICI_SCONTO_MIN_PERCENTO}% al "
                                     f"{CODICI_SCONTO_MAX_PERCENTO}%.")
    else:
        # LA CIFRA FISSA, col tetto NELLA SUA UNITA': un euro e un sat
        # non si misurano con lo stesso numero, e un tetto solo
        # lascerebbe passare in una scala quel che rifiuta nell'altra.
        # IL PAVIMENTO E' 1 e non una leva: sotto c'e' solo lo zero,
        # che qui vuol dire «nessuno sconto» — cioe' il codice che il
        # libro mastro chiama «non puo' scattare».
        tetto = (CODICI_SCONTO_MAX_VALORE_SATS if valuta == "sats"
                 else CODICI_SCONTO_MAX_VALORE_EUR)
        if not (1 <= valore <= tetto):
            raise HTTPException(400, f"Lo sconto di un codice a cifra fissa "
                                     f"va da 1 a "
                                     f"{_fmt_sats(tetto)}"
                                     f"{' sats' if valuta == 'sats' else ' €'}.")
    if usi_max < 0 or usi_max > CODICI_SCONTO_MAX_USI:
        raise HTTPException(400, f"Gli usi di un codice arrivano a "
                                 f"{_fmt_sats(CODICI_SCONTO_MAX_USI)}: "
                                 f"lascia 0 per non metterci un tetto.")
    # LA SCADENZA SI DICHIARA IN GIORNI e mai come istante: il calco di
    # ORE_LAMPO_OPZIONI. Un timestamp che arriva da fuori metterebbe la
    # deriva dell'orologio del telefono dentro una promessa.
    if giorni not in CODICI_SCONTO_DURATE_GIORNI:
        raise HTTPException(400, "Durata non prevista per un codice sconto")
    scadenza = (int(time.time()) + giorni * 86400) if giorni else 0
    # CUMULABILE (ott 2026): un si'/no. ASSENTE non vale «no»: e' il
    # client di ieri, che non lo conosce — alla creazione vale il default
    # della colonna (si', come i codici gia' in giro), all'aggiornamento
    # si CONSERVA (COALESCE), il patto di `giorni` e `usi_max` qui sopra.
    cum = d.get("cumulabile")
    cum = None if cum is None else (1 if cum is True or cum == 1 else 0)

    con = db()
    if cid:
        # AGGIORNAMENTO. Proprieta' nella WHERE, mai una SELECT prima.
        # ⚠️ LA TRAPPOLA DI MSG_CLIENT_VECCHIO, ROVESCIATA: qui lo ZERO
        # e' il PERMISSIVO («mai», «illimitato»), quindi una chiave
        # assente NON puo' valere zero — un client di ieri renderebbe
        # eterno e illimitato un codice che aveva un tetto, in silenzio
        # e nella direzione che costa. Si conserva col COALESCE.
        sc = None if d.get("giorni") is None else scadenza
        um = None if d.get("usi_max") is None else usi_max
        # LE DUE COLONNE DELLA CIFRA SI CONSERVANO A VICENDA, il patto
        # delle due soglie a valore: si scrive SOLO quella dell'unita'
        # dichiarata, e l'altra resta l'ultima cifra che il venditore
        # ha battuto in quell'unita' — cosi' chi prova gli euro e torna
        # ai sats ritrova il suo numero e non una conversione che non
        # ha scelto. Sul tipo 'percento' non si tocca nessuna delle
        # due: passare a percentuale e tornare indietro non deve
        # cancellare la cifra.
        vs = valore if (tipo == "valore" and valuta == "sats") else None
        ve = valore if (tipo == "valore" and valuta == "eur") else None
        vv = valuta if tipo == "valore" else None
        try:
            n = con.execute("UPDATE codici_sconto SET codice=?, percento=?, "
                            "tipo=?, "
                            "valore_sats=COALESCE(?, valore_sats), "
                            "valore_eur=COALESCE(?, valore_eur), "
                            "valore_valuta=COALESCE(?, valore_valuta), "
                            "scadenza=COALESCE(?, scadenza), "
                            "usi_max=COALESCE(?, usi_max), "
                            "cumulabile=COALESCE(?, cumulabile) "
                            "WHERE id=? AND venditore_id=?",
                            (codice, percento, tipo, vs, ve, vv, sc, um, cum,
                             cid, user["id"])).rowcount
        except sqlite3.IntegrityError:
            con.close()
            raise HTTPException(400, "Hai già un codice che si scrive così")
        if not n:
            con.close()
            raise HTTPException(400, "Codice sconto non trovato")
    else:
        quanti = con.execute("SELECT COUNT(*) AS n FROM codici_sconto "
                             "WHERE venditore_id=?",
                             (user["id"],)).fetchone()["n"]
        if quanti >= CODICI_SCONTO_MAX_PER_VENDITORE:
            con.close()
            raise HTTPException(400, f"Hai già "
                                     f"{CODICI_SCONTO_MAX_PER_VENDITORE} "
                                     f"codici: eliminane uno per farne di "
                                     f"nuovi.")
        # L'UNICITA' LA FA LA UNIQUE, non una SELECT prima (che aprirebbe
        # una finestra fra il controllo e la scrittura): il patto di
        # xp_eventi, dove il vincolo E' il giudice.
        try:
            con.execute("INSERT INTO codici_sconto(venditore_id, codice, "
                        "percento, tipo, valore_sats, valore_eur, "
                        "valore_valuta, scadenza, usi_max, attivo, creato, "
                        "cumulabile) "
                        "VALUES(?,?,?,?,?,?,?,?,?,1,?,?)",
                        (user["id"], codice, percento, tipo,
                         valore if (tipo == "valore"
                                    and valuta == "sats") else 0,
                         valore if (tipo == "valore"
                                    and valuta == "eur") else 0,
                         valuta or "eur", scadenza, usi_max,
                         int(time.time()), 1 if cum is None else cum))
        except sqlite3.IntegrityError:
            con.close()
            raise HTTPException(400, "Hai già un codice che si scrive così")
        cid = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    con.commit()
    r = con.execute("SELECT * FROM codici_sconto WHERE id=?",
                    (cid,)).fetchone()
    usi = _usi_codice(con, cid)
    con.close()
    return {"ok": True, "codice": _codice_pubblico(r, usi, int(time.time()))}


@app.post("/api/me/codici-sconto/{codice_id}/pausa")
async def pausa_codice_sconto(codice_id: int,
                              x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """Spegne o riaccende un codice. `pausa` NON e' `elimina`: qui l'id
    resta, quindi il conteggio degli usi resta — e riaccendendo il
    tetto riparte da dov'era."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    con.execute("UPDATE codici_sconto SET attivo=1-attivo "
                "WHERE id=? AND venditore_id=?", (codice_id, user["id"]))
    con.commit()
    con.close()
    return {"ok": True}


@app.post("/api/me/codici-sconto/{codice_id}/elimina")
async def elimina_codice_sconto(codice_id: int,
                                x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """Toglie la riga. DICHIARATO: ricreare lo stesso nome da' un id
    NUOVO e un tetto FRESCO — gli ordini di prima restano legati al
    vecchio id e non contano piu'. E' la lettura onesta («un codice
    nuovo e' un codice nuovo»); il contrario esigerebbe un soft delete,
    cioe' un secondo significato per `attivo`, e «spento» smetterebbe
    di essere uno stato solo.
    Gli ordini gia' nati non si toccano: portano il NOME fotografato,
    che sopravvive alla riga — un JOIN direbbe «?»."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    con.execute("DELETE FROM codici_sconto WHERE id=? AND venditore_id=?",
                (codice_id, user["id"]))
    con.commit()
    con.close()
    return {"ok": True}


# --- L'invito del codice ai clienti (14 nov 2026) ---------------------
# La richiesta di un venditore, via Andrea: «Ho creato un codice sconto
# della durata di 30gg, mi piacerebbe mandarlo a tutti i miei clienti di
# Barattolo, ovvero chi ha gia' ordinato qualcosa da me». Il tasto
# «📣 Condividi» sulla riga del codice apre l'elenco dei clienti, tutti
# spuntati, e «Invia invito sconto» mette in coda: il messaggio lo
# recapita Barattolo con `notifica()`, sulla strada che il CLIENTE ha
# scelto (bot, DM Nostr, avviso in app).
# IL CLIENTE e' chi ha almeno un ordine PAGATO da questo negozio: uno
# stato oltre 'creato' e diverso da 'annullato' (l'ordine abbandonato
# prima di pagare non fa di nessuno un cliente). Mai se stesso, mai un
# account cancellato (il fantasma vive in [2^52, 2^53), FANTASMA_BASE).
# LA PRIVACY: il venditore non riceve MAI un tg_id, uno username o una
# npub. Ogni cliente esce col NUMERO DEL SUO ULTIMO ORDINE — che il
# venditore legge gia' nei suoi Ordini — ed e' quel numero che torna
# indietro con la scelta: il server lo ritraduce rifacendo l'elenco
# con la proprieta' nella WHERE, quindi un numero d'ordine altrui non
# porta da nessuna parte.
# CHI HA DETTO NO NON COMPARE NEMMENO: ne' il no a tutti i negozi
# (utenti.offerte_negozi) ne' quello a questo (inviti_codice_no). Una
# riga «non vuole le tue offerte» direbbe al venditore una cosa che il
# cliente ha detto a Barattolo, non a lui.
# LE CINTURE ANTI-SPAM: lo stesso codice una volta sola per cliente (la
# chiave di inviti_codice), al piu' un invito ogni
# CODICI_SCONTO_INVITI_GIORNI dallo stesso negozio, al piu'
# CODICI_SCONTO_INVITI_MAX per volta, e solo un codice che OGGI vale. Il
# server rifa' SEMPRE l'elenco da se': la scelta che arriva dal telefono
# e' un filtro, mai una fonte.

STATI_NON_CLIENTE = ("creato", "annullato")
PAUSA_INVITI = 0.3        # secondi fra due inviti: mai raffiche sul bot
LOTTO_INVITI = 50         # righe per giro della coda
_INVITI_IN_GIRO = False   # un giro solo alla volta (vedi _giro_inviti_codice)


def _leve_inviti_codice() -> dict:
    """La parte delle leve che serve al foglio «📣 Condividi»: la busta
    di /api/me e quella della lista dei codici si tengono in pari da
    qui, o il cassetto direbbe due cose secondo la strada."""
    return {"inviti": bool(CODICI_SCONTO_INVITI and CODICI_SCONTO_ATTIVI),
            "inviti_giorni": int(CODICI_SCONTO_INVITI_GIORNI or 0),
            "inviti_max": int(CODICI_SCONTO_INVITI_MAX or 0)}


def _stato_invito(gia_questo: bool, ultimo_invito: int, adesso: int) -> str:
    """PURA: se questo cliente si puo' invitare adesso. 'ok', oppure
    'gia_invitato' (questo codice gli e' gia' arrivato, o e' in coda),
    oppure 'da_poco' (un codice dello stesso negozio negli ultimi
    CODICI_SCONTO_INVITI_GIORNI). L'ordine conta: «gia' invitato» e' la
    cosa piu' definitiva, e vince. GIORNI a zero = nessuna cintura di
    tempo (la chiave della tabella resta)."""
    if gia_questo:
        return "gia_invitato"
    giorni = int(CODICI_SCONTO_INVITI_GIORNI or 0)
    if giorni > 0 and ultimo_invito and adesso - int(ultimo_invito) < giorni * 86400:
        return "da_poco"
    return "ok"


def _clienti_del_codice(con, venditore_id: int, codice_id: int, adesso: int) -> list:
    """I clienti veri di un negozio, visti dal foglio di UN codice, dal
    piu' recente. Ogni voce porta il tg_id SOLO per il server: chi la
    manda al client la spoglia (`_cliente_pubblico`)."""
    segni = ",".join("?" * len(STATI_NON_CLIENTE))
    righe = con.execute(
        "SELECT o.compratore_id AS tg_id, MAX(o.id) AS ordine, "
        "MAX(o.creato) AS ultimo, COUNT(*) AS ordini, "
        "COALESCE(u.nome,'') AS nome "
        "FROM ordini o JOIN utenti u ON u.tg_id=o.compratore_id "
        "WHERE o.venditore_id=? AND o.compratore_id<>? "
        f"AND o.stato NOT IN ({segni}) "
        "AND NOT (o.compratore_id >= ? AND o.compratore_id < ?) "
        "AND COALESCE(u.offerte_negozi, 1) <> 0 "
        "AND NOT EXISTS (SELECT 1 FROM inviti_codice_no n "
        "  WHERE n.tg_id=o.compratore_id AND n.venditore_id=o.venditore_id) "
        "GROUP BY o.compratore_id ORDER BY ultimo DESC, ordine DESC",
        (venditore_id, venditore_id, *STATI_NON_CLIENTE,
         2 ** 52, 2 ** 53)).fetchall()
    if not righe:
        return []
    gia = {int(r["tg_id"]) for r in con.execute(
        "SELECT tg_id FROM inviti_codice WHERE codice_id=?", (codice_id,))}
    # L'ULTIMO INVITO DI QUESTO NEGOZIO a ogni cliente: le righe
    # consumate senza messaggio (mandato=1) non contano, nessuno le ha
    # ricevute. Quelle in coda si' — stanno per arrivare.
    ultimi = {int(r["tg_id"]): int(r["quando"] or 0) for r in con.execute(
        "SELECT tg_id, MAX(accodato) AS quando FROM inviti_codice "
        "WHERE venditore_id=? AND mandato<>1 GROUP BY tg_id",
        (venditore_id,))}
    fuori = []
    for r in righe:
        tg = int(r["tg_id"])
        fuori.append({"tg_id": tg, "ordine": int(r["ordine"]),
                      "nome": r["nome"] or "", "ultimo": int(r["ultimo"] or 0),
                      "ordini": int(r["ordini"] or 0),
                      "stato": _stato_invito(tg in gia, ultimi.get(tg, 0), adesso),
                      "invitato_il": ultimi.get(tg, 0)})
    return fuori


def _cliente_pubblico(c: dict) -> dict:
    """Il cliente come lo legge il venditore: il nome che vede gia'
    negli Ordini, quando ha comprato l'ultima volta, quante volte, e il
    numero dell'ordine come maniglia. MAI il tg_id."""
    return {"ordine": c["ordine"], "nome": c["nome"] or "Cliente",
            "ultimo": c["ultimo"], "ordini": c["ordini"], "stato": c["stato"],
            "invitato_il": c["invitato_il"] if c["stato"] != "ok" else 0}


def _codice_vale_ora(con, r, adesso: int) -> bool:
    """Il codice vale OGGI, per lo stesso giudice della cassa."""
    return bool(_codice_vale(r["tipo"], r["percento"], r["valore_sats"],
                             r["valore_eur"], r["valore_valuta"], r["scadenza"],
                             r["usi_max"], r["attivo"], r["venditore_id"],
                             r["venditore_id"], adesso, _usi_codice(con, r["id"])))


def _cifra_codice_testo(tipo, percento, valore_sats, valore_eur, valuta) -> str:
    """PURA: «−15%», «−10 €», «−5.000 sats» — il gemello di
    `cifraCodice` del client, per il messaggio dell'invito."""
    if (_tipo_codice(tipo) or "percento") != "valore":
        return f"−{int(percento or 0)}%"
    if (_valuta_soglia(valuta) or "eur") == "sats":
        return f"−{_fmt_sats(int(valore_sats or 0))} sats"
    return f"−{_fmt_sats(int(valore_eur or 0))} €"


def _testo_invito_codice(nome: str, negozio: str, codice: str, cifra: str,
                         scadenza: int) -> str:
    """PURA: il messaggio dell'invito. Chi lo manda, il codice da
    copiare, cosa toglie, fino a quando, il negozio a un tocco — e in
    fondo come si dice basta, sempre."""
    chi = html.escape(str(nome or "")) or "Un negozio"
    testo = (f"🎟️ <b>{chi}</b> ti manda un codice sconto: hai già "
             f"comprato nel suo negozio su Barattolo.\n\n"
             f"Codice: <code>{html.escape(str(codice or ''))}</code> — "
             f"{cifra} sugli articoli\n")
    testo += (f"Valido fino al "
              f"{time.strftime('%d/%m/%Y', time.localtime(int(scadenza)))}"
              if scadenza else "Senza scadenza")
    testo += "\nScrivilo alla cassa del negozio."
    cod = re.sub(r"[^A-Za-z0-9_]", "", str(negozio or ""))
    if cod:
        testo += (f"\n\n<a href=\"{URL_PUBBLICO}/negozio/{cod}\">"
                  f"🫙 Apri il suo negozio</a>")
    testo += ("\n\n🔕 Non vuoi più offerte dai negozi? In Barattolo: "
              "Profilo → «🔔 Avvisi».")
    return testo


@app.get("/api/me/codici-sconto/{codice_id}/clienti")
async def clienti_codice_sconto(codice_id: int,
                                x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """Il foglio «📣 Condividi»: i clienti veri di chi chiede, visti da
    UN suo codice. Proprieta' nella WHERE: il codice di un altro e' un
    404, come se non esistesse."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    leve = _leve_inviti_codice()
    if not leve["inviti"]:
        raise HTTPException(409, "L'invito ai clienti è spento")
    adesso = int(time.time())
    con = db()
    try:
        r = con.execute("SELECT * FROM codici_sconto WHERE id=? AND venditore_id=?",
                        (codice_id, user["id"])).fetchone()
        if not r:
            raise HTTPException(404, "Codice sconto non trovato")
        vale = _codice_vale_ora(con, r, adesso)
        clienti = _clienti_del_codice(con, user["id"], codice_id, adesso)
    finally:
        con.close()
    return {"codice": r["codice"], "vale": vale,
            "clienti": [_cliente_pubblico(c) for c in clienti], **leve}


@app.post("/api/me/codici-sconto/{codice_id}/invita")
async def invita_codice_sconto(codice_id: int, req: Request,
                               x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """«Invia invito sconto»: il payload porta i NUMERI D'ORDINE dei
    clienti scelti ({"ordini": [...]}) e il server li incrocia con
    l'elenco che rifa' da se'. Chi non e' invitabile adesso (gia'
    invitato, invitato da poco, non cliente, numero inventato) si conta
    fra i `saltati`; oltre CODICI_SCONTO_INVITI_MAX restano i `rimasti`,
    invitabili al giro dopo. BEGIN IMMEDIATE: due «Invia» insieme su
    due codici diversi non passano entrambi la cintura dei giorni."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    leve = _leve_inviti_codice()
    if not leve["inviti"]:
        raise HTTPException(409, "L'invito ai clienti è spento")
    d = await leggi_json(req)
    grezzi = d.get("ordini")
    if not isinstance(grezzi, list) or not grezzi:
        raise HTTPException(400, "Scegli almeno un cliente")
    try:
        scelti = {int(x) for x in grezzi}
    except (TypeError, ValueError):
        raise HTTPException(400, "Clienti in formato sbagliato")
    adesso = int(time.time())
    con = db()
    try:
        con.execute("BEGIN IMMEDIATE")
        r = con.execute("SELECT * FROM codici_sconto WHERE id=? AND venditore_id=?",
                        (codice_id, user["id"])).fetchone()
        if not r:
            raise HTTPException(404, "Codice sconto non trovato")
        if not _codice_vale_ora(con, r, adesso):
            raise HTTPException(409, "Oggi questo codice non vale (scaduto, "
                                     "finito o in pausa): rianimalo con ✏️ "
                                     "prima di condividerlo.")
        clienti = _clienti_del_codice(con, user["id"], codice_id, adesso)
        buoni = [c for c in clienti if c["ordine"] in scelti and c["stato"] == "ok"]
        tetto = leve["inviti_max"]
        via = buoni[:tetto] if tetto > 0 else buoni
        accodati = 0
        for c in via:
            accodati += con.execute(
                "INSERT OR IGNORE INTO inviti_codice(codice_id, venditore_id, "
                "tg_id, accodato, mandato) VALUES(?,?,?,?,0)",
                (codice_id, user["id"], c["tg_id"], adesso)).rowcount
        con.commit()
    finally:
        con.close()
    if accodati:
        print(f"📣 Invito del codice {codice_id}: {accodati} in coda "
              f"(negozio {user['id']})", flush=True)
        try:
            asyncio.create_task(_giro_inviti_codice())
        except Exception as e:
            print(f"⚠️ Invito del codice {codice_id}: la coda partirà "
                  f"col prossimo battito ({e})", flush=True)
    return {"ok": True, "accodati": accodati,
            "saltati": len(scelti) - len(buoni),
            "rimasti": len(buoni) - len(via)}


def _scarica_inviti_codice(con, adesso: int) -> list:
    """Un lotto della coda, gia' SEGNATO come mandato prima del
    messaggio: al piu' una volta, come la coda del mercatino — un
    riavvio a meta' perde un invito, non ne raddoppia nessuno. Ogni
    riga si RIGIUDICA qui: il cliente puo' aver detto basta e il codice
    puo' essere morto (pausa, scadenza, eliminato) dopo l'«Invia».
    Torna [(tg_id, testo, riga_del_journal)]. Committa."""
    righe = con.execute(
        "SELECT i.codice_id, i.tg_id, i.venditore_id, "
        "COALESCE(u.offerte_negozi, 1) AS offerte, "
        "EXISTS(SELECT 1 FROM inviti_codice_no n WHERE n.tg_id=i.tg_id "
        "       AND n.venditore_id=i.venditore_id) AS zitto "
        "FROM inviti_codice i LEFT JOIN utenti u ON u.tg_id=i.tg_id "
        "WHERE i.mandato=0 ORDER BY i.accodato, i.codice_id, i.tg_id LIMIT ?",
        (LOTTO_INVITI,)).fetchall()
    fuori, codici, venditori = [], {}, {}
    for x in righe:
        cid, tg, vid = int(x["codice_id"]), int(x["tg_id"]), int(x["venditore_id"])
        if cid not in codici:
            c = con.execute("SELECT * FROM codici_sconto WHERE id=?", (cid,)).fetchone()
            codici[cid] = (c, bool(c) and _codice_vale_ora(con, c, adesso))
        c, vale = codici[cid]
        if not vale or not int(x["offerte"]) or x["zitto"]:
            con.execute("UPDATE inviti_codice SET mandato=1 WHERE codice_id=? "
                        "AND tg_id=? AND mandato=0", (cid, tg))
            continue
        if vid not in venditori:
            venditori[vid] = con.execute("SELECT nome, negozio FROM utenti "
                                         "WHERE tg_id=?", (vid,)).fetchone()
        v = venditori[vid]
        testo = _testo_invito_codice(
            v["nome"] if v else "", v["negozio"] if v else "", c["codice"],
            _cifra_codice_testo(c["tipo"], c["percento"], c["valore_sats"],
                                c["valore_eur"], c["valore_valuta"]),
            int(c["scadenza"] or 0))
        con.execute("UPDATE inviti_codice SET mandato=? WHERE codice_id=? "
                    "AND tg_id=? AND mandato=0", (max(adesso, 2), cid, tg))
        fuori.append((tg, testo, f"📣 Invito del codice {cid} a {tg}"))
    con.commit()
    return fuori


async def _giro_inviti_codice():
    """Svuota la coda degli inviti, un lotto alla volta, con
    PAUSA_INVITI fra due messaggi. UN GIRO SOLO ALLA VOLTA: lo chiamano
    l'«Invia» e l'orologio al minuto, e due giri insieme leggerebbero
    lo stesso lotto (la segnatura prima del messaggio lo renderebbe
    innocuo, ma il secondo giro romperebbe la pausa). A leva spenta non
    parte niente: le righe aspettano in coda, e al giro dopo si
    rigiudicano. Fail-open: ogni invio ha il suo try."""
    global _INVITI_IN_GIRO
    if _INVITI_IN_GIRO or not _leve_inviti_codice()["inviti"]:
        return
    _INVITI_IN_GIRO = True
    try:
        while True:
            con = db()
            try:
                lotto = _scarica_inviti_codice(con, int(time.time()))
            finally:
                con.close()
            if not lotto:
                break
            for tg_id, testo, riga in lotto:
                try:
                    esito = await notifica(tg_id, testo)
                    print(f"{riga}: mandato ({esito})" if esito
                          else f"{riga}: mandato", flush=True)
                except Exception as e:
                    print(f"⚠️ {riga}: SALTATO ({type(e).__name__}: {e})",
                          flush=True)
                await asyncio.sleep(PAUSA_INVITI)
    finally:
        _INVITI_IN_GIRO = False


def _offerte_negozi_di(tg_id) -> dict:
    """Per il cassetto Avvisi: l'interruttore «🎟️ Offerte dei negozi» e
    i negozi che ti hanno GIA' mandato un codice (al massimo 50, dal
    piu' recente), ognuno col suo 🔕. Il negozio esce col numero del
    suo ultimo invito come maniglia, mai col tg_id. Fail-open: un
    elenco che non si legge e' vuoto e l'interruttore resta acceso,
    che e' lo stato di serie."""
    try:
        con = db()
        try:
            u = con.execute("SELECT offerte_negozi FROM utenti WHERE tg_id=?",
                            (tg_id,)).fetchone()
            righe = con.execute(
                "SELECT MAX(i.codice_id) AS invito, MAX(i.mandato) AS quando, "
                "COALESCE(v.nome,'') AS nome, "
                "EXISTS(SELECT 1 FROM inviti_codice_no n WHERE n.tg_id=i.tg_id "
                "       AND n.venditore_id=i.venditore_id) AS zitto "
                "FROM inviti_codice i LEFT JOIN utenti v ON v.tg_id=i.venditore_id "
                "WHERE i.tg_id=? AND i.mandato>1 GROUP BY i.venditore_id "
                "ORDER BY quando DESC LIMIT 50", (tg_id,)).fetchall()
        finally:
            con.close()
    except Exception as e:
        print(f"⚠️ Offerte dei negozi di {tg_id} illeggibili ({e}): elenco vuoto")
        return {"offerte_negozi": True, "offerte_negozi_lista": []}
    attive = True if (not u or u["offerte_negozi"] is None) else bool(u["offerte_negozi"])
    return {"offerte_negozi": attive,
            "offerte_negozi_lista": [{"invito": int(r["invito"]),
                                      "nome": r["nome"] or "Un negozio",
                                      "zitto": bool(r["zitto"])} for r in righe]}


@app.post("/api/me/offerte-negozi")
async def scegli_offerte_negozi(req: Request, x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """Il NO del cliente, in due misure: {"attive": false} spegne le
    offerte di TUTTI i negozi; {"invito": <numero>, "zitto": true}
    zittisce il negozio che ha mandato quell'invito (false lo
    riaccende). NON dipende dalla leva: dire basta funziona sempre,
    anche a invito spento. Il negozio si ritrova SOLO fra gli inviti
    ricevuti da chi chiede: un numero altrui e' un 404."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    con = db()
    try:
        if "attive" in d:
            con.execute("UPDATE utenti SET offerte_negozi=? WHERE tg_id=?",
                        (1 if d.get("attive") else 0, user["id"]))
        if d.get("invito") is not None:
            try:
                invito = int(d.get("invito"))
            except (TypeError, ValueError):
                raise HTTPException(400, "Negozio in formato sbagliato")
            v = con.execute("SELECT venditore_id FROM inviti_codice "
                            "WHERE codice_id=? AND tg_id=?",
                            (invito, user["id"])).fetchone()
            if not v:
                raise HTTPException(404, "Negozio non trovato fra le tue offerte")
            if d.get("zitto"):
                con.execute("INSERT OR IGNORE INTO inviti_codice_no(tg_id, "
                            "venditore_id, creato) VALUES(?,?,?)",
                            (user["id"], v["venditore_id"], int(time.time())))
            else:
                con.execute("DELETE FROM inviti_codice_no WHERE tg_id=? AND "
                            "venditore_id=?", (user["id"], v["venditore_id"]))
        con.commit()
    finally:
        con.close()
    return {"ok": True, **_offerte_negozi_di(user["id"])}


# --- Verifica della npub con una nota pubblica -----------------------
# L'utente dimostra di POSSEDERE la npub pubblicando dal suo client una
# nota (kind 1) con un codice generato da noi. Nessuna nsec, nessuna
# firma da consegnare, MAI (regola ferrea): solo una nota pubblica, che
# dopo la verifica puo' anche cancellare senza conseguenze.
# Relay e conversione bech32->hex sono lo specchio di importa_nostr.py
# (oggi importabile, ma i gemelli restano: il server non deve dipendere
# da uno script che vive di vita propria).

# I RELAY SONO UNA LEVA (ago 2026): erano cinque elenchi scritti a
# mano che gia' divergevano fra loro, quindi puntare a un relay nuovo
# — il NOSTRO, il giorno che ci sara' — era un commit invece di una
# riga nel config del VPS. E' la regola di casa per tutto cio' che il
# VPS decide: `canale_id()`, `ONION_HOST`, le sei dei connettori.
# Il config e' il VALORE DI PARTENZA e non la verita': senza quella
# riga valgono questi di serie.
# LA LISTA DI SERIE NUOVA (15 ott 2026, cantiere «relay-di-barattolo»,
# decisione di Andrea): sei relay di sei gestori diversi, misurati in
# sola lettura (CANTIERI, «I relay di Barattolo»). Fuori damus (503 a
# ogni ora) e nostr.mom (8690 errori in tre giorni nel journal, e da
# qui la connessione sicura si chiude subito). L'ORDINE CONTA in due
# punti: il PRIMO e' il relay suggerito nel 31990 (`tag_client`), e i
# primi QUATTRO sono dove vanno i DM a chi non ha un 10050
# (`relay_dm_di`) — quindi il nostro relay sta in fondo (le buste 1059
# le firma una chiave usa-e-getta, e lui le rifiuta) e nos.lol al
# quarto posto: frena con un 429 chi gli apre piu' di una decina di
# connessioni di fila, e da qui ne apriamo una per lettura.
# LA STESSA LISTA E' IL KIND 10002 DI BARATTOLO
# (`deploy/nostr/relay-di-barattolo.mjs`): una prova le tiene uguali.
# ⚠️ IL NOME NON SI RINOMINA: `RELAYS_VERIFICA` e' letto in una dozzina di
# punti e importato da `ripubblica_tag_client.py`, che cosi' eredita
# la leva senza una riga — il patto dei nomi interni.
RELAY_DI_SERIE = [
    "wss://relay.primal.net",
    "wss://relay.nostr.net",
    "wss://nostr.oxtr.dev",
    "wss://nos.lol",
    "wss://relay.mostro.network",
    "wss://relay.barattolo.store",
]
try:
    from config import RELAY_NOSTR
    RELAYS_VERIFICA = [str(r) for r in RELAY_NOSTR if str(r).strip()]
except ImportError:
    RELAYS_VERIFICA = list(RELAY_DI_SERIE)
# quel che il config dice DAVVERO, prima del ripiego qui sotto: e' la
# lista che il recinto dell'istanza di prova guarda (vedi
# `fuori_dal_recinto`), dove vuota vuol dire nessuno
_RELAY_NOSTR_DICHIARATI = (
    [str(r) for r in RELAY_NOSTR if str(r).strip()]
    if "RELAY_NOSTR" in globals() else [])
# FAIL-SAFE VERSO IL MONDO DI IERI, e non e' pignoleria: una lista
# vuota nel config non spegnerebbe Nostr con un messaggio — farebbe
