def p2p_usdt_frase(testo: str) -> str:
    """PURA: un avviso scritto per gli euro, detto per gli USDT."""
    t = str(testo or "")
    for vecchio, nuovo in P2P_USDT_FRASI:
        t = t.replace(vecchio, nuovo)
    # e ogni «euro» rimasto («i tuoi euro»), parola intera
    return re.sub(r"\beuro\b", "USDT", t)


def p2p_usdt_ordine(con, ordine) -> bool:
    """L'ordine e' in USDT? Lo dicono i METODI del libro (`p2p_ordini`):
    in USDT ogni metodo e' una rete, «USDT (Tron)» o «USDT (Ethereum)»,
    e l'app non mescola reti e metodi dell'euro (`valeNuovoOrdineP2P`).
    Senza riga, o con la riga storta, e' l'euro di sempre."""
    try:
        r = con.execute("SELECT metodi FROM p2p_ordini WHERE ordine=?",
                        (str(ordine or ""),)).fetchone()
        metodi = json.loads((r["metodi"] if r else "") or "[]")
    except Exception:
        return False
    return (isinstance(metodi, list) and len(metodi) > 0
            and all(str(m).startswith("USDT (") for m in metodi))


# LE PAROLE DEL BOT IN FRANCHI (14 nov 2026, cantiere p2p-chf): il calco
# di `P2P_USDT_FRASI`, piu' corto, perche' il franco si paga come l'euro
# (bonifico, conto, contanti): cambiano solo i soldi. L'italiano vuole
# l'articolo giusto, e «gli euro» → «i franchi» lo da' anche dentro le
# preposizioni: «degli euro» diventa «dei franchi», «agli euro» «ai
# franchi». Per questo la riga dell'articolo viene PRIMA della parola
# nuda. `prove_p2p_chf` passa le famiglie degli avvisi di qui e vuole
# zero «euro» e zero «€» nel risultato.
P2P_CHF_FRASI = (
    ("💶", "🇨🇭"),
    ("Gli euro", "I franchi"), ("gli euro", "i franchi"),
    ("Un euro", "Un franco"), ("un euro", "un franco"),
    ("Euro inviati", "Franchi inviati"),
    ("\u00a0€", "\u00a0CHF"),
    (" €", " CHF"),
)


def p2p_chf_frase(testo: str) -> str:
    """PURA: un avviso scritto per gli euro, detto per i franchi."""
    t = str(testo or "")
    for vecchio, nuovo in P2P_CHF_FRASI:
        t = t.replace(vecchio, nuovo)
    # e ogni «euro» rimasto («i tuoi euro», «in euro»), parola intera
    t = re.sub(r"\bEURO\b", "FRANCHI", t)
    t = re.sub(r"\bEuro\b", "Franchi", t)
    return re.sub(r"\beuro\b", "franchi", t)


def p2p_chf_ordine(con, ordine) -> bool:
    """L'ordine e' in franchi? Lo dice la valuta del libro (`p2p_ordini.
    fiat`, il `f` del 38383). Senza riga, senza colonna (un banco) o mai
    letta, e' l'euro di sempre."""
    try:
        r = con.execute("SELECT fiat FROM p2p_ordini WHERE ordine=?",
                        (str(ordine or ""),)).fetchone()
    except Exception:
        return False
    try:
        return bool(r) and str(r["fiat"] or "").upper() == "CHF"
    except (IndexError, KeyError, TypeError):
        return bool(r) and str(r[0] or "").upper() == "CHF"


# LE PAROLE DEL BOT CON ETH, MONERO E USDe (16 nov 2026, cantiere
# p2p-monete-ritocchi, Andrea: «tutto deve corrispondere, perché quando
# avevamo acceso USDT nel dettaglio di un ordine diceva invia ancora euro»).
# Il calco di `P2P_USDT_FRASI`, con una differenza che conta: qui l'ordine
# resta IN EURO (la moneta e' un METODO, come Revolut), quindi la cifra
# resta in € e ci si aggiunge la moneta in cui si paga — «50,00 €» diventa
# «50,00 € in ETH» — mentre le parole dei soldi che viaggiano diventano
# la moneta: «gli euro» → «gli XMR», «Euro inviati» → «USDe inviati», il
# conto → il wallet, i bonifici → l'id della transazione. La moneta la
# dice `p2p_coin_ordine`: SOLO un ordine che si paga in una moneta sola
# (tutti i metodi suoi), perche' il server il metodo scelto da chi prende
# non lo sa; un ordine misto («SEPA, ETH») resta con le parole dell'euro.
# `prove_p2p_monete_ritocchi` passa le famiglie degli avvisi di qui e vuole
# zero «euro», «bonifico», «conto», «💶» e nessun € senza la moneta.
P2P_COIN_METODI = {
    "ETH (Ethereum)": "ETH", "XMR (Monero)": "XMR",
    "USDe (Ethereum)": "USDe", "USDe (Arbitrum)": "USDe", "USDe (Base)": "USDe",
    "USDe (BNB Chain)": "USDe", "USDe (Solana)": "USDe",
}
# ...e la FORMA dell'id della transazione su ogni rete (17 nov 2026,
# cantiere onchain-chat-sollecito): quella del giudice del telefono
# (`giudiceTxidCoinP2P`, il campo `forma` di P2P_RETI_COIN), rete per rete
P2P_COIN_FORMA = {
    "ETH (Ethereum)": "evm", "XMR (Monero)": "monero",
    "USDe (Ethereum)": "evm", "USDe (Arbitrum)": "evm", "USDe (Base)": "evm",
    "USDe (BNB Chain)": "evm", "USDe (Solana)": "solana",
}
P2P_COIN_FRASI = (
    (P2P_USDT_FRASI[0][0], P2P_USDT_FRASI[0][1]),
    (P2P_USDT_FRASI[1][0], P2P_USDT_FRASI[1][1]),
    ("sul tuo conto", "sul tuo wallet"),
    ("il tuo conto", "il tuo wallet"),
    ("Controlla il conto", "Controlla il tuo wallet"),
    ("controlla il conto", "controlla il tuo wallet"),
    ("💶", "🪙"),
)


def p2p_coin_frase(testo: str, coin: str) -> str:
    """PURA: un avviso scritto per gli euro, detto per uno scambio pagato
    in `coin` (ETH, XMR, USDe). Senza moneta torna com'era."""
    t = str(testo or "")
    c = str(coin or "")
    if not c:
        return t
    for vecchio, nuovo in P2P_COIN_FRASI:
        t = t.replace(vecchio, nuovo)
    t = t.replace("Euro inviati", c + " inviati")
    t = t.replace("Gli euro", "Gli " + c).replace("gli euro", "gli " + c)
    # la cifra resta in euro, e si dice in che cosa si paga (una volta)
    t = re.sub(r"(\d)([ \u00a0])€(?! in )", lambda m: m.group(1) + m.group(2) + "€ in " + c, t)
    # e ogni «euro» rimasto («i tuoi euro», «in euro»), parola intera
    t = re.sub(r"\bEURO\b", c.upper(), t)
    t = re.sub(r"\bEuro\b", c, t)
    return re.sub(r"\beuro\b", c, t)


# ETH, MONERO E USDe COME VALUTE (16 nov 2026, cantiere p2p-monete-valute,
# Andrea: «devono comportarsi come valute a sé stanti, esattamente come
# USDT o euro»). Il nodo non ne conosce il prezzo e il `fiat_amount` e' un
# intero, quindi un ordine in moneta viaggia come il tabacchino a prezzo
# fisso: `fa` il controvalore in euro, sats fissi, e la cifra esatta DENTRO
# OGNI METODO — «ETH (Ethereum) 0.0153», «USDe (Base) 50». I due giudici qui
# sotto la leggono; chi li usa li chiede con `globals().get`, come le
# sorelle, perche' i banchi che estraggono una funzione sola non li portano.
def _coin_pm_libro(m):
    """PURA: un metodo con la cifra della moneta → (nome, cifra col punto);
    altrimenti None. Il nome dev'essere uno di `P2P_COIN_METODI`, la cifra
    fino a nove cifre intere e sei decimali, sopra lo zero."""
    t = str(m or "").strip()
    i = t.rfind(") ")
    if i < 0:
        return None
    nome, q = t[:i + 1], t[i + 2:].strip()
    if nome not in globals().get("P2P_COIN_METODI", {}):
        return None
    intero, punto, dec = q.partition(".")
    if (not intero.isdigit() or len(intero) > 9
            or (punto and (not dec.isdigit() or len(dec) > 6))):
        return None
    return (nome, q) if float(q) > 0 else None


def _coin_ordine_libro(metodi):
    """PURA: i metodi di un ordine IN MONETA — tutti con la cifra, tutti
    della stessa moneta, tutti la stessa cifra — → (moneta, cifra come si
    legge, [nomi nudi]): «0,0153», USDe coi centesimi «50,00». Altrimenti
    None, e l'ordine resta in euro (o USDT, o franchi) come dice il `fa`."""
    pm = [_coin_pm_libro(m) for m in metodi or []]
    if not pm or None in pm:
        return None
    monete = {globals()["P2P_COIN_METODI"][n] for n, _ in pm}
    if len(monete) != 1 or len({float(q) for _, q in pm}) != 1:
        return None
    moneta, n = monete.pop(), float(pm[0][1])
    s = f"{n:,.2f}" if moneta == "USDe" else f"{n:,.6f}".rstrip("0").rstrip(".")
    return (moneta, s.replace(",", "X").replace(".", ",").replace("X", "."),
            [nome for nome, _ in pm])


def p2p_coin_ordine(con, ordine) -> str:
    """In che moneta si paga l'ordine: 'ETH', 'XMR', 'USDe', o '' (euro,
    riga che manca o storta). PRIMA la scelta di chi ha preso, nel giro in
    corso (`p2p_metodi_scelti`, 16 nov 2026, cantiere p2p-monete-scelta):
    su un ordine misto «SEPA, ETH» decide lei — ETH → 'ETH', SEPA → ''.
    Senza scelta, i METODI del libro: tutti della stessa moneta (USDe su
    piu' reti e' una moneta sola); un misto senza scelta resta in euro."""
    # il giro in corso lo dice `_parti_scambio_p2p` (coordinatore, o il
    # libro di riserva): una scelta di un giro di prima non vale. Il
    # `globals()` e' quello delle sorelle, per i banchi che non lo portano
    _parti = globals().get("_parti_scambio_p2p")
    try:
        giro = int(_parti(con, str(ordine or ""))["giro"]) if _parti else None
        sc = con.execute(
            "SELECT metodo FROM p2p_metodi_scelti WHERE ordine=? AND giro=?",
            (str(ordine or ""), giro)).fetchone() if giro is not None else None
    except Exception:
        sc = None
    # il nome senza la cifra di un ordine in moneta (16 nov 2026)
    _cp = globals().get("_coin_pm_libro")

    def nudo(m):
        c = _cp(m) if _cp else None
        return c[0] if c else str(m).strip()
    if sc:
        return P2P_COIN_METODI.get(nudo(sc[0] or ""), "")
    try:
        r = con.execute("SELECT metodi FROM p2p_ordini WHERE ordine=?",
                        (str(ordine or ""),)).fetchone()
        metodi = json.loads((r["metodi"] if r else "") or "[]")
    except Exception:
        return ""
    if not isinstance(metodi, list) or not metodi:
        return ""
    monete = {P2P_COIN_METODI.get(nudo(m)) for m in metodi}
    return monete.pop() if len(monete) == 1 and None not in monete else ""


def p2p_chf_ammesso(tg_id) -> bool:
    """CHI VEDE GLI ORDINI IN FRANCHI (14 nov 2026, cantiere p2p-chf): il
    calco di `p2p_usdt_ammesso` — la leva madre spenta e' no per
    chiunque, poi la porticina degli admin, poi il P2P per questa
    persona."""
    if not (P2P_CHF_ATTIVO and _p2p_leve()["attivo"]):
        return False
    if P2P_CHF_SOLO_ADMIN and not e_admin(tg_id):
        return False
    return bool(_p2p_per(tg_id)["attivo"])


