@app.post("/api/p2p/chat/chiama")
async def chat_chiama_p2p(req: Request, x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """«VUOLE SCRIVERTI» (20 ott 2026, punto 9 del piano, sì di Andrea):
    l'altra parte di un ordine non ha ancora nessuna chiave — non ha
    aperto Barattolo da quando c'e' la scorta — e chi vuole scriverle la
    chiama. Un avviso, uno per ordine e per persona, col tasto che porta
    DRITTO alla chat. Nel corpo `{ordine}`."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    ordine, st = _chat_p2p_chiede(d, user)
    if not _chat_chiavi_dal_server(ordine):
        raise HTTPException(400, "Richiesta non valida")
    if not st["aperta"]:
        raise HTTPException(409, f"La chat di {_chat_questo(ordine)} non e' aperta")
    if st.get("ferma"):
        raise HTTPException(409, CHAT_MERCATINO_FERMA_TESTO)
    con = db()
    try:
        p = _parti_chat(con, ordine)
    finally:
        con.close()
    lato = "compra" if int(p["compratore"]) == int(user["id"]) else "vende"
    adesso = int(time.time())
    cc = db_chat()
    try:
        # prima un lucchetto: se nel frattempo e' arrivato, non serve chiamare
        _chat_scorta_assegna(cc, ordine, st["giro"], st["altro"], adesso)
        esito = _chat_mercatino_chiamata(cc, ordine, st["giro"], user["id"], st["altro"], adesso)
    finally:
        cc.close()
    if esito != "nuova":
        return JSONResponse({"ok": True, "gia": esito == "gia", "serve": esito != "ha_chiave"},
                            headers={"Cache-Control": "no-store"})
    if FORMA_CHAT_ONCHAIN.fullmatch(ordine):
        bottone = (P2P_ONCHAIN_BOTTONE, f"{LINK_LIBRO_P2P}?scambio={ordine}&chat=1")
    else:
        bottone = (CHAT_MERCATINO_CHIAMA_BOTTONE,
                   f"{URL_PUBBLICO}/?ordine={int(ordine[1:])}&chat=1")
    try:
        e = await notifica(st["altro"], _chat_chiama_testo(ordine, lato), bottone)
    except Exception as x:
        e = f"SALTATO ({type(x).__name__}: {x})"
    j = _chat_nel_journal(ordine)
    print(f"💬 {j['etichetta']}: {'chi compra' if lato == 'compra' else 'chi vende'} vuole "
          f"scrivere {j['su']}, avvisato {st['altro']}", flush=True)
    _esiti_p2p_dice("💬", [(st["altro"], e)])
    return JSONResponse({"ok": True, "avvisato": True}, headers={"Cache-Control": "no-store"})


def _chat_p2p_allegato_posa(cc, ordine: str, giro: int, io: int, dati: bytes,
                            adesso: int) -> tuple:
    """UN ALLEGATO ENTRA NEL CASSETTO (16 ott 2026). Pura sulla
    connessione del cassetto. `dati` e' gia' cifrato dal telefono: qui
    si guarda solo quanto pesa. Torna `(200, {id, peso})` o `(codice,
    perche')`. L'id lo sceglie il server, a caso: non dice niente di chi
    l'ha mandato ne' di quando."""
    peso = len(dati or b"")
    if peso < P2P_CHAT_ALLEGATO_MIN:
        return (400, "Richiesta non valida")
    if peso > P2P_CHAT_ALLEGATO_MAX:
        return (413, "Il file è troppo grande: al massimo 20 MB")
    mie = int(cc.execute("SELECT COUNT(*) FROM allegati WHERE ordine=? AND giro=? AND da=?",
                         (ordine, giro, int(io))).fetchone()[0] or 0)
    if mie >= P2P_CHAT_ALLEGATI_PARTE:
        return (409, f"In {_chat_questo(ordine)} hai già mandato {P2P_CHAT_ALLEGATI_PARTE} file")
    peso_mio = int(cc.execute("SELECT COALESCE(SUM(peso), 0) FROM allegati WHERE ordine=? "
                              "AND giro=? AND da=?", (ordine, giro, int(io))).fetchone()[0] or 0)
    if peso_mio + peso > P2P_CHAT_PESO_PARTE:
        return (409, f"In {_chat_questo(ordine)} hai già mandato quasi "
                     f"{P2P_CHAT_PESO_PARTE // (1024 * 1024)} MB di file")
    tutto = int(cc.execute("SELECT COALESCE(SUM(peso), 0) FROM allegati").fetchone()[0] or 0)
    if tutto + peso > P2P_CHAT_ALLEGATI_CASSETTO:
        return (507, "Adesso non c'è spazio per i file: riprova più tardi")
    persona = int(cc.execute("SELECT COALESCE(SUM(peso), 0) FROM allegati WHERE da=?",
                             (int(io),)).fetchone()[0] or 0)
    if persona + peso > P2P_CHAT_PESO_PERSONA:
        return (507, "Adesso non c'è spazio per i file: riprova più tardi")
    ident = secrets.token_hex(16)
    cc.execute("INSERT INTO allegati(id, ordine, giro, da, dati, peso, quando) "
               "VALUES(?,?,?,?,?,?,?)",
               (ident, ordine, giro, int(io), sqlite3.Binary(bytes(dati)), peso, adesso))
    cc.commit()
    return (200, {"id": ident, "peso": peso})


def _avviso_cassetto_chat(tutto: int, tetto: int, gia: bool) -> tuple:
    """IL CASSETTO QUASI PIENO (16 ott 2026, richiesta di Andrea). Pura.
    Torna `(testo, avvisato)`: un testo per il gruppo degli admin la PRIMA
    volta che si passa l'80 % del tetto, e niente le volte dopo finche' non
    si torna sotto il 60 % (si riarma). Il testo dice quanto e' pieno e
    cosa guardare; i file se ne vanno da soli a scambio finito."""
    if tetto <= 0:
        return "", gia
    quota = tutto / tetto
    if gia:
        return "", quota >= P2P_CHAT_CASSETTO_RIARMO
    if quota < P2P_CHAT_CASSETTO_AVVISO:
        return "", False
    mb = lambda n: f"{n / (1024 * 1024):,.0f}".replace(",", ".")
    return (f"📎 <b>Il cassetto dei file della chat (scambi e ordini) è quasi pieno</b>: "
            f"{mb(tutto)} MB su {mb(tetto)} MB ({quota:.0%}). I file se ne vanno da "
            "soli a scambio o ordine concluso; se non scende, guarda gli scambi e gli "
            "ordini aperti e lo "
            "spazio sul VPS (PRODUZIONE, «GLI ALLEGATI»). Al pieno chi manda un "
            "file sente «Adesso non c'è spazio per i file».", True)


async def _chat_p2p_guarda_cassetto():
    """Dopo ogni file posato o rifiutato per spazio: il giudice, e se c'e'
    da dirlo l'avviso nel gruppo degli admin (argomento errori). Mai un
    errore a chi chiama."""
    try:
        cc = db_chat()
        try:
            tutto = int(cc.execute("SELECT COALESCE(SUM(peso), 0) FROM allegati").fetchone()[0] or 0)
        finally:
            cc.close()
        testo, _CASSETTO_AVVISATO["su"] = _avviso_cassetto_chat(
            tutto, P2P_CHAT_ALLEGATI_CASSETTO, _CASSETTO_AVVISATO["su"])
        if testo:
            print(f"📎 {CHAT_CASSETTO_ETICHETTA}: cassetto dei file all'80 % ({tutto} byte): avviso agli admin",
                  flush=True)
            await notifica_admin(testo, argomento="errori")
    except Exception as e:
        print(f"⚠️ {CHAT_CASSETTO_ETICHETTA}: il controllo del cassetto non e' riuscito "
              f"({type(e).__name__}: {e})", flush=True)


def _chat_p2p_allegato_prendi(cc, ordine: str, giro: int, ident: str):
    """I byte cifrati di un allegato di QUESTO scambio e di QUESTO giro, o
    None. Pura sulla connessione del cassetto."""
    if not FORMA_ALLEGATO_CHAT.fullmatch(str(ident or "")):
        return None
    r = cc.execute("SELECT dati FROM allegati WHERE id=? AND ordine=? AND giro=?",
                   (ident, ordine, int(giro))).fetchone()
    return bytes(r["dati"]) if r else None


def _risposta_allegato(dati: bytes) -> Response:
    """I byte cifrati, cosi' come sono: nessuno qui sa cosa siano."""
    return Response(content=dati, media_type="application/octet-stream",
                    headers={"Cache-Control": "no-store",
                             "Content-Disposition": "attachment; filename=allegato.bin"})


@app.post("/api/p2p/chat/allegato")
async def chat_allegato_p2p(req: Request, x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie(""),
                            x_chat_ordine: str = Header("")):
    """Il telefono consegna un allegato GIA' CIFRATO: il corpo sono i
    byte nudi (`iv || cifrato`), lo scambio sta nell'intestazione
    `X-Chat-Ordine` (mai nell'indirizzo: uvicorn lo scriverebbe). Il
    corpo si legge A PEZZI col tetto, come il cestino della CSP: un
    Content-Length che mente non cambia niente. Nel journal una riga
    col peso, e basta: il tipo il server non lo sa."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    ordine, st = _chat_p2p_chiede({"ordine": x_chat_ordine}, user)
    if not st["aperta"]:
        raise HTTPException(409, f"La chat di {_chat_questo(ordine)} non e' aperta")
    if st.get("ferma"):
        raise HTTPException(409, CHAT_MERCATINO_FERMA_TESTO)
    dati = bytearray()
    async for pezzo in req.stream():
        dati.extend(pezzo)
        if len(dati) > P2P_CHAT_ALLEGATO_MAX:
            raise HTTPException(413, "Il file è troppo grande: al massimo 20 MB")
    cc = db_chat()
    try:
        codice, esito = _chat_p2p_allegato_posa(cc, ordine, st["giro"], user["id"],
                                                dati, int(time.time()))
    finally:
        cc.close()
    # il cassetto quasi pieno: un compito a parte, chi manda non aspetta Telegram
    t = asyncio.create_task(_chat_p2p_guarda_cassetto())
    _TASK_CHAT_P2P.add(t)
    t.add_done_callback(_TASK_CHAT_P2P.discard)
    if codice != 200:
        raise HTTPException(codice, str(esito))
    j = _chat_nel_journal(ordine)
    print(f"📎 {j['etichetta']}: un allegato {j['su']}, "
          f"{max(1, esito['peso'] // 1024)} KB", flush=True)
    return JSONResponse({"ok": True, "id": esito["id"]}, headers={"Cache-Control": "no-store"})


@app.post("/api/p2p/chat/allegato/leggi")
async def chat_allegato_leggi_p2p(req: Request, x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """Una delle due parti ritira i byte cifrati di un allegato del giro
    in corso. Nel corpo `{ordine, id}`. La chiave ce l'ha il suo
    telefono, nel messaggio che l'ha portato."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    ordine, st = _chat_p2p_chiede(d, user)
    if not st["aperta"]:
        return _chat_p2p_chiusa(ordine, st)
    cc = db_chat()
    try:
        dati = _chat_p2p_allegato_prendi(cc, ordine, st["giro"], d.get("id"))
    finally:
        cc.close()
    if dati is None:
        raise HTTPException(404, "Questo file non c'è più")
    return _risposta_allegato(dati)


@app.post("/api/p2p/moderazione/chat/allegato")
async def moderazione_chat_allegato_p2p(req: Request, x_tg_init_data: str = Header(""),
                                        barattolo_sessione: str = Cookie("")):
    """SOLO IL MODERATORE CHE HA PRESO LA DISPUTA, come per le buste della
    chat: i byte cifrati di un allegato del giro della disputa. Li apre
    il suo telefono SOLO se una delle parti gli ha dato la chiave della
    chat, che porta quella del file. Nel corpo `{ordine, id}`."""
    user = _moderatore_o_403(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    ordine = str(d.get("ordine") or "").strip()
    # UN ORDINE DEL MERCATINO (16 ott 2026), o uno scambio on-chain (17
    # nov): a ordine in disputa, con la chiave di moderatore dichiarata —
    # lo stesso giudice delle buste
    if _chat_chiavi_dal_server(ordine):
        con, cc = db(), db_chat()
        try:
            codice, corpo = _chat_mercatino_per_moderatore(con, cc, user["id"], ordine)
            dati = _chat_p2p_allegato_prendi(cc, ordine, 0, d.get("id")) \
                if codice == 200 else None
        finally:
            con.close()
            cc.close()
        if codice != 200:
            raise HTTPException(codice, str(corpo))
        if dati is None:
            raise HTTPException(404, "Questo file non c'è più")
        return _risposta_allegato(dati)
    if not FORMA_ORDINE_P2P.fullmatch(ordine):
        raise HTTPException(400, "Richiesta non valida")
    con, cc = db(), db_chat()
    try:
        r = con.execute("SELECT giro, stato, presa_da FROM p2p_dispute WHERE ordine=?",
                        (ordine,)).fetchone()
        if not r:
            raise HTTPException(404, "Disputa non trovata")
        if r["stato"] != "presa" or int(r["presa_da"] or 0) != int(user["id"]):
            raise HTTPException(409, "La chat si legge dopo aver preso la disputa")
        dati = _chat_p2p_allegato_prendi(cc, ordine, int(r["giro"] or 0), d.get("id"))
    finally:
        con.close()
        cc.close()
    if dati is None:
        raise HTTPException(404, "Questo file non c'è più")
    return _risposta_allegato(dati)


@app.post("/api/p2p/chat/moderatori")
async def chat_moderatori_p2p(req: Request, x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """Le chiavi PUBBLICHE dei moderatori, per chi sta aprendo una
    disputa: e' a quelle che il suo telefono chiude la chiave di lettura
    della chat. Solo a una delle due parti di uno scambio in corso.
    Sono le chiavi gia' aggiunte al nodo come solver: non dicono niente
    di nessuno."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    ordine, st = _chat_p2p_chiede(d, user)
    if not st["aperta"]:
        return _chat_p2p_chiusa(ordine, st)
    con = db()
    try:
        chiavi = sorted({r[0] for r in con.execute("SELECT chiave FROM p2p_moderatori")
                         if FORMA_PUBKEY_P2P.fullmatch(r[0] or "")})
    finally:
        con.close()
    return JSONResponse({"ok": True, "aperta": True, "chiavi": chiavi},
                        headers={"Cache-Control": "no-store"})


def _chat_p2p_novita(con, cc, io: int, ordini, accesa: bool = True) -> dict:
    """IL PALLINO DELL'APP, E LE CHAT FINITE. Pura sulle due connessioni.
    Torna `{ultimi, finite}`.
    `ultimi`: per ognuno degli scambi nominati di cui chi chiede e' una
    parte, a chat aperta, il numero dell'ultimo MESSAGGIO dell'altra
    parte (0 = nessuno). NON SPOSTA NESSUN SEGNALIBRO e non dice «sta
    guardando»: e' la domanda dell'app aperta su un'altra pagina, e chi
    non ha aperto la chat l'avviso lo deve ricevere lo stesso. Uno
    scambio di cui chi chiede non e' una parte non compare, e basta. A
    leva spenta (`accesa` falso) e' vuoto.
    `finite` (12 ott 2026, notte, richiesta di Andrea): gli scambi
    nominati che per chi chiede sono FINITI — una sua parte, e lo
    scambio non e' piu' in corso — o che il server non conosce piu'. E'
    L'UNICA COSA CHE FA BUTTARE AL TELEFONO UNA CHIAVE: lo stato della
    riga sul telefono non conta, perche' una riga che manca per un
    attimo costerebbe una chat. Non guarda la leva: uno scambio finito
    e' finito anche a chat spenta."""
    ultimi, finite = {}, []
    for o in ordini:
        st = _chat_p2p_stato(con, o, io)
        if st["aperta"]:
            if accesa:
                r = cc.execute("SELECT MAX(n) FROM buste WHERE ordine=? AND giro=? "
                               "AND tipo='msg' AND da<>?",
                               (o, st["giro"], int(io))).fetchone()
                ultimi[o] = int((r and r[0]) or 0)
        elif st["perche"] == "finito" or not st["noto"]:
            finite.append(o)
    return {"ultimi": ultimi, "finite": finite}


@app.post("/api/p2p/chat/novita")
async def chat_novita_p2p(req: Request, x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """Il pallino dei messaggi non letti, e le chat finite. Nel corpo
    `{ordini: [...]}`, gli scambi che il telefono ha (quelli vivi e
    quelli di cui tiene ancora una chiave); risponde `{ultimi: {ordine:
    n}, finite: [ordine]}`. Il telefono confronta `ultimi` con l'ultimo
    messaggio che ha APERTO, e butta chiave e messaggi dei `finite`.
    Non segna niente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    attivo = _p2p_per(user["id"])["attivo"]
    d = await leggi_json(req)
    ordini = d.get("ordini")
    # GLI ORDINI DEL MERCATINO (16 ott 2026) stanno nella stessa domanda,
    # con la loro leva, e non chiedono il P2P attivo: a P2P spento la
    # domanda resta un 409 solo se di ordini del mercatino non ne porta
    merc = [o for o in ordini if isinstance(o, str) and FORMA_CHAT_MERCATINO.fullmatch(o)] \
        if isinstance(ordini, list) else []
    if not attivo and not merc:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    if not isinstance(ordini, list) or len(ordini) > P2P_CHAT_NOVITA_MAX \
            or not all(isinstance(o, str) and (FORMA_ORDINE_P2P.fullmatch(o)
                                               or FORMA_CHAT_MERCATINO.fullmatch(o))
                       for o in ordini):
        raise HTTPException(400, "Richiesta non valida")
    scambi = [o for o in ordini if o not in merc] if attivo else []
    corpo = {"ultimi": {}, "finite": []}
    if scambi or merc:
        con, cc = db(), db_chat()
        try:
            for quali, accesa in ((scambi, bool(P2P_CHAT_SCAMBIO)),
                                  (merc, bool(MERCATINO_CHAT_ORDINI))):
                if quali:
                    pezzo = _chat_p2p_novita(con, cc, user["id"], quali, accesa)
                    corpo["ultimi"].update(pezzo["ultimi"])
                    corpo["finite"] += pezzo["finite"]
        finally:
            con.close()
            cc.close()
    return JSONResponse({"ok": True, "spenta": not P2P_CHAT_SCAMBIO,
                         "spenta_mercatino": not MERCATINO_CHAT_ORDINI,
                         "ultimi": corpo["ultimi"], "finite": corpo["finite"]},
                        headers={"Cache-Control": "no-store"})


def _chat_p2p_per_moderatore(con, cc, io: int, ordine: str) -> tuple:
    """LA CHAT DELLE DUE PARTI, PER IL MODERATORE CHE HA PRESO LA
    DISPUTA. Pura sulle due connessioni. Torna `(200, corpo)` o
    `(codice, perche')`. Solo a disputa PRESA e solo a chi l'ha presa:
    le buste dei messaggi (chiuse: le apre il suo telefono, se una delle
    parti gli ha dato la chiave) e le buste `mod` chiuse per la SUA
    chiave. `lato` dice chi ha spedito ('compra' | 'vende'). Non sposta
    nessun segnalibro: il moderatore che legge non e' una parte che ha
    ritirato.
    Un ordine del mercatino (`m<numero>`, 16 ott 2026) ha il suo giudice:
    `_chat_mercatino_per_moderatore`."""
    if _chat_chiavi_dal_server(ordine):
        return _chat_mercatino_per_moderatore(con, cc, io, ordine)
    if not FORMA_ORDINE_P2P.fullmatch(ordine):
        return (400, "Richiesta non valida")
    r = con.execute("SELECT giro, compratore, venditore, stato, presa_da, "
                    "chiave_moderatore FROM p2p_dispute WHERE ordine=?",
                    (ordine,)).fetchone()
    if not r:
        return (404, "Disputa non trovata")
    if r["stato"] != "presa" or int(r["presa_da"] or 0) != int(io):
        return (409, "La chat si legge dopo aver preso la disputa")
    giro = int(r["giro"] or 0)
    lato = lambda da: ("compra" if int(da) == int(r["compratore"] or 0) else
                       "vende" if int(da) == int(r["venditore"] or 0) else "")
    buste = [{"n": int(b["n"]), "lato": lato(b["da"]), "busta": b["busta"],
              "quando": int(b["quando"])} for b in cc.execute(
        "SELECT n, da, busta, quando FROM buste WHERE ordine=? AND giro=? "
        "AND tipo='msg' ORDER BY n", (ordine, giro))]
    chiavi = [{"n": int(b["n"]), "lato": lato(b["da"]), "busta": b["busta"]}
              for b in cc.execute(
        "SELECT n, da, busta FROM buste WHERE ordine=? AND giro=? AND tipo='mod' "
        "AND per=? ORDER BY n", (ordine, giro, r["chiave_moderatore"] or ""))]
    return (200, {"ok": True, "buste": buste, "chiavi": chiavi})


@app.post("/api/p2p/moderazione/chat")
async def moderazione_chat_p2p(req: Request, x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """SOLO IL MODERATORE CHE HA PRESO LA DISPUTA: le buste della chat
    fra le due parti, e la chiave di lettura che una di loro gli ha
    chiuso aprendo la disputa. Nel corpo `{ordine}`."""
    user = _moderatore_o_403(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    con, cc = db(), db_chat()
    try:
        codice, corpo = _chat_p2p_per_moderatore(
            con, cc, user["id"], str(d.get("ordine") or "").strip())
    finally:
        con.close()
        cc.close()
    return _risposta_moderazione(codice, corpo)


class _ChatFuoriDalJournal(logging.Filter):
    """GLI ACCESSI RIUSCITI DELLA CHAT NON VANNO NEL JOURNAL: una riga
    per busta spedita e una ogni pochi secondi per chi la tiene aperta
    direbbero, a chat cancellata, chi scriveva a chi e a che ora — e il
    journal resta. Le righe degli ERRORI (dal 400 in su) restano: un
    guasto si deve poter leggere. Non alza mai: e' un filtro sul
    registro di tutti."""

    def filter(self, record):
        try:
            a = record.args
            if isinstance(a, tuple) and len(a) >= 5 and isinstance(a[2], str) \
                    and (a[2].startswith("/api/p2p/chat/")
                         or a[2].startswith("/api/p2p/moderazione/chat")) \
                    and int(a[4]) < 400:
                return False
        except Exception:
            pass
        return True


logging.getLogger("uvicorn.access").addFilter(_ChatFuoriDalJournal())


# ═══ IL CONTROLLO DELLA FATTURA PRIMA DEL COORDINATORE (10 ott 2026,
# cantiere controllo-fattura, richiesta di Andrea) ═══════════════════
# IL PERCHE': il 10 ott 2026 un payout P2P da 180.917 sats e' fallito
# tre volte con NO_ROUTE e ZERO tentativi HTLC. La fattura di chi
# comprava veniva da un nodo che nel grafo pubblico non esiste («unable
# to find node») e non portava route hints: impagabile da chiunque, non
# solo da noi — e lo si e' saputo solo alla fine dello scambio, con la
# garanzia gia' incassata. Da oggi la fattura (o la Lightning address)
# si guarda APPENA la si inserisce, PRIMA che parta verso il
# coordinatore: sia alla presa sia quando il coordinatore chiede una
# fattura nuova (`add-invoice` dopo i payout falliti), che nel client
# passano dallo stesso foglio e dalla stessa rotta (`/api/p2p/fattura`).
# DUE GRADI DI GIUDIZIO (decisione di Andrea, 10 ott 2026):
#   • CERTO, e si ferma (`FATTURA_FERMA`): importo diverso da quello
#     dovuto, fattura scaduta o piu' corta della finestra del
#     coordinatore, rete sbagliata, nodo ASSENTE dal grafo senza route
#     hints, indirizzo Phoenix (BIP-353) o con un dominio che non c'e'.
#   • PROBABILE, e si avvisa forte lasciando un «Usa comunque questa
#     fattura» (`FATTURA_AVVISA`): nessuna strada trovata con il nodo
#     presente nel grafo, costo di rete oltre il tetto del coordinatore.
# E IL CONTROLLO NON FERMA MAI GLI SCAMBI quando non si puo' fare: LND
# muto, macaroon senza il permesso (`getnodeinfo` e `queryroutes`
# vogliono `info:read`, e quello di lettura del set 2026 ha solo
# `offchain:read` — verificato sul sorgente di LND, `rpcserver.go`),
# ponte spento, wallet dell'indirizzo che non risponde: la fattura
# passa e nel journal resta l'avviso. Il controllo deve AIUTARE: un
# «non lo so» non e' un «no».
# NEL JOURNAL una riga per controllo, con l'esito e MAI la fattura
# intera: la destinazione accorciata basta a riconoscerla, e una bolt11
# in un log e' una riga che qualcuno un giorno copia.
# COSA SI CHIEDE A LND, sullo stesso ponte di `_chiedi_lnd`:
#   1) `GET /v1/payreq/{bolt11}` (DecodePayReq, `offchain:read`): la
#      destinazione, i route hints, l'importo — e la firma la verifica
#      LND, che il nostro lettore guarda solo il checksum;
#   2) senza route hints, `GET /v1/graph/node/{dest}` (GetNodeInfo,
#      `info:read`): «unable to find node» = il nodo non e' nel grafo,
#      e senza indicazioni di strada e' il caso CERTO di oggi;
#   3) `POST /v1/graph/routes/{dest}/{sats}` (QueryRoutes, `info:read`)
#      coi route hints nel corpo e SENZA fee_limit (LND cerca la piu'
#      economica fino al 100%): se non c'e' strada e' un avviso, se la
#      piu' economica costa piu' di `sats × P2P_TETTO_ROTTA` il
#      coordinatore, che ha quel tetto, non la pagherebbe — avviso.
#   4) LA STRADA A PEZZI (16 ott 2026, cantiere strada-phoenix): una
#      fattura Phoenix da 270.030 sats prendeva «non trova una strada»,
#      e la strada c'era. QueryRoutes cerca UNA strada con la cifra
#      INTERA, e se nessun nostro canale da solo la regge risponde
#      «unable to find a path» (LND 0.19.3, `routing/pathfind.go`: «may
#      still be possible to complete the payment by splitting»); il
#      payout vero di Mostro la divide fino a 16 pezzi (non passa
#      `max_parts`) quando la fattura dichiara MPP. Allora, se la cifra
#      intera non passa, si chiede la strada per il PEZZO piu' piccolo
#      che LND proverebbe (`_pezzo_lnd`): se non passa nemmeno quello
#      la strada manca davvero. Se passa e la fattura si divide (bit 16
#      o 17 nei `features` della decodifica), il costo si stima in
#      proporzione e si guarda che l'uscita UTILIZZABILE dei canali in
#      linea (`GET /v1/channels`, `offchain:read`: saldo meno riserva,
#      ognuno entro il suo tetto degli appesi) copra cifra + rete; se
#      non la copre e' un fatto NOSTRO e non del wallet — e la garanzia
#      incassata rimette i sats prima del payout — quindi nessun avviso,
#      solo la riga nel journal (`uscita_corta`). Se passa e la fattura
#      NON si divide, va pagata intera: `pezzo_solo`, avviso. Nessuna
#      sonda, nessun pagamento: solo domande al grafo.
# IL TETTO e' `max_routing_fee` del settings.toml del nodo (0.01 dal
# 17 set 2026, confermato da Andrea il 10 ott): il config del VPS lo
# SPECCHIA, non lo legge — se cambia la', va cambiato qui.
try:
    from config import P2P_TETTO_ROTTA
except ImportError:
    P2P_TETTO_ROTTA = 0.01
# I WALLET IL CUI INDIRIZZO NON PASSA (10 ott 2026, cantiere
# indirizzo-non-verificato). La Lightning address parte verso il
# coordinatore COSI' COM'E', e lui la verifica PER CONTO SUO, da dietro
# Tor (`ln_exists` di Mostro): certi servizi a lui non rispondono, e al
# nostro server — che esce in chiaro — si'. Su quegli indirizzi il
# nostro «ok» non vale niente: chi li manda si prende `invalid-invoice`
# DOPO l'invio (l'ordine 44c46ddf, un indirizzo @sbpc.ch: quattro «ok»
# nostri e quattro «no» suoi in un minuto). Quelli che si SANNO si
# dicono PRIMA, e fermano: dominio (minuscolo, esatto) -> il nome da
# dire. La FATTURA di quei wallet passa: non passa solo l'indirizzo.
# Sta nel config perche' l'elenco cresce dal campo, senza un deploy;
# una leva scritta male vale «nessuno» e non ferma l'avvio.
try:
    from config import P2P_INDIRIZZI_NON_PASSANO
except ImportError:
    P2P_INDIRIZZI_NON_PASSANO = {"walletofsatoshi.com": "Wallet of Satoshi"}
P2P_INDIRIZZI_NON_PASSANO = {
    str(k).strip().lower(): str(v).strip()
    for k, v in (P2P_INDIRIZZI_NON_PASSANO.items()
                 if isinstance(P2P_INDIRIZZI_NON_PASSANO, dict) else ())
    if str(k).strip() and str(v).strip()}
LND_FATTURA_ATTESA_S = 8          # per domanda: cinque al massimo, e il client ne aspetta 40
# il pezzo piu' piccolo che LND prova quando divide (`DefaultShardMinAmt`,
