_controlli_fattura = {}   # tg_id → [secondi di ogni controllo nell'ultima ora]


async def _lnd_rest(metodo: str, percorso: str, corpo: dict | None = None,
                    cosa: str = "") -> tuple[str, dict]:
    """Una domanda REST a LND attraverso lo stesso ponte, lo stesso TLS
    guardato e lo stesso macaroon di `_chiedi_lnd`. Torna (stato,
    risposta): 'ok' col JSON; `negato` se il macaroon non ha il
    permesso (un guasto di CONFIGURAZIONE, e il journal lo dice con
    quella parola); 'errore' col `message` di LND, che e' il «no» di
    una domanda arrivata («unable to find node», «unable to find a
    path to destination»); `muto` se non risponde; `spento` senza
    macaroon. NON ALZA MAI, e nel journal del guasto mette il TIPO e
    `cosa` — mai il percorso, che su `payreq` porta la fattura intera."""
    if not _lnd_configurato():
        return LND_SPENTO, {}
    try:
        tls = ssl.create_default_context(cafile=LND_PONTE_CERT)
        async with httpx.AsyncClient(timeout=LND_FATTURA_ATTESA_S,
                                     verify=tls) as c:
            r = await c.request(
                metodo, f"{LND_PONTE_URL}{percorso}", json=corpo,
                headers={"Grpc-Metadata-macaroon":
                         str(LND_PONTE_MACAROON_LETTURA).strip()})
    except Exception as e:
        print(f"⚡ LND non ha risposto su {cosa or 'una domanda'} "
              f"({type(e).__name__})", flush=True)
        return LND_MUTO, {}
    try:
        d = r.json()
    except ValueError:
        d = {}
    if not isinstance(d, dict):
        d = {}
    err = d.get("error")
    msg = str((err.get("message") if isinstance(err, dict) else err)
              or d.get("message") or "")
    if "permission denied" in msg.lower():
        return LND_NEGATO, {"message": msg}
    if r.status_code == 200 and not err:
        return "ok", d
    return "errore", {"message": msg, "status": r.status_code}


def _controllo_locale_fattura_p2p(bolt11: str, deve: int, finestra: int,
                                  adesso: int) -> dict:
    """Quel che di una bolt11 si giudica SENZA rete, e che il
    coordinatore rifiuterebbe di sicuro: la forma, la rete, l'importo
    (uguale a `deve`, la cifra che lui pretende — a cifra ignota non si
    sbarra la strada, come nel client), la scadenza (gia' passata, o
    sotto la finestra che il coordinatore esige all'arrivo). PURA.
    Torna {'esito', 'messaggio'} piu' `sats` e `scade` se passa."""
    letta = leggi_bolt11(bolt11)
    sats = importo_bolt11(bolt11)
    if letta is None or sats is None:
        return {"esito": "illeggibile",
                "messaggio": "Questa richiesta di pagamento non si legge: "
                             "controlla di averla copiata tutta."}
    rete = rete_bolt11(bolt11)
    if rete != "bc":
        nome = {"tb": "testnet", "tbs": "signet", "bcrt": "regtest"}.get(
            rete, "di prova")
        return {"esito": "rete",
                "messaggio": f"Questa fattura è della rete {nome}, non di "
                             "Bitcoin: qui si pagano solo fatture della rete "
                             "vera. Generane una dal wallet che usi davvero."}
    if sats > 0 and deve > 0 and sats != deve:
        return {"esito": "importo",
                "messaggio": f"La richiesta è di {_fmt_sats(sats)} sats, ma "
                             f"ne devi ricevere {_fmt_sats(deve)}. Rifalla "
                             "dell'importo esatto, oppure lascia l'importo "
                             "libero."}
    if letta["scade"] <= adesso:
        return {"esito": "scaduta",
                "messaggio": "Questa richiesta è già scaduta. Rifanne una "
                             "nuova. " + MSG_SCADENZA_LUNGA}
    if letta["scade"] < adesso + finestra:
        resta = max(1, (letta["scade"] - adesso) // 60)
        return {"esito": "corta",
                "messaggio": f"Questa richiesta scade fra {resta} minuti, e "
                             "viene accettata solo se vale ancora più di "
                             f"{-(-finestra // 60)} minuti quando arriva. "
                             + MSG_SCADENZA_LUNGA}
    return {"esito": "ok", "messaggio": "", "sats": sats,
            "scade": letta["scade"]}


def _fee_rotta_msat(rotte: dict) -> int | None:
    """La commissione della strada piu' economica di una risposta di
    QueryRoutes, in msat; None se le strade non ci sono. PURA: un
    numero scritto storto vale zero, come prima del 16 ott."""
    vie = rotte.get("routes") or []
    if not vie:
        return None
    v0 = vie[0] if isinstance(vie[0], dict) else {}
    try:
        if v0.get("total_fees_msat") is not None:
            return int(v0["total_fees_msat"])
        return int(v0.get("total_fees") or 0) * 1000
    except (TypeError, ValueError):
        return 0


def _pezzo_lnd(importo: int) -> int:
    """Il pezzo piu' piccolo che LND prova quando divide un pagamento:
    dimezza finche' il pezzo resta sopra `LND_PEZZO_MIN_SATS` e i pezzi
    non passano `LND_PEZZI_MAX`. Una cifra che non si dimezza torna
    intera. PURA."""
    pezzo, pezzi = int(importo), 1
    while pezzi * 2 <= LND_PEZZI_MAX and pezzo // 2 >= LND_PEZZO_MIN_SATS:
        pezzo, pezzi = -(-pezzo // 2), pezzi * 2
    return pezzo


def _fattura_si_divide(dec: dict) -> bool:
    """La fattura accetta un pagamento a pezzi (MPP, bit 16 o 17 nei
    `features` di DecodePayReq)? PURA."""
    f = dec.get("features")
    return isinstance(f, dict) and any(str(b) in f for b in (16, 17))


def _uscita_utilizzabile(canali: list) -> int:
    """Quanti sats possono USCIRE adesso dai canali in linea, sommati:
    per ognuno il saldo meno la riserva (`_sats_canale`), e non oltre il
    suo tetto degli appesi — il piu' piccolo dei due
    `max_pending_amt_msat`, meno gli HTLC gia' in USCITA. Un canale
    senza tetti conta col solo saldo. PURA: un canale scritto storto
    vale zero."""
    somma = 0
    for c in canali:
        if not isinstance(c, dict) or not c.get("active"):
            continue
        esce = _sats_canale(c, "local")
        try:
            tetti = [int((c.get(lato + "_constraints") or {})
                         .get("max_pending_amt_msat") or 0) // 1000
                     for lato in ("local", "remote")]
            appesi = sum(int(h.get("amount") or 0)
                         for h in c.get("pending_htlcs") or []
                         if not h.get("incoming"))
        except (TypeError, ValueError, AttributeError):
            continue
        tetti = [t for t in tetti if t > 0]
        if tetti:
            esce = min(esce, max(0, min(tetti) - appesi))
        somma += esce
    return somma


async def _controllo_rete_fattura_p2p(bolt11: str, sats: int,
                                      chiedi=None) -> dict:
    """LA RAGGIUNGIBILITA', chiesta al nostro LND (i tre passi del
    cappello di questa sezione). `sats` e' la cifra che il coordinatore
    paghera' — quella della fattura, o quella dovuta se la fattura e'
    senza importo. `chiedi` e' `_lnd_rest` o il suo cartone nelle prove.
    Torna {'esito', 'messaggio', 'dest', 'fee', 'tetto', 'perche'}:
    `non_disponibile` ogni volta che LND non sa rispondere, col perche'
    per il journal."""
    chiedi = chiedi or _lnd_rest
    stato, dec = await chiedi("GET", f"/v1/payreq/{bolt11}", None, "payreq")
    if stato != "ok":
        return {"esito": FATTURA_NON_DISPONIBILE,
                "perche": f"decodifica {stato}" + (
                    f" ({dec['message']})" if dec.get("message") else "")}
    dest = str(dec.get("destination") or "").lower()
    hints = dec.get("route_hints") or []
    if not re.fullmatch(r"[0-9a-f]{66}", dest):
        return {"esito": FATTURA_NON_DISPONIBILE,
                "perche": "decodifica senza destinazione"}
    try:
        importo = int(sats) or int(dec.get("num_satoshis") or 0)
    except (TypeError, ValueError):
        importo = 0
    if not hints:
        stato, nodo = await chiedi("GET", f"/v1/graph/node/{dest}", None,
                                   "nodo")
        if stato == "errore" and "unable to find node" in str(
                nodo.get("message") or "").lower():
            return {"esito": "nodo_assente", "dest": dest,
                    "messaggio": MSG_NODO_ASSENTE}
        if stato != "ok":
            return {"esito": FATTURA_NON_DISPONIBILE, "dest": dest,
                    "perche": f"nodo {stato}" + (
                        f" ({nodo['message']})" if nodo.get("message")
                        else "")}
    if importo <= 0:
        return {"esito": "ok", "dest": dest,
                "perche": "senza importo e cifra ignota: la strada non si prova"}
    tetto = int(importo * P2P_TETTO_ROTTA)
    senza_strada = {"esito": "senza_strada", "dest": dest,
                    "messaggio": MSG_SENZA_STRADA}

    def troppo_cara(fee):
        return {"esito": "costo", "dest": dest, "fee": fee, "tetto": tetto,
                "messaggio": f"Arrivare a questa fattura costa almeno "
                             f"{_fmt_sats(fee)} sats di rete, più del "
                             f"tetto di {_fmt_sats(tetto)} sats ammesso "
                             "per lo scambio: il pagamento molto "
                             "probabilmente fallirebbe. "
                             + MEGLIO_ALTRI_WALLET}

    async def strada(cifra, cosa):
        """(stato, fee in msat) di QueryRoutes: 'ok', 'nessuna' (la
        risposta di LND quando la strada non c'e'), o un «non so»."""
        stato, rotte = await chiedi(
            "POST", f"/v1/graph/routes/{dest}/{cifra}",
            {"route_hints": hints}, cosa)
        if stato == "ok":
            fee = _fee_rotta_msat(rotte)
            return ("nessuna", None) if fee is None else ("ok", fee)
        m = str(rotte.get("message") or "").lower()
        if stato == "errore" and ("unable to find a path" in m
                                  or "no path" in m
                                  or "unable to find node" in m):
            return "nessuna", None
        return f"{cosa} {stato}" + (
            f" ({rotte['message']})" if rotte.get("message") else ""), None

    esito, fee_msat = await strada(importo, "rotte")
    if esito == "ok":
        fee = (fee_msat + 999) // 1000
        if fee > tetto:
            return troppo_cara(fee)
        return {"esito": "ok", "dest": dest, "fee": fee, "tetto": tetto}
    if esito != "nessuna":
        return {"esito": FATTURA_NON_DISPONIBILE, "dest": dest,
                "perche": esito}
    # 4) la cifra intera non passa da UN canale: si prova il pezzo
    pezzo = _pezzo_lnd(importo)
    if pezzo >= importo:
        return senza_strada
    esito, fee_msat = await strada(pezzo, "pezzo")
    if esito == "nessuna":
        return senza_strada
    if esito != "ok":
        return {"esito": FATTURA_NON_DISPONIBILE, "dest": dest,
                "perche": esito}
    if not _fattura_si_divide(dec):
        return {"esito": "pezzo_solo", "dest": dest,
                "messaggio": MSG_PEZZO_SOLO}
    # il costo dei pezzi, in proporzione: per eccesso, come la cifra intera
    fee = -(-fee_msat * importo // (pezzo * 1000))
    if fee > tetto:
        return troppo_cara(fee)
    a_pezzi = {"dest": dest, "fee": fee, "tetto": tetto}
    stato, canali = await chiedi("GET", "/v1/channels?active_only=true",
                                 None, "canali")
    if stato != "ok":
        return {"esito": "ok", **a_pezzi,
                "perche": f"a pezzi da {_fmt_sats(pezzo)}, uscita non "
                          f"letta (canali {stato})"}
    uscita = _uscita_utilizzabile(canali.get("channels") or [])
    if uscita < importo + fee:
        return {"esito": FATTURA_USCITA_CORTA, **a_pezzi,
                "perche": f"a pezzi da {_fmt_sats(pezzo)} la strada c'e', "
                          f"ma l'uscita utilizzabile ({_fmt_sats(uscita)}) "
                          f"non copre cifra + rete "
                          f"({_fmt_sats(importo + fee)})"}
    return {"esito": "ok", **a_pezzi,
            "perche": f"a pezzi da {_fmt_sats(pezzo)}, uscita "
                      f"{_fmt_sats(uscita)}"}


async def _controllo_indirizzo_p2p(indirizzo: str, deve: int, chiedi=None,
                                   risolvi=None, diagnosi=None) -> dict:
    """La Lightning address: la forma (LUD-16), Phoenix (BIP-353: parla
    un'altra lingua, e il coordinatore come il nostro nodo non la sa
    pagare), poi si chiede al suo wallet una fattura di `deve` sats
    con `invoice_da_ln_address` — la stessa strada degli incassi del
    mercatino, con la guardia anti-SSRF del 1 ott — e la si giudica
    come una fattura incollata, sulla sola rete: la scadenza non conta,
    perche' QUELLA fattura non parte da nessuna parte (il coordinatore
    all'add-invoice se ne fa una sua). Dominio inesistente = certo e
    si ferma (quasi sempre un refuso); wallet muto = non si sa.
    ⚠️ UN «OK» DI QUI NON E' IL «SI'» DEL COORDINATORE (10 ott 2026):
    noi risolviamo l'indirizzo dalla rete aperta, lui lo verifica per
    conto suo da dietro Tor. I wallet che a lui non rispondono stanno
    in `P2P_INDIRIZZI_NON_PASSANO`, e fermano prima (`wallet_non_passa`)."""
    risolvi = risolvi or invoice_da_ln_address
    diagnosi = diagnosi or diagnosi_ln_address
    nome, _, dominio = str(indirizzo or "").strip().lower().partition("@")
    if not nome or not FORMA_LN_NOME.fullmatch(nome) \
            or not FORMA_LN_DOMINIO.fullmatch(dominio):
        return {"esito": "indirizzo", "tramite": "indirizzo",
                "messaggio": "Non sembra un indirizzo Lightning: la forma è "
                             "nome@dominio, come mario@walletofsatoshi.com."}
    if dominio in DOMINI_BIP353:
        return {"esito": "indirizzo", "tramite": "indirizzo",
                "messaggio": "Questo è un indirizzo Phoenix (BIP-353), che "
                             "parla un'altra lingua, e qui non si sa pagare. "
                             "Non hai sbagliato a scriverlo — usa "
                             "l'indirizzo di un altro wallet (Blink, Alby) "
                             "o incolla una fattura."}
    # il wallet che si SA che non passa: si dice senza bussare a nessuno,
    # e prima della cifra (vale anche a cifra ignota). Nel journal il
    # dominio lo posa il giudice unico, come per ogni indirizzo
    if dominio in P2P_INDIRIZZI_NON_PASSANO:
        return {"esito": "wallet_non_passa", "tramite": "indirizzo",
                "messaggio": MSG_WALLET_NON_PASSA.format(
                    nome=P2P_INDIRIZZI_NON_PASSANO[dominio])}
    if deve <= 0:
        return {"esito": FATTURA_NON_DISPONIBILE, "tramite": "indirizzo",
                "perche": "cifra ignota: l'indirizzo non si prova"}
    pr = await risolvi(indirizzo.strip().lower(), deve)
    if not pr:
        d = await asyncio.to_thread(diagnosi, dominio)
        if d == "inesistente":
            return {"esito": "indirizzo", "tramite": "indirizzo",
                    "messaggio": f"Il dominio di questo indirizzo "
                                 f"({dominio}) non esiste: controlla di "
                                 "averlo scritto giusto."}
        return {"esito": FATTURA_NON_DISPONIBILE, "tramite": "indirizzo",
                "perche": f"il wallet dell'indirizzo non ha dato una fattura ({d})"}
    v = await _controllo_rete_fattura_p2p(str(pr).strip().lower(), deve,
                                          chiedi)
    v["tramite"] = "indirizzo"
    if v["esito"] in MSG_INDIRIZZO:
        v["messaggio"] = MSG_INDIRIZZO[v["esito"]]
    return v


async def controlla_fattura_p2p(testo: str, deve: int, finestra: int,
                                adesso: int | None = None, chiedi=None,
                                risolvi=None, diagnosi=None) -> dict:
    """IL GIUDICE UNICO di quel che chi compra mette nel foglio «Dove
    vuoi ricevere i sats»: una bolt11 (prima il locale, poi la rete) o
    una Lightning address. `deve` e' la cifra che il coordinatore ha
    detto (0 = ignota), `finestra` la sua `invoice_expiration_window`.
    Torna il dizionario del giudice che ha deciso, con `tramite`."""
    adesso = int(time.time()) if adesso is None else int(adesso)
    testo = str(testo or "").strip()
    if re.fullmatch(r"ln[a-z0-9]+", testo, re.I):
        v = _controllo_locale_fattura_p2p(testo.lower(), deve, finestra,
                                          adesso)
        v["tramite"] = "fattura"
        if v["esito"] != "ok":
            return v
        r = await _controllo_rete_fattura_p2p(testo.lower(),
                                              v["sats"] or deve, chiedi)
        r["tramite"] = "fattura"
        r.setdefault("sats", v["sats"])
        return r
    if "@" in testo:
        v = await _controllo_indirizzo_p2p(testo, deve, chiedi, risolvi,
                                           diagnosi)
        # IL DOMINIO VA NEL JOURNAL A OGNI CONTROLLO DI UN INDIRIZZO (10
        # ott 2026, richiesta di Andrea): i wallet che il coordinatore
        # rifiuta si trovano con un grep, accanto al nostro «ok» — che
        # su un indirizzo non e' il suo «si'». Il SOLO dominio, e solo
        # se ha la forma di un dominio: il nome prima della chiocciola
        # e' di una persona, e nel journal non entra.
        dominio = testo.lower().rpartition("@")[2]
        if FORMA_LN_DOMINIO.fullmatch(dominio):
            v["dominio"] = dominio
        return v
    return {"esito": "illeggibile", "tramite": "?",
            "messaggio": "Non sembra un indirizzo Lightning né una "
                         "richiesta di pagamento."}


def _risposta_fattura_p2p(v: dict, chi, ordine, adesso: int | None = None
                          ) -> dict:
    """La riga del journal e la risposta al client, da un verdetto.
    PURA a parte il print. Al client vanno tre cose: `ok` (puo' partire
    cosi' com'e'), `comunque` (puo' partire se l'utente insiste) e il
    `messaggio`; l'`esito` viaggia per il diario della diagnosi, che
    non e' mai un segreto. Nel journal MAI la fattura: l'ordine e la
    destinazione accorciati, la cifra, l'esito e il perche'."""
    esito = str(v.get("esito") or "")
    ferma, avvisa = esito in FATTURA_FERMA, esito in FATTURA_AVVISA
    segno = ("⛔" if ferma else "⚠️" if avvisa
             else "·" if esito in (FATTURA_NON_DISPONIBILE,
                                   FATTURA_USCITA_CORTA) else "✅")
    dest = str(v.get("dest") or "")
    pezzi = [str(v.get("tramite") or "")]
    # di un indirizzo, il dominio accanto al tramite («indirizzo
    # @sbpc.ch»): lo posa `controlla_fattura_p2p`, e qui passa ancora da
    # una whitelist di caratteri — una riga di journal non si spezza
    if v.get("dominio"):
        pezzi[0] += " @" + re.sub(r"[^a-z0-9.-]", "", str(v["dominio"]))[:80]
    if v.get("sats"):
        pezzi.append(f"{_fmt_sats(v['sats'])} sats")
    if dest:
        pezzi.append(f"dest {dest[:12]}…")
    if v.get("fee") is not None and v.get("tetto") is not None:
        pezzi.append(f"fee {v['fee']}/{v['tetto']}")
    if v.get("perche"):
        pezzi.append(str(v["perche"]))
    nome = re.sub(r"[^\w-]", "", str(ordine or ""))[:8] or "?"
    print(f"{segno} Fattura P2P: ordine {nome}, da {chi}, "
          f"{', '.join(p for p in pezzi if p)}: {esito}", flush=True)
    return {"ok": not (ferma or avvisa), "esito": esito,
            "comunque": avvisa,
            "messaggio": str(v.get("messaggio") or "") if (ferma or avvisa)
            else ""}


def _controllo_fattura_concesso(chi, adesso: int | None = None) -> bool:
    """Il tetto per utente di `TETTO_CONTROLLI_FATTURA_ORA`: ogni
    indirizzo e' un giro di rete verso un dominio scelto da chi lo
    scrive, e un LND non e' un servizio da interrogare a raffica.
    Oltre il tetto il controllo NON si fa, e la fattura passa come
    passava ieri (la regola: il controllo aiuta, mai ferma)."""
    t = int(time.time()) if adesso is None else int(adesso)
    if len(_controlli_fattura) > 2000:
        _controlli_fattura.clear()
    vivi = [x for x in _controlli_fattura.get(chi, []) if x > t - 3600]
    if len(vivi) >= TETTO_CONTROLLI_FATTURA_ORA:
        _controlli_fattura[chi] = vivi
        return False
    _controlli_fattura[chi] = vivi + [t]
    return True


@app.post("/api/p2p/fattura")
async def fattura_p2p(req: Request, x_tg_init_data: str = Header(""),
                      barattolo_sessione: str = Cookie("")):
    """«Questa fattura (o indirizzo) e' pagabile?», chiesto dal foglio
    «Dove vuoi ricevere i sats» PRIMA dell'add-invoice al coordinatore.
    Corpo: `testo` (bolt11 o Lightning address), `sats` (la cifra che
    il coordinatore ha detto, 0 = ignota), `finestra` (la sua
    `invoice_expiration_window`), `ordine` (solo per il journal).
    Risposta: `{ok, comunque, messaggio, esito}` — `ok` false e
    `comunque` false ferma, `comunque` true lascia il bottone «Usa
    comunque». Un 4xx/5xx o un silenzio qui il client li legge come
    «non si sa», e manda: questa rotta non puo' fermare uno scambio
    rompendosi."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    try:
        d = await req.json()
    except Exception:
        raise HTTPException(400, "Richiesta illeggibile")
    d = d if isinstance(d, dict) else {}
    testo = pulisci_fattura(d.get("testo"))
    if not testo or len(testo) > 4096:
        raise HTTPException(400, "Serve una fattura o un indirizzo")
    try:
        deve = max(0, int(d.get("sats") or 0))
        finestra = int(d.get("finestra") or 3600)
    except (TypeError, ValueError):
        raise HTTPException(400, "Cifra o finestra illeggibili")
    finestra = min(max(finestra, 60), 30 * 86400)
    if not _controllo_fattura_concesso(user["id"]):
        v = {"esito": FATTURA_NON_DISPONIBILE, "tramite": "?",
             "perche": "oltre il tetto di controlli dell'ora: non si guarda"}
    else:
        v = await controlla_fattura_p2p(testo, deve, finestra)
    return _risposta_fattura_p2p(v, user["id"], d.get("ordine"))


@app.post("/api/p2p/seme")
def seme_profilo_p2p(x_tg_init_data: str = Header(""),
                     barattolo_sessione: str = Cookie("")):
    """Il seme del profilo di scambio di chi entra da Telegram.

    NESSUN CORPO E NESSUN PARAMETRO, la regola della GET qui accanto:
    non si puo' chiedere il seme DI UN ALTRO, e non esiste nemmeno la
    sintassi per provarci. Ed e' anche cio' che tiene UNA sola `body:`
    nel blocco del mazzo, dove la sentinella pretende che l'unico corpo
    che parte di li' sia quello delle pubkey.

    E' UNA ROTTA SUA E NON UN CAMPO DI `/api/me`, per quattro ragioni
    che vanno tutte nello stesso verso: `/api/me` rispedisce la riga
    intera di `utenti` e parte a ogni apertura per TUTTI — anche per chi
    il P2P non lo tocca mai e anche in fase chiusa — mentre questo deve
    partire una volta sola, al primo gesto che lo richiede; li' non c'e'
    nessuno dei gate di qui; li' non c'e' `no-store`; e qui si SCRIVE
    (il sale nasce ora), che su una GET non si fa.

    ⚠️ `tg_id > 0` E' LA RIGA CHE TIENE IN PIEDI IL PATTO: la strada
    derivata e' solo per chi entra da Telegram. Un nativo Nostr ha un
    id NEGATIVO e prende 409 — e' venuto qui apposta per non farsi
    ricavare niente, e questa rotta non deve poterglielo fare.

    NON TORNA L'INDICE, e va detto perche' il disegno lo prevedeva:
    per darlo servirebbe la PUBKEY del seme, cioe' una moltiplicazione
    sulla curva, e in questo blocco non entra una libreria di curve (in
    CI non c'e', e la regola e' che qui non si firma niente). Non serve:
    il client deriva la pubkey da solo e la manda subito dopo a
    `/api/p2p/chiavi`, che il pavimento glielo risponde — identita' e
    contatore restano un colpo solo, in due rotte invece che in una.

    409 IN TUTTI I MODI DI NON POTERE, e mai un seme a meta': leva
    spenta, fase chiusa, id negativo, segreto assente, versione che nel
    dizionario non c'e' piu' (un ripristino da un backup vecchio), o
    uno scalare non derivabile. Il client legge il 409 come SILENZIO —
    il patto della GET — e genera come ha sempre fatto."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    if user["id"] <= 0 or not _segreto_p2p_vivo():
        raise HTTPException(409, "Il profilo legato all'account non e' attivo")
    con = db()
    riga = _sale_profilo_p2p(con, user["id"], int(time.time()))
    # ⚠️ IL COMMIT E' MEZZA IDENTITA' (9 set 2026): `db()` non e' in
    # autocommit, quindi senza questa riga l'INSERT del sale viveva solo
    # nella transazione — la SELECT di `_sale_profilo_p2p`, sulla STESSA
    # connessione, lo vedeva e la rotta rispondeva un seme valido, poi la
    # close() faceva rollback e il sale evaporava. Risultato: OGNI chiamata
    # coniava un'identita' NUOVA con la faccia di una derivazione stabile
    # (tre superfici dello stesso account, tre profili «del conto» diversi,
    # `p2p_semi` vuota in produzione). La prova che lo tiene e' quella a
    # DUE connessioni in prove.py: il sale deve sopravvivere a chi l'ha
    # coniato.
    con.commit()
    con.close()
    # LA VERSIONE E' QUELLA DELLA RIGA e non quella viva: chi c'era
    # prima di una rotazione continua a derivare con la SUA finche' non
    # passa alla nuova con un gesto. E' tutto il senso della colonna.
    versione = riga.get("versione", 0)
    segreto = SEGRETI_PROFILO_P2P.get(versione, "")
    if not riga.get("sale") or not segreto:
        raise HTTPException(409, "Il profilo legato all'account non e' attivo")
    try:
        seme = _seme_profilo_p2p(segreto, riga["sale"], user["id"], versione)
    except ValueError:
        seme = ""
    if not seme:
        raise HTTPException(409, "Il profilo legato all'account non e' attivo")
    return JSONResponse({"ok": True, "seme": seme, "versione": versione},
                        headers={"Cache-Control": "no-store, private"})


# ==================== LA SVEGLIA DEL TABACCHINO (set 2026) ==============
# Emenda alla fase 6 (decisione di Andrea): gli avvisi di scadenza
# dello scambio in contanti al tabacchino arrivano anche ad app chiusa,
# su Telegram o Nostr secondo le impostazioni — passano da `notifica`,
# che gia' sceglie il canale. Il server impara SOLO «questo account ha
# una scadenza a quest'ora»: la rotta legge una chiave sola dal corpo
# e la tabella ha quattro colonne. I due momenti li ricava il server
# (sei ore prima, un'ora prima), cosi' la regola vive in un posto; il
# testo non porta numeri, id ne' importi, e dice «se e' gia' chiuso,
# ignora» perche' chi chiude da un altro dispositivo non toglie la
# sveglia. La riga muore alla scadenza.
MAX_SVEGLIE_P2P = 20          # per persona: piu' di cosi' non e' un uso
# L'ORIZZONTE E' QUELLO DI UN PAYCODE (23 set 2026, percorso Barattozon):
# la sveglia si mette sulla scadenza del PayCode, che Amazon da' a 72
# ore al massimo; il client rifiuta gia' oltre le 72, e qui resta un
# quarto d'ora di respiro per gli orologi. Era `max_expiration_days`
# (15 giorni), cioe' un tetto che non diceva niente sul metodo.
PAYCODE_ORE_MAX = 72
SVEGLIA_P2P_ORIZZONTE_S = PAYCODE_ORE_MAX * 3600 + 900
# IL TETTO DI AMAZON «Paga in contanti» (23 set 2026): 999 euro per
# ordine, nessun minimo oltre lo zero, nessuna commissione. Vale per il
# solo Barattozon: il tetto di Barattolo (P2P_MAX_EURO) e i limiti del
# P2P normale restano quelli che sono. Il gemello del client e'
# `giudiceImportoPayCodeP2P`; qui lo guarda la rotta del canale, l'unico
# posto in cui l'importo di un PayCode arriva al server.
PAYCODE_EURO_MAX = 999.0


def _importo_paycode_valido(euro) -> bool:
    """PURA: l'importo di un PayCode e' pagabile in contanti? Sopra lo
    zero e fino a 999,00 compresi: 0,50 passa, 999,01 no. Si confronta
    in CENTESIMI, che 999.01 <= 999.0 sui float non ha sorprese ma
    999.005 arrotondato si'."""
    try:
        cent = round(float(euro) * 100)
    except (TypeError, ValueError):
        return False
    return 0 < cent <= round(PAYCODE_EURO_MAX * 100)


def _paycode_sopra_minimo(euro, minimo) -> bool:
    """PURA: l'importo di un PayCode sta sopra il minimo di Barattozon
    (30 set 2026)? A minimo zero o storto passa tutto — il minimo e'
    una leva, e spenta non ferma nessuno. In centesimi, come il tetto:
    24,99 contro 25 no, 25,00 si'. Il gemello del client e'
    `giudiceMinimoPayCodeP2P`."""
    try:
        cent = round(float(euro) * 100)
        m = int(minimo)
    except (TypeError, ValueError):
        return True
    return m <= 0 or cent >= m * 100
SVEGLIA_P2P_TESTI = {
    1: "⏳ Un tuo scambio in contanti al tabacchino scade fra circa sei "
       "ore. Se l'ordine Amazon non è ancora pagato, è il momento di "
       "andare. Se lo scambio è già chiuso, ignora questo avviso.",
    2: "⏰ Un tuo scambio in contanti al tabacchino scade fra meno di "
       "un'ora. Se non è ancora pagato, è adesso: dopo resta solo "
       "annullare d'accordo. Se lo scambio è già chiuso, ignora questo "
       "avviso.",
}


def _sveglie_p2p_da_mandare(righe, adesso):
    """PURA: quali avvisi partono adesso e quali righe sono morte.
    Torna (da_mandare, morte): il primo e' una lista di (tg_id,
    quando, livello) col livello 1 = sei ore, 2 = un'ora; il secondo
    e' la lista delle (tg_id, quando) gia' scadute, da cancellare.
    UN AVVISO SOLO PER GIRO E PER RIGA, il piu' alto: una sveglia
    messa a mezz'ora dalla fine prende l'avviso dell'ora e salta
    quello delle sei, che sarebbe gia' falso."""
    da_mandare, morte = [], []
    for r in righe:
        quando = int(r["quando"])
        manca = quando - adesso
        if manca <= 0:
            morte.append((r["tg_id"], quando))
            continue
        livello = 2 if manca <= 3600 else (1 if manca <= 6 * 3600 else 0)
        if livello > int(r["avvisata"] or 0):
            da_mandare.append((r["tg_id"], quando, livello))
    return da_mandare, morte


async def _giro_sveglie_p2p():
    adesso = int(time.time())
    con = db()
    righe = [dict(r) for r in con.execute(
        "SELECT tg_id, quando, avvisata FROM p2p_sveglie").fetchall()]
    da_mandare, morte = _sveglie_p2p_da_mandare(righe, adesso)
    for tg_id, quando in morte:
        con.execute("DELETE FROM p2p_sveglie WHERE tg_id=? AND quando=?",
                    (tg_id, quando))
    # IL TIMBRO PRIMA DELL'INVIO: `notifica` non alza mai, ma un giro
    # che muore a meta' non deve ripetere lo stesso avviso al giro dopo
    for tg_id, quando, livello in da_mandare:
        con.execute("UPDATE p2p_sveglie SET avvisata=? WHERE tg_id=? AND quando=?",
                    (livello, tg_id, quando))
    con.commit()
    con.close()
    for tg_id, quando, livello in da_mandare:
        await notifica(tg_id, SVEGLIA_P2P_TESTI[livello])


async def orologio_sveglie_p2p():
    """Un giro al minuto, fail-open come gli altri orologi: un giro
    che muore lo dice nel journal e il prossimo riparte."""
    while True:
        await asyncio.sleep(60)
        try:
            await _giro_sveglie_p2p()
        except Exception as e:
            print(f"⚠️ Giro delle sveglie P2P saltato: {e}", flush=True)


_TASK_SVEGLIE_P2P = None


@app.on_event("startup")
async def avvia_sveglie_p2p():
    global _TASK_SVEGLIE_P2P
    _TASK_SVEGLIE_P2P = asyncio.create_task(orologio_sveglie_p2p())


async def _quando_sveglia_p2p(req, x_tg_init_data, barattolo_sessione):
    """Il pezzo comune delle due rotte: chi sei, se il P2P e' tuo, e
    l'UNICA chiave che si legge dal corpo. Torna (tg_id, quando)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    try:
        d = await req.json()
        quando = int(d.get("quando") or 0)
    except Exception:
        raise HTTPException(400, "Corpo non valido")
    if quando <= 0:
        raise HTTPException(400, "Manca la scadenza")
    return user["id"], quando


@app.post("/api/p2p/sveglia")
async def metti_sveglia_p2p(req: Request, x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """«Avvisami quando questa scadenza si avvicina». Solo `quando`,
    nel futuro e dentro l'orizzonte del coordinatore; un tetto per
    persona, e la stessa scadenza messa due volte e' una sola riga."""
    tg_id, quando = await _quando_sveglia_p2p(req, x_tg_init_data, barattolo_sessione)
    adesso = int(time.time())
    if not (adesso < quando <= adesso + SVEGLIA_P2P_ORIZZONTE_S):
        raise HTTPException(400, "Scadenza fuori misura")
    con = db()
    quante = con.execute("SELECT COUNT(*) FROM p2p_sveglie WHERE tg_id=?",
                         (tg_id,)).fetchone()[0]
    gia = con.execute("SELECT 1 FROM p2p_sveglie WHERE tg_id=? AND quando=?",
                      (tg_id, quando)).fetchone()
    if quante >= MAX_SVEGLIE_P2P and not gia:
        con.close()
        raise HTTPException(429, "Troppe sveglie")
    con.execute("INSERT OR IGNORE INTO p2p_sveglie(tg_id, quando, creata, avvisata) "
                "VALUES (?, ?, ?, 0)", (tg_id, quando, adesso))
    con.commit()
    con.close()
    return JSONResponse({"ok": True}, headers={"Cache-Control": "no-store, private"})


@app.post("/api/p2p/sveglia/togli")
async def togli_sveglia_p2p(req: Request, x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """Lo scambio e' finito: la sveglia non serve piu'. Idempotente."""
    tg_id, quando = await _quando_sveglia_p2p(req, x_tg_init_data, barattolo_sessione)
    con = db()
    con.execute("DELETE FROM p2p_sveglie WHERE tg_id=? AND quando=?", (tg_id, quando))
    con.commit()
    con.close()
    return JSONResponse({"ok": True}, headers={"Cache-Control": "no-store, private"})


# ⚠️ E' IN EURO, e non ricalca `max_order_amount` del coordinatore, che
# e' in SATS: qui stava scritto «lo stesso tetto di mostrod» ed era vero
# solo per la cifra (100.000), mai per l'unita'. Il tetto vero degli
# ordini lo legge il client VIVO dal 38385 — dal 17 set 2026 sono
# 500.000 sats, qualche centinaio di euro — e qui resta solo l'argine
# contro un numero assurdo nel post del canale: non si tiene a mano e
# non va inseguito quando il coordinatore cambia il suo.
MAX_EURO_P2P_CANALE = 100_000   # un argine, non il tetto degli ordini
MAX_METODO_P2P_CANALE = 60      # il maxlength del campo nel foglio
# il cursore del premio di Barattozon (26 set 2026): da −20 a +20, a
# numeri interi — il gemello di `P2P_PREMIO_TAB_MAX` del client, e una
# prova li tiene uguali
P2P_PREMIO_CANALE_MAX = 20
# ...e l'argine della convenienza degli ALTRI ordini (10 nov 2026): a
# sats fissi non ha tetto per costruzione, quindi qui c'e' solo un
# freno contro un numero assurdo nel post, come `MAX_EURO_P2P_CANALE`
P2P_CONVENIENZA_CANALE_MAX = 1000


def _premio_canale_p2p(lato: str, premio: int) -> str:
    """Il premio di un ordine P2P come lo dice il post nei canali: dal 13
    nov 2026 «3% fee al compratore», «4% fee al venditore», a zero «al
    prezzo di mercato» (fino ad allora «10% più conveniente» come la
    card del libro, vedi sotto). PURA.
    IL GIUDICE E' QUELLO DEL CLIENT, `affareP2P`: la formula uniforme di
    mostro (`sats -= premium/100 * sats`) fa che un premio positivo
    assottigli sempre i sats, quindi conviene a chi legge solo se chi ha
    pubblicato COMPRA sats. Chi pubblica «vendo» mette nel libro un
    ordine `sell`, e chi lo legge dal canale e' chi compra."""
    # «FEE AL VENDITORE / AL COMPRATORE» (13 nov 2026, Andrea: «nelle
    # vetrine invece di scrivere piu conveniente o meno conveniente,
    # scrivi fee al venditore, o fee al compratore»). Nei canali il
    # post lo leggono tutti e due i lati, quindi non si dice piu'
    # l'effetto su chi guarda ma CHI PAGA la differenza dal mercato. Il
    # verso e' quello di mostro e non dipende dal lato: un premio
    # positivo assottiglia sempre i sats (`sats -= premium/100 * sats`),
    # cioe' il compratore riceve meno sats per gli stessi euro — la fee
    # e' sua; negativo, il venditore ne consegna di piu' — e' sua.
    # Le card dell'app restano col «piu'/meno conveniente» di `affareP2P`:
    # la' chi guarda ha un lato solo. `lato` resta nella firma per i
    # chiamanti, e qui non serve piu'.
    if not premio:
        return "al prezzo di mercato"
    return f"{abs(premio)}% fee al {'compratore' if premio > 0 else 'venditore'}"


def _caption_canale_p2p(lato: str, euro: float, metodo: str, venditore: dict,
                        premio=None, zona: str = "", valuta: str = "EUR",
                        cifra_coin: str = "") -> str:
    """La caption del post P2P nel canale «Barattolo Vetrina», gemella
    di `_caption_canale` ma per un ordine invece che per un annuncio
    (chiesto da Andrea, set 2026: il P2P deve vedersi in vetrina come
    un annuncio qualunque).

    LA FIRMA C'E' (decisione di Andrea, set 2026, ribaltata sulla
    prima stesura): «voglio sempre vedere chi l'ha pubblicato, come
    gia' faccio in Barattolo» — e la riga e' letteralmente quella,
    `_firma_venditore`, non una sua imitazione. Chi pubblica un ordine
    e' gia' un utente autenticato (il gate di `annuncia_ordine_p2p_canale`
    lo richiede), quindi qui non si scopre niente che il server non
    sapesse gia': si SCEGLIE di scriverlo, mentre altrove nel P2P
    (`/api/p2p/chiavi`, la trade key) resta la regola opposta — quella
    e' l'identita' DI SCAMBIO (pseudonima per costruzione, vedi regola
    ferrea 2), questa e' l'identita' di chi ha PREMUTO PUBBLICA, e sono
    due cose diverse: la seconda Barattolo la mostra da sempre per gli
    annunci normali, e ora anche qui."""
    verbo = "Compra" if lato == "compro" else "Vende"
    testo = f"🔁 <b>{verbo} BTC su Barattolo</b>"
    # IN FRANCHI (14 nov 2026, cantiere p2p-chf): la cifra col suo segno;
    # ogni altra valuta resta la riga di ieri, byte per byte
    if valuta == "CHF":
        testo += f"\n🇨🇭 {_fmt_eur(euro)} CHF"
    # ...e in moneta la cifra nella moneta, «🪙 0,0153 ETH» (16 nov 2026,
    # p2p-monete-valute): l'euro e' solo il controvalore per il nodo
    elif cifra_coin:
        testo += f"\n🪙 {html.escape(cifra_coin)}"
    else:
        testo += f"\n💶 {_fmt_eur(euro)} €"
    # IL PREMIO DI BARATTOZON (26 set 2026): a prezzo fisso non sta in
    # nessun campo del libro, e chi legge il canale e' lo stesso che
    # legge la card — le stesse parole. Per gli altri ordini `None`, e
    # la caption resta quella di ieri.
    if premio is not None:
        testo += f"\n🏷️ {_premio_canale_p2p(lato, premio)}"
    # «💵 CONTANTI» NEL POST (10 ott 2026): il contanti di persona porta le
    # sue banconote come sulla card, e il 💳 resta a intestare gli ALTRI
    # nomi — «💳 SEPA, 💵 Contanti». A parola intera: «Contanti al
    # tabacchino» e' Barattozon e resta sotto il 💳, come ieri. Senza
    # «Contanti» fra le voci la riga e' quella di ieri, byte per byte.
    voci = [m.strip() for m in str(metodo or "").split(",") if m.strip()]
    if "Contanti" in voci:
        pezzi, intestato = [], False
        for m in voci:
            if m == "Contanti":
                pezzi.append("💵 Contanti")
            else:
                pezzi.append(("" if intestato else "💳 ") + html.escape(m))
                intestato = True
        testo += "\n" + ", ".join(pezzi)
    else:
        testo += f"\n💳 {html.escape(metodo)}"
    # LA ZONA DI SCAMBIO DEL CONTANTI (10 ott 2026): la stessa riga della
    # card, «📍 Milano centro», sotto il metodo. Arriva gia' giudicata
    # dalla rotta (solo col contanti, solo pulita); senza, la caption e'
    # quella di ieri. Testo di un utente: si scappa come il metodo.
    if zona:
        testo += f"\n📍 {html.escape(zona)}"
    testo += "\n🔒 Sats bloccati in un deposito di garanzia fino allo scambio"
    # il post vive nel canale Telegram e basta: a leva accesa il link apre
    # la Mini App (`_link_casa_telegram`), a leva spenta e' quello di ieri
    testo += f"\n\n<a href=\"{_link_casa_telegram()}\">🫙 Apri lo Scambio P2P su Barattolo</a>"
    testo += f"\n\n{_firma_venditore(venditore)}"
    testo += "\n\n#p2p #barattolo"
    return testo


@app.post("/api/p2p/canale")
async def annuncia_ordine_p2p_canale(req: Request,
                                     x_tg_init_data: str = Header(""),
                                     barattolo_sessione: str = Cookie("")):
    """Il client dice al server «ho appena pubblicato un ordine», e il
    server lo racconta nello stesso canale dove escono gli annunci
    normali (`canale_id()`, «Barattolo Vetrina»). Fail-open come
    `_posta_promo_singolo`: un post di vetrina saltato non deve mai
    rompere il gesto di chi ha appena scambiato.

    NIENTE PROVA CRITTOGRAFICA che l'ordine sia vero: il server non
    parla mai col coordinatore (e' il patto di privacy del P2P, vedi
    Architettura), quindi non puo' verificare questa richiesta piu' di
    quanto verifichi le pubkey di `/api/p2p/chiavi`. Il gate e' lo
    stesso di quella rotta — leva P2P accesa E persona nella lista."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    try:
        d = await req.json()
    except Exception:
        raise HTTPException(400, "Richiesta illeggibile")
    d = d or {}
    lato = str(d.get("lato") or "")
    if lato not in ("compro", "vendo"):
        raise HTTPException(400, "Lato sconosciuto")
    # coi centesimi (22 set 2026, il tabacchino): 23.47 e' un importo
    # buono, e si arrotonda al centesimo; NaN e infinito sono storti
    try:
        euro = round(float(d.get("euro")), 2)
    except (TypeError, ValueError):
        raise HTTPException(400, "Importo storto")
    if not (0 < euro <= MAX_EURO_P2P_CANALE):
        raise HTTPException(400, "Importo fuori misura")
    metodo = str(d.get("metodo") or "").strip()
    if not metodo or len(metodo) > MAX_METODO_P2P_CANALE:
        raise HTTPException(400, "Metodo di pagamento storto")
    # il tetto di Amazon, sul solo Barattozon (23 set 2026)
    if _tabacchino_libro([metodo]) and not _importo_paycode_valido(euro):
        raise HTTPException(
            400, "Amazon accetta il pagamento in contanti fino a 999 € per ordine")
    # ...e il minimo di Barattozon (30 set 2026), dopo il tetto di Amazon
    # e con la stessa leva che legge il foglio
    if _tabacchino_libro([metodo]) and not _paycode_sopra_minimo(euro, BARATTOZON_MIN_EURO):
        raise HTTPException(
            400, f"Un PayCode Barattozon vale almeno {BARATTOZON_MIN_EURO} €")
    # un ordine nuovo nel libro: la fotografia si rifa' subito, cosi' la
    # fila «Scambi P2P» di Esplora lo mostra al suo giro dopo (LA
    # FOTOGRAFIA SUBITO) — col canale acceso o spento. Il client manda
    # l'id del suo ordine (27 set 2026): cosi' il server sa quale
    # aspettare, e riprova solo se la prima lettura non lo porta. Un id
    # storto o assente vale «nessuno»: il giro c'e' lo stesso.
    ordine = str(d.get("ordine") or "")
    buono = bool(FORMA_ORDINE_P2P.fullmatch(ordine))
    # ⚠️ E CHI L'HA PUBBLICATO SI SCRIVE QUI, PRIMA DELLA FOTOGRAFIA (28
    # set 2026, dalla prova di Alan: un suo «compra BTC» stava nella fila
    # della home col «?» al posto del volto, e sul suo telefono come un
    # ordine da prendere). L'autore lo scriveva solo /api/p2p/ordini, che
    # il telefono manda da solo e SENZA aspettarlo: se non arriva — o
    # arriva dopo il giro subito — la fotografia nasce senza volto e
    # senza `autori`, e la fila lo mostra anche a chi l'ha pubblicato
    # fino al giro del minuto. Qui la sessione c'e' e l'id pure: e' la
    # stessa dichiarazione («l'ho pubblicato io»), con lo stesso giudice
    # e la stessa regola del primo che arriva, fatta nel solo momento
    # in cui il server sa che l'ordine e' appena nato.
    if buono:
        _intesta_dal_canale_p2p(user["id"], ordine)
    _foto_subito_p2p(ordine if buono else "")
    # il premio di Barattozon (26 set 2026): solo sul tabacchino, e solo
    # un INTERO della scala del cursore — «2.5», «10» fra virgolette o un
    # booleano sono storti. Sugli altri metodi si ignora: il loro premio
    # il post non l'ha mai detto.
    premio = None
    if _tabacchino_libro([metodo]) and d.get("premio") is not None:
        premio = d.get("premio")
        if (isinstance(premio, bool) or not isinstance(premio, int)
                or abs(premio) > P2P_PREMIO_CANALE_MAX):
            raise HTTPException(400, "Premio storto")
    # LA CONVENIENZA DI OGNI ALTRO ORDINE (10 nov 2026, richiesta di
    # Andrea: «nella vetrina mettici anche la convenienza, positiva o
    # negativa»). Il client manda il premio a mercato (da −20 a +20) o,
    # a sats fissi, la convenienza di adesso col suo cambio — la stessa
    # che dice il badge della card, `premioCardP2P`, e che puo' passare
    # il 20 (vedi `convenienzaFissaP2P`: «212%» se e' 212). Il segno e'
    # quello di mostro, e a dirlo con le parole giuste e' lo stesso
    # giudice di Barattozon, `_premio_canale_p2p`.
    # QUI UN NUMERO STORTO NON E' UN 400, ed e' la differenza col
    # Barattozon qui sopra: un client di ieri non lo manda, e la vetrina
    # non deve fermare nessuno — si ignora e il post esce senza la riga.
    elif d.get("premio") is not None:
        p = d.get("premio")
        if (not isinstance(p, bool) and isinstance(p, int)
                and abs(p) <= P2P_CONVENIENZA_CANALE_MAX):
            premio = p
    # la zona di scambio (10 ott 2026): solo se fra i metodi c'e'
    # «Contanti» a parola intera, e solo pulita. Una zona storta NON e' un
    # 400: il post esce senza, che la vetrina non deve fermare nessuno.
    zona = _zona_pulita_p2p(d.get("zona")) \
        if "Contanti" in _metodi_lista_p2p(metodo) else ""
    # LA VALUTA (14 nov 2026, cantiere p2p-chf): «CHF» o l'euro di sempre.
    # Un ordine in franchi esce nei canali solo coi franchi aperti a tutti
    # (`P2P_CHF_SOLO_ADMIN` spenta): un post pubblico non annuncia quel che
    # chi lo legge non puo' prendere
    valuta = "CHF" if str(d.get("valuta") or "").upper() == "CHF" else "EUR"
    chf_chiuso = valuta == "CHF" and (P2P_CHF_SOLO_ADMIN or not P2P_CHF_ATTIVO)
    # ...E LE MONETE (16 nov 2026, cantiere p2p-monete-valute): «ETH», «XMR»
    # o «USDE» con la `cifra` col punto, letta dallo stesso giudice del
    # libro; storta, il post esce con l'euro di sempre. A leva spenta il
    # post non esce, come i franchi chiusi
    moneta = {"ETH": "ETH", "XMR": "XMR", "USDE": "USDe"}.get(
        str(d.get("valuta") or "").upper(), "")
    cifra_coin = ""
    if moneta:
        nome = next(n for n, c in P2P_COIN_METODI.items() if c == moneta)
        letto = _coin_ordine_libro([f"{nome} {str(d.get('cifra') or '').strip()[:20]}"])
        cifra_coin = f"{letto[1]} {letto[0]}" if letto else ""
        chf_chiuso = chf_chiuso or not P2P_COIN_ATTIVO
    postato = False
    # UN POST PER ORDINE, E UNO OGNI DIECI MINUTI PER PERSONA (cura 4, la
    # M3 del secondo audit): il doppione e il raffica NON sono un 429 —
    # l'intestazione e la fotografia qui sopra servono lo stesso — si
    # salta solo il post nel canale, e la risposta lo dice.
    adesso_canale = time.time()
    doppione = bool(buono) and adesso_canale - _CANALE_POSTATI.get(ordine, 0) < 86400
    raffica = not _secchio_passa(f"canale:{user['id']}", *FRENI["canale"], adesso_canale)
    # SUBITO CRYPTO (10 nov 2026, richiesta di Andrea): lo stesso post
    # anche nel canale della comunita', `canale_vetrina()` — e SOLO per
    # chi viene da Telegram. La regola e' quella degli annunci normali in
    # `_posta_promo_singolo` (un account Telegram, `tg_id > 0`, con un
    # @username: la firma «da @tizio» e' la maniglia che quel pubblico si
    # aspetta), cosi' le due porte di casa d'altri non divergono. Chi
    # entra da Nostr resta nel nostro canale, come per gli annunci.
    # Ogni canale fallisce per conto suo, e gli stessi freni valgono per
    # tutti e due: un doppione o una raffica non escono da nessuna parte.
    # UNO A SETTIMANA PER PERSONA, ANCHE QUI (17 nov 2026, Andrea: «gli
    # annunci della vetrina di subito crypto p2p devono comunque
    # rispettare la regola di non piu' di uno a settimana per persona»).
    # Il freno e' quello degli annunci, `ritmo_vetrina()` coi suoi
    # giorni (a 0, ritmo «tutto», niente freno), e conta tutti e due i
    # timbri: chi questa settimana ha gia' avuto in canale un annuncio
    # (`promo_canale_il`) o un ordine P2P su Subito Crypto
    # (`promo_vetrina_p2p_il`) non ci torna con un ordine. Il resto del
    # post esce lo stesso: il nostro canale e BitcoinPodcast non hanno
    # questo freno per il P2P.
    vetrina_ok = False
    settimana_piena = False
    if canale_vetrina() and user["id"] > 0:
        try:
            con = db()
            r_u = con.execute("SELECT username, promo_canale_il, "
                              "promo_vetrina_p2p_il FROM utenti WHERE tg_id=?",
                              (user["id"],)).fetchone()
            con.close()
            vetrina_ok = bool(r_u and (r_u["username"] or ""))
            giorni_v = ritmo_vetrina()[0]
            if vetrina_ok and giorni_v > 0:
                soglia_v = int(adesso_canale) - giorni_v * 86400
                if max(r_u["promo_canale_il"] or 0,
                       r_u["promo_vetrina_p2p_il"] or 0) > soglia_v:
                    vetrina_ok, settimana_piena = False, True
        except Exception as e:
            vetrina_ok = False
            print(f"⚠️ Post P2P su Subito Crypto saltato: {e}")
    # BITCOINPODCAST (10 nov 2026, Andrea: «su bitcoinpodcast devi
    # mandare anche quelli relativi al p2p»): la terza porta, e qui entra
    # TUTTO — la stessa regola degli annunci in `_posta_promo_singolo`,
    # senza il filtro dell'@username, perche' quel pubblico e' di
    # bitcoiner e la menzione Telegram non e' la maniglia che si aspetta.
    if (canale_id() or vetrina_ok or canale_bitcoin_podcast()) \
            and not doppione and not raffica and not chf_chiuso:
        try:
            con = db()
            riga = con.execute(
                "SELECT nome, username, npub, npub_verificata, npub_accesso, "
                "negozio FROM utenti WHERE tg_id=?", (user["id"],)).fetchone()
            con.close()
            venditore = {
                "venditore": (riga["nome"] if riga else "") or "",
                "venditore_username": (riga["username"] if riga else "") or "",
                "venditore_npub": (riga["npub"] if riga else "") or "",
                "venditore_npub_verificata": (riga["npub_verificata"] if riga else 0) or 0,
                "venditore_npub_accesso": (riga["npub_accesso"] if riga else "") or "",
                "venditore_negozio": (riga["negozio"] if riga else "") or "",
            }
            caption = _caption_canale_p2p(lato, euro, metodo, venditore, premio, zona,
                                          valuta, cifra_coin)
            if canale_id():
                try:
                    postato = bool(await _manda_post_canale(canale_id(), caption, []))
                except Exception as e:
                    print(f"⚠️ Post P2P nel canale saltato: {e}")
            if vetrina_ok:
                try:
                    # il timbro PRIMA dell'invio, il patto delle campagne
                    # (`_posta_promo_singolo`): un guasto puo' far perdere
                    # un post, mai raddoppiarlo
                    con = db()
                    con.execute("UPDATE utenti SET promo_vetrina_p2p_il=? "
                                "WHERE tg_id=?", (int(adesso_canale), user["id"]))
                    con.commit()
                    con.close()
                    if await _manda_post_canale(canale_vetrina(), caption, []):
                        postato = True
                except Exception as e:
                    print(f"⚠️ Post P2P su Subito Crypto saltato: {e}")
            if canale_bitcoin_podcast():
                try:
                    if await _manda_post_canale(canale_bitcoin_podcast(), caption, []):
                        postato = True
                except Exception as e:
                    print(f"⚠️ Post P2P su BitcoinPodcast saltato: {e}")
            if postato and buono:
                if len(_CANALE_POSTATI) > 5000:
                    _CANALE_POSTATI.clear()
                _CANALE_POSTATI[ordine] = adesso_canale
        except Exception as e:
            print(f"⚠️ Post P2P nel canale saltato: {e}")
    return {"ok": True, "postato": postato,
            **({"saltato": "doppione"} if doppione else {}),
            **({"saltato": "raffica"} if raffica and not doppione else {}),
            **({"subito_crypto": "settimana"} if settimana_piena else {})}


_CANALE_POSTATI: dict = {}      # ordine -> quando e' uscito il suo post (cura 4)


# ---------- GLI AVVISI DELLO SCAMBIO P2P: MOSTRO E' L'UNICA FONTE ------
# (patch 0007, 18 set 2026, decisione di Andrea con Alan)
# Uno scambio dura ore: chi ha preso ha 900 secondi per la sua mossa, e
# fra una mossa e l'altra la Mini App e' CHIUSA. Senza un avviso, chi
# vende scopre che gli euro sono partiti quando riapre l'app — e magari
# e' tardi.
#
# FINO AL 18 SET 2026 QUI C'ERA UN CAMPANELLO CHE DEDUCEVA. Il server
# guardava sui relay le buste cifrate del coordinatore verso le chiavi
# dei nostri utenti, e non potendole leggere diceva «Novita' in un tuo
# scambio». Attorno a quella frase cieca era cresciuto un castello: un
# gate da 600 secondi e uno da 90 contro le raffiche, una coda per non
# perdere la busta arrivata a gate chiuso, la «busta gemella» per non
# raddoppiare le frasi del libro, e una finestra dell'eco — il telefono
# diceva «sto facendo un gesto» — per non suonare a chi aveva l'app in
# mano. DAL VIVO (journal del VPS, 18 set, 20:15-20:26) HA DATO AVVISI
# A CASO: la pausa da 600 s rimasta attaccata alla persona per tutto lo
# scambio dopo, le buste di uno scambio gia' concluso che suonavano, il
# «concluso» mai arrivato a chi vendeva.
# Il difetto non era in una taratura: era nel DEDURRE. E c'e' chi i
# fatti li SA — il coordinatore, che e' nostro. Dalla patch 0007 mostrod
# racconta ogni passo a `/api/p2p/evento`, e da li' nasce UN avviso
# preciso, alla parte che deve agire o sapere, MAI a chi ha fatto il
# gesto. Il castello e' stato tolto per intero, e non si rimette: vedi
# CANTIERI, «Mostro e' l'unica fonte degli avvisi P2P».
#
# IL SERVER CONTINUA A NON DECIFRARE NIENTE — adesso non guarda nemmeno
# piu' le buste. COSA SA IN PIU', e va detto perche' e' il prezzo: a che
# punto e' ogni scambio e fra quali due trade key (quindi, per i nostri
# utenti, fra quali due account). NON sa gli importi, tranne i tre della
# chiusura; non vede fatture, preimage, ne' dove vanno gli euro.
#
# LA RETE DI SICUREZZA E' IL LIBRO PUBBLICO: presa, concluso, annullato,
# scaduto e il ritorno in vetrina si leggono anche dal 38383, come dal
# 16 set 2026. Il giro del libro RESTA — uno al minuto, piu' l'ascolto
# sullo specchio — ma la sua frase aspetta `P2P_RISERVA_S`: se intanto
# l'evento di mostrod e' arrivato il libro TACE, se no parla lui. Finche'
# la porta degli eventi e' chiusa (`P2P_EVENTI_SEGRETO` vuoto: la patch
# non e' ancora sul nodo) il libro non aspetta nessuno e parla subito,
# com'era.
P2P_GIRO_S = 60          # ogni quanto si guarda il libro: la latenza della riserva
P2P_RISERVA_S = 60       # quanto il libro aspetta il coordinatore prima di parlare lui
# DUE FONTI, UN MOMENTO: l'evento di mostrod porta l'ora del suo
# orologio, il 38383 il suo `created_at` — stessa macchina, stesso
# istante, a meno dei secondi che `monotonic_order_event_timestamp`
# aggiunge per tenere in fila due eventi dello stesso ordine. Trenta
# secondi sono larghi per quello e stretti per tutto il resto: due prese
# VERE dello stesso ordine a meno di mezzo minuto non esistono (in mezzo
# ci vuole un ritiro o un timeout da 900 s).
P2P_STESSO_MOMENTO_S = 30
# IL RESPIRO DELLA PRESA: l'evento di mostrod arriva in un secondo, il
# 38383 coi NUMERI della presa (a prezzo di mercato i sats si fissano
# li') in tre, e il telefono di chi ha preso dichiara il suo nome poco
# dopo. La frase della presa aspetta fin qui i numeri, e meno il nome:
# sei secondi contro i sessanta di prima.
P2P_RESPIRO_S = 6
P2P_RESPIRO_NOME_S = 3
_P2P_ATTESE = {"scade": 0}   # quando scade la prima attesa: sveglia l'orologio
_TASK_EVENTI_P2P = set()     # gli invii in volo: un task senza riferimento si perde
# LA PRESA SUL LIBRO E' `in-progress`, E BASTA (corretto il 18 set
# 2026, letto sul sorgente di mostrod 0.18.7 e visto sullo specchio).
# Il 17 set qui c'era scritto che il 38383 dice anche
# `waiting-buyer-invoice` e `waiting-payment`: FALSO. Quei due stati
# stanno nel LOG di mostro e nella restore-session, mai sul libro —
# `create_status_tags` in `src/nip33.rs` pubblica i soli quattro
# secchi di NIP-69 (pending, in-progress, success, canceled), e un
# ordine in `waiting-*` esce come `in-progress`. Restano nella tupla
# perche' un coordinatore che li pubblicasse non deve far cadere la
# presa fra gli stati «mai visti».
STATI_LIBRO_PRESO = ("in-progress", "waiting-buyer-invoice",
                     "waiting-payment",
                     # ...e «active», che il libro non scrive mai: lo scrive
                     # l'evento della garanzia pagata (25 set 2026), e per
                     # i passaggi del libro vale come una presa
                     "active")
P2P_BLOCCO = 100         # quanti id in un filtro (i relay hanno tetti)
P2P_PRIMO_SGUARDO = 600  # al primo avvio si guarda indietro dieci minuti

# ═══ L'OROLOGIO CHE NON SI APPENDE (17 set 2026, dal journal del VPS) ═══
# Il fatto: dal riavvio del deploy delle 10:03 il journal non ha piu'
# avuto una riga del libro, la presa delle 10:09 e' rimasta muta per
# un quarto d'ora a tutt'e due, e un `systemctl restart` a mano ha
# fatto arrivare subito le frasi giuste, quella in coda compresa. Segnalibro e recupero
# funzionavano; era il GIRO a non girare, e dal journal non si
# distingueva «non gira» da «gira a vuoto», perche' il giro parlava
# solo quando avvisava qualcuno.
# DUE COSE POTEVANO FERMARLO SENZA UNA RIGA, e quale sia stata quel
# giorno non e' provato — quindi si curano tutt'e due:
# 1) le domande ai relay giravano in un thread SENZA UN TETTO: i
#    timeout dei socket coprono connessione e lettura, non il DNS ne'
#    un thread che non parte perche' il pool comune e' pieno. Un await
#    che non torna ferma TUTTE le passate dopo, per sempre.
# 2) l'orologio nasceva con un `create_task` di cui nessuno teneva il
#    riferimento (gli altri orologi hanno il loro `_TASK_…`), e niente
#    lo sorvegliava: morto o appeso, restava cosi' fino al deploy dopo.
# LE CINTURE, dalla piu' stretta alla piu' larga: ogni domanda a un
# relay ha il suo tetto e un pool di thread SUO (chi e' lento non
# affama gli altri, e gli altri non affamano lui); ogni passata ha il
# suo; e un guardiano tiene il riferimento, guarda il battito e fa
# ripartire l'orologio se e' morto o fermo — dicendolo.
P2P_RELAY_MAX_S = 20      # il tetto di UNA domanda a UN relay
P2P_PASSATA_MAX_S = 240   # il tetto di una passata intera (libro, o attese)
P2P_GUARDIA_S = 30        # ogni quanto il guardiano guarda il battito
P2P_FERMO_S = 600         # oltre, l'orologio e' FERMO: un giro + due passate al tetto + margine
try:
    from config import P2P_LOG_PASSATE
except ImportError:
    P2P_LOG_PASSATE = True   # la riga a ogni passata: si spegne dal config
_P2P_POOL = None          # il pool di thread del solo P2P: nasce al primo uso
_P2P_BATTITO = {"n": 0, "vivo": 0.0}
_P2P_CONTO = {"libro": "", "attese": ""}   # cosa ha fatto l'ultima passata
_P2P_RELAY_MUTI = set()   # i relay che tacciono ADESSO: si dice al cambio, non a ogni giro
_TASK_OROLOGIO_P2P = None
_TASK_GUARDIANO_P2P = None


def _esiti_p2p_dice(segno: str, esiti: list):
    """«AVVISATI N» NON DICE SE E' ARRIVATO (17 set 2026, dal campo:
    il journal diceva «avvisati 2», nessun errore, e su nessuno dei due
    telefoni era arrivato niente). Quella riga conta chi si e' PROVATO
    ad avvisare; questa dice, per destinatario, per quale strada e'
    passato e cosa ha risposto Telegram — col `message_id` quando e'
    andata, che e' la ricevuta. Un esito vuoto (un `notifica` di ieri,
    o di cartone) si dice come tale: mai un «ok» dedotto."""
    for tg_id, esito in esiti:
        print(f"   {segno} ↳ {tg_id}: {esito or 'esito non detto'}", flush=True)


def _relay_copia_p2p() -> list:
    """I relay su cui il client mette la copia cifrata del profilo di
    scambio (11 ott 2026): RELAY_NOSTR (o i relay di serie) e lo
    specchio nostro, senza doppioni, nell'ordine in cui stanno. PURA sui
    globali, cosi' una prova la chiama e basta."""
    visti, fuori = set(), []
    for r in list(RELAYS_VERIFICA) + list(MOSTRO_RELAY_SPECCHIO):
        r = str(r or "").strip().rstrip("/")
        if r and r not in visti and r.startswith(("wss://", "ws://")):
            visti.add(r)
            fuori.append(r)
    return fuori


def _relay_p2p_dice(relay: str, muto: bool, perche: str = ""):
    """Il journal dice quando un relay SMETTE di rispondere e quando
    RIPRENDE — al cambio, non a ogni passata: un relay giu' per un'ora
    sarebbero sessanta righe uguali, e la riga che conta ci annegherebbe."""
    if muto and relay not in _P2P_RELAY_MUTI:
        _P2P_RELAY_MUTI.add(relay)
        print(f"🔇 P2P: il relay {relay} non risponde ({perche}): "
              "passo al successivo", flush=True)
    elif not muto and relay in _P2P_RELAY_MUTI:
        _P2P_RELAY_MUTI.discard(relay)
        print(f"🔊 P2P: il relay {relay} e' tornato a rispondere", flush=True)


async def _chiedi_relay_p2p(fn, relay: str, *args):
    """UNA domanda a UN relay, col suo tetto. Le funzioni che leggono
    sono sincrone (websocket-client) e hanno i timeout dei socket; qui
    sta il tetto che manca a loro — quello sull'ATTESA INTERA, thread
    compreso. Allo scadere si torna None («non ho potuto chiedere») e
    il chiamante passa al relay dopo; il thread rimasto indietro muore
    da solo coi suoi timeout, nel pool del P2P e non in quello comune.
    Qualunque eccezione e' un relay muto, mai un giro che cade."""
    global _P2P_POOL
    if _P2P_POOL is None:
        from concurrent.futures import ThreadPoolExecutor
        # otto e non quattro: da quando si chiede a TUTTI i relay
        # insieme, quattro thread li occupa una domanda sola — e uno
        # rimasto indietro coi suoi timeout non deve far fare la coda
        # alla domanda dopo
        _P2P_POOL = ThreadPoolExecutor(max_workers=8,
                                       thread_name_prefix="p2p-relay")
    loop = asyncio.get_running_loop()
    try:
        fuori = await asyncio.wait_for(
            loop.run_in_executor(_P2P_POOL, fn, relay, *args),
            P2P_RELAY_MAX_S)
    except asyncio.TimeoutError:
        _relay_p2p_dice(relay, True, f"oltre {P2P_RELAY_MAX_S}s")
        return None
    except Exception as e:
        _relay_p2p_dice(relay, True, f"{type(e).__name__}: {e}")
        return None
    _relay_p2p_dice(relay, fuori is None, "connessione o lettura fallita")
    return fuori


# ═══ SI CHIEDE A TUTTI, E SI UNISCE (17 set 2026, dal campo) ═══
# Il fatto: l'ordine fdce9231 preso alle 11:24:42 UTC, mostro manda i
# suoi kind 14 e ripubblica il 38383 — e tre passate di fila dicono
# «0 eventi», «0 messaggi». La sonda sui relay veri, fatta nello stesso
# quarto d'ora: `relay.mostro.network` RISPONDEVA in 0,3 s ma di mostro
# non aveva piu' niente dalla sera prima (ultimo 38383 il 16 alle
# 14:43, ultimo kind 14 alle 19:43); nos.lol aveva tutto, lo specchio i
# 38383, damus dava 503. Il giro si fermava «al primo che risponde», e
# il primo della lista rispondeva: una lista VUOTA. Un `[]` e' «non ho
# niente», e detto da UN relay non vuol dire che non ci sia niente —
# vuol dire che non ce l'ha LUI. (Quando quello stesso relay va in
# timeout — nella sonda e' successo una volta su quattro — il giro
# passava al secondo e funzionava: e' il modo in cui un guasto cosi'
# va e viene. Che sia andata cosi' anche la mattina non e' provato.)
# LA CURA: ogni domanda va a TUTTI i relay INSIEME — ognuno col suo
# tetto, quindi la passata dura quanto il piu' lento e non la somma — e
# le risposte si UNISCONO. Lo stesso evento da due relay e' lo stesso
# evento (stesso id): cade nell'unione, e i doppioni che restano li
# rende inerti il giudice del libro (stato uguale = nessun passaggio).
# (Dalla patch 0007, 18 set 2026, ai relay si chiede il SOLO libro: i
# kind 14 del coordinatore non si guardano piu'. Il guasto di quel
# giorno resta la ragione per cui si chiede a tutti.)
# E IL JOURNAL DICE CHI HA DATO COSA, a ogni passata: «nos.lol 2 ·
# relay.mostro.network 0 · relay.damus.io ✗». Lo zero accanto a un due
# e' il guasto di quel giorno scritto in una riga; «✗» e' chi non ha
# risposto affatto.
# IL MARGINE DEL SEGNALIBRO: il `since` e' l'ultimo `created_at` letto,
# ma gli eventi NON arrivano sui relay nell'ordine in cui sono nati —
# mostro pubblica via Tor, relay per relay. Uno nato due secondi PRIMA
# di quello gia' letto e comparso dopo restava sotto il segnalibro per
# sempre (riprodotto a banco). Si chiede da un po' prima: i doppioni
# non costano niente, per le due ragioni qui sopra.
P2P_MARGINE_S = 120       # quanto indietro dal segnalibro si richiede


async def _chiedi_tutti_p2p(fn, relays: list, *args) -> list:
    """La stessa domanda a TUTTI i relay, insieme. Torna le coppie
    (relay, risposta) nell'ordine della lista, con None per chi non ha
    potuto rispondere — `_chiedi_relay_p2p` non alza mai, quindi un
    relay che cade non porta giu' gli altri."""
    risposte = await asyncio.gather(
        *[_chiedi_relay_p2p(fn, relay, *args) for relay in relays])
    return list(zip(relays, risposte))


def _unisci_p2p(risposte: list, chiave, conto: dict) -> list:
    """PURA: dalle risposte di tutti all'unione senza doppioni, e nel
    frattempo SEGNA in `conto` quanti eventi ha dato ciascuno. `conto`
    parte da None per ogni relay («non ha mai risposto in questa
    passata») e diventa un numero alla prima risposta: chi ha risposto
    a un blocco e non a un altro resta un numero, e il suo silenzio
    l'ha gia' detto `_relay_p2p_dice`."""
    visti, uniti = set(), []
    for relay, eventi in risposte:
        conto.setdefault(relay, None)
        if eventi is None:
            continue
        conto[relay] = (conto[relay] or 0) + len(eventi)
        for e in eventi:
            k = chiave(e)
            if k not in visti:
                visti.add(k)
                uniti.append(e)
    return uniti


def _conto_relay_p2p(conto: dict) -> str:
    """Il pezzo di riga che dice chi ha dato cosa: «nos.lol 2 ·
    relay.damus.io ✗». Senza `wss://`, che nel journal e' solo rumore."""
    return " · ".join(
        f"{r.split('://', 1)[-1]} {'✗' if n is None else n}"
        for r, n in conto.items())


def _evento_libro_p2p(ev: dict):
    """PURA: da un 38383 ai SOLI tag che servono alla frase — id,
    stato, lato, sats, euro, metodi, quando, scade — o None se manca il
    `d` o lo stato. L'unico posto che guarda dentro un 38383, per il
    lettore al minuto e per l'ascolto.
    `scade` (18 set 2026) e' il tag `expires_at`, la scadenza dell'ORDINE
    scritta dal coordinatore: e' l'unico modo di distinguere uno scaduto
    da un ritiro, perche' mostrod li pubblica tutt'e due come
    `canceled` (vedi `_passaggio_libro_p2p`). 0 = non si sa."""
    tag = {}
    for t in ev.get("tags", []):
        if len(t) > 1 and t[0] not in tag:
            tag[t[0]] = [str(x) for x in t[1:]]
    if not tag.get("d") or not tag.get("s"):
        return None
    try:
        sats = max(0, int(float(tag.get("amt", ["0"])[0])))
    except ValueError:
        sats = 0
    try:
        scade = max(0, int(float(tag.get("expires_at", ["0"])[0])))
    except (ValueError, OverflowError):
        scade = 0
    # il premio (27 set 2026): percentuale col segno, storta = 0
    try:
        premio = float(tag.get("premium", ["0"])[0])
    except (ValueError, OverflowError):
        premio = 0.0
    if premio != premio or abs(premio) > 100:
        premio = 0.0
    return {"id": tag["d"][0], "stato": tag["s"][0],
            "lato": (tag.get("k") or [""])[0],
            "sats": sats, "euro": tag.get("fa") or [],
            "metodi": tag.get("pm") or [],
            "quando": int(ev.get("created_at") or 0), "scade": scade,
            "premio": premio,
            # la valuta (1 nov 2026, cantiere p2p-usdt): «EUR» di serie, in
            # maiuscolo come la scrive il protocollo
            "fiat": ((tag.get("f") or ["EUR"])[0] or "EUR").upper()}


_P2P_FIRMA_DETTO = {"manca": False}   # l'avviso di coincurve assente, una volta


def _firmato_dal_coordinatore(ev, mostro: str) -> bool:
    """IL LIBRO SI CREDE SOLO SE LO HA FIRMATO MOSTROD (24 set 2026).
    PURA: un evento Nostr grezzo (38383 o 38385), e la pubkey
    esadecimale del coordinatore. Vero solo se l'evento e' SUO — la
    pubkey e' la sua, l'id ricalcolato con la serializzazione canonica
    NIP-01 combacia, e la firma Schnorr regge su quell'id (lo stesso
    controllo del login Nostr, `verifica_evento_login`).
    PERCHE': il filtro `authors` e' una DOMANDA al relay, non una
    prova. Fin qui il lettore del libro e l'ascolto si fidavano della
    risposta — un relay bucato, o chiunque in mezzo (il socket va su
    con `CERT_NONE` fino al 20 ott 2026), poteva servire un 38383 con la pubkey di mostrod
    e far partire dalla riserva un «preso» o un «concluso» a chi vuole:
    la stessa notizia non confermata che la cura di A1 (23 set 2026)
    ha tolto al telefono. Con la firma, quel che il libro dice l'ha
    detto mostrod: la riserva resta la rete di sicurezza di un POST
    perso, e non e' piu' una parola presa in prestito.
    FAIL-CLOSED: senza `coincurve` (sul VPS c'e', firma gli annunci
    NIP-99; in CI no, e li' nessun relay si legge) nessun evento si
    crede, e il journal lo dice una volta."""
    if ChiavePubblicaNostr is None:
        if not _P2P_FIRMA_DETTO["manca"]:
            _P2P_FIRMA_DETTO["manca"] = True
            print("⚠️ Libro P2P: coincurve non c'e': nessun 38383 si puo' "
                  "credere, il libro resta fermo", flush=True)
        return False
    if not isinstance(ev, dict):
        return False
    pubkey, sig, ev_id = ev.get("pubkey"), ev.get("sig"), ev.get("id")
    creato, kind = ev.get("created_at"), ev.get("kind")
    tags, content = ev.get("tags"), ev.get("content")
    if not (isinstance(pubkey, str) and pubkey == mostro):
        return False
    if not (isinstance(sig, str) and RE_HEX_128.fullmatch(sig)):
        return False
    if not (isinstance(ev_id, str) and RE_HEX_64.fullmatch(ev_id)):
        return False
    if (not isinstance(creato, int) or isinstance(creato, bool)
            or not isinstance(kind, int) or isinstance(kind, bool)
            or not isinstance(content, str)):
        return False
    if not (isinstance(tags, list)
            and all(isinstance(t, list)
                    and all(isinstance(x, str) for x in t) for t in tags)):
        return False
    serial = json.dumps([0, pubkey, creato, kind, tags, content],
                        separators=(",", ":"), ensure_ascii=False)
    if hashlib.sha256(serial.encode("utf-8")).hexdigest() != ev_id:
        return False
    try:
        return bool(ChiavePubblicaNostr(bytes.fromhex(pubkey)).verify(
            bytes.fromhex(sig), bytes.fromhex(ev_id)))
    except Exception:
        return False


# ═══ L'ASCOLTO: le notifiche P2P istantanee (17 set 2026) ═══
# Il giro al minuto ha una latenza fino a sessanta secondi, su finestre
# da novecento. Qui il server tiene UNA connessione permanente al
# NOSTRO specchio (`relay.barattolo.store`) e reagisce al 38383 del
# coordinatore appena arriva.
# (DALLA PATCH 0007, 18 set 2026, ASCOLTA IL SOLO LIBRO: i kind 14 —
# le buste cifrate — non li guarda piu' nessuno, ne' qui ne' al minuto.
# A cosa serve ancora: a riempire SUBITO `p2p_ordini` coi numeri della
# presa, che la frase nata dall'evento di mostrod aspetta per pochi
# secondi (`P2P_RESPIRO_S`), e ad armare la riserva del libro.)
# LA PRIMA STESURA DI QUESTA SEZIONE DICEVA DI NO («un giro d'orologio,
# non una websocket lunga… un task che puo' morire in silenzio»), e
# aveva ragione sul rischio: la risposta non e' ignorarlo, sono le
# CINQUE REGOLE qui sotto. Il giro al minuto RESTA, identico: e' la
# rete di sicurezza, e l'ascolto e' solo un modo di farlo partire prima.
# 1) L'ASCOLTO NON GIUDICA NIENTE. Porta gli eventi in un MAZZETTO e
#    sveglia l'orologio, che li passa allo STESSO giro — stesso
#    giudice, stesso segnalibro. Un solo esecutore: niente lucchetti,
#    niente due strade che divergono.
# 2) IL MAZZETTO ASPETTA TRE SECONDI: mostro ripubblica il 38383 a
#    raffica quando un passo ne porta un altro, e raccolti insieme si
#    applicano in ordine di tempo, in una passata sola.
# 3) SOLO IL VIVO. Quel che il relay manda PRIMA dell'EOSE e' passato,
#    e il passato e' del giro al minuto (che ha il segnalibro): qui si
#    butta. Un evento caduto in un buco di connessione lo prende il
#    giro, entro un minuto.
# 4) LA CONNESSIONE CHE MUORE ZITTA e' il guasto da cui si e' partiti:
#    ogni 45 secondi l'ascolto manda una domandina e pretende l'EOSE
#    entro 10. Un socket aperto a meta' non risponde: si chiude e si
#    riprova, con l'attesa che cresce (5 s per caduta, tetto 60). Il
#    journal dice la caduta e la ripresa AL CAMBIO, e la riga della
#    passata dice lo stato ogni minuto.
# 5) IL CONTROLLO INCROCIATO: se il giro al minuto trova un evento che
#    l'ascolto — connesso da prima che nascesse — non ha portato, lo
#    scrive. E' il caso «specchio vivo, router fermo», che il polso da
#    solo non vede: il relay risponde, ma non gli arriva piu' niente.
# NESSUNA TRADE KEY NEL FILTRO: si chiede tutto quel che firma il
# coordinatore, e a chi e' indirizzato si guarda in tabella. Cosi' una
# chiave nuova non chiede di ri-sottoscrivere niente.
# E' UN THREAD E NON UN TASK perche' websocket-client e' sincrona, e
# una libreria asincrona sarebbe una dipendenza pip in piu' sul VPS.
P2P_MAZZETTO_S = 3            # quanto si aspetta per raccogliere una raffica
P2P_ASCOLTO_POLSO_S = 45      # ogni quanto la domandina
P2P_ASCOLTO_EOSE_S = 10       # entro quanto deve tornare l'EOSE
P2P_ASCOLTO_ATTESA_S = 5      # l'attesa prima di riprovare: per caduta, tetto 60
P2P_ASCOLTO_FERMO_S = 180     # il filo senza un segno: si abbandona e si rifa'
P2P_ASCOLTO_RITARDO_S = 20    # un evento piu' vecchio di cosi' l'ascolto doveva averlo portato
_P2P_ASCOLTO = {"filo": None, "ferma": None, "stato": "spento", "da": 0.0,
                "connesso_da": 0.0, "segno": 0.0, "polso": 0.0, "vivi": 0,
                "cadute": 0, "perche": "", "portati": {}, "detti": set()}
_P2P_MAZZETTO = {"libro": [], "timer": None}
_P2P_SVEGLIA = {"ev": None}   # l'asyncio.Event dell'orologio che gira ADESSO
_P2P_LAMPI = {"n": 0}


def _chiave_evento_p2p(tipo: str, dato) -> tuple:
    """Come si riconosce lo STESSO evento fra ascolto e giro: il 38383
    per (ordine, quando, stato) — il lettore il suo id non lo tiene.
    `tipo` e' rimasto nella firma, e vale sempre `libro`: dalla patch
    0007 l'ascolto non porta nient'altro."""
    return (tipo, dato["id"], dato["quando"], dato["stato"])


def _ascolto_porta(tipo: str, dati: list):
    """Gira NEL LOOP (ce la manda il filo con `call_soon_threadsafe`):
    mette nel mazzetto, segna il portato, e arma la sveglia se non e'
    gia' armata. Non giudica e non notifica."""
    adesso = time.time()
    for d in dati:
        _P2P_MAZZETTO[tipo].append(d)
        _P2P_ASCOLTO["portati"][_chiave_evento_p2p(tipo, d)] = adesso
    _P2P_ASCOLTO["vivi"] += 1
    portati = _P2P_ASCOLTO["portati"]
    if len(portati) > 5000:
        for k in sorted(portati, key=portati.get)[:2500]:
            del portati[k]
    if _P2P_MAZZETTO["timer"] is None:
        _P2P_MAZZETTO["timer"] = asyncio.get_running_loop().call_later(
            P2P_MAZZETTO_S, _mazzetto_sveglia)


def _mazzetto_sveglia():
    _P2P_MAZZETTO["timer"] = None
    if _P2P_SVEGLIA["ev"] is not None:
        _P2P_SVEGLIA["ev"].set()


def _mazzetto_prendi() -> list:
    """Svuota il mazzetto e lo consegna: i 38383 portati dall'ascolto."""
    libro = _P2P_MAZZETTO["libro"]
    _P2P_MAZZETTO["libro"] = []
    return libro


def _ascolto_mancato_p2p(tipo: str, dati: list, adesso: int):
    """IL CONTROLLO INCROCIATO, chiamato dal giro al minuto su quel che
    ha LETTO dai relay: un evento nato mentre l'ascolto era connesso,
    abbastanza vecchio da dover essere gia' arrivato, e che l'ascolto
    non ha portato. Si dice UNA volta per evento. Con l'ascolto giu'
    o spento non dice niente: li' parla gia' la riga dello stato."""
    da = _P2P_ASCOLTO["connesso_da"]
    if _P2P_ASCOLTO["stato"] != "connesso" or not da:
        return
    for d in dati:
        quando = d["quando"]
        if quando <= da + 5 or adesso - quando < P2P_ASCOLTO_RITARDO_S:
            continue
        k = _chiave_evento_p2p(tipo, d)
        if k in _P2P_ASCOLTO["portati"] or k in _P2P_ASCOLTO["detti"]:
            continue
        if len(_P2P_ASCOLTO["detti"]) > 5000:
            _P2P_ASCOLTO["detti"].clear()
        _P2P_ASCOLTO["detti"].add(k)
        cosa = f"il 38383 dell'ordine {str(d['id'])[:8]} ({d['stato']})"
        print(f"⚠️ Ascolto P2P: {cosa} l'ha trovato il giro al minuto e "
              f"NON l'ascolto, che era connesso ({adesso - quando}s dopo): "
              "lo specchio non l'ha ricevuto, o non lo copia", flush=True)


def _stato_ascolto_p2p() -> str:
    """Il pezzo di riga della passata: come sta l'ascolto ADESSO."""
    A = _P2P_ASCOLTO
    adesso = time.time()

    def fa(t):
        s = int(max(0, adesso - t))
        return f"{s}s" if s < 120 else f"{s // 60}m" if s < 7200 else f"{s // 3600}h"
    if A["stato"] == "connesso":
        polso = f", polso {fa(A['polso'])} fa" if A["polso"] else ""
        return f"connesso da {fa(A['connesso_da'])}, {A['vivi']} eventi vivi{polso}"
    if A["stato"] == "giu":
        return (f"GIU' da {fa(A['da'])} ({A['cadute']} tentativi): "
                f"{A['perche']}")
    if A["stato"] == "parte":
        return "in partenza"
    if A["stato"] == "simulato":
        return "spento: in collaudo lo specchio non e' di casa"
    return "spento (nessuno specchio nel config)"


def _ascolto_p2p_filo(relay: str, mostro: str, loop, ferma):
    """IL FILO: una connessione, tenuta viva, e rifatta quando cade.
    SINCRONO, in un thread suo (non nel pool del P2P: quello e' delle
    domande, e questo non finisce mai). Di ogni evento tiene quel che
    tengono i lettori — passa dagli stessi due estrattori — e lo manda
    nel loop; non giudica, non scrive sul database, non notifica.
    L'AUTORE SI RICONTROLLA QUI: il filtro lo chiede al relay, ma un
    relay e' un programma, e questa e' la porta da cui un 38383 fa
    partire «scambio concluso». (La firma non si verifica, come non la
    verificano i lettori al minuto: il relay e' il nostro.)
    `ferma` e' di QUESTO filo: quando il guardiano lo abbandona lo
    alza, e il filo non tocca piu' lo stato condiviso.
    In collaudo verso uno specchio che non e' di casa non parte
    nemmeno (vedi `lettura_simulata`): la guardia ha gia' chiesto
    prima di farlo nascere, e questa e' la sua, per chi lo facesse
    partire da un'altra parte."""
    A = _P2P_ASCOLTO
    if lettura_simulata(relay, "dell'ascolto P2P (38383)"):
        return
    while not ferma.is_set():
        ws = None
        try:
            A["segno"] = inizio = time.time()
            ws = create_connection(relay, timeout=10,
                                   sslopt=SSLOPT_RELAY)
            ws.settimeout(5)
            # IL SOLO LIBRO (patch 0007, 18 set 2026): le buste cifrate
            # non si guardano piu', nemmeno per sapere che esistono
            ws.send(json.dumps(["REQ", "ascolto", {
                "kinds": [38383], "authors": [mostro],
                "since": int(inizio)}]))
            vivo, polso_mandato, ultimo_polso = False, 0.0, inizio
            while not ferma.is_set():
                A["segno"] = time.time()
                try:
                    grezzo = ws.recv()
                except Exception as e:
                    # il timeout dei 5 secondi e' il BATTITO del filo,
                    # non un guasto: serve a guardare gli orologi
                    if "Timeout" not in type(e).__name__ \
                            and not isinstance(e, socket.timeout):
                        raise
                    grezzo = None
                adesso = time.time()
                msg = json.loads(grezzo) if grezzo else None
                if isinstance(msg, list) and len(msg) >= 2:
                    if msg[0] == "EOSE" and msg[1] == "ascolto" and not vivo:
                        vivo = True
                        dopo = (f" dopo {A['cadute']} tentativi"
                                if A["cadute"] else "")
                        A.update(stato="connesso", da=adesso,
                                 connesso_da=adesso, polso=0.0, cadute=0,
                                 perche="")
                        print(f"👂 Ascolto P2P connesso a {relay}{dopo}",
                              flush=True)
                    elif msg[0] == "EOSE" and msg[1] == "polso":
                        polso_mandato = 0.0
                        A["polso"] = adesso
                        ws.send(json.dumps(["CLOSE", "polso"]))
                    elif msg[0] == "CLOSED" and msg[1] == "ascolto":
                        raise RuntimeError(
                            f"sottoscrizione chiusa dal relay: {msg[2:]}")
                    elif (msg[0] == "EVENT" and msg[1] == "ascolto" and vivo
                          and len(msg) > 2 and isinstance(msg[2], dict)
                          and msg[2].get("pubkey") == mostro):
                        ev = msg[2]
                        if (ev.get("kind") == 38383
                                and not _firmato_dal_coordinatore(ev, mostro)):
                            print(f"⛔ Ascolto P2P: un 38383 da {relay} non e' "
                                  "firmato dal coordinatore: buttato", flush=True)
                        elif ev.get("kind") == 38383:
                            letto = _evento_libro_p2p(ev)
                            if letto:
                                loop.call_soon_threadsafe(
                                    _ascolto_porta, "libro", [letto])
                if not vivo and adesso - inizio > P2P_ASCOLTO_EOSE_S:
                    raise TimeoutError("nessun EOSE alla sottoscrizione")
                if polso_mandato and adesso - polso_mandato > P2P_ASCOLTO_EOSE_S:
                    raise TimeoutError(
                        f"il polso non e' tornato in {P2P_ASCOLTO_EOSE_S}s")
                if vivo and not polso_mandato \
                        and adesso - ultimo_polso >= P2P_ASCOLTO_POLSO_S:
                    ws.send(json.dumps(["REQ", "polso", {
                        "kinds": [38385], "authors": [mostro], "limit": 1}]))
                    polso_mandato = ultimo_polso = adesso
        except Exception as e:
            if ferma.is_set():
                break
            A["cadute"] += 1
            A["perche"] = f"{type(e).__name__}: {str(e)[:120]}"
            if A["stato"] != "giu":
                A.update(stato="giu", da=time.time(), connesso_da=0.0)
                print(f"👂 Ascolto P2P CADUTO ({A['perche']}): riprovo, e "
                      "intanto resta il giro al minuto", flush=True)
        finally:
            try:
                if ws is not None:
                    ws.close()
            except Exception:
                pass
        A["segno"] = time.time()
        ferma.wait(min(P2P_ASCOLTO_ATTESA_S * max(1, A["cadute"]), 60))


def _guardia_ascolto_p2p():
    """Lo sguardo del guardiano sull'ascolto, ogni P2P_GUARDIA_S: lo fa
    PARTIRE, e lo RIFA' se il filo e' morto o non da' un segno da piu'
    di P2P_ASCOLTO_FERMO_S. Un thread non si uccide: a quello fermo si
    alza la sua `ferma` e lo si abbandona (e' daemon, e se mai si
    sveglia esce da solo), e ne nasce uno nuovo. Senza specchio nel
    config l'ascolto non c'e', e si dice una volta."""
    import threading
    A = _P2P_ASCOLTO
    leve = _p2p_leve()
    if not leve["specchio"] or not create_connection:
        if A["stato"] != "spento-detto":
            A["stato"] = "spento-detto"
            print("👂 Ascolto P2P: nessuno specchio nel config "
                  "(MOSTRO_RELAY_SPECCHIO): resta il solo giro al minuto",
                  flush=True)
        return
    # IN COLLAUDO UNO SPECCHIO CHE NON E' DI CASA NON SI ASCOLTA (23 set
    # 2026, vedi `lettura_simulata`): e' come non averlo, e lo dice il
    # giudice, una volta. Il filo ha la sua guardia, ma e' questa che
    # conta: senza, la guardia vedrebbe il filo uscire e lo farebbe
    # ripartire a ogni sguardo, con un «MORTO» nel journal ogni volta.
    if lettura_simulata(leve["specchio"][0], "dell'ascolto P2P (38383)"):
        A["stato"] = "simulato"
        return
    adesso = time.time()
    filo = A["filo"]
    if filo is not None and filo.is_alive():
        if adesso - A["segno"] <= P2P_ASCOLTO_FERMO_S:
            return
        print(f"⚠️ Ascolto P2P FERMO da {int(adesso - A['segno'])}s: lo "
              "abbandono e ne faccio partire un altro", flush=True)
        A["ferma"].set()
    elif filo is not None:
        print("💥 Ascolto P2P MORTO (il filo e' uscito): riparte adesso",
              flush=True)
    relay = leve["specchio"][0]
    ferma = threading.Event()
    A.update(ferma=ferma, stato="parte", da=adesso, connesso_da=0.0,
             segno=adesso)
    A["filo"] = threading.Thread(
        target=_ascolto_p2p_filo, name="p2p-ascolto", daemon=True,
        args=(relay, leve["mostro"], asyncio.get_running_loop(), ferma))
    A["filo"].start()
    print(f"👂 Ascolto P2P: parte su {relay}", flush=True)


# ═══ LE ATTESE: gli avvisi che aspettano il loro minuto (patch 0007) ═══
# Due cose aspettano, e tutt'e due in tabella (`p2p_attese`), cosi' un
# deploy in mezzo non se le porta via:
# • LA RISERVA DEL LIBRO. Il libro legge presa, concluso, annullato,
#   scaduto e ritorno in vetrina, ma non parla subito: mette la sua
#   frase in attesa per `P2P_RISERVA_S`. Alla scadenza, se mostrod ha
#   raccontato LO STESSO momento di QUELL'ordine (`p2p_momenti`, a meno
#   di `P2P_STESSO_MOMENTO_S`), la frase si butta — il libro tace. Se
#   no parte lei: un evento perso costa un minuto, non un avviso.
# • IL RILASCIO. «Concluso» mostrod lo dice a pagamento RIUSCITO, e chi
#   vende ha finito il suo prima, quando rilascia. Se il pagamento a chi
#   compra si impianta (il 17 set 2026: tre tentativi, NO_ROUTE), a chi
#   vende non arrivava niente. Al rilascio gli si mette in attesa
#   «Sats in pagamento», la voce della sua card: se entro il minuto il
#   pagamento e' passato tace — «concluso» gliel'ha gia' detto il
#   `success` — se no parte, con la riga del pagamento non passato se
#   e' quello il caso. «Concluso» da qui NON parte piu' (23 set 2026):
#   finche' si diceva «per te e' concluso», chi vendeva lo leggeva su
#   uno scambio fermo per una fattura scaduta.
# L'ANTI-DOPPIONE E' UNO, e sta all'ULTIMO passo prima dell'invio: la
# riga in `p2p_avvisi` — stesso ordine, stesso momento, stessa persona,
# stesso giro — si scrive con INSERT OR IGNORE, e chi non riesce a
# scriverla non manda.


def eventi_p2p_attivi() -> bool:
    """La porta del coordinatore ESISTE? Il calco di `sconto_p2p_attivo`:
    senza segreto la rotta non c'e' (404), e il libro non aspetta
    nessuno — parla subito, com'era prima della patch 0007."""
    return bool(P2P_EVENTI_SEGRETO
                and not P2P_EVENTI_SEGRETO.startswith("INCOLLA"))


