async def _respiro_presa_p2p(ordine: str):
    """LA FRASE DELLA PRESA ASPETTA I SUOI NUMERI: l'evento di mostrod
    arriva un attimo prima che il libro mostri la presa (a prezzo di
    mercato i sats si fissano LI') e che il telefono di chi ha preso
    dichiari chi e'. Si guarda la riga ogni secondo: appena ci sono i
    numeri E il nome si parte; il nome si aspetta meno dei numeri, e
    chi entra da Nostr senza farsi riconoscere non lo dichiara mai. Un
    ordine che il libro non segue non ha niente da aspettare."""
    inizio = time.time()
    while time.time() - inizio < P2P_RESPIRO_S:
        con = db()
        try:
            r = con.execute("SELECT sats, stato, preso_da FROM p2p_ordini "
                            "WHERE ordine=?", (ordine,)).fetchone()
        finally:
            con.close()
        if not r:
            return
        numeri = int(r["sats"] or 0) > 0 and (r["stato"] or "") in STATI_LIBRO_PRESO
        if numeri and (int(r["preso_da"] or 0)
                       or time.time() - inizio >= P2P_RESPIRO_NOME_S):
            return
        await asyncio.sleep(1)


async def _manda_evento_p2p(ev: dict, fatto: dict):
    """L'invio, in un task suo: mostrod ha gia' avuto il suo 200 e non
    aspetta Telegram. Fail-open come le sorelle: un invio che va male e'
    una riga nel journal, mai un'eccezione che sale."""
    try:
        if fatto["momento"] == "preso":
            await _respiro_presa_p2p(ev["ordine"])
        con = db()
        try:
            avvisi = _avvisi_evento_p2p(con, ev, fatto, int(time.time()))
            # ...e a chi ha PUBBLICATO, sotto l'avviso della presa, il
            # bottone della pausa (12 ott 2026). Si decide QUI, sulle
            # sole parti: i moderatori qui sotto non lo vedono. Un
            # guasto li' toglie il bottone, mai l'avviso.
            try:
                bottoni = {tg: _bottone_pausa_p2p(con, ev, fatto, tg) for tg, _ in avvisi}
            except Exception:
                bottoni = {}
            # ...E SOTTO OGNI AVVISO ALLE PARTI «⚡ APRI LO SCAMBIO» (13 ott
            # 2026, cantiere notifica-porta-allo-scambio): il tocco porta
            # alla pagina di QUESTO scambio, dove c'e' il gesto da fare.
            # Sopra la pausa, dove c'e'. Anche questo sulle sole parti, e
            # un guasto lascia i bottoni com'erano: mai l'avviso in meno
            try:
                bottoni = _bottoni_evento_p2p(ev["ordine"], avvisi, bottoni)
            except Exception:
                pass
            # ...e la riga del PARACADUTE (13 ott 2026), sotto l'avviso
            # della presa a chi ha pubblicato: prima dei moderatori, che
            # non la vedono. Un guasto toglie la riga, mai l'avviso
            try:
                avvisi = _riga_paracadute_presa_p2p(avvisi, fatto)
            except Exception:
                pass
            # ...e la riga della RIPUBBLICA (16 nov 2026) nell'avviso della
            # scadenza, a chi aveva pubblicato: prima dei traduttori della
            # valuta qui sotto, che ne voltano il «€». Un guasto toglie la
            # riga, mai l'avviso
            try:
                avvisi = _riga_ripubblica_scadenza_p2p(avvisi, fatto)
            except Exception:
                pass
            # ...e IN USDT le parole dei soldi (2 nov 2026, usdt-due-reti):
            # alle sole parti, e un guasto lascia l'avviso com'era
            try:
                if p2p_usdt_ordine(con, ev["ordine"]):
                    avvisi = [(tg, p2p_usdt_frase(t)) for tg, t in avvisi]
                # ...e in franchi (14 nov 2026, cantiere p2p-chf)
                elif p2p_chf_ordine(con, ev["ordine"]):
                    avvisi = [(tg, p2p_chf_frase(t)) for tg, t in avvisi]
                # ...e con ETH, Monero o USDe (16 nov 2026, p2p-monete-ritocchi)
                elif p2p_coin_ordine(con, ev["ordine"]):
                    _moneta = p2p_coin_ordine(con, ev["ordine"])
                    # la riga della ripubblica resta in euro: BTC in moneta
                    # si misura in euro (16 nov 2026, ricevi-mercato)
                    avvisi = [(tg, _p2p_coin_frase_rip(t, _moneta)) for tg, t in avvisi]
            except Exception:
                pass
            # ...e i MODERATORI, se l'evento apre o chiude una disputa
            # (28 set 2026). Un guasto qui non toglie l'avviso alle parti.
            try:
                avvisi = avvisi + _disputa_evento_p2p(con, ev, fatto, int(time.time()))
            except Exception as e:
                print(f"⚠️ Disputa P2P {ev['ordine'][:8]}: avviso ai moderatori "
                      f"saltato ({type(e).__name__}: {e})", flush=True)
            # ...e a scambio CHIUSO le posizioni della prova d'incontro si
            # scordano (30 set 2026): una disputa non si puo' piu' aprire,
            # e il luogo non serve piu' a nessuno
            try:
                if fatto["momento"] in P2P_PRESENZA_MOMENTI_CHIUSI:
                    _scorda_posizioni_presenza_p2p(con, ev["ordine"], int(time.time()))
            except Exception as e:
                print(f"⚠️ Presenza P2P {ev['ordine'][:8]}: posizioni non scordate "
                      f"({type(e).__name__}: {e})", flush=True)
        finally:
            con.close()
        if fatto["momento"] == "rilasciato" and _P2P_SVEGLIA["ev"] is not None:
            # l'attesa di chi vende scade fra un minuto: l'orologio si
            # sveglia li', invece di aspettare il suo giro
            asyncio.get_running_loop().call_later(
                P2P_RISERVA_S + 0.5, _P2P_SVEGLIA["ev"].set)
        esiti = []
        for tg_id, testo in avvisi:
            try:
                # il bottone solo dove c'e' (None per tutti gli altri):
                # `_recapita_p2p` a `notifica()` lo passa solo allora
                esiti.append((tg_id, await _recapita_p2p(tg_id, testo, bottone=bottoni.get(tg_id))))
            except Exception as e:
                esiti.append((tg_id, f"SALTATO ({type(e).__name__}: {e})"))
            await asyncio.sleep(0.2)
        if avvisi:
            print(f"🛰️ Evento P2P: {ev['ordine'][:8]} «{fatto['momento']}»"
                  + (f"/{ev['dettaglio']}" if ev["dettaglio"] else "")
                  + f" da {ev['attore']} (giro {fatto['giro']}): avvisati "
                  f"{[t for t, _ in avvisi]}", flush=True)
            _esiti_p2p_dice("🛰️", esiti)
    except Exception as e:
        print(f"⚠️ Evento P2P {ev.get('ordine', '')[:8]} «{ev.get('azione')}»: "
              f"invio saltato ({type(e).__name__}: {e})", flush=True)


def _porta_eventi_p2p(autorizzazione: str) -> None:
    """404 a porta chiusa, 403 a segreto sbagliato: il calco di
    `_porta_sconto_p2p`. Confronto a tempo costante, e a BYTE
    (`compare_digest` su due str alza TypeError al primo carattere non
    ASCII, e un header lo scrive chi chiama)."""
    if not eventi_p2p_attivi():
        raise HTTPException(404, "Non trovato")
    atteso = ("Bearer " + P2P_EVENTI_SEGRETO).encode("utf-8")
    if not hmac.compare_digest(
            str(autorizzazione or "").encode("utf-8"), atteso):
        raise HTTPException(403, "Segreto sbagliato")


@app.post("/api/p2p/evento")
async def evento_p2p(req: Request):
    """Il coordinatore racconta un passo di uno scambio. La risposta
    parte SUBITO — mostrod non deve aspettare Telegram — e dice solo se
    l'evento era nuovo: a chi e' andato l'avviso lo dice il journal.
    `nuovo: false` e' il suo retry arrivato dopo un primo invio che era
    passato: tutto bene, e niente suona due volte.
    I giudici sono `_porta_eventi_p2p`, `_evento_p2p_pulito`,
    `_registra_evento_p2p` e `_avvisi_evento_p2p`."""
    _porta_eventi_p2p(req.headers.get("authorization", ""))
    try:
        d = await req.json()
    except Exception:
        raise HTTPException(400, "Richiesta illeggibile")
    adesso = int(time.time())
    con = db()
    try:
        ev = _evento_p2p_pulito(d, adesso)
        # col cambio di adesso, dalla cache: a una presa diventa il suo
        # metro (27 set 2026)
        fatto = _registra_evento_p2p(con, ev, adesso, cambio_noto_ora())
        # LA PRESA A PARACADUTE APERTO (13 ott 2026, cantiere paracadute):
        # si scrive adesso, alla presa, PRIMA degli esiti — e' la tutela
        # che gli esiti leggeranno. Mai un 500 per lei: l'evento e' gia'
        # registrato
        if fatto is not None:
            try:
                for riga in _segna_presa_paracadute_p2p(con, ev, fatto):
                    print(riga, flush=True)
            except Exception as e:
                print(f"⚠️ Paracadute P2P: la presa di {ev['ordine'][:8]} non si "
                      f"e' guardata ({type(e).__name__}: {e})", flush=True)
        # LA RIPUBBLICA ALLA SCADENZA (16 nov 2026, cantiere ripubblica):
        # si giudica adesso, col prezzo di adesso, e l'avviso della
        # scadenza porta la riga. Mai un 500 per lei
        if fatto is not None:
            try:
                _prezzi, _letto = _prezzi_ripubblica_p2p()
                for riga in _segna_scadenza_ripubblica_p2p(
                        con, ev, fatto, _prezzi, _letto, adesso):
                    print(riga, flush=True)
            except Exception as e:
                fatto["ripubblica"] = None
                print(f"⚠️ Ripubblica P2P: la scadenza di {ev['ordine'][:8]} non "
                      f"si e' guardata ({type(e).__name__}: {e})", flush=True)
        # GLI ESITI (10 ott 2026, reputazione-p2p): il completato alle due
        # parti, il non completato a chi ha preso e non ha fatto il suo
        # gesto. Mai un 500 per loro: l'evento e' gia' registrato
        if fatto is not None:
            try:
                for riga in _segna_esiti_p2p(
                        con, ev, _parti_per_esiti_p2p(con, ev, fatto, adesso), adesso):
                    print(riga, flush=True)
            except Exception as e:
                print(f"⚠️ Reputazione P2P: l'esito di {ev['ordine'][:8]} non si "
                      f"e' scritto ({type(e).__name__}: {e})", flush=True)
        # I SOLLECITI (10 ott 2026, «I SOLLECITI PER TUTTI I METODI»): a
        # chi compra dalla garanzia bloccata, a chi vende dal «pagato».
        # Come gli esiti: solo su un evento nuovo, e mai un 500 per loro
        if fatto is not None:
            try:
                for riga in _solleciti_evento_p2p(con, ev, fatto, adesso):
                    print(riga, flush=True)
            except Exception as e:
                print(f"⚠️ Solleciti P2P: le attese di {ev['ordine'][:8]} non si "
                      f"sono scritte ({type(e).__name__}: {e})", flush=True)
        # la garanzia morta non pagata: I PAGAMENTI CHE NON ARRIVANO. Mai
        # un 500 per lei: l'evento e' gia' registrato, e il retry di
        # mostrod troverebbe «ripetuto» e non avviserebbe le parti
        garanzia_morta = False
        if fatto is not None and ev["azione"] == "expired":
            try:
                garanzia_morta = _garanzia_mai_pagata_p2p(
                    con, ev["ordine"], fatto["giro"])
            except Exception as e:
                print(f"⚠️ Garanzia scaduta di {ev['ordine'][:8]} non "
                      f"guardata ({type(e).__name__}: {e})", flush=True)
    except ValueError as e:
        print(f"⚠️ Evento P2P rifiutato: {e}", flush=True)
        raise HTTPException(400, str(e))
    finally:
        con.close()
    if fatto is None:
        print(f"· Evento P2P: {ev['ordine'][:8]} «{ev['azione']}» ripetuto "
              "(il retry del coordinatore): gia' registrato", flush=True)
    else:
        t = asyncio.create_task(_manda_evento_p2p(ev, fatto))
        _TASK_EVENTI_P2P.add(t)
        t.add_done_callback(_TASK_EVENTI_P2P.discard)
        # ...e la fotografia del libro si rifa' subito (LA FOTOGRAFIA SUBITO)
        _foto_dopo_evento_p2p(ev)
        # ...e se questo passo ha chiuso lo scambio, la sua chat se ne
        # va adesso (LA CHAT NELLO SCAMBIO, 12 ott 2026)
        _chat_p2p_dopo_evento(ev["ordine"])
        if garanzia_morta:
            t = asyncio.create_task(segnala_fatture_scadute(
                "p2p", [f"{ev['ordine']}:{fatto['giro']}"]))
            _TASK_EVENTI_P2P.add(t)
            t.add_done_callback(_TASK_EVENTI_P2P.discard)
    return JSONResponse({"ok": True, "nuovo": fatto is not None},
                        headers={"Cache-Control": "no-store"})


# ---------- LA PROVA D'INCONTRO DEL CONTANTI DI PERSONA: «📍 SONO QUI» --
# (30 set 2026 col QR; rifatta il 1 ott 2026, decisione di Andrea dopo la
# prova vera). Una banconota non lascia ricevuta: in una disputa sul
# contanti il moderatore aveva una parola contro l'altra. Il 30 set era
# nato «🤝 Siamo insieme» — un telefono mostrava un QR firmato, l'altro lo
# inquadrava e controfirmava — ma alla prova vera il QR NON aggiungeva
# sicurezza: si inquadra anche da lontano, da una foto mandata in chat, e
# due firme nello stesso minuto non dicevano che i telefoni fossero
# vicini. Restava un rito a due che pareva una garanzia.
# ADESSO LE PRESENZE SONO DUE E INDIPENDENTI. Ognuno, quando arriva,
# tocca «📍 Sono qui»: il suo telefono firma con la chiave usa-e-getta
# dello scambio una nota (kind P2P_KIND_PRESENZA, tag `d` = ordine,
# `ruolo` = qui, nel contenuto un nonce e — se il telefono la da' — la
# posizione) e la manda qui. La firma si verifica (`verifica_firma_nostr`,
# id ricalcolato) contro le due chiavi che mostrod ha detto per il GIRO
# corrente (`p2p_scambi`): il lato lo dice la chiave, non chi carica, e
# un ordine tornato nel libro e ripreso da un altro e' un altro giro —
# le presenze di prima non le vede (la cura trovata dalla riverifica di
# sicurezza del 1 ott 2026). L'ORA CHE CONTA E' LA NOSTRA, all'arrivo,
# coi secondi: quella firmata dal telefono deve starle vicina
# (P2P_SONO_QUI_OROLOGIO_S) e resta accanto.
# IL CONFRONTO lo fa `_confronto_presenze_p2p` (puro) e lo legge il
# MODERATORE: «incontro probabile» se due presenze dei due lati stanno
# entro P2P_SONO_QUI_FINESTRA_S e i telefoni non risultano lontani; le
# PARTI vedono solo le due ore — la propria posizione si', quella
# dell'altro mai (`_presenze_per_parte_p2p`).
# L'APPUNTAMENTO: chi vende lo fissa nel recapito «📍 Dove vedervi», che
# viaggia cifrato fra i due telefoni; qui arriva in una nota SUA (`ruolo`
# = appuntamento) solo quel che serve al confronto — l'ora e, se
# l'indirizzo e' stato riconosciuto, le coordinate. Mai il testo. Le
# versioni restano tutte, e una presenza si confronta con l'appuntamento
# in vigore QUANDO e' arrivata: cambiarlo dopo l'incontro non sposta chi
# si era gia' presentato.
# IL GPS SI PUO' FALSIFICARE: la posizione e' una CONFERMA, non una
# prova assoluta, e le pagine lo dicono. Le posizioni, il punto e le
# copie delle note si SCORDANO quando lo scambio si chiude
# (`_manda_evento_p2p`) e comunque dopo P2P_PRESENZA_POSIZIONI_S; le
# DISTANZE si calcolano all'arrivo e restano, con le ore, finche' vive
# la cronaca (P2P_LIBRO_MEMORIA_S). MAI NEI LOG: nessuna riga di questo
# blocco stampa una coordinata. «Dimentica il profilo» toglie le mie
# presenze e i miei appuntamenti (`_dimentica_presenze_p2p`).
# LE PROVE COL QR GIA' NATE (`p2p_presenze`) restano leggibili dal
# moderatore, sul loro giro: la tabella non si scrive piu', si legge e si
# scopa.
# I GIUDICI SONO PURI SULLA CONNESSIONE e tornano `(codice, corpo)`,
# come quelli della moderazione. Il blocco sta FUORI da quello della
# moderazione apposta: la' una sentinella conta sette rotte e vieta la
# parola «firma(», e qui di firme si parla eccome (per verificarle).
P2P_KIND_PRESENZA = 27383
P2P_RUOLO_SONO_QUI = "qui"
P2P_RUOLO_APPUNTAMENTO = "appuntamento"
P2P_SONO_QUI_OROLOGIO_S = 300       # fra l'ora firmata dal telefono e la nostra
P2P_SONO_QUI_MAX = 5                # tocchi per lato e per giro
P2P_SONO_QUI_FINESTRA_S = 15 * 60   # due presenze cosi' vicine: incontro probabile
P2P_SONO_QUI_LONTANI_M = 500        # oltre (piu' le due precisioni): lontani
P2P_APPUNTAMENTO_FINESTRA_S = 30 * 60   # «all'ora dell'appuntamento»
P2P_APPUNTAMENTO_MAX = 10           # versioni per giro
P2P_APPUNTAMENTO_PASSATO_S = 3600   # un'ora gia' passata da piu' di cosi' non si fissa
P2P_APPUNTAMENTO_FUTURO_S = 7 * 86400   # ne' una oltre la vita di una garanzia
P2P_PRESENZA_POSIZIONI_S = 15 * 86400
# I MOMENTI CHE CHIUDONO LA PARTE IN CONTANTI: da `rilasciato` in poi chi
# vende ha gia' liberato i sats — cioe' i contanti li ha avuti — e una
# disputa sul pagamento dei sats (payout fallito) non ha niente da
# chiedere all'incontro; `concluso`, `annullato`, `scaduto` e `tornato`
# chiudono lo scambio; i due della disputa sono i passaggi del libro.
P2P_PRESENZA_MOMENTI_CHIUSI = ("rilasciato", "concluso", "annullato", "scaduto", "tornato",
                               "disputa_conclusa", "disputa_annullata")


def _tag_presenza_p2p(ev, nome: str) -> str:
    """PURA: il valore del primo tag `nome` di un evento, o ''."""
    for t in (ev.get("tags") or []) if isinstance(ev, dict) else []:
        if isinstance(t, list) and len(t) >= 2 and t[0] == nome:
            return str(t[1])
    return ""


def _geo_presenza_p2p(v):
    """PURA: una posizione `{lat, lon, acc}` coi numeri in misura, o None
    — una posizione storta non e' un errore, e' una nota senza posizione."""
    if not isinstance(v, dict):
        return None
    try:
        lat, lon = float(v.get("lat")), float(v.get("lon"))
        acc = float(v.get("acc") or 0)
    except (TypeError, ValueError):
        return None
    if any(isinstance(v.get(k), bool) for k in ("lat", "lon", "acc")):
        return None
    if any(math.isnan(x) or math.isinf(x) for x in (lat, lon, acc)):
        return None
    if not (-90 <= lat <= 90 and -180 <= lon <= 180 and 0 <= acc <= 100000):
        return None
    return {"lat": round(lat, 5), "lon": round(lon, 5), "acc": int(round(acc))}


def _distanza_metri_p2p(a, b) -> int:
    """PURA: la distanza in metri fra due posizioni (haversine)."""
    r = 6371000.0
    la1, la2 = math.radians(a["lat"]), math.radians(b["lat"])
    dla = la2 - la1
    dlo = math.radians(b["lon"] - a["lon"])
    h = math.sin(dla / 2) ** 2 + math.cos(la1) * math.cos(la2) * math.sin(dlo / 2) ** 2
    return int(round(2 * r * math.asin(min(1.0, math.sqrt(h)))))


def _tabella_p2p(con, nome: str) -> bool:
    """C'e' la tabella? I banchi di ieri non l'hanno, e per loro vale
    «nessuna prova» — mai un errore sulla pagina degli scambi o sulla
    card del moderatore."""
    return bool(con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                            (nome,)).fetchone())


def _nota_p2p(ev, ordine: str, ruolo: str) -> dict:
    """PURA: una nota del contanti — una presenza o un appuntamento —
    come la manda il telefono, verificata: firma vera (id ricalcolato),
    kind giusto, ordine giusto, il RUOLO che questo gesto si aspetta,
    contenuto leggibile alla versione 1. ValueError con la frase, mai un
    400 diretto: la prova non ha bisogno di FastAPI. Il ruolo atteso e'
    la guardia contro lo scambio di note: una presenza non passa per un
    appuntamento, ne' una nota del QR di ieri per una presenza."""
    if not isinstance(ev, dict):
        raise ValueError("Nota illeggibile")
    if not verifica_firma_nostr(ev):
        raise ValueError("La firma della nota non torna")
    if ev.get("kind") != P2P_KIND_PRESENZA:
        raise ValueError("Non e' una nota dello scambio in contanti")
    if _tag_presenza_p2p(ev, "d") != ordine:
        raise ValueError("La nota parla di un altro scambio")
    if _tag_presenza_p2p(ev, "ruolo") != ruolo:
        raise ValueError("Questa nota non e' quella di questo gesto")
    try:
        c = json.loads(ev.get("content") or "")
    except ValueError:
        raise ValueError("Contenuto illeggibile")
    if not isinstance(c, dict) or c.get("v") != 1:
        raise ValueError("Versione della nota sconosciuta")
    return {"pubkey": ev["pubkey"], "ora": int(ev["created_at"]), "id": ev["id"], "c": c}


def _chiavi_giro_p2p(con, ordine: str):
    """Il giro corrente e le due chiavi che mostrod ha detto per
    l'ordine: `(giro, {"compra": chiave, "vende": chiave})`, o None se
    il coordinatore non le ha ancora dette tutt'e due."""
    s = con.execute("SELECT giro, chiave_compratore, chiave_venditore FROM p2p_scambi "
                    "WHERE ordine=?", (ordine,)).fetchone()
    if not s or not s["chiave_compratore"] or not s["chiave_venditore"]:
        return None
    return int(s["giro"] or 0), {"compra": s["chiave_compratore"], "vende": s["chiave_venditore"]}


def _contanti_chiuso_p2p(con, ordine: str, giro: int) -> bool:
    """La parte in contanti di QUESTO giro e' chiusa? Un momento di
    P2P_PRESENZA_MOMENTI_CHIUSI in un giro precedente non conta: e' un
    altro scambio."""
    segni = ",".join("?" for _ in P2P_PRESENZA_MOMENTI_CHIUSI)
    return bool(con.execute(
        f"SELECT 1 FROM p2p_momenti WHERE ordine=? AND giro=? AND momento IN ({segni})",
        (ordine, giro) + tuple(P2P_PRESENZA_MOMENTI_CHIUSI)).fetchone())


def _appuntamento_in_vigore_p2p(con, ordine: str, giro: int, istante: int):
    """L'ultima versione dell'appuntamento nata entro `istante`, o None."""
    if not _tabella_p2p(con, "p2p_appuntamenti"):
        return None
    return con.execute(
        "SELECT * FROM p2p_appuntamenti WHERE ordine=? AND giro=? AND quando<=? "
        "ORDER BY quando DESC, id DESC LIMIT 1", (ordine, giro, int(istante))).fetchone()


def _presenze_per_parte_p2p(con, ordine: str, giro: int, lato: str):
    """Le presenze del giro come le vede UNA delle due parti (`lato` =
    'compra' | 'vende'): la mia ultima — l'ora, se il telefono ha dato
    la posizione, quante volte l'ho segnata — e l'ultima dell'altra
    parte, SOLO l'ora. Mai una coordinata, mai una distanza: quelle sono
    del moderatore. None quando non c'e' niente da dire."""
    if lato not in ("compra", "vende") or not _tabella_p2p(con, "p2p_sono_qui"):
        return None
    righe = con.execute("SELECT lato, ora, posizione FROM p2p_sono_qui WHERE ordine=? "
                        "AND giro=? ORDER BY ora, id", (ordine, int(giro))).fetchall()
    mie = [r for r in righe if r["lato"] == lato]
    altre = [r for r in righe if r["lato"] != lato]
    if not mie and not altre:
        return None
    return {"mia": ({"ora": int(mie[-1]["ora"]), "posizione": bool(mie[-1]["posizione"]),
                     "volte": len(mie)} if mie else None),
            "altra": ({"ora": int(altre[-1]["ora"])} if altre else None)}


def _registra_sono_qui_p2p(con, io, d, adesso: int) -> tuple:
    """«📍 SONO QUI», giudicato: `(codice, corpo)`. La nota si verifica
    (firma, ordine, ruolo, orologio), poi contro lo SCAMBIO: la chiave e'
    una delle due che mostrod ha detto per il giro corrente — e dice il
    lato —, e la parte in contanti di questo giro non e' chiusa. Una riga
    per tocco, fino a P2P_SONO_QUI_MAX per lato. Le distanze si calcolano
    QUI, all'arrivo: dal punto dell'appuntamento in vigore e dalle
    presenze dell'altro lato gia' arrivate; restano quando le posizioni se
    ne vanno. Chi carica e' irrilevante: a provare e' la firma."""
    if not isinstance(d, dict):
        return 400, "Richiesta illeggibile"
    ordine = str(d.get("ordine") or "").strip()
    if not FORMA_ORDINE_P2P.fullmatch(ordine):
        return 400, "Ordine in una forma sconosciuta"
    try:
        n = _nota_p2p(d.get("nota"), ordine, P2P_RUOLO_SONO_QUI)
    except ValueError as e:
        return 400, str(e)
    if abs(int(adesso) - n["ora"]) > P2P_SONO_QUI_OROLOGIO_S:
        return 400, "L'orologio del telefono e' troppo lontano dal nostro: controlla data e ora"
    detto = _chiavi_giro_p2p(con, ordine)
    if detto is None:
        return 409, ("Il coordinatore non ha ancora detto le due chiavi di questo "
                     "scambio: riprova fra un minuto")
    giro, chiavi = detto
    lato = "compra" if n["pubkey"] == chiavi["compra"] else (
        "vende" if n["pubkey"] == chiavi["vende"] else "")
    if not lato:
        return 403, "La firma non e' di una delle due chiavi di questo scambio"
    if _contanti_chiuso_p2p(con, ordine, giro):
        return 409, "Questo scambio e' chiuso: la presenza non serve piu'"
    fatte = con.execute("SELECT COUNT(*) FROM p2p_sono_qui WHERE ordine=? AND giro=? AND lato=?",
                        (ordine, giro, lato)).fetchone()[0]
    if fatte >= P2P_SONO_QUI_MAX:
        return 429, f"Hai gia' segnato la presenza {P2P_SONO_QUI_MAX} volte in questo scambio"
    geo = _geo_presenza_p2p(n["c"].get("geo"))
    app = _appuntamento_in_vigore_p2p(con, ordine, giro, adesso)
    dist_luogo = None
    if geo and app is not None and app["lat"] is not None and app["lon"] is not None:
        dist_luogo = _distanza_metri_p2p(geo, {"lat": app["lat"], "lon": app["lon"]})
    vicine = {}
    if geo:
        for r in con.execute("SELECT id, lat, lon FROM p2p_sono_qui WHERE ordine=? AND giro=? "
                             "AND lato<>? AND lat IS NOT NULL AND lon IS NOT NULL",
                             (ordine, giro, lato)):
            vicine[str(r["id"])] = _distanza_metri_p2p(geo, {"lat": r["lat"], "lon": r["lon"]})
    con.execute(
        "INSERT INTO p2p_sono_qui(ordine, giro, lato, chiave, ora, ora_firmata, lat, lon, acc, "
        "posizione, posizione_via, appuntamento, dist_luogo, vicine, prova, caricata_da) "
        "VALUES(?,?,?,?,?,?,?,?,?,?,0,?,?,?,?,?)",
        (ordine, giro, lato, n["pubkey"], int(adesso), n["ora"],
         geo["lat"] if geo else None, geo["lon"] if geo else None, geo["acc"] if geo else None,
         int(bool(geo)), int(app["id"]) if app is not None else 0, dist_luogo,
         json.dumps(vicine, separators=(",", ":")) if vicine else "",
         json.dumps(d.get("nota"), separators=(",", ":"), ensure_ascii=False),
         int(io or 0)))
    con.commit()
    return 200, {"ok": True, "ora": int(adesso), "posizione": bool(geo), "giro": giro,
                 "presenze": _presenze_per_parte_p2p(con, ordine, giro, lato)}


def _registra_appuntamento_p2p(con, io, d, adesso: int) -> tuple:
    """L'APPUNTAMENTO, giudicato: `(codice, corpo)`. La nota e' di CHI
    VENDE (la sua chiave del giro corrente: e' lui a scriverlo nel
    recapito), l'ora e' 0 (non detta) o in misura, il punto e'
    facoltativo. A scambio chiuso o a disputa aperta non si cambia piu'.
    Una versione uguale all'ultima non ne fa una nuova (`gia`); oltre
    P2P_APPUNTAMENTO_MAX versioni, no."""
    if not isinstance(d, dict):
        return 400, "Richiesta illeggibile"
    ordine = str(d.get("ordine") or "").strip()
    if not FORMA_ORDINE_P2P.fullmatch(ordine):
        return 400, "Ordine in una forma sconosciuta"
    try:
        n = _nota_p2p(d.get("nota"), ordine, P2P_RUOLO_APPUNTAMENTO)
    except ValueError as e:
        return 400, str(e)
    if abs(int(adesso) - n["ora"]) > P2P_SONO_QUI_OROLOGIO_S:
        return 400, "L'orologio del telefono e' troppo lontano dal nostro: controlla data e ora"
    ora = n["c"].get("ora")
    if isinstance(ora, bool) or not isinstance(ora, int) or ora < 0:
        return 400, "L'ora dell'incontro e' illeggibile"
    if ora and not (int(adesso) - P2P_APPUNTAMENTO_PASSATO_S <= ora
                    <= int(adesso) + P2P_APPUNTAMENTO_FUTURO_S):
        return 400, "L'ora dell'incontro e' fuori misura: gia' passata, o troppo lontana"
    punto = _geo_presenza_p2p(n["c"].get("geo"))
    detto = _chiavi_giro_p2p(con, ordine)
    if detto is None:
        return 409, ("Il coordinatore non ha ancora detto le due chiavi di questo "
                     "scambio: riprova fra un minuto")
    giro, chiavi = detto
    if n["pubkey"] != chiavi["vende"]:
        return 403, "L'appuntamento lo fissa chi vende, con la sua chiave di questo scambio"
    if _contanti_chiuso_p2p(con, ordine, giro):
        return 409, "Questo scambio e' chiuso: l'appuntamento non serve piu'"
    if con.execute("SELECT 1 FROM p2p_momenti WHERE ordine=? AND giro=? AND momento='disputa'",
                   (ordine, giro)).fetchone():
        return 409, "La disputa e' aperta: l'appuntamento non si cambia piu'"
    ultimo = con.execute("SELECT ora_incontro, lat, lon FROM p2p_appuntamenti WHERE ordine=? "
                         "AND giro=? ORDER BY quando DESC, id DESC LIMIT 1",
                         (ordine, giro)).fetchone()
    lat, lon = (punto["lat"], punto["lon"]) if punto else (None, None)
    if ultimo and int(ultimo["ora_incontro"] or 0) == ora \
            and ultimo["lat"] == lat and ultimo["lon"] == lon:
        return 200, {"ok": True, "gia": True}
    versioni = con.execute("SELECT COUNT(*) FROM p2p_appuntamenti WHERE ordine=? AND giro=?",
                           (ordine, giro)).fetchone()[0]
    if versioni >= P2P_APPUNTAMENTO_MAX:
        return 429, "L'appuntamento e' gia' cambiato troppe volte in questo scambio"
    con.execute(
        "INSERT INTO p2p_appuntamenti(ordine, giro, chiave, ora_incontro, lat, lon, punto, "
        "posizione_via, prova, caricata_da, quando) VALUES(?,?,?,?,?,?,?,0,?,?,?)",
        (ordine, giro, n["pubkey"], ora, lat, lon, int(bool(punto)),
         json.dumps(d.get("nota"), separators=(",", ":"), ensure_ascii=False),
         int(io or 0), int(adesso)))
    con.commit()
    return 200, {"ok": True, "gia": False}


def _confronto_presenze_p2p(presenze: list, appuntamenti: list) -> dict:
    """PURA: il confronto che legge il MODERATORE. `presenze` sono le
    righe del giro (dict con id, lato, ora, posizione, posizione_via,
    acc, appuntamento, dist_luogo, vicine), `appuntamenti` le versioni
    del giro (dict con id, ora_incontro, punto, quando).
    L'ESITO: con le presenze dei due lati si sceglie UNA COPPIA, e la
    scelta dice la prova piu' forte che c'e': dentro
    P2P_SONO_QUI_FINESTRA_S prima una coppia coi telefoni vicini e la
    distanza nota, poi una senza posizione, poi una coi telefoni lontani
    (oltre P2P_SONO_QUI_LONTANI_M piu' le due precisioni); fuori dalla
    finestra la piu' vicina nel tempo. A pari grado la piu' vicina nel
    tempo, poi la piu' recente. Si puo' ripremere apposta — chi ha
    toccato a casa per sbaglio lo rifa' all'incontro —, e il tocco di
    casa non deve coprire quello giusto. L'esito: «probabile» (vicini, o
    senza distanza), «lontani», «ore_diverse». Con un lato solo
    e' «solo_compra» o «solo_vende» (la presenza piu' vicina all'ora
    dell'appuntamento, o l'ultima), senza nessuna «nessuna».
    L'APPUNTAMENTO di ogni presenza e' quello in vigore QUANDO e'
    arrivata (`appuntamento`, l'id della versione): «all'ora» entro
    P2P_APPUNTAMENTO_FINESTRA_S, e la distanza dal luogo calcolata
    all'arrivo. In testa quello in vigore alla prima presenza scelta (o
    l'ultimo), con quante versioni ci sono state e se e' cambiato DOPO.
    LA REGOLA DELLA DISPUTA che vale per il caso (`regola`, 1 ott 2026,
    precisata da Andrea): «incontro» se la prova c'e' (probabile);
    «decide_moderatore» se chi compra ha segnato la presenza ALL'ORA e
    VICINO AL LUOGO dell'appuntamento e chi vende no — una qualunque delle
    sue presenze, e «chi vende no» vuol dire nessuna delle sue cosi':
    allora la disputa non va in automatico a chi vende; altrimenti
    «senza_prova», cioe' se chi vende dice di non aver ricevuto i
    contanti si da' ragione a lui. Vicino vuol dire entro
    P2P_SONO_QUI_LONTANI_M piu' la precisione di quella presenza, la
    stessa misura di «lontani»; senza posizione o senza il punto del
    luogo non si puo' dire, e vale la regola di sempre."""
    def di(lato):
        return [p for p in presenze if p.get("lato") == lato]

    versioni = {int(a["id"]): a for a in appuntamenti}

    def coppia_dist(a, b):
        tardi, presto = (a, b) if int(a["id"]) > int(b["id"]) else (b, a)
        try:
            v = json.loads(tardi.get("vicine") or "{}")
        except ValueError:
            v = {}
        x = v.get(str(int(presto["id"]))) if isinstance(v, dict) else None
        return int(x) if isinstance(x, (int, float)) and not isinstance(x, bool) else None

    def rispetto(p):
        a = versioni.get(int(p.get("appuntamento") or 0))
        if a is None:
            return None
        ora_app = int(a.get("ora_incontro") or 0)
        scarto = int(p["ora"]) - ora_app if ora_app else None
        dist = p.get("dist_luogo")
        return {"ora": ora_app, "scarto_s": scarto,
                "all_ora": (abs(scarto) <= P2P_APPUNTAMENTO_FINESTRA_S) if scarto is not None else None,
                "dist_luogo": int(dist) if dist is not None else None}

    def al_luogo(p):
        r = rispetto(p)
        return bool(r and r["all_ora"] and r["dist_luogo"] is not None
                    and r["dist_luogo"] <= P2P_SONO_QUI_LONTANI_M + int(p.get("acc") or 0))

    def vista(p, tutte):
        return {"ora": int(p["ora"]), "posizione": bool(p.get("posizione")),
                "acc": (int(p["acc"]) if p.get("acc") is not None else None),
                "volte": len(tutte), "appuntamento": rispetto(p)}

    def lontani(c, v, dist):
        return dist is not None and dist > P2P_SONO_QUI_LONTANI_M + int(c.get("acc") or 0) \
            + int(v.get("acc") or 0)

    def grado(cv):
        c, v = cv
        scarto, dist = abs(int(c["ora"]) - int(v["ora"])), coppia_dist(c, v)
        g = (3 if scarto > P2P_SONO_QUI_FINESTRA_S else 2 if lontani(c, v, dist)
             else 1 if dist is None else 0)
        return (g, scarto, -max(int(c["ora"]), int(v["ora"])))

    compra, vende = di("compra"), di("vende")
    fuori = {"esito": "nessuna", "compra": None, "vende": None, "scarto_s": None,
             "distanza": None,
             "posizioni_via": any(p.get("posizione_via") for p in presenze),
             "appuntamento": None}
    scelte = []
    if compra and vende:
        c, v = min(((c, v) for c in compra for v in vende), key=grado)
        scarto = abs(int(c["ora"]) - int(v["ora"]))
        dist = coppia_dist(c, v)
        fuori.update(compra=vista(c, compra), vende=vista(v, vende), scarto_s=scarto, distanza=dist)
        if scarto > P2P_SONO_QUI_FINESTRA_S:
            fuori["esito"] = "ore_diverse"
        elif lontani(c, v, dist):
            fuori["esito"] = "lontani"
        else:
            fuori["esito"] = "probabile"
        scelte = [c, v]
    elif compra or vende:
        lato, tutte = ("compra", compra) if compra else ("vende", vende)

        def chiave(p):
            r = rispetto(p)
            if r and r["scarto_s"] is not None:
                return (0, abs(r["scarto_s"]), -int(p["ora"]))
            return (1, 0, -int(p["ora"]))
        p = min(tutte, key=chiave)
        fuori.update({"esito": "solo_" + lato, lato: vista(p, tutte)})
        scelte = [p]
    if appuntamenti:
        prima = min((int(p["ora"]) for p in scelte), default=None)
        in_vigore = None
        if prima is not None:
            prima_p = min(scelte, key=lambda p: int(p["ora"]))
            in_vigore = versioni.get(int(prima_p.get("appuntamento") or 0))
        if in_vigore is None:
            in_vigore = max(appuntamenti, key=lambda a: (int(a["quando"]), int(a["id"])))
        fuori["appuntamento"] = {
            "ora": int(in_vigore.get("ora_incontro") or 0), "punto": bool(in_vigore.get("punto")),
            "versioni": len(appuntamenti),
            "cambiato_dopo": prima is not None and any(int(a["quando"]) > prima for a in appuntamenti)}
    if fuori["esito"] == "probabile":
        fuori["regola"] = "incontro"
    elif any(al_luogo(p) for p in compra) and not any(al_luogo(p) for p in vende):
        fuori["regola"] = "decide_moderatore"
    else:
        fuori["regola"] = "senza_prova"
    return fuori


def _confronto_giro_p2p(con, ordine: str, giro: int):
    """Il confronto del moderatore per un giro, dalle due tabelle; None
    quando non c'e' ne' una presenza ne' un appuntamento (o le tabelle)."""
    if not _tabella_p2p(con, "p2p_sono_qui") or not _tabella_p2p(con, "p2p_appuntamenti"):
        return None
    presenze = [dict(r) for r in con.execute(
        "SELECT id, lato, ora, posizione, posizione_via, acc, appuntamento, dist_luogo, vicine "
        "FROM p2p_sono_qui WHERE ordine=? AND giro=? ORDER BY id", (ordine, int(giro)))]
    appuntamenti = [dict(r) for r in con.execute(
        "SELECT id, ora_incontro, punto, quando FROM p2p_appuntamenti WHERE ordine=? AND giro=? "
        "ORDER BY id", (ordine, int(giro)))]
    if not presenze and not appuntamenti:
        return None
    return _confronto_presenze_p2p(presenze, appuntamenti)


def _incontro_da_riga_p2p(r) -> dict:
    """PURA: una riga di `p2p_presenze` — la prova COL QR, di prima del 1
    ott 2026 — come la legge il moderatore. `distanza` in metri o None;
    `precisione` la peggiore delle due, finche' le posizioni ci sono."""
    acc = [x for x in (r["acc_mostra"], r["acc_legge"]) if x is not None]
    return {"ora": int(r["ora_legge"] or 0),
            "distanza": (int(r["distanza_m"]) if r["distanza_m"] is not None else None),
            "posizioni": int(r["posizioni"] or 0),
            "precisione": (int(max(acc)) if acc else None),
            "posizioni_via": bool(r["posizioni_via"])}


def _incontro_p2p(con, ordine: str, giro: int):
    """La prova COL QR di un ordine, SUL SUO GIRO, o None (la cura della
    riverifica di sicurezza del 1 ott 2026: un ordine tornato nel libro e
    ripreso da un altro e' un altro incontro, e la prova di prima — di
    altre persone — non deve dire «confermato» a questo). Senza la
    tabella vale None."""
    if not _tabella_p2p(con, "p2p_presenze"):
        return None
    r = con.execute("SELECT * FROM p2p_presenze WHERE ordine=? AND giro=?",
                    (ordine, int(giro))).fetchone()
    return _incontro_da_riga_p2p(r) if r else None


def _scorda_posizioni_presenza_p2p(con, ordine: str, adesso: int) -> int:
    """Lo scambio si e' chiuso: le posizioni, il punto dell'appuntamento e
    le copie delle note (che li portano) se ne vanno; le ore, le distanze
    gia' calcolate e le chiavi restano. Torna quante righe ha toccato."""
    n = 0
    if _tabella_p2p(con, "p2p_presenze"):
        n += con.execute(
            "UPDATE p2p_presenze SET lat_mostra=NULL, lon_mostra=NULL, acc_mostra=NULL, "
            "lat_legge=NULL, lon_legge=NULL, acc_legge=NULL, prova='', posizioni_via=? "
            "WHERE ordine=? AND posizioni_via=0", (int(adesso), ordine)).rowcount
    if _tabella_p2p(con, "p2p_sono_qui"):
        n += con.execute(
            "UPDATE p2p_sono_qui SET lat=NULL, lon=NULL, prova='', posizione_via=? "
            "WHERE ordine=? AND posizione_via=0", (int(adesso), ordine)).rowcount
    if _tabella_p2p(con, "p2p_appuntamenti"):
        n += con.execute(
            "UPDATE p2p_appuntamenti SET lat=NULL, lon=NULL, prova='', posizione_via=? "
            "WHERE ordine=? AND posizione_via=0", (int(adesso), ordine)).rowcount
    con.commit()
    return n


def _scopa_presenze_p2p(con, adesso: int) -> int:
    """La rete di sicurezza della privacy: posizioni e punti piu' vecchi di
    P2P_PRESENZA_POSIZIONI_S si scordano anche se l'evento di chiusura
    non e' mai arrivato, e le righe intere se ne vanno con la cronaca
    (P2P_LIBRO_MEMORIA_S). Non fa commit: e' `_pulisci_memoria_p2p` a farlo."""
    vecchie, morte = int(adesso) - P2P_PRESENZA_POSIZIONI_S, int(adesso) - P2P_LIBRO_MEMORIA_S
    n = 0
    if _tabella_p2p(con, "p2p_presenze"):
        n += con.execute(
            "UPDATE p2p_presenze SET lat_mostra=NULL, lon_mostra=NULL, acc_mostra=NULL, "
            "lat_legge=NULL, lon_legge=NULL, acc_legge=NULL, prova='', posizioni_via=? "
            "WHERE posizioni_via=0 AND quando<?", (int(adesso), vecchie)).rowcount
        n += con.execute("DELETE FROM p2p_presenze WHERE quando<?", (morte,)).rowcount
    if _tabella_p2p(con, "p2p_sono_qui"):
        n += con.execute(
            "UPDATE p2p_sono_qui SET lat=NULL, lon=NULL, prova='', posizione_via=? "
            "WHERE posizione_via=0 AND ora<?", (int(adesso), vecchie)).rowcount
        n += con.execute("DELETE FROM p2p_sono_qui WHERE ora<?", (morte,)).rowcount
    if _tabella_p2p(con, "p2p_appuntamenti"):
        n += con.execute(
            "UPDATE p2p_appuntamenti SET lat=NULL, lon=NULL, prova='', posizione_via=? "
            "WHERE posizione_via=0 AND quando<?", (int(adesso), vecchie)).rowcount
        n += con.execute("DELETE FROM p2p_appuntamenti WHERE quando<?", (morte,)).rowcount
    # ...e gli scambi on-chain chiusi scordano le posizioni (17 nov 2026)
    n += _p2p_onchain_scorda_incontri(con, adesso)
    return n


def _dimentica_presenze_p2p(con, io: int, chiavi, adesso: int) -> int:
    """«Dimentica il profilo» toglie anche le prove d'incontro (1 ott
    2026, la seconda cura della riverifica di sicurezza): le presenze e
    gli appuntamenti firmati con una delle MIE chiavi, o caricati da me,
    se ne vanno. ⚠️ CON UNA ECCEZIONE, ed e' contro la frode: su uno
    scambio la cui parte in contanti e' ANCORA APERTA della riga restano
    l'ora e il lato — la posizione, il punto e la copia della nota se ne
    vanno subito, come alla chiusura —, perche' altrimenti chi ha segnato
    «Sono qui», incassato i contanti e negato di averli avuti cancellerebbe
    con un tocco la presenza che l'altra persona ha visto nella sua
    pagina. Il resto se ne va quando lo scambio si chiude, con la scopa.
    Delle prove col QR di ieri, che portano anche la firma dell'altra
    persona, si scordano le posizioni e la copia delle note. Si chiama
    PRIMA di cancellare le chiavi: sono loro a dire quali righe sono mie.
    Torna quante righe ha toccato; senza le tabelle zero."""
    chiavi = sorted({str(k) for k in (chiavi or []) if k})
    io = int(io or 0)
    n = 0
    for tabella, colonne in (("p2p_sono_qui", ("chiave",)), ("p2p_appuntamenti", ("chiave",)),
                             ("p2p_presenze", ("chiave_mostra", "chiave_legge"))):
        if not _tabella_p2p(con, tabella):
            continue
        for i in range(0, max(1, len(chiavi)), 200):
            fetta = chiavi[i:i + 200]
            dove = " OR ".join(
                [f"{c} IN ({','.join('?' for _ in fetta)})" for c in colonne if fetta]
                + (["caricata_da=?"] if io else []))
            if not dove:
                continue
            arg = [x for c in colonne if fetta for x in fetta] + ([io] if io else [])
            righe = con.execute(f"SELECT rowid, ordine, giro FROM {tabella} WHERE {dove}",
                                arg).fetchall()
            for r in righe:
                if tabella != "p2p_presenze" and \
                        _contanti_chiuso_p2p(con, r["ordine"], int(r["giro"] or 0)):
                    n += con.execute(f"DELETE FROM {tabella} WHERE rowid=?", (r[0],)).rowcount
                elif tabella == "p2p_presenze":
                    n += con.execute(
                        "UPDATE p2p_presenze SET lat_mostra=NULL, lon_mostra=NULL, "
                        "acc_mostra=NULL, lat_legge=NULL, lon_legge=NULL, acc_legge=NULL, "
                        "prova='', posizioni_via=? WHERE rowid=? AND posizioni_via=0",
                        (int(adesso), r[0])).rowcount
                else:
                    n += con.execute(
                        f"UPDATE {tabella} SET lat=NULL, lon=NULL, prova='', posizione_via=? "
                        "WHERE rowid=? AND posizione_via=0", (int(adesso), r[0])).rowcount
    return n


@app.post("/api/p2p/sono-qui")
async def sono_qui_p2p(req: Request, x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """«📍 Sono qui»: la presenza firmata di una delle due parti. Chiunque
    sia riconosciuto puo' caricarla: a provare e' la firma, e il lato lo
    dice la chiave. Il corpo non si stampa mai: porta una posizione."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    d = await leggi_json(req)
    con = db()
    try:
        codice, corpo = _registra_sono_qui_p2p(con, user["id"], d, int(time.time()))
    finally:
        con.close()
    return _risposta_moderazione(codice, corpo)


@app.post("/api/p2p/appuntamento")
async def appuntamento_p2p(req: Request, x_tg_init_data: str = Header(""),
                           barattolo_sessione: str = Cookie("")):
    """L'appuntamento del contanti, firmato da chi vende: l'ora e il punto,
    mai l'indirizzo scritto. Il corpo non si stampa mai."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    d = await leggi_json(req)
    con = db()
    try:
        codice, corpo = _registra_appuntamento_p2p(con, user["id"], d, int(time.time()))
    finally:
        con.close()
    return _risposta_moderazione(codice, corpo)


# ---------- I LUOGHI DELL'APPUNTAMENTO (1 ott 2026) --------------------
# Mentre chi vende scrive dove vedersi, la pagina propone INDIRIZZI VERI:
# scelto uno, il punto diventa per l'altra persona «🧭 Apri nel
# navigatore». LA FONTE: Photon (photon.komoot.io), il geocoder costruito
# sui dati di OpenStreetMap PER la ricerca mentre si scrive. Scartato
# Nominatim, il geocoder ufficiale di OpenStreetMap: la sua policy VIETA
# l'autocompletamento («you must not implement such a service on the
# client side using the API»), letta il 1 ott 2026. Scartate Google e
# Apple: chiavi, contratti, e i dati dell'utente a chi vive di quelli.
# PASSA DAL NOSTRO SERVER, ed e' il patto con Andrea: a Photon arriva
# SOLO il testo cercato — niente indirizzo IP dell'utente (chiama il
# server), niente cookie, niente posizione (nessun `lat`/`lon` di
# preferenza: sarebbe dire dove sta chi cerca), niente Referer —, col
# filtro del paese e un'intestazione che dice chi siamo. CON UN FRENO:
# P2P_LUOGHI_PER_PERSONA ricerche al minuto per persona e
# P2P_LUOGHI_PER_TUTTI chiamate al minuto verso Photon in tutto — la
# fair use di un servizio gratuito —, piu' una memoria in RAM delle
# risposte (P2P_LUOGHI_MEMORIA_S, mai su disco) e, nel telefono, l'attesa
# fra un tasto e l'altro. Il testo cercato non si stampa mai.
# «📍 USA LA MIA POSIZIONE» NON PASSA DA TERZI: il nome del comune vicino
# lo da' il nostro elenco dei comuni (`_comune_vicino`), in RAM.
try:
    from config import P2P_LUOGHI_URL
except ImportError:
    P2P_LUOGHI_URL = "https://photon.komoot.io"
P2P_LUOGHI_PAESE = "IT"            # il filtro del paese ('' = ovunque)
P2P_LUOGHI_MAX = 5                 # suggerimenti per ricerca
P2P_LUOGHI_MIN_LETTERE = 3
P2P_LUOGHI_MAX_LETTERE = 120
P2P_LUOGHI_PER_PERSONA = 30        # ricerche al minuto, per persona
P2P_LUOGHI_PER_TUTTI = 120         # chiamate a Photon al minuto, in tutto
P2P_LUOGHI_MEMORIA_S = 6 * 3600
P2P_LUOGHI_MEMORIA_MAX = 1000
P2P_LUOGHI_ATTESA_S = 4.0
P2P_LUOGHI_CORPO_MAX = 256 * 1024
P2P_LUOGHI_UA = "Barattolo/1.0 (+https://barattolo.store)"
P2P_LUOGHI_VICINO_KM = 30          # oltre, «vicino a» sarebbe una bugia
_P2P_LUOGHI_MEMORIA: dict = {}     # testo -> (scade, suggerimenti)
_P2P_LUOGHI_PERSONE: dict = {}     # tg_id -> istanti dell'ultimo minuto
_P2P_LUOGHI_TUTTI: list = []       # istanti dell'ultimo minuto, verso Photon
_P2P_COMUNI_PUNTI: list = []       # [(lat, lon, «Nome (PR)»)], nato al primo uso


class LuoghiMuti(Exception):
    """Photon non ha risposto, o ha risposto male, o il freno di tutti e'
    tirato: i suggerimenti tacciono, l'indirizzo si scrive a mano."""


def _testo_luogo_pulito(q) -> str:
    """PURA: il testo cercato, senza caratteri di controllo e con gli spazi
    ripuliti, al massimo P2P_LUOGHI_MAX_LETTERE."""
    t = "".join(ch for ch in str(q or "") if ch.isprintable())
    return re.sub(r"\s+", " ", t).strip()[:P2P_LUOGHI_MAX_LETTERE]


def _etichetta_luogo(p) -> tuple:
    """PURA: dalle proprieta' di un risultato di Photon, `(nome,
    indirizzo)` come li legge una persona: «Bar Sport» e «Via Emilia 354,
    47922 Rimini»; «Piazza Castello» e «10123 Torino»; «» e «Via Roma 10,
    20056 Trezzo sull'Adda». Testo degli altri: ripulito e accorciato qui,
    scappato dal client."""
    p = p if isinstance(p, dict) else {}
    s = lambda k: re.sub(r"\s+", " ", "".join(
        ch for ch in str(p.get(k) or "") if ch.isprintable())).strip()[:80]
    nome, via = s("name"), s("street")
    strada = " ".join(x for x in (via, s("housenumber")) if x) if via else ""
    citta = s("city") or s("locality") or s("district")
    dove = " ".join(x for x in (s("postcode"), citta) if x)
    if not dove:
        # il risultato E' un comune o una zona: «Torino, Piemonte»
        dove = next((x for x in (s("county"), s("state")) if x and x != nome), "")
    if nome and nome in (via, strada):
        nome = ""                      # una via: il nome e' la via stessa
    return nome, ", ".join(x for x in (strada, dove) if x and x != nome)


def _luoghi_da_photon(dati) -> list:
    """PURA: la risposta GeoJSON di Photon in al piu' P2P_LUOGHI_MAX
    suggerimenti `{nome, indirizzo, etichetta, lat, lon}`, senza doppioni
    (la stessa etichetta due volte e' un doppione per chi legge) e senza
    le voci con coordinate storte."""
    fuori, visti = [], set()
    feat = dati.get("features") if isinstance(dati, dict) else None
    for f in feat if isinstance(feat, list) else []:
        try:
            lon, lat = f["geometry"]["coordinates"][:2]
        except (KeyError, TypeError, ValueError, IndexError):
            continue
        geo = _geo_presenza_p2p({"lat": lat, "lon": lon})
        if not geo:
            continue
        nome, indirizzo = _etichetta_luogo(f.get("properties"))
        etichetta = ", ".join(x for x in (nome, indirizzo) if x)
        if not etichetta or etichetta.casefold() in visti:
            continue
        visti.add(etichetta.casefold())
        fuori.append({"nome": nome, "indirizzo": indirizzo, "etichetta": etichetta,
                      "lat": geo["lat"], "lon": geo["lon"]})
        if len(fuori) >= P2P_LUOGHI_MAX:
            break
    return fuori


def _freno_luoghi(conta: list, tetto: int, adesso: float) -> bool:
    """PURA sulla lista: c'e' posto per un'altra chiamata nell'ultimo
    minuto? Se si', la conta."""
    while conta and conta[0] <= adesso - 60:
        conta.pop(0)
    if len(conta) >= tetto:
        return False
    conta.append(adesso)
    return True


def _freno_luoghi_persona(tg_id: int, adesso: float) -> bool:
    """Il freno di una persona. Il dizionario non cresce per sempre: oltre
    qualche migliaio di voci si tolgono quelle ferme da piu' di un minuto."""
    if len(_P2P_LUOGHI_PERSONE) > 5000:
        for k in [k for k, v in _P2P_LUOGHI_PERSONE.items() if not v or v[-1] <= adesso - 60]:
            _P2P_LUOGHI_PERSONE.pop(k, None)
    return _freno_luoghi(_P2P_LUOGHI_PERSONE.setdefault(int(tg_id), []),
                         P2P_LUOGHI_PER_PERSONA, adesso)


async def _cerca_luoghi(testo: str) -> list:
    """I suggerimenti per un testo: dalla memoria se c'e', se no da Photon
    — col SOLO testo, il paese e il numero di risultati. LuoghiMuti su
    ogni cosa che non sia una risposta buona."""
    chiave = testo.casefold()
    adesso = time.time()
    voce = _P2P_LUOGHI_MEMORIA.get(chiave)
    if voce and voce[0] > adesso:
        return voce[1]
    if not _freno_luoghi(_P2P_LUOGHI_TUTTI, P2P_LUOGHI_PER_TUTTI, adesso):
        raise LuoghiMuti("il freno di tutti e' tirato")
    parametri = {"q": testo, "limit": str(P2P_LUOGHI_MAX * 2)}
    if P2P_LUOGHI_PAESE:
        parametri["countrycode"] = P2P_LUOGHI_PAESE
    try:
        async with httpx.AsyncClient(timeout=P2P_LUOGHI_ATTESA_S, follow_redirects=False,
                                     headers={"User-Agent": P2P_LUOGHI_UA}) as c:
            r = await c.get(P2P_LUOGHI_URL.rstrip("/") + "/api/", params=parametri)
        if r.status_code != 200:
            raise LuoghiMuti(f"HTTP {r.status_code}")
        if len(r.content) > P2P_LUOGHI_CORPO_MAX:
            raise LuoghiMuti("risposta troppo grande")
        luoghi = _luoghi_da_photon(r.json())
    except LuoghiMuti:
        raise
    except Exception as e:
        raise LuoghiMuti(type(e).__name__)
    if len(_P2P_LUOGHI_MEMORIA) >= P2P_LUOGHI_MEMORIA_MAX:
        for k in sorted(_P2P_LUOGHI_MEMORIA, key=lambda k: _P2P_LUOGHI_MEMORIA[k][0])[
                :max(1, P2P_LUOGHI_MEMORIA_MAX // 10)]:
            _P2P_LUOGHI_MEMORIA.pop(k, None)
    _P2P_LUOGHI_MEMORIA[chiave] = (adesso + P2P_LUOGHI_MEMORIA_S, luoghi)
    return luoghi


def _comune_vicino(lat: float, lon: float) -> str:
    """Il comune piu' vicino a un punto, «Torino (TO)», dal nostro elenco
    in RAM — nessuna chiamata fuori. '' senza l'elenco, o oltre
    P2P_LUOGHI_VICINO_KM (all'estero, in mare: «vicino a» mentirebbe)."""
    global _P2P_COMUNI_PUNTI
    if not _P2P_COMUNI_PUNTI and COMUNI_LISTA:
        punti = []
        for c in COMUNI_LISTA:
            xy = COMUNI.get(normalizza(f"{c['nome']} {c['provincia']}"))
            if xy:
                punti.append((xy[0], xy[1], f"{c['nome']} ({c['provincia']})"))
        _P2P_COMUNI_PUNTI = punti
    if not _P2P_COMUNI_PUNTI:
        return ""
    k = math.cos(math.radians(lat))
    la, lo, nome = min(_P2P_COMUNI_PUNTI,
                       key=lambda p: (p[0] - lat) ** 2 + ((p[1] - lon) * k) ** 2)
    if _distanza_metri_p2p({"lat": lat, "lon": lon}, {"lat": la, "lon": lo}) \
            > P2P_LUOGHI_VICINO_KM * 1000:
        return ""
    return nome


@app.post("/api/p2p/luoghi")
async def luoghi_p2p(req: Request, x_tg_init_data: str = Header(""),
                     barattolo_sessione: str = Cookie("")):
    """I suggerimenti degli indirizzi mentre si scrive dove vedersi. POST
    e non GET apposta: il testo cercato e' un indirizzo, e in una GET
    finirebbe nel registro degli accessi."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    d = await leggi_json(req)
    testo = _testo_luogo_pulito(d.get("q"))
    if len(testo) < P2P_LUOGHI_MIN_LETTERE:
        return JSONResponse({"luoghi": []}, headers={"Cache-Control": "no-store"})
    if not _freno_luoghi_persona(user["id"], time.time()):
        raise HTTPException(429, "Troppe ricerche: aspetta qualche secondo")
    try:
        luoghi = await _cerca_luoghi(testo)
    except LuoghiMuti as e:
        print(f"🗺️ Luoghi P2P: i suggerimenti tacciono ({e})", flush=True)
        raise HTTPException(503, "I suggerimenti non rispondono: scrivi l'indirizzo a mano")
    return JSONResponse({"luoghi": luoghi}, headers={"Cache-Control": "no-store"})


@app.post("/api/p2p/luoghi/vicino")
async def luogo_vicino_p2p(req: Request, x_tg_init_data: str = Header(""),
                           barattolo_sessione: str = Cookie("")):
    """«📍 Usa la mia posizione»: il comune vicino al punto, dal nostro
    elenco. La posizione non esce di qui e non si stampa."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _p2p_per(user["id"])["attivo"]:
        raise HTTPException(409, "Lo scambio P2P non e' attivo")
    d = await leggi_json(req)
    geo = _geo_presenza_p2p({"lat": d.get("lat"), "lon": d.get("lon")})
    if not geo:
        raise HTTPException(400, "Posizione illeggibile")
    return JSONResponse({"vicino": _comune_vicino(geo["lat"], geo["lon"])},
                        headers={"Cache-Control": "no-store"})


# ---------- IL PAGAMENTO A CHI COMPRA, DETTO A CHI VENDE -------------
# (23 set 2026, «Ritocchi allo scambio P2P», dalla prova vera a due
# telefoni). Chi vende tocca «Libera i sats» e mostrod gli risponde
# SUBITO che la sua garanzia e' stata incassata — il messaggio che il
# client leggeva come «Scambio concluso» — ma i sats a chi compra
# partono DOPO, e possono non passare: quel giorno la fattura di chi
# comprava era scaduta. Chi compra lo sa dal coordinatore (il pagamento
# fallito, poi «dammi una fattura nuova»); chi vende NO — a lui mostrod
# non scrive piu' niente fino al voto — e leggeva «concluso» su uno
# scambio fermo.
# IL SERVER LO SA, ed e' la ragione per cui la domanda viene qui: dal
# 19 set 2026 mostrod gli racconta ogni passo (patch 0007) — il
# rilascio, ogni pagamento non passato, la fattura nuova, e il
# pagamento RIUSCITO (`success`, il momento `concluso`). La cronaca sta
# in `p2p_momenti`; qui si legge e basta. Lo stesso giudice decide
# anche il messaggio Telegram di chi vende (l'attesa del rilascio, in
# `_scarica_attese_p2p`): la card e il bot dicono la stessa cosa.
# IL PESO DEI FATTI CHE CADONO NELLO STESSO SECONDO: un pagamento non
# passato e' sempre la conseguenza di un tentativo — il rilascio, o la
# fattura nuova — quindi a parita' d'ora viene DOPO, e vince.
_DOPO_RILASCIO_P2P = {"rilasciato": 0, "fattura_data": 1, "payout_fallito": 2}


def _pagamenti_p2p(con, ordini, io: int) -> dict:
    """PURA sulla connessione: dove sta il pagamento a chi compra, per
    ogni scambio della lista di cui `io` e' una delle due parti. Torna
    `{ordine: {"stato": ..., "quando": ...}}`, con stato
    • 'riuscito' — il pagamento e' passato: i sats sono arrivati;
    • 'fallito'  — l'ultimo fatto dopo il rilascio e' un pagamento non
      passato: si aspetta la fattura nuova di chi compra;
    • 'in_corso' — liberati, e il pagamento e' in volo (o e' ripartito
      con la fattura nuova).
    `quando` e' l'ora di MOSTROD del fatto che decide, e al client serve
    a datare la chiusura.
    LE PARTI SONO QUELLE DETTE DA MOSTROD (`p2p_scambi`), non quelle
    dichiarate dai telefoni: e' lo stesso giudice degli avvisi.
    CHI NON E' DELLA PARTITA NON RICEVE LA RIGA — e nemmeno un errore:
    come per un ordine che non esiste, e i due casi non si distinguono
    (la lezione di Q3). E UNO SCAMBIO DI CUI IL SERVER NON HA SENTITO
    NIENTE DOPO IL RILASCIO resta fuori allo stesso modo: «non lo so»
    non si serve come «in corso».
    `concluso` VALE DA TUTT'E DUE LE FONTI: e' il `success` di mostrod,
    o quello del libro quando la sua riserva e' partita (`fonte`
    'libro') — il pagamento riuscito e' l'unico fatto di qui che il
    libro pubblico veda. Gli altri tre li racconta solo mostrod.
    Alza ValueError sulla forma storta della lista (via
    `_ordini_puliti_p2p`), mai un 400 diretto: la prova non ha bisogno
    di FastAPI. Il giudizio di ogni scambio e' `_pagamento_ordine_p2p`."""
    pulite = _ordini_puliti_p2p(ordini)
    io = int(io or 0)
    if not io:
        return {}
    segni = ",".join("?" * len(pulite))
    miei = [r["ordine"] for r in con.execute(
        f"SELECT ordine, compratore, venditore FROM p2p_scambi "
        f"WHERE ordine IN ({segni})", pulite).fetchall()
        if io in (int(r["compratore"] or 0), int(r["venditore"] or 0))]
    fuori = {}
    for ordine in miei:
        esito = _pagamento_ordine_p2p(con, ordine)
        if esito:
            fuori[ordine] = esito
    return fuori


def _pagamento_ordine_p2p(con, ordine: str) -> dict:
    """PURA sulla connessione: dove sta il pagamento a chi compra su
    QUELL'ordine, dalla sola cronaca — `{"stato": ..., "quando": ...}`
    con gli stati di `_pagamenti_p2p`, o un dizionario vuoto se dopo il
    rilascio il server non ha sentito niente.
    E' IL GIUDICE UNICO DEL PAGAMENTO (23 set 2026): lo chiedono la
    rotta, per la card e la pagina di chi vende, e l'attesa del
    rilascio, per il suo messaggio Telegram — cosi' le due voci non si
    contraddicono mai. Le parti NON le guarda: chi puo' chiedere lo
    decide chi chiama."""
    righe = con.execute(
        "SELECT momento, quando, dettaglio FROM p2p_momenti "
        "WHERE ordine=? AND momento IN ('rilasciato', 'payout_fallito', "
        "'fattura_data', 'concluso')", (ordine,)).fetchall()
    riuscito = [int(r["quando"]) for r in righe if r["momento"] == "concluso"]
    if riuscito:
        return {"stato": "riuscito", "quando": max(riuscito)}
    # la fattura data PRIMA del rilascio e' un'altra storia — la
    # presa, lo scambio che si apre —: conta solo quella NUOVA
    fatti = [(int(r["quando"]), _DOPO_RILASCIO_P2P[r["momento"]], r["momento"])
             for r in righe if r["momento"] != "fattura_data"
             or (r["dettaglio"] or "") == "new-invoice"]
    if not fatti:
        return {}
    quando, _peso, momento = max(fatti)
    return {"stato": "fallito" if momento == "payout_fallito" else "in_corso",
            "quando": quando}


@app.post("/api/p2p/pagamenti")
async def pagamenti_p2p(req: Request, x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """«Su questi scambi, il pagamento a chi compra e' passato?» — la
    domanda di chi vende a sats liberati, che dal coordinatore non lo
    viene a sapere. Il giudice e' `_pagamenti_p2p`.
    Le regole delle sorelle `controparte` e `recensibile`: la SESSIONE
    serve (chi ha preso un ordine non e' un fatto pubblico, e nemmeno
    come e' andato il suo pagamento), NIENTE ID NELL'URL (un log e' un
    posto dove le cose restano), e NESSUN GATE SULLA LEVA — qui non si
    scrive niente, e un 409 colpirebbe proprio chi ha uno scambio a
    meta' il giorno che la leva si spegne."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    con = db()
    try:
        esiti = _pagamenti_p2p(con, d.get("ordini"), user["id"])
    except ValueError as e:
        raise HTTPException(400, str(e))
    finally:
        con.close()
    return JSONResponse({"pagamenti": esiti},
                        headers={"Cache-Control": "no-store"})


# ---------- I MIEI SCAMBI SU OGNI DISPOSITIVO: L'ARCHIVIO DEL SERVER ---
# (24 set 2026, dal campo: Andrea pubblica dall'app Android, Alan prende
# dal tablet; nella mini app Telegram dello stesso account di Andrea lo
# scambio NON c'era, e sul tablet di Alan e' anche sparito.) La riga di
# uno scambio vive nel localStorage del dispositivo che l'ha aperto, e
# dal secondo dispositivo si ricostruiva SOLO quel che il libro pubblico
# sapeva descrivere: un ordine ancora in vetrina. Di uno scambio PRESO
# il 38383 non dice piu' niente di utile, e la restore-session da' solo
# id, indice e uno stato — non il lato, non la cifra, non chi c'e'
# dall'altra parte. IL SERVER INVECE SA TUTTO: dalla patch 0007 mostrod
# gli racconta ogni passo (`p2p_momenti`) e gli dice le due parti
# (`p2p_scambi`), e il libro gli ha gia' insegnato lato, cifra e metodi
# (`p2p_ordini`). Qui glielo si chiede: per ogni scambio di cui chi
# chiede E' una delle due parti (o l'ha pubblicato), tutto quel che
# serve a farlo COMPARIRE su un dispositivo che non l'ha mai visto — e
# a governarlo, quando quel dispositivo sa ricavare la trade key.
# LO STATO E' TRADOTTO NEL VOCABOLARIO DEL CLIENT dalla cronaca
# (`_stato_scambio_p2p`, puro), con gli stessi momenti che gia' fanno
# le frasi degli avvisi — nessuno stato nuovo, nessuna storia inventata:
# un momento che non si conosce da' '' e il client tiene quel che sa.
# CHI NON E' DELLA PARTITA NON RICEVE LA RIGA (la lezione di Q3): la
# risposta e' senza quell'id, come per un ordine che non esiste.
# I FINALI RESTANO PER `P2P_STORICO_GIORNI`: e' lo storico dei
# conclusi e degli annullati, lo stesso orizzonte della scopa del client.
P2P_STORICO_GIORNI = 30
# a parita' d'ora vince il momento che viene DOPO nella storia: mostrod
# fa certi passi a due a due nello stesso istante (la presa e la
# garanzia chiesta; la garanzia pagata e la fattura chiesta) e a dire
# «a chi tocca» e' il secondo della coppia
_PESO_MOMENTO_P2P = {
    "preso": 0, "fattura_data": 1, "garanzia_chiesta": 2, "garanzia_pagata": 2,
    "fattura_chiesta": 3, "fiat": 4, "annullo_chiesto": 4, "rilasciato": 5,
    "payout_fallito": 6, "concluso": 7, "annullato": 8, "scaduto": 8,
    "tornato": 8, "disputa": 8}


def _euro_numero_p2p(testo) -> float:
    """PURA: da «10,00 €» — la cifra del libro come `p2p_ordini.euro`
    la tiene, scritta come si legge — al numero. Storta o vuota = 0."""
    t = str(testo or "").replace("€", "").replace("\xa0", "").replace(" ", "").strip()
    if not t:
        return 0.0
    if "," in t:
        t = t.replace(".", "").replace(",", ".")
    try:
        v = float(t)
    except ValueError:
        return 0.0
    return v if v > 0 else 0.0


def _euri_numero_p2p(testo) -> tuple:
    """PURA: la cifra del libro come `_euro_libro` la scrive, in due
    numeri — `(euro, euro_max)` —: «10,00 €» e' (10.0, 0.0), un
    intervallo ancora da scegliere «da 20,00 a 100,00 €» e' (20.0,
    100.0). Fino al 27 set 2026 l'intervallo usciva 0, e il conto di un
    annullato diceva «Invia 0 · Ricevi 0». Storta o vuota = (0.0, 0.0)."""
    t = str(testo or "")
    if t.strip().lower().startswith("da ") and " a " in t:
        lo, _, hi = t.strip()[3:].partition(" a ")
        a, b = _euro_numero_p2p(lo), _euro_numero_p2p(hi)
        return (a, b) if a > 0 and b > a else (0.0, 0.0)
    return (_euro_numero_p2p(t), 0.0)


def _metodi_lista_p2p(testo) -> list:
    """PURA: i metodi come `p2p_ordini.metodi` li tiene (una lista JSON,
    o i nomi separati da virgola) in una lista di stringhe."""
    t = str(testo or "").strip()
    if not t:
        return []
    if t.startswith("["):
        try:
            v = json.loads(t)
            return [str(x).strip() for x in v if str(x).strip()] if isinstance(v, list) else []
        except ValueError:
            return []
    return [x.strip() for x in t.split(",") if x.strip()]


def _stato_scambio_p2p(momenti, lato: str, preso_dal: str, stato_libro: str,
                       mio: bool) -> dict:
    """PURA: dove sta uno scambio, nel vocabolario del CLIENT (le chiavi
    di `STATI_P2P`), dalla cronaca di mostrod. Torna `{stato, preso,
    quando, payout_fallito}`; `stato` vuoto = non si sa, e il client
    tiene quel che sa (mai un default, la lezione di Q4).
    GUARDA L'ULTIMO GIRO: un ordine tornato in vetrina e ripreso ha una
    storia nuova, e i momenti del giro di prima non dicono piu' a chi
    tocca. A parita' d'ora decide `_PESO_MOMENTO_P2P`.
    SENZA CRONACA vale il libro: `pending` e' «pubblicato» per chi l'ha
    scritto, `success` concluso, `canceled`/`expired` annullato,
    `in-progress` non dice a chi tocca e resta vuoto.
    `lato` e' di chi LEGGE ('compro' | 'vendo'); `preso_dal` chi ha
    preso secondo mostrod ('buyer' | 'seller'), che decide il primo
    passo dopo la presa: se ha preso chi compra deve dire dove ricevere
    i sats, se ha preso chi vende deve bloccarli."""
    giro = max([int(m.get("giro") or 0) for m in momenti] or [0])
    # SOLO I MOMENTI CHE SI CONOSCONO DECIDONO (24 set 2026): la cronaca
    # porta anche `recapito` (la dichiarazione del telefono di chi
    # vende, fonte 'telefono'), e preso come «ultimo» spegneva lo stato
    # — «non si sa» su uno scambio attivo, proprio dopo il gesto che lo
    # rende pagabile. Un momento fuori dal peso non racconta niente.
    del_giro = [m for m in momenti if int(m.get("giro") or 0) == giro
                and str(m.get("momento") or "") in _PESO_MOMENTO_P2P]
    if not del_giro:
        s = {"pending": "pubblicato" if mio else "", "success": "concluso",
             "canceled": "annullato", "expired": "annullato",
             "active": "attivo"}.get(
                 str(stato_libro or ""), "")
        return {"stato": s, "preso": False, "quando": 0, "payout_fallito": False}
    ultimo = max(del_giro, key=lambda m: (int(m.get("quando") or 0),
                                          _PESO_MOMENTO_P2P.get(m.get("momento"), 0)))
    m = str(ultimo.get("momento") or "")
    d = str(ultimo.get("dettaglio") or "")
    a = str(ultimo.get("attore") or "")
    compro = lato == "compro"
    io_attore = "buyer" if compro else "seller"
    attesa_hold = "attesa_hold_venditore" if compro else "attesa_mia_hold"
    attesa_fatt = "attesa_mia_fattura" if compro else "attesa_fattura_compratore"
    if m == "preso":
        chi = preso_dal if preso_dal in ("buyer", "seller") else a
        s = attesa_fatt if chi == "buyer" else (attesa_hold if chi == "seller" else "")
    elif m == "garanzia_chiesta":
        s = attesa_hold
    elif m == "fattura_chiesta":
        s = attesa_fatt
    elif m == "fattura_data":
        s = attesa_hold if d == "hold-next" else ("rilasciato" if d == "new-invoice" else "attivo")
    elif m == "garanzia_pagata":
        s = "attivo"
    elif m == "fiat":
        s = "euro_inviati"
    elif m == "rilasciato":
        s = "rilasciato"
    elif m == "payout_fallito":
        s = "fattura_nuova" if compro else "rilasciato"
    elif m == "concluso":
        s = "concluso"
    elif m == "annullo_chiesto":
        s = "annullo_chiesto" if a == io_attore else "annullo_proposto"
    elif m in ("annullato", "scaduto"):
        s = "annullato"
    elif m == "tornato":
        s = "pubblicato" if mio else "annullato"
    elif m == "disputa":
        s = "in_disputa"
    else:
        s = ""
    return {"stato": s,
            "preso": any(str(x.get("momento")) == "preso" for x in del_giro),
            "quando": int(ultimo.get("quando") or 0),
            "payout_fallito": m == "payout_fallito"}


def _passo_euro_p2p(dati) -> str:
    """PURA: COME SI CHIAMA IL TERZO PASSO per il moderatore (16 ott 2026,
    orari-passi, decisione di Andrea), dai numeri della frase
    (`_dati_frase_p2p`): 'paycode' col PayCode del tabacchino, che vince
    come nella pagina delle parti; 'contanti' col contanti di persona
    SAPUTO (`contanti`: la forma del recapito di questo giro, o il solo
    «Contanti» fra i metodi — mai il solo «forse»); '' per gli euro.
    Le parole le mette il client, le stesse delle parti."""
    d = dati or {}
    if d.get("tabacchino"):
        return "paycode"
    return "contanti" if d.get("contanti") else ""


def _orari_passi_p2p(momenti, creato: int = 0, mio: bool = False,
                     giro=None) -> dict:
    """PURA: QUANDO E' SUCCESSO OGNI PASSO DELLO SCAMBIO (16 ott 2026,
    cantiere orari-passi, decisione di Andrea): l'ora che la linea dei
    passi scrive, piccola e grigia, sotto ogni passo fatto.
    L'ORA E' QUELLA DI MOSTROD, cioe' `quando` della cronaca
    (`p2p_momenti`): un istante solo per scambio, uguale per chi compra,
    per chi vende e per il moderatore. Mai l'ora in cui un telefono l'ha
    visto, che e' diversa su ogni dispositivo.
    I PASSI, nella scala di `P2P_PROGRESSO` del client:
    • `pubblicato` — solo per chi l'ordine l'ha scritto (`mio`): quando
      il server l'ha saputo (`p2p_ordini.creato`); il libro non ha un
      momento della pubblicazione;
    • `preso` — la presa; `garanzia` — la hold pagata (`garanzia_pagata`);
      `fiat` — gli euro detti inviati; `concluso` — il pagamento arrivato;
    • `disputa` — l'apertura; `chiuso` — l'annullo, la scadenza o il
      ritorno in vetrina.
    DEL GIRO detto (il moderatore guarda quello della sua disputa) o
    dell'ULTIMO della cronaca, come `_stato_scambio_p2p`: dopo un
    ritorno in vetrina i passi di prima non sono di questo scambio. Di
    ogni momento vale la PRIMA volta. 0 = non si sa, e allora il passo
    resta senza ora: un'ora inventata e' peggio di nessuna (una disputa
    aperta prima degli euro non ha un `fiat`, e non lo riceve)."""
    noti = [m for m in (momenti or []) if str(m.get("momento") or "") in _PESO_MOMENTO_P2P]
    if giro is None:
        giro = max([int(m.get("giro") or 0) for m in noti] or [0])
    del_giro = [m for m in noti if int(m.get("giro") or 0) == int(giro or 0)]

    def primo(*nomi) -> int:
        ore = [int(m.get("quando") or 0) for m in del_giro
               if str(m.get("momento") or "") in nomi and int(m.get("quando") or 0) > 0]
        return min(ore) if ore else 0

    return {"pubblicato": int(creato or 0) if mio else 0,
            "preso": primo("preso"),
            "garanzia": primo("garanzia_pagata"),
            "fiat": primo("fiat"),
            "concluso": primo("concluso"),
            "disputa": primo("disputa"),
            "chiuso": primo("annullato", "scaduto", "tornato")}


def _tocca_a_me_p2p(stato: str, lato: str, recapito_detto: bool) -> bool:
    """PURA: in questo scambio la mossa e' di chi legge? Il calco di
    `azioniDisponibili` del client, stato per stato (24 set 2026, il
    pallino all'apertura): chi compra deve dire dove ricevere i sats
    (`attesa_mia_fattura`, `fattura_nuova`) e, a garanzia bloccata,
    mandare gli euro — ma solo se il recapito gli e' stato detto; chi
    vende deve bloccare (`attesa_mia_hold`), indicare dove ricevere gli
    euro (`attivo` senza recapito) e liberare (`euro_inviati`)."""
    compro = lato == "compro"
    if compro:
        return stato in ("attesa_mia_fattura", "fattura_nuova") or (
            stato == "attivo" and bool(recapito_detto))
    return stato in ("attesa_mia_hold", "euro_inviati") or (
        stato == "attivo" and not recapito_detto)


def _scambi_p2p(con, io, adesso: int) -> dict:
    """PURA sulla connessione: gli scambi di `io` come il server li sa —
    `{ordine: {lato, mio, preso, euro, sats, metodi, cambio_pub, stato, stato_libro,
    creato, quando, giro, chiave_mia, chiave_peer, sats_ordine, cambio_presa,
    sats_miei, payout_fallito, momenti}}`. Entrano gli ordini che `io`
    ha pubblicato (`p2p_ordini`) e quelli in cui mostrod lo nomina come
    una delle due parti (`p2p_scambi`); il LATO e' quello detto da
    mostrod quando c'e', altrimenti quello del libro per chi ha
    pubblicato; senza un lato la riga non si serve. I finali piu'
    vecchi di `P2P_STORICO_GIORNI` restano fuori. Tetto
    `MAX_ORDINI_P2P`, come le sorelle."""
    io = int(io or 0)
    if not io:
        return {}
    ids = [r["ordine"] for r in con.execute(
        "SELECT ordine FROM p2p_ordini WHERE tg_id=? ORDER BY creato DESC", (io,))]
    for r in con.execute("SELECT ordine FROM p2p_scambi WHERE compratore=? "
                         "OR venditore=? ORDER BY aggiornato DESC", (io, io)):
        if r["ordine"] not in ids:
            ids.append(r["ordine"])
    soglia = int(adesso) - P2P_STORICO_GIORNI * 86400
    fuori = {}
    for ordine in ids:
        o = con.execute(
            "SELECT tg_id, lato, maker, stato, euro, sats, metodi, creato, "
            "cambio_pub, premio FROM p2p_ordini WHERE ordine=?", (ordine,)).fetchone()
        s = con.execute(
            "SELECT compratore, venditore, preso_dal, giro, sats, sats_compratore, "
            "sats_venditore, chiave_compratore, chiave_venditore, aggiornato, "
            "cambio_presa FROM p2p_scambi WHERE ordine=?", (ordine,)).fetchone()
        compra = int(s["compratore"] or 0) if s else 0
        vende = int(s["venditore"] or 0) if s else 0
        libro = (o["lato"] if o else "") or ""
        if io == compra and io == vende:
            # LE DUE PARTI SONO IO (28 set 2026, l'ordine d66347c2: il
            # telefono non aveva riconosciuto il proprio ordine e l'ha
            # preso): vale il lato di chi ha PUBBLICATO, perche' e' con
            # quella chiave che l'ordine si governa — `chiave_mia` e'
            # quella del lato, e con l'altro sarebbe la chiave della presa
            lato = {"buy": "compro", "sell": "vendo"}.get(libro, "compro")
        elif io == compra:
            lato = "compro"
        elif io == vende:
            lato = "vendo"
        elif o and int(o["tg_id"] or 0) == io:
            lato = {"buy": "compro", "sell": "vendo"}.get(libro, "")
        else:
            lato = ""
        if not lato:
            continue
        parti = _parti_mostro_p2p(con, ordine)
        mio = ((parti["detto"] and parti["maker"] == io)
               or (not parti["detto"] and bool(o) and int(o["tg_id"] or 0) == io))
        momenti = [dict(r) for r in con.execute(
            "SELECT momento, quando, attore, dettaglio, giro FROM p2p_momenti "
            "WHERE ordine=? ORDER BY quando", (ordine,))]
        q = _stato_scambio_p2p(momenti, lato, (s["preso_dal"] if s else "") or "",
                               (o["stato"] if o else "") or "", bool(mio))
        # il recapito gia' detto in QUESTO giro (la dichiarazione del
        # telefono di chi vende, `momento` = 'recapito'): decide a chi
        # tocca a garanzia bloccata (24 set 2026)
        giro_s = int(s["giro"] or 0) if s else 0
        recapito = any(str(x.get("momento") or "") == "recapito"
                       and int(x.get("giro") or 0) == giro_s for x in momenti)
        ultimo = q["quando"] or (int(s["aggiornato"] or 0) if s else 0) \
            or (int(o["creato"] or 0) if o else 0)
        if q["stato"] in ("concluso", "annullato") and ultimo < soglia:
            continue
        chiavi = {"compro": (s["chiave_compratore"] if s else "") or "",
                  "vendo": (s["chiave_venditore"] if s else "") or ""}
        altro = "vendo" if lato == "compro" else "compro"
        euri = _euri_numero_p2p(o["euro"] if o else "")
        fuori[ordine] = {
            "lato": lato, "mio": bool(mio), "preso": bool(q["preso"]),
            # la cifra e il secondo capo dell'intervallo (27 set 2026)
            "euro": euri[0], "euro_max": euri[1],
            # il premio del libro, col segno (27 set 2026)
            "premium": float(o["premio"] or 0) if o else 0.0,
            "sats": int(o["sats"] or 0) if o else 0,
            "metodi": _metodi_lista_p2p(o["metodi"] if o else ""),
            # il cambio di Barattozon (26 set 2026): il premio scelto si
            # rilegge anche sul dispositivo che la riga non l'ha scritta
            "cambio_pub": float(o["cambio_pub"] or 0) if o else 0.0,
            "stato": q["stato"],
            "stato_libro": (o["stato"] if o else "") or "",
            "creato": int(o["creato"] or 0) if o else 0,
            "quando": int(q["quando"] or 0),
            "giro": int(s["giro"] or 0) if s else 0,
            "chiave_mia": chiavi[lato], "chiave_peer": chiavi[altro],
            "sats_ordine": int(s["sats"] or 0) if s else 0,
            # il cambio della presa (27 set 2026): a sats fissi la
            # convenienza dello scambio si ferma li'
            "cambio_presa": float(s["cambio_presa"] or 0) if s else 0.0,
            "sats_miei": int((s["sats_compratore"] if lato == "compro"
                              else s["sats_venditore"]) or 0) if s else 0,
            "payout_fallito": bool(q["payout_fallito"]),
            "recapito_detto": bool(recapito),
            "tocca": _tocca_a_me_p2p(q["stato"], lato, recapito),
            # «📍 SONO QUI» DEL GIRO CORRENTE (1 ott 2026): la mia ultima
            # presenza e l'ora dell'ultima dell'altra parte — mai la sua
            # posizione —, cosi' le vede anche il dispositivo che non le
            # ha segnate. Al posto di `incontro`, la prova col QR, che ora
            # legge solo il moderatore.
            "presenze": _presenze_per_parte_p2p(
                con, ordine, giro_s, "compra" if lato == "compro" else "vende"),
            "momenti": [{"m": str(m.get("momento") or ""), "q": int(m.get("quando") or 0),
                         "a": str(m.get("attore") or ""), "d": str(m.get("dettaglio") or "")}
                        for m in momenti],
            # L'ORA DI OGNI PASSO (16 ott 2026, orari-passi): quella di
            # mostrod, uguale per i due — la linea dei passi la scrive
            # sotto ogni passo fatto
            "orari": _orari_passi_p2p(momenti, int(o["creato"] or 0) if o else 0,
                                      bool(mio)),
            # LA RIGA DEL CONTO NELL'APP (10 ott 2026, l'avviso del blocco):
            # se QUESTO giro mi e' stato contato come non completato, la
            # stessa frase del Telegram — la pagina dello scambio tornato
            # nel libro la mostra. '' per tutti gli altri; nei banchi senza
            # il giudice, ''
            "conto": _conto_scambio_p2p(con, io, ordine, giro_s, adesso)}
        if len(fuori) >= MAX_ORDINI_P2P:
            break
    return fuori


def _conto_scambio_p2p(con, io, ordine: str, giro: int, adesso: int) -> str:
    """La riga del conto per l'archivio, fail-open come il giudice che la
    scrive: un banco senza `_conto_esito_p2p` o senza la tabella vale ''."""
    try:
        return _conto_esito_p2p(con, io, ordine, giro, adesso)["riga"]
    except Exception:
        return ""


def _quanti_tocca_p2p(con, io, adesso: int) -> int:
    """Quanti dei miei scambi aspettano un mio gesto, per il pallino
    all'apertura (`/api/me.p2p_tocca`, 24 set 2026). Lo stesso giudice
    della rotta degli scambi, contato. Un database senza le tabelle —
    i banchi di ieri — vale zero, mai un errore sul profilo."""
    try:
        return sum(1 for r in _scambi_p2p(con, io, adesso).values() if r["tocca"])
    except sqlite3.OperationalError:
        return 0


# ---- LA ✕ SU OGNI DISPOSITIVO (7 ott 2026, richiesta di Andrea) ----
# La ✕ di «I miei scambi» toglieva la riga dal localStorage di UN
# dispositivo; gli altri dello stesso account la tenevano, e l'archivio
# qui sopra gliela rifaceva nascere. Adesso il gesto si ricorda per
# ACCOUNT in `p2p_tolti` (l'id e l'ora, nient'altro), e l'archivio ne
# manda l'elenco: ogni dispositivo toglie da se' le sue righe, anche
# quelle che vivono solo li', alla prossima lettura.
# SOLO UNO SCAMBIO FINITO, e lo giudicano in DUE: il telefono prima di
# chiedere (`p2pTogliibile`) e il server qui, con il suo stato. Uno
# scambio in corso non si ricorda mai, nemmeno se il telefono si
# sbaglia: la sua chiave serve ancora a muovere dei sats.
P2P_STATI_TOGLIBILI = ("concluso", "annullato")


def _tolti_p2p(con, io, adesso: int) -> dict:
    """PURA sulla connessione: `{ordine: quando}` degli scambi che `io`
    ha tolto con la ✕, piu' giovani di P2P_LIBRO_MEMORIA_S (oltre, la
    pulizia li porta via comunque)."""
    return {r[0]: int(r[1] or 0) for r in con.execute(
        "SELECT ordine, quando FROM p2p_tolti WHERE tg_id=? AND quando>=?",
        (int(io or 0), int(adesso) - P2P_LIBRO_MEMORIA_S))}


def _tolto_vale_p2p(servito, quando_tolto: int) -> bool:
    """PURA: la ✕ di allora vale ancora? `servito` e' la riga che
    l'archivio serve per quell'ordine (None se non la serve piu').
    Vale se l'archivio non lo serve — non c'e' niente da far rinascere —
    o lo serve FINITO e fermo dalla ✕ in poi. UNO SCAMBIO CHE SI MUOVE
    DOPO IL GESTO torna a vedersi: la ✕ ha tolto quello scambio, non
    l'ordine per sempre, e un dispositivo non deve mai togliere da solo
    una riga che nessuno ha tolto."""
    if not servito:
        return True
    return (servito.get("stato") in P2P_STATI_TOGLIBILI
            and int(servito.get("quando") or 0) <= int(quando_tolto or 0))


def _togli_scambio_p2p(con, io, ordine: str, adesso: int) -> dict:
    """PURA sulla connessione: la ✕ di `io` sullo scambio `ordine`.
    Torna `{esito, stato}`, con lo stato che il server sa:
    · 'tolto'  — e' mio e per il server e' finito: si ricorda, con l'ora
      del gesto o quella dell'ultimo passo se e' piu' avanti (un
      orologio del coordinatore un filo avanti non deve far sembrare lo
      scambio mosso DOPO la ✕). Una seconda ✕ da un altro dispositivo
      la rinfresca e basta;
    · 'aperto' — e' mio ma per il server non e' finito: non si scrive
      niente, e il telefono non toglie;
    · 'ignoto' — l'archivio non lo serve (non e' mio, non esiste, e'
      oltre lo storico) o non ne sa dire lo stato: niente da ricordare,
      e il telefono lo toglie solo da se'. Lo stesso no per «non e'
      tuo» e «non esiste»: la domanda non dice niente degli altri.
    IL GIUDICE DI «MIO» E DELLO STATO E' L'ARCHIVIO (`_scambi_p2p`), cioe'
    la stessa risposta che ha fatto nascere la riga sui dispositivi."""
    s = _scambi_p2p(con, io, adesso).get(ordine)
    stato = str((s or {}).get("stato") or "")
    if not stato:
        return {"esito": "ignoto", "stato": ""}
    if stato not in P2P_STATI_TOGLIBILI:
        return {"esito": "aperto", "stato": stato}
    con.execute("INSERT INTO p2p_tolti(tg_id, ordine, quando) VALUES(?,?,?) "
                "ON CONFLICT(tg_id, ordine) DO UPDATE SET quando=excluded.quando",
                (int(io), ordine, max(int(adesso), int(s.get("quando") or 0))))
    con.commit()
    return {"esito": "tolto", "stato": stato}


@app.post("/api/p2p/scambi/togli")
async def togli_scambio_p2p(req: Request, x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """La ✕ di «I miei scambi», per l'account e non per il dispositivo.
    Il giudice e' `_togli_scambio_p2p`. Le regole delle sorelle: la
    SESSIONE serve, l'id dell'ordine sta nel POST e mai nell'indirizzo
    (nel corpo SOLO quello), e NESSUN GATE SULLA LEVA — togliere una
    propria riga non dipende da un interruttore, come «dimentica».
    LE RISPOSTE: 200 tolto, 404 il server non ha niente da ricordare (il
    telefono toglie da se'), 409 per il server lo scambio e' ancora in
    corso (il telefono non toglie). Nel journal solo il 409, che e' il
    caso da guardare: un telefono e un server che non sono d'accordo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    try:
        d = await req.json()
    except Exception:
        raise HTTPException(400, "Richiesta illeggibile")
    ordine = str(d.get("ordine") or "").strip() if isinstance(d, dict) else ""
    if not FORMA_ORDINE_P2P.fullmatch(ordine):
        raise HTTPException(400, "Ordine non valido")
    con = db()
    try:
        esito = _togli_scambio_p2p(con, user["id"], ordine, int(time.time()))
    finally:
        con.close()
    if esito["esito"] == "ignoto":
        raise HTTPException(404, "Scambio non trovato")
    if esito["esito"] == "aperto":
        print(f"✕ P2P: {ordine[:8]} per {user['id']}: il telefono lo dice finito, "
              f"il server «{esito['stato']}» — resta", flush=True)
        raise HTTPException(409, "Lo scambio risulta ancora in corso")
    return {"ok": True, "stato": esito["stato"]}


@app.post("/api/p2p/scambi")
async def scambi_p2p(x_tg_init_data: str = Header(""),
                     barattolo_sessione: str = Cookie("")):
    """«Quali sono i miei scambi, e a che punto stanno?» — la domanda di
    un dispositivo che non li ha mai visti. Il giudice e' `_scambi_p2p`.
    Le regole delle sorelle (`controparte`, `pagamenti`): la SESSIONE
    serve (chi ha preso un ordine non e' un fatto pubblico), NESSUN
    CORPO e niente nell'indirizzo (non si puo' chiedere degli scambi di
    un altro: non esiste la sintassi), NESSUN GATE SULLA LEVA (qui non si
    scrive niente, e un 409 toglierebbe i propri scambi a chi ne ha uno a
    meta' il giorno che la leva si spegne), e `no-store`.
    E I TOLTI CON LA ✕ (7 ott 2026): `tolti` e' l'elenco degli id che lo
    stesso account ha tolto da un altro dispositivo, finche' la ✕ vale
    (`_tolto_vale_p2p`). Lo scambio tolto RESTA in `scambi`, ed e'
    voluto: un dispositivo rimasto indietro lo porta prima avanti fino
    alla fine (l'adozione), e solo allora lo toglie — senza quella riga
    resterebbe «in corso» per sempre, perche' nessuno gli direbbe piu'
    che e' finito. Quel che non deve fare e' NASCERE, e lo dice l'elenco."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    try:
        esiti = _scambi_p2p(con, user["id"], int(time.time()))
        tolti = sorted(o for o, q in _tolti_p2p(con, user["id"], int(time.time())).items()
                       if _tolto_vale_p2p(esiti.get(o), q))[:MAX_ORDINI_P2P]
    finally:
        con.close()
    # `adesso` (16 ott 2026, orari-passi): l'ora del server, con cui il
    # telefono decide «oggi» e «ieri» anche con l'orologio sbagliato
    return JSONResponse({"scambi": esiti, "tolti": tolti, "adesso": int(time.time())},
                        headers={"Cache-Control": "no-store"})


TIMBRO_CAMPAGNA_P2P = "campagna_p2p_acceso"


async def avvisa_interessi_p2p():
    """Chi aveva premuto «🔔 Avvisami» sulla pagina P2P lo viene a
    sapere. E' IL DEBITO SCRITTO SULLA TABELLA `interessi` (il like su
    quelle pagine non e' solo un termometro: il testo PROMETTE
    l'avviso, e la promessa si legge prima del tocco), e si paga qui.

    Una-tantum GLOBALE col timbro in `timbri`, il calco di
    `avvisa_sconto_su_mono`: e' un evento del deploy, non una
    condizione che ricorre. Il timbro si scrive PRIMA degli invii — un
    errore di rete puo' perdere un avviso di cortesia, mai
    raddoppiarlo — ma DOPO la guardia della leva, o accendendo il P2P
    la campagna non partirebbe piu'.

    Le righe di `interessi` NON si cancellano: «quanti lo aspettavano»
    resta una domanda con una risposta (la decisione di Andrea sulla
    tabella). E il testo non nomina mai Nostr, chiavi o relay: chi
    entra con Telegram legge «il coordinatore, un servizio
    indipendente», che e' quel che gli serve sapere."""
    # LA TERZA DOMANDA, ed e' quella che rende sostenibile la fase
    # chiusa: la campagna e' l'ANNUNCIO dell'apertura, e la lista
    # vuota E' l'apertura. Partendo con la fase chiusa accesa direbbe
    # «il P2P c'e'» a chi poi non lo vedrebbe, e siccome il timbro e'
    # UNA-TANTUM brucerebbe il turno — il giorno vero l'avviso non
    # partirebbe piu', e per rimandarlo bisognerebbe mettere le mani
    # nella tabella `timbri`.
    if not _p2p_leve()["attivo"] or P2P_PROVA_IDS:
        return                    # non c'e', o c'e' per due: si tace
    if timbro_letto(TIMBRO_CAMPAGNA_P2P):
        return
    con = db()
    righe = con.execute(
        "SELECT tg_id FROM interessi WHERE funzione='p2p'").fetchall()
    con.close()
    timbro_scrivi(TIMBRO_CAMPAGNA_P2P, "fatto")
    mandati = []
    for r in righe:
        try:
            await notifica(r["tg_id"], (
                "🔄 <b>Lo scambio in euro è arrivato.</b>\n\n"
                "Avevi chiesto di essere avvisato: da oggi puoi comprare "
                "e vendere sats in euro direttamente con un'altra "
                "persona, dall'app.\n\n"
                "I sats restano bloccati finché il bonifico non arriva — "
                "a tenerli è il coordinatore (Mostro, un servizio "
                "indipendente): Barattolo non tiene né vede i tuoi "
                "sats.\n\n"
                "Lo trovi nella barra in basso, alla voce <b>P2P</b>."))
            mandati.append(r["tg_id"])
        except Exception as e:
            print(f"⚠️ Avviso P2P saltato per {r['tg_id']}: {e}")
        await asyncio.sleep(0.2)
    # la riga nel journal SEMPRE quando la campagna gira: e' il modo di
    # sapere a chi e' arrivata (il patto dei timbri)
    print(f"🔄 Campagna «lo scambio P2P è arrivato»: avvisati "
          f"{len(mandati)} {mandati}")


TIMBRO_CAMPAGNA_P2P_TUTTI = "campagna_p2p_tutti"
TESTO_CAMPAGNA_P2P_TUTTI = (
    "🔄 Su Barattolo è arrivato lo scambio P2P in euro!\n"
    "Da oggi puoi comprare e vendere bitcoin direttamente con altre "
    "persone, pagando con SEPA, Revolut e altri metodi.\n"
    "Apri Barattolo → P2P e prova 🫙")
_TASK_CAMPAGNA_P2P_TUTTI = None


def avvia_campagna_p2p_tutti():
    """L'orologio la LANCIA e non la aspetta: sono minuti (0,2 s a
    persona), e in quei minuti l'orologio deve continuare a guardare i
    pagamenti. Il riferimento al task si tiene, o il garbage collector
    puo' portarsi via un task che nessuno guarda. Un task ancora vivo
    non se ne lancia un secondo; a non farla ripartire DOPO e' il
    timbro, che la campagna scrive prima del primo invio."""
    global _TASK_CAMPAGNA_P2P_TUTTI
    if not P2P_CAMPAGNA_TUTTI:
        return
    if _TASK_CAMPAGNA_P2P_TUTTI is not None and not _TASK_CAMPAGNA_P2P_TUTTI.done():
        return
    _TASK_CAMPAGNA_P2P_TUTTI = asyncio.create_task(avvisa_tutti_p2p())


async def avvisa_tutti_p2p():
    """LA CAMPAGNA A TUTTI (9 ott 2026, la vigilia del lancio, richiesta
    di Andrea): il giorno che il P2P si apre, un messaggio a OGNI
    iscritto — non solo a chi aveva premuto «Avvisami».

    LE TRE DOMANDE, nell'ordine di `avvisa_interessi_p2p` e per le sue
    ragioni: la leva (P2P_CAMPAGNA_TUTTI, solo True), il P2P aperto a
    TUTTI (acceso e fase di prova vuota — partendo in fase chiusa
    direbbe «e' arrivato» a chi poi non lo vede, e brucerebbe il
    turno), e il timbro `campagna_p2p_tutti`, scritto DOPO le guardie e
    PRIMA degli invii: un riavvio a meta' puo' perdere degli avvisi di
    cortesia, mai raddoppiarli.

    UN MESSAGGIO A TESTA: chi ha una riga in `interessi` per il P2P
    riceve gia' quello dell'altra campagna, e qui resta fuori. NOT
    EXISTS e non NOT IN: un solo tg_id NULL nella sottoquery farebbe
    tornare zero righe al NOT IN, cioe' una campagna muta e timbrata.

    TUTTI, ANCHE I NATIVI NOSTR: passa da notifica(), che sceglie il
    canale di ognuno (Telegram, DM cifrato NIP-17, o tutt'e due). In
    `utenti` stanno solo persone entrate davvero (Telegram, login con
    firma): i profili Nostr importati non hanno una riga.

    Gli esiti si contano da quel che notifica() RESTITUISCE, perche' lei
    non alza mai (fail-open): un 403 (bot bloccato o mai avviato) torna
    come stringa, e qui diventa un «saltato» con la sua riga. Il DM
    Nostr parte in sottofondo e non dice com'e' andata: vale «inviato»."""
    if not P2P_CAMPAGNA_TUTTI:
        return
    if not _p2p_leve()["attivo"] or P2P_PROVA_IDS:
        return                    # non c'e', o c'e' per pochi: si tace
    if timbro_letto(TIMBRO_CAMPAGNA_P2P_TUTTI):
        return
    con = db()
    righe = con.execute(
        "SELECT u.tg_id FROM utenti u WHERE u.tg_id IS NOT NULL "
        "AND NOT EXISTS (SELECT 1 FROM interessi i "
        "WHERE i.funzione='p2p' AND i.tg_id=u.tg_id) "
        "ORDER BY u.tg_id").fetchall()
    con.close()
    timbro_scrivi(TIMBRO_CAMPAGNA_P2P_TUTTI, "fatto")
    print(f"🔄 Campagna P2P a tutti: parte verso {len(righe)} iscritti",
          flush=True)
    inviati, saltati = 0, 0
    for r in righe:
        tg_id = r["tg_id"]
        try:
            esito = await notifica(tg_id, TESTO_CAMPAGNA_P2P_TUTTI) or ""
        except Exception as e:          # notifica() non alza; se mai...
            esito = f"errore {type(e).__name__}: {e}"
        if ("telegram ok" in esito or "DM Nostr in volo" in esito
                or "simulata" in esito):
            inviati += 1
        else:
            saltati += 1
            print(f"⚠️ Campagna P2P a tutti: saltato {tg_id} ({esito})")
        await asyncio.sleep(0.2)
    # la riga nel journal SEMPRE a fine giro: il totale, non l'elenco
    # (sono tutti gli iscritti); i saltati hanno la loro riga qui sopra
    print(f"🔄 Campagna P2P a tutti: finita — inviati {inviati}, "
          f"saltati {saltati}", flush=True)


def _bech32_polymod(valori: list) -> int:
    """Il cuore del checksum bech32 (BIP-173): un registro a scorrimento
    che 'mastica' i valori a 5 bit. Serve solo a hex_to_npub."""
    gen = (0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3)
    chk = 1
    for v in valori:
        b = chk >> 25
        chk = ((chk & 0x1ffffff) << 5) ^ v
        for i in range(5):
            if (b >> i) & 1:
                chk ^= gen[i]
    return chk


def hex_to_npub(hexkey: str) -> str:
    """Gemella SPECULARE di npub_to_hex: dalla chiave esadecimale alla
    npub bech32, checksum vero incluso (a differenza della decodifica,
    qui il checksum va CALCOLATO, non buttato). Proprieta' di sanita':
    npub_to_hex(hex_to_npub(h)) == h."""
    dati, bits, val = [], 0, 0
    for byte in bytes.fromhex(hexkey):   # da byte a gruppi di 5 bit
        val = (val << 8) | byte
        bits += 8
        while bits >= 5:
            bits -= 5
            dati.append((val >> bits) & 31)
    if bits:
        dati.append((val << (5 - bits)) & 31)
    # hrp "npub" espansa come vuole lo standard: bit alti, zero, bit bassi
    hrp = [ord(c) >> 5 for c in "npub"] + [0] + [ord(c) & 31 for c in "npub"]
    polymod = _bech32_polymod(hrp + dati + [0] * 6) ^ 1
    checksum = [(polymod >> 5 * (5 - i)) & 31 for i in range(6)]
    return "npub1" + "".join(CHARSET_BECH32[d] for d in dati + checksum)


def decodifica_naddr(naddr: str) -> dict:
    """Decodifica un identificatore 'naddr1...' (NIP-19) nei suoi campi:
    kind, la pubkey di chi ha COMPOSTO l'evento (tipo TLV 2, "author"),
    l'identificatore cioe' il tag "d" (tipo 0, "special") e i relay
    suggeriti (tipo 1, ripetibile). Stessa ricetta bech32 di
    npub_to_hex — stesso CHARSET_BECH32, stesso checksum SCARTATO e
    non verificato (coerente: neanche li' si verifica in decodifica) —
    ma qui il payload non e' una chiave nuda: e' una sequenza TLV
    (byte di tipo, byte di lunghezza, valore), perche' una naddr porta
    PIU' di una chiave. Il kind (tipo 3) e' un intero a 4 byte
    big-endian, non una stringa."""
    if not naddr.startswith("naddr1"):
        raise ValueError("deve iniziare con naddr1")
    dati = [CHARSET_BECH32.find(c) for c in naddr[6:]]
    if -1 in dati:
        raise ValueError("naddr non valida: carattere sconosciuto")
    dati = dati[:-6]                     # togli il checksum
    bits, val, grezzo = 0, 0, []
    for d in dati:                       # da gruppi di 5 bit a byte
        val = (val << 5) | d
        bits += 5
        if bits >= 8:
            bits -= 8
            grezzo.append((val >> bits) & 0xFF)
    grezzo = bytes(grezzo)
    identificatore, pubkey, kind, relays = None, None, None, []
    i = 0
    while i + 2 <= len(grezzo):
        tipo, lunghezza = grezzo[i], grezzo[i + 1]
        valore = grezzo[i + 2:i + 2 + lunghezza]
        if len(valore) != lunghezza:
            raise ValueError("naddr non valida: TLV troncato")
        if tipo == 0:
            identificatore = valore.decode("utf-8", errors="replace")
        elif tipo == 1:
            relays.append(valore.decode("utf-8", errors="replace"))
        elif tipo == 2 and len(valore) == 32:
            pubkey = valore.hex()
        elif tipo == 3 and len(valore) == 4:
            kind = int.from_bytes(valore, "big")
        i += 2 + lunghezza
    if identificatore is None or pubkey is None or kind is None:
        raise ValueError(
            "naddr non valida: manca identificatore, autore o kind")
    return {"identificatore": identificatore, "pubkey": pubkey,
            "kind": kind, "relays": relays}


# --- Doppia cittadinanza: la firma e' la chiave d'ingresso -----------
# (set 2026: non piu' badge dichiarato + nota pubblica esterna + questo
# switch — tre gesti senza mai firmare niente, sostituiti da UNA firma
# vera. Vedi collega_npub_firma, piu' sotto, e CANTIERI, "Entra anche
# con Nostr". cerca_nota_verifica/verifica_npub_avvia/
# verifica_npub_controlla/abilita_accesso_nostr sono andati via con
# quel giro: davano un badge o un accesso senza mai una firma, e
# lasciavano pensare che bastasse.)

@app.post("/api/me/npub/disabilita-accesso")
def disabilita_accesso_nostr(x_tg_init_data: str = Header(""),
                             barattolo_sessione: str = Cookie("")):
    """Il gesto contrario a collega_npub_firma: si spegne la chiave
    d'accesso. NON e' un lucchetto contro chi ha la chiave (14 nov
    2026, cantiere audit-parole-bot, dal primo audit di sicurezza): il
    badge resta verificato, e `login_nostr` a quella firma ripropone il
    collegamento — e' voluto (ARCHITETTURA: chiude solo la porta, il
    badge resta). Per chiudere del tutto si TOGLIE la chiave dal
    profilo, e la pagina adesso lo dice (scelta di Andrea: «Cambia solo
    le parole»)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if user["id"] < 0:
        # Doppia cintura col tg_id>0 nella WHERE qui sotto: un nativo
        # Nostr e' entrato PROPRIO con questa chiave, togliergliela
        # significherebbe chiuderlo fuori per sempre.
        raise HTTPException(400, "Sei entrato proprio con questa chiave: "
                                 "toglierla ti chiuderebbe fuori per sempre")
    con = db()
    con.execute("UPDATE utenti SET npub_accesso='' WHERE tg_id=? AND tg_id>0",
                (user["id"],))
    con.commit()
    con.close()
    return {"ok": True, "npub_accesso": False}


def _accoda_trasloco_di(con, tg_id: int) -> int:
    """Il trasloco (vedi trasloca_annunci_nostr) per UN utente solo,
    SUBITO dopo che la sua chiave e' appena diventata provata qui — non
    nel giro periodico. Solo la meta' che accoda (niente relay, niente
    attesa): la lapide sul vecchio evento nostro resta all'orologio, che
    tocca i relay e non deve far aspettare la richiesta di nessuno.
    Le tre condizioni della WHERE sono quelle di trasloca_annunci_nostr,
    ripetute a mano apposta (estrarle vorrebbe dire toccare quella
    funzione, fuori da questo cantiere): prove_collega_npub_firma
    confronta le due stringhe, cosi' se divergono la prova si accorge.
    Con «no» (annunci_sul_suo_profilo) non si accoda niente: e' il
    trasloco che quella scelta rifiuta."""
    if not annunci_sul_suo_profilo(con, tg_id):
        return 0
    righe = con.execute(
        "SELECT a.id FROM annunci a "
        "LEFT JOIN firme_nostr f ON f.annuncio_id=a.id "
        "WHERE a.venditore_id=? AND a.nostr_event_id<>'' "
        "  AND a.nostr_autore='' AND a.contatto_nostr='' "
        "  AND f.annuncio_id IS NULL", (tg_id,)).fetchall()
    for r in righe:
        accoda_firma(con, r["id"], tg_id, "pubblica")
    return len(righe)


def _spegni_badge_altrove(con, npub: str, tg_id: int) -> int:
    """UNA CHIAVE, UNA CASA (20 ott 2026, cantiere npub-una-casa): quando
    `npub` diventa la chiave d'accesso di `tg_id`, il badge verificato
    della stessa npub sulle ALTRE righe senza accesso si spegne. Il
    giro che lo rendeva necessario: A collega X, disabilita l'accesso
    (il badge resta), B collega X, disabilita — e il login con X
    trovava due badge, e apriva in silenzio un terzo account.
    Chi firma adesso ha in mano la chiave: e' lui a dire dove abita.
    Le righe CON accesso non si toccano (quella chiave apre un'altra
    porta, ed e' l'indice unico a giudicarla). Ritorna quante ne ha
    spente. Gira dentro la scrittura di chi la chiama: niente commit."""
    return con.execute(
        "UPDATE utenti SET npub_verificata=0 WHERE npub=? AND tg_id<>? "
        "AND npub_verificata=1 AND npub_accesso=''",
        (npub, tg_id)).rowcount


@app.post("/api/me/npub/collega-firma")
async def collega_npub_firma(req: Request, x_tg_init_data: str = Header(""),
                             barattolo_sessione: str = Cookie("")):
    """Collega+verifica+abilita in un solo gesto: l'utente firma la
    stessa sfida del login vero (GET /api/login/nostr/sfida) col suo
    firmatario (nsec in pagina, bunker, telefono), e quella firma stessa
    e' la prova — l'UNICA porta, da set 2026 (vedi CANTIERI, "Entra
    anche con Nostr"): niente piu' salva-npub, nota pubblica esterna o
    switch senza firma. Una sola scrittura atomica, indice unico come
    giudice sulla WHERE (ripetuta apposta, vedi sotto)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if ChiavePubblicaNostr is None:
        raise HTTPException(503, "Login Nostr non disponibile: sul "
                                 "server manca il pacchetto coincurve")
    d = await leggi_json(req)
    pubkey = verifica_evento_login(
        d.get("evento"), host_di_casa(req.headers.get("host", "")))
    npub = hex_to_npub(pubkey)
    con = db()
    u = con.execute("SELECT npub_accesso FROM utenti WHERE tg_id=?",
                    (user["id"],)).fetchone()
    if not u:
        con.close()
        raise HTTPException(404, "Profilo non trovato")
    if u["npub_accesso"]:
        con.close()
        raise HTTPException(400, "L'accesso con Nostr e' gia' attivo")
    try:
        # La condizione si ripete nella WHERE: tra la lettura sopra e
        # questa scrittura non deve essere cambiato nulla.
        scritta = con.execute(
            "UPDATE utenti SET npub=?, npub_verificata=1, npub_accesso=?, "
            "verifica_codice='', verifica_scade=0 "
            "WHERE tg_id=? AND npub_accesso=''",
            (npub, npub, user["id"])).rowcount
        # Solo se la chiave e' davvero entrata qui: gli altri badge si
        # spengono per far posto a QUESTA casa, mai per nessuna
        if scritta:
            _spegni_badge_altrove(con, npub, user["id"])
    except sqlite3.IntegrityError:
        # LA CHIAVE APRE GIA' UN ALTRO ACCOUNT (20 ott 2026, cantiere
        # fusione-da-telegram, dal campo: entrato con Nostr da Tor, poi con
        # Telegram, e «Entra anche con Nostr» diceva solo «gia' creato»).
        # Se l'altro e' un account NATO CON NOSTR, la firma appena
        # verificata e' la stessa prova che serve per entrarci, e questa
        # sessione prova il Telegram: le due meta' sono della stessa
        # persona, e si propone di unirle — l'atto e' `esegui_fusione`,
        # lo stesso del bot, con le stesse guardie. Si CHIEDE prima (non
        # si puo' annullare): qui nasce solo la proposta, col token che
        # `/api/me/unisci-nostr` incassa. Se l'altro e' un account
        # Telegram, no: due Telegram non diventano uno.
        altro = con.execute("SELECT * FROM utenti WHERE npub_accesso=?",
                            (npub,)).fetchone()
        if not altro or altro["tg_id"] >= 0 or user["id"] < 0:
            con.close()
            raise HTTPException(409,
                "Questa chiave e' gia' l'accesso Nostr di un altro account "
                "Telegram: un account, una chiave")
        io = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                         (user["id"],)).fetchone()
        errore = _guardie_fusione(con, altro, io)
        if errore:
            con.close()
            raise HTTPException(409, errore)
        annunci = con.execute("SELECT COUNT(*) FROM annunci WHERE venditore_id=?",
                              (altro["tg_id"],)).fetchone()[0]
        ordini = con.execute("SELECT COUNT(*) FROM ordini WHERE compratore_id=? "
                             "OR venditore_id=?",
                             (altro["tg_id"], altro["tg_id"])).fetchone()[0]
        con.close()
        _pulisci_fusioni()
        # Una sola proposta viva per account, come gli inviti del bot
        for t in [t for t, v in UNIONI_DAL_WEB.items() if v[0] == user["id"]]:
            UNIONI_DAL_WEB.pop(t, None)
        token = secrets.token_hex(16)
        UNIONI_DAL_WEB[token] = (user["id"], altro["tg_id"],
                                 int(time.time()) + SECONDI_CODICE_FUSIONE)
        raise HTTPException(409, {
            "messaggio": "Questa chiave apre gia' un tuo account Nostr: "
                         "puoi unirlo a questo",
            "unione": {"token": token, "npub": npub,
                       "nome": altro["nome"] or "", "annunci": annunci,
                       "ordini": ordini,
                       "valida_secondi": SECONDI_CODICE_FUSIONE}})
    accodati = _accoda_trasloco_di(con, user["id"])
    con.commit()
    con.close()
    await premia_distintivi(user["id"])
    await premia_reputazione_nostr(user["id"])
    return {"ok": True, "npub": npub, "npub_verificata": True,
            "npub_accesso": True, "annunci_in_coda": accodati}


@app.post("/api/me/unisci-nostr")
async def unisci_nostr(req: Request, x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """Il «Si', unisci» della proposta nata in `collega_npub_firma`: fonde
    l'account nato con Nostr in QUESTO account Telegram, con lo stesso
    atto e le stesse guardie della porta del bot (`esegui_fusione`, che
    le ricontrolla dentro la transazione). Il token e' monouso, dura
    cinque minuti e vale solo per chi l'ha ricevuto firmando. `async`
    come le altre rotte dei lasciapassare (`prove_dizionari_nel_loop`)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    dati = UNIONI_DAL_WEB.pop(str(d.get("token") or ""), None)
    if not dati or dati[2] < int(time.time()) or dati[0] != user["id"]:
        raise HTTPException(409, "⏳ La proposta e' scaduta: rifai «Entra "
                                 "anche con Nostr» e firma di nuovo")
    esito = esegui_fusione(dati[0], dati[1])
    if isinstance(esito, str):
        raise HTTPException(409, esito)
    # Dopo la fusione la chiave e' provata su questo account: gli annunci
    # pubblicati finora a nome della piattaforma passano alla sua firma,
    # come dopo un collegamento normale
    con = db()
    try:
        accodati = _accoda_trasloco_di(con, dati[0])
        con.commit()
        doppioni = len(trova_doppioni_nostr(con, dati[0]))
    finally:
        con.close()
    await premia_distintivi(dati[0])
    await premia_reputazione_nostr(dati[0])
    await notifica_admin(f"🔗 Doppia cittadinanza dal web: "
                         f"{_npub_breve(esito['npub'])} → tg {dati[0]}"
                         + _unione_coda_admin(esito),
                         argomento="riepiloghi")
    return {"ok": True, "npub": esito["npub"], "npub_verificata": True,
            "npub_accesso": True, "annunci": esito["annunci"],
            "ordini": esito["ordini"], "negozio": esito["negozio"],
            "doppioni": doppioni, "annunci_in_coda": accodati}


# --- Barattolo su Nostr: gli annunci in piazza -----------------------
# Quando un annuncio supera la moderazione, il server lo firma con la
# chiave DELLA PIATTAFORMA (mai degli utenti: regola ferrea) e lo
# pubblica come "classified listing" NIP-99 (kind 30402) sugli stessi
# 4 relay della verifica. Venduto -> si ripubblica con status "sold"
# (stesso tag "d": i relay sostituiscono il vecchio evento). Rimosso ->
# richiesta di cancellazione NIP-09 (kind 5). Tutto fail-open: se la
# chiave e' il segnaposto, mancano coincurve/websocket-client o i relay
# tacciono, l'annuncio su Barattolo vive normalmente e resta solo un
# avviso in console. Gli utenti solo-Telegram non vedono nulla.

# L'INDIRIZZO E IL BOT SONO LEVE (19 ott 2026, cantiere collaudo-vm,
# richiesta di Andrea; il disegno e' STUDIO-ISTANZA-PROVA, §3). Erano
# costanti: un'istanza di PROVA che le eredita registrerebbe il webhook
# del SUO bot sull'indirizzo di produzione (che lo rifiuta col segreto
# diverso: bot sordo) e metterebbe link di produzione in ogni notifica.
# NON DICHIARATE = il mondo di ieri byte per byte: il config del VPS non
# ha bisogno di nessuna riga. SCRITTE MALE = il default e lo si DICE nel
# journal, come TELEGRAM_MINIAPP_LINK: sul VPS un errore di battitura non
# deve spegnere il sito, e sulla prova la riga si legge al primo avvio.
URL_PUBBLICO_DI_SERIE = "https://barattolo.store"
LINK_BOT_DI_SERIE = "https://t.me/ilbarattolobot"
_FORMA_URL_PUBBLICO = re.compile(r"https://[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?(:[0-9]{1,5})?")
