@app.post("/api/me/nip85-dichiarazione")
async def conferma_nip85_dichiarazione(req: Request,
                                       x_tg_init_data: str = Header(""),
                                       barattolo_sessione: str = Cookie("")):
    """Il browser ha gia' firmato E pubblicato sui relay il kind 10040
    che dichiara Barattolo provider di fiducia per '30382:rank': qui si
    verifica SOLO che la firma sia vera e che l'evento dica davvero
    quello, mai fidarsi della parola del client — stessa regola della
    modifica firmata (riga ~14897). Non si ripubblica nulla: l'evento e'
    gia' sui relay, e' il browser che ce l'ha mandato per conferma."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not _NOSTR:
        raise HTTPException(503, "Nostr è spento sul server")
    d = await leggi_json(req)
    evento = d.get("evento") or {}
    if not verifica_firma_nostr(evento):
        raise HTTPException(400, "Firma non valida")
    if evento.get("kind") != 10040:
        raise HTTPException(400, "Non è un kind 10040")
    con = db()
    u = con.execute("SELECT npub FROM utenti WHERE tg_id=?",
                    (user["id"],)).fetchone()
    con.close()
    try:
        attesa = npub_to_hex(u["npub"]) if u and u["npub"] else ""
    except ValueError:
        attesa = ""
    if not attesa or evento["pubkey"].lower() != attesa.lower():
        raise HTTPException(400, "La firma non è della tua npub")
    if not any(len(t) >= 2 and t[0] == NIP85_TAG_FIDUCIA
               and t[1].lower() == _NOSTR[1].lower()
               for t in evento.get("tags", [])):
        raise HTTPException(400,
            "L'evento non dichiara Barattolo come fonte di fiducia")
    con = db()
    con.execute("UPDATE utenti SET nip85_dichiarato=1 WHERE tg_id=?",
                (user["id"],))
    con.commit()
    con.close()
    return {"ok": True}


@app.post("/api/admin/live/sincronizza-distintivi")
async def sincronizza_badge_distintivi(x_tg_init_data: str = Header(""),
                                       barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: crea (se mancano) i badge Nostr dei distintivi
    interni e li assegna a chi li ha gia' guadagnati e ha una npub
    verificata. Da qui in poi chi guadagna un distintivo nuovo riceve
    il suo badge da solo (vedi premia_distintivi); questo bottone
    mette in pari chi l'aveva gia' prima, e si puo' rilanciare quando
    si vuole — non riassegna mai due volte (vedi _premia_distintivo)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    if not _NOSTR:
        raise HTTPException(503, "Nostr è spento sul server")
    riepilogo = {}
    for dist in DISTINTIVI:
        live = await _assicura_badge_distintivo(dist)
        if not live["evento_id"]:
            riepilogo[dist["id"]] = {"errore": "definizione non pubblicata"}
            continue
        con = db()
        candidati = con.execute(
            "SELECT b.tg_id FROM badge_utente b JOIN utenti u "
            "ON u.tg_id=b.tg_id WHERE b.badge_id=? AND u.npub_verificata=1",
            (dist["id"],)).fetchall()
        con.close()
        assegnati, falliti = 0, 0
        for r in candidati:
            if await _premia_distintivo(dist, r["tg_id"]):
                assegnati += 1
            else:
                falliti += 1
            await asyncio.sleep(0.3)
        riepilogo[dist["id"]] = {"assegnati": assegnati, "falliti": falliti,
                                 "candidati": len(candidati)}
    return {"ok": True, "riepilogo": riepilogo}


@app.post("/api/admin/live/{live_id}/badge")
async def crea_badge_live(live_id: str, req: Request,
                          x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: crea o aggiorna la definizione NIP-58 (kind 30009)
    del badge di una live e la pubblica sui relay. Idempotente: lo
    stesso live_id (tag "d") aggiorna la definizione invece di
    duplicarla — utile per quando arriva l'immagine (endpoint sotto)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    if not RE_LIVE_ID.fullmatch(live_id):
        raise HTTPException(400, "live_id non valido: solo minuscole, "
                                 "cifre e trattini, 3-40 caratteri")
    if not _NOSTR:
        raise HTTPException(503, "Nostr è spento sul server: manca "
                                 "NOSTR_NSEC_PIATTAFORMA")
    d = await leggi_json(req)
    nome = (d.get("nome") or "").strip()
    descrizione = (d.get("descrizione") or "").strip()
    if not nome or not descrizione:
        raise HTTPException(400, "Nome e descrizione sono obbligatori")
    con = db()
    con.execute(
        "INSERT INTO nostr_badge_live(live_id, nome, descrizione, "
        "creato) VALUES(?,?,?,?) ON CONFLICT(live_id) DO UPDATE SET "
        "nome=excluded.nome, descrizione=excluded.descrizione",
        (live_id, nome, descrizione, int(time.time())))
    con.commit()
    riga = con.execute("SELECT * FROM nostr_badge_live WHERE live_id=?",
                       (live_id,)).fetchone()
    con.close()
    evento = evento_badge_definizione(riga)
    ok = await _spedisci_ai_relay(evento)
    if not ok:
        raise HTTPException(502, "Nessun relay ha accettato la "
                                 "definizione del badge: riprova")
    con = db()
    con.execute("UPDATE nostr_badge_live SET evento_id=? WHERE live_id=?",
                (evento["id"], live_id))
    con.commit()
    con.close()
    print(f"🏺 Badge live «{live_id}» pubblicato ({ok}/"
          f"{len(RELAYS_VERIFICA)} relay)")
    return {"ok": True, "live_id": live_id, "evento_id": evento["id"],
            "relay_ok": ok, "relay_totali": len(RELAYS_VERIFICA)}


@app.post("/api/admin/live/{live_id}/immagine")
async def carica_immagine_badge(live_id: str, req: Request,
                                x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: carica l'immagine del badge — un data URL base64,
    la stessa forma delle foto degli annunci (vedi salva_foto, riga
    ~9298) — e, se la definizione era gia' pubblicata, la ripubblica
    con image/thumb aggiornati (stesso "d": e' un aggiornamento, non
    un badge nuovo)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    con = db()
    riga = con.execute("SELECT * FROM nostr_badge_live WHERE live_id=?",
                       (live_id,)).fetchone()
    con.close()
    if not riga:
        raise HTTPException(404, "Prima crea il badge (nome e descrizione)")
    if not ImmaginePillow:
        raise HTTPException(503, "Sul server manca Pillow: caricamento "
                                 "immagine non disponibile")
    d = await leggi_json(req)
    m = re.match(r"^data:image/(jpeg|jpg|png|webp);base64,(.+)$",
                d.get("foto") or "", re.S)
    if not m:
        raise HTTPException(400, "Immagine non leggibile: usa JPG, PNG o WebP")
    try:
        raw = base64.b64decode(m.group(2))
        img = ImmaginePillow.open(io.BytesIO(raw))
        img = ImageOps.exif_transpose(img).convert("RGB")
        img = ImageOps.fit(img, (BADGE_LATO, BADGE_LATO),
                           ImmaginePillow.Resampling.LANCZOS)
    except Exception:
        raise HTTPException(400, "Questa immagine non si riesce a leggere")
    vecchia = riga["immagine"]
    nome = f"bdg_{live_id}_{int(time.time())}.jpg"
    img.save(os.path.join(FOTO_DIR, nome), "JPEG", quality=AVATAR_QUALITA)
    con = db()
    con.execute("UPDATE nostr_badge_live SET immagine=? WHERE live_id=?",
                (nome, live_id))
    con.commit()
    con.close()
    if vecchia:
        try:
            os.remove(os.path.join(FOTO_DIR, vecchia))
        except OSError:
            pass
    ripubblicato = False
    if riga["evento_id"] and _NOSTR:
        con = db()
        riga = con.execute("SELECT * FROM nostr_badge_live WHERE live_id=?",
                           (live_id,)).fetchone()
        con.close()
        evento = evento_badge_definizione(riga)
        if await _spedisci_ai_relay(evento):
            con = db()
            con.execute("UPDATE nostr_badge_live SET evento_id=? "
                        "WHERE live_id=?", (evento["id"], live_id))
            con.commit()
            con.close()
            ripubblicato = True
    return {"ok": True, "immagine": nome, "ripubblicato": ripubblicato}


@app.post("/api/admin/live/{live_id}/assegna-manuale")
async def assegna_manuale_live(live_id: str, req: Request,
                               x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: assegna il badge a UNA npub/pubkey scelta a mano —
    «mandalo a chi voglio». Chi ha partecipato manda la sua npub fuori
    da qui (in chat, in un messaggio); l'admin la incolla qui e la
    manda — la verifica e' il suo giudizio nel seguire la diretta, non
    un protocollo (vedi la nota in testa alla sezione). Se quella
    pubkey l'aveva gia' (magari ritirato in seguito), la ripropone: e'
    la via per rimettere un badge tolto."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    if not _NOSTR:
        raise HTTPException(503, "Nostr è spento sul server")
    con = db()
    live = con.execute("SELECT * FROM nostr_badge_live WHERE live_id=?",
                       (live_id,)).fetchone()
    if not live or not live["evento_id"]:
        con.close()
        raise HTTPException(400, "Prima crea e pubblica il badge (kind 30009)")
    con.close()
    d = await leggi_json(req)
    pubkey = _pubkey_normalizzata(d)
    con = db()
    con.execute(
        "INSERT INTO nostr_badge_partecipanti(live_id, pubkey) "
        "VALUES(?,?) ON CONFLICT(live_id, pubkey) DO NOTHING",
        (live_id, pubkey))
    con.commit()
    con.close()
    evento_id = await _premia_pubkey(live, pubkey)
    if not evento_id:
        raise HTTPException(502, "Nessun relay ha accettato: riprova")
    return {"ok": True, "pubkey": pubkey, "evento_id": evento_id}


@app.post("/api/admin/live/{live_id}/assegna-admin")
async def assegna_admin_live(live_id: str,
                             x_tg_init_data: str = Header(""),
                             barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: assegna il badge a tutti i moderatori (ADMIN_IDS)
    che hanno una npub verificata — «prima agli admin». Chi non ha una
    npub verificata resta fuori e si VEDE nella risposta, non sparisce
    in silenzio."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    if not _NOSTR:
        raise HTTPException(503, "Nostr è spento sul server")
    con = db()
    live = con.execute("SELECT * FROM nostr_badge_live WHERE live_id=?",
                       (live_id,)).fetchone()
    if not live or not live["evento_id"]:
        con.close()
        raise HTTPException(400, "Prima crea e pubblica il badge (kind 30009)")
    righe = []
    if ADMIN_IDS:
        segnaposto = ",".join("?" * len(ADMIN_IDS))
        righe = con.execute(
            f"SELECT tg_id, npub FROM utenti WHERE tg_id IN ({segnaposto}) "
            "AND npub_verificata=1", tuple(ADMIN_IDS)).fetchall()
    con.close()
    assegnati, non_pubblicato, npub_rotta = [], [], []
    for r in righe:
        try:
            pubkey = npub_to_hex(r["npub"])
        except ValueError:
            npub_rotta.append(r["tg_id"])
            continue
        con = db()
        con.execute(
            "INSERT INTO nostr_badge_partecipanti(live_id, pubkey) "
            "VALUES(?,?) ON CONFLICT(live_id, pubkey) DO NOTHING",
            (live_id, pubkey))
        con.commit()
        con.close()
        (assegnati if await _premia_pubkey(live, pubkey)
         else non_pubblicato).append(r["tg_id"])
        await asyncio.sleep(0.3)
    visti = {r["tg_id"] for r in righe}
    senza_npub = [a for a in ADMIN_IDS if a not in visti]
    return {"ok": True, "assegnati": assegnati,
            "non_pubblicato": non_pubblicato, "npub_non_valida": npub_rotta,
            "senza_npub_verificata": senza_npub}


@app.post("/api/admin/live/{live_id}/ritira")
async def ritira_badge_live(live_id: str, req: Request,
                            x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: ritira un badge già assegnato (NIP-09, kind 5). Come
    ritira_da_nostr per gli annunci: si segna ritirato SOLO se almeno
    un relay accetta la cancellazione, altrimenti si può ripetere.
    Riassegnare a mano (assegna_manuale_live) rimette il badge e
    azzera ritirato."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    if not _NOSTR:
        raise HTTPException(503, "Nostr è spento sul server")
    d = await leggi_json(req)
    pubkey = _pubkey_normalizzata(d)
    con = db()
    riga = con.execute(
        "SELECT premiato_evento FROM nostr_badge_partecipanti "
        "WHERE live_id=? AND pubkey=?", (live_id, pubkey)).fetchone()
    con.close()
    if not riga or not riga["premiato_evento"]:
        raise HTTPException(400, "Questa pubkey non ha un badge da ritirare")
    ok = await _spedisci_ai_relay(
        _lapide_badge(live_id, pubkey, riga["premiato_evento"]))
    if not ok:
        raise HTTPException(502, "Nessun relay ha accettato il ritiro: riprova")
    con = db()
    con.execute("UPDATE nostr_badge_partecipanti SET premiato_evento='', "
                "premiato_il=0, ritirato=1 WHERE live_id=? AND pubkey=?",
                (live_id, pubkey))
    con.commit()
    con.close()
    return {"ok": True}


@app.get("/api/admin/live")
async def elenco_live_badge(x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: l'elenco di tutti i badge live creati coi
    conteggi — il pannello altrimenti dovrebbe indovinare i live_id a
    memoria."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    con = db()
    righe = con.execute(
        "SELECT l.*, "
        "(SELECT COUNT(*) FROM nostr_badge_partecipanti p "
        " WHERE p.live_id=l.live_id) AS partecipanti, "
        "(SELECT COUNT(*) FROM nostr_badge_partecipanti p "
        " WHERE p.live_id=l.live_id AND p.premiato_evento<>'') AS premiati "
        "FROM nostr_badge_live l ORDER BY l.creato DESC").fetchall()
    con.close()
    return {"ok": True, "live": [dict(r) for r in righe]}


@app.get("/api/admin/live/{live_id}")
async def stato_live(live_id: str,
                     x_tg_init_data: str = Header(""),
                     barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: lo stato di una live — definizione, quanti
    partecipanti/premiati e l'elenco per pubkey (serve al pannello per
    offrire il ritiro riga per riga)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    con = db()
    live = con.execute("SELECT * FROM nostr_badge_live WHERE live_id=?",
                       (live_id,)).fetchone()
    if not live:
        con.close()
        raise HTTPException(404, "Live non trovata")
    totale = con.execute(
        "SELECT COUNT(*) n, SUM(premiato_evento<>'') p FROM "
        "nostr_badge_partecipanti WHERE live_id=?", (live_id,)).fetchone()
    partecipanti = con.execute(
        "SELECT pubkey, premiato_evento<>'' AS premiato, ritirato "
        "FROM nostr_badge_partecipanti WHERE live_id=? ORDER BY "
        "premiato_il DESC, pubkey", (live_id,)).fetchall()
    con.close()
    return {"ok": True, "live": dict(live),
            "partecipanti": totale["n"] or 0, "premiati": totale["p"] or 0,
            "lista": [dict(p) for p in partecipanti]}


# ---------- I POST AUTOMATICI: la piattaforma racconta i fatti -------
# Quando un annuncio nuovo entra in vetrina, Barattolo lo annuncia da
# solo sui suoi canali: una nota Nostr kind-1 (firmata dalla chiave
# piattaforma) e un post nel canale Telegram (TELEGRAM_CANALE_ID, il
# bot deve esserne amministratore). Zero AI, zero editoriale: solo
# fatti veri, formattati bene.
# L'anti-spam e' una coda con drenatore a finestra: chi pubblica si
# limita ad accodare, il drenatore dorme ATTESA_RAGGRUPPO secondi e
# poi decide — pochi annunci e budget orario capiente = post singoli,
# una raffica (l'import CSV da 500 righe) = UN solo post aggregato.
# Fail-open totale: post fallito = riga in console, mai un errore per
# chi pubblica. In collaudo si simula tutto in console (bot_api e
# _spedisci_ai_relay lo fanno gia' da soli).

CODA_PROMO: list[int] = []              # annunci in attesa di annuncio
_drenatore_promo_avviato = False
_post_promo_recenti: list[float] = []   # timestamp dei post singoli
ATTESA_RAGGRUPPO = 5 if MODALITA_COLLAUDO else 90   # finestra (secondi)
SOGLIA_AGGREGA = 3         # piu' di cosi' in una finestra = aggregato
PAUSA_TRA_PROMO = 2        # secondi tra un post singolo e l'altro


# ---------- IL RITMO DELLA VETRINA, DECISO DAL BOT -------------------
# Quanto parla il canale sta in tre numeri — ogni quanti giorni uno
# stesso venditore puo' tornare in canale, quanti post singoli si
# fanno in un'ora, e da quanti annunci in una finestra si passa
# all'aggregato. Erano tre costanti del config, cioe' cambiare il
# ritmo voleva dire entrare nel VPS e riavviare; e il ritmo e'
# proprio la cosa che si tara GUARDANDO il canale, non a tavolino.
#
# NEL DATABASE VA IL NOME, NON I NUMERI, ed e' la scelta che tiene
# semplice il resto: una riga, una parola, e le tre cifre restano
# qui, dove hanno il loro commento accanto. Un nome fuori catalogo —
# scritto a mano, o rimasto da una posizione che un domani si toglie
# — ricade sul config: fail-safe, perche' sbagliare qui non deve
# poter spegnere il canale.
#
# PERCHE' `impostazioni` E' IL POSTO GIUSTO, e non e' una deroga alla
# regola «le leve si guardano e basta» del pannello admin: quella
# difende gli interruttori che muovono DENARO (ASTA_ABILITATA,
# IMPORT_NOSTR_APERTO, AUTO_SBLOCCO_ATTIVO nascono spenti apposta
# perche' accenderli costi un gesto dal VPS). Un ritmo di
# pubblicazione non accende niente, dice quanto il bot parla, e
# sbagliarlo si vede subito nel canale. E' la stessa famiglia dell'id
# del canale, che da lassu' passa gia' di qui.
#
# NIENTE CACHE, al contrario di `_CANALE`: e' una SELECT ogni finestra
# di raggruppamento (90 secondi), e una seconda copia in RAM sarebbe
# una copia da tenere allineata in cambio di niente.

RITMI = {                     # (giorni fra due post dello stesso
                              #  venditore, post singoli all'ora,
                              #  soglia dell'aggregato)
    "tutto":     (0, 30, 20),   # la vetrina: ogni annuncio un post
    "giorno":    (1,  6,  3),   # uno per venditore al giorno
    "settimana": (7,  6,  3),   # la selezione: uno a settimana
}


def nome_ritmo() -> str:
    """Come si chiama la posizione di adesso, e l'UNICO posto che va a
    leggere quella riga. '' = nessuna posizione scelta, cioe' vale il
    config — che e' un'informazione diversa da «settimana» anche
    quando i numeri combaciano: chi legge il pannello deve poter
    distinguere «l'ha deciso qualcuno» da «e' il valore di partenza».
    Un nome fuori catalogo vale come '': fail-safe, perche' sbagliare
    qui non deve poter spegnere il canale."""
    nome = impostazione("ritmo_vetrina", "")
    return nome if nome in RITMI else ""


def ritmo_vetrina() -> tuple[int, int, int]:
    """IL GIUDICE UNICO di «quanto parla il canale». Nessuna posizione
    scelta = i valori del config, cioe' il mondo di ieri byte per
    byte."""
    return RITMI.get(nome_ritmo()) or (PROMO_GIORNI_VENDITORE,
                                       POST_MAX_ORA, SOGLIA_AGGREGA)


def imposta_ritmo(nome: str) -> str:
    """Cambia la posizione e la restituisce. Un nome fuori catalogo si
    scrive come stringa vuota, cioe' «torna al config»: e' anche il
    modo di annullare la scelta senza andare a cancellare una riga a
    mano sul VPS."""
    nome = (nome or "").strip().lower()
    if nome not in RITMI:
        nome = ""
    scrivi_impostazione("ritmo_vetrina", nome)
    return nome


def _fmt_sats(n) -> str:
    """80000 -> '80.000': i puntini delle migliaia all'italiana.

    NON SOLLEVA MAI, e non e' pigrizia: da qui passano le cifre delle
    NOTIFICHE, e parecchie di quelle vivono dentro un try/except che
    protegge un'operazione piu' importante — l'avviso ai moderatori di
    un pagamento rifiutato, per dirne una, sta apposta sotto except
    perche' una notifica non deve mai rompere un rifiuto. Il prezzo di
    quella scelta e' che un formattatore che alza le mani li' dentro
    non fa un errore: fa SPARIRE L'ALLARME, in silenzio.
    Il caso vero: `importo_invoice` torna None quando la bolt11 non si
    decodifica, e con un `f"{None:,}"` l'avviso «importo storto» —
    cioe' o un wallet rotto o un tentativo di prelievo — non partiva
    piu'. Su qualunque cosa non sia un numero si ripiega su str(),
    che e' anche esattamente quel che si vedeva prima che le cifre
    passassero di qui."""
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return str(n)
    return f"{n:,}".replace(",", ".")


def _fmt_eur(x: float) -> str:
    """284.61 -> '284,61': la VIRGOLA dei decimali, che in italiano il
    punto separa le migliaia e su una cifra grande si legge per un
    fattore mille. Gemello di _fmt_sats, e come lui vive in un posto
    solo — UN euro si scrive in un modo solo in tutta l'app: da qui
    passano i post del canale, le note Nostr, le anteprime dei link e
    le notifiche delle offerte. Il client dice gia' la stessa cosa per
    conto suo (fmtEur, toLocaleString 'it-IT'): il server era l'unico
    fuori riga.

    NON ci passano i valori dei TAG NIP-99 (price, delivery), e non e'
    una dimenticanza: quelli non sono testo per una persona ma campi
    di protocollo, che importa_nostr rilegge — li' il punto decimale
    e' la specifica, non una nostra scelta. Per la stessa ragione
    resta col punto la riga «Prezzo:» del content di evento_annuncio,
    che sta nello stesso evento del tag e lo ripete a parole."""
    return f"{x:.2f}".replace(".", ",")


def _prezzo_promo(a: dict, cambio: float) -> str:
    """Il prezzo del post: la valuta del listino per prima, l'altra
    col ≈. Se il cambio non c'e' (CoinGecko muto) il ≈ si omette."""
    if a.get("valuta") == "eur" and a.get("prezzo_eur"):
        return (f"{_fmt_eur(a['prezzo_eur'])} € "
                f"(≈ {_fmt_sats(a['prezzo_sats'])} sats)")
    prezzo = f"{_fmt_sats(a['prezzo_sats'])} sats"
    if cambio > 0:
        eur = a["prezzo_sats"] / 100_000_000 * cambio
        prezzo += f" (≈ {_fmt_eur(eur)} €)"
    return prezzo


def _slug_categoria(a: dict) -> str:
    """La categoria come hashtag: minuscola e senza spazi
    ("Casa e giardino" -> "casaegiardino")."""
    return (a.get("categoria") or "").lower().replace(" ", "")


def _hashtag_promo(a: dict) -> str:
    """Gli hashtag in coda al post: la categoria (se c'e') e sempre
    #barattolo."""
    slug = _slug_categoria(a)
    return (f"#{slug} " if slug else "") + "#barattolo"


def _nota_promo(a: dict, cambio: float) -> str:
    """Il testo della nota Nostr kind-1: una riga di fatto, la zona
    col 📍, l'immagine come URL su una riga sua (i client la mostrano
    inline), il link e gli hashtag in coda."""
    testo = f"🫙 Nuovo nel barattolo: {a['titolo']} — {_prezzo_promo(a, cambio)}"
    if a.get("zona"):
        testo += f"\n📍 {a['zona']}"
    foto = _foto_url_nostr(a.get("foto", ""))
    if foto:
        testo += f"\n\n{foto[0]}"
    testo += f"\n{link_telegram('annuncio', a['id'])}"
    testo += f"\n\n{_hashtag_promo(a)}"
    return testo


def _npub_venditore(a: dict) -> str:
    """La npub del venditore, e SOLO dal possesso dimostrato: la regola
    di `notifica()` e dei ponti di contatto — `npub_accesso`, oppure il
    badge `npub` ma solo se VERIFICATO. Mai una npub nuda, che e' una
    dichiarazione e non una prova.

    Qui quella regola pesa piu' che altrove: questa riga finisce in un
    post PUBBLICO, e una npub soltanto DICHIARATA manderebbe i lettori
    del canale sul profilo Nostr di un'altra persona. '' quando non
    c'e' niente di dimostrato, e allora la firma resta quella di
    sempre.

    Si passa dall'hex e si torna indietro con `hex_to_npub` apposta:
    cosi' quel che si mostra e' la npub CANONICA bech32, non la
    stringa che qualcuno ha incollato nel profilo."""
    u = {"npub_accesso": a.get("venditore_npub_accesso") or "",
         "npub": a.get("venditore_npub") or "",
         "npub_verificata": a.get("venditore_npub_verificata") or 0}
    # NIENTE try/except QUI, ed e' una cosa che ha detto la tortura:
    # ce n'era uno sulla npub storta, e la mutazione che lo rendeva un
    # `raise` non faceva rossa nessuna prova. Perche' era irraggiungibile
    # — `chiave_nostr_provata` la stringa storta la scarta gia' da se'
    # (`except ValueError: continue`) e torna '', quindi `hex_to_npub`
    # su un hex rotto non ci arriva mai. Un except che non puo' scattare
    # e' peggio di niente: promette una guardia che nessuno esercita.
    # Se un domani `hex_to_npub` alzasse davvero, risale al fail-open
    # del chiamante, che almeno lo STAMPA invece di lasciare la firma
    # muta in silenzio.
    hexk = chiave_nostr_provata(u)
    return hex_to_npub(hexk) if hexk else ""


def _firma_venditore(a: dict) -> str:
    """La riga «Annuncio da …» col ponte verso il negozio.

    L'@username si mostra solo se c'e' DAVVERO: i nativi Nostr non ce
    l'hanno, e scrivere «@» davanti a un nome proprio farebbe nascere
    una menzione che Telegram non sa risolvere — cioe' un link morto
    su ogni loro annuncio. Il negozio invece c'e' sempre (il codice si
    assegna alla prima riga di `utenti` e non cambia mai), ma la
    guardia resta: senza codice si scrive la sola firma, mai un link
    a `/negozio/` che porterebbe a un 404.

    E CHI VIENE DA NOSTR HA LA SUA MANIGLIA (ago 2026, chiesto da
    Andrea): la npub PROVATA diventa un'ancora su njump.me, con la npub
    abbreviata dentro un `<code>` — che su Telegram si copia con un
    tocco, ed e' il modo in cui quella stringa serve davvero.
    IL NOME DIVENTA IL LINK SOLO A CHI NON HA @USERNAME, ed e' la riga
    da non uniformare: dove lo username c'e', quello e' una MENZIONE
    che Telegram risolve, e avvolgerla in un'ancora la spegnerebbe. Il
    doppio cittadino tiene la menzione e guadagna la npub accanto; il
    nativo Nostr — che una menzione non ce l'ha mai avuta, ed e' il
    caso che ha aperto la voce — guadagna tutti e due."""
    npub = _npub_venditore(a)
    nome = a.get("venditore_username") or ""
    if nome:
        chi = f"@{html.escape(nome)}"          # una menzione vera
    else:
        chi = html.escape(a.get("venditore") or "un venditore")
        if npub:
            chi = f"<a href=\"https://njump.me/{npub}\">{chi}</a>"
    riga = f"Annuncio da <b>{chi}</b>"
    # ...ma non due volte la stessa cosa: chi non ha mai messo un nome
    # sul suo kind-0 SI CHIAMA gia' con la npub abbreviata (e' il nome
    # che gli da' `crea_utente_nostr`), e ripeterla accanto sarebbe la
    # stessa stringa due volte nella stessa riga. Il link ce l'ha gia'
    # sul nome.
    if npub and not (a.get("venditore") or "").startswith("npub1"):
        riga += (f" · <a href=\"https://njump.me/{npub}\">🟣 "
                 f"<code>{_npub_breve(npub)}</code></a>")
    if a.get("venditore_negozio"):
        riga += (f" — <a href=\"{URL_PUBBLICO}/negozio/"
                 f"{a['venditore_negozio']}\">vedi il suo negozio</a>")
    return riga


MAX_VETRINA_PROMO = 3      # quanti altri articoli linka un post


def _altri_del_venditore(con, a: dict, quanti: int = MAX_VETRINA_PROMO):
    """Gli altri annunci ATTIVI dello stesso venditore, i piu' recenti
    per primi. Legge e basta.
    Le guardie sono quelle della vetrina — solo 'attivo', mai
    l'annuncio del post — perche' questi sono link che qualcuno
    tocchera' a giorni di distanza: linkare un venduto vorrebbe dire
    mandare su uno scaffale vuoto chi era venuto a comprare."""
    return [dict(r) for r in con.execute(
        "SELECT id, titolo FROM annunci WHERE venditore_id=? "
        "AND stato='attivo' AND id<>? ORDER BY creato DESC, id DESC "
        "LIMIT ?", (a["venditore_id"], a["id"], quanti)).fetchall()]

def _costo_sped_promo(a: dict, cambio: float) -> str:
    """Quanto costa la spedizione, in una manciata di caratteri.

    I GIUDICI SONO QUELLI DEL CONTO (`_tariffa_dichiarata`,
    `_sped_in_sats`) e non una lettura a mano delle colonne: la regola
    della retrocompat — una tariffa sola dichiarata vale per tutte e
    due le strade — deve dire qui quel che dice alla cassa, o il
    canale prometterebbe una cifra che il checkout smentisce.
    QUANDO LE DUE STRADE DIVERGONO si scrive «da …» col MINIMO: nel
    post non c'e' spazio per due cifre, e il minimo e' l'unica delle
    due che non promette meno di quel che si paga davvero.
    Col cambio muto una tariffa ancorata all'euro NON si converte e la
    riga esce senza cifra: si dice la strada, mai un numero inventato
    (la regola dell'avviso EUR senza cambio)."""
    vie = ["casa"]
    if a.get("spedizione_punto_dichiarata"):
        vie.append("punto")
    valori = []
    for via in vie:
        s, e = _tariffa_dichiarata(a, via)
        v = _sped_in_sats(s, e or 0.0, cambio)
        if v is None:
            return ""
        valori.append((v, s, e or 0.0))
    v, s, e = min(valori)
    if v <= 0:
        return "<b>gratuita</b>"
    da = "da " if len({x[0] for x in valori}) > 1 else ""
    return f"{da}{_fmt_eur(e)} €" if e > 0 else f"{da}{_fmt_sats(s)} sats"

def _righe_consegna_promo(a: dict, cambio: float) -> str:
    """COME ARRIVA LA ROBA, nel post del canale (ago 2026, chiesto da
    Andrea): una riga per strada offerta, con le stesse icone e le
    stesse parole della scheda — 🚚 spedizione, 🤝 ritiro in zona,
    💾 codice online.

    La spedizione nomina TUTTE E DUE le destinazioni («a casa o a un
    punto di ritiro») perche' dall'ago 2026 la via punto si offre
    sempre dove c'e' la spedizione: dirne una sola sarebbe la meta'
    della verita' proprio nel posto dove si decide se aprire.
    Consegna NON DICHIARATA (gli storici e gli importati da Nostr) =
    nessuna riga: su una strada che nessuno ha scelto non si promette
    niente, che e' la regola gia' scritta per i filtri della vetrina."""
    c = a.get("consegna") or ""
    righe = []
    if c in ("spedizione", "entrambe"):
        riga = "🚚 Spedizione a un indirizzo o a un punto di ritiro"
        costo = _costo_sped_promo(a, cambio)
        if costo:
            riga += f" — {costo}"
        righe.append(riga)
    if c in ("ritiro", "entrambe"):
        righe.append("🤝 Ritiro in zona")
    if c == "digitale" or a.get("anche_digitale"):
        righe.append("💾 Codice online, subito")
    return "\n".join(righe)

def _vetrina_venditore(a: dict, altri: list) -> str:
    """Gli altri articoli del venditore, linkati sotto al post.

    E' la contropartita del freno (ago 2026, decisione di Andrea): un
    post a settimana per venditore, ma quel post non parla di un
    oggetto solo — porta anche gli altri e il negozio, cosi' il
    venditore che pubblica tre cose in un pomeriggio si vede lo
    stesso, senza tre post.
    I titoli si TRONCANO prima e si scappano dopo (la lezione della
    ricevuta): la caption di Telegram ha 1024 caratteri, e un «<» in
    un titolo spegnerebbe il post in silenzio."""
    if not altri:
        return ""
    voci = []
    for x in altri:
        t = (x.get("titolo") or "").strip()
        if len(t) > 46:
            t = t[:45].rstrip() + "…"
        link = link_telegram('annuncio', x['id'])
        voci.append(f"\n• <a href=\"{link}\">{html.escape(t)}</a>")
    return "\n\n🛍 Anche in vendita da lui:" + "".join(voci)


def _caption_canale(a: dict, cambio: float, venduto: bool = False,
                    altri: list | None = None) -> str:
    """La caption HTML del post nel canale Telegram (usata anche per
    RICOSTRUIRE il testo quando si edita col ✅ Venduto: cosi' non
    serve salvarlo da nessuna parte — ed e' il motivo per cui questa
    funzione dev'essere PURA rispetto alla riga che riceve).

    IL LINK NON SI VEDE (ago 2026, decisione di Andrea): al posto
    dell'URL nudo c'e' l'ancora «🫙 Apri su Barattolo». Non e' solo
    estetica — un URL in chiaro in mezzo a un post e' anche la riga
    che la gente copia e incolla altrove, mentre l'ancora tiene il
    lettore dentro il messaggio; e la caption di Telegram ha 1024
    caratteri, che i link lunghi si mangiano.
    ATTENZIONE a chi la ritocca: `a` DEVE arrivare con le tre chiavi
    del venditore (venditore, venditore_username, venditore_negozio),
    cioe' letta col JOIN su `utenti` — senza, la firma esce anonima e
    il post NUOVO e quello RIEDITATO col ✅ direbbero cose diverse."""
    link = f"{link_telegram('annuncio', a['id'])}"
    testo = f"🫙 <b>{html.escape(a['titolo'])}</b>"
    testo += f"\n💰 {_prezzo_promo(a, cambio)}"
    if a.get("zona"):
        testo += f"\n📍 {html.escape(a['zona'])}"
    consegna = _righe_consegna_promo(a, cambio)
    if consegna:
        testo += f"\n{consegna}"
    testo += f"\n\n<a href=\"{link}\">🫙 Apri su Barattolo</a>"
    testo += "\n⚡ Pagabile in Satoshi"
    testo += _vetrina_venditore(a, altri or [])
    testo += f"\n\n{_firma_venditore(a)}"
    testo += f"\n\n{_hashtag_promo(a)}"
    if venduto:
        testo += "\n\n✅ Venduto"
    return testo


def _un_post_per_venditore(annunci: list[dict], giorni: int,
                           adesso: int = 0) -> list[dict]:
    """Il freno del canale: al massimo UN annuncio per venditore, e
    solo se il suo ultimo post e' vecchio di `giorni`.
    Fra i suoi vince il PIU' RECENTE (`creato`, poi `id` — lo stesso
    tie-break dell'ordine della vetrina: due annunci pubblicati nello
    stesso secondo esistono davvero, e senza il secondo campo la
    scelta dipenderebbe dall'ordine di arrivo nella coda).

    PURA APPOSTA, come le pure del conto: prende righe e restituisce
    righe, non tocca ne' rete ne' database — cosi' si tortura in CI
    invece di sperarci. A scrivere il timbro e' chi posta.
    `giorni` e' OBBLIGATORIO E SENZA DEFAULT apposta (la lezione di
    `atteso_sats`): dall'ago 2026 il ritmo lo decide `ritmo_vetrina()`
    e non piu' una costante, e chi aggiungera' un chiamante domani
    deve scegliere il freno invece di ereditarne uno in silenzio.
    A 0 = nessun freno, cioe' la vetrina vera: si riconosce che e' una
    posizione e non una taratura, quindi non si limita nemmeno a un
    annuncio per venditore."""
    if giorni <= 0:
        return annunci
    adesso = adesso or int(time.time())
    soglia = adesso - giorni * 86400
    migliori: dict[int, dict] = {}
    for a in annunci:
        if (a.get("promo_canale_il") or 0) > soglia:
            continue          # ha gia' avuto il suo turno questa settimana
        v = a["venditore_id"]
        vecchio = migliori.get(v)
        if not vecchio or (a.get("creato") or 0, a["id"]) > \
                (vecchio.get("creato") or 0, vecchio["id"]):
            migliori[v] = a
    # l'ordine di arrivo si conserva: la coda e' cronologica, e un
    # post che scavalca l'altro senza motivo si nota
    scelti = set(id(a) for a in migliori.values())
    return [a for a in annunci if id(a) in scelti]


def accoda_promo(annuncio_id: int):
    """Mette l'annuncio in coda per i post automatici e, se dorme,
    sveglia il drenatore. Leggera e sincrona: si chiama DOPO il commit,
    mai dentro una transazione."""
    global _drenatore_promo_avviato
    if not POST_AUTOMATICI:
        return
    CODA_PROMO.append(annuncio_id)
    if not _drenatore_promo_avviato:
        _drenatore_promo_avviato = True
        asyncio.create_task(_drena_promo())


# ---------- LA CODA DEL CANALE (ott 2026, decisione di Andrea) -------
# «Un articolo a settimana per persona, ma se pubblica altri articoli
# entrano in una coda schedulata per la settimana dopo, in automatico.»
# Fino a ieri il freno `_un_post_per_venditore` li SCARTAVA: chi
# pubblicava tre annunci in una settimana ne vedeva uno in canale, e
# gli altri due non ci arrivavano mai. Adesso chi resta fuori entra in
# `coda_vetrina`, e l'orologio dei dieci minuti lo rimette in fila
# (`accoda_promo`) appena il turno del SUO venditore si libera: uno per
# turno, il piu' vecchio per primo. Il primo annuncio esce SUBITO come
# sempre — la strada scartata ad agosto era far ASPETTARE quello
# («un annuncio puo' restare invisibile in canale per sette giorni»), e
# resta scartata: in coda va solo cio' che ieri si perdeva.
# A ritmo «tutto» (nessun freno) la coda si svuota da sola al primo
# battito. In collaudo il giro e' lo stesso: a non uscire e' bot_api.

# stati da cui un annuncio non torna in vetrina: la riga si toglie
STATI_FUORI_CODA = ("venduto", "rimosso")


def rimanda_in_coda(ids: list[int]):
    """Gli annunci lasciati fuori dal freno entrano in coda. Una riga
    gia' in coda resta col suo `accodato`: rientrarci non la fa
    scivolare in fondo."""
    if not ids:
        return
    con = db()
    try:
        adesso = int(time.time())
        con.executemany("INSERT OR IGNORE INTO coda_vetrina(annuncio_id, "
                        "accodato) VALUES(?,?)", [(i, adesso) for i in ids])
        con.commit()
    finally:
        con.close()


def _chi_esce_dalla_coda(righe: list[dict], giorni: int,
                         adesso: int) -> tuple[list[int], list[int]]:
    """PURA, il giudice della coda: dalle righe in coda (annuncio_id,
    venditore_id, stato, creato, promo_canale_il, ferie_fino, origine)
    a (chi richiamare adesso, chi togliere per sempre).
    - Tolte: l'annuncio che non c'e' piu', venduto o rimosso, e quello
      arrivato da fuori (il canale non li ha mai raccontati).
    - Richiamato: per ogni venditore col turno LIBERO e il negozio
      aperto, il suo piu' vecchio in coda (`creato`, poi l'id) fra
      quelli in vetrina; a freno spento (`giorni` <= 0) tutti.
    - Gli altri aspettano: in revisione, in ferie, turno gia' preso."""
    via, pronti = [], {}
    soglia = adesso - giorni * 86400
    for r in righe:
        if (r.get("stato") is None or r["stato"] in STATI_FUORI_CODA
                or r.get("origine")):
            via.append(r["annuncio_id"])
            continue
        if r["stato"] != "attivo" or in_ferie(r.get("ferie_fino") or 0,
                                              adesso):
            continue
        if giorni > 0 and (r.get("promo_canale_il") or 0) > soglia:
            continue
        pronti.setdefault(r["venditore_id"], []).append(r)
    esce = []
    for suoi in pronti.values():
        suoi.sort(key=lambda r: (r.get("creato") or 0, r["annuncio_id"]))
        esce += [r["annuncio_id"] for r in (suoi if giorni <= 0
                                             else suoi[:1])]
    return sorted(esce), via


async def richiama_coda_vetrina():
    """Dall'orologio: chi in coda ha di nuovo il turno torna nella fila
    del drenatore, e chi non tornera' mai esce dalla coda. La riga si
    toglie PRIMA di accodare: se il drenatore la lasciasse di nuovo
    fuori (un annuncio fresco dello stesso venditore gli ha preso il
    turno nella stessa finestra), ci rientra da sola."""
    if not POST_AUTOMATICI:
        return
    con = db()
    try:
        righe = []
        for r in con.execute(
                "SELECT c.annuncio_id, a.venditore_id, a.stato, a.creato, "
                "a.contatto_nostr, a.fonte, u.promo_canale_il, "
                "u.ferie_fino FROM coda_vetrina c "
                "LEFT JOIN annunci a ON a.id=c.annuncio_id "
                "LEFT JOIN utenti u ON u.tg_id=a.venditore_id"):
            r = dict(r)
            r["origine"] = origine_annuncio(r) if r["stato"] else ""
            righe.append(r)
        if not righe:
            return
        giorni = ritmo_vetrina()[0]
        esce, via = _chi_esce_dalla_coda(righe, giorni, int(time.time()))
        if esce or via:
            con.executemany("DELETE FROM coda_vetrina WHERE annuncio_id=?",
                            [(i,) for i in esce + via])
            con.commit()
    finally:
        con.close()
    for i in esce:
        accoda_promo(i)
    if esce:
        print(f"📣 Coda del canale: {len(esce)} annunci tornano in fila, "
              f"{len(righe) - len(esce) - len(via)} aspettano", flush=True)


async def _drena_promo():
    """Il drenatore: dorme la finestra di raggruppamento, prende TUTTO
    quel che si e' accumulato e applica la regola unica — post singoli
    se sono pochi e il budget orario regge, un solo aggregato
    altrimenti. Rilegge ogni annuncio dal database: chi e' stato
    venduto o rimosso durante l'attesa non viene mai annunciato.

    I tre numeri del ritmo si leggono UNA VOLTA in cima al giro: cosi'
    un `/vetrina` che arriva a meta' drenaggio non fa uscire una parte
    del gruppo con una regola e il resto con un'altra."""
    global _drenatore_promo_avviato
    await asyncio.sleep(ATTESA_RAGGRUPPO)
    ids = list(dict.fromkeys(CODA_PROMO))   # senza doppioni, in ordine
    CODA_PROMO.clear()
    _drenatore_promo_avviato = False   # chi arriva ora fa un giro nuovo
    try:
        annunci = []
        con = db()
        adesso_f = int(time.time())
        for i in ids:
            # il ferie_fino del venditore viaggia col giro: un negozio
            # chiuso non si annuncia in piazza — sarebbe una vetrina
            # che promette una cosa che non si puo' comprare
            a = con.execute(
                "SELECT a.*, u.ferie_fino, u.promo_canale_il, "
                "u.nome AS venditore, u.username AS venditore_username, "
                "u.npub AS venditore_npub, "
                "u.npub_verificata AS venditore_npub_verificata, "
                "u.npub_accesso AS venditore_npub_accesso, "
                "u.negozio AS venditore_negozio "
                "FROM annunci a JOIN utenti u ON u.tg_id=a.venditore_id "
                "WHERE a.id=?", (i,)).fetchone()
            if a and a["stato"] == "attivo" and not origine_annuncio(a) \
                    and not in_ferie(a["ferie_fino"], adesso_f):
                annunci.append(dict(a))
        con.close()
        giorni, max_ora, soglia_aggrega = ritmo_vetrina()
        tutti = annunci
        annunci = _un_post_per_venditore(annunci, giorni)
        # chi il freno lascia fuori non si perde: aspetta il suo turno
        # in coda (vedi «LA CODA DEL CANALE»)
        presi = {a["id"] for a in annunci}
        rimanda_in_coda([a["id"] for a in tutti if a["id"] not in presi])
        if not annunci:
            return
        adesso = time.time()
        _post_promo_recenti[:] = [t for t in _post_promo_recenti
                                  if adesso - t < 3600]
        if (len(annunci) <= soglia_aggrega and
                len(_post_promo_recenti) + len(annunci) <= max_ora):
            for a in annunci:
                await _posta_promo_singolo(a, giorni)
                _post_promo_recenti.append(time.time())
                await asyncio.sleep(PAUSA_TRA_PROMO)
        else:
            # LA RAFFICA SI RACCONTA PER NEGOZIO (ago 2026, decisione di
            # Andrea): chi ne ha pubblicati almeno due in una finestra
            # ha un post SUO — la figura coi barattoli e un link per
            # annuncio — invece di sparire dentro un «📦 N nuovi
            # annunci» che non nomina nessuno. Il caso vero e' proprio
            # quello: le raffiche vengono quasi sempre da UN negozio
            # (l'import CSV), e finora erano la cosa che il canale
            # raccontava peggio.
            # IL TETTO E' QUEL CHE TIENE LA VALVOLA UNA VALVOLA: senza,
            # venti venditori con due annunci a testa farebbero venti
            # post. Oltre `MAX_NEGOZI_RAFFICA` — e per chi ne ha
            # pubblicato UNO solo — resta l'aggregato anonimo di
            # sempre, che passa comunque e non nomina nessuno.
            gruppi = _raggruppa_per_venditore(annunci)
            raccontati = 0
            for gruppo in gruppi[:MAX_NEGOZI_RAFFICA]:
                if len(gruppo) < 2:
                    break          # ordinati per numero: da qui in giu'
                await _posta_negozio(gruppo, giorni)
                _post_promo_recenti.append(time.time())
                raccontati += len(gruppo)
                await asyncio.sleep(PAUSA_TRA_PROMO)
            resto = len(annunci) - raccontati
            if resto:
                await _posta_promo_aggregato(resto)
    except Exception as e:
        print(f"⚠️ Post automatici saltati: {e}")


def _post_vetrina(a) -> int:
    """Il message_id del post nel canale della comunita', o 0.

    Il try non e' cerimonia (e' il pattern di `origine_annuncio`): una
    SELECT che non chiede la colonna nuova — o un database piu'
    vecchio della migrazione, cioe' lo script lanciato a mano — su una
    sqlite3.Row alza IndexError, e qui vorrebbe dire far fallire il ✅
    Venduto anche sul NOSTRO canale, che con questa colonna non
    c'entra niente."""
    try:
        return a["post_vetrina_id"] or 0
    except (KeyError, IndexError):
        return 0


def _post_podcast(a) -> int:
    """Il message_id del post su BitcoinPodcastTelegram, o 0: il gemello
    di `_post_vetrina`, con lo stesso perche' (17 ott 2026, cantiere
    venduto-canale). Al suo posto c'era `a.get(...)`, che una
    sqlite3.Row NON ha: dal 15 ott ogni ✅ Venduto e ogni ritiro dei
    post saltavano su TUTTI i canali, nostro compreso, con «'sqlite3.Row'
    object has no attribute 'get'» nel journal. La riga sqlite si legge
    con le parentesi quadre, e la colonna che manca vale 0."""
    try:
        return a["post_bitcoin_podcast_id"] or 0
    except (KeyError, IndexError):
        return 0


async def _manda_post_canale(dove: str, caption: str, foto: list) -> int:
    """Manda UN post in UN canale e torna il suo message_id (0 se non
    e' partito).

    UNA FABBRICA SOLA PER DUE DESTINAZIONI (ago 2026): il nostro
    canale e quello della comunita' ricevono lo STESSO messaggio, e
    scritto in due posti divergerebbe al primo ritocco — il ripiego
    senza foto, il parse_mode, la caption. Cambia solo il `dove`.

    IL RIPIEGO E' QUELLO DI SEMPRE: con la foto il testo vive nella
    caption, e se Telegram non la digerisce (URL irraggiungibile,
    immagine troppo grande) il post esce come testo invece di non
    uscire."""
    r = None
    if foto:
        r = await bot_api("sendPhoto", {
            "chat_id": dove, "photo": foto[0],
            "caption": caption, "parse_mode": "HTML"})
    if not (r and r.get("ok")):
        r = await bot_api("sendMessage", {
            "chat_id": dove, "text": caption, "parse_mode": "HTML"})
    return r["result"]["message_id"] if r and r.get("ok") else 0


async def _posta_promo_singolo(a: dict, giorni: int):
    """Un annuncio, un post per canale. Ogni canale fallisce per conto
    suo; i riferimenti (message_id, event id) si salvano per il ciclo
    di vita (✅ Venduto, cancellazione).

    `giorni` arriva dal chiamante — che l'ha gia' letto da
    `ritmo_vetrina()` — e non si rilegge qui: a meta' drenaggio un
    `/vetrina` cambierebbe il freno sotto i piedi al gruppo, e mezzo
    gruppo timbrato e mezzo no e' il modo in cui questo freno diventa
    difficile da spiegare."""
    cambio = await cambio_btc_eur()
    # Il timbro del turno si scrive PRIMA dell'invio, il patto delle
    # campagne: un errore di rete puo' far perdere un post di vetrina,
    # mai raddoppiarlo — e qui il doppio sarebbe proprio la cosa che il
    # freno esiste per togliere. Chi salta il turno per un guasto ha
    # comunque il suo annuncio in vetrina, che e' il posto dove si
    # compra.
    # A freno spento NON si timbra, ed e' deliberato: un timbro scritto
    # mentre il ritmo e' «tutto» bloccherebbe per una settimana intera
    # ogni venditore il giorno che qualcuno stringe a «settimana».
    con = db()
    altri = _altri_del_venditore(con, a)
    if giorni > 0 and a.get("venditore_id"):
        con.execute("UPDATE utenti SET promo_canale_il=? WHERE tg_id=?",
                    (int(time.time()), a["venditore_id"]))
        con.commit()
    con.close()
    post_nostr_id, post_canale_id = "", 0
    if _NOSTR:
        try:
            tags = [["t", "barattolo"]]
            if _slug_categoria(a):
                tags.append(["t", _slug_categoria(a)])
            evento = firma_evento(1, tags, _nota_promo(a, cambio))
            if await _spedisci_ai_relay(evento):
                post_nostr_id = evento["id"]
        except Exception as e:
            print(f"⚠️ Nota promo Nostr #{a['id']} saltata: {e}")
    post_vetrina_id = 0
    post_bitcoin_podcast_id = 0
    caption = _caption_canale(a, cambio, altri=altri)
    foto = _foto_url_nostr(a.get("foto", ""))
    if canale_id():
        post_canale_id = await _manda_post_canale(canale_id(), caption, foto)
    # E IL CANALE DELLA COMUNITA' (ago 2026): lo STESSO post, in un
    # canale che non e' nostro, ma solo per chi ha un @USERNAME.
    # IL PERCHE' DEL FILTRO (decisione di Andrea): li' il pubblico e'
    # di gente, non di clienti nostri, e la firma «Annuncio da @tizio»
    # e' la maniglia che si aspetta — un post senza menzione, in casa
    # d'altri, e' un volantino. Chi viene da Nostr non ci compare, e i
    # suoi annunci restano nella vetrina di Barattolo, dove si
    # comprano esattamente come tutti gli altri.
    # NON E' UNA POPOLAZIONE DIVERSA MA UN SOTTOINSIEME: nel NOSTRO
    # canale entrano tutti, come sempre — due canali, due regole, e la
    # piu' stretta e' quella di casa d'altri.
    if canale_vetrina() and (a.get("venditore_username") or ""):
        post_vetrina_id = await _manda_post_canale(
            canale_vetrina(), caption, foto)
    # BitcoinPodcastTelegram (ott 2026): nuovo canale, NO filtro @username
    if canale_bitcoin_podcast():
        post_bitcoin_podcast_id = await _manda_post_canale(
            canale_bitcoin_podcast(), caption, foto)
    if post_nostr_id or post_canale_id or post_vetrina_id or post_bitcoin_podcast_id:
        con = db()
        con.execute(
            "UPDATE annunci SET post_nostr_id=?, post_canale_id=?, "
            "post_vetrina_id=?, post_bitcoin_podcast_id=? WHERE id=?",
            (post_nostr_id, post_canale_id, post_vetrina_id,
             post_bitcoin_podcast_id, a["id"]))
        con.commit()
        con.close()


def _riga_prezzo_lampo(a: dict, percento: int, cambio: float) -> str:
    """Il prezzo del post della lampo: il listino BARRATO e accanto lo
    scontato, ognuno reso da `_prezzo_promo` — cosi' la regola di come
    si scrive un prezzo nel canale (quale valuta per prima, il ≈, il
    caso col cambio muto) resta in un posto solo.

    Sul listino in EURO lo sconto si applica anche all'equivalente in
    sats, che per quei listini e' gia' «l'equivalente al cambio di
    pubblicazione»: la stessa percentuale sulle due facce, o la riga
    direbbe due sconti diversi."""
    scontato = dict(a)
    sats, eur = _prezzo_lampo(a, percento)
    scontato["prezzo_sats"] = sats or (
        a["prezzo_sats"] * (100 - percento) // 100)
    scontato["prezzo_eur"] = eur
    return (f"<s>{_prezzo_promo(a, cambio)}</s> → "
            f"<b>{_prezzo_promo(scontato, cambio)}</b>")


async def promo_lampo(annuncio_id: int, percento: int, scadenza: int):
    """Lo sconto lampo raccontato nel canale (ago 2026, chiesto da
    Andrea). Gancio in coda a `lancia_lampo`, in create_task e DOPO il
    commit: il patto di `accoda_promo` — un post fallito non deve mai
    rompere il lancio di uno sconto.

    UN POST NUOVO, E L'ORIGINALE NON SI TOCCA. La lampo non cambia
    `prezzo_sats` (il listino non si tocca MAI, e' la regola sua),
    quindi il post di quando l'annuncio e' nato non mente: dice il
    listino, che e' ancora vero. E' la differenza col ✅ Venduto, che
    invece riscrive quel post — li' a cambiare era la DISPONIBILITA',
    qui si aggiunge un'occasione a tempo. Cosi' non c'e' niente da
    dis-editare alla scadenza.

    SOLO CANALE, NIENTE NOSTR, ed e' una regola gia' scritta altrove:
    lo sconto e' LOCALE, cioe' il vantaggio di chi compra dentro
    Barattolo, e il NIP-99 parla il prezzo pieno per costruzione.

    CONSUMA IL BUDGET ORARIO e a budget pieno SALTA invece di
    aggregare (una lampo aggregata non direbbe niente di utile).
    Senza, il tetto dei post si aggirerebbe lanciando sconti:
    MAX_LAMPO_SETTIMANA e' 2 *per annuncio*, quindi chi ne ha cinquanta
    puo' fare cento lampo a settimana. Una lampo persa e' un post
    perso, non un ordine perso — chi la cerca ha la vetrina col filtro
    «⚡ In offerta».

    IMPERFEZIONE DICHIARATA: se l'annuncio si vende mentre la lampo e'
    viva, questo post resta senza il ✅ (l'originale ce l'ha). Il testo
    e' DATATO — «fino alle 18:00» — e il link apre la scheda vera, che
    dice sempre la verita'; nessuno puo' pagare. Se in rodaggio dara'
    fastidio la leva e' una colonna `post_lampo_id` piu' una riga in
    `promo_venduto`: qui si e' scelto di non raddoppiare il ciclo di
    vita per un post che si autodata."""
    if not (POST_AUTOMATICI and POST_LAMPO_CANALE and canale_id()):
        return
    try:
        con = db()
        # si rilegge dal database e non ci si fida del payload, e con
        # le guardie di _posta_promo_singolo: un negozio in ferie o un
        # annuncio importato non si annunciano in piazza
        a = con.execute(
            "SELECT a.*, u.ferie_fino FROM annunci a "
            "JOIN utenti u ON u.tg_id=a.venditore_id WHERE a.id=?",
            (annuncio_id,)).fetchone()
        con.close()
        adesso = time.time()
        if not a or a["stato"] != "attivo" or origine_annuncio(a) \
                or in_ferie(a["ferie_fino"], int(adesso)) \
                or a["lampo_scadenza"] <= adesso:
            return
        _post_promo_recenti[:] = [t for t in _post_promo_recenti
                                  if adesso - t < 3600]
        if len(_post_promo_recenti) >= ritmo_vetrina()[1]:
            print(f"⚡ Lampo #{annuncio_id} non annunciata: budget orario "
                  f"dei post esaurito")
            return
        a = dict(a)
        cambio = await cambio_btc_eur()
        testo = (f"⚡ <b>-{percento}%</b> su "
                 f"<b>{html.escape(a['titolo'])}</b>"
                 f"\n💰 {_riga_prezzo_lampo(a, percento, cambio)}"
                 f"\n⏳ solo fino {_quando_scade(scadenza)}"
                 f"\n\n{link_telegram('annuncio', a['id'])}"
                 f"\n\n{_hashtag_promo(a)}")
        r = await bot_api("sendMessage", {
            "chat_id": canale_id(), "text": testo,
            "parse_mode": "HTML", "disable_web_page_preview": True})
        if r and r.get("ok"):
            _post_promo_recenti.append(time.time())
    except Exception as e:
        print(f"⚠️ Post della lampo #{annuncio_id} saltato: {e}")


def _raggruppa_per_venditore(annunci: list) -> list:
    """Gli annunci raccolti per venditore, i gruppi PIU' NUMEROSI per
    primi — sono quelli che la figura serve meglio, e quelli che
    dentro un aggregato anonimo si perdevano di piu'.

    PURA come le sorelle del canale: righe in, righe out. A pari
    numero comanda l'ordine di ARRIVO (la coda e' cronologica), o due
    negozi con due annunci a testa si scambierebbero di posto a ogni
    finestra senza motivo."""
    per_uno: dict = {}
    for a in annunci:
        per_uno.setdefault(a["venditore_id"], []).append(a)
    return sorted(per_uno.values(), key=lambda g: -len(g))


def _riga_negozio(a: dict, cambio: float) -> str:
    """Una riga della didascalia: l'emoji del reparto, il titolo che E'
    il link, e il prezzo. Il titolo passa da `html.escape` — la
    didascalia e' HTML e un «<» spegne il messaggio in silenzio, ed e'
    la lezione dell'avviso di spedizione."""
    return (f"{EMOJI_CATEGORIA.get(a.get('categoria'), '📦')} "
            f"{html.escape(a['titolo'])} ({link_telegram('annuncio', a['id'])})"
            f" — {_prezzo_promo(a, cambio)}")


async def _posta_negozio(gruppo: list, giorni: int):
    """UN post per il negozio che ha pubblicato piu' cose insieme: la
    figura coi tre barattoli in FILA (non un podio: qui non c'e' nessuna
    classifica, sono tre cose dello stesso banco) e un link per
    annuncio nella didascalia.

    I TRE DELLA FIGURA SONO I PIU' RECENTI, i link li elenca TUTTI fino
    al tetto della didascalia: la figura ha una forma sola da tarare e
    da guardare, l'elenco puo' crescere. Oltre il tetto si dice quanti
    ne restano invece di troncare in silenzio.

    Fail-open come il resto del canale: se la figura non si compone si
    manda comunque il testo coi link, che e' la parte che serve."""
    gruppo = sorted(gruppo, key=lambda a: (a.get("creato") or 0, a["id"]),
                    reverse=True)
    cambio = await cambio_btc_eur()
    # il timbro del turno, come per il post singolo: un post-negozio E'
    # il turno di quel venditore, e a freno acceso non deve poterne
    # avere un secondo (oggi non ci si arriva — col freno ognuno ha un
    # annuncio solo e questo ramo non parte — ma la regola vale lo
    # stesso, ed e' quella che reggera' se il freno cambia)
    if giorni > 0 and gruppo[0].get("venditore_id"):
        con = db()
        con.execute("UPDATE utenti SET promo_canale_il=? WHERE tg_id=?",
                    (int(time.time()), gruppo[0]["venditore_id"]))
        con.commit()
        con.close()
    righe = [_riga_negozio(a, cambio) for a in gruppo[:MAX_LINK_NEGOZIO]]
    restanti = len(gruppo) - len(righe)
    if restanti:
        righe.append(f"…e altri {restanti} nel suo negozio")
    chi = _firma_venditore(gruppo[0]).replace("Annuncio da ", "")
    testo = (f"🫙 <b>{len(gruppo)} nuovi annunci</b>\n\n"
             + "\n".join(righe) + f"\n\n{chi}\n\n#barattolo")
    con = db()
    nome = _salva_figura_negozio(con, gruppo)
    con.close()
    r = None
    if nome:
        r = await bot_api("sendPhoto", {
            "chat_id": canale_riepilogo(), "parse_mode": "HTML",
            "photo": f"{URL_PUBBLICO}/foto/{nome}", "caption": testo})
    if not (r and r.get("ok")):
        await bot_api("sendMessage", {
            "chat_id": canale_id(), "parse_mode": "HTML",
            "disable_web_page_preview": True, "text": testo})


def _salva_figura_negozio(con, gruppo: list) -> str:
    """La figura in FILA coi tre piu' recenti del gruppo. Torna il nome
    del file o '' — e allora il post esce di solo testo, che coi link
    dentro e' comunque quel che serve."""
    if not (RIEPILOGO_IMMAGINE and gruppo
            and ImmaginePillow and ImageDraw and ImageOps):
        return ""
    try:
        tre = [{"annuncio_id": a["id"]} for a in gruppo[:3]]
        nome = (f"neg_{gruppo[0]['venditore_id']}_"
                f"{int(time.time())}.jpg")
        disegna_figura(_foto_podio(con, tre), FILA_MISURE).save(
            os.path.join(FOTO_DIR, nome), quality=88)
        return nome
    except Exception as e:
        print(f"⚠️ Figura del negozio saltata: {e}")
        return ""


async def _posta_promo_aggregato(n: int):
    """Il post valvola delle raffiche: niente nomi, solo il conto e il
    link alla vetrina. Nessun ciclo di vita (non nomina nessuno)."""
    conto = "1 nuovo annuncio" if n == 1 else f"{n} nuovi annunci"
    testo = f"📦 {conto} nel barattolo → {URL_PUBBLICO}"
    if _NOSTR:
        try:
            await _spedisci_ai_relay(
                firma_evento(1, [["t", "barattolo"]], testo))
        except Exception as e:
            print(f"⚠️ Nota promo aggregata saltata: {e}")
    if canale_id():
        await bot_api("sendMessage",
                      {"chat_id": canale_id(), "text": testo})


# ============ LA CASSA DI RISONANZA SU X (9 ott 2026) ===============
# I post che Barattolo scrive su Nostr — le note kind 1 della npub
# ufficiale, scritte da una persona con un client — escono anche su X,
# ripubblicate da QUI con l'API ufficiale (v2, contesto utente, firma
# OAuth 1.0a con le quattro chiavi dell'app). X e' la cassa di
# risonanza: chi sta la' legge quel che e' nato qua, e Nostr resta la
# casa.
#
# COSA ESCE E COSA NO (richiesta di Andrea):
#  · SOLO GLI ORIGINALI della npub ufficiale: niente risposte (tag `e`),
#    niente citazioni e repost (tag `q`, kind 6/16 che qui nemmeno si
#    chiedono), niente note di altre chiavi anche se un relay le
#    servisse (il filtro `authors` e' una domanda al relay, la firma e'
#    la prova: `_x_firma_valida`);
#  · NIENTE NOTE DI CASA: le note kind 1 che il SERVER stesso firma —
#    la promo di ogni annuncio (`_posta_promo_singolo`), l'aggregato
#    («N nuovi annunci nel barattolo») — sono prodotti del mercatino
#    uno per uno, cioe' lo spam che questa cassa non deve fare. Ogni
#    kind 1 che esce da `_spedisci_ai_relay` si timbra prima in
#    `x_post` con esito `di_casa`, e il lettore lo salta;
#  · i PRODOTTI (NIP-99, kind 30402) non si ripubblicano mai uno per
#    uno: al loro posto, spento di serie, UN post al giorno «Nuovi
#    arrivi di oggi nel mercatino: N annunci» con fino a 4 foto e
#    senza link (`X_RIEPILOGO_GIORNO`);
#  · DI SERIE SENZA LINK: X fa pagare 0,200 $ un post con un URL e
#    0,015 $ uno senza (docs.x.com/x-api/getting-started/pricing, letto
#    il 9 ott 2026). `X_CON_LINK` aggiunge il link njump alla nota; i
#    link che la persona ha scritto NEL testo restano suoi, e il costo
#    stimato li conta (il journal lo dice).
#
# IL TESTO: fino a 280 (il peso di X: URL = 23, emoji e ideogrammi = 2);
# oltre si taglia su una parola intera e si chiude con «… continua su
# Nostr». Le immagini della nota (tag `imeta` NIP-92, o URL con
# estensione nel testo) si CARICANO su X — fino a 4 — e si tolgono dal
# testo, o varrebbero come URL e costerebbero 0,200 $; i video pure
# (il caricamento a pezzi di /2/media/upload: initialize, append,
# finalize, poi lo stato finche' «succeeded»). X vuole o foto o UN
# video: con un video le foto restano su Nostr.
#
# NIENTE DOPPIONI: `x_post` tiene l'id dell'evento Nostr (chiave) e l'id
# del post X. ALLA PRIMA ACCENSIONE NON SI RIPUBBLICA NIENTE: la
# lancetta `x_dal` (in `impostazioni`) nasce ad «adesso», e le note di
# prima non si guardano.
#
# IL RITMO E' PRUDENTE: una lettura dei relay ogni X_GIRO_S, un post
# alla volta con X_PAUSA_S fra uno e l'altro (il limite di X e' 100 per
# 15 minuti per utente: qui non ci si avvicina nemmeno). Un 429 o un
# 5xx si riprova a distanza (5, 15, 45 minuti), poi la nota si segna
# `rifiutata` e si va avanti: un rifiuto di X e' una riga nel journal,
# mai un compito che si ferma. Il resto del server non sa che X
# esiste: e' un orologio in sottofondo, fail-open come tutti.
#
# LE LEVE si AGGIUNGONO al config del VPS col patto delle altre
# (nascono spente; le chiavi mai nel repo, mai nei log — il journal
# dice i FATTI: «chiavi presenti», mai un valore): X_RIPUBBLICA,
# X_CON_LINK, X_RIEPILOGO_GIORNO, X_PROVA (scrive nel journal cosa
# avrebbe pubblicato, X non viene chiamato), le quattro chiavi, X_NPUB
# e X_API_BASE (solo per i collaudi: un X di cartone sul loopback). Il
# pannello «⚙️ Stato delle leve» le mostra; la procedura per Andrea sta
# in PRODUZIONE, «LA CASSA DI RISONANZA SU X»; il verbale in CANTIERI.
try:
    from config import X_RIPUBBLICA
except ImportError:
    X_RIPUBBLICA = False
try:
    from config import X_CON_LINK
except ImportError:
    X_CON_LINK = False
try:
    from config import X_RIEPILOGO_GIORNO
except ImportError:
    X_RIEPILOGO_GIORNO = False
try:
    from config import X_PROVA
except ImportError:
    X_PROVA = False
# Le quattro chiavi dell'app su X (OAuth 1.0a, contesto utente). SOLO
# nel config del VPS: segnaposto in config_esempio, forme nello scanner
# dei segreti della CI. Qui dentro si leggono in DUE posti soltanto:
# `x_configurato` (c'e' / non c'e') e `_x_oauth1` (la firma).
try:
    from config import (X_API_KEY, X_API_SECRET, X_ACCESS_TOKEN,
                        X_ACCESS_SECRET)
except ImportError:
    X_API_KEY = X_API_SECRET = X_ACCESS_TOKEN = X_ACCESS_SECRET = ""
# La npub ufficiale di Barattolo: e' quella che Andrea usa dal client,
# NON la chiave con cui il server firma gli annunci (che puo' essere
# un'altra, e in collaudo lo e'). Dichiarabile nel config per i giri di
# prova con una chiave usa-e-getta.
try:
    from config import X_NPUB
except ImportError:
    X_NPUB = "npub19ea0u0u6lrpaeyxkazk27ht64yn22ncvytcu24tswvyuqk07svds63txqy"
# La base dell'API: cambia SOLO nei collaudi (un X di cartone su
# 127.0.0.1). In collaudo verso un X che non e' di casa non esce
# niente, come per i relay e per Blossom.
try:
    from config import X_API_BASE
except ImportError:
    X_API_BASE = "https://api.x.com"

X_LIMITE = 280                      # il peso massimo di un post
X_CODA = "… continua su Nostr"      # la chiusura di un testo tagliato
X_PESO_URL = 23                     # un URL pesa 23, qualunque lunghezza
X_COSTO_POST = 0.015                # $ a post semplice (pay-per-use)
X_COSTO_LINK = 0.200                # $ a post con un URL
X_GIRO_S = 300                      # ogni quanto si leggono i relay
X_PAUSA_S = 60                      # fra un post e l'altro
X_RIPROVA_MIN = (5, 15, 45)         # le attese dopo un 429 o un 5xx
X_PEZZO = 4 * 1024 * 1024           # un pezzo dell'upload (X: max 5 MB)
X_IMG_MAX = 5 * 1024 * 1024         # X: 5 MB per foto
X_GIF_MAX = 15 * 1024 * 1024        # X: 15 MB per GIF
X_VIDEO_MAX = 256 * 1024 * 1024     # il nostro tetto (X ne accetta 8 GB)
X_RIEPILOGO_ORA = 18                # l'ora italiana del post del giorno
X_RIEPILOGO_TESTO = "🫙 Nuovi arrivi di oggi nel mercatino: {conto}"
X_EST_IMMAGINI = (".jpg", ".jpeg", ".png", ".gif", ".webp")
X_EST_VIDEO = (".mp4", ".mov", ".webm", ".m4v")
X_URL_RE = re.compile(r"https?://[^\s<>\"']+")
X_PAGINA_NJUMP = "https://njump.me/"


def x_configurato() -> bool:
    """Le quattro chiavi ci sono e non sono il segnaposto. E' il FATTO
    che esce nel pannello e nel journal: mai un valore."""
    chiavi = (X_API_KEY, X_API_SECRET, X_ACCESS_TOKEN, X_ACCESS_SECRET)
    return all(isinstance(c, str) and c.strip() and "INCOLLA_QUI" not in c
               for c in chiavi)


def _x_base_di_casa() -> bool:
    """L'API di X sta su questa macchina? Solo nei collaudi."""
    return relay_di_casa(str(X_API_BASE or "").replace("http", "ws", 1))


def x_in_prova() -> bool:
    """IL GIUDICE della modalita' prova: la leva, oppure il collaudo
    verso un X che non e' di casa (da qui non esce niente, mai)."""
    return bool(X_PROVA) or (bool(MODALITA_COLLAUDO) and not _x_base_di_casa())


def x_ripubblica_viva() -> bool:
    """La leva LETTA VIVA, come `cassaforte_nuova`: accesa senza le
    chiavi e senza la prova vale SPENTA."""
    return bool(X_RIPUBBLICA) and (x_configurato() or x_in_prova())


def x_riepilogo_vivo() -> bool:
    return bool(X_RIEPILOGO_GIORNO) and (x_configurato() or x_in_prova())


def x_npub_hex() -> str:
    """La chiave ufficiale in esadecimale, '' se la riga e' storta."""
    try:
        chiave = str(X_NPUB or "").strip()
        if re.fullmatch(r"[0-9a-fA-F]{64}", chiave):
            return chiave.lower()
        return npub_to_hex(chiave).lower()
    except Exception:
        return ""


def x_pesa(testo: str) -> int:
    """Il peso di un testo come lo conta X: ogni URL vale 23, i
    caratteri latini (e la punteggiatura comune) 1, emoji e ideogrammi
    2. E' il conto della «weighted length» del loro twitter-text."""
    peso = 0
    resto = X_URL_RE.sub("", testo)
    peso += X_PESO_URL * len(X_URL_RE.findall(testo))
    for c in resto:
        o = ord(c)
        if (o <= 4351 or 8192 <= o <= 8205 or 8208 <= o <= 8223
                or 8242 <= o <= 8247):
            peso += 1
        else:
            peso += 2
    return peso


def x_taglia(testo: str, limite: int = X_LIMITE, coda: str = X_CODA) -> str:
    """Il testo entro il limite: intero se ci sta, sennò tagliato su una
    PAROLA intera e chiuso con la coda. Un taglio a meta' parola e' il
    segno di un robot, e questa cassa deve sembrare scritta da chi ha
    scritto la nota."""
    testo = testo.strip()
    if x_pesa(testo) <= limite:
        return testo
    budget = limite - x_pesa(" " + coda)
    parole = testo.split()
    tenuto = ""
    for p in parole:
        candidato = (tenuto + " " + p).strip()
        if x_pesa(candidato) > budget:
            break
        tenuto = candidato
    if not tenuto:
        # una sola parola piu' lunga del budget (un muro di caratteri):
        # si taglia a caratteri, e' l'unico caso
        tenuto = parole[0] if parole else ""
        while tenuto and x_pesa(tenuto) > budget:
            tenuto = tenuto[:-1]
    tenuto = tenuto.rstrip(" ,;:.-—–")
    return f"{tenuto} {coda}".strip()


def x_originale(ev, nostra_hex: str) -> bool:
    """PURA: la nota e' un originale della npub ufficiale? Kind 1,
    pubkey nostra, nessun tag `e` (risposta) ne' `q` (citazione), un
    contenuto non vuoto."""
    if not isinstance(ev, dict) or ev.get("kind") != 1:
        return False
    if not nostra_hex or str(ev.get("pubkey", "")).lower() != nostra_hex:
        return False
    for t in ev.get("tags") or []:
        if isinstance(t, list) and t and t[0] in ("e", "q"):
            return False
    return bool(str(ev.get("content") or "").strip())


def _x_firma_valida(ev) -> bool:
    """L'id rifatto dalla serializzazione NIP-01 e la firma Schnorr su
    quell'id: con coincurve dov'e' (il VPS), con `schnorr_puro` dove non
    c'e' (la CI). Senza nessuno dei due nessuna nota si crede."""
    try:
        pubkey, sig, ev_id = ev["pubkey"], ev["sig"], ev["id"]
        rifatto = evento_non_firmato(pubkey, int(ev["kind"]), ev["tags"],
                                     ev["content"], int(ev["created_at"]))
        if rifatto["id"] != ev_id:
            return False
        if ChiavePubblicaNostr is not None:
            return bool(ChiavePubblicaNostr(bytes.fromhex(pubkey)).verify(
                bytes.fromhex(sig), bytes.fromhex(ev_id)))
        import schnorr_puro
        return bool(schnorr_puro.verifica(bytes.fromhex(pubkey),
                                          bytes.fromhex(ev_id),
                                          bytes.fromhex(sig)))
    except Exception:
        return False


def _x_bech32(hrp: str, hexdati: str) -> str:
    """Un id in bech32 (`note1…`) per il link njump: lo stesso
    `_bech32_polymod` di hex_to_npub, con l'hrp che serve."""
    alfabeto = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
    dati, bits, val = [], 0, 0
    for byte in bytes.fromhex(hexdati):
        val = (val << 8) | byte
        bits += 8
        while bits >= 5:
            bits -= 5
            dati.append((val >> bits) & 31)
    if bits:
        dati.append((val << (5 - bits)) & 31)
    espansa = [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]
    polymod = _bech32_polymod(espansa + dati + [0] * 6) ^ 1
    checksum = [(polymod >> 5 * (5 - i)) & 31 for i in range(6)]
    return hrp + "1" + "".join(alfabeto[d] for d in dati + checksum)


def x_link_nota(ev_id: str) -> str:
    return X_PAGINA_NJUMP + _x_bech32("note", ev_id)


def _x_media_di(ev) -> tuple:
    """(immagini, video): gli URL dei media della nota, dai tag `imeta`
    (NIP-92: «url …», «m …») e dagli URL con estensione nel testo. In
    ordine, senza doppioni."""
    immagini, video, visti = [], [], set()

    def metti(url, mime=""):
        url = str(url or "").strip()
        if not url.startswith("http") or url in visti:
            return
        basso = url.split("?", 1)[0].lower()
        if mime.startswith("video/") or basso.endswith(X_EST_VIDEO):
            video.append(url)
            visti.add(url)
        elif mime.startswith("image/") or basso.endswith(X_EST_IMMAGINI):
            immagini.append(url)
            visti.add(url)

    for t in ev.get("tags") or []:
        if isinstance(t, list) and t and t[0] == "imeta":
            campi = {}
            for voce in t[1:]:
                k, _, v = str(voce).partition(" ")
                campi.setdefault(k, v)
            metti(campi.get("url", ""), campi.get("m", ""))
    for url in X_URL_RE.findall(str(ev.get("content") or "")):
        metti(url)
    return immagini, video


def x_costo(testo: str) -> float:
    """La stima di X: con un URL nel testo il post costa 0,200 $, sennò
    0,015 $. I media caricati non si pagano a parte (il listino non li
    elenca); «Media Metadata» e' un'altra chiamata, che non facciamo."""
    return X_COSTO_LINK if X_URL_RE.search(testo) else X_COSTO_POST


def x_prepara(ev, con_link: bool = False) -> dict:
    """Dalla nota al post: il testo senza gli URL dei media caricati,
    tagliato al peso di X (con lo spazio per il link njump, se chiesto),
    le foto (al piu' 4) e il video (al piu' 1, e allora niente foto).
    PURA: niente rete, niente database."""
    immagini, video = _x_media_di(ev)
    testo = str(ev.get("content") or "")
    for url in immagini + video:
        testo = testo.replace(url, " ")
    righe = [" ".join(r.split()) for r in testo.split("\n")]
    testo = "\n".join(righe)
    testo = re.sub(r"\n{3,}", "\n\n", testo).strip()
    link = x_link_nota(ev["id"]) if con_link and ev.get("id") else ""
    limite = X_LIMITE - (X_PESO_URL + 1 if link else 0)
    testo = x_taglia(testo, limite)
    if link:
        testo = f"{testo}\n{link}" if testo else link
    if video:
        immagini = []
    return {"testo": testo, "immagini": immagini[:4], "video": video[:1],
            "costo": x_costo(testo)}


# --- La firma OAuth 1.0a e le chiamate -------------------------------

def _x_percent(s) -> str:
    from urllib.parse import quote
    return quote(str(s), safe="-._~")


def _x_oauth1(metodo: str, url: str, parametri: dict = None,
              chiavi: tuple = None, nonce: str = "", quando: int = 0) -> str:
    """L'intestazione `Authorization: OAuth …` (HMAC-SHA1) per UNA
    richiesta. `parametri` sono query e corpo form-urlencoded (un corpo
    JSON o multipart non si firma: e' la regola di OAuth 1.0a).
    `chiavi`, `nonce` e `quando` si passano solo nelle prove, col
    vettore pubblicato da docs.x.com."""
    ck, cs, tk, ts = chiavi or (X_API_KEY, X_API_SECRET,
                                X_ACCESS_TOKEN, X_ACCESS_SECRET)
    oauth = {
        "oauth_consumer_key": ck,
        "oauth_nonce": nonce or secrets.token_hex(16),
        "oauth_signature_method": "HMAC-SHA1",
        "oauth_timestamp": str(quando or int(time.time())),
        "oauth_token": tk,
        "oauth_version": "1.0",
    }
    tutti = dict(parametri or {})
    tutti.update(oauth)
    coppie = sorted((_x_percent(k), _x_percent(v)) for k, v in tutti.items())
    stringa = "&".join(f"{k}={v}" for k, v in coppie)
    base = f"{metodo.upper()}&{_x_percent(url)}&{_x_percent(stringa)}"
    chiave = f"{_x_percent(cs)}&{_x_percent(ts)}"
    firma = base64.b64encode(hmac.new(chiave.encode(), base.encode(),
                                      hashlib.sha1).digest()).decode()
    oauth["oauth_signature"] = firma
    return "OAuth " + ", ".join(
        f'{_x_percent(k)}="{_x_percent(v)}"' for k, v in sorted(oauth.items()))


class XRifiuta(Exception):
    """X ha risposto, e ha detto di no. `status` dice se si riprova (429
    e 5xx) o se la nota si lascia li' (il resto)."""

    def __init__(self, status: int, perche: str):
        super().__init__(f"HTTP {status} {perche}".strip())
        self.status = status


async def _x_chiama(metodo: str, percorso: str, *, params: dict = None,
                    json_corpo=None, form: dict = None, files: dict = None,
                    timeout: float = 30):
    """UNA chiamata a X, firmata. Torna (status, corpo-dict). L'URL per
    la firma e' senza query; i `params` e il `form` (se non c'e' un
    file) entrano nella firma. L'intestazione non si stampa MAI."""
    url = f"{str(X_API_BASE).rstrip('/')}{percorso}"
    da_firmare = dict(params or {})
    if form and not files:
        da_firmare.update(form)
    intestazioni = {"Authorization": _x_oauth1(metodo, url, da_firmare),
                    "User-Agent": "Barattolo/1.0 (+https://barattolo.store)"}
    async with httpx.AsyncClient(timeout=timeout) as c:
        r = await c.request(metodo, url, params=params, json=json_corpo,
                            data=form, files=files, headers=intestazioni)
    try:
        corpo = r.json()
    except ValueError:
        corpo = {}
    return r.status_code, (corpo if isinstance(corpo, dict) else {})


def _x_perche(status: int, corpo: dict) -> str:
    """Il motivo di X in una riga corta, senza il corpo intero."""
    voci = []
    for e in (corpo.get("errors") or [])[:2]:
        if isinstance(e, dict):
            voci.append(str(e.get("message") or e.get("detail") or "")[:80])
    if not voci and corpo.get("detail"):
        voci.append(str(corpo["detail"])[:80])
    if not voci and corpo.get("title"):
        voci.append(str(corpo["title"])[:80])
    return "; ".join(v for v in voci if v)


X_MEDIA_SALTI = 4       # i redirect che si seguono, ognuno giudicato


async def _x_media_ammesso(url: str) -> bool:
    """Il giudice di OGNI indirizzo a cui `_x_scarica` bussa. Le foto di
    casa (`URL_PUBBLICO/foto/...`) passano senza chiedere al DNS: le
    serve la nostra rotta, e il nostro nome visto dal VPS puo' anche
    risolvere dentro casa. Tutto il resto lo giudica `url_foto_ammesso`,
    il guardiano di ogni URL scritto da un utente (nel suo thread: fa
    una risoluzione DNS).
    UN INDIRIZZO DI CASA VALE SOLO IN COLLAUDO, come il relay di casa:
    li' i media delle note stanno su una porta di loopback del banco
    (`collaudo_x_risonanza`), in produzione e' proprio la porta che
    questo giudice chiude."""
    if url.startswith(f"{URL_PUBBLICO}/foto/"):
        return True
    if MODALITA_COLLAUDO and relay_di_casa(url):
        return True
    return await asyncio.to_thread(url_foto_ammesso, url)


async def _x_scarica(url: str, tetto: int) -> tuple:
    """(byte, mime) di un media della nota, entro il tetto. Oltre, o se
    non e' un'immagine/un video, si torna (b'', '') e il post esce
    senza.
    NON E' PIU' UNA PORTA SENZA GUARDIA (14 nov 2026, cantiere
    audit-chiusure, dal primo audit di sicurezza). Nasceva per i media
    delle NOSTRE note, ma il riepilogo del giorno gli passa le foto
    degli annunci, e quelle di un annuncio importato da Nostr sono
    indirizzi scritti da chi firma l'evento — proprio quelli che il
    guardiano dell'import ha rifiutato restano in colonna grezzi. Senza
    giudice e coi redirect seguiti da httpx, il server bussava a un
    indirizzo di casa o della rete privata scelto da uno sconosciuto, e
    il corpo partiva verso X. Ora ogni indirizzo — la partenza e ogni
    salto, al piu' X_MEDIA_SALTI — passa da `_x_media_ammesso`, e
    httpx non segue niente da solo."""
    partenza = url
    try:
        async with httpx.AsyncClient(timeout=60, follow_redirects=False) as c:
            for _ in range(X_MEDIA_SALTI + 1):
                if not await _x_media_ammesso(url):
                    print(f"🐦 X: media non scaricato, indirizzo non "
                          f"ammesso: {url[:80]}", flush=True)
                    return b"", ""
                async with c.stream("GET", url) as r:
                    if r.status_code in (301, 302, 303, 307, 308):
                        dove = r.headers.get("location") or ""
                        if not dove:
                            return b"", ""
                        url = urllib.parse.urljoin(url, dove)
                        continue
                    if r.status_code != 200:
                        return b"", ""
                    mime = (r.headers.get("content-type")
                            or "").split(";")[0].strip()
                    pezzi, totale = [], 0
                    async for pezzo in r.aiter_bytes():
                        totale += len(pezzo)
                        if totale > tetto:
                            return b"", ""
                        pezzi.append(pezzo)
                    break
            else:
                return b"", ""          # troppi salti: non e' una foto
        raw = b"".join(pezzi)
    except Exception:
        return b"", ""
    url = partenza          # l'estensione si legge dall'indirizzo scritto
    if not mime.startswith(("image/", "video/")):
        basso = url.split("?", 1)[0].lower()
        if basso.endswith(X_EST_VIDEO):
            mime = "video/mp4"
        elif basso.endswith(".png"):
            mime = "image/png"
        elif basso.endswith(".gif"):
            mime = "image/gif"
        elif basso.endswith(".webp"):
            mime = "image/webp"
        else:
            mime = "image/jpeg"
    return raw, mime


async def _x_carica_media(raw: bytes, mime: str) -> str:
    """Il caricamento a pezzi dell'API media v2 di X — initialize,
    append (pezzi da X_PEZZO), finalize, e lo stato finche' il video e'
    «succeeded». Torna l'id del media (`data.id`). Un no di X e' un
    XRifiuta."""
    if mime.startswith("video/"):
        categoria = "tweet_video"
    elif mime == "image/gif":
        categoria = "tweet_gif"
    else:
        categoria = "tweet_image"
    status, corpo = await _x_chiama("POST", "/2/media/upload/initialize",
                                    json_corpo={"media_type": mime,
                                                "total_bytes": len(raw),
                                                "media_category": categoria})
    media_id = str((corpo.get("data") or {}).get("id") or "")
    if status >= 300 or not media_id:
        raise XRifiuta(status, "initialize: " + _x_perche(status, corpo))
    for i in range(0, max(1, (len(raw) + X_PEZZO - 1) // X_PEZZO)):
        pezzo = raw[i * X_PEZZO:(i + 1) * X_PEZZO]
        status, corpo = await _x_chiama(
            "POST", f"/2/media/upload/{media_id}/append",
            form={"segment_index": str(i)},
            files={"media": ("pezzo", pezzo, "application/octet-stream")},
            timeout=120)
        if status >= 300:
            raise XRifiuta(status, f"append {i}: " + _x_perche(status, corpo))
    status, corpo = await _x_chiama("POST", f"/2/media/upload/{media_id}/finalize")
    if status >= 300:
        raise XRifiuta(status, "finalize: " + _x_perche(status, corpo))
    info = (corpo.get("data") or {}).get("processing_info") or {}
    giri = 0
    while info and info.get("state") not in ("succeeded", "failed"):
        giri += 1
        if giri > 30:
            raise XRifiuta(0, "il media non e' pronto dopo 30 controlli")
        await asyncio.sleep(min(10, max(1, int(info.get("check_after_secs") or 2))))
        status, corpo = await _x_chiama("GET", "/2/media/upload",
                                        params={"command": "STATUS",
                                                "media_id": media_id})
        if status >= 300:
            raise XRifiuta(status, "status: " + _x_perche(status, corpo))
        info = (corpo.get("data") or {}).get("processing_info") or {}
    if info.get("state") == "failed":
        raise XRifiuta(0, "X non ha digerito il media")
    return media_id


async def _x_posta(testo: str, media_ids: list) -> str:
    """POST /2/tweets: torna l'id del post. Un no di X e' un XRifiuta."""
    corpo = {"text": testo}
    if media_ids:
        corpo["media"] = {"media_ids": [str(m) for m in media_ids]}
    status, risposta = await _x_chiama("POST", "/2/tweets", json_corpo=corpo)
    post_id = str((risposta.get("data") or {}).get("id") or "")
    if status >= 300 or not post_id:
        raise XRifiuta(status, _x_perche(status, risposta))
    return post_id


# --- Il registro, la lancetta e le note di casa ----------------------

def _x_prepara_tabella(con):
    """`x_post`: una riga per nota, l'id dell'evento Nostr e' la chiave
    — e' cosi' che un doppione non puo' nascere. `evento` e' la nota
    intera (JSON): i tentativi dopo il primo ripartono da li', non dai
    relay."""
    con.execute("""CREATE TABLE IF NOT EXISTS x_post(
        evento_id TEXT PRIMARY KEY,
        creato_nota INTEGER DEFAULT 0,
        evento TEXT DEFAULT '',
        esito TEXT DEFAULT 'in_coda',
        -- in_coda | riprova | pubblicato | prova | rifiutato | di_casa
        post_x_id TEXT DEFAULT '',
        testo_x TEXT DEFAULT '',
        costo_usd REAL DEFAULT 0,
        tentativi INTEGER DEFAULT 0,
        riprova_il INTEGER DEFAULT 0,
        ultimo_errore TEXT DEFAULT '',
        creato INTEGER DEFAULT 0,
        pubblicato_il INTEGER DEFAULT 0)""")


def _x_segna_di_casa(evento_id: str):
    """Una nota kind 1 firmata dal SERVER: si timbra prima che parta,
    cosi' il lettore la riconosce anche dopo un riavvio. Fail-open:
    questo gancio sta sulla strada delle promo, e una promo non deve
    mai cadere per via di X."""
    try:
        con = db()
        _x_prepara_tabella(con)
        con.execute("INSERT OR IGNORE INTO x_post(evento_id, esito, creato) "
                    "VALUES(?,?,?)", (evento_id, "di_casa", int(time.time())))
        con.commit()
        con.close()
    except Exception:
        pass


def _x_accoda(con, ev) -> bool:
    """Mette in coda una nota. False se c'era gia' (doppione, o nota di
    casa): la chiave primaria decide, non chi chiama."""
    cur = con.execute(
        "INSERT OR IGNORE INTO x_post(evento_id, creato_nota, evento, esito, "
        "creato) VALUES(?,?,?,?,?)",
        (ev["id"], int(ev.get("created_at") or 0),
         json.dumps(ev, ensure_ascii=False), "in_coda", int(time.time())))
    return cur.rowcount == 1


def _x_spesa_mese() -> float:
    """La stima dei dollari spesi dal primo del mese (UTC), per il
    journal e per il pannello. Fail-open a 0 (il pannello non deve
    cadere per una tabella che ancora non c'e')."""
    try:
        from datetime import datetime, timezone
        oggi = datetime.now(timezone.utc)
        primo = int(datetime(oggi.year, oggi.month, 1,
                             tzinfo=timezone.utc).timestamp())
        con = db()
        r = con.execute("SELECT COALESCE(SUM(costo_usd), 0) AS s FROM x_post "
                        "WHERE esito='pubblicato' AND pubblicato_il>=?",
                        (primo,)).fetchone()
        con.close()
        return round(float(r["s"] or 0), 3)
    except Exception:
        return 0.0


def _x_dollari(v: float) -> str:
    return f"{v:.3f} $".replace(".", ",")


# --- La lettura dei relay --------------------------------------------

def _x_note_da_relay(relay: str, hexkey: str, dal: int) -> list:
    """Le note kind 1 della chiave da UN relay, da `dal` in poi, fino
    all'EOSE. SINCRONA (websocket-client): in asyncio.to_thread. None =
    non ho potuto chiedere (relay muto, o collaudo verso un relay che
    non e' di casa)."""
    if not create_connection:
        return None
    if lettura_simulata(relay, f"delle note di {hexkey[:12]}… per X"):
        return None
    if fuori_dal_recinto(relay, "lettura delle note per X"):
        return None
    posta = _posta_per(relay)
    if posta is not None:
        letto = posta.leggi({"kinds": [1], "authors": [hexkey],
                             "since": int(dal), "limit": 100}, 8)
        return None if letto is None else letto[0]
    try:
        ws = create_connection(relay, timeout=5,
                               sslopt=SSLOPT_RELAY)
        ws.send(json.dumps(["REQ", "x", {"kinds": [1], "authors": [hexkey],
                                         "since": int(dal), "limit": 100}]))
        inizio, fuori = time.time(), []
        while time.time() - inizio < 8:
            msg = json.loads(ws.recv())
            if msg[0] == "EVENT" and msg[1] == "x" and isinstance(msg[2], dict):
                fuori.append(msg[2])
            elif msg[0] == "EOSE":
                break
        ws.close()
        return fuori
    except Exception:
        return None


async def _x_leggi_note(hexkey: str, dal: int) -> list:
    """Le note nuove da tutti i relay di casa nostra, senza doppioni,
    dalla piu' vecchia. Un relay muto non ferma gli altri."""
    async def uno(relay):
        try:
            return await asyncio.wait_for(
                asyncio.to_thread(_x_note_da_relay, relay, hexkey, dal), 15)
        except Exception:
            return None
    esiti = await asyncio.gather(*[uno(r) for r in RELAYS_VERIFICA])
    visti, note = set(), []
    for lista in esiti:
        for ev in lista or []:
            if isinstance(ev, dict) and ev.get("id") and ev["id"] not in visti:
                visti.add(ev["id"])
                note.append(ev)
    note.sort(key=lambda e: int(e.get("created_at") or 0))
    return note


# --- L'elaborazione di una riga --------------------------------------

async def _x_elabora(riga) -> str:
    """UNA nota verso X: prepara, (in prova: racconta e basta), carica i
    media, pubblica, timbra. Torna l'esito scritto. Un no di X si
    scrive qui, con la riga nel journal, e non esce come eccezione: il
    giro va avanti con la nota dopo."""
    evento_id = riga["evento_id"]
    try:
        ev = json.loads(riga["evento"] or "{}")
    except ValueError:
        ev = {}
    if not ev.get("content") and not evento_id.startswith("riepilogo-"):
        return _x_timbra(evento_id, "rifiutato", errore="nota senza contenuto")
    post = x_prepara(ev, con_link=bool(X_CON_LINK)
                     and not evento_id.startswith("riepilogo-"))
    corto = evento_id[:12]
    media = (f"{len(post['immagini'])} foto"
             + (", 1 video" if post["video"] else ""))
    if x_in_prova():
        print(f"🐦 [X prova] per la nota {corto}… avrei pubblicato "
              f"({media}, stima {_x_dollari(post['costo'])}): "
              f"«{post['testo'][:200]}»", flush=True)
        return _x_timbra(evento_id, "prova", testo=post["testo"])
    try:
        media_ids = []
        for url in post["video"] or post["immagini"]:
            tetto = X_VIDEO_MAX if post["video"] else X_GIF_MAX
            raw, mime = await _x_scarica(url, tetto)
            if not raw:
                print(f"🐦 X: media saltato per la nota {corto}… "
                      f"(non scaricabile o oltre il tetto)", flush=True)
                continue
            if mime.startswith("image/") and mime != "image/gif" \
                    and len(raw) > X_IMG_MAX:
                print(f"🐦 X: foto saltata per la nota {corto}… "
                      f"({len(raw) // 1024} KB > 5 MB)", flush=True)
                continue
            media_ids.append(await _x_carica_media(raw, mime))
        if not post["testo"] and not media_ids:
            return _x_timbra(evento_id, "rifiutato",
                             errore="niente da pubblicare")
        post_id = await _x_posta(post["testo"], media_ids)
    except XRifiuta as e:
        return _x_fallita(riga, e.status, str(e))
    except Exception as e:
        return _x_fallita(riga, 0, f"{type(e).__name__}: {str(e)[:100]}")
    esito = _x_timbra(evento_id, "pubblicato", post_id=post_id,
                      testo=post["testo"], costo=post["costo"])
    tariffa = (" (c'è un URL nel testo: tariffa piena)"
               if post["costo"] >= X_COSTO_LINK else "")
    print(f"🐦 X: pubblicato il post {post_id} per la nota {corto}… "
          f"({media}) — stima {_x_dollari(post['costo'])}{tariffa}, "
          f"totale del mese {_x_dollari(_x_spesa_mese())}", flush=True)
    return esito


def _x_timbra(evento_id: str, esito: str, post_id: str = "", testo: str = "",
              costo: float = 0.0, errore: str = "") -> str:
    con = db()
    con.execute("UPDATE x_post SET esito=?, post_x_id=?, testo_x=?, costo_usd=?, "
                "ultimo_errore=?, pubblicato_il=? WHERE evento_id=?",
                (esito, post_id, testo, costo, errore[:200],
                 int(time.time()) if esito == "pubblicato" else 0, evento_id))
    con.commit()
    con.close()
    return esito


def _x_fallita(riga, status: int, perche: str) -> str:
    """Un no di X: un 429 o un 5xx (o la rete) si riprova a distanza,
    finche' ci sono attese; il resto (401, 403, un duplicato…) si
    lascia subito. In tutti i casi una riga nel journal, e avanti."""
    corto = riga["evento_id"][:12]
    tentativi = int(riga["tentativi"] or 0) + 1
    riprovabile = status == 429 or status >= 500 or status == 0
    if riprovabile and tentativi <= len(X_RIPROVA_MIN):
        attesa = X_RIPROVA_MIN[tentativi - 1]
        con = db()
        con.execute("UPDATE x_post SET esito='riprova', tentativi=?, "
                    "riprova_il=?, ultimo_errore=? WHERE evento_id=?",
                    (tentativi, int(time.time()) + attesa * 60, perche[:200],
                     riga["evento_id"]))
        con.commit()
        con.close()
        print(f"🐦 X: {perche} per la nota {corto}…: riprovo fra {attesa} min "
              f"(tentativo {tentativi}/{len(X_RIPROVA_MIN)})", flush=True)
        return "riprova"
    con = db()
    con.execute("UPDATE x_post SET esito='rifiutato', tentativi=?, "
                "ultimo_errore=? WHERE evento_id=?",
                (tentativi, perche[:200], riga["evento_id"]))
    con.commit()
    con.close()
    print(f"🐦 X: la nota {corto}… resta su Nostr e basta ({perche}): "
          "si va avanti", flush=True)
    return "rifiutato"


# --- Il riepilogo del giorno -----------------------------------------

def _x_oggi_italiano():
    """La data di oggi e l'ora in Italia. Senza il fuso nel sistema
    (Windows senza tzdata) si cade su UTC+1, e si dice una volta."""
    from datetime import datetime, timezone, timedelta
    try:
        from zoneinfo import ZoneInfo
        fuso = ZoneInfo("Europe/Rome")
    except Exception:
        fuso = timezone(timedelta(hours=1))
        if not _X_STATO.get("fuso_detto"):
            _X_STATO["fuso_detto"] = True
            print("🐦 X: il fuso Europe/Rome non c'e' nel sistema: "
                  "il riepilogo usa UTC+1", flush=True)
    return datetime.now(fuso)


def _x_riepilogo_di_oggi(con, adesso) -> dict:
    """La nota «sintetica» del riepilogo: il conto degli annunci nati
    oggi (ora italiana) e le prime foto, nella forma di un evento
    cosi' che `x_prepara` la tratti come tutte le altre. None se oggi
    non e' nato niente: un post «0 annunci» non e' una notizia."""
    inizio = int(adesso.replace(hour=0, minute=0, second=0,
                                microsecond=0).timestamp())
    righe = con.execute(
        "SELECT foto FROM annunci WHERE stato='attivo' AND creato>=? "
        "ORDER BY creato DESC", (inizio,)).fetchall()
    if not righe:
        return None
    foto = []
    for r in righe:
        for url in _foto_url_nostr(r["foto"] or "")[:1]:
            if url not in foto:
                foto.append(url)
        if len(foto) >= 4:
            break
    conto = "1 annuncio" if len(righe) == 1 else f"{len(righe)} annunci"
    return {"id": "riepilogo-" + adesso.strftime("%Y-%m-%d"),
            "kind": 1, "created_at": int(time.time()),
            "content": X_RIEPILOGO_TESTO.format(conto=conto),
            "tags": [["imeta", f"url {u}", "m image/jpeg"] for u in foto]}


async def _x_giro_riepilogo(con) -> bool:
    """Una volta al giorno, dall'ora X_RIEPILOGO_ORA in poi: mette in
    coda il riepilogo se oggi non e' ancora uscito. Il timbro del giorno
    (`x_riepilogo_il`) si scrive PRIMA dell'invio, il patto delle
    campagne: un guasto puo' far perdere un riepilogo, mai raddoppiarlo."""
    adesso = _x_oggi_italiano()
    if adesso.hour < X_RIEPILOGO_ORA:
        return False
    giorno = adesso.strftime("%Y-%m-%d")
    if impostazione("x_riepilogo_il") == giorno:
        return False
    scrivi_impostazione("x_riepilogo_il", giorno)
    ev = _x_riepilogo_di_oggi(con, adesso)
    if not ev:
        print("🐦 X: oggi nessun annuncio nuovo, niente riepilogo", flush=True)
        return False
    _x_accoda(con, ev)
    con.commit()
    return True


# --- L'orologio ------------------------------------------------------

_X_STATO = {"giri": 0, "ultimo": 0.0, "fuso_detto": False}
_TASK_X = None


async def giro_x():
    """UN giro: le note nuove dai relay in coda, poi la coda verso X
    una riga alla volta. La lancetta `x_dal` avanza all'ultima nota
    vista (con un minuto di sovrapposizione: i relay non sono in orario
    fra loro, e un doppione lo ferma la chiave)."""
    con = db()
    _x_prepara_tabella(con)
    adesso = int(time.time())
    dal = int(impostazione("x_dal", "0") or 0)
    if not dal:
        scrivi_impostazione("x_dal", str(adesso))
        dal = adesso
        print("🐦 X: si parte da adesso — le note di prima non si "
              "ripubblicano", flush=True)
    nuove = 0
    if x_ripubblica_viva():
        nostra = x_npub_hex()
        if not nostra:
            print("⚠️ X: X_NPUB non e' una npub valida: nessuna lettura",
                  flush=True)
        else:
            ultimo = dal
            for ev in await _x_leggi_note(nostra, max(0, dal - 60)):
                ultimo = max(ultimo, int(ev.get("created_at") or 0))
                if not x_originale(ev, nostra):
                    continue
                if not _x_firma_valida(ev):
                    print(f"⛔ X: una nota «di Barattolo» da un relay non ha "
                          f"una firma valida: buttata", flush=True)
                    continue
                if int(ev.get("created_at") or 0) < dal:
                    continue
                if _x_accoda(con, ev):
                    nuove += 1
            con.commit()
            if ultimo > dal:
                scrivi_impostazione("x_dal", str(ultimo))
    if x_riepilogo_vivo():
        await _x_giro_riepilogo(con)
    righe = con.execute(
        "SELECT * FROM x_post WHERE esito='in_coda' OR (esito='riprova' AND "
        "riprova_il<=?) ORDER BY creato_nota, creato", (adesso,)).fetchall()
    con.close()
    fatti = 0
    for riga in righe:
        if fatti:
            await asyncio.sleep(X_PAUSA_S)
        await _x_elabora(dict(riga))
        fatti += 1
    _X_STATO["giri"] += 1
    _X_STATO["ultimo"] = time.time()
    return nuove, fatti


async def orologio_x():
    while True:
        try:
            await giro_x()
        except Exception as e:
            print(f"⚠️ X: giro saltato ({type(e).__name__}: {str(e)[:120]}): "
                  "il prossimo riparte da solo", flush=True)
        await asyncio.sleep(X_GIRO_S)


@app.on_event("startup")
async def avvia_x():
    """La riga all'avvio dice lo stato VIVO, come per le cassaforti:
    una leva accesa senza le chiavi vale spenta, e qui lo si legge."""
    global _TASK_X
    if (X_RIPUBBLICA or X_RIEPILOGO_GIORNO) and not x_configurato() \
            and not x_in_prova():
        print("⚠️ X_RIPUBBLICA / X_RIEPILOGO_GIORNO accese ma mancano le "
              "quattro chiavi (X_API_KEY, X_API_SECRET, X_ACCESS_TOKEN, "
              "X_ACCESS_SECRET) o sono il segnaposto: la cassa di "
              "risonanza vale SPENTA (o accendi X_PROVA per provare senza "
              "chiavi)", flush=True)
    if not (x_ripubblica_viva() or x_riepilogo_vivo()):
        print("🐦 X: cassa di risonanza spenta "
              "(X_RIPUBBLICA / X_RIEPILOGO_GIORNO)", flush=True)
        return
    print("🐦 X: cassa di risonanza ACCESA"
          + (" in PROVA (X non viene chiamato)" if x_in_prova() else "")
          + (" — note" if x_ripubblica_viva() else "")
          + (" — riepilogo del giorno" if x_riepilogo_vivo() else "")
          + (" — con link njump" if X_CON_LINK else " — senza link")
          + f", npub {str(X_NPUB)[:16]}…", flush=True)
    _TASK_X = asyncio.create_task(orologio_x())


def _x_leve() -> list:
    """Le voci del pannello «Stato delle leve»: i fatti, mai le chiavi."""
    return [
        _leva("Cassa di risonanza: le note su X", "X_RIPUBBLICA",
              x_ripubblica_viva(),
              allarme=bool(X_RIPUBBLICA) and not x_ripubblica_viva(),
              acceso="le note kind 1 originali della npub ufficiale "
                     "escono su X (un post alla volta, mai le promo del "
                     "server, mai i prodotti)",
              spento="nessuna nota esce su X; se la leva è True nel "
                     "config, mancano le quattro chiavi"),
        _leva("Modalità prova", "X_PROVA", x_in_prova(),
              acceso="il journal dice cosa AVREBBE pubblicato, X non "
                     "viene chiamato e niente si paga"),
        _leva("Il link njump in coda", "X_CON_LINK", bool(X_CON_LINK),
              acceso="ogni post porta il link alla nota: X lo fa pagare "
                     "0,200 $ invece di 0,015 $",
              spento="i post escono senza link (0,015 $); restano i link "
                     "che la persona ha scritto nella nota"),
        _leva("Riepilogo del giorno (prodotti)", "X_RIEPILOGO_GIORNO",
              x_riepilogo_vivo(),
              acceso="alle 18 un post «Nuovi arrivi di oggi: N annunci» "
                     "con fino a 4 foto, senza link",
              spento="i prodotti non escono su X in nessuna forma"),
        _leva("Le quattro chiavi di X", "X_API_KEY…", x_configurato(),
              spento="senza, le due leve qui sopra valgono spente"),
        _leva("Npub ufficiale ascoltata", "X_NPUB",
              (str(X_NPUB)[:20] + "…") if x_npub_hex() else "non valida",
              allarme=not x_npub_hex()),
        _leva("Spesa stimata del mese ($)", "db: x_post", _x_spesa_mese()),
    ]


# ---------- IL CAMPANELLO DEI NUOVI ISCRITTI (solo moderatori) -------
# In rodaggio ogni persona che entra e' una notizia. La ricevono i
# moderatori nel loro Telegram e SOLO loro: il nome di chi si iscrive
# non si annuncia in piazza, e anche i traguardi (100 pionieri!) sono
# roba da annunciare a mano, quando e come si vuole.
# Niente coda in memoria come i post: qui il filo dell'acqua e' la
# colonna `registrato`, e a ogni giro d'orologio si guarda chi e'
# arrivato da quando abbiamo guardato l'ultima volta. Cosi' il
# campanello copre da solo TUTTE le porte d'ingresso — Mini App, login
# web, nativo Nostr, /start del bot — comprese quelle di domani, senza
# un gancio dentro l'autenticazione. Un riavvio salta un battito e
# riparte da adesso: mai una raffica di recuperi all'avvio.
# La finestra di raggruppamento e' il giro dell'orologio (10 minuti).

_ultimo_giro_iscritti = 0.0             # filo dell'acqua (0 = da armare)
_iscritti_annunciati: list[float] = []  # timestamp dei messaggi singoli
TRAGUARDI_PIONIERI = (50, 100, 250, 500, 1000)


def _riga_pioniere(u: dict) -> str:
    """Chi e' arrivato, in una riga: il nome, l'eventuale @username e
    la porta da cui e' entrato (i tg_id negativi sono i nativi Nostr).
    Il nome lo scrive l'utente: passa da html.escape, che le notifiche
    viaggiano in parse_mode HTML."""
    nome = html.escape(u["nome"] or "senza nome")
    if u["tg_id"] < 0:
        return f"{nome} — da Nostr"
    if u["username"]:
        return f"{nome} (@{html.escape(u['username'])}) — da Telegram"
    return f"{nome} — da Telegram"


async def avvisa_nuovi_iscritti():
    """Un giro d'orologio: pochi arrivi = un messaggio ciascuno, con
    nome e provenienza; una raffica (il link finito in un gruppo) = UN
    messaggio solo col conto, che non nomina nessuno — la valvola del
    drenatore promo, stessa soglia. Fail-open: la chiama l'orologio, e
    un campanello muto non deve mai fermare gli sblocchi."""
    global _ultimo_giro_iscritti
    if not AVVISI_ISCRITTI:
        return
    adesso = time.time()
    if not _ultimo_giro_iscritti:
        _ultimo_giro_iscritti = adesso     # primo giro: si arma e basta
        return
    con = db()
    nuovi = [dict(r) for r in con.execute(
        "SELECT tg_id, nome, username FROM utenti "
        "WHERE registrato >= ? AND registrato < ? "
        "ORDER BY registrato, tg_id",
        (int(_ultimo_giro_iscritti), int(adesso)))]
    # Il conto lo rifacciamo qui e non con conta_pionieri(): la sua
    # cache di un minuto potrebbe non vedere ancora chi stiamo
    # annunciando, e «siamo in 24» mentre presenti il 25° e' una bugia.
    totale = con.execute("SELECT COUNT(*) AS n FROM utenti").fetchone()["n"]
    con.close()
    _ultimo_giro_iscritti = adesso
    if not nuovi:
        return
    # I traguardi scattano solo nel giro in cui il numero li supera: si
    # deducono dai dati, nessuno stato da tenere (e se una fusione
    # cancella una riga proprio in quel giro, il traguardo salta — pace,
    # il numero vero resta quello del contatore in vetrina).
    prima = totale - len(nuovi)
    for soglia in TRAGUARDI_PIONIERI:
        if prima < soglia <= totale:
            await notifica_admin(f"🎉 <b>Traguardo: {soglia} pionieri!</b>\n"
                                 f"Il barattolo si riempie. 🫙",
                                 argomento="riepiloghi")
    # Il tetto orario vale sui messaggi SINGOLI; oltre resta
    # l'aggregato, che passa sempre (al massimo uno per giro, e solo se
    # qualcuno e' davvero arrivato).
    _iscritti_annunciati[:] = [t for t in _iscritti_annunciati
                               if adesso - t < 3600]
    if (len(nuovi) <= SOGLIA_AGGREGA
            and len(_iscritti_annunciati) + len(nuovi) <= AVVISI_ISCRITTI_MAX_ORA):
        for u in nuovi:
            await notifica_admin(f"👥 <b>Nuovo pioniere:</b> {_riga_pioniere(u)}\n"
                                 f"Siamo in {totale}.", argomento="riepiloghi")
            _iscritti_annunciati.append(time.time())
    else:
        conto = ("1 nuovo pioniere" if len(nuovi) == 1
                 else f"{len(nuovi)} nuovi pionieri")
        await notifica_admin(f"👥 <b>{conto}</b> negli ultimi minuti.\n"
                             f"Siamo in {totale}.", argomento="riepiloghi")


# --- Il motore degli avvisi di ricerca -------------------------------
# Gemello della coda promo qui sopra: chi pubblica accoda e basta, il
# drenatore dorme la stessa finestra e poi confronta gli annunci nuovi
# coi criteri salvati. Anti-molestia a tre strati: dedup persistente
# (avvisi_notificati: lo stesso annuncio non suona mai due volte per lo
# stesso utente, nemmeno dopo un riavvio), aggregazione (2+ match in
# finestra = UN solo messaggio: l'import da 500 righe non mitraglia
# nessuno) e tetto giornaliero di messaggi per utente (in memoria: un
# riavvio lo azzera, al peggio qualche messaggio in piu' una tantum —
# le raffiche vere le ferma l'aggregazione, che e' strutturale).
# A differenza dei promo, gli annunci IMPORTATI restano dentro: per
# chi cerca, un annuncio e' un annuncio.

CODA_MATCH: list[int] = []
_drenatore_match_avviato = False
TETTO_AVVISI_GIORNO = 3 if MODALITA_COLLAUDO else 5   # messaggi/giorno
AVVISI_QUOTA: dict[int, list] = {}    # tg_id -> [giorno, messaggi]


def accoda_match(annuncio_id: int):
    """Mette l'annuncio in coda per il matching degli avvisi e, se
    dorme, sveglia il drenatore. Come accoda_promo: leggera e
    sincrona, DOPO il commit, mai dentro una transazione."""
    global _drenatore_match_avviato
    CODA_MATCH.append(annuncio_id)
    if not _drenatore_match_avviato:
        _drenatore_match_avviato = True
        asyncio.create_task(_drena_match())


def _match_avviso(avviso, a: dict, token_annuncio: list,
                  cambio: float) -> bool:
    """La verifica fine, dopo il prefiltro SQL (categoria e prezzo in
    sats sono gia' passati): parole chiave, prezzo in EUR, distanza.
    Ogni criterio non impostato lascia passare."""
    # parole chiave: TUTTE (e' un AND), a prefisso di parola — 'bici'
    # prende 'bicicletta', ma 'ram' non affoga in 'ceramica'
    for parola in avviso["parole"].split():
        if not any(t.startswith(parola) for t in token_annuncio):
            return False
    # prezzo massimo in EUR: il listino EUR si confronta com'e', il
    # listino sats si converte col cambio di adesso; cambio mai
    # arrivato = criterio non valutabile = niente avviso (meglio un
    # match perso che uno sbagliato)
    if avviso["prezzo_max_eur"]:
        if a.get("valuta") == "eur" and a.get("prezzo_eur"):
            eur = a["prezzo_eur"]
        elif cambio > 0:
            eur = a["prezzo_sats"] / 100_000_000 * cambio
        else:
            return False
        if eur > avviso["prezzo_max_eur"]:
            return False
    # raggio: un annuncio senza coordinate (zona non riconosciuta)
    # non matcha mai i criteri geografici — imperfezione dichiarata
    if avviso["raggio_km"]:
        if not (a.get("lat") or a.get("lon")):
            return False
        if distanza_km(avviso["lat"], avviso["lon"],
                       a["lat"], a["lon"]) > avviso["raggio_km"]:
            return False
    return True


async def _drena_match():
    """Il drenatore del matching: dorme la finestra, rilegge gli
    annunci accumulati dal database (chi e' sparito nel frattempo non
    suona) e confronta ciascuno coi criteri salvati — prefiltro SQL
    sulla tabella minuscola degli avvisi, verifica fine in Python.
    Fail-open totale: un errore qui non tocca mai la pubblicazione."""
    global _drenatore_match_avviato
    await asyncio.sleep(ATTESA_RAGGRUPPO)
    ids = list(dict.fromkeys(CODA_MATCH))
    CODA_MATCH.clear()
    _drenatore_match_avviato = False
    try:
        cambio = await cambio_btc_eur()
        per_utente: dict[int, list] = {}
        in_vetrina: list = []   # gli stessi annunci, per gli avvisi del mercatino
        con = db()
        adesso_f = int(time.time())
        for i in ids:
            # come nel drenatore promo: un avviso di ricerca che suona
            # per un negozio chiuso manderebbe qualcuno davanti a una
            # vetrina da cui non si compra
            a = con.execute("SELECT a.*, u.ferie_fino FROM annunci a "
                            "JOIN utenti u ON u.tg_id=a.venditore_id "
                            "WHERE a.id=?", (i,)).fetchone()
            if not a or a["stato"] != "attivo" \
                    or in_ferie(a["ferie_fino"], adesso_f):
                continue
            a = dict(a)
            in_vetrina.append(a)
            token = normalizza(f"{a['titolo']} {a['descrizione']}").split()
            candidati = con.execute(
                "SELECT * FROM avvisi_ricerca WHERE attivo=1 "
                "AND tg_id != ? "
                "AND (categorie='' OR categorie LIKE '%|' || ? || '|%') "
                "AND (prezzo_max_sats=0 OR prezzo_max_sats >= ?)",
                (a["venditore_id"], a["categoria"],
                 a["prezzo_sats"])).fetchall()
            gia_suoi = set()
            for avviso in candidati:
                if avviso["tg_id"] in gia_suoi:   # un utente, una voce
                    continue
                if _match_avviso(avviso, a, token, cambio):
                    gia_suoi.add(avviso["tg_id"])
                    per_utente.setdefault(avviso["tg_id"], []).append(a)
        # dedup persistente: conta solo chi entra DAVVERO adesso
        adesso = int(time.time())
        da_avvisare: dict[int, list] = {}
        for tg_id, annunci in per_utente.items():
            nuovi = []
            for a in annunci:
                cur = con.execute(
                    "INSERT OR IGNORE INTO avvisi_notificati"
                    "(tg_id, annuncio_id, creato) VALUES(?,?,?)",
                    (tg_id, a["id"], adesso))
                if cur.rowcount:
                    nuovi.append(a)
            if nuovi:
                da_avvisare[tg_id] = nuovi
        # GLI AVVISI DEL MERCATINO (9 ott 2026): gli stessi annunci, in
        # coda per chi segue il venditore o vuole tutti i nuovi — DOPO il
        # dedup qui sopra, cosi' chi riceve «fa per te» non li riceve due
        # volte (vedi `_accoda_avvisi_mercatino`)
        accodati = 0
        for a in in_vetrina:
            accodati += _accoda_avvisi_mercatino(con, a, cambio, adesso)
        con.commit()
        con.close()
        for tg_id, annunci in da_avvisare.items():
            await _notifica_match(tg_id, annunci, cambio)
            await asyncio.sleep(0.2)   # mai raffiche sull'API Telegram
        if accodati:
            await _giro_avvisi_mercatino()   # il primo messaggio parte subito
    except Exception as e:
        print(f"⚠️ Matching avvisi saltato: {e}")


async def _notifica_match(tg_id: int, annunci: list, cambio: float):
    """Il messaggio all'utente: uno solo per finestra — ricco se il
    match e' singolo, il conto e basta se sono di piu'. Il tetto
    giornaliero chiude con onesta', mai in silenzio muto."""
    oggi = time.strftime("%Y-%m-%d")
    voce = AVVISI_QUOTA.get(tg_id)
    if not voce or voce[0] != oggi:
        voce = [oggi, 0]
        AVVISI_QUOTA[tg_id] = voce
    if voce[1] >= TETTO_AVVISI_GIORNO:
        return
    if len(annunci) == 1:
        a = annunci[0]
        testo = (f"🔎 Un annuncio fa per te!\n"
                 f"<b>{html.escape(a['titolo'])}</b> — "
                 f"{_prezzo_promo(a, cambio)}")
        if a.get("zona"):
            testo += f"\n📍 {html.escape(a['zona'])}"
        testo += f"\n{link_telegram('annuncio', a['id'])}"
    else:
        testo = (f"📬 {len(annunci)} nuovi annunci corrispondono ai "
                 f"tuoi avvisi di ricerca → {URL_PUBBLICO}")
    voce[1] += 1
    if voce[1] >= TETTO_AVVISI_GIORNO:
        testo += ("\n\n(per oggi mi fermo qui 🤫: il resto lo "
                  "trovi nel mercatino)")
    await notifica(tg_id, testo)


# ═══ GLI AVVISI DEL MERCATINO: I NUOVI ANNUNCI E I VENDITORI SEGUITI ═══
# (9 ott 2026, richiesta di Andrea.) Chi lo chiede sa quando nel mercatino
# compare un annuncio nuovo, senza tenere l'app aperta, in DUE modi:
#  · «🆕 Avvisami dei nuovi annunci»: TUTTI i nuovi, con un filtro
#    facoltativo di categorie e di prezzo massimo — raggruppati, al piu'
#    un messaggio ogni MERCATINO_AVVISI_NUOVI_MINUTI per persona, con
#    quanti sono e i primi titoli, e il tocco che apre Esplora coi suoi
#    filtri;
#  · «🔔 Segui» sulla pagina di un venditore: quando LUI pubblica, un
#    messaggio — raggruppato se ne pubblica piu' d'uno in poco tempo, al
#    piu' uno ogni MERCATINO_AVVISI_SEGUI_MINUTI per venditore.
# LA FONTE E' IL DRENATORE DEGLI AVVISI DI RICERCA (`_drena_match`): chi
# pubblica accoda e basta, e l'annuncio arriva qui DOPO il suo dedup —
# cosi' chi ha gia' ricevuto «Un annuncio fa per te!» non lo riceve una
# seconda volta da qui, e viceversa. Gli annunci in moderazione passano
# di li' solo quando un moderatore li approva (e' la loro prima uscita),
# le aste restano fuori dai canali come sempre, e un annuncio nascosto,
# tolto o venduto prima del suo minuto non si annuncia.
# LE REGOLE, e ognuna ha il suo posto nel codice:
# 1) SPENTO DI SERIE, per persona (`utenti.avvisi_mercatino`; seguire e'
#    un gesto, quindi e' acceso per costruzione), sotto la leva globale.
# 2) RAGGRUPPATI: ogni annuncio che qualcuno vuole va in CODA
#    (`mercatino_avvisi_coda`), e il messaggio parte quando dall'ultimo
#    sono passati i minuti della finestra. Il primo parte subito.
# 3) MAI PER I PROPRI ANNUNCI, MAI DUE VOLTE LO STESSO: la chiave della
#    coda e' persona+annuncio, e sopra c'e' `avvisi_notificati`.
# 4) LA LEVA GLOBALE MERCATINO_AVVISI_NUOVI, nel pannello delle leve.
# IL CANALE LO SCEGLIE `notifica()`: bot Telegram a chi entra da
# Telegram, DM Nostr a chi entra con Nostr, o la scelta del cassetto.
try:
    from config import MERCATINO_AVVISI_NUOVI
    if not isinstance(MERCATINO_AVVISI_NUOVI, bool):
        print("[mercatino] MERCATINO_AVVISI_NUOVI non e' True/False: gli avvisi "
              "del mercatino restano ACCESI")
        MERCATINO_AVVISI_NUOVI = True
except ImportError:
    MERCATINO_AVVISI_NUOVI = True
# ...e le due finestre del raggruppamento, in minuti: 60 per «tutti i
# nuovi annunci», 15 per ogni venditore seguito. Interi da 1 in su.
try:
    from config import MERCATINO_AVVISI_NUOVI_MINUTI
    MERCATINO_AVVISI_NUOVI_MINUTI = int(MERCATINO_AVVISI_NUOVI_MINUTI)
    if MERCATINO_AVVISI_NUOVI_MINUTI < 1:
        raise ValueError("una finestra sotto il minuto non raggruppa niente")
except ImportError:
    MERCATINO_AVVISI_NUOVI_MINUTI = 60
except (TypeError, ValueError):
    MERCATINO_AVVISI_NUOVI_MINUTI = 60
    print("[mercatino] MERCATINO_AVVISI_NUOVI_MINUTI non e' un numero intero: vale "
          "la finestra di serie, 60 minuti")
try:
    from config import MERCATINO_AVVISI_SEGUI_MINUTI
    MERCATINO_AVVISI_SEGUI_MINUTI = int(MERCATINO_AVVISI_SEGUI_MINUTI)
    if MERCATINO_AVVISI_SEGUI_MINUTI < 1:
        raise ValueError("una finestra sotto il minuto non raggruppa niente")
except ImportError:
    MERCATINO_AVVISI_SEGUI_MINUTI = 15
except (TypeError, ValueError):
    MERCATINO_AVVISI_SEGUI_MINUTI = 15
    print("[mercatino] MERCATINO_AVVISI_SEGUI_MINUTI non e' un numero intero: vale "
          "la finestra di serie, 15 minuti")
TETTO_VENDITORI_SEGUITI = 100   # per persona: un tetto di buon senso, non una leva
TITOLI_AVVISO_MERCATINO = 3     # i primi titoli nel messaggio raggruppato


def _leve_avvisi_mercatino() -> dict:
    """La busta delle leve per il client: la riga del cassetto compare
    solo se gli avvisi esistono, e dice «al massimo uno ogni N minuti»
    coi numeri veri."""
    return {"attivi": bool(MERCATINO_AVVISI_NUOVI),
            "minuti": int(MERCATINO_AVVISI_NUOVI_MINUTI),
            "seguiMinuti": int(MERCATINO_AVVISI_SEGUI_MINUTI)}


def _pref_avvisi_mercatino(riga) -> dict:
    """PURA: le quattro colonne di `utenti` come le legge il client —
    {attivo, categorie, prezzo_max, valuta}. Una riga assente, o di ieri
    senza le colonne, vale SPENTO senza filtri: lo spento di serie e' una
    regola, non un default del database. Le categorie escono nell'ordine
    del catalogo e solo se esistono; un prezzo storto vale «nessuno»."""
    if not riga:
        return {"attivo": False, "categorie": [], "prezzo_max": 0, "valuta": "sats"}
    try:
        attivo = bool(int(_campo_riga(riga, "avvisi_mercatino", 0) or 0))
    except (TypeError, ValueError):
        attivo = False
    cat_txt = str(_campo_riga(riga, "avvisi_mercatino_categorie", "") or "")
    categorie = [c for c in CATEGORIE if f"|{c}|" in cat_txt]
    valuta = str(_campo_riga(riga, "avvisi_mercatino_valuta", "") or "")
    if valuta not in ("sats", "eur"):
        valuta = "sats"
    try:
        prezzo = float(_campo_riga(riga, "avvisi_mercatino_prezzo", 0) or 0)
    except (TypeError, ValueError):
        prezzo = 0.0
    if prezzo < 0 or prezzo != prezzo or prezzo == float("inf"):
        prezzo = 0.0
    prezzo = int(prezzo) if valuta == "sats" else round(prezzo, 2)
    return {"attivo": attivo, "categorie": categorie, "prezzo_max": prezzo, "valuta": valuta}


def _passa_avviso_mercatino(pref: dict, a: dict, cambio: float) -> bool:
    """PURA: queste preferenze vogliono quest'annuncio? Acceso; la
    categoria fra le scelte (nessuna scelta = tutte); e sotto il prezzo
    massimo, se c'e' — in sats contro il listino in sats, in euro contro
    il listino in euro com'e' o col cambio di adesso. Cambio mai arrivato
    = criterio non valutabile = niente avviso: meglio un avviso perso che
    uno sbagliato, il patto di `_match_avviso`."""
    if not pref.get("attivo"):
        return False
    cats = pref.get("categorie") or []
    if cats and a.get("categoria") not in cats:
        return False
    tetto = pref.get("prezzo_max") or 0
    if not tetto:
        return True
    if pref.get("valuta") == "eur":
        if a.get("valuta") == "eur" and a.get("prezzo_eur"):
            eur = float(a["prezzo_eur"])
        elif cambio and cambio > 0:
            eur = float(a.get("prezzo_sats") or 0) / 100_000_000 * cambio
        else:
            return False
        return eur <= float(tetto)
    return int(a.get("prezzo_sats") or 0) <= int(tetto)


def _titoli_avviso_mercatino(righe: list) -> str:
    """PURA: i primi titoli, uno per riga col puntino, e «…e altri N»."""
    testo = "".join(f"\n• {html.escape(str(r.get('titolo') or '')[:60])}"
                    for r in righe[:TITOLI_AVVISO_MERCATINO])
    resto = len(righe) - TITOLI_AVVISO_MERCATINO
    if resto > 0:
        testo += "\n…e " + ("un altro" if resto == 1 else f"altri {resto}")
    return testo


def _link_esplora_avvisi(pref: dict) -> str:
    """PURA: il tocco che apre Esplora coi filtri della persona — il
    reparto se la categoria e' una sola (/categoria/{slug}, la pagina
    vera del reparto), la vetrina intera altrimenti, e il prezzo massimo
    in coda (?max=…&valuta=…), che la pagina legge all'arrivo."""
    cats = pref.get("categorie") or []
    url = (f"{URL_PUBBLICO}/categoria/{slug_categoria(cats[0])}" if len(cats) == 1
           else f"{URL_PUBBLICO}/")
    tetto = pref.get("prezzo_max") or 0
    if tetto:
        url += f"?max={tetto}&valuta={'eur' if pref.get('valuta') == 'eur' else 'sats'}"
    return url


def _frase_filtro_avvisi_mercatino(pref: dict) -> str:
    """PURA: «Elettronica · Motori, fino a 50,00 €» — il filtro della
    persona in una riga, '' senza filtri."""
    pezzi = []
    cats = pref.get("categorie") or []
    if cats:
        pezzi.append(" · ".join(html.escape(c) for c in cats))
    tetto = pref.get("prezzo_max") or 0
    if tetto:
        pezzi.append("fino a " + (f"{_fmt_eur(tetto)} €" if pref.get("valuta") == "eur"
                                  else f"{_fmt_sats(int(tetto))} sats"))
    return ", ".join(pezzi)


def _testo_avviso_mercatino_tutti(righe: list, pref: dict) -> str:
    """PURA: il messaggio raggruppato dei nuovi annunci — quanti, il
    filtro della persona se ce l'ha, i primi titoli e il tocco che apre
    Esplora coi suoi filtri. Nessun nome di chi vende: la vetrina e' la
    pagina dove si guarda."""
    n = len(righe)
    testo = f"🆕 <b>{n} {'nuovo annuncio' if n == 1 else 'nuovi annunci'} nel mercatino</b>"
    filtro = _frase_filtro_avvisi_mercatino(pref)
    if filtro:
        testo += f"\nIl tuo filtro: {filtro}"
    testo += _titoli_avviso_mercatino(righe)
    # (10 ott 2026) dentro Telegram, a leva accesa, il tocco apre la Mini App
    # su Esplora con gli stessi filtri (`_link_esplora_telegram`)
    testo += (f"\n\n<a href=\"{_link_esplora_telegram(_link_esplora_avvisi(pref))}\">"
              "🫙 Apri Esplora</a>")
    return testo


def _testo_avviso_mercatino_segui(righe: list, nome: str, negozio: str) -> str:
    """PURA: il messaggio di un venditore seguito — chi, quanti annunci
    nuovi, i primi titoli; con uno solo il tocco apre l'annuncio, con
    piu' d'uno il suo negozio."""
    n = len(righe)
    chi = html.escape(str(nome or "")) or "Un venditore che segui"
    testo = f"🔔 <b>{chi}</b> ha pubblicato {n} {'nuovo annuncio' if n == 1 else 'nuovi annunci'}"
    testo += _titoli_avviso_mercatino(righe)
    cod = re.sub(r"[^A-Za-z0-9_]", "", str(negozio or ""))
    if n == 1 and righe[0].get("annuncio_id"):
        testo += f"\n\n<a href=\"{URL_PUBBLICO}/annuncio/{int(righe[0]['annuncio_id'])}\">🫙 Apri l'annuncio</a>"
    elif cod:
        testo += f"\n\n<a href=\"{URL_PUBBLICO}/negozio/{cod}\">🫙 Apri il suo negozio</a>"
    else:
        testo += f"\n\n<a href=\"{_link_esplora_telegram(URL_PUBBLICO + '/')}\">🫙 Apri Esplora</a>"
    return testo


def _venditore_da_chi(con, chi: str):
    """Il venditore come lo trova /api/negozio — lo slug sulla stringa
    intera, poi username e codice sul pezzo prima del trattino
    (`_chi_da_percorso`) — ma col solo profilo che serve a «Segui»:
    tg_id, nome, codice. None se non c'e'."""
    campi = "SELECT tg_id, nome, negozio FROM utenti "
    v = con.execute(campi + "WHERE negozio_slug=? COLLATE NOCASE AND negozio_slug!='' "
                    "LIMIT 1", (chi,)).fetchone()
    if not v:
        corto = _chi_da_percorso(chi)
        # (14 nov 2026, audit) il codice prima dello username, come /negozio
        v = con.execute(campi + "WHERE negozio=? LIMIT 1", (corto,)).fetchone()
        if not v:
            v = con.execute(campi + "WHERE username=? COLLATE NOCASE AND username!='' "
                            "LIMIT 1", (corto,)).fetchone()
    return v


def _seguiti_di(tg_id) -> list:
    """I venditori che questa persona segue, come li legge il cassetto:
    codice del negozio, nome e foto — mai il tg_id, mai niente d'altro.
    Dal piu' recente. Fail-open: un elenco che non si legge e' vuoto,
    non un /api/me rotto."""
    try:
        con = db()
        righe = con.execute(
            "SELECT u.nome, u.negozio, u.username, "
            "(CASE WHEN u.avatar_scelta='nessuna' THEN '' ELSE u.avatar END) AS avatar, "
            "s.creato FROM venditori_seguiti s JOIN utenti u ON u.tg_id=s.venditore_id "
            "WHERE s.tg_id=? ORDER BY s.creato DESC, u.nome", (tg_id,)).fetchall()
        con.close()
    except Exception as e:
        print(f"⚠️ Venditori seguiti di {tg_id} illeggibili ({e}): elenco vuoto")
        return []
    return [{"nome": r["nome"] or "", "negozio": r["negozio"] or "",
             "username": r["username"] or "", "avatar": r["avatar"] or "",
             "creato": r["creato"] or 0} for r in righe]


def _accoda_avvisi_mercatino(con, a: dict, cambio: float, adesso: int) -> int:
    """Per un annuncio appena in vetrina, le persone che lo vogliono: in
    CODA, una riga per (persona, annuncio). Qui stanno le regole 1 e 3 —
    la leva globale, mai per chi l'ha pubblicato, chi lo SEGUE
    ('segui'), chi ha acceso «tutti i nuovi annunci» coi filtri che lo
    passano ('tutti'; chi segue il venditore E ha l'interruttore acceso
    lo riceve UNA volta, dal venditore). L'anti-doppione e' doppio: la
    chiave della coda, e `avvisi_notificati` — lo stesso «mai due volte»
    degli avvisi di ricerca, scritto QUI al momento della coda, cosi' un
    annuncio gia' annunciato da «Avvisami se arriva» non torna da qui e
    viceversa. Torna quante righe nuove ha scritto. NON committa: lo fa
    chi chiama, insieme al resto."""
    if not MERCATINO_AVVISI_NUOVI or not a or a.get("stato") != "attivo":
        return 0
    venditore = int(a.get("venditore_id") or 0)
    voluti = {}   # tg_id -> motivo
    for r in con.execute("SELECT tg_id FROM venditori_seguiti WHERE venditore_id=?",
                         (venditore,)).fetchall():
        voluti[int(r["tg_id"])] = "segui"
    for p in con.execute(
            "SELECT tg_id, avvisi_mercatino, avvisi_mercatino_categorie, "
            "avvisi_mercatino_prezzo, avvisi_mercatino_valuta FROM utenti "
            "WHERE avvisi_mercatino=1").fetchall():
        tg = int(p["tg_id"])
        if tg in voluti:
            continue
        if _passa_avviso_mercatino(_pref_avvisi_mercatino(p), a, cambio):
            voluti[tg] = "tutti"
    scritte = 0
    for tg, motivo in voluti.items():
        if tg == venditore:
            continue                      # mai per i suoi
        gia = con.execute(
            "INSERT OR IGNORE INTO avvisi_notificati(tg_id, annuncio_id, creato) "
            "VALUES(?,?,?)", (tg, a["id"], adesso))
        if not gia.rowcount:
            continue                      # gia' annunciato: da qui o da «Avvisami se arriva»
        cur = con.execute(
            "INSERT OR IGNORE INTO mercatino_avvisi_coda(tg_id, annuncio_id, motivo, "
            "venditore_id, titolo, accodato, mandato) VALUES(?,?,?,?,?,?,0)",
            (tg, a["id"], motivo, venditore, str(a.get("titolo") or "")[:80], adesso))
        scritte += cur.rowcount
    return scritte


def _scarica_avvisi_mercatino(con, adesso: int) -> list:
    """La regola 2: per ogni persona con righe in coda, UN messaggio per
    i 'tutti' quando dall'ultimo sono passati MERCATINO_AVVISI_NUOVI_MINUTI
    (o non ce n'e' mai stato uno), e UNO per venditore seguito quando
    sono passati MERCATINO_AVVISI_SEGUI_MINUTI — con le righe i cui
    annunci sono ANCORA in vetrina (attivi, e il negozio non in ferie);
    le righe si timbrano PRIMA dell'invio col patto di sempre. Si
    consumano senza messaggio le righe di chi ha spento l'interruttore,
    di chi ha smesso di seguire, e degli annunci spariti (nascosti dalle
    ferie, tolti, venduti, rimessi in moderazione). Torna [(tg_id,
    testo, riga di journal)]. Committa."""
    con.execute("UPDATE mercatino_avvisi_coda SET mandato=1 WHERE mandato=0 AND motivo='tutti' "
                "AND tg_id NOT IN (SELECT tg_id FROM utenti WHERE avvisi_mercatino=1)")
    con.execute("UPDATE mercatino_avvisi_coda SET mandato=1 WHERE mandato=0 AND motivo='segui' "
                "AND NOT EXISTS (SELECT 1 FROM venditori_seguiti s "
                "WHERE s.tg_id=mercatino_avvisi_coda.tg_id "
                "AND s.venditore_id=mercatino_avvisi_coda.venditore_id)")
    finestre = {"tutti": int(MERCATINO_AVVISI_NUOVI_MINUTI) * 60,
                "segui": int(MERCATINO_AVVISI_SEGUI_MINUTI) * 60}
    gruppi = con.execute(
        "SELECT tg_id, motivo, "
        "(CASE WHEN motivo='segui' THEN venditore_id ELSE 0 END) AS chi, "
        "MAX(CASE WHEN mandato > 1 THEN mandato ELSE 0 END) AS ultimo, "
        "SUM(CASE WHEN mandato = 0 THEN 1 ELSE 0 END) AS in_coda "
        "FROM mercatino_avvisi_coda GROUP BY tg_id, motivo, chi").fetchall()
    fuori = []
    for g in gruppi:
        if not g["in_coda"]:
            continue
        tg, motivo, chi = int(g["tg_id"]), str(g["motivo"] or "tutti"), int(g["chi"] or 0)
        if adesso - int(g["ultimo"] or 0) < finestre.get(motivo, finestre["tutti"]):
            continue
        righe = con.execute(
            "SELECT c.annuncio_id, c.titolo, a.stato, a.titolo AS titolo_vivo, u.ferie_fino "
            "FROM mercatino_avvisi_coda c LEFT JOIN annunci a ON a.id=c.annuncio_id "
            "LEFT JOIN utenti u ON u.tg_id=a.venditore_id "
            "WHERE c.tg_id=? AND c.mandato=0 AND c.motivo=? AND (?=0 OR c.venditore_id=?) "
            "ORDER BY c.accodato, c.annuncio_id", (tg, motivo, chi, chi)).fetchall()
        vive = [{"annuncio_id": r["annuncio_id"], "titolo": r["titolo_vivo"] or r["titolo"]}
                for r in righe
                if r["stato"] == "attivo" and not in_ferie(r["ferie_fino"] or 0, adesso)]
        if not vive:
            con.execute("UPDATE mercatino_avvisi_coda SET mandato=1 WHERE tg_id=? AND mandato=0 "
                        "AND motivo=? AND (?=0 OR venditore_id=?)", (tg, motivo, chi, chi))
            continue
        con.execute("UPDATE mercatino_avvisi_coda SET mandato=? WHERE tg_id=? AND mandato=0 "
                    "AND motivo=? AND (?=0 OR venditore_id=?)", (adesso, tg, motivo, chi, chi))
        if motivo == "segui":
            v = con.execute("SELECT nome, negozio FROM utenti WHERE tg_id=?", (chi,)).fetchone()
            testo = _testo_avviso_mercatino_segui(vive, v["nome"] if v else "",
                                                  v["negozio"] if v else "")
            riga = f"🔔 Venditore seguito: {len(vive)} annunci di {chi} a {tg}"
        else:
            p = con.execute("SELECT avvisi_mercatino, avvisi_mercatino_categorie, "
                            "avvisi_mercatino_prezzo, avvisi_mercatino_valuta FROM utenti "
                            "WHERE tg_id=?", (tg,)).fetchone()
            testo = _testo_avviso_mercatino_tutti(vive, _pref_avvisi_mercatino(p))
            riga = f"🆕 Nuovi annunci: {len(vive)} a {tg}"
        fuori.append((tg, testo, riga))
    con.execute("DELETE FROM mercatino_avvisi_coda WHERE accodato < ?",
                (adesso - GIORNI_DEDUP_AVVISI * 86400,))
    con.commit()
    return fuori


async def _giro_avvisi_mercatino():
    """Un battito: a chi tocca il messaggio, e via. Lo chiamano il
    drenatore (subito dopo la coda: il primo messaggio parte subito) e
    l'orologio al minuto (le righe che aspettano la loro finestra). Esce
    a leva spenta. Fail-open come le sorelle: ogni invio ha il suo try e
    la sua riga nel journal."""
    if not MERCATINO_AVVISI_NUOVI:
        return
    adesso = int(time.time())
    con = db()
    try:
        avvisi = _scarica_avvisi_mercatino(con, adesso)
    finally:
        con.close()
    for tg_id, testo, riga in avvisi:
        try:
            esito = await notifica(tg_id, testo)
            print(f"{riga}: mandato ({esito})" if esito else f"{riga}: mandato",
                  flush=True)
        except Exception as e:
            print(f"⚠️ {riga}: SALTATO ({type(e).__name__}: {e})", flush=True)
        await asyncio.sleep(0.2)


async def orologio_avvisi_mercatino():
    """Il giro al minuto degli avvisi del mercatino: le righe in coda che
    hanno aspettato la loro finestra escono da qui. L'orologio grande
    batte ogni dieci minuti, troppo rado per una finestra da quindici:
    un giro suo, come il cambio."""
    while True:
        await asyncio.sleep(60)
        try:
            await _giro_avvisi_mercatino()
        except Exception as e:
            print(f"⚠️ Avvisi del mercatino: battito saltato "
                  f"({type(e).__name__}: {e})", flush=True)
        # GLI INVITI DEI CODICI SCONTO (14 nov 2026): l'«Invia» parte
        # subito da solo; qui si riprende una coda rimasta a meta' (un
        # riavvio, un giro saltato)
        try:
            await _giro_inviti_codice()
        except Exception as e:
            print(f"⚠️ Inviti dei codici sconto: battito saltato "
                  f"({type(e).__name__}: {e})", flush=True)
        # LA SCOPA DELLA CHAT DEGLI ORDINI (16 ott 2026): al minuto, e a
        # leva spenta pure — un ordine concluso da una strada che non
        # passa dalle rotte (un payout ripreso dall'orologio, un
        # rimborso pagato) perde la sua chat entro un minuto
        try:
            n = _chat_p2p_spazza(mercatino=True)
            if n:
                print(f"🧹 Chat degli ordini: cancellate le buste di {n} "
                      f"{'ordine concluso' if n == 1 else 'ordini conclusi'}", flush=True)
        except Exception as e:
            print(f"⚠️ Chat degli ordini: la scopa non e' passata "
                  f"({type(e).__name__}: {e})", flush=True)


def pulisci_indirizzi():
    """LA SCOPA DEGLI INDIRIZZI (ago 2026): l'indirizzo di casa vive
    quanto l'ordine e poi sparisce. E' il pezzo che rende vera la
    parola «trasporta»: senza, «non lo conserviamo» sarebbe una frase
    e basta.

    E DALL'AGO 2026 SPAZZA ANCHE L'EMAIL PER IL CORRIERE, che e' la
    stessa promessa su un altro campo — il nome resta il suo (il patto
    dei nomi interni: si rinominano i testi, mai le chiavi). QUI
    DENTRO e non in una gemella: le due velocita' e il gate sulla leva
    sono la parte delicata, e due copie divergono al primo ritocco;
    le tre righe da non ammorbidire qui sotto valgono identiche per
    tutte e due.

    DUE VELOCITA', ed e' una decisione di Andrea che viene dritta
    dalla regola di casa — «garantiamo la TRANSAZIONE, non la
    consegna»:
    - alla CONFERMA DI RICEZIONE si cancella SUBITO (al primo giro
      dell'orologio, entro dieci minuti). Il compratore ha detto che
      l'oggetto e' arrivato: da li' in poi quel che succede fra loro
      non ci riguarda piu', e l'indirizzo non serve a niente;
    - gli ordini che si chiudono SENZA quella conferma — un rimborso,
      una disputa decisa da un moderatore — hanno la finestra di
      GIORNI_INDIRIZZO, perche' li' la conferma non arrivera' mai e
      il pacco puo' essere ancora in giro.

    IL DISCRIMINANTE E' `disputata`, E IL PERCHE' E' STRUTTURALE: con
    AUTO_SBLOCCO_ATTIVO spenta a 'released' ci si arriva in due modi
    soli — la conferma del compratore, o la decisione di un moderatore
    su una disputa — e la seconda lascia `disputata=1` per sempre.
    NON si guarda `consegnato`, che verrebbe naturale e sarebbe la
    trappola: conferma_ricezione accetta anche 'locked' e 'shipped',
    quindi quasi nessuno passa da 'delivered' (misurato: 14 released
    su 14 col campo a zero) e la purga immediata non scatterebbe
    quasi mai, credendo di essere piu' severa.
    ⚠️ E IL GIORNO CHE L'AUTO-SBLOCCO SI RIACCENDE la regola
    diventerebbe FALSA in silenzio: uno sblocco automatico lascia
    `disputata=0` e nessuno ha confermato niente — anzi, e' proprio il
    caso in cui il pacco potrebbe non essere mai arrivato. Per questo
    la corsia veloce e' gated sulla leva: a leva accesa passano tutti
    dalla finestra. E' lo stesso patto di sollecita_conferme_ferme,
    che gira solo a leva spenta perche' e' il SOSTITUTO
    dell'auto-sblocco e non un'aggiunta.

    TRE RIGHE DA NON AMMORBIDIRE.
    1) La guardia `indirizzo<>''` non e' un'ottimizzazione: senza,
       questo UPDATE riscriverebbe OGNI ordine chiuso a ogni battito
       dell'orologio, e soprattutto timbrerebbe indirizzo_purgato_il
       anche su righe che un indirizzo non l'hanno mai avuto — cioe'
       farebbe perdere di senso l'unico controllo che rende la
       promessa VERIFICABILE («purgato ma ancora scritto»).
    2) NON si tocca `aggiornato`. E' l'ancora di _SQL_FERMI e delle
       finestre dei promemoria: spostarla vorrebbe dire far ripartire
       da capo l'attesa di qualcuno per una manutenzione — la trappola
       gia' pagata altrove, e nascondi_ordine se l'e' negata per
       iscritto.
    3) Solo gli stati ASSORBENTI. 'annullato' NON serve e non c'e':
       quelle lapidi le cancella per intero pulisci_ordini_fantasma
       dopo un'ora, quindi l'indirizzo di chi non ha mai pagato se ne
       va con la riga molto prima — ed e' la parte migliore del
       meccanismo, non un buco."""
    adesso = int(time.time())
    try:
        con = db()
        # 1) LA CORSIA VELOCE: chi ha confermato la ricezione. Due
        #    UPDATE separati e non uno con l'SQL costruito a pezzi: qui
        #    la differenza non e' di stile — una WHERE che cambia forma
        #    secondo una leva e' una WHERE che si legge male il giorno
        #    che qualcuno la deve capire in fretta.
        veloce = 0
        if not AUTO_SBLOCCO_ATTIVO:
            veloce = con.execute(
                "UPDATE ordini SET indirizzo='', indirizzo_purgato_il=? "
                "WHERE indirizzo<>'' AND indirizzo_purgato_il=0 "
                "AND stato='released' AND disputata=0",
                (adesso,)).rowcount
            # L'EMAIL PER IL CORRIERE VIAGGIA CON LUI (ago 2026), e
            # sta QUI DENTRO e non in una gemella: le due velocita' e
            # il gate sulla leva sono la parte delicata, e due copie
            # divergono al primo ritocco — il patto gia' scritto nella
            # docstring. Due UPDATE in piu' con la stessa forma, le
            # stesse tre righe da non ammorbidire (la guardia
            # `<>''`, `aggiornato` mai toccato, i soli stati
            # assorbenti).
            veloce += con.execute(
                "UPDATE ordini SET email_corriere='', "
                "email_corriere_purgata_il=? "
                "WHERE email_corriere<>'' AND email_corriere_purgata_il=0 "
                "AND stato='released' AND disputata=0",
                (adesso,)).rowcount
            # e le risposte alle domande del venditore (6 nov 2026),
            # stessa forma e stesse tre righe da non ammorbidire
            veloce += con.execute(
                "UPDATE ordini SET risposte='', risposte_purgate_il=? "
                "WHERE risposte<>'' AND risposte_purgate_il=0 "
                "AND stato='released' AND disputata=0",
                (adesso,)).rowcount
        # 2) LA FINESTRA: chi si e' chiuso senza quella conferma
        n = con.execute(
            "UPDATE ordini SET indirizzo='', indirizzo_purgato_il=? "
            "WHERE indirizzo<>'' AND indirizzo_purgato_il=0 "
            "AND stato IN ('released','refunded') AND aggiornato < ?",
            (adesso, adesso - GIORNI_INDIRIZZO * 86400)).rowcount
        n += con.execute(
            "UPDATE ordini SET email_corriere='', "
            "email_corriere_purgata_il=? "
            "WHERE email_corriere<>'' AND email_corriere_purgata_il=0 "
            "AND stato IN ('released','refunded') AND aggiornato < ?",
            (adesso, adesso - GIORNI_INDIRIZZO * 86400)).rowcount
        n += con.execute(
            "UPDATE ordini SET risposte='', risposte_purgate_il=? "
            "WHERE risposte<>'' AND risposte_purgate_il=0 "
            "AND stato IN ('released','refunded') AND aggiornato < ?",
            (adesso, adesso - GIORNI_INDIRIZZO * 86400)).rowcount
        # 3) (14 nov 2026, audit) LA FOTOGRAFIA DELL'ACQUISTO ON-CHAIN
        #    (`onchain_ordini.dettagli`: indirizzo, email, nota, risposte)
        #    se ne va con l'ordine di sempre a cui ha dato vita: quando la
        #    sua riga in `ordini` e' chiusa e i suoi campi sono stati
        #    puliti (o la finestra e' passata). Prima restava per sempre
        try:
            n += con.execute(
                "UPDATE onchain_ordini SET dettagli='{}' "
                "WHERE dettagli NOT IN ('', '{}') AND ordine_id>0 AND ordine_id IN "
                "(SELECT id FROM ordini WHERE stato IN ('released','refunded') "
                "AND (indirizzo_purgato_il>0 OR email_corriere_purgata_il>0 "
                "OR risposte_purgate_il>0 OR aggiornato < ?))",
                (adesso - GIORNI_INDIRIZZO * 86400,)).rowcount
        except sqlite3.OperationalError:
            pass
        con.commit()
        con.close()
        if veloce or n:
            print(f"🏠 Indirizzi cancellati: {veloce} alla conferma, "
                  f"{n} allo scadere della finestra")
    except Exception as e:
        print(f"⚠️ Pulizia indirizzi saltata: {e}")


def pulisci_presenze_p2p():
    """La scopa delle prove d'incontro del contanti (30 set 2026),
    chiamata dall'orologio: le posizioni si scordano dopo
    P2P_PRESENZA_POSIZIONI_S anche se l'evento di chiusura non e' mai
    arrivato, e la riga intera se ne va con la cronaca
    (P2P_LIBRO_MEMORIA_S). Il conto lo fa `_scopa_presenze_p2p`."""
    con = db()
    try:
        n = _scopa_presenze_p2p(con, int(time.time()))
        con.commit()
    finally:
        con.close()
    if n:
        print(f"🧹 P2P: {n} prove d'incontro alleggerite o tolte", flush=True)


def pulisci_avvisi():
    """La scopa degli avvisi, chiamata dall'orologio: via le righe di
    dedup piu' vecchie di GIORNI_DEDUP_AVVISI (un annuncio non rinasce
    dopo un mese) e i contatori dei giorni passati."""
    try:
        con = db()
        con.execute("DELETE FROM avvisi_notificati WHERE creato < ?",
                    (int(time.time()) - GIORNI_DEDUP_AVVISI * 86400,))
        con.commit()
        con.close()
    except Exception as e:
        print(f"⚠️ Pulizia avvisi saltata: {e}")
    oggi = time.strftime("%Y-%m-%d")
    for tg_id in [t for t, v in AVVISI_QUOTA.items() if v[0] != oggi]:
        AVVISI_QUOTA.pop(tg_id, None)
    # (i gettoni delle ricerche AI non ci sono piu': la ricerca non
    # chiama nessuno e non ha una quota da spazzare — ma l'ORA resta,
    # che la usa la scopa dei codici sconto qui sotto)
    ora = time.strftime("%Y-%m-%d %H")
    # e i gettoni dei codici sconto sbagliati, per la stessa ragione
    for tg_id in [t for t, v in CODICE_QUOTA.items() if v[0] != ora]:
        CODICE_QUOTA.pop(tg_id, None)


# ------------------- offerta lampo: «ha fatto colpo» -----------------
# Quando qualcuno mette un annuncio nel suo barattolo, il VENDITORE
# riceve un avviso ANONIMO («qualcuno», mai chi ne' quanti: i preferiti
# restano privati per natura) con l'invito a lanciare un'offerta lampo.
# Stessa valvola dei post promo: finestra di raggruppamento, rilettura
# dal DB, aggregato oltre la soglia. In piu' un cooldown PER ANNUNCIO
# (GIORNI_COLPO, colonna lampo_colpo_avvisato): dieci salvataggi in una
# settimana = un solo avviso, l'entusiasmo non deve diventare molestia.

CODA_COLPO: list[int] = []       # annunci appena messi nel barattolo
_drenatore_colpo_avviato = False


def accoda_colpo(annuncio_id: int):
    """Mette l'annuncio in coda per l'avviso «ha fatto colpo» e, se
    dorme, sveglia il drenatore. Leggera e sincrona: si chiama DOPO il
    commit del salvataggio, mai dentro la transazione."""
    global _drenatore_colpo_avviato
    if not LAMPO_ATTIVE:
        return
    CODA_COLPO.append(annuncio_id)
    if not _drenatore_colpo_avviato:
        _drenatore_colpo_avviato = True
        asyncio.create_task(_drena_colpo())


async def _drena_colpo():
    """Il drenatore: dorme la finestra, rilegge ogni annuncio dal DB
    (spariti, importati, in cooldown o gia' in lampo = muti), raggruppa
    per venditore e applica la regola di sempre — un messaggio per
    annuncio fino alla soglia, un solo aggregato oltre. Il timbro del
    cooldown si scrive PRIMA di notificare (il pattern dei commit)."""
    global _drenatore_colpo_avviato
    await asyncio.sleep(ATTESA_RAGGRUPPO)
    ids = list(dict.fromkeys(CODA_COLPO))
    CODA_COLPO.clear()
    _drenatore_colpo_avviato = False   # chi arriva ora fa un giro nuovo
    try:
        adesso = int(time.time())
        per_venditore: dict[int, list] = {}
        con = db()
        for i in ids:
            a = con.execute("SELECT * FROM annunci WHERE id=?",
                            (i,)).fetchone()
            if (not a or a["stato"] != "attivo"
                    or a["lampo_scadenza"] > adesso   # lampo gia' in corso
                    or adesso - a["lampo_colpo_avvisato"]
                        < GIORNI_COLPO * 86400):
                continue
            per_venditore.setdefault(a["venditore_id"], []).append(dict(a))
        # Il timbro del cooldown prima delle notifiche: se una notifica
        # inciampa, meglio un avviso perso che uno ripetuto.
        for annunci in per_venditore.values():
            for a in annunci:
                con.execute("UPDATE annunci SET lampo_colpo_avvisato=? "
                            "WHERE id=?", (adesso, a["id"]))
        con.commit()
        con.close()
        for venditore, annunci in per_venditore.items():
            if len(annunci) <= SOGLIA_AGGREGA:
                for a in annunci:
                    await notifica(venditore, (
                        f"🫙 Il tuo annuncio ha fatto colpo!\n"
                        f"<b>{html.escape(a['titolo'])}</b>: qualcuno "
                        f"l'ha appena messo nel suo barattolo.\n"
                        f"💰 Se vuoi dargli una spinta, lancia "
                        f"un'offerta lampo dalla scheda dell'annuncio:\n"
                        f"{link_telegram('annuncio', a['id'])}"))
            else:
                # La valvola: un solo messaggio, non nomina nessuno.
                await notifica(venditore, (
                    f"🫙 {len(annunci)} tuoi annunci hanno fatto colpo: "
                    f"qualcuno li ha messi nel suo barattolo.\n"
                    f"💰 Dalle loro schede puoi lanciare un'offerta "
                    f"lampo → {URL_PUBBLICO}"))
            await asyncio.sleep(0.2)
    except Exception as e:
        print(f"⚠️ Avviso «ha fatto colpo» saltato: {e}")


# Il ciclo di vita agisce solo su post GIA' fatti (le colonne piene):
# per questo non guarda la leva POST_AUTOMATICI — un post esistente va
# tenuto vero (o tolto) anche se nel frattempo la leva e' stata spenta.

async def promo_venduto(annuncio_id: int, venduto: bool = True):
    """L'annuncio e' stato venduto: il post nel canale si aggiorna col
    ✅ Venduto. La nota Nostr resta com'e': e' storia vera. Con
    venduto=False fa il viaggio inverso (rimborso: l'oggetto torna in
    vetrina e il post non deve mentire)."""
    try:
        con = db()
        # il JOIN sul venditore NON e' un di piu': _caption_canale
        # RICOSTRUISCE il testo da capo, e senza queste tre chiavi il
        # post riscritto col ✅ perderebbe la firma che aveva da nuovo
        a = con.execute(
            "SELECT a.*, u.nome AS venditore, "
            "u.username AS venditore_username, "
            "u.npub AS venditore_npub, "
            "u.npub_verificata AS venditore_npub_verificata, "
            "u.npub_accesso AS venditore_npub_accesso, "
            "u.negozio AS venditore_negozio "
            "FROM annunci a JOIN utenti u ON u.tg_id=a.venditore_id "
            "WHERE a.id=?", (annuncio_id,)).fetchone()
        # gli altri articoli si RILEGGONO: il post riscritto col ✅ non
        # deve perdere la vetrina che aveva da nuovo, e nel frattempo
        # qualcuno di quei link puo' essere stato venduto — meglio la
        # lista di oggi che tre link a scaffali vuoti
        altri = _altri_del_venditore(con, dict(a)) if a else []
        con.close()
        if not a:
            return
        # DUE DESTINAZIONI, LO STESSO ✅ (ago 2026): ognuna col SUO
        # message_id, o il segno finirebbe su un post che sta altrove.
        # Ognuna fallisce per conto suo: se il canale della comunita'
        # ci ha tolto i permessi, il nostro si aggiorna lo stesso.
        dove = [(canale_id(), a["post_canale_id"]),
                (canale_vetrina(), _post_vetrina(a)),
                (canale_bitcoin_podcast(), _post_podcast(a))]
        if not any(c and m for c, m in dove):
            return
        caption = _caption_canale(dict(a), await cambio_btc_eur(),
                                  venduto=venduto, altri=altri)
        # Con la foto il testo vive nella caption, senza nel body — ma
        # il ripiego sendMessage di _posta_promo_singolo rende il tipo
        # ambiguo: si tenta il piu' probabile e poi l'altro.
        campo = {"editMessageCaption": "caption", "editMessageText": "text"}
        tentativi = (["editMessageCaption", "editMessageText"]
                     if _foto_url_nostr(a["foto"])
                     else ["editMessageText", "editMessageCaption"])
        for canale, msg in dove:
            if not (canale and msg):
                continue
            dati = {"chat_id": canale, "message_id": msg,
                    "parse_mode": "HTML"}
            for metodo in tentativi:
                r = await bot_api(metodo, {**dati, campo[metodo]: caption})
                if r and r.get("ok"):
                    break
    except Exception as e:
        # flush=True (17 ott 2026, cantiere venduto-canale): senza, la
        # riga restava nel buffer dello stdout e ai riavvii si perdeva —
        # sul VPS il guasto del .get() e' scattato e il journal non l'ha
        # mai mostrato. Un errore si vede SUBITO o non serve.
        print(f"⚠️ Aggiornamento post venduto #{annuncio_id} saltato: {e}",
              flush=True)


async def promo_rimuovi(annuncio_id: int):
    """L'annuncio e' sparito dalla vetrina: il post nel canale si
    cancella e la nota Nostr riceve la sua NIP-09 (fail-open: se un
    relay la ignora, pazienza — la nota non mente, l'annuncio c'era)."""
    try:
        con = db()
        a = con.execute(
            "SELECT post_canale_id, post_vetrina_id, post_bitcoin_podcast_id, "
            "post_nostr_id, foto FROM annunci WHERE id=?", (annuncio_id,)).fetchone()
        con.close()
        vetrina = _post_vetrina(a) if a else 0
        if not a or not (a["post_canale_id"] or vetrina
                         or _post_podcast(a) or a["post_nostr_id"]):
            return
        # ogni canale col SUO id, e ognuno fallisce per conto suo
        for canale, msg in ((canale_id(), a["post_canale_id"]),
                            (canale_vetrina(), vetrina),
                            (canale_bitcoin_podcast(), _post_podcast(a))):
            if canale and msg:
                await bot_api("deleteMessage",
                              {"chat_id": canale, "message_id": msg})
        if a["post_nostr_id"] and _NOSTR:
            await _spedisci_ai_relay(
                firma_evento(5, [["e", a["post_nostr_id"]], ["k", "1"]],
                             "Annuncio rimosso da Barattolo"))
        con = db()
        con.execute("UPDATE annunci SET post_canale_id=0, "
                    "post_vetrina_id=0, post_bitcoin_podcast_id=0, post_nostr_id='' WHERE id=?",
                    (annuncio_id,))
        con.commit()
        con.close()
    except Exception as e:
        print(f"⚠️ Ritiro post automatici #{annuncio_id} saltato: {e}",
              flush=True)


@app.get("/api/swap/preventivo/{ordine_id}")
async def swap_preventivo(ordine_id: int, hash: str = "",
                          fornitore: str = "satsrouting",
                          x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """IL PREVENTIVO DELLO SWAP (19 ott 2026, tappa 2): per il venditore
    di un ordine CONFERMATO, quanto riceverebbe on-chain con uno swap di
    SATS Routing invece che in Lightning. Non crea niente e non muove
    niente: legge le tariffe e fa il conto.
    `hash` = l'impronta del preventivo che il client ha gia' mostrato:
    se le tariffe nel frattempo sono cambiate la risposta lo dice
    (`cambiata`), col preventivo nuovo — e' il rifiuto «tariffa
    cambiata» che la tappa 3 usera' alla conferma vera.
    `fornitore` (20 ott 2026, l'instradatore) = di quale fornitore: il
    telefono li chiede tutti e sceglie il migliore; di serie SATS Routing.
    La risposta dice chi (`fornitore`, `fornitore_nome`): il preventivo lo
    mostra in piccolo, «eseguito da …»."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not swap_per(user["id"]):
        raise HTTPException(403, "Lo swap non e' disponibile")
    chi = swap_fornitore(str(fornitore or ""))
    if chi is None:
        raise HTTPException(404, "Fornitore sconosciuto")
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=?",
                    (ordine_id,)).fetchone()
    con.close()
    if not o or o["venditore_id"] != user["id"]:
        raise HTTPException(404, "Ordine non trovato")
    if o["stato"] != "confirmed":
        raise HTTPException(409, "Lo swap si sceglie quando i sats "
                                 "sono da incassare")
    dovuto = netto_venditore(o["prezzo_sats"] - o["protezione_sats"])
    tariffa = await leggi_tariffa_swap(chi)
    if tariffa is None:
        return {"ok": False, "motivo": "non_risponde", "dovuto": dovuto,
                "fornitore": chi["id"], "fornitore_nome": chi["nome"]}
    p = preventivo_swap(dovuto, tariffa, SWAP_FEE_PERCENTO,
                        SWAP_MIN_SATS, SWAP_MAX_SATS)
    p["cambiata"] = bool(hash) and hash != tariffa["hash"]
    p["valido_s"] = SWAP_PREVENTIVO_VALE_S
    p["fornitore"], p["fornitore_nome"] = chi["id"], chi["nome"]
    return p


# --- LA TAPPA 4 DELLO SWAP: BARATTOLO PAGA LA FATTURA (24 ott 2026) -----
# Il telefono di chi vende ha creato lo swap e l'ha verificato (tappa 3);
# adesso manda qui le sole parti PUBBLICHE — la fattura, l'impronta del
# segreto, l'indirizzo dove il fornitore blocchera' i bitcoin, quanto ci
# blocchera', a che blocco scade — e il server paga la fattura con i sats
# dell'ordine, dalla SUA cassaforte, per la porta di sempre
# (`_sblocca_sats` -> `paga_venditore`, con la riga dell'ordine): la
# stessa difesa contro il doppio pagamento di ogni incasso, e i
# 🧊 Pagamenti da verificare quando non si sa com'e' andata. swap@ NON
# paga niente: incassa solo la quota (decisione di Andrea, 24 ott).
#
# PRIMA DI PAGARE, i controlli che si possono fare prima (il lockup
# arriva solo DOPO il pagamento: in uno swap Lightning -> on-chain la
# fattura e' «trattenuta», e il fornitore blocca i bitcoin quando vede il
# pagamento arrivare): l'importo e' quel che spetta a chi vende, la
# fattura porta l'impronta che il telefono dichiara, l'indirizzo e' un
# taproot della rete giusta e su mempool e' ancora VUOTO, lo swap ha
# ancora tempo davanti. I tre controlli sul lockup (lo script atteso,
# l'importo, la transazione letta da mempool) restano nel telefono,
# prima del segreto: se il lockup mente il segreto non esce, la fattura
# non si chiude, e alla scadenza i sats tornano nella cassaforte.
#
# UN PAGAMENTO PER SWAP, registrato PRIMA di partire (`swap_pagamenti`),
# e UNO swap vivo per ordine. Lo stato della riga si DERIVA dall'ordine
# (`_swap_pag_stato`), come lo stadio del pagamento: la colonna e'
# l'ultimo stato visto, che il journal racconta quando cambia.
SWAP_PAG_REGISTRATO = "registrato"     # scritto, non ancora partito
SWAP_PAG_IN_VOLO = "in_volo"           # partito: aspetta il ritiro
SWAP_PAG_PAGATO = "pagato"             # la fattura si e' chiusa
SWAP_PAG_DA_VERIFICARE = "da_verificare"   # 🧊: decide una persona
SWAP_PAG_FALLITO = "fallito"           # non e' uscito niente
SWAP_PAG_FINALI = (SWAP_PAG_PAGATO, SWAP_PAG_FALLITO)
# il prefisso degli indirizzi e delle fatture di ogni rete
SWAP_HRP = {"bitcoin": "bc", "testnet": "tb", "regtest": "bcrt"}
_SWAP_ID_FORMA = re.compile(r"^[A-Za-z0-9_-]{4,80}$")
_SWAP_IMPRONTA_FORMA = re.compile(r"^[0-9a-f]{64}$")
_SWAP_BECH32M = 0x2bc830a3
# un lucchetto solo per le registrazioni: i tetti del giorno si contano e
# si superano dentro, e due richieste insieme non li passano tutt'e due
_lucchetto_swap_pagamenti = asyncio.Lock()
_SWAP_MEMPOOL_DETTO = set()


def _swap_pag_prepara(con):
    """`swap_pagamenti`: una riga per fattura di swap che Barattolo paga."""
    con.execute("""CREATE TABLE IF NOT EXISTS swap_pagamenti(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ordine_id INTEGER NOT NULL,
        venditore_id INTEGER NOT NULL,
        fornitore TEXT NOT NULL,
        swap_id TEXT NOT NULL,
        hash TEXT NOT NULL UNIQUE,
        bolt11 TEXT NOT NULL,
        sats INTEGER NOT NULL,
        onchain INTEGER DEFAULT 0,
        indirizzo TEXT DEFAULT '',
        scade_blocco INTEGER DEFAULT 0,
        vola_fino INTEGER DEFAULT 0,
        stato TEXT DEFAULT 'registrato',
        creato INTEGER DEFAULT 0,
        aggiornato INTEGER DEFAULT 0,
        UNIQUE(fornitore, swap_id))""")


def _swap_pag_db():
    con = db()
    _swap_pag_prepara(con)
    return con


def swap_indirizzo_p2tr(indirizzo: str, rete: str) -> bool:
    """E' un indirizzo TAPROOT di questa rete? Gli swap Lightning ->
    on-chain bloccano i bitcoin in un p2tr (la chiave MuSig con l'albero
    dello swap): bech32m (BIP-350), versione 1, 32 byte. Il checksum si
    verifica davvero: un carattere sbagliato e' un no."""
    return _swap_programma_p2tr(indirizzo, rete) is not None


def _swap_programma_p2tr(indirizzo: str, rete: str) -> bytes | None:
    """I 32 byte che un indirizzo TAPROOT di questa rete porta dentro (la
    chiave x-only dell'uscita), o None se non e' un p2tr di questa rete.
    (2 nov 2026, cantiere swap-auto) staccata da `swap_indirizzo_p2tr`
    perche' lo swap automatico deve CONFRONTARE l'indirizzo del lockup
    con la chiave che rifa' da se', non solo sapere che e' un p2tr."""
    s = str(indirizzo or "").strip()
    if s != s.lower() and s != s.upper():
        return None
    s = s.lower()
    hrp = SWAP_HRP.get(rete, "bc")
    if not s.startswith(hrp + "1"):
        return None
    try:
        v = [_BECH32_ALFABETO.index(c) for c in s[len(hrp) + 1:]]
    except ValueError:
        return None
    if len(v) < 7:
        return None
    espanso = [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]
    if _bech32_polymod(espanso + v) != _SWAP_BECH32M:
        return None
    dati = v[:-6]
    if dati[0] != 1:
        return None
    programma, acc, bits = [], 0, 0
    for g in dati[1:]:
        acc = (acc << 5) | g
        bits += 5
        if bits >= 8:
            bits -= 8
            programma.append((acc >> bits) & 0xff)
    if bits >= 5 or (acc & ((1 << bits) - 1)):
        return None
    return bytes(programma) if len(programma) == 32 else None


async def _swap_mempool_leggi(base: str, percorso: str) -> str | None:
    """Una lettura dal mempool (sola lettura, dati pubblici). None = non
    risponde. IN COLLAUDO NON SI ESCE DAL COMPUTER, come per le tariffe:
    una base che non e' di casa non si legge."""
    base = str(base or "").rstrip("/")
    if not base:
        return None
    if MODALITA_COLLAUDO and not _swap_base_di_casa(base):
        if base not in _SWAP_MEMPOOL_DETTO:
            _SWAP_MEMPOOL_DETTO.add(base)
            print(f"🟣 [swap simulato] il mempool {base}: in collaudo non si "
                  "esce dal computer (punta SWAP_MEMPOOL_API al cartone)",
                  flush=True)
        return None
    try:
        async with httpx.AsyncClient(timeout=8) as c:
            r = await c.get(f"{base}{percorso}")
        if r.status_code != 200:
            return None
        return r.text
    except Exception as e:
        print(f"⚠️ Swap: il mempool non risponde ({type(e).__name__})",
              flush=True)
        return None


def _swap_pag_stato(r, o) -> str:
    """LO STATO DI UN PAGAMENTO DI SWAP, derivato dall'ordine: l'ordine e'
    la verita' (lo scrive la porta dei pagamenti), la riga dice solo di
    QUALE fattura si parla."""
    if not o:
        return SWAP_PAG_FALLITO
    if (o["payout_hash"] or "") == r["hash"]:
        if o["stato"] == "released" or o["payout_stato"] == "uscito":
            return SWAP_PAG_PAGATO
        if o["payout_stato"] == "in_volo":
            return SWAP_PAG_IN_VOLO
        if o["payout_stato"] == "incerto":
            return SWAP_PAG_DA_VERIFICARE
    if (o["invoice_venditore"] or "") == r["bolt11"] \
            and o["stato"] == "confirmed":
        return SWAP_PAG_REGISTRATO
    return SWAP_PAG_FALLITO


def _swap_pag_aggiorna(con, r) -> str:
    """Rilegge lo stato di una riga dall'ordine, e se e' cambiato lo
    scrive e lo dice nel journal. Torna lo stato di adesso."""
    o = con.execute("SELECT * FROM ordini WHERE id=?",
                    (r["ordine_id"],)).fetchone()
    nuovo = _swap_pag_stato(r, o)
    # FALLITO RESTA FALLITO (26 ott 2026, il giro sul regtest): dopo un
    # fallimento che LNbits non aveva nemmeno registrato, la porta dei
    # pagamenti tiene sull'ordine il NOME di quel pagamento per 15 minuti
    # (finche' non lo crede «mai partito»), e la riga sembrava tornata in
    # volo — col journal che lo diceva e i tetti del giorno che contavano
    # due volte i sats dello stesso ordine. Una riga vista fallita puo'
    # solo diventare pagata: il pagamento fatto a mano (il caso del #241).
    if r["stato"] == SWAP_PAG_FALLITO and nuovo != SWAP_PAG_PAGATO:
        nuovo = SWAP_PAG_FALLITO
    if nuovo != r["stato"]:
        con.execute("UPDATE swap_pagamenti SET stato=?, aggiornato=? "
                    "WHERE id=?", (nuovo, int(time.time()), r["id"]))
        con.commit()
        print(f"🔄 Swap dell'ordine #{r['ordine_id']}: il pagamento passa "
              f"da «{r['stato']}» a «{nuovo}» ({r['hash'][:12]}…)",
              flush=True)
    return nuovo


def swap_pagamenti_ripassa() -> int:
    """Rilegge le righe non ancora finite: il journal dice ogni passo
    anche quando a chiuderlo e' stata la ronda o un moderatore."""
    con = _swap_pag_db()
    try:
        righe = con.execute("SELECT * FROM swap_pagamenti WHERE stato NOT IN "
                            "(?, ?)", SWAP_PAG_FINALI).fetchall()
        for r in righe:
            _swap_pag_aggiorna(con, r)
        return len(righe)
    finally:
        con.close()


def _limite_in_volo(tabella: str, riga_id: int, phash: str,
                    quando: int) -> int:
    """FINO A QUANDO un pagamento in volo e' normale. Di serie
    `IN_VOLO_LIMITE_S` dopo la partenza; la fattura di uno swap invece e'
    trattenuta finche' il telefono di chi vende non ritira i bitcoin, e
    puo' restare in volo fino alla scadenza dello swap (`vola_fino`,
    scritto alla registrazione): prima di allora non e' una stranezza."""
    base = int(quando or 0) + IN_VOLO_LIMITE_S
    if tabella != "ordini" or not phash:
        return base
    try:
        con = _swap_pag_db()
        try:
            r = con.execute("SELECT vola_fino FROM swap_pagamenti WHERE "
                            "ordine_id=? AND hash=?",
                            (riga_id, phash)).fetchone()
        finally:
            con.close()
    except Exception as e:
        print(f"⚠️ Il limite del volo di {tabella}#{riga_id} non si legge "
              f"({e}): vale quello di serie", flush=True)
        return base
    return max(base, int(r[0] or 0)) if r else base


def _swap_pag_somme(con, venditore_id: int, adesso: int) -> tuple:
    """Quanto e' gia' impegnato nelle ultime 24 ore: (di chi vende, di
    tutti). Contano le righe non fallite, rilette dall'ordine."""
    mio = tutti = 0
    for r in con.execute("SELECT * FROM swap_pagamenti WHERE creato>?",
                         (adesso - 86_400,)).fetchall():
        if _swap_pag_aggiorna(con, r) == SWAP_PAG_FALLITO:
            continue
        tutti += int(r["sats"])
        if int(r["venditore_id"]) == int(venditore_id):
            mio += int(r["sats"])
    return mio, tutti


def _swap_pag_no(ordine_id: int, motivo: str, detto: str = "") -> dict:
    """Un rifiuto PRIMA di pagare: niente e' partito, e il journal lo dice."""
    print(f"🔄 Swap dell'ordine #{ordine_id}: non si paga — {motivo}"
          + (f" ({detto})" if detto else "") + ". Niente e' partito.",
          flush=True)
    return {"ok": False, "motivo": motivo}


async def swap_registra_pagamento(venditore_id: int, ordine_id: int,
                                  chi: dict, s: dict) -> dict:
    """I CONTROLLI, LA REGISTRAZIONE, IL PAGAMENTO. `s` sono le parti
    pubbliche dello swap, gia' ripulite nella forma dalla rotta."""
    con = _swap_pag_db()
    try:
        o = con.execute("SELECT * FROM ordini WHERE id=?",
                        (ordine_id,)).fetchone()
        if not o or o["venditore_id"] != venditore_id:
            return {"ok": False, "motivo": "ordine", "non_trovato": True}
        stessa = con.execute("SELECT * FROM swap_pagamenti WHERE hash=?",
                             (s["impronta"],)).fetchone()
        if stessa and int(stessa["ordine_id"]) != ordine_id:
            return _swap_pag_no(ordine_id, "usato",
                                "la fattura e' di un altro ordine")
        if stessa:
            # LA STESSA FATTURA UNA SECONDA VOLTA (un telefono che ripete,
            # una risposta persa): niente di nuovo si registra, e se e'
            # ancora ferma si ripassa dalla porta di sempre, che sa da
            # sola se qualcosa e' gia' partito
            if _swap_pag_aggiorna(con, stessa) != SWAP_PAG_REGISTRATO:
                return {"ok": True, "stato": _swap_pag_aggiorna(con, stessa)}
            con.close()
            await _sblocca_sats(ordine_id)
            con = _swap_pag_db()
            stessa = con.execute("SELECT * FROM swap_pagamenti WHERE id=?",
                                 (stessa["id"],)).fetchone()
            return {"ok": True, "stato": _swap_pag_aggiorna(con, stessa)}
        for r in con.execute("SELECT * FROM swap_pagamenti WHERE ordine_id=?",
                             (ordine_id,)).fetchall():
            if _swap_pag_aggiorna(con, r) != SWAP_PAG_FALLITO:
                return _swap_pag_no(ordine_id, "occupato",
                                    "c'e' gia' uno swap vivo")
        if o["stato"] != "confirmed":
            return _swap_pag_no(ordine_id, "ordine", f"stato {o['stato']}")
        if (o["payout_stato"] or "") in ("in_volo", "incerto", "uscito") \
                or (o["invoice_venditore"] or "") \
                or int(_campo(o, "spese_rese_sats", 0) or 0) > 0:
            return _swap_pag_no(ordine_id, "occupato",
                                "c'e' gia' un incasso in corso")
    finally:
        con.close()
    rete = chi["rete"]
    dovuto = netto_venditore(o["prezzo_sats"] - o["protezione_sats"])
    # LA NOSTRA FEE: la porta dei pagamenti paga ESATTAMENTE quel che spetta
    # a chi vende, e con la fee accesa la fattura dello swap e' meno. Finche'
    # la fee e' spenta (lo e', e lo resta fino al parere legale) e' uguale.
    if float(SWAP_FEE_PERCENTO or 0) > 0:
        return _swap_pag_no(ordine_id, "fee",
                            "con SWAP_FEE_PERCENTO accesa la tappa 4 non paga")
    # 1. L'IMPORTO, letto dalla fattura e non chiesto a nessuno
    if importo_bolt11(s["bolt11"]) != dovuto:
        return _swap_pag_no(ordine_id, "importo",
                            f"la fattura non chiede {_fmt_sats(dovuto)} sats")
    if rete_bolt11(s["bolt11"]) != SWAP_HRP.get(rete, "bc"):
        return _swap_pag_no(ordine_id, "rete", "fattura di un'altra rete")
    # 2. L'IMPRONTA: la fattura porta quella del segreto del telefono
    letta = leggi_bolt11(s["bolt11"], con_hash=True)
    if not letta or letta.get("hash") != s["impronta"]:
        return _swap_pag_no(ordine_id, "impronta",
                            "la fattura non porta l'impronta dichiarata")
    no = rifiuto_scadenza(s["bolt11"])
    if no:
        return _swap_pag_no(ordine_id, "scadenza", "fattura in scadenza")
    # 3. I TETTI DI UNO SWAP e le tariffe di adesso: il fornitore non si
    #    tiene piu' di quel che ha dichiarato
    tariffa = await leggi_tariffa_swap(chi)
    if tariffa is None:
        return _swap_pag_no(ordine_id, "non_risponde",
                            f"le tariffe di {chi['nome']} non arrivano")
    p = preventivo_swap(dovuto, tariffa, 0, SWAP_MIN_SATS, SWAP_MAX_SATS)
    if not p["ok"]:
        return _swap_pag_no(ordine_id, p["motivo"])
    if not (p["onchain"] <= s["onchain"] < dovuto):
        return _swap_pag_no(ordine_id, "cambiata",
                            f"on-chain {s['onchain']}, il preventivo dice "
                            f"{p['onchain']}")
    # 4. L'INDIRIZZO: taproot della rete giusta, e su mempool ancora vuoto
    if not swap_indirizzo_p2tr(s["indirizzo"], rete):
        return _swap_pag_no(ordine_id, "indirizzo",
                            "non e' un taproot di questa rete")
    base = chi.get("mempool") or ""
    cima = await _swap_mempool_leggi(base, "/blocks/tip/height")
    movimenti = await _swap_mempool_leggi(
        base, f"/address/{s['indirizzo']}/txs") if cima else None
    try:
        cima = int(str(cima).strip())
        movimenti = json.loads(movimenti)
    except (TypeError, ValueError):
        return _swap_pag_no(ordine_id, "mempool", "il mempool non risponde")
    if not isinstance(movimenti, list):
        return _swap_pag_no(ordine_id, "mempool", "risposta storta")
    if movimenti:
        return _swap_pag_no(ordine_id, "usato",
                            "sull'indirizzo del lockup c'e' gia' qualcosa")
    # 5. LA SCADENZA DELLO SWAP: tempo per bloccare e per ritirare
    blocchi = s["scade_blocco"] - cima
    if not (SWAP_MARGINE_BLOCCHI <= blocchi <= 10_000):
        return _swap_pag_no(ordine_id, "scadenza",
                            f"allo swap restano {blocchi} blocchi")
    print(f"🔄 Swap dell'ordine #{ordine_id}: controlli passati — "
          f"{_fmt_sats(dovuto)} sats a {chi['nome']} (swap {s['swap_id'][:12]}, "
          f"{s['impronta'][:12]}…), lockup {s['indirizzo'][:10]}…"
          f"{s['indirizzo'][-6:]} vuoto, scade fra {blocchi} blocchi",
          flush=True)
    # 6. I TETTI DEL GIORNO E LA REGISTRAZIONE, sotto un lucchetto solo
    async with _lucchetto_swap_pagamenti:
        con = _swap_pag_db()
        try:
            adesso = int(time.time())
            # LE DUE DOMANDE DI PRIMA, RIFATTE DENTRO IL LUCCHETTO: due
            # richieste insieme (un doppio tocco, un telefono che ripete
            # mentre la prima e' ancora per strada) passano tutt'e due i
            # controlli, ma qui ne entra una alla volta. La stessa fattura
            # e' lo stesso pagamento; un altro swap vivo e' un no.
            stessa = con.execute("SELECT * FROM swap_pagamenti WHERE hash=?",
                                 (s["impronta"],)).fetchone()
            if stessa and int(stessa["ordine_id"]) == ordine_id:
                return {"ok": True, "stato": _swap_pag_aggiorna(con, stessa)}
            if stessa:
                return _swap_pag_no(ordine_id, "usato",
                                    "la fattura e' di un altro ordine")
            for r in con.execute("SELECT * FROM swap_pagamenti WHERE "
                                 "ordine_id=?", (ordine_id,)).fetchall():
                if _swap_pag_aggiorna(con, r) != SWAP_PAG_FALLITO:
                    return _swap_pag_no(ordine_id, "occupato",
                                        "c'e' gia' uno swap vivo")
            mio, tutti = _swap_pag_somme(con, venditore_id, adesso)
            if SWAP_MAX_SATS_UTENTE_GIORNO > 0 \
                    and mio + dovuto > SWAP_MAX_SATS_UTENTE_GIORNO:
                return _swap_pag_no(ordine_id, "tetto_utente",
                                    f"{mio} + {dovuto} in 24 ore")
            if SWAP_MAX_SATS_GIORNO > 0 \
                    and tutti + dovuto > SWAP_MAX_SATS_GIORNO:
                return _swap_pag_no(ordine_id, "tetto_giorno",
                                    f"{tutti} + {dovuto} in 24 ore")
            # la scadenza in secondi, con un'ora di margine: fino ad
            # allora il volo di questa fattura e' normale
            vola_fino = adesso + blocchi * 600 + 3600
            try:
                cur = con.execute(
                    "INSERT INTO swap_pagamenti(ordine_id, venditore_id, "
                    "fornitore, swap_id, hash, bolt11, sats, onchain, "
                    "indirizzo, scade_blocco, vola_fino, stato, creato, "
                    "aggiornato) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (ordine_id, venditore_id, chi["id"], s["swap_id"],
                     s["impronta"], s["bolt11"], dovuto, s["onchain"],
                     s["indirizzo"], s["scade_blocco"], vola_fino,
                     SWAP_PAG_REGISTRATO, adesso, adesso))
            except sqlite3.IntegrityError:
                con.rollback()
                return _swap_pag_no(ordine_id, "usato", "swap gia' visto")
            messa = con.execute(
                "UPDATE ordini SET invoice_venditore=?, aggiornato=? "
                "WHERE id=? AND stato='confirmed' "
                "AND COALESCE(invoice_venditore,'')='' "
                "AND COALESCE(payout_stato,'') NOT IN "
                "('in_volo','incerto','uscito')",
                (s["bolt11"], adesso, ordine_id)).rowcount
            if not messa:
                con.rollback()
                return _swap_pag_no(ordine_id, "occupato",
                                    "l'ordine e' cambiato intanto")
            con.commit()
            riga_id = cur.lastrowid
        finally:
            con.close()
    print(f"🔄 Swap dell'ordine #{ordine_id}: registrato (pagamento "
          f"#{riga_id}), parte il pagamento della fattura", flush=True)
    # 7. IL PAGAMENTO, per la porta di sempre
    await _sblocca_sats(ordine_id)
    return {"ok": True, "stato": _swap_pag_dell_ordine(ordine_id, riga_id)}


def _swap_pag_dell_ordine(ordine_id: int, riga_id: int = 0) -> str:
    """Rilegge TUTTE le righe di un ordine — anche una «fallita»: un
    pagamento fallito che poi risulta uscito (pagato a mano, il caso del
    #241) lo si scopre proprio qui — e torna lo stato di `riga_id` (di
    serie l'ultima)."""
    con = _swap_pag_db()
    try:
        stati = {r["id"]: _swap_pag_aggiorna(con, r) for r in con.execute(
            "SELECT * FROM swap_pagamenti WHERE ordine_id=? ORDER BY id",
            (ordine_id,)).fetchall()}
    finally:
        con.close()
    if not stati:
        return ""
    return stati.get(riga_id) or stati[max(stati)]


def _swap_parti(d: dict) -> dict | None:
    """Le parti pubbliche dello swap dal corpo, ripulite nella forma; None
    se una non ha la forma giusta. Nessuna chiave privata, nessuna parola:
    se ne arrivasse una non avrebbe dove stare."""
    try:
        s = {"swap_id": str(d.get("swap_id") or "").strip(),
             "bolt11": str(d.get("invoice") or "").strip().lower(),
             "impronta": str(d.get("impronta") or "").strip().lower(),
             "indirizzo": str(d.get("indirizzo") or "").strip(),
             "scade_blocco": int(d.get("scade_blocco") or 0),
             "onchain": int(d.get("onchain") or 0)}
    except (TypeError, ValueError, AttributeError):
        return None
    if not (_SWAP_ID_FORMA.match(s["swap_id"])
            and s["bolt11"].startswith("ln") and len(s["bolt11"]) < 2000
            and _SWAP_IMPRONTA_FORMA.match(s["impronta"])
            and 0 < len(s["indirizzo"]) <= 100
            and s["scade_blocco"] > 0 and s["onchain"] > 0):
        return None
    return s


@app.post("/api/swap/paga/{ordine_id}")
async def swap_paga(ordine_id: int, req: Request,
                    x_tg_init_data: str = Header(""),
                    barattolo_sessione: str = Cookie("")):
    """IL PAGAMENTO DELLO SWAP (24 ott 2026, tappa 4): chi vende manda le
    parti pubbliche dello swap che il suo telefono ha creato e verificato,
    e Barattolo paga la fattura con i sats dell'ordine. La risposta dice
    `ok` e lo `stato` del pagamento, o il `motivo` per cui non parte."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not swap_per(user["id"]):
        raise HTTPException(403, "Lo swap non e' disponibile")
    d = await leggi_json(req)
    chi = swap_fornitore(str(d.get("fornitore") or "satsrouting"))
    if chi is None:
        raise HTTPException(404, "Fornitore sconosciuto")
    s = _swap_parti(d)
    if s is None:
        return _swap_pag_no(ordine_id, "forma")
    esito = await swap_registra_pagamento(int(user["id"]), int(ordine_id),
                                          chi, s)
    if esito.pop("non_trovato", False):
        raise HTTPException(404, "Ordine non trovato")
    return esito


@app.get("/api/swap/pagamento/{ordine_id}")
async def swap_pagamento_stato(ordine_id: int,
                               x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """A che punto e' il pagamento dello swap di un ordine (per la carta
    dello swap nel telefono di chi vende). `stato` vuoto: nessuno."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = _swap_pag_db()
    try:
        r = con.execute("SELECT * FROM swap_pagamenti WHERE ordine_id=? "
                        "AND venditore_id=? ORDER BY id DESC LIMIT 1",
                        (ordine_id, int(user["id"]))).fetchone()
    finally:
        con.close()
    if not r:
        return {"stato": "", "swap_id": ""}
    return {"stato": _swap_pag_dell_ordine(ordine_id, r["id"]),
            "swap_id": r["swap_id"]}


# --- LO SWAP AUTOMATICO DEL MERCATINO (2 nov 2026, cantiere swap-auto) ---
# Chi vende in Lightning e vuole i bitcoin on-chain non fa niente col
# telefono: il cambio lo fa il SERVER, perche' i sats sono gia' sul nodo
# (strada B, decisione di Andrea del 2 nov; via di Alan). Le chiavi del
# ritiro sono di BARATTOLO, non del venditore: dodici parole sul VPS
# (`chiavi/swap-barattolo.json`, nate da un admin col gesto del pannello,
# nell'archivio di `backup-fuori.sh` come la chiave on-chain), una chiave
# NUOVA per ogni swap, lo schema delle chiavi di SATS Routing (m/44/0/0/0/i,
# segreto = sha256 della privata) cosi' uno swap si ritrova anche dalla
# loro pagina «Rescue» con le nostre parole. Lo swap ESPLICITO della
# pagina «Cambio» resta del telefono e delle sue chiavi.
# QUESTA E' LA TAPPA 1 (piano approvato da Andrea, «ok parti»): le
# parole, l'indice di ogni swap, la nascita dal fornitore e la VERIFICA
# della sua risposta, in Python, gemella di `swapVerifica` di
# `swap/boltz.js` — e una prova le fa giudicare le STESSE risposte, nate
# dal bundle del telefono (boltz-core 5.0.0). Nessun sats si muove: la
# fattura si paga dalla tappa 3, il ritiro e' la tappa 2.
# L'aritmetica della curva qui sotto e' Python puro, e tocca SOLO chiavi
# pubbliche (la chiave MuSig a due e il ritocco taproot): nessun segreto
# passa da qui, quindi una conta lenta o non a tempo costante non
# racconta niente a nessuno. Le chiavi private le deriva embit.
_SWAP_EC_P = 2 ** 256 - 2 ** 32 - 977
_SWAP_EC_N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
_SWAP_EC_G = (0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798,
              0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8)
# la versione delle foglie dello swap su bitcoin (BIP-342; Liquid ne ha
# un'altra, e qui Liquid non c'e')
SWAP_FOGLIA_VERSIONE = 0xc0


def _swap_ec_somma(a, b):
    """La somma di due punti della curva (None = il punto all'infinito)."""
    p = _SWAP_EC_P
    if a is None:
        return b
    if b is None:
        return a
    if a[0] == b[0] and (a[1] + b[1]) % p == 0:
        return None
    if a == b:
        m = 3 * a[0] * a[0] * pow(2 * a[1], p - 2, p) % p
    else:
        m = (b[1] - a[1]) * pow(b[0] - a[0], p - 2, p) % p
    x = (m * m - a[0] - b[0]) % p
    return (x, (m * (a[0] - x) - a[1]) % p)


def _swap_ec_per(punto, k: int):
    """Un punto per un numero (raddoppia e somma)."""
    r = None
    k = int(k) % _SWAP_EC_N
    while k:
        if k & 1:
            r = _swap_ec_somma(r, punto)
        punto = _swap_ec_somma(punto, punto)
        k >>= 1
    return r


def _swap_ec_punto(sec: bytes, pari: bool = False):
    """Il punto di una chiave pubblica compressa da 33 byte (o, con
    `pari`, quello di una x-only da 32 con la y pari). ValueError se non
    sta sulla curva."""
    sec = bytes(sec)
    if pari:
        if len(sec) != 32:
            raise ValueError("chiave x-only della lunghezza sbagliata")
        sec = b"\x02" + sec
    if len(sec) != 33 or sec[0] not in (2, 3):
        raise ValueError("chiave pubblica non compressa")
    p = _SWAP_EC_P
    x = int.from_bytes(sec[1:], "big")
    if x >= p:
        raise ValueError("chiave pubblica fuori dalla curva")
    y = pow((pow(x, 3, p) + 7) % p, (p + 1) // 4, p)
    if (y * y - pow(x, 3, p) - 7) % p:
        raise ValueError("chiave pubblica fuori dalla curva")
    if (y & 1) != (sec[0] & 1):
        y = p - y
    return (x, y)


def _swap_etichettato(etichetta: str, *pezzi: bytes) -> bytes:
    """L'hash etichettato del BIP-340: sha256(sha256(e)||sha256(e)||dati)."""
    e = hashlib.sha256(etichetta.encode()).digest()
    return hashlib.sha256(e + e + b"".join(pezzi)).digest()


def _swap_spinta(dati: bytes) -> bytes:
    """Lo script che mette `dati` sulla pila (fino a 75 byte, che qui
    bastano: 20, 32 e i pochi del numero del blocco)."""
    if not 1 <= len(dati) <= 75:
        raise ValueError("spinta fuori misura")
    return bytes([len(dati)]) + dati


def _swap_numero_script(n: int) -> bytes:
    """Un numero nello script come lo scrive btc-signer: OP_0, OP_1..16,
    oppure la spinta del numero minimo in little-endian col segno."""
    n = int(n)
    if n == 0:
        return b"\x00"
    if 1 <= n <= 16:
        return bytes([0x50 + n])
    if n < 0:
        raise ValueError("numero negativo nello script")
    b = n.to_bytes((n.bit_length() + 7) // 8, "little")
    if b[-1] & 0x80:
        b += b"\x00"
    return _swap_spinta(b)


def swap_albero_reverse(impronta: bytes, pub_ritiro: bytes,
                        pub_rimborso: bytes, scadenza: int) -> dict:
    """L'ALBERO DI UNO SWAP REVERSE, come lo serializza boltz-core 5.0.0
    (`reverseSwapTree` + `serializeSwapTree`): due foglie, e l'esadecimale
    dello script di ognuna.
      ritiro:   SIZE 32 EQUALVERIFY HASH160 <ripemd160(impronta)>
                EQUALVERIFY <x della chiave di ritiro> CHECKSIG
      rimborso: <x della chiave del fornitore> CHECKSIGVERIFY <scadenza>
                CHECKLOCKTIMEVERIFY
    Chi ritira (noi) mostra il segreto; il fornitore si riprende i
    bitcoin solo dopo il blocco `scadenza`."""
    from embit.hashes import ripemd160
    impronta, pub_ritiro, pub_rimborso = (bytes(impronta), bytes(pub_ritiro),
                                          bytes(pub_rimborso))
    if len(impronta) != 32:
        raise ValueError("impronta della lunghezza sbagliata")
    _swap_ec_punto(pub_ritiro)
    _swap_ec_punto(pub_rimborso)
    if not 0 < int(scadenza) < 500_000_000:
        raise ValueError("scadenza fuori misura")
    ritiro = (b"\x82" + _swap_numero_script(32) + b"\x88" + b"\xa9"
              + _swap_spinta(ripemd160(impronta)) + b"\x88"
              + _swap_spinta(pub_ritiro[1:]) + b"\xac")
    rimborso = (_swap_spinta(pub_rimborso[1:]) + b"\xad"
                + _swap_numero_script(scadenza) + b"\xb1")
    return {"claimLeaf": {"version": SWAP_FOGLIA_VERSIONE,
                          "output": ritiro.hex()},
            "refundLeaf": {"version": SWAP_FOGLIA_VERSIONE,
                           "output": rimborso.hex()}}


def _swap_radice_albero(albero: dict) -> bytes:
    """La radice taproot dell'albero a due foglie (BIP-341): TapLeaf di
    ognuna, poi TapBranch coi due hash in ordine."""
    foglie = []
    for nome in ("claimLeaf", "refundLeaf"):
        script = bytes.fromhex(albero[nome]["output"])
        if len(script) >= 0xfd:
            raise ValueError("foglia troppo lunga")
        foglie.append(_swap_etichettato(
            "TapLeaf", bytes([int(albero[nome]["version"])]),
            bytes([len(script)]), script))
    return _swap_etichettato("TapBranch", *sorted(foglie))


def swap_chiave_musig(pubbliche: list):
    """LA CHIAVE MUSIG2 DI PIU' CHIAVI (BIP-327, KeyAgg), nell'ordine
    dato e SENZA riordinarle — come `Musig.create` di boltz-core, che le
    prende cosi' come arrivano (la chiave del fornitore PER PRIMA). Torna
    il punto."""
    if len(pubbliche) < 2:
        raise ValueError("servono almeno due chiavi")
    pubbliche = [bytes(k) for k in pubbliche]
    punti = [_swap_ec_punto(k) for k in pubbliche]
    if len(set(pubbliche)) != len(pubbliche):
        raise ValueError("chiavi doppie")
    seconda = next((k for k in pubbliche[1:] if k != pubbliche[0]), None)
    lista = _swap_etichettato("KeyAgg list", *pubbliche)
    somma = None
    for k, punto in zip(pubbliche, punti):
        a = 1 if k == seconda else int.from_bytes(
            _swap_etichettato("KeyAgg coefficient", lista, k), "big") % _SWAP_EC_N
        somma = _swap_ec_somma(somma, _swap_ec_per(punto, a))
    if somma is None:
        raise ValueError("la somma delle chiavi e' all'infinito")
    return somma


def swap_programma_lockup(pub_fornitore: bytes, pub_nostra: bytes,
                          albero: dict) -> bytes:
    """I 32 byte dell'indirizzo dove il fornitore deve bloccare i
    bitcoin: la chiave MuSig a due (la sua PER PRIMA, poi la nostra)
    ritoccata con la radice dell'albero (BIP-341, TapTweak sulla x)."""
    return _swap_ritocco(pub_fornitore, pub_nostra, albero)[1][0].to_bytes(32, "big")


def swap_auto_chiavi(parole: str, indice: int) -> dict:
    """LE CHIAVI DELLO SWAP NUMERO `indice` (lo schema di SATS Routing,
    come `swapChiavi` del telefono): la privata in m/44/0/0/0/indice
    dalle dodici parole, la pubblica compressa, il segreto della fattura
    (sha256 della privata) e la sua impronta (sha256 del segreto)."""
    from embit import bip32, bip39
    indice = int(indice)
    if not 0 <= indice < 2 ** 31:
        raise ValueError("indice fuori misura")
    k = bip32.HDKey.from_seed(bip39.mnemonic_to_seed(
        str(parole or "").strip())).derive(f"m/44/0/0/0/{indice}")
    privata = k.key.secret
    segreto = hashlib.sha256(privata).digest()
    return {"privata": privata, "pubblica": k.key.get_public_key().sec(),
            "segreto": segreto, "impronta": hashlib.sha256(segreto).digest()}


def swap_auto_xpub(parole: str) -> str:
    """La xpub della RADICE delle parole, quella che la pagina «Rescue»
    di SATS Routing manda al recupero (come `swapXpub` del telefono)."""
    from embit import bip32, bip39
    return bip32.HDKey.from_seed(bip39.mnemonic_to_seed(
        str(parole or "").strip())).to_public().to_string()


def swap_auto_verifica(r, chiavi: dict, attesa: dict, rete: str):
    """LA VERIFICA DELLA RISPOSTA DEL FORNITORE, prima di fidarsi: None =
    tutto torna, altrimenti la ragione, con gli STESSI nomi di
    `swapVerifica` del telefono (una prova le mette a confronto):
      risposta   non e' una risposta di swap
      fattura    la fattura non si legge
      importo    la fattura non chiede quel che il preventivo dice
      impronta   la fattura non e' legata al NOSTRO segreto (il fornitore
                 incasserebbe senza che noi ritiriamo)
      albero     l'albero non e' quello che rifacciamo coi nostri pezzi
      indirizzo  l'indirizzo del lockup non e' quello di quell'albero e
                 delle due chiavi
      meno       on-chain blocca meno del preventivo
    `attesa` = {"sats": la fattura, "onchainMin": il minimo on-chain}."""
    if not isinstance(r, dict) or not isinstance(r.get("invoice"), str):
        return "risposta"
    letta = leggi_bolt11(r["invoice"], con_hash=True)
    sats = importo_bolt11(r["invoice"])
    if not letta or sats is None:
        return "fattura"
    if sats != int(attesa["sats"]):
        return "importo"
    if not letta.get("hash") or letta["hash"] != chiavi["impronta"].hex():
        return "impronta"
    try:
        scadenza = int(r.get("timeoutBlockHeight"))
        loro = bytes.fromhex(str(r.get("refundPublicKey") or ""))
        atteso = swap_albero_reverse(chiavi["impronta"], chiavi["pubblica"],
                                     loro, scadenza)
        albero = r.get("swapTree")
        if isinstance(albero, str):
            albero = json.loads(albero)
        # un albero con una terza foglia (il «covenant» di Liquid) non e'
        # il nostro: le chiavi devono essere ESATTAMENTE le due
        if not isinstance(albero, dict) or set(albero) != {"claimLeaf",
                                                          "refundLeaf"}:
            return "albero"
        for nome in ("claimLeaf", "refundLeaf"):
            f = albero[nome]
            if (int(f["version"]) != atteso[nome]["version"]
                    or str(f["output"]).lower() != atteso[nome]["output"]):
                return "albero"
    except (TypeError, ValueError, KeyError, AttributeError):
        return "albero"
    try:
        programma = swap_programma_lockup(loro, chiavi["pubblica"], atteso)
    except ValueError:
        return "indirizzo"
    if _swap_programma_p2tr(r.get("lockupAddress"), rete) != programma:
        return "indirizzo"
    try:
        if not int(r.get("onchainAmount")) >= int(attesa["onchainMin"]):
            return "meno"
    except (TypeError, ValueError):
        return "meno"
    return None


# LE PAROLE DELLO SWAP AUTOMATICO STANNO SUL VPS, come la chiave on-chain
# (`onchain_crea_chiave_barattolo`): nascono con un gesto di un admin dal
# pannello, una volta sola, con `os.urandom`; il file e' 600 in
# `chiavi/`, e `backup-fuori.sh` porta via la cartella intera. Le parole
# non escono MAI dal server: ne' nella risposta, ne' nel journal, ne' nel
# pannello (che vede impronta, xpub di radice e se il backup le ha).
# PERCHE' NON LE STESSE PAROLE DELLA CHIAVE ON-CHAIN: quella firma le
# dispute del 2-di-3, queste ritirano gli swap; un incidente su una non
# deve aprire l'altra, e il recupero di SATS Routing vuole la xpub di
# radice delle SUE parole — darla vorrebbe dire dare la radice del 2-di-3.
def _swap_auto_file() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(DB)), "chiavi",
                        "swap-barattolo.json")


def _swap_auto_parole_vps():
    """Il file delle parole letto, o None se non e' nato. Un file che
    c'e' e non si legge, o che e' nato su un'altra rete, ALZA: tirare
    dritto vorrebbe dire far nascere swap che non sappiamo ritirare."""
    f = _swap_auto_file()
    if not os.path.exists(f):
        return None
    with open(f, encoding="utf-8") as h:
        d = json.load(h)
    if not d.get("parole") or not d.get("xpub"):
        raise ValueError("il file delle parole dello swap e' monco")
    if d.get("rete") != swap_rete():
        raise ValueError(f"le parole dello swap sono nate su {d.get('rete')}, "
                         f"ma la rete dello swap adesso e' {swap_rete()}")
    return d


def swap_auto_crea_parole(admin_id: int) -> dict:
    """Il gesto dell'admin: dodici parole nuove, il file. Una volta sola
    (FileExistsError). Torna solo la parte pubblica."""
    from embit import bip32, bip39
    f = _swap_auto_file()
    if os.path.exists(f):
        raise FileExistsError(f)
    parole = bip39.mnemonic_from_bytes(os.urandom(16))
    radice = bip32.HDKey.from_seed(bip39.mnemonic_to_seed(parole))
    d = {"parole": parole, "rete": swap_rete(),
         "xpub": radice.to_public().to_string(),
         "impronta": radice.my_fingerprint.hex(),
         "creata_il": int(time.time()), "creata_da": int(admin_id)}
    os.makedirs(os.path.dirname(f), mode=0o700, exist_ok=True)
    # O_EXCL: due admin che premono insieme non fanno due file
    fd = os.open(f, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as h:
        json.dump(d, h)
    return {k: d[k] for k in ("xpub", "impronta", "creata_il", "rete")}


def swap_auto_stato_parole() -> dict:
    """Quel che il pannello mostra delle parole dello swap, mai le parole:
    nate o no, l'impronta, la xpub di radice (per la pagina «Rescue»), e
    se l'ultimo backup fuori sede e' venuto dopo la nascita."""
    try:
        d = _swap_auto_parole_vps()
    except Exception as e:
        return {"dove": "rotta", "motivo": str(e)[:200]}
    if not d:
        return {"dove": "nessuna", "rete": swap_rete()}
    ultimo = 0
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(DB)), "backup",
                               "fuori", ".ultimo-successo")) as h:
            ultimo = int(h.read().strip() or 0)
    except Exception:
        pass
    nata = int(d.get("creata_il") or 0)
    return {"dove": "vps", "xpub": d["xpub"], "impronta": d.get("impronta", ""),
            "rete": d["rete"], "creata_il": nata, "file": _swap_auto_file(),
            "backup_ultimo": ultimo, "nel_backup": ultimo >= nata > 0}


# OGNI SWAP HA LA SUA CHIAVE: l'indice e' una riga di `swap_auto`, scritta
# PRIMA di bussare al fornitore e mai riusata (anche se la nascita va
# storta: la chiave pubblica e l'impronta possono essere gia' uscite).
# La riga tiene le sole parti PUBBLICHE della risposta: le private si
# rifanno dalle parole e dall'indice quando servono (il ritiro, tappa 2).
SWAP_AUTO_CHIESTO = "chiesto"     # indice preso, il fornitore non ha risposto
SWAP_AUTO_NATO = "nato"           # risposta verificata: lo swap c'e'
SWAP_AUTO_MENTE = "mente"         # la risposta non torna: non si paga mai
SWAP_AUTO_GIU = "giu"             # il fornitore non risponde o dice di no


def _swap_auto_prepara(con):
    con.execute("""CREATE TABLE IF NOT EXISTS swap_auto(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        indice INTEGER NOT NULL UNIQUE,
        ordine_id INTEGER NOT NULL,
        fornitore TEXT NOT NULL,
        swap_id TEXT DEFAULT '',
        stato TEXT DEFAULT 'chiesto',
        perche TEXT DEFAULT '',
        sats INTEGER DEFAULT 0,
        onchain_min INTEGER DEFAULT 0,
        risposta TEXT DEFAULT '',
        ritiro_txid TEXT DEFAULT '',
        destinazione TEXT DEFAULT '',
        ricevi INTEGER DEFAULT 0,
        dest_valore TEXT DEFAULT '',
        dest_indice INTEGER DEFAULT -1,
        creato INTEGER DEFAULT 0,
        aggiornato INTEGER DEFAULT 0)""")
    # (6 nov 2026, ritiro a scalini) il ritiro ha la sua prima conferma:
    # da li' nessun rilancio lo guarda piu'
    if "confermato" not in {x[1] for x in con.execute(
            "PRAGMA table_info(swap_auto)")}:
        con.execute("ALTER TABLE swap_auto ADD COLUMN confermato "
                    "INTEGER DEFAULT 0")


def swap_auto_prenota_indice(con, ordine_id: int, fornitore: str,
                             sats: int, onchain_min: int) -> int:
    """Il prossimo indice libero, preso in UNA istruzione (due richieste
    insieme non prendono lo stesso: lo vieta anche l'UNIQUE).

    IL PAVIMENTO FUORI DAL DATABASE (14 nov 2026, cantiere
    audit-pagamenti-2, dal secondo audit di sicurezza): l'UNIQUE vale
    dentro UN file di database, mentre le parole stanno in chiavi/. Un
    `satmarket.db` rimesso da una copia vecchia (un ripristino sul posto,
    con chiavi/ intatta) faceva ripartire il contatore da un indice gia'
    usato: stesso indice = stessa chiave = stesso segreto, gia' rivelato.
    Ora l'ultimo indice preso si scrive anche accanto alle parole
    (`swap-barattolo-indice.json`, PRIMA che il fornitore lo veda) e il
    prossimo e' il piu' alto fra i due. Un file del pavimento che c'e' e
    non si legge ALZA, come quello delle parole: meglio nessuno swap che
    un segreto riusato."""
    _swap_auto_prepara(con)
    fp = _swap_auto_file()[:-len(".json")] + "-indice.json"
    pavimento = -1
    if os.path.exists(fp):
        with open(fp, encoding="utf-8") as h:
            pavimento = int(json.load(h)["ultimo"])
    adesso = int(time.time())
    cur = con.execute(
        "INSERT INTO swap_auto(indice, ordine_id, fornitore, sats, "
        "onchain_min, creato, aggiornato) SELECT MAX(COALESCE(MAX(indice), "
        "-1) + 1, ?), ?, ?, ?, ?, ?, ? FROM swap_auto",
        (pavimento + 1, int(ordine_id), str(fornitore), int(sats),
         int(onchain_min), adesso, adesso))
    con.commit()
    indice = int(con.execute("SELECT indice FROM swap_auto WHERE id=?",
                             (cur.lastrowid,)).fetchone()[0])
    # scritto e sincronizzato prima di tornare: il fornitore lo vede solo
    # dopo. Un crash fra la commit e qui non fa danni: l'indice sta nel
    # database, e il MAX lo ritrova.
    os.makedirs(os.path.dirname(fp), mode=0o700, exist_ok=True)
    tmp = fp + ".tmp"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as h:
        json.dump({"ultimo": max(indice, pavimento)}, h)
        h.flush()
        os.fsync(h.fileno())
    os.replace(tmp, fp)
    return indice


# i soli campi della risposta che il ritiro (tappa 2) vorra' rileggere
SWAP_AUTO_CAMPI = ("id", "invoice", "lockupAddress", "refundPublicKey",
                   "swapTree", "timeoutBlockHeight", "onchainAmount")


async def swap_auto_crea(fornitore: dict, ordine_id: int,
                         preventivo: dict) -> dict:
    """LA NASCITA DI UNO SWAP AUTOMATICO: l'indice, le chiavi, la
    richiesta al fornitore col codice partner, la VERIFICA. Non paga
    niente: torna {"stato", "perche", "indice", "swap_id", "fattura",
    "lockup", "onchain"} e la fattura si paga solo se `stato` e' «nato»
    (tappa 3). `preventivo` = quello di `preventivo_swap` (fattura, hash,
    onchain). ValueError se le parole non ci sono o non si leggono."""
    d = _swap_auto_parole_vps()
    if not d:
        raise ValueError("le parole dello swap automatico non sono ancora "
                         "nate: un admin le crea dal pannello")
    sats, minimo = int(preventivo["fattura"]), int(preventivo["onchain"])
    con = db()
    try:
        indice = swap_auto_prenota_indice(con, ordine_id, fornitore["id"],
                                          sats, minimo)
    finally:
        con.close()
    chiavi = swap_auto_chiavi(d["parole"], indice)
    corpo = {"from": "BTC", "to": "BTC", "invoiceAmount": sats,
             "preimageHash": chiavi["impronta"].hex(),
             "claimPublicKey": chiavi["pubblica"].hex(),
             "pairHash": str(preventivo.get("hash") or "")}
    if fornitore.get("referral"):
        corpo["referralId"] = fornitore["referral"]
    base = str(fornitore.get("api") or "").rstrip("/")
    r, perche = None, ""
    if swap_lettura_simulata(base):
        stato, perche = SWAP_AUTO_GIU, "simulato"
    else:
        try:
            async with httpx.AsyncClient(timeout=15) as c:
                h = await c.post(f"{base}/v2/swap/reverse", json=corpo)
            if h.status_code not in (200, 201):
                stato, perche = SWAP_AUTO_GIU, f"http {h.status_code}"
            else:
                r = h.json()
                stato = SWAP_AUTO_NATO
        except Exception as e:
            stato, perche = SWAP_AUTO_GIU, type(e).__name__
    if stato == SWAP_AUTO_NATO:
        perche = swap_auto_verifica(r, chiavi, {"sats": sats,
                                                "onchainMin": minimo},
                                    fornitore.get("rete") or swap_rete()) or ""
        if not perche and not _SWAP_ID_FORMA.match(str(r.get("id") or "")):
            perche = "risposta"
        if perche:
            stato = SWAP_AUTO_MENTE
    pubblica = ({k: r.get(k) for k in SWAP_AUTO_CAMPI}
                if isinstance(r, dict) and stato == SWAP_AUTO_NATO else {})
    con = db()
    try:
        con.execute("UPDATE swap_auto SET stato=?, perche=?, swap_id=?, "
                    "risposta=?, aggiornato=? WHERE indice=?",
                    (stato, perche[:80], str(pubblica.get("id") or ""),
                     json.dumps(pubblica) if pubblica else "",
                     int(time.time()), indice))
        con.commit()
    finally:
        con.close()
    if stato != SWAP_AUTO_NATO:
        print(f"⚠️ Swap automatico dell'ordine {int(ordine_id)} (indice "
              f"{indice}): {stato} ({perche})", flush=True)
    return {"stato": stato, "perche": perche, "indice": indice,
            "swap_id": str(pubblica.get("id") or ""),
            "fattura": pubblica.get("invoice") or "",
            "lockup": pubblica.get("lockupAddress") or "",
            "onchain": int(pubblica.get("onchainAmount") or 0),
            "scade_blocco": int(pubblica.get("timeoutBlockHeight") or 0),
            "impronta": chiavi["impronta"].hex() if pubblica else ""}


@app.get("/api/admin/swap/parole")
async def swap_auto_parole_vedi(x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: com'e' fatta la chiave dello swap automatico (mai le
    parole)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    return swap_auto_stato_parole()


