# --- TAPPA 2: IL RITIRO DAL SERVER (2 nov 2026, cantiere swap-auto) ---
# Quando il fornitore ha bloccato i bitcoin, il server li porta
# all'indirizzo di chi vende. DALLO SCRIPT, con la sola chiave nostra e
# il segreto: il permesso del fornitore non serve, e la firma MuSig2 a
# due (il ritiro «cooperativo», un po' piu' leggero) embit non la sa
# fare — e una seconda libreria di firme a piu' mani sul VPS non vale i
# pochi vbyte. E' la strada di riserva del telefono (`swapRitiro` con
# `cooperativo = false`), e il cartone la verifica col bundle.
# I CONTROLLI PRIMA DEL SEGRETO, gli stessi del telefono (cantiere
# swap-lockup): il segreto esce di qui nella transazione, e un fornitore
# che mente se lo farebbe dare senza aver bloccato i bitcoin. Quindi
# (1) il lockup si legge dalla RETE, non dal fornitore, e la rete deve
# dire proprio quell'id; (2) l'uscita e' ESATTAMENTE il p2tr della
# chiave MuSig con l'albero; (3) porta non meno di quanto promesso alla
# nascita; (4) la fee del ritiro (lockup - ricevi) e' positiva.
_SWAP_RETI_EMBIT = {"bitcoin": "main", "testnet": "test", "regtest": "regtest"}


def _swap_ritocco(pub_fornitore: bytes, pub_nostra: bytes, albero: dict):
    """La chiave interna (x, 32 byte) e il punto dell'uscita ritoccata:
    servono al ritiro dallo script (il blocco di controllo vuole la x
    interna e la parita' dell'uscita)."""
    interna = swap_chiave_musig([pub_fornitore, pub_nostra])
    if interna[1] & 1:
        interna = (interna[0], _SWAP_EC_P - interna[1])
    x = interna[0].to_bytes(32, "big")
    t = int.from_bytes(_swap_etichettato("TapTweak", x,
                                         _swap_radice_albero(albero)), "big")
    if t >= _SWAP_EC_N:
        raise ValueError("ritocco fuori misura")
    q = _swap_ec_somma(interna, _swap_ec_per(_SWAP_EC_G, t))
    if q is None:
        raise ValueError("ritocco all'infinito")
    return x, q


def _swap_script_destinazione(indirizzo: str, rete: str) -> bytes | None:
    """Lo script di un indirizzo bitcoin DI QUESTA RETE (segwit v0/v1, o
    i vecchi 1… e 3…), o None. Il checksum lo controlla embit; la rete
    la controlliamo noi, che embit non la guarda."""
    from embit import script as _esc
    from embit.networks import NETWORKS
    s = str(indirizzo or "").strip()
    rete_e = NETWORKS.get(_SWAP_RETI_EMBIT.get(rete, "main"))
    if not s or not rete_e:
        return None
    try:
        script = _esc.address_to_scriptpubkey(s).data
    except Exception:
        return None
    if s.lower().startswith(rete_e["bech32"] + "1"):
        return script
    try:
        from embit import base58
        prefisso = base58.decode_check(s)[:1]
    except Exception:
        return None
    return script if prefisso in (rete_e["p2pkh"], rete_e["p2sh"]) else None


def swap_auto_tx_ritiro(rec: dict, chiavi: dict, lockup_hex: str,
                        destinazione: str, ricevi: int, rete: str) -> dict:
    """LA TRANSAZIONE DEL RITIRO, dallo script: spende l'uscita del lockup
    verso `destinazione`, con un'uscita sola da `ricevi` sats (la
    differenza e' la fee per i minatori, come `createAdjustedClaim`).
    `rec` = le parti pubbliche della nascita (refundPublicKey, swapTree,
    onchainAmount). Torna {"hex", "txid", "sats", "fee"}; ValueError col
    perche' se un controllo non torna — e allora il segreto non esce."""
    from embit.ec import PrivateKey
    from embit.script import Script, Witness
    from embit.transaction import (SIGHASH, Transaction, TransactionInput,
                                   TransactionOutput)
    loro = bytes.fromhex(str(rec.get("refundPublicKey") or ""))
    albero = rec.get("swapTree")
    if isinstance(albero, str):
        albero = json.loads(albero)
    x_interna, q = _swap_ritocco(loro, chiavi["pubblica"], albero)
    atteso = b"\x51\x20" + q[0].to_bytes(32, "big")
    lockup = Transaction.parse(bytes.fromhex(str(lockup_hex or "")))
    uscita = next((i for i, o in enumerate(lockup.vout)
                   if o.script_pubkey.data == atteso), None)
    if uscita is None:
        raise ValueError("nel lockup non c'e' il nostro swap")
    valore = int(lockup.vout[uscita].value)
    if valore < int(rec.get("onchainAmount") or 0):
        raise ValueError("il lockup porta meno di quanto promesso")
    ricevi = int(ricevi)
    if not 546 <= ricevi < valore:
        raise ValueError("il lockup non copre quel che il preventivo promette")
    script_dest = _swap_script_destinazione(destinazione, rete)
    if not script_dest:
        raise ValueError("indirizzo di destinazione non valido")
    foglia = bytes.fromhex(albero["claimLeaf"]["output"])
    tx = Transaction(version=2, locktime=0,
                     vin=[TransactionInput(lockup.txid(), uscita,
                                           sequence=0xfffffffd)],
                     vout=[TransactionOutput(ricevi, Script(script_dest))])
    impronta = tx.sighash_taproot(0, [Script(atteso)], [valore],
                                  sighash=SIGHASH.DEFAULT, ext_flag=1,
                                  script=Script(foglia),
                                  leaf_version=SWAP_FOGLIA_VERSIONE)
    firma = PrivateKey(chiavi["privata"]).schnorr_sign(impronta).serialize()
    rimborso = bytes.fromhex(albero["refundLeaf"]["output"])
    fratello = _swap_etichettato("TapLeaf",
                                 bytes([int(albero["refundLeaf"]["version"])]),
                                 bytes([len(rimborso)]), rimborso)
    controllo = (bytes([SWAP_FOGLIA_VERSIONE | (q[1] & 1)]) + x_interna
                 + fratello)
    tx.vin[0].witness = Witness([firma, chiavi["segreto"], foglia, controllo])
    return {"hex": tx.serialize().hex(), "txid": tx.txid().hex(),
            "sats": ricevi, "fee": valore - ricevi, "valore": valore,
            "vsize": _swap_tx_vsize(tx)}


def _swap_tx_vsize(tx) -> int:
    """I vbyte di una transazione di embit: il peso e' tre volte la parte
    senza testimoni piu' la transazione intera, diviso quattro per eccesso."""
    from embit.script import Witness
    from embit.transaction import Transaction
    intera = tx.serialize()
    nuda = Transaction.parse(intera)
    for i in nuda.vin:
        i.witness = Witness([])
    return (len(nuda.serialize()) * 3 + len(intera) + 3) // 4


SWAP_AUTO_RITIRATO = "ritirato"   # il ritiro e' partito ed e' stato preso


async def _swap_auto_trasmetti(fornitore: dict, hex_: str) -> bool:
    """LA TRASMISSIONE DEL RITIRO, su due strade come il telefono: la rete
    (`POST /tx` del mempool, testo) e il fornitore. Basta che una la
    prenda. In collaudo nessuna delle due esce dal computer."""
    prese = False
    strade = ((str(fornitore.get("mempool") or "").rstrip("/"), "/tx", hex_,
               None),
              (str(fornitore.get("api") or "").rstrip("/"),
               "/v2/chain/BTC/transaction", None, {"hex": hex_}))
    for base, percorso, testo, corpo in strade:
        if not base or swap_lettura_simulata(base):
            continue
        try:
            async with httpx.AsyncClient(timeout=15) as c:
                h = await (c.post(base + percorso, content=testo)
                           if corpo is None
                           else c.post(base + percorso, json=corpo))
            prese = prese or h.status_code in (200, 201)
        except Exception as e:
            print(f"⚠️ Swap automatico: la trasmissione su {base} non va "
                  f"({type(e).__name__})", flush=True)
    return prese


# LA COMMISSIONE DEL RITIRO A SCALINI (6 nov 2026, dalla prova di Andrea:
# il primo ritiro vero pagava 123 sats, ~1 sat/vB, la stima che SATS
# Routing dava al preventivo del mattino; il pomeriggio la coda era piena
# e la transazione e' rimasta ferma per ore, con la scadenza dello swap a
# 122 blocchi). Dopo il «Conferma» i bitcoin vanno ritirati PRIMA della
# scadenza (`timeoutBlockHeight`), o il fornitore se li riprende col suo
# rimborso: «non accetto» qui non esiste, si sceglie solo quanto pagare e
# quanto aspettare. Andrea: «chi riceve puo' scegliere se accettare se
# diventa troppo costosa?» — si', ma PRIMA, alla carta del «Conferma»;
# dopo, il server paga il meno possibile che arrivi in tempo:
#   1. il ritiro usa la tariffa per entrare in circa un'ora (`hourFee`), e
#      mai meno di quel che il preventivo aveva messo da parte;
#   2. fermo da due ore, o a meno di SWAP_AUTO_BLOCCHI_MEZZORA blocchi
#      dalla scadenza: la tariffa da mezz'ora (`halfHourFee`);
#   3. a meno di SWAP_AUTO_BLOCCHI_URGENTE blocchi: la piu' veloce.
# Il rilancio SOSTITUISCE la transazione (e' gia' RBF: sequenza
# 0xfffffffd), pagando almeno un sat/vB in piu' di prima, come chiede la
# rete. Il di piu' esce da `ricevi`: i costi del cambio sono di chi vende
# (decisione del 2 nov). Mai sotto la polvere.
SWAP_AUTO_TARIFFA_MAX = 500           # sat/vB: oltre e' una risposta storta
SWAP_AUTO_RILANCIO_DOPO = 20 * 60     # secondi prima di guardare un ritiro
SWAP_AUTO_RILANCIO_OGNI = 10 * 60     # ...e poi una volta ogni dieci minuti
SWAP_AUTO_FERMO_A_LUNGO = 2 * 3600    # fermo da due ore: lo scalino 2
SWAP_AUTO_BLOCCHI_MEZZORA = 72        # circa mezza giornata
SWAP_AUTO_BLOCCHI_URGENTE = 36        # circa sei ore
_SWAP_AUTO_GUARDATO = {}              # indice -> quando l'ho guardato

# IL SEGRETO ESCE SOLO SU UN LOCKUP CONFERMATO, E MAI A RIDOSSO DELLA
# SCADENZA (14 nov 2026, cantiere audit-swap-conferma, dal primo audit di
# sicurezza; scelta di Andrea sulla card: «Aspetta una conferma»). Il
# ritiro porta dentro il segreto, e chi ha il segreto incassa la fattura
# che abbiamo pagato coi sats di chi vende. Fino a ieri bastava che il
# lockup si VEDESSE in rete: ma una transazione in coda si puo' ancora
# sostituire, e un fornitore disonesto poteva prendersi il segreto e
# riprendersi i bitcoin. E a scadenza vicina (o passata) il suo rimborso
# puo' arrivare in un blocco prima del nostro ritiro. Adesso, al PRIMO
# ritiro (finche' la riga non ha un `ritiro_txid`, cioe' finche' il
# segreto non e' mai uscito):
#   1. il lockup deve stare in un blocco (`status.confirmed` del mempool,
#      lo stesso campo che legge l'on-chain del mercatino);
#   2. alla scadenza devono restare almeno SWAP_AUTO_MARGINE_RITIRO
#      blocchi, e se la rete non dice l'altezza si aspetta.
# Senza una delle due il segreto resta a casa: la fattura non la incassa
# nessuno, alla scadenza il fornitore la annulla, i sats tornano e chi
# vende puo' rifare il cambio (la strada del cambio fallito, che c'era
# gia'). Dopo il primo ritiro NIENTE di tutto questo: il segreto e' gia'
# fuori, e li' vale la regola del 6 nov, o si ritira in tempo o si perde.
SWAP_AUTO_MARGINE_RITIRO = 12         # blocchi: un paio d'ore
SWAP_AUTO_SENZA_CONFERMA = "lockup senza conferma"
SWAP_AUTO_TARDI = "scadenza troppo vicina"
_SWAP_AUTO_DETTO_TARDI = set()        # indici gia' detti agli admin


def swap_auto_scalino(restano, fermo_da: int) -> str:
    """PURA: la tariffa di mempool da usare. `restano` = blocchi alla
    scadenza (None = la rete non l'ha detto), `fermo_da` = secondi da
    quando il ritiro e' partito (0 al primo ritiro)."""
    if restano is not None and restano < SWAP_AUTO_BLOCCHI_URGENTE:
        return "fastestFee"
    if (restano is not None and restano < SWAP_AUTO_BLOCCHI_MEZZORA) \
            or fermo_da >= SWAP_AUTO_FERMO_A_LUNGO:
        return "halfHourFee"
    return "hourFee"


def swap_auto_ricevi_con_tariffa(valore: int, ricevi: int, vsize: int,
                                 sat_vb: float, minimo_fee: int = 0) -> int:
    """PURA: quanto arriva a chi vende perche' il ritiro paghi almeno
    `sat_vb` (e almeno `minimo_fee` sats). Mai piu' di `ricevi` (la
    promessa del preventivo), mai sotto la polvere: 0 = non si puo'."""
    serve = max(int(math.ceil(float(sat_vb) * int(vsize))), int(minimo_fee))
    nuovo = min(int(ricevi), int(valore) - serve)
    return nuovo if nuovo >= 546 else 0


async def _swap_auto_tariffa(base: str, scalino: str) -> float:
    """sat/vB dello scalino dal mempool del fornitore; 0 = non risponde."""
    try:
        d = json.loads(await _swap_mempool_leggi(base, "/v1/fees/recommended")
                       or "{}")
        v = float(d.get(scalino) or 0) if isinstance(d, dict) else 0
    except (ValueError, TypeError):
        v = 0
    return min(max(v, 1.0), SWAP_AUTO_TARIFFA_MAX) if v > 0 else 0.0


async def _swap_auto_restano(base: str, rec: dict):
    """Blocchi alla scadenza dello swap, o None se la rete tace."""
    try:
        cima = int(str(await _swap_mempool_leggi(base, "/blocks/tip/height")
                       or "").strip())
        return int(rec.get("timeoutBlockHeight")) - cima
    except (ValueError, TypeError):
        return None


async def swap_auto_ritira(indice: int, destinazione: str,
                           ricevi: int) -> dict:
    """IL RITIRO DI UNO SWAP AUTOMATICO NATO: il lockup letto dalla rete
    (prima l'indirizzo, poi i byte; l'id deve tornare), la transazione
    dallo script, l'id scritto nella riga PRIMA di trasmettere (se la
    risposta si perde, il giro dopo lo riconosce), la trasmissione.
    Torna {"stato", "txid", "perche"}: «ritirato», oppure «aspetta» (il
    lockup non c'e' ancora, o la rete non risponde: si riprova) o «no»
    (un controllo non torna: niente segreto a nessuno).
    (14 nov 2026) Al PRIMO ritiro il lockup deve essere CONFERMATO e la
    scadenza lontana almeno SWAP_AUTO_MARGINE_RITIRO blocchi: vedi il
    commento sopra la costante."""
    con = db()
    try:
        _swap_auto_prepara(con)
        r = con.execute("SELECT * FROM swap_auto WHERE indice=?",
                        (int(indice),)).fetchone()
    finally:
        con.close()
    if not r or r["stato"] not in (SWAP_AUTO_NATO, SWAP_AUTO_RITIRATO):
        return {"stato": "no", "txid": "", "perche": "swap non nato"}
    rec = json.loads(r["risposta"] or "{}")
    fornitore = swap_fornitore(r["fornitore"]) or {}
    rete = fornitore.get("rete") or swap_rete()
    base = str(fornitore.get("mempool") or "").rstrip("/")
    # gia' ritirato: la rete conosce la nostra transazione? (se la
    # risposta della trasmissione si e' persa, il giro dopo la ritrova)
    if r["ritiro_txid"]:
        try:
            gia = json.loads(await _swap_mempool_leggi(
                base, f"/tx/{r['ritiro_txid']}") or "{}")
        except ValueError:
            gia = {}
        if isinstance(gia, dict) and gia.get("txid") == r["ritiro_txid"]:
            if r["stato"] != SWAP_AUTO_RITIRATO:
                con = db()
                try:
                    con.execute("UPDATE swap_auto SET stato=?, aggiornato=? "
                                "WHERE indice=?", (SWAP_AUTO_RITIRATO,
                                                   int(time.time()),
                                                   int(indice)))
                    con.commit()
                finally:
                    con.close()
            return {"stato": SWAP_AUTO_RITIRATO, "txid": r["ritiro_txid"],
                    "perche": ""}
    # (14 nov 2026) il segreto non e' mai uscito finche' la riga non ha
    # un ritiro scritto: solo li' valgono la conferma e il margine
    primo = not r["ritiro_txid"]
    testo = await _swap_mempool_leggi(
        base, f"/address/{rec.get('lockupAddress', '')}/utxo")
    txid = ""
    in_coda = False
    try:
        uscite = [u for u in json.loads(testo or "[]")
                  if isinstance(u, dict)
                  and re.fullmatch(r"[0-9a-f]{64}", str(u.get("txid") or ""))]
        if primo:
            ferme = [u for u in uscite if isinstance(u.get("status"), dict)
                     and u["status"].get("confirmed") is True]
            in_coda = len(ferme) < len(uscite)
            uscite = ferme
        piena = next((u for u in uscite if int(u.get("value") or 0)
                      >= int(rec.get("onchainAmount") or 0)), None)
        txid = str((piena or (uscite[0] if uscite else {})).get("txid") or "")
    except (ValueError, TypeError):
        txid = ""
    if not txid:
        return {"stato": "aspetta", "txid": "", "perche":
                SWAP_AUTO_SENZA_CONFERMA if in_coda else "lockup non visto"}
    if primo:
        restano = await _swap_auto_restano(base, rec)
        if restano is None:
            return {"stato": "aspetta", "txid": "", "perche": "la rete non "
                    "dice l'altezza"}
        if restano < SWAP_AUTO_MARGINE_RITIRO:
            print(f"⚠️ Swap automatico {int(indice)}: niente ritiro, alla "
                  f"scadenza restano {restano} blocchi (ne servono "
                  f"{SWAP_AUTO_MARGINE_RITIRO})", flush=True)
            return {"stato": "no", "txid": "", "perche": SWAP_AUTO_TARDI}
    lockup_hex = (await _swap_mempool_leggi(base, f"/tx/{txid}/hex") or "").strip()
    try:
        from embit.transaction import Transaction
        if Transaction.parse(bytes.fromhex(lockup_hex)).txid().hex() != txid:
            return {"stato": "no", "txid": "", "perche": "la rete risponde "
                    "con un altro lockup"}
    except Exception:
        return {"stato": "aspetta", "txid": "", "perche": "lockup illeggibile"}
    d = _swap_auto_parole_vps()
    if not d:
        return {"stato": "no", "txid": "", "perche": "parole assenti"}
    try:
        chiavi = swap_auto_chiavi(d["parole"], indice)
        t = swap_auto_tx_ritiro(rec, chiavi, lockup_hex, destinazione,
                                ricevi, rete)
        # (6 nov 2026) LO SCALINO 1: la coda di adesso, non la stima del
        # preventivo — se chiede di piu', il di piu' esce da `ricevi`
        sat_vb = await _swap_auto_tariffa(base, swap_auto_scalino(
            await _swap_auto_restano(base, rec), 0))
        if sat_vb:
            nuovo = swap_auto_ricevi_con_tariffa(t["valore"], ricevi,
                                                 t["vsize"], sat_vb)
            if nuovo and nuovo < int(ricevi):
                ricevi = nuovo
                t = swap_auto_tx_ritiro(rec, chiavi, lockup_hex,
                                        destinazione, ricevi, rete)
    except ValueError as e:
        print(f"⚠️ Swap automatico {int(indice)}: ritiro fermo ({e})",
              flush=True)
        return {"stato": "no", "txid": "", "perche": str(e)}
    con = db()
    try:
        con.execute("UPDATE swap_auto SET ritiro_txid=?, destinazione=?, "
                    "ricevi=?, aggiornato=? WHERE indice=?",
                    (t["txid"], str(destinazione), int(ricevi),
                     int(time.time()), int(indice)))
        con.commit()
    finally:
        con.close()
    if not await _swap_auto_trasmetti(fornitore, t["hex"]):
        return {"stato": "aspetta", "txid": t["txid"],
                "perche": "nessuna strada ha preso il ritiro"}
    con = db()
    try:
        con.execute("UPDATE swap_auto SET stato=?, aggiornato=? WHERE indice=?",
                    (SWAP_AUTO_RITIRATO, int(time.time()), int(indice)))
        con.commit()
    finally:
        con.close()
    return {"stato": SWAP_AUTO_RITIRATO, "txid": t["txid"], "perche": "",
            "sats": int(t["sats"])}


async def swap_auto_rilancia(indice: int) -> dict:
    """IL RILANCIO DI UN RITIRO FERMO (6 nov 2026, scalini 2 e 3): chi ha
    speso il lockup lo dice la rete (`/address/<lockup>/txs`). Speso e
    confermato: fatto, la riga non si guarda piu'. Speso ma fermo: se lo
    scalino di adesso chiede piu' di quel che paga, si rifa' la stessa
    transazione con meno sats in uscita (RBF) e si trasmette; la riga
    cambia SOLO se una strada l'ha presa (una risposta persa si
    ritrova al giro dopo: la firma e' la stessa, la transazione anche).
    Torna {"stato": «confermato» | «rilanciato» | «fermo» | «aspetta» |
    «no» | «altro», "txid", "sats", "prima", "perche"}.
    (14 nov 2026, cantiere audit-swap-conferma) «Confermato» vuol dire
    che e' confermato il NOSTRO ritiro: la spesa deve avere un'uscita
    sola, verso l'indirizzo di chi vende. Se in un blocco c'e' la spesa
    di un altro (il rimborso del fornitore, per dire) i bitcoin a chi
    vende NON sono arrivati: la riga prende `confermato=2`, non si
    guarda piu' (non c'e' piu' niente da rilanciare) e lo stato «altro»
    lo fa dire agli admin, una volta. Prima quella riga diceva «fatto»."""
    con = db()
    try:
        _swap_auto_prepara(con)
        r = con.execute("SELECT * FROM swap_auto WHERE indice=?",
                        (int(indice),)).fetchone()
    finally:
        con.close()
    vuoto = {"txid": "", "sats": 0, "prima": 0}
    if not r or r["stato"] != SWAP_AUTO_RITIRATO or not r["ritiro_txid"]:
        return dict(vuoto, stato="no", perche="niente ritiro da guardare")
    rec = json.loads(r["risposta"] or "{}")
    fornitore = swap_fornitore(r["fornitore"]) or {}
    rete = fornitore.get("rete") or swap_rete()
    base = str(fornitore.get("mempool") or "").rstrip("/")
    indirizzo = str(rec.get("lockupAddress") or "")
    try:
        txs = json.loads(await _swap_mempool_leggi(
            base, f"/address/{indirizzo}/txs") or "null")
    except ValueError:
        txs = None
    if not isinstance(txs, list):
        return dict(vuoto, stato="aspetta", perche="la rete non risponde")
    txs = [x for x in txs if isinstance(x, dict)]
    spesa = next((x for x in txs if any(
        isinstance(i, dict) and isinstance(i.get("prevout"), dict)
        and i["prevout"].get("scriptpubkey_address") == indirizzo
        for i in x.get("vin") or [])), None)
    if spesa and (spesa.get("status") or {}).get("confirmed"):
        arrivo = (_swap_script_destinazione(r["destinazione"], rete)
                  or b"").hex()
        pagate = [o for o in spesa.get("vout") or [] if isinstance(o, dict)]
        nostra = bool(arrivo) and len(pagate) == 1 \
            and pagate[0].get("scriptpubkey") == arrivo
        con = db()
        try:
            con.execute("UPDATE swap_auto SET confermato=? WHERE indice=?",
                        (1 if nostra else 2, int(indice)))
            con.commit()
        finally:
            con.close()
        if not nostra:
            print(f"🚨 Swap automatico {int(indice)}: il lockup l'ha speso "
                  f"un'altra transazione ({spesa.get('txid')}), non il "
                  "nostro ritiro", flush=True)
            return dict(vuoto, stato="altro", txid=str(spesa.get("txid")
                                                       or ""),
                        perche="il lockup l'ha speso un altro")
        return dict(vuoto, stato="confermato", txid=str(spesa.get("txid")
                                                         or ""))
    if spesa:
        lockup_txid = next(str(i.get("txid") or "") for i in spesa["vin"]
                           if isinstance(i, dict) and isinstance(
                               i.get("prevout"), dict)
                           and i["prevout"].get("scriptpubkey_address")
                           == indirizzo)
    else:
        # nessuno l'ha speso: il ritiro e' uscito dalla coda (la rete
        # butta le transazioni povere dopo giorni) — si ritrasmette
        lockup_txid = next((str(x.get("txid") or "") for x in txs if any(
            isinstance(o, dict) and o.get("scriptpubkey_address") == indirizzo
            for o in x.get("vout") or [])), "")
    if not re.fullmatch(r"[0-9a-f]{64}", lockup_txid):
        return dict(vuoto, stato="aspetta", perche="lockup non visto")
    lockup_hex = (await _swap_mempool_leggi(base, f"/tx/{lockup_txid}/hex")
                  or "").strip()
    try:
        from embit.transaction import Transaction
        if Transaction.parse(bytes.fromhex(lockup_hex)).txid().hex() \
                != lockup_txid:
            return dict(vuoto, stato="no", perche="la rete risponde con un "
                        "altro lockup")
    except Exception:
        return dict(vuoto, stato="aspetta", perche="lockup illeggibile")
    d = _swap_auto_parole_vps()
    if not d:
        return dict(vuoto, stato="no", perche="parole assenti")
    destinazione = r["destinazione"]
    try:
        chiavi = swap_auto_chiavi(d["parole"], indice)
        t = swap_auto_tx_ritiro(rec, chiavi, lockup_hex, destinazione,
                                int(r["ricevi"]), rete)
        # quel che paga davvero la transazione in coda, se e' la nostra
        # (stesso indirizzo d'arrivo); sennò l'ultima scritta nella riga
        attuale = int(r["ricevi"])
        dest_hex = (_swap_script_destinazione(destinazione, rete)
                    or b"").hex()
        if spesa:
            uscite = [o for o in spesa.get("vout") or []
                      if isinstance(o, dict)]
            if len(uscite) == 1 and uscite[0].get("scriptpubkey") == dest_hex:
                attuale = int(uscite[0].get("value") or attuale)
        prima_fee = t["valore"] - attuale
        fermo_da = max(0, int(time.time()) - int(r["aggiornato"] or 0))
        sat_vb = await _swap_auto_tariffa(base, swap_auto_scalino(
            await _swap_auto_restano(base, rec), fermo_da))
        if not sat_vb:
            return dict(vuoto, stato="aspetta", perche="tariffe mute")
        if spesa and math.ceil(sat_vb * t["vsize"]) <= prima_fee:
            return dict(vuoto, stato="fermo", txid=str(spesa.get("txid")
                                                      or ""),
                        sats=attuale, perche="la commissione basta")
        nuovo = swap_auto_ricevi_con_tariffa(
            t["valore"], attuale, t["vsize"], sat_vb,
            prima_fee + t["vsize"] if spesa else 0)
        if not nuovo:
            print(f"⚠️ Swap automatico {int(indice)}: il rilancio a "
                  f"{sat_vb} sat/vB scenderebbe sotto la polvere", flush=True)
            return dict(vuoto, stato="no", perche="sotto la polvere")
        t = swap_auto_tx_ritiro(rec, chiavi, lockup_hex, destinazione,
                                nuovo, rete)
    except ValueError as e:
        print(f"⚠️ Swap automatico {int(indice)}: rilancio fermo ({e})",
              flush=True)
        return dict(vuoto, stato="no", perche=str(e))
    if not await _swap_auto_trasmetti(fornitore, t["hex"]):
        return dict(vuoto, stato="aspetta", txid=t["txid"],
                    perche="nessuna strada ha preso il rilancio")
    con = db()
    try:
        # `aggiornato` resta l'ora del primo ritiro: «fermo da» si conta
        # da li', non dall'ultimo rilancio
        con.execute("UPDATE swap_auto SET ritiro_txid=?, ricevi=? "
                    "WHERE indice=?", (t["txid"], int(nuovo), int(indice)))
        con.commit()
    finally:
        con.close()
    print(f"🔁 Swap automatico {int(indice)}: ritiro rilanciato a {sat_vb} "
          f"sat/vB, {_fmt_sats(attuale)} → {_fmt_sats(nuovo)} sats "
          f"({t['txid']})", flush=True)
    return {"stato": "rilanciato", "txid": t["txid"], "sats": int(nuovo),
            "prima": int(attuale), "perche": ""}


async def swap_auto_rilancia_fermi() -> int:
    """I RITIRI ANCORA SENZA CONFERMA degli ultimi sette giorni, guardati
    dal battito dei pagamenti: ognuno una volta ogni dieci minuti, dopo i
    primi venti. Chi vende sa di ogni rilancio. Torna quanti."""
    ora = int(time.time())
    con = _swap_pag_db()
    try:
        _swap_auto_prepara(con)
        righe = con.execute(
            "SELECT s.indice, s.ordine_id, s.destinazione, o.venditore_id, "
            "a.titolo FROM swap_auto s JOIN ordini o ON o.id=s.ordine_id "
            "LEFT JOIN annunci a ON a.id=o.annuncio_id WHERE s.stato=? AND "
            "s.ritiro_txid!='' AND COALESCE(s.confermato, 0)=0 AND "
            "s.creato>? AND s.aggiornato<?",
            (SWAP_AUTO_RITIRATO, ora - 7 * 86_400,
             ora - SWAP_AUTO_RILANCIO_DOPO)).fetchall()
    finally:
        con.close()
    rilanciati = 0
    for r in righe:
        if ora - _SWAP_AUTO_GUARDATO.get(r["indice"], 0) \
                < SWAP_AUTO_RILANCIO_OGNI:
            continue
        _SWAP_AUTO_GUARDATO[r["indice"]] = ora
        try:
            esito = await swap_auto_rilancia(r["indice"])
        except Exception as e:
            print(f"⚠️ Swap automatico {r['indice']}: il rilancio salta "
                  f"({type(e).__name__})", flush=True)
            continue
        if esito["stato"] == "altro":
            # (14 nov 2026) una volta sola: la riga ha gia' `confermato=2`
            # e il giro dopo non la guarda piu'
            await notifica_admin(argomento="liquidita", testo=
                f"🚨 <b>Swap automatico dell'ordine #{int(r['ordine_id'])}:"
                "</b> i bitcoin bloccati dal fornitore li ha spesi una "
                "transazione che NON è il nostro ritiro (<code>"
                f"{html.escape(esito['txid'])}</code>). A chi vende non sono "
                "arrivati, anche se gli abbiamo scritto che erano partiti: "
                "va guardato a mano, col fornitore.")
            continue
        if esito["stato"] != "rilanciato":
            continue
        rilanciati += 1
        titolo = html.escape(str(r['titolo'] or '')[:40])
        if esito["sats"] >= esito["prima"]:
            # la rete l'aveva buttato: ritrasmesso com'era, niente da dire
            # sui sats (la transazione e' la stessa)
            continue
        await notifica(r["venditore_id"],
            f"🔁 <b>{titolo}:</b> la rete bitcoin è intasata e il tuo ritiro "
            "era fermo, così l'abbiamo rilanciato con una commissione più "
            f"alta. Arrivano <b>{_fmt_sats(esito['sats'])} sats</b> (prima "
            f"{_fmt_sats(esito['prima'])}) verso <code>"
            f"{html.escape(r['destinazione'])}</code>. La nuova transazione "
            f"è <code>{esito['txid']}</code>: la vecchia non vale più.")
    return rilanciati


# --- TAPPA 3: CHI VENDE SCEGLIE, CONFERMA, E I BITCOIN ARRIVANO -------
# (2 nov 2026, cantiere swap-auto) La scelta sta nel Profilo: «Quando
# vendi in Lightning, ricevi ⚡ in Lightning o ₿ on-chain». Chi sceglie
# on-chain, a ordine confermato, NON riceve sul Lightning address
# (`_sblocca_sats` lo salta: `swap_auto_aspetta`): apre l'ordine, vede
# quanto arriva e dove, e preme «Conferma» (Alan: «riceve in automatico,
# previa conferma»). L'indirizzo: il prossimo della xpub che ha dato per
# l'on-chain (un indirizzo nuovo per ogni vendita) o l'indirizzo fisso
# che ha scelto la', se sono della rete dello swap; sennò lo scrive li'.
# Da «Conferma» in poi fa tutto il server: nasce lo swap (tappa 1), lo
# paga la porta di sempre (`swap_registra_pagamento`, coi suoi tetti e
# controlli), e il battito dei pagamenti ritira i bitcoin (tappa 2) e lo
# dice a chi vende. Il costo del cambio e' di chi lo sceglie, scritto
# prima del tocco: «Ricevi circa X».
_swap_auto_lucchetti = defaultdict(asyncio.Lock)


def swap_auto_per(tg_id) -> bool:
    """LO SWAP AUTOMATICO C'E' PER QUESTA PERSONA? La leva, embit, e a
    solo-admin acceso la sola lista degli admin. Decide il server."""
    if not SWAP_AUTO_ATTIVO or not EMBIT:
        return False
    if SWAP_AUTO_SOLO_ADMIN:
        return e_admin(int(tg_id or 0))
    return True


def _swap_auto_pref_prepara(con):
    """Chi ha scelto «₿ On-chain» nel Profilo: una riga, e niente altro.
    Non e' un segreto e non sposta sats da solo. (9 nov 2026) la colonna
    `modo` dice quale delle due scelte che non sono Lightning: 'onchain'
    (le righe di prima) o 'ogni_volta'. Nessuna riga = Lightning."""
    con.execute("""CREATE TABLE IF NOT EXISTS swap_auto_preferenze(
        tg_id INTEGER PRIMARY KEY,
        aggiornato INTEGER DEFAULT 0)""")
    if "modo" not in _colonne_di(con, "swap_auto_preferenze"):
        try:
            con.execute("ALTER TABLE swap_auto_preferenze ADD COLUMN "
                        "modo TEXT DEFAULT 'onchain'")
        except sqlite3.OperationalError:
            pass


SWAP_AUTO_MODI = ("ln", "onchain", "ogni_volta")


def swap_auto_modo(con, tg_id) -> str:
    """«QUANDO TI PAGANO IN LIGHTNING, RICEVI IN…» (9 nov 2026): 'ln',
    'onchain' o 'ogni_volta'. A leva spenta tutti tornano in Lightning,
    come ieri."""
    if not swap_auto_per(tg_id):
        return "ln"
    _swap_auto_pref_prepara(con)
    r = con.execute("SELECT modo FROM swap_auto_preferenze WHERE tg_id=?",
                    (int(tg_id),)).fetchone()
    if r is None:
        return "ln"
    return "ogni_volta" if r["modo"] == "ogni_volta" else "onchain"


def swap_auto_preferisce(con, tg_id) -> bool:
    """Ha scelto on-chain, e lo swap automatico c'e' per lui? A leva
    spenta tutti tornano in Lightning, come ieri."""
    return swap_auto_modo(con, tg_id) == "onchain"


def incasso_da_payload(d) -> str:
    """L'incasso scelto sull'annuncio (9 nov 2026): 'ln', 'onchain' o ''
    (come nel Profilo). Una parola ignota vale ''."""
    v = str((d or {}).get("incasso") or "").strip().lower()
    return v if v in ("ln", "onchain") else ""


def incasso_annuncio(con, annuncio_id) -> str:
    """Come vuole ricevere chi vende per QUESTO annuncio: 'ln', 'onchain'
    o '' (come nel Profilo)."""
    try:
        r = con.execute("SELECT incasso FROM annunci WHERE id=?",
                        (int(annuncio_id or 0),)).fetchone()
    except (sqlite3.OperationalError, TypeError, ValueError):
        return ""
    v = (r["incasso"] if r else "") or ""
    return v if v in ("ln", "onchain") else ""


def incasso_ln_ordine(con, o) -> str:
    """UN ORDINE PAGATO IN LIGHTNING, COME RICEVE CHI VENDE (9 nov 2026):
    la scelta dell'annuncio vince, sennò quella del Profilo. 'ln',
    'onchain' o 'ogni_volta'; senza lo swap automatico, sempre 'ln'."""
    if not swap_auto_per(o["venditore_id"]):
        return "ln"
    return (incasso_annuncio(con, o["annuncio_id"])
            or swap_auto_modo(con, o["venditore_id"]))


def swap_auto_aspetta(con, tg_id, netto: int, modo: str | None = None) -> bool:
    """`_sblocca_sats` deve LASCIARE STARE il Lightning address? Si', se
    chi vende ha scelto on-chain (o di scegliere ogni volta) e la cifra
    sta nei tetti del cambio; sotto il minimo (o sopra il massimo) si
    paga in Lightning come sempre, e il Profilo lo dice. `modo` e' quello
    dell'ordine (`incasso_ln_ordine`); senza, quello del Profilo."""
    if modo is None:
        modo = swap_auto_modo(con, tg_id)
    if modo not in ("onchain", "ogni_volta") or not swap_auto_per(tg_id):
        return False
    netto = int(netto)
    if netto < int(SWAP_MIN_SATS or 0):
        return False
    return not (int(SWAP_MAX_SATS or 0) > 0 and netto > int(SWAP_MAX_SATS))


def swap_auto_proposta(tg_id) -> dict | None:
    """L'INDIRIZZO CHE SI PROPONE a chi vende, dalla destinazione on-chain
    del suo Profilo (`onchain_incasso`, firmata dal suo seme): l'indirizzo
    fisso, o il prossimo `/0/i` della sua xpub, contato con le vendite
    on-chain e gli scambi P2P (`_p2p_onchain_prossimo_esterno`, che conta
    anche gli swap automatici). None se non c'e', se non si legge, o se e'
    di un'altra rete (l'on-chain su signet, lo swap su bitcoin)."""
    if not EMBIT or ONCHAIN_RETE_DEL_CAMBIO.get(ONCHAIN_RETE) != swap_rete():
        return None
    try:
        con = _onchain_db_ordini()
        try:
            r = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                            (int(tg_id),)).fetchone()
            dest = (_onchain_destinazione_viva(con, tg_id, r["xpub"])
                    if r else None)
            if not dest:
                return None
            indice = (_p2p_onchain_prossimo_esterno(con, tg_id, dest["valore"])
                      if dest["tipo"] == "xpub" else -1)
        finally:
            con.close()
        indirizzo = onchain_indirizzo_esterno(dest["tipo"], dest["valore"],
                                              max(indice, 0))
    except Exception:
        return None
    if not _swap_script_destinazione(indirizzo, swap_rete()):
        return None
    return {"indirizzo": indirizzo, "tipo": dest["tipo"],
            "valore": dest["valore"] if dest["tipo"] == "xpub" else "",
            "indice": indice}


def _swap_auto_no(ordine_id: int, motivo: str, detto: str = "") -> dict:
    """Un no PRIMA di creare o pagare: non e' partito niente."""
    print(f"🔁 Swap automatico dell'ordine #{int(ordine_id)}: no — {motivo}"
          + (f" ({detto})" if detto else ""), flush=True)
    return {"ok": False, "motivo": motivo}


async def swap_auto_incassa(venditore_id: int, ordine_id: int,
                            indirizzo: str = "") -> dict:
    """IL «CONFERMA» DI CHI VENDE: l'indirizzo (quello scritto, o quello
    del Profilo), il preventivo di adesso, lo swap nato e verificato, il
    pagamento per la porta di sempre. Un tocco doppio non fa due swap: il
    lucchetto dell'ordine, e dentro la porta il suo."""
    async with _swap_auto_lucchetti[int(ordine_id)]:
        if not swap_auto_per(venditore_id):
            return _swap_auto_no(ordine_id, "spento")
        if float(SWAP_AUTO_FEE_PERCENTO or 0) > 0:
            return _swap_auto_no(ordine_id, "fee", "SWAP_AUTO_FEE_PERCENTO "
                                 "sopra 0: la porta paga solo il dovuto intero")
        con = _swap_pag_db()
        try:
            o = con.execute("SELECT * FROM ordini WHERE id=?",
                            (int(ordine_id),)).fetchone()
            vivo = None
            if o:
                for r in con.execute("SELECT * FROM swap_pagamenti WHERE "
                                     "ordine_id=?", (int(ordine_id),)).fetchall():
                    if _swap_pag_aggiorna(con, r) != SWAP_PAG_FALLITO:
                        vivo = r
        finally:
            con.close()
        if not o or int(o["venditore_id"]) != int(venditore_id):
            return {"ok": False, "motivo": "ordine", "non_trovato": True}
        if vivo:
            return {"ok": True, "stato": _swap_pag_dell_ordine(ordine_id,
                                                               vivo["id"])}
        if o["stato"] != "confirmed" or (_campo(o, "cassaforte") or "") == "onchain":
            return _swap_auto_no(ordine_id, "ordine", f"stato {o['stato']}")
        chi = swap_fornitore("satsrouting")
        # La carta manda SEMPRE l'indirizzo che mostra: se e' proprio quello
        # proposto dal Profilo, vale come proposta (e il suo `/0/i` resta
        # contato, cosi' la vendita dopo ne riceve uno nuovo); se e' un
        # altro, l'ha scritto chi vende e conta solo la sua rete.
        scritto = str(indirizzo or "").strip()
        proposta = swap_auto_proposta(venditore_id)
        if proposta and scritto in ("", proposta["indirizzo"]):
            dest = proposta
        elif scritto:
            if not _swap_script_destinazione(scritto, chi["rete"]):
                return _swap_auto_no(ordine_id, "indirizzo",
                                     "non e' un indirizzo di questa rete")
            dest = {"indirizzo": scritto, "valore": "", "indice": -1}
        else:
            return _swap_auto_no(ordine_id, "indirizzo",
                                 "nel Profilo non c'e' un indirizzo")
        dovuto = netto_venditore(o["prezzo_sats"] - o["protezione_sats"])
        tariffa = await leggi_tariffa_swap(chi)
        if tariffa is None:
            return _swap_auto_no(ordine_id, "non_risponde")
        p = preventivo_swap(dovuto, tariffa, 0, SWAP_MIN_SATS, SWAP_MAX_SATS)
        if not p["ok"]:
            return _swap_auto_no(ordine_id, p["motivo"])
        try:
            nato = await swap_auto_crea(chi, ordine_id, p)
        except ValueError as e:
            return _swap_auto_no(ordine_id, "parole", str(e))
        if nato["stato"] != SWAP_AUTO_NATO:
            return _swap_auto_no(ordine_id, nato["stato"], nato["perche"])
        con = db()
        try:
            con.execute("UPDATE swap_auto SET destinazione=?, ricevi=?, "
                        "dest_valore=?, dest_indice=?, aggiornato=? "
                        "WHERE indice=?",
                        (dest["indirizzo"], int(p["ricevi"]), dest["valore"],
                         int(dest["indice"]), int(time.time()), nato["indice"]))
            con.commit()
        finally:
            con.close()
        esito = await swap_registra_pagamento(
            int(venditore_id), int(ordine_id), chi,
            {"swap_id": nato["swap_id"], "impronta": nato["impronta"],
             "bolt11": nato["fattura"], "onchain": nato["onchain"],
             "indirizzo": nato["lockup"], "scade_blocco": nato["scade_blocco"]})
        return dict(esito, ricevi=int(p["ricevi"]), indirizzo=dest["indirizzo"])


def swap_auto_dell_ordine(ordine_id: int) -> dict:
    """A che punto e' il cambio automatico di un ordine, per la carta di
    chi vende: {} se non c'e'; sennò lo stato del pagamento (la porta
    di sempre), dove vanno i bitcoin, quanti, e l'id del ritiro."""
    con = db()
    try:
        _swap_auto_prepara(con)
        r = con.execute("SELECT * FROM swap_auto WHERE ordine_id=? AND "
                        "stato IN (?, ?) AND destinazione!='' ORDER BY "
                        "indice DESC LIMIT 1", (int(ordine_id), SWAP_AUTO_NATO,
                                                SWAP_AUTO_RITIRATO)).fetchone()
        pag = None
        if r:
            pag = con.execute("SELECT id FROM swap_pagamenti WHERE "
                              "ordine_id=? AND swap_id=?",
                              (int(ordine_id), r["swap_id"])).fetchone() \
                if con.execute("SELECT name FROM sqlite_master WHERE "
                               "name='swap_pagamenti'").fetchone() else None
    finally:
        con.close()
    if not r:
        return {}
    return {"pagamento": _swap_pag_dell_ordine(ordine_id, pag["id"]) if pag else "",
            "ritirato": r["stato"] == SWAP_AUTO_RITIRATO,
            "txid": r["ritiro_txid"] or "", "indirizzo": r["destinazione"],
            "ricevi": int(r["ricevi"] or 0)}


# IL TASTO DELL'AVVISO (6 nov 2026, richiesta di Andrea: «nel messaggio
# del bot voglio un tasto che riporti esattamente dove l'utente deve
# compiere l'azione»): apre l'ordine e scorre fino al riquadro
# dell'incasso, quello col «Conferma» del cambio (`&incasso=1`, vedi
# `_startapp_da_link` e `incassoDaAvviso` nel telefono).
SWAP_AUTO_BOTTONE = "₿ Controlla e conferma"


def _bottone_swap_auto(ordine_id: int) -> tuple:
    """La coppia (etichetta, indirizzo) del tasto sotto l'avviso."""
    return (SWAP_AUTO_BOTTONE, f"{URL_PUBBLICO}/?ordine={int(ordine_id)}&incasso=1")


def _msg_swap_auto_scegli(sats: int, testa: str) -> str:
    """(9 nov 2026) Le parole per chi ha scelto di decidere ogni volta:
    il suo gesto e' la scelta, poi un tocco o una fattura."""
    return (f"{testa} Hai scelto di decidere a ogni vendita come ricevere: "
            "apri l'ordine nella Mini App e scegli <b>⚡ Lightning</b> o "
            f"<b>₿ on-chain</b>. I tuoi <b>{_fmt_sats(sats)} sats</b> intanto "
            "restano al sicuro nel deposito di garanzia.")


def _msg_swap_auto_conferma(sats: int, testa: str) -> str:
    """Le parole per chi ha scelto on-chain, a ordine confermato: il suo
    gesto e' un tocco, non una fattura."""
    return (f"{testa} Hai scelto di ricevere in <b>bitcoin on-chain</b>: apri "
            "l'ordine nella Mini App, controlla l'indirizzo e premi "
            f"<b>«Conferma»</b>. I tuoi <b>{_fmt_sats(sats)} sats</b> intanto "
            "restano al sicuro nel deposito di garanzia.")


async def swap_auto_giro() -> int:
    """IL RITIRO NEL BATTITO DEI PAGAMENTI: per ogni swap automatico nato
    e confermato degli ultimi tre giorni, se il fornitore ha bloccato i
    bitcoin si ritirano (tappa 2). Chi vende lo sa con l'id della
    transazione. Torna quanti ne sono partiti in questo giro."""
    con = _swap_pag_db()
    try:
        _swap_auto_prepara(con)
        # solo gli swap la cui fattura e' partita: uno mai pagato (o
        # fallito) non avra' mai un lockup, e non si chiede al mempool
        righe = con.execute(
            "SELECT s.*, o.venditore_id, a.titolo FROM swap_auto s JOIN "
            "ordini o ON o.id=s.ordine_id LEFT JOIN annunci a ON "
            "a.id=o.annuncio_id JOIN swap_pagamenti p ON p.ordine_id="
            "s.ordine_id AND p.swap_id=s.swap_id WHERE s.stato=? AND "
            "s.destinazione!='' AND s.creato>? AND p.stato IN (?, ?)",
            (SWAP_AUTO_NATO, int(time.time()) - 3 * 86_400,
             SWAP_PAG_IN_VOLO, SWAP_PAG_PAGATO)).fetchall()
    finally:
        con.close()
    partiti = 0
    for r in righe:
        try:
            esito = await swap_auto_ritira(r["indice"], r["destinazione"],
                                           r["ricevi"])
        except Exception as e:
            print(f"⚠️ Swap automatico {r['indice']}: il giro salta "
                  f"({type(e).__name__})", flush=True)
            continue
        if esito["stato"] != SWAP_AUTO_RITIRATO:
            # (14 nov 2026) il ritiro rifiutato perche' la scadenza e'
            # troppo vicina: lo sanno gli admin, una volta per swap
            if esito.get("perche") == SWAP_AUTO_TARDI \
                    and r["indice"] not in _SWAP_AUTO_DETTO_TARDI:
                _SWAP_AUTO_DETTO_TARDI.add(r["indice"])
                await notifica_admin(argomento="liquidita", testo=
                    f"⚠️ <b>Swap automatico dell'ordine #{int(r['ordine_id'])}"
                    ":</b> non ritiro i bitcoin, perché alla scadenza dello "
                    f"swap mancano meno di {SWAP_AUTO_MARGINE_RITIRO} blocchi "
                    "e il segreto non deve uscire così tardi. Non si è perso "
                    "niente: la fattura resta non incassata, quando il "
                    "fornitore la annulla i sats tornano e chi vende può "
                    "rifare il cambio. Se fra qualche ora l'ordine dice "
                    "ancora «Swap in corso», va guardato a mano.")
            continue
        partiti += 1
        print(f"₿ Swap automatico dell'ordine #{r['ordine_id']}: ritiro "
              f"{esito['txid']} verso {r['destinazione'][:10]}…", flush=True)
        await notifica(r["venditore_id"],
            f"₿ <b>{html.escape(str(r['titolo'] or '')[:40])}:</b> i tuoi "
            f"bitcoin sono partiti, <b>{_fmt_sats(esito.get('sats') or r['ricevi'])}"
            f" sats</b> verso "
            f"<code>{html.escape(r['destinazione'])}</code>. La transazione è "
            f"<code>{esito['txid']}</code>: arrivano con la prima conferma.")
    # (6 nov 2026) i ritiri gia' partiti e ancora fermi: lo scalino dopo
    try:
        await swap_auto_rilancia_fermi()
    except Exception as e:
        print(f"⚠️ Swap automatico: i rilanci saltano ({type(e).__name__})",
              flush=True)
    return partiti


@app.post("/api/swap/auto/preferenza")
async def swap_auto_preferenza(req: Request, x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """«QUANDO TI PAGANO IN LIGHTNING, RICEVI IN…» dal Profilo: {modo:
    'ln' | 'onchain' | 'ogni_volta'} (o {onchain: bool} di un client di
    prima). Vale dalle conferme dopo; un ordine gia' confermato si
    sceglie dall'ordine."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not swap_auto_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    d = await leggi_json(req)
    modo = str(d.get("modo") or "").strip()
    if modo not in SWAP_AUTO_MODI:
        modo = "onchain" if d.get("onchain") else "ln"
    con = db()
    try:
        _swap_auto_pref_prepara(con)
        if modo != "ln":
            con.execute("INSERT INTO swap_auto_preferenze(tg_id, aggiornato, modo) "
                        "VALUES (?,?,?) ON CONFLICT(tg_id) DO UPDATE SET "
                        "aggiornato=excluded.aggiornato, modo=excluded.modo",
                        (user["id"], int(time.time()), modo))
        else:
            con.execute("DELETE FROM swap_auto_preferenze WHERE tg_id=?",
                        (user["id"],))
        con.commit()
    finally:
        con.close()
    return swap_auto_busta(user["id"])


def swap_auto_busta(tg_id) -> dict:
    """La busta di `/api/me` (`swap_leve.auto`): il cancello, la scelta,
    l'indirizzo che si proporrebbe (solo pubblico), i tetti."""
    attivo = swap_auto_per(tg_id)
    modo = "ln"
    proposta = None
    if attivo:
        con = db()
        try:
            modo = swap_auto_modo(con, tg_id)
        finally:
            con.close()
        proposta = swap_auto_proposta(tg_id)
    return {"attivo": attivo, "onchain": modo == "onchain", "modo": modo,
            "indirizzo": (proposta or {}).get("indirizzo", ""),
            "da": (proposta or {}).get("tipo", ""),
            "minimo": int(SWAP_MIN_SATS or 0), "massimo": int(SWAP_MAX_SATS or 0),
            "fornitore": "SATS Routing"}


@app.get("/api/swap/auto/ordine/{ordine_id}")
async def swap_auto_ordine_vedi(ordine_id: int,
                                x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """La carta del cambio automatico di un ordine, per chi vende: il
    preventivo di adesso, l'indirizzo proposto e, se c'e', il cambio in
    corso. Non crea niente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not swap_auto_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=?", (ordine_id,)).fetchone()
    con.close()
    if not o or o["venditore_id"] != user["id"]:
        raise HTTPException(404, "Ordine non trovato")
    corso = swap_auto_dell_ordine(ordine_id)
    proposta = swap_auto_proposta(user["id"])
    d = {"corso": corso, "indirizzo": (proposta or {}).get("indirizzo", ""),
         "da": (proposta or {}).get("tipo", ""), "rete": swap_rete()}
    # un cambio fallito (non e' uscito niente) lascia rifare il preventivo
    if o["stato"] != "confirmed" or (corso and corso["pagamento"] != SWAP_PAG_FALLITO):
        return d
    chi = swap_fornitore("satsrouting")
    dovuto = netto_venditore(o["prezzo_sats"] - o["protezione_sats"])
    tariffa = await leggi_tariffa_swap(chi)
    d["preventivo"] = ({"ok": False, "motivo": "non_risponde", "dovuto": dovuto}
                       if tariffa is None else
                       preventivo_swap(dovuto, tariffa, 0, SWAP_MIN_SATS,
                                       SWAP_MAX_SATS))
    return d


