@app.post("/api/swap/auto/ordine/{ordine_id}/lightning")
async def swap_auto_ordine_lightning(ordine_id: int,
                                     x_tg_init_data: str = Header(""),
                                     barattolo_sessione: str = Cookie("")):
    """«⚡ RICEVI AL MIO LIGHTNING ADDRESS» (9 nov 2026, incasso-annuncio):
    su un ordine confermato che aspetta la scelta di chi vende (ha scelto
    on-chain o «ogni volta», nel Profilo o sull'annuncio), chi vende sceglie
    Lightning con un tocco. La fattura la chiede il server al suo
    Lightning address e la mette in colonna come una incollata — la stessa
    porta, con la stessa ancora degli swap (stato confermato, colonna
    vuota, nessun pagamento in volo) — e poi `_sblocca_sats` la paga."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not swap_auto_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("swap_auto", user["id"])
    con = db()
    try:
        o = con.execute("SELECT * FROM ordini WHERE id=?", (ordine_id,)).fetchone()
        v = con.execute("SELECT ln_address FROM utenti WHERE tg_id=?",
                        (user["id"],)).fetchone()
    finally:
        con.close()
    if not o or o["venditore_id"] != user["id"]:
        raise HTTPException(404, "Ordine non trovato")
    if o["stato"] != "confirmed":
        raise HTTPException(409, "Quest'ordine non aspetta un incasso")
    indirizzo = ((v["ln_address"] if v else "") or "").strip()
    if not indirizzo:
        raise HTTPException(400, "Non hai un Lightning address: incolla una fattura")
    netto = netto_venditore(o["prezzo_sats"] - o["protezione_sats"])
    bolt11 = await invoice_da_ln_address(indirizzo, netto)
    if not bolt11:
        raise HTTPException(502, "Il tuo Lightning address non ha risposto: "
                                 "riprova, o incolla una fattura")
    con = db()
    try:
        messa = con.execute(
            "UPDATE ordini SET invoice_venditore=?, aggiornato=? "
            "WHERE id=? AND stato='confirmed' "
            "AND COALESCE(invoice_venditore,'')='' "
            "AND COALESCE(payout_stato,'') NOT IN "
            "('in_volo','incerto','uscito')",
            (bolt11, int(time.time()), ordine_id)).rowcount
        con.commit()
    finally:
        con.close()
    if not messa:
        raise HTTPException(409, "C'è già un incasso in corso su questo ordine")
    return await _sblocca_sats(ordine_id)


# --- IL CAMBIO LIBERO (27 ott 2026, cantiere cambio-libero) ---------------
# I SUOI sats, senza un ordine: dalla pagina «Cambio» chi passa il
# cancello sceglie la direzione e la cifra, vede il preventivo, conferma,
# e il suo telefono fa il cambio con SATS Routing come per un incasso —
# ma la fattura la paga LUI col suo wallet, e i bitcoin arrivano al suo
# indirizzo. La cassaforte non c'entra: qui il server da' il preventivo
# (lo stesso conto del preventivo dell'incasso, sulla cifra chiesta),
# stacca un BIGLIETTO prima che il telefono chieda lo swap al fornitore,
# e conta i biglietti del giorno (decisione di Andrea: 500.000 sats per
# cambio, 5 cambi in 24 ore per persona). Il biglietto e' una riga di
# `cambi_liberi`: «chiesto» quando si stacca, «nato» quando il telefono
# dice che lo swap c'e' (le sole parti pubbliche), «annullato» se la
# nascita non e' andata; un «chiesto» vecchio di un quarto d'ora non
# conta piu' (il telefono si e' spento a meta'). Un telefono manomesso
# puo' saltare il biglietto: non c'e' un sats di Barattolo in gioco, e
# il tetto e' una regola della casa, non una cassaforte.
def cambio_strade() -> tuple:
    """Le direzioni del cambio: Lightning → indirizzo sempre; bitcoin →
    Lightning solo a `CAMBIO_BTC_LN_ATTIVO` (spenta di serie: si accende
    dal config, quando decide Andrea)."""
    return ("ln-btc", "btc-ln") if CAMBIO_BTC_LN_ATTIVO else ("ln-btc",)


CAMBIO_CHIESTO_VALE_S = 900
CAMBIO_STATI = ("chiesto", "nato", "annullato")
_lucchetto_cambi = asyncio.Lock()


def _cambi_prepara(con):
    """`cambi_liberi`: un biglietto per cambio."""
    con.execute("""CREATE TABLE IF NOT EXISTS cambi_liberi(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tg_id INTEGER NOT NULL,
        direzione TEXT NOT NULL,
        sats INTEGER NOT NULL,
        fornitore TEXT NOT NULL,
        swap_id TEXT DEFAULT '',
        impronta TEXT DEFAULT '',
        indirizzo TEXT DEFAULT '',
        onchain INTEGER DEFAULT 0,
        stato TEXT DEFAULT 'chiesto',
        creato INTEGER DEFAULT 0,
        aggiornato INTEGER DEFAULT 0)""")
    # L'ESITO (11 nov 2026, cantiere volume-cambio): '' = non si sa
    # ancora, «fatto» o «non_andato» come lo dice il fornitore; `visto` =
    # l'ultima volta che glielo si e' chiesto. Li scrive `ronda_esiti_cambi`.
    for colonna in ("esito TEXT DEFAULT ''", "esito_visto INTEGER DEFAULT 0"):
        try:
            con.execute(f"ALTER TABLE cambi_liberi ADD COLUMN {colonna}")
        except sqlite3.OperationalError:
            pass
    con.execute("CREATE INDEX IF NOT EXISTS cambi_liberi_chi ON "
                "cambi_liberi(tg_id, creato)")
    con.execute("CREATE UNIQUE INDEX IF NOT EXISTS cambi_liberi_swap ON "
                "cambi_liberi(fornitore, swap_id) WHERE swap_id <> ''")


def _cambi_db():
    con = db()
    _cambi_prepara(con)
    return con


def cambi_oggi(con, tg_id: int, adesso: int) -> int:
    """QUANTI CAMBI HA FATTO OGGI questa persona: nelle ultime 24 ore, i
    biglietti «nati» e quelli «chiesti» ancora freschi (un quarto d'ora).
    Un cambio annullato prima di nascere non conta."""
    r = con.execute(
        "SELECT COUNT(*) FROM cambi_liberi WHERE tg_id=? AND creato>? AND "
        "(stato='nato' OR (stato='chiesto' AND creato>?))",
        (int(tg_id), int(adesso) - 86400,
         int(adesso) - CAMBIO_CHIESTO_VALE_S)).fetchone()
    return int(r[0] if r else 0)


def cambio_leve(tg_id: int) -> dict:
    """La busta del cambio libero per `/api/me`: il cancello, i tetti, le
    strade che il server sa, quanti cambi oggi."""
    attivo = cambio_libero_per(tg_id)
    oggi = 0
    if attivo:
        con = _cambi_db()
        try:
            oggi = cambi_oggi(con, tg_id, int(time.time()))
        finally:
            con.close()
    return {"attivo": attivo, "minimo": int(SWAP_MIN_SATS or 0),
            "massimo": int(CAMBIO_LIBERO_MAX_SATS or 0),
            "al_giorno": int(CAMBIO_LIBERO_MAX_AL_GIORNO or 0),
            "oggi": oggi, "strade": list(cambio_strade())}


def _cambio_tetto_giorno(oggi: int) -> bool:
    """Il tetto dei cambi al giorno e' raggiunto? (0 = nessun tetto)"""
    tetto = int(CAMBIO_LIBERO_MAX_AL_GIORNO or 0)
    return tetto > 0 and int(oggi) >= tetto


def _cambio_sats(valore) -> int:
    """La cifra chiesta, in sats interi; 0 se non e' un numero buono."""
    try:
        n = int(str(valore or "0").strip().replace(".", "").replace(" ", ""))
    except ValueError:
        return 0
    return n if 0 < n <= 21_000_000 * 100_000_000 else 0


@app.get("/api/swap/cambio/preventivo")
async def cambio_preventivo(sats: str = "", direzione: str = "ln-btc",
                            fornitore: str = "satsrouting", hash: str = "",
                            lato: str = "",
                            x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """IL PREVENTIVO DEL CAMBIO LIBERO: quanto riceverebbe al suo indirizzo
    chi cambia `sats` in Lightning, con le regole e i tetti del cambio
    (non quelli dell'incasso). Non crea niente. `hash` e `fornitore` come
    nel preventivo dell'incasso; `oggi` e `al_giorno` dicono dove sta col
    tetto del giorno, e a tetto raggiunto il motivo e' `tetto_giorno`.
    (28 ott 2026, cambio-due-riquadri) `lato` dice dove si e' scritta la
    cifra, `mandi` o `ricevi`; vuoto = il lato del `dovuto` (mandi verso
    l'indirizzo, ricevi verso Lightning). Dall'altro lato il dovuto si
    trova col conto al contrario. La busta ripete `lato` e la cifra
    scritta (`scritta`): il telefono butta le risposte vecchie con quelle."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not cambio_libero_per(user["id"]):
        raise HTTPException(403, "Lo swap non è disponibile")
    if direzione not in cambio_strade():
        raise HTTPException(400, "Direzione sconosciuta")
    chi = swap_fornitore(str(fornitore or ""))
    if chi is None:
        raise HTTPException(404, "Fornitore sconosciuto")
    if lato not in ("", "mandi", "ricevi"):
        raise HTTPException(400, "Lato sconosciuto")
    lato_dovuto = "ricevi" if direzione == "btc-ln" else "mandi"
    lato = lato or lato_dovuto
    cifra = _cambio_sats(sats)
    con = _cambi_db()
    try:
        oggi = cambi_oggi(con, user["id"], int(time.time()))
    finally:
        con.close()
    busta = {"dovuto": cifra, "direzione": direzione, "oggi": oggi,
             "lato": lato, "scritta": cifra,
             "al_giorno": int(CAMBIO_LIBERO_MAX_AL_GIORNO or 0),
             "fornitore": chi["id"], "fornitore_nome": chi["nome"]}
    if not cifra:
        return dict(busta, ok=False, motivo="cifra")
    if _cambio_tetto_giorno(oggi):
        return dict(busta, ok=False, motivo="tetto_giorno")
    if direzione == "btc-ln":
        # (tappa 3) la strada rovesciata: le tariffe del submarine, e il
        # conto di quanto MANDARE all'indirizzo del fornitore
        tariffa = await leggi_tariffa_sub(chi)
        if tariffa is None:
            return dict(busta, ok=False, motivo="non_risponde")
        dovuto = cifra if lato == lato_dovuto \
            else sub_ricevi_per_mandare(cifra, tariffa)
        p = preventivo_sub(dovuto, tariffa, SWAP_MIN_SATS, CAMBIO_LIBERO_MAX_SATS)
    else:
        tariffa = await leggi_tariffa_swap(chi)
        if tariffa is None:
            return dict(busta, ok=False, motivo="non_risponde")
        dovuto = cifra if lato == lato_dovuto \
            else swap_dovuto_per_ricevere(cifra, tariffa, SWAP_FEE_PERCENTO)
        if not dovuto:
            return dict(busta, ok=False, motivo="cifra")
        p = preventivo_swap(dovuto, tariffa, SWAP_FEE_PERCENTO,
                            SWAP_MIN_SATS, CAMBIO_LIBERO_MAX_SATS)
    # (12 nov 2026, cantiere nome-swap, Andrea: «voglio cambiare 50000
    # sats da onchain a lightning e mi esce lo swap parte da 50000») il
    # minimo e il massimo valgono sul lato del `dovuto` (la richiesta
    # Lightning, verso Lightning; quel che si manda, verso l'indirizzo).
    # Chi ha scritto dall'altro lato li legge nella SUA cifra: 50.000
    # mandati in bitcoin ne fanno ricevere meno di 50.000, e «parte da
    # 50.000» gli sembrava falso. `minimo_scritto` e `massimo_scritto`
    # sono le soglie tradotte sul lato scritto, solo quando servono.
    if not p.get("ok") and lato != lato_dovuto and \
            p.get("motivo") in ("sotto_minimo", "sopra_tetto"):
        try:
            soglia = int(p["minimo"] if p["motivo"] == "sotto_minimo"
                         else p["massimo"])
            if direzione == "btc-ln":
                q = preventivo_sub(soglia, tariffa)
                tradotta = int(q["mandi"]) if q.get("ok") else 0
            else:
                q = preventivo_swap(soglia, tariffa, SWAP_FEE_PERCENTO)
                tradotta = int(q["ricevi"]) if q.get("ok") else 0
            if tradotta > 0:
                p["minimo_scritto" if p["motivo"] == "sotto_minimo"
                  else "massimo_scritto"] = tradotta
        except Exception:
            pass
    p["cambiata"] = bool(hash) and hash != tariffa["hash"]
    p["valido_s"] = SWAP_PREVENTIVO_VALE_S
    return dict(busta, **p)


@app.post("/api/swap/cambio")
async def cambio_biglietto(req: Request, x_tg_init_data: str = Header(""),
                           barattolo_sessione: str = Cookie("")):
    """IL BIGLIETTO: il telefono lo chiede PRIMA di chiedere lo swap al
    fornitore. Dentro un lucchetto: il cancello, la direzione, la cifra
    nei tetti, il tetto del giorno. Risponde {ok, id} o {ok: false,
    motivo}; a tetto raggiunto `tetto_giorno`."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not cambio_libero_per(user["id"]):
        raise HTTPException(403, "Lo swap non è disponibile")
    d = await leggi_json(req)
    direzione = str(d.get("direzione") or "ln-btc")
    if direzione not in cambio_strade():
        return {"ok": False, "motivo": "direzione"}
    chi = swap_fornitore(str(d.get("fornitore") or "satsrouting"))
    if chi is None:
        return {"ok": False, "motivo": "fornitore"}
    cifra = _cambio_sats(d.get("sats"))
    if not cifra or cifra < int(SWAP_MIN_SATS or 0):
        return {"ok": False, "motivo": "sotto_minimo"}
    if int(CAMBIO_LIBERO_MAX_SATS or 0) and cifra > int(CAMBIO_LIBERO_MAX_SATS):
        return {"ok": False, "motivo": "sopra_tetto"}
    adesso = int(time.time())
    async with _lucchetto_cambi:
        con = _cambi_db()
        try:
            oggi = cambi_oggi(con, user["id"], adesso)
            if _cambio_tetto_giorno(oggi):
                return {"ok": False, "motivo": "tetto_giorno", "oggi": oggi}
            cur = con.execute(
                "INSERT INTO cambi_liberi(tg_id,direzione,sats,fornitore,"
                "stato,creato,aggiornato) VALUES(?,?,?,?,'chiesto',?,?)",
                (int(user["id"]), direzione, cifra, chi["id"], adesso, adesso))
            con.commit()
            cid = int(cur.lastrowid)
        finally:
            con.close()
    return {"ok": True, "id": cid, "oggi": oggi + 1}


def _cambio_mio(con, cid: int, tg_id: int):
    r = con.execute("SELECT * FROM cambi_liberi WHERE id=? AND tg_id=?",
                    (int(cid), int(tg_id))).fetchone()
    return r


@app.post("/api/swap/cambio/{cid}/nato")
async def cambio_nato(cid: int, req: Request, x_tg_init_data: str = Header(""),
                      barattolo_sessione: str = Cookie("")):
    """LO SWAP C'E': il telefono porta le sole parti pubbliche (l'id dello
    swap, l'impronta del segreto, l'indirizzo dove il fornitore blocca i
    bitcoin, quanto). Il biglietto passa a «nato». Idempotente sullo
    stesso swap; un biglietto di un altro e' 404."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    swap_id = str(d.get("swap_id") or "").strip()
    impronta = str(d.get("impronta") or "").strip().lower()
    if not _SWAP_ID_FORMA.match(swap_id) or (
            impronta and not _SWAP_IMPRONTA_FORMA.match(impronta)):
        return {"ok": False, "motivo": "forma"}
    adesso = int(time.time())
    async with _lucchetto_cambi:
        con = _cambi_db()
        try:
            r = _cambio_mio(con, cid, user["id"])
            if not r:
                raise HTTPException(404, "Biglietto non trovato")
            if r["stato"] == "nato":
                return {"ok": r["swap_id"] == swap_id, "stato": "nato"}
            if r["stato"] != "chiesto":
                return {"ok": False, "motivo": r["stato"]}
            try:
                con.execute(
                    "UPDATE cambi_liberi SET stato='nato', swap_id=?, impronta=?,"
                    " indirizzo=?, onchain=?, aggiornato=? WHERE id=?",
                    (swap_id, impronta, str(d.get("indirizzo") or "")[:120],
                     int(d.get("onchain") or 0), adesso, int(cid)))
                con.commit()
            except sqlite3.IntegrityError:
                return {"ok": False, "motivo": "doppio"}
        finally:
            con.close()
    return {"ok": True, "stato": "nato"}


@app.post("/api/swap/cambio/{cid}/annulla")
async def cambio_annulla(cid: int, x_tg_init_data: str = Header(""),
                         barattolo_sessione: str = Cookie("")):
    """LA NASCITA NON E' ANDATA (il fornitore non risponde, o mente): il
    biglietto torna libero e non conta. Solo un «chiesto»."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    async with _lucchetto_cambi:
        con = _cambi_db()
        try:
            r = _cambio_mio(con, cid, user["id"])
            if not r:
                raise HTTPException(404, "Biglietto non trovato")
            if r["stato"] != "chiesto":
                return {"ok": False, "motivo": r["stato"]}
            con.execute("UPDATE cambi_liberi SET stato='annullato', aggiornato=? "
                        "WHERE id=?", (int(time.time()), int(cid)))
            con.commit()
        finally:
            con.close()
    return {"ok": True, "stato": "annullato"}


@app.post("/api/swap/cambio/fattura")
async def cambio_fattura_da_address(req: Request, x_tg_init_data: str = Header(""),
                                    barattolo_sessione: str = Cookie("")):
    """IL LIGHTNING ADDRESS AL POSTO DELLA RICHIESTA (11 nov 2026, cantiere
    cifra-copia, Andrea: «si»). Nel Cambio da bitcoin a Lightning chi
    incolla il suo address (nome@wallet) invece di una richiesta: la
    richiesta della cifra esatta la chiede il server al suo wallet, con
    lo stesso `invoice_da_ln_address` degli incassi del mercatino (forma
    giudicata, niente redirect, cifra riletta). Il browser non puo'
    farlo da se': la CSP non lo lascia bussare a un dominio qualunque.
    L'address e la fattura non si scrivono da nessuna parte. LIMITE
    DICHIARATO, come per gli ordini: un server manomesso potrebbe dare
    una fattura sua; il telefono la rilegge comunque (cifra, rete,
    scadenza) col giudice del fornitore prima di far nascere il cambio."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not cambio_libero_per(user["id"]) or "btc-ln" not in cambio_strade():
        raise HTTPException(403, "Lo swap da bitcoin a Lightning non è acceso")
    _frena("ln_address", user["id"])
    d = await leggi_json(req)
    address = str(d.get("address") or "").strip()
    if address.lower().startswith("lightning:"):
        address = address[10:].strip()
    cifra = _cambio_sats(d.get("sats"))
    if not cifra or cifra < int(SWAP_MIN_SATS or 0) or (
            int(CAMBIO_LIBERO_MAX_SATS or 0) and cifra > int(CAMBIO_LIBERO_MAX_SATS)):
        raise HTTPException(400, "Cifra della richiesta fuori misura")
    try:
        pr = await invoice_da_ln_address(address, cifra)
    except LnbitsMuto:
        raise HTTPException(503, "Adesso non riusciamo a leggere la richiesta: "
                                 "riprova fra poco, o incollane una creata dal wallet")
    if not pr:
        raise HTTPException(409, f"Il tuo Lightning address non ha dato una "
                                 f"richiesta da {_fmt_sats(cifra)} sats: "
                                 "incollane una creata dal wallet")
    return {"ok": True, "fattura": pr}

# --- IL VOLUME DEL CAMBIO NEL PANNELLO (11 nov 2026, cantiere volume-cambio)
# Andrea, il giorno in cui il Cambio si apre a tutti: «metti una sezione
# dove vediamo quanto volume gli utenti hanno scambiato nella sezione
# cambio». Il biglietto dice solo che lo swap e' NATO presso il fornitore:
# la fattura la paga l'utente col suo wallet, e Barattolo da solo non sa se
# l'ha pagata. Un volume fatto di biglietti conterebbe anche chi ha chiuso
# la pagina davanti alla fattura. Per questo LA RONDA DEGLI ESITI chiede al
# fornitore lo stato di ogni cambio nato (`swap_stato_di`: il solo numero
# dello swap, niente chiavi, niente utente) finche' non e' finito, e lo
# scrive nella riga. Il pannello conta i FATTI, e accanto dice quanti sono
# ancora in corso e quanti non sono andati: un numero che si legge senza
# dover sapere come e' fatto.
# Quando e' fatto: Lightning → bitcoin quando il fornitore incassa la
# fattura («invoice.settled»: succede solo dopo il ritiro dei bitcoin);
# bitcoin → Lightning quando ha pagato la fattura dell'utente
# («invoice.paid» e quel che viene dopo). I sats contati sono quelli dal
# lato Lightning, la cifra del biglietto: chi manda per Lightning → bitcoin,
# chi riceve per bitcoin → Lightning.
CAMBIO_ESITI_FATTI = {
    "ln-btc": ("invoice.settled",),
    "btc-ln": ("invoice.paid", "transaction.claim.pending",
               "transaction.claimed"),
}
CAMBIO_ESITI_NON_ANDATI = ("swap.expired", "invoice.expired",
                           "transaction.failed", "transaction.refunded",
                           "invoice.failedToPay", "transaction.lockupFailed",
                           "swap.sconosciuto")
# si guarda un cambio ogni dieci minuti, per tre giorni (un cambio vive
# al piu' un giorno: la scadenza del fornitore); dopo resta «non si sa»
CAMBIO_ESITO_OGNI_S = 600
CAMBIO_ESITO_GUARDA_S = 3 * 86400
CAMBIO_ESITO_PER_GIRO = 20


def cambio_esito_di(direzione: str, stato: str) -> str:
    """PURA: «fatto», «non_andato» o '' (ancora in corso) per lo stato
    che dice il fornitore."""
    if stato in CAMBIO_ESITI_FATTI.get(direzione, ()):
        return "fatto"
    if stato in CAMBIO_ESITI_NON_ANDATI:
        return "non_andato"
    return ""


async def ronda_esiti_cambi(adesso: int | None = None) -> int:
    """LA RONDA DEGLI ESITI: per i cambi nati negli ultimi tre giorni e
    senza esito, lo stato dal fornitore, uno ogni dieci minuti, al piu'
    venti per giro. Fornitore muto → si riprova dopo. Torna quanti esiti
    ha scritto."""
    adesso = int(adesso if adesso is not None else time.time())
    con = _cambi_db()
    try:
        righe = [dict(r) for r in con.execute(
            "SELECT id, direzione, fornitore, swap_id FROM cambi_liberi "
            "WHERE stato='nato' AND swap_id<>'' AND COALESCE(esito,'')='' "
            "AND creato>? AND COALESCE(esito_visto,0)<? "
            "ORDER BY COALESCE(esito_visto,0), id LIMIT ?",
            (adesso - CAMBIO_ESITO_GUARDA_S, adesso - CAMBIO_ESITO_OGNI_S,
             CAMBIO_ESITO_PER_GIRO))]
    finally:
        con.close()
    scritti = 0
    for r in righe:
        f = swap_fornitore(str(r["fornitore"] or "satsrouting"))
        stato = await swap_stato_di(f, r["swap_id"]) if f else None
        esito = cambio_esito_di(r["direzione"], stato) if stato else ""
        con = _cambi_db()
        try:
            con.execute("UPDATE cambi_liberi SET esito=?, esito_visto=? "
                        "WHERE id=?", (esito, adesso, int(r["id"])))
            con.commit()
        finally:
            con.close()
        scritti += 1 if esito else 0
    return scritti


CAMBIO_PERIODI = (("7 giorni", 7 * 86400), ("30 giorni", 30 * 86400),
                  ("da sempre", 0))


def dati_cambi_cruscotto(adesso: int | None = None):
    """La card «🔁 Volume dello Swap» (fino al 12 nov 2026 «del Cambio») di `/admin`: per periodo e per
    direzione, i cambi FATTI (quanti, sats, persone diverse), e quanti
    sono in corso o non sono andati. Solo numeri: niente nomi, niente
    indirizzi. None = niente card (Cambio spento e nessun cambio nato)."""
    adesso = int(adesso if adesso is not None else time.time())
    con = _cambi_db()
    try:
        nati = con.execute("SELECT COUNT(*) FROM cambi_liberi "
                           "WHERE stato='nato'").fetchone()[0]
        if not CAMBIO_LIBERO_ATTIVO and not nati:
            return None
        periodi = []
        for nome, durata in CAMBIO_PERIODI:
            dal = adesso - durata if durata else 0
            riga = {"nome": nome, "strade": []}
            for strada in ("ln-btc", "btc-ln"):
                f = con.execute(
                    "SELECT COUNT(*), COALESCE(SUM(sats),0), "
                    "COUNT(DISTINCT tg_id) FROM cambi_liberi WHERE "
                    "stato='nato' AND direzione=? AND esito='fatto' AND "
                    "creato>=?", (strada, dal)).fetchone()
                altri = dict(con.execute(
                    "SELECT COALESCE(esito,''), COUNT(*) FROM cambi_liberi "
                    "WHERE stato='nato' AND direzione=? AND creato>=? "
                    "AND COALESCE(esito,'')<>'fatto' GROUP BY 1",
                    (strada, dal)).fetchall())
                riga["strade"].append({
                    "strada": strada, "fatti": int(f[0]), "sats": int(f[1]),
                    "persone": int(f[2]),
                    "in_corso": int(altri.get("", 0)),
                    "non_andati": int(altri.get("non_andato", 0))})
            tot = con.execute(
                "SELECT COUNT(DISTINCT tg_id) FROM cambi_liberi WHERE "
                "stato='nato' AND esito='fatto' AND creato>=?",
                (dal,)).fetchone()[0]
            riga["persone"] = int(tot)
            riga["sats"] = sum(x["sats"] for x in riga["strade"])
            riga["fatti"] = sum(x["fatti"] for x in riga["strade"])
            periodi.append(riga)
    finally:
        con.close()
    return {"attivo": bool(CAMBIO_LIBERO_ATTIVO), "periodi": periodi}


# --- PRENDERE UN ORDINE P2P LIGHTNING E RICEVERE ON-CHAIN (1 nov 2026,
# cantiere presa-altra-rete, tappa 1; studio del 30 ott, ok di Andrea del 1
# nov) ----------------------------------------------------------------------
# Chi COMPRA sats su un ordine Lightning di Mostro e ha solo un wallet
# bitcoin sceglie «₿ On-chain» nel foglio «Dove ricevere i sats». Il suo
# telefono fa nascere un cambio «reverse» di SATS Routing (lo stesso
# dell'incasso swap e del Cambio libero: chiave dal wallet di Barattolo,
# verifica della risposta, ritiro dal telefono) per la cifra ESATTA che
# Mostro gli deve, e a Mostro parte la fattura del cambio con
# l'`add-invoice` di sempre. Mostro non sa niente del cambio: al rilascio
# paga quella fattura, SATS Routing blocca i bitcoin e il telefono li
# ritira all'indirizzo scritto. Se il moderatore da' ragione a chi vende,
# la fattura non si paga mai e il cambio scade senza costare niente.
# Il server qui fa tre cose e nessuna tocca i sats: il PREVENTIVO (il conto
# di sempre, ma SENZA la nostra fee: la fattura deve portare la cifra di
# Mostro al sat), il BIGLIETTO (chi, quale scambio, quale swap: le sole
# parti pubbliche) e LA RONDA DELL'AVVISO: le chiavi stanno solo nel
# telefono, quindi se al rilascio l'app e' chiusa il ritiro aspetta;
# il server, che vede lo stato del cambio dal suo numero, manda UNA volta
# l'avviso del bot «apri Barattolo per ritirare i tuoi bitcoin». Senza
# ritiro il cambio scade, il pagamento di Mostro torna indietro e Mostro
# chiede una fattura nuova: i sats non si perdono.
P2P_CAMBI_STATI = ("chiesto", "nato", "annullato", "finito")
# quanti biglietti vivi per scambio: il primo, e quelli di una «fattura
# nuova» dopo un cambio scaduto
P2P_CAMBI_PER_SCAMBIO = 3
# gli stati del cambio in cui i bitcoin sono gia' bloccati e aspettano il
# ritiro del telefono: e' il momento dell'avviso
P2P_CAMBIO_DA_RITIRARE = ("transaction.mempool", "transaction.confirmed")
# ...e quelli in cui il cambio e' finito, bene o male: la ronda lo lascia
P2P_CAMBIO_FINITI = ("invoice.settled", "swap.expired", "invoice.expired",
                     "transaction.failed", "transaction.refunded",
                     "swap.sconosciuto")
# la ronda guarda i cambi nati negli ultimi otto giorni (la vita di un
# ordine nel libro, 168 ore, piu' la garanzia): dopo, non c'e' piu' niente
P2P_CAMBIO_GUARDA_S = 8 * 86400
P2P_BOTTONE_RITIRO = "₿ Ritira i tuoi bitcoin"
_lucchetto_cambi_p2p = asyncio.Lock()


def p2p_altra_rete_tetto() -> int:
    """Il massimo in sats dei cambi dell'altra rete, ADESSO: con
    P2P_ALTRA_RETE_MAX_EURO sopra 0 sono quegli euro al cambio di adesso
    (la cache, mai la rete: la tiene fresca `orologio_cambio`); senza
    tetto in euro, o senza cambio, il tetto in sats di sempre. 0 = solo il
    massimo del fornitore. Un solo giudice per i preventivi, i biglietti
    e la busta del telefono: due conti diversi direbbero «sì» al
    preventivo e «no» al biglietto."""
    euro = int(P2P_ALTRA_RETE_MAX_EURO or 0)
    if euro > 0:
        cambio = cambio_noto_ora()
        if cambio > 0:
            return int(round(euro * 100_000_000 / cambio))
    return int(P2P_ALTRA_RETE_MAX_SATS or 0)


def p2p_altra_rete_leve(tg_id: int) -> dict:
    """La busta per `/api/me` → `swap_leve.p2p`: il cancello e i tetti."""
    return {"attivo": p2p_altra_rete_per(tg_id),
            # (caso 4) il cambio bitcoin → Lightning prima della presa
            "presa": p2p_presa_cambio_per(tg_id),
            "minimo": int(SWAP_MIN_SATS or 0),
            "massimo": p2p_altra_rete_tetto()}


def _cambi_p2p_prepara(con):
    """`cambi_p2p`: un biglietto per cambio, legato allo scambio di Mostro."""
    con.execute("""CREATE TABLE IF NOT EXISTS cambi_p2p(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tg_id INTEGER NOT NULL,
        ordine TEXT NOT NULL,
        sats INTEGER NOT NULL,
        fornitore TEXT NOT NULL,
        swap_id TEXT DEFAULT '',
        impronta TEXT DEFAULT '',
        indirizzo TEXT DEFAULT '',
        onchain INTEGER DEFAULT 0,
        stato TEXT DEFAULT 'chiesto',
        visto TEXT DEFAULT '',
        avvisato INTEGER DEFAULT 0,
        creato INTEGER DEFAULT 0,
        aggiornato INTEGER DEFAULT 0)""")
    con.execute("CREATE INDEX IF NOT EXISTS cambi_p2p_ordine ON "
                "cambi_p2p(ordine, tg_id)")
    con.execute("CREATE UNIQUE INDEX IF NOT EXISTS cambi_p2p_swap ON "
                "cambi_p2p(fornitore, swap_id) WHERE swap_id <> ''")


def _cambi_p2p_db():
    con = db()
    _cambi_p2p_prepara(con)
    return con


def cambi_p2p_vivi(con, tg_id: int, ordine: str, adesso: int) -> int:
    """QUANTI CAMBI VIVI ha questa persona su questo scambio: i «nati» non
    finiti e i «chiesti» ancora freschi (un quarto d'ora, come il cambio
    libero: un telefono spento a meta' non brucia un posto per sempre)."""
    r = con.execute(
        "SELECT COUNT(*) FROM cambi_p2p WHERE tg_id=? AND ordine=? AND "
        "(stato='nato' OR (stato='chiesto' AND creato>?))",
        (int(tg_id), str(ordine), int(adesso) - CAMBIO_CHIESTO_VALE_S)).fetchone()
    return int(r[0] if r else 0)


@app.get("/api/swap/p2p/preventivo")
async def p2p_cambio_preventivo(sats: str = "", fornitore: str = "satsrouting",
                                hash: str = "",
                                x_tg_init_data: str = Header(""),
                                barattolo_sessione: str = Cookie("")):
    """IL PREVENTIVO DEL CAMBIO DI UNO SCAMBIO P2P: `sats` e' la cifra che
    Mostro paghera' (quella della fattura, al sat), il conto dice quanto
    arriva all'indirizzo. SENZA la nostra fee (`preventivo_swap` con 0):
    con la fee la fattura porterebbe meno di quel che Mostro pretende, e
    lui la rifiuterebbe. Non crea niente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not p2p_altra_rete_per(user["id"]):
        raise HTTPException(403, "Lo swap non è disponibile")
    chi = swap_fornitore(str(fornitore or ""))
    if chi is None:
        raise HTTPException(404, "Fornitore sconosciuto")
    cifra = _cambio_sats(sats)
    busta = {"dovuto": cifra, "fornitore": chi["id"],
             "fornitore_nome": chi["nome"]}
    if not cifra:
        return dict(busta, ok=False, motivo="cifra")
    tariffa = await leggi_tariffa_swap(chi)
    if tariffa is None:
        return dict(busta, ok=False, motivo="non_risponde")
    p = preventivo_swap(cifra, tariffa, 0, SWAP_MIN_SATS, p2p_altra_rete_tetto())
    p["cambiata"] = bool(hash) and hash != tariffa["hash"]
    p["valido_s"] = SWAP_PREVENTIVO_VALE_S
    return dict(busta, **p)


@app.post("/api/swap/p2p")
async def p2p_cambio_biglietto(req: Request, x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """IL BIGLIETTO: il telefono lo chiede PRIMA di chiedere lo swap al
    fornitore, con lo scambio di Mostro e la cifra. Dentro un lucchetto:
    il cancello, la forma dello scambio, la cifra nei tetti, al piu'
    `P2P_CAMBI_PER_SCAMBIO` cambi vivi sullo stesso scambio. {ok, id} o
    {ok: false, motivo}."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not p2p_altra_rete_per(user["id"]):
        raise HTTPException(403, "Lo swap non è disponibile")
    d = await leggi_json(req)
    ordine = str(d.get("ordine") or "").strip()
    if not FORMA_ORDINE_P2P.fullmatch(ordine):
        return {"ok": False, "motivo": "ordine"}
    chi = swap_fornitore(str(d.get("fornitore") or "satsrouting"))
    if chi is None:
        return {"ok": False, "motivo": "fornitore"}
    cifra = _cambio_sats(d.get("sats"))
    if not cifra or cifra < int(SWAP_MIN_SATS or 0):
        return {"ok": False, "motivo": "sotto_minimo"}
    tetto = p2p_altra_rete_tetto()
    if tetto and cifra > tetto:
        return {"ok": False, "motivo": "sopra_tetto"}
    adesso = int(time.time())
    async with _lucchetto_cambi_p2p:
        con = _cambi_p2p_db()
        try:
            if cambi_p2p_vivi(con, user["id"], ordine, adesso) >= P2P_CAMBI_PER_SCAMBIO:
                return {"ok": False, "motivo": "troppi"}
            cur = con.execute(
                "INSERT INTO cambi_p2p(tg_id,ordine,sats,fornitore,stato,"
                "creato,aggiornato) VALUES(?,?,?,?,'chiesto',?,?)",
                (int(user["id"]), ordine, cifra, chi["id"], adesso, adesso))
            con.commit()
            cid = int(cur.lastrowid)
        finally:
            con.close()
    return {"ok": True, "id": cid}


def _cambio_p2p_mio(con, cid: int, tg_id: int):
    return con.execute("SELECT * FROM cambi_p2p WHERE id=? AND tg_id=?",
                       (int(cid), int(tg_id))).fetchone()


@app.post("/api/swap/p2p/{cid}/nato")
async def p2p_cambio_nato(cid: int, req: Request, x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """LO SWAP C'E': le sole parti pubbliche (id dello swap, impronta del
    segreto, indirizzo del lockup, quanto), come il cambio libero. Il
    biglietto passa a «nato» e da qui lo guarda la ronda dell'avviso.
    Idempotente sullo stesso swap; un biglietto di un altro e' 404. Niente
    cancello: un cambio nato prima di una leva spenta deve poter finire."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    swap_id = str(d.get("swap_id") or "").strip()
    impronta = str(d.get("impronta") or "").strip().lower()
    if not _SWAP_ID_FORMA.match(swap_id) or (
            impronta and not _SWAP_IMPRONTA_FORMA.match(impronta)):
        return {"ok": False, "motivo": "forma"}
    adesso = int(time.time())
    async with _lucchetto_cambi_p2p:
        con = _cambi_p2p_db()
        try:
            r = _cambio_p2p_mio(con, cid, user["id"])
            if not r:
                raise HTTPException(404, "Biglietto non trovato")
            if r["stato"] == "nato":
                return {"ok": r["swap_id"] == swap_id, "stato": "nato"}
            if r["stato"] != "chiesto":
                return {"ok": False, "motivo": r["stato"]}
            try:
                con.execute(
                    "UPDATE cambi_p2p SET stato='nato', swap_id=?, impronta=?,"
                    " indirizzo=?, onchain=?, aggiornato=? WHERE id=?",
                    (swap_id, impronta, str(d.get("indirizzo") or "")[:120],
                     int(d.get("onchain") or 0), adesso, int(cid)))
                con.commit()
            except sqlite3.IntegrityError:
                return {"ok": False, "motivo": "doppio"}
        finally:
            con.close()
    return {"ok": True, "stato": "nato"}


@app.post("/api/swap/p2p/{cid}/annulla")
async def p2p_cambio_annulla(cid: int, x_tg_init_data: str = Header(""),
                             barattolo_sessione: str = Cookie("")):
    """LA NASCITA NON E' ANDATA: il biglietto torna libero. Solo un «chiesto»."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    async with _lucchetto_cambi_p2p:
        con = _cambi_p2p_db()
        try:
            r = _cambio_p2p_mio(con, cid, user["id"])
            if not r:
                raise HTTPException(404, "Biglietto non trovato")
            if r["stato"] != "chiesto":
                return {"ok": False, "motivo": r["stato"]}
            con.execute("UPDATE cambi_p2p SET stato='annullato', aggiornato=? "
                        "WHERE id=?", (int(time.time()), int(cid)))
            con.commit()
        finally:
            con.close()
    return {"ok": True, "stato": "annullato"}


def _testo_ritiro_p2p(r) -> str:
    """PURA: l'avviso di chi deve ritirare i bitcoin di un cambio P2P."""
    onchain = int(r["onchain"] or 0)
    quanti = f" ({_fmt_sats(onchain)} sats)" if onchain > 0 else ""
    return ("₿ I bitcoin del tuo scambio P2P sono pronti" + quanti + ".\n"
            "Apri Barattolo per ritirarli sul tuo indirizzo: il ritiro lo "
            "fa il tuo telefono. Se non lo apri in tempo lo swap scade, "
            "i sats tornano fermi al sicuro e ti chiediamo una fattura nuova.")


async def ronda_cambi_p2p(adesso: int | None = None) -> int:
    """LA RONDA DELL'AVVISO: per ogni cambio P2P nato e non ancora finito,
    lo stato dal fornitore (`swap_stato_di`, dal solo numero dello swap:
    niente chiavi). Bitcoin bloccati e avviso non ancora mandato → UN
    avviso a chi deve ritirare, col bottone sullo scambio. Cambio finito
    → la riga si chiude. Fornitore muto → si riprova al giro dopo. Torna
    quanti avvisi ha mandato."""
    adesso = int(adesso if adesso is not None else time.time())
    con = _cambi_p2p_db()
    try:
        righe = [dict(r) for r in con.execute(
            "SELECT * FROM cambi_p2p WHERE stato='nato' AND creato>? "
            "ORDER BY id LIMIT 50", (adesso - P2P_CAMBIO_GUARDA_S,))]
    finally:
        con.close()
    mandati = 0
    for r in righe:
        f = swap_fornitore(str(r["fornitore"] or "satsrouting"))
        stato = await swap_stato_di(f, r["swap_id"]) if f else None
        if not stato:
            continue
        # (caso 4) un cambio prima della presa e' un «submarine»: altri
        # stati, altre parole (`_avviso_presa_p2p`)
        presa = str(r["ordine"] or "").startswith("presa:")
        avviso = _avviso_presa_p2p(r, stato) if presa else None
        if presa:
            avvisa = avviso is not None and not r["avvisato"]
            finito = stato in P2P_PRESA_FINITI
        else:
            avvisa = stato in P2P_CAMBIO_DA_RITIRARE and not r["avvisato"]
            finito = stato in P2P_CAMBIO_FINITI
        if avvisa:
            try:
                # (tappa 3) un cambio del deposito di uno scambio on-chain
                # ha le sue parole e il suo bottone (`_avviso_ritiro_p2p`)
                testo, bottone = avviso if presa else _avviso_ritiro_p2p(r)
                esito = await notifica(int(r["tg_id"]), testo, bottone)
            except Exception as e:
                esito = f"SALTATO ({type(e).__name__}: {e})"
            mandati += 1
            print(f"₿ Cambio P2P {r['ordine'][:8]} di {r['tg_id']}: "
                  f"{stato if presa else 'bitcoin bloccati'}, avviso {esito}",
                  flush=True)
        if avvisa or finito or stato != r["visto"]:
            con = _cambi_p2p_db()
            try:
                con.execute(
                    "UPDATE cambi_p2p SET visto=?, avvisato=?, stato=?, "
                    "aggiornato=? WHERE id=?",
                    (stato, 1 if (avvisa or r["avvisato"]) else 0,
                     "finito" if finito else "nato", adesso, int(r["id"])))
                con.commit()
            finally:
                con.close()
    return mandati


_TASK_CAMBI_P2P = None   # stesso patto di _TASK_ONCHAIN: il riferimento tiene vivo il task


async def orologio_cambi_p2p():
    """Ogni due minuti la ronda dell'avviso. Gira anche a leva spenta: un
    cambio nato prima di spegnerla deve poter finire col suo avviso; senza
    cambi nati la ronda non chiama nessuno."""
    while True:
        await asyncio.sleep(120)
        try:
            await ronda_cambi_p2p()
        except Exception as e:
            print(f"⚠️ Cambi P2P: ronda saltata: {e}", flush=True)
        # (11 nov 2026, volume-cambio) e gli esiti dei cambi della
        # pagina Cambio, per il pannello: senza cambi nati non chiama nessuno
        try:
            await ronda_esiti_cambi()
        except Exception as e:
            print(f"⚠️ Cambio: ronda degli esiti saltata: {e}", flush=True)


@app.on_event("startup")
async def avvia_cambi_p2p():
    global _TASK_CAMBI_P2P
    _TASK_CAMBI_P2P = asyncio.create_task(orologio_cambi_p2p())


@app.post("/api/orders/{ordine_id}/invoice")
async def deposita_invoice(ordine_id: int, req: Request,
                           x_tg_init_data: str = Header(""),
                           barattolo_sessione: str = Cookie("")):
    """Deposita una invoice Lightning sull'ordine, e SOLO quando il
    pagamento parte subito (21 set 2026, deciso con Alan):
    - il VENDITORE a ordine 'confirmed', per incassare: importo =
      prezzo - commissione, e i sats partono immediatamente
    - l'ACQUIRENTE (stato refund, disputa vinta) per il rimborso:
      importo = prezzo pieno; il rimborso parte immediatamente.

    PRIMA DELLA CONFERMA LA FATTURA NON SI ACCETTA PIU'. Fino a ieri il
    venditore poteva incollarla da 'locked' e 'shipped', e restava in
    colonna per giorni: le fatture dei wallet durano da un'ora a sette
    giorni, e il #152 e' arrivato al payout scaduto da quattro. Il
    metodo che si imposta IN ANTICIPO e' uno solo, il Lightning address,
    che non scade; la fattura e' il gesto di chi non ce l'ha, e si fa
    quando tocca. Gli ordini che una fattura in colonna ce l'hanno GIA'
    non si toccano: `_sblocca_sats` la paga come ieri, e se e' scaduta
    la cintura di `paga_venditore` non la tenta e se ne chiede una nuova.
    ⚠️ I commenti sparsi che dicono «deposita_invoice accetta il
    venditore proprio su 'locked'» raccontano il mondo di ieri: le
    ancore che difendono (mai `aggiornato`) restano giuste lo stesso."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    bolt11 = pulisci_fattura(d.get("invoice"))
    if not bolt11.lower().startswith("ln"):
        raise HTTPException(400, "Questa non sembra una invoice Lightning")

    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=?", (ordine_id,)).fetchone()
    # LA FATTURA CHIESTA DA UN MODERATORE (21 set 2026, «paga da un'altra
    # cassaforte»): il payout e' congelato, il pagamento d'origine e'
    # morto e ci serve una fattura NUOVA per pagare da un'altra strada.
    # Un ordine finito in volo dal ramo mite e' rimasto 'locked' o
    # 'shipped' — lo stato non cambia finche' i sats non arrivano — e
    # senza questa riga la porta gli direbbe «troppo presto» mentre
    # aspettiamo proprio lui (trovato dal collaudo col server vero).
    # Vale SOLO a richiesta fatta: senza, la porta resta quella di ieri.
    # (CHI bussa lo guardano le due righe qui sotto, come sempre: questa
    # dice solo se la porta e' stata aperta da noi)
    chiesta_da_noi = bool(
        o and o["payout_stato"] == "incerto"
        and (o["payout_verso"] or "") == "venditore"
        and (lambda u: u.get("passo") == PASSO_SERVE
             and u.get("motivo") == MOTIVO_ALTRA_CASSAFORTE)(
                 _ultimo_passo(con, "ordini", ordine_id) or {}))
    if o and o["venditore_id"] == user["id"] and not chiesta_da_noi \
            and o["stato"] in ("locked", "shipped", "delivered"):
        # troppo presto: si dice perche', PRIMA di scomodare LNbits
        con.close()
        raise HTTPException(400, MSG_FATTURA_PRESTO)
    if o and o["venditore_id"] == user["id"] and (
            o["stato"] == "confirmed" or chiesta_da_noi):
        # L'incasso del venditore: il totale meno la protezione (che
        # resta alla piattaforma), cioe' articolo + spedizione.
        ruolo, atteso, colonna = "venditore", \
            netto_venditore(o["prezzo_sats"] - o["protezione_sats"]), \
            "invoice_venditore"
        spiegazione = f"{_fmt_sats(atteso)} sats (il tuo incasso)"
    elif o and o["compratore_id"] == user["id"] and o["stato"] == "refund":
        # la cifra del giudice unico: col quarto esito (13 ott 2026)
        # non e' piu' il totale, e una fattura del totale va rifiutata
        # col numero giusto invece che pagata
        ruolo, atteso, colonna = ("compratore", importo_rimborso(o),
                                  "invoice_rimborso")
        spiegazione = (f"{_fmt_sats(atteso)} sats (rimborso dei codici "
                       f"non pagati)"
                       if int(_campo(o, "codici_venditore", 0) or 0) else
                       f"{_fmt_sats(atteso)} sats (rimborso meno le spese "
                       f"di spedizione)"
                       if int(_campo(o, "spese_rese_sats", 0) or 0)
                       else f"{_fmt_sats(atteso)} sats (rimborso integrale)")
    else:
        con.close()
        raise HTTPException(400, "Operazione non permessa")

    try:
        importo_sats = await importo_invoice(bolt11)
    except LnbitsMuto:
        con.close()      # e la colonna resta com'era: chi ha incollato
        #                  una fattura buona non la perde per un guasto
        #                  nostro, e non gli si dice che e' sbagliata
        raise HTTPException(503, MSG_LNBITS_MUTO)
    if importo_sats is None:
        con.close()
        raise HTTPException(400, "Invoice non valida o illeggibile")
    if importo_sats == 0:
        con.close()
        raise HTTPException(400, MSG_FATTURA_SENZA_IMPORTO.format(
            cifra=spiegazione))
    if importo_sats != atteso:
        con.close()
        raise HTTPException(400,
            f"Importo sbagliato: la invoice e' di {_fmt_sats(importo_sats)} sats, "
            f"deve essere esattamente {spiegazione}")
    # LA SCADENZA SI GUARDA QUI, non il giorno del payout (20 set 2026,
    # ordine #152: incollata alla spedizione, pagata quattro giorni
    # dopo, scaduta da quattro). Da questa porta i sats partono SEMPRE
    # appena la si accetta: basta il margine di chi paga subito.
    no = rifiuto_scadenza(bolt11)
    if no:
        con.close()
        raise HTTPException(400, no)

    congelato = ruolo == "venditore" and o["payout_stato"] == "incerto"
    chiesta = chiesta_da_noi
    if ruolo == "venditore":
        # LA SCADENZA DELLA VECCHIA, prima che la nuova la copra (21 set
        # 2026): se in colonna c'e' la fattura di un tentativo gia'
        # fatto, quando scadeva e' l'unica cosa che un giorno si potra'
        # sapere di quel pagamento — e da domani non la sa piu' nessuno.
        try:
            _trascrivi_scadenza(con, ordine_id)
            if chiesta:
                # la riga che spegne il gesto: la fattura c'e'
                _segna_passo(con, "ordini", ordine_id,
                             PASSO_IN_VERIFICA, MOTIVO_FATTURA_NUOVA)
        except Exception as e:
            print(f"⚠️ Ordine #{ordine_id}: scadenza della fattura di "
                  f"prima non trascritta ({e})")
    con.execute(f"UPDATE ordini SET {colonna}=?, aggiornato=? WHERE id=?",
                (bolt11, int(time.time()), ordine_id))
    con.commit()
    con.close()

    if ruolo == "compratore":                      # rimborso: parte subito
        return await _rimborsa_compratore(ordine_id)
    if congelato:
        # A PAGAMENTO CONGELATO DA QUI NON PARTE NIENTE, ed e' giusto: la
        # fattura resta in colonna e a farla pagare — da un'altra
        # cassaforte, dopo aver provato che il pagamento di prima e'
        # morto — e' un moderatore. Se l'aveva chiesta lui, lo sa subito.
        if chiesta:
            try:
                await notifica_admin(
                    f"📥 <b>Ordine #{ordine_id}: chi vende ha incollato la "
                    f"fattura nuova.</b> Dal Profilo, in «🧊 Pagamenti da "
                    f"verificare», adesso «Paga da un'altra cassaforte» "
                    f"può partire. Una fattura scade: meglio non aspettare.",
                    argomento="errori")
            except Exception as e:
                print(f"⚠️ Avviso ai moderatori non partito: {e}")
        return {"ok": False, "stato": o["stato"], "incerto": True,
                "attende_moderatore": True}
    return await _sblocca_sats(ordine_id)          # incasso: parte subito


# Un lucchetto per ordine: sblocco e rimborso MUOVONO FONDI e possono
# partire insieme da strade diverse (orologio, conferma dell'acquirente,
# invoice appena depositata). Il server e' un processo solo: il lucchetto
# asyncio mette le chiamate in fila, e la guardia sullo stato fa uscire
# a mani vuote chi arriva a cose gia' fatte. Senza, due invoice diverse
# (via Lightning address) potrebbero essere pagate entrambe.
_lucchetti_ordine = defaultdict(asyncio.Lock)


async def _sblocca_sats(ordine_id: int, automatico: bool = False) -> dict:
    """Consegna i sats al venditore, provando in ordine:
    1. la invoice che il venditore ha eventualmente depositato
    2. INCASSO AUTOMATICO: il suo Lightning address (se impostato)
    3. altrimenti l'ordine resta 'confirmed' e il venditore viene
       avvisato di fornire una invoice o impostare il suo address.
    Se un pagamento fallisce (es. invoice scaduta), i sats restano
    al sicuro in cassaforte e si riprova con metodo nuovo."""
    async with _lucchetti_ordine[ordine_id]:
        con = db()
        o = con.execute("SELECT * FROM ordini WHERE id=?", (ordine_id,)).fetchone()
        if not o:
            con.close()
            return {"ok": False, "stato": "?"}
        if o["stato"] in ("released", "refunded", "refund", "creato", "annullato"):
            con.close()          # gia' risolto (o mai pagato): niente doppioni
            return {"ok": o["stato"] == "released", "stato": o["stato"]}
        # LA CINTURA DEL QUARTO ESITO (13 ott 2026): un ordine deciso
        # «rimborso meno le spese» ha gia' le sue DUE uscite — il
        # rimborso ridotto a chi compra e la riga di spese a chi vende —
        # e il netto intero al venditore sarebbe una terza. Ci si
        # arriverebbe solo da una corsa (un altro moderatore che decide
        # «al venditore» nello stesso istante, con la riga letta prima):
        # qui la riga e' quella fresca, sotto il lucchetto.
        if int(_campo(o, "spese_rese_sats", 0) or 0) > 0:
            con.close()
            return {"ok": False, "stato": o["stato"], "meno_spese": True}
        if o["payout_stato"] in ("incerto", "in_volo"):
            con.close()   # un pagamento in volo di cui non sappiamo l'esito:
            #               finche' non si sa com'e' finito, qui non si paga
            return {"ok": False, "stato": o["stato"], "incerto": True}
        # L'ON-CHAIN (27 ott 2026, strada A): qui non si paga niente. I
        # sats escono dal 2-di-3 solo con le due firme dei telefoni, e a
        # transazione partita `onchain_ordine_firma` torna qui: allora
        # si chiude l'ordine come un Lightning riuscito (stato, conti,
        # XP, avvisi). Prima di allora — un timer, un moderatore, un
        # Lightning address appena salvato — si esce senza toccare
        # niente, e lo si dice.
        # (il letterale e non CASSAFORTE_ONCHAIN: i banchi di prove.py
        # eseguono questa funzione da sola, e sul Lightning il giudice
        # on-chain non deve nemmeno essere nominato)
        oc = (_onchain_uscita_fatta(con, o, "venditore")
              if (_campo(o, "cassaforte") or "") == "onchain" else None)
        if oc is False:
            con.close()
            return {"ok": False, "stato": o["stato"], "onchain": True}
        # LO STADIO «IN PAGAMENTO» COMINCIA QUI (set 2026): la decisione
        # e' presa — una conferma, un timer, un moderatore — e da questa
        # riga in giu' consegnare i sats tocca a noi. `primo_passo` e'
        # vero in un giro solo, ed e' il «primo giro» degli avvisi nuovi.
        primo_passo = _segna_deciso(con, ordine_id, o, automatico)
        v = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                        (o["venditore_id"],)).fetchone()
        # Al venditore va articolo + spedizione: la protezione del
        # compratore resta in cassaforte, alla piattaforma. Sugli
        # ordini di ieri la quota e' 0 e non cambia nulla.
        netto = netto_venditore(o["prezzo_sats"] - o["protezione_sats"])
        if oc:
            # on-chain al venditore e' andato il prezzo dell'ordine, quello
            # che la transazione firmata dice (`_onchain_psbt_giudica`)
            netto = oc["prezzo_sats"]
        # LA PORTA DEL TIMER: il timbro di questo giro, 0 se a chiamare
        # e' stata una persona. Si scrive in TUTTI E DUE i rami qui
        # sotto — anche in quello riuscito, dove non apre niente — o il
        # nome direbbe una mezza verita' e il censimento dei timer
        # sarebbe monco. Il MAX e' l'idioma di quantita_max: una
        # chiamata non automatica non cancella mai un timbro gia' li'.
        auto_il = int(time.time()) if automatico else 0

        # Con 'uscito' il pagamento e' GIA' partito e un moderatore
        # l'ha verificato su LNbits: non si conia nessuna fattura e
        # non si chiama il nodo, si va dritti al ramo riuscito.
        bolt11 = ""
        taccuino = {"etichetta": f"Incasso del venditore sull'ordine "
                                 f"#{ordine_id}"}
        # (2 nov 2026, swap-auto) CHI HA SCELTO I BITCOIN ON-CHAIN nel
        # Profilo non riceve sul Lightning address: l'ordine resta
        # 'confirmed' e chi vende conferma il cambio dall'ordine (Alan:
        # «in automatico, previa conferma»). Una fattura incollata vince
        # (e' un suo gesto), e sotto il minimo del cambio si paga in
        # Lightning come sempre (`swap_auto_aspetta`).
        # (9 nov 2026, incasso-annuncio) il modo e' quello dell'ORDINE:
        # la scelta dell'annuncio vince su quella del Profilo
        modo_ln = incasso_ln_ordine(con, o)
        aspetta_onchain = bool(not oc and not o["invoice_venditore"]
                               and o["payout_stato"] != "uscito"
                               and swap_auto_aspetta(con, o["venditore_id"],
                                                     netto, modo_ln))
        try:
            if o["payout_stato"] != "uscito" and not oc:
                bolt11 = o["invoice_venditore"]
                if not bolt11 and v and v["ln_address"] and not aspetta_onchain:
                    bolt11 = await invoice_da_ln_address(v["ln_address"], netto)
            esito = (PAGATO if o["payout_stato"] == "uscito" or oc
                     else await paga_venditore(bolt11, netto, taccuino,
                                               cassaforte=_cassaforte_uscita(o),
                                               riga=("ordini", ordine_id,
                                                     "venditore"))
                     if bolt11 else NON_PAGATO)
        except LnbitsMuto as e:
            print(f"🔁 Ordine #{ordine_id}: {e}")
            esito = NON_CHIESTO
        if esito == OCCUPATO:
            # un'altra mano sta pagando questa riga: NON la si tocca
            con.close()
            return {"ok": False, "stato": o["stato"], "in_volo": True}
        # Il diario si scrive PRIMA dei rami, e per tutti gli esiti: i
        # due timbri dello stato chiudono la connessione, quindi da
        # dentro quei rami non ci si tornerebbe piu'.
        _timbra_pagamento(con, "ordini", ordine_id, taccuino)
        if esito == INCERTO:
            # IL CANTIERE B: se quel pagamento ha un nome, non serve
            # nessuno — lo si richiede al battito dopo. Il tetto dei
            # tentativi e' il freno dell'anello: esaurito quello,
            # l'umano torna a essere la risposta giusta.
            # IL TIMBRO DEL TIMER ANCHE QUI (set 2026): senza, un ordine
            # chiuso da un timer e finito in volo tornerebbe dalla ronda
            # come chiamata NON automatica — e lo stadio direbbe «hai
            # confermato» a chi non ha confermato niente.
            con.execute("UPDATE ordini SET sbloccato_auto_il="
                        "MAX(sbloccato_auto_il, ?) WHERE id=?",
                        (auto_il, ordine_id))
            # ...E IL TETTO NON VALE PER I GUASTI NOSTRI: un tentativo
            # fallito per il ponte giu' passa di qui a OGNI ritentativo
            # (si aspetta che LND dica «mai partito»), e col tetto dal
            # sesto giro ogni attesa diventerebbe un 🧊 ai moderatori.
            guasto_in_corso = (_ultimo_passo(con, "ordini", ordine_id)
                               or {}).get("passo") == PASSO_GUASTO
            if (taccuino.get("risolvibile")
                    and (guasto_in_corso or (o["payout_tentativi"] or 0)
                         < MAX_TENTATIVI_PAYOUT)):
                _segna_passo(con, "ordini", ordine_id, PASSO_IN_VOLO)
                _in_volo(con, "ordini", ordine_id, "venditore")
                if primo_passo:
                    await _avvisa_in_pagamento(o, netto, automatico, True)
                return {"ok": False, "stato": o["stato"], "in_volo": True}
            _segna_passo(con, "ordini", ordine_id, PASSO_IN_VERIFICA)
            await _congela_pagamento(
                con, "ordini", ordine_id, bolt11, "venditore",
                f"Incasso del venditore sull'ordine #{ordine_id}: "
                f"<b>{_fmt_sats(netto)} sats</b>.",
                cassaforte=_cassaforte_uscita(o))
            if primo_passo:
                await _avvisa_in_pagamento(o, netto, automatico, True)
            return {"ok": False, "stato": o["stato"], "incerto": True}
        if esito == NON_CHIESTO:
            # Non si e' potuto chiedere: la riga resta ESATTAMENTE
            # com'era — stato, invoice del venditore, ancore — e ci
            # torna `riprova_pagamenti_sospesi`. Sta qui, DOPO l'INCERTO
            # e PRIMA del PAGATO, e non e' estetica: la sentinella di
            # `_rimborsa_sblocco` in prove.py affetta il sorgente da
            # «if esito == PAGATO:» in giu', e un ramo nuovo la' dentro
            # le farebbe leggere quel che non deve.
            # IL TIMBRO DEL TIMER SI SCRIVE ANCHE QUI, ed e' la riga che
            # impedisce alla cura di reintrodurre una bugia: senza,
            # l'ordine chiuso da un timer e ripreso dal giro tornerebbe
            # qui come chiamata NON automatica, e direbbe al venditore
            # «L'acquirente ha confermato la ricezione» — cioe' proprio
            # la famiglia di messaggi falsi che questo cantiere chiude.
            # I rami che lo scrivono diventano tre, come dice il commento
            # di `auto_il` qui sopra.
            con.execute("UPDATE ordini SET sbloccato_auto_il="
                        "MAX(sbloccato_auto_il, ?) WHERE id=?",
                        (auto_il, ordine_id))
            _sospendi_pagamento(con, "ordini", ordine_id, "venditore",
                                taccuino.get("motivo") or "")
            # E QUI NESSUNO SENTE NIENTE DEL GUASTO: il nodo giu' e'
            # affare nostro. Al primo giro le due parti sanno solo che
            # la decisione e' presa e che da qui ci pensiamo noi.
            if primo_passo:
                await _avvisa_in_pagamento(o, netto, automatico, True)
            return {"ok": False, "stato": o["stato"], "non_chiesto": True}

        if esito == PAGATO:
            # Il titolo di cortesia copre anche i set («primo + N altri»)
            titolo = html.escape(_titolo_ordine(_righe_ordine(con, o)))
            if titolo == "?":
                titolo = "il tuo acquisto"
            # (14 nov 2026, terzo giro dell'audit) il timbro del pagamento
            # si chiude QUI: il cambio puo' chiedere a CoinGecko fino a 10
            # secondi, e con la scrittura aperta tutto il database
            # aspetterebbe con lui
            con.commit()
            cambio = await cambio_btc_eur()
            # `payout_stato='uscito'` sul ramo riuscito (set 2026): da
            # qui in poi il vuoto vuol dire «mai provato» e basta —
            # prima diceva anche «riuscito», cioe' non diceva niente.
            con.execute("UPDATE ordini SET stato='released', cambio_eur=?, "
                        "payout_stato='uscito', "
                        "sbloccato_auto_il=MAX(sbloccato_auto_il, ?), "
                        "aggiornato=? WHERE id=?",
                        (cambio, auto_il, int(time.time()), ordine_id))
            _segna_passo(con, "ordini", ordine_id, PASSO_ARRIVATO)
            con.execute("UPDATE utenti SET vendite_ok=vendite_ok+1 WHERE tg_id=?",
                        (o["venditore_id"],))
            con.execute("UPDATE utenti SET acquisti_ok=acquisti_ok+1 WHERE tg_id=?",
                        (o["compratore_id"],))
            con.commit()
            con.close()
            invito = ("⭐ Com'è andata? Apri l'ordine nella Mini App "
                      "e lascia un feedback.")
            # (26 ott 2026, il giro sul regtest) SE ERA LA FATTURA DI UNO
            # SWAP i sats non arrivano «nel wallet» in Lightning: arrivano
            # on-chain, meno la rete del ritiro, e confermati o no. A chi
            # vende si dice quello; a chi compra non cambia niente.
            fine_swap = await _msg_swap_arrivato(
                ordine_id, o["invoice_venditore"] or bolt11, invito)
            if automatico:
                await notifica(o["venditore_id"], fine_swap or
                               f"🔓 <b>Sats sbloccati automaticamente!</b> Il tempo di "
                               f"conferma è scaduto senza problemi segnalati: "
                               f"<b>{_fmt_sats(netto)} sats</b> sono in arrivo nel tuo wallet. ⚡ "
                               f"{invito}")
                await notifica(o["compratore_id"],
                               f"✅ <b>Affare concluso:</b> «{titolo}». Il tempo per "
                               f"confermare o aprire una disputa è scaduto e i sats "
                               f"sono stati sbloccati al venditore. Grazie per aver "
                               f"usato Barattolo 🫙 {invito}")
            elif o["disputata"]:
                # Lo sblocco arriva da una disputa decisa al venditore:
                # il messaggio dice la verita', non «ha confermato».
                await notifica(o["venditore_id"], fine_swap or
                               f"⚖️ <b>La disputa è stata decisa a tuo favore:</b> "
                               f"<b>{_fmt_sats(netto)} sats</b> sono in arrivo nel tuo wallet. "
                               f"Affare concluso! ⚡ {invito}")
                await notifica(o["compratore_id"],
                               f"⚖️ <b>La disputa su «{titolo}» è stata decisa a "
                               f"favore del venditore:</b> i sats gli sono stati "
                               f"sbloccati. {invito}")
            elif not primo_passo:
                # «ARRIVATI ✓» (set 2026): chi vende aveva gia' sentito
                # «sono in arrivo» (o aspettava da un giro precedente),
                # quindi qui non gli si ridice che l'acquirente ha
                # confermato: gli si dice la sola cosa nuova.
                await notifica(o["venditore_id"], fine_swap or
                               f"✅ <b>Arrivati ✓</b> I tuoi "
                               f"<b>{_fmt_sats(netto)} sats</b> sono nel tuo "
                               f"wallet. Affare concluso! ⚡ {invito}")
                await notifica(o["compratore_id"],
                               f"✅ <b>Affare concluso:</b> «{titolo}». "
                               f"I sats sono arrivati al venditore. "
                               f"Grazie per aver usato Barattolo 🫙 {invito}")
            else:
                await notifica(o["venditore_id"], fine_swap or
                               f"🔓 <b>Sats sbloccati!</b> L'acquirente ha confermato la "
                               f"ricezione: <b>{_fmt_sats(netto)} sats</b> sono in arrivo nel tuo "
                               f"wallet. Affare concluso! ⚡ {invito}")
                await notifica(o["compratore_id"],
                               f"✅ <b>Affare concluso:</b> «{titolo}». "
                               f"Grazie per aver usato Barattolo 🫙 {invito}")
            # Un affare concluso puo' far scattare distintivi a
            # ENTRAMBE le parti (primo baratto, primo acquisto...)
            await premia_distintivi(o["venditore_id"])
            await premia_distintivi(o["compratore_id"])
            # ...e puo' far passare una soglia dei PREMI FEDELTA' del
            # negozio (17 nov 2026): l'avviso a tutti e due, il premio
            # si attacca al prossimo ordine pagato dei due
            await premia_fedelta_negozio(o["compratore_id"],
                                         o["venditore_id"])
            # ...e vale XP a tutti e due. Il cambio e' quello appena
            # scritto in colonna per l'export contabile: qui non
            # serve un secondo giro di rete. Il riferimento porta il
            # RUOLO, o le due parti si pesterebbero sulla UNIQUE.
            # SOLO su released: rimborsato vuol dire che la merce e'
            # tornata indietro e lo scambio non c'e' stato.
            for chi, ruolo in ((o["venditore_id"], "venditore"),
                               (o["compratore_id"], "compratore")):
                await premia_xp(chi, "ordine",
                                xp_ordine(o["prezzo_sats"], cambio, ruolo),
                                f"ordine:{ordine_id}:{ruolo}")
            # DOPO il giro degli XP e non dentro premia_distintivi qui
            # sopra: quello girava PRIMA che premia_xp scrivesse i punti
            # di QUESTO ordine, e avrebbe pubblicato un 30382 con l'XP
            # vecchio di un giro — la stessa lezione del cronometro che
            # riparte a ogni fase (vedi Mostro, docs/CANTIERI.md).
            for chi in (o["venditore_id"], o["compratore_id"]):
                await premia_reputazione_nostr(chi)
            # Il polso dei moderatori: ordine chiuso, sats consegnati
            if o["disputata"]:
                await polso_ordini_admin(
                    f"⚖️ <b>Disputa chiusa a favore del venditore:</b> "
                    f"«{titolo}» — {_fmt_sats(netto)} sats sbloccati. "
                    f"Restano {{aperti}} ordini aperti.")
            else:
                await polso_ordini_admin(
                    f"✅ <b>Ordine concluso:</b> «{titolo}» — {_fmt_sats(netto)} "
                    f"sats al venditore. Restano {{aperti}} ordini aperti.")
            return {"ok": True, "stato": "released"}

        # Niente pagamento riuscito: l'ordine resta/va in 'confirmed',
        # la invoice (se c'era) viene ripulita, il venditore avvisato.
        # 'confirmed' vuol dire «i sats spettano al venditore, manca il
        # modo di dargliglieli», che dopo una disputa decisa a suo
        # favore e' la verita' — e da li' deposita_invoice funziona.
        # Chi perdeva il controllo era il MODERATORE, e a rimetterlo in
        # gioco e' la coda di risolvi_disputa, che ora guarda anche qui.
        primo_giro = o["stato"] != "confirmed"
        # IL RITENTATIVO (cantiere B2). Si riprova da soli SOLO col
        # Lightning address, e la ragione e' la dedup di LNbits: una
        # bolt11 gia' fallita non si ripaga — a chiederlo due volte
        # torna l'eco del record vecchio — mentre ogni conio da un
        # address produce un payment hash NUOVO. Il timbro e' quello
        # di sempre, 'da_riprovare', il cui invariante e' «nessuna
        # fattura e' mai stata pagata»: ci si arriva per la strada del
        # quarto esito (non si e' chiesto) e ora anche per questa
        # (si e' chiesto e la risposta e' stata un no definitivo, senza
        # preimage). A distanziare i tentativi e' `_quando_ritentare`.
        # UN GUASTO NOSTRO NON HA TETTO (set 2026): il freno dei cinque
        # tentativi esiste per non bussare in eterno al wallet di un
        # terzo su una ROTTA che non c'e'; il saldo nostro che non basta
        # o il ponte giu' tornano da soli, e arrendersi li' vorrebbe
        # dire chiedere un gesto a chi non ha sbagliato niente. A
        # distanziare i giri e' `BACKOFF_NOSTRO`, letto dal passo.
        motivo_no = taccuino.get("motivo") or ""
        nostro = motivo_no in MOTIVI_NOSTRI
        ritenta = bool(taccuino.get("ritentabile") and v and v["ln_address"]
                       and (nostro or (o["payout_tentativi"] or 0)
                            < MAX_TENTATIVI_PAYOUT))
        # LA LINEA DEL TEMPO: cos'e' successo, e — se da soli non c'e'
        # piu' niente da tentare — che adesso serve un gesto di chi
        # vende. `gia_detto` dice se e' una notizia o una replica, e si
        # chiede PRIMA di segnare il passo.
        gia_detto = False
        if taccuino.get("ritentabile") or motivo_no:
            tipo = PASSO_GUASTO if nostro else PASSO_FALLITO
            gia_detto = _gia_detto(con, "ordini", ordine_id, tipo, motivo_no)
            _segna_passo(con, "ordini", ordine_id, tipo, motivo_no)
        if not ritenta:
            _segna_passo(con, "ordini", ordine_id, PASSO_SERVE,
                         motivo_no or ("fattura" if bolt11 else "metodo"))
        # IL VERSO SI SCRIVE COL TIMBRO (14 nov 2026, cantiere
        # audit-dispute). Qui si arriva anche SENZA aver preso la mano —
        # la fattura scaduta non si tenta nemmeno — e allora nessuno
        # aveva riscritto `payout_verso`: restava quello di IERI. Dopo
        # un rimborso rimasto a meta' e un moderatore che ci ripensa, il
        # giro leggeva «compratore» e rimborsava chi aveva perso
        # (riprodotto: `prove_disputa_cambia_strada`). Chi lascia un
        # 'da_riprovare' dice anche A CHI: e' il patto di
        # `_sospendi_pagamento`, e ora vale anche qui.
        con.execute("UPDATE ordini SET invoice_venditore='', stato='confirmed', "
                    "payout_stato=?, payout_verso=?, "
                    "sbloccato_auto_il=MAX(sbloccato_auto_il, ?), "
                    "aggiornato=? WHERE id=?",
                    ("da_riprovare" if ritenta else "", "venditore",
                     auto_il, int(time.time()), ordine_id))
        con.commit()
        con.close()
        # Chi ha perso la disputa ha diritto di saperlo, e UNA volta
        # sola: solo nel giro in cui l'ordine cambia stato davvero, o
        # ogni ritentativo fallito glielo ridirebbe.
        if o["disputata"] and primo_giro:
            await notifica(
                o["compratore_id"],
                "⚖️ <b>La disputa è stata decisa a favore del venditore.</b> "
                "I sats gli spettano; appena ci dà un modo per riceverli "
                "l'ordine si chiude. Se pensi che ci sia stato un errore, "
                "scrivi ai moderatori.")
        # E CHI NON HA DISPUTATO NIENTE, ma si e' visto chiudere
        # l'affare da un timer? Fino a ieri non riceveva NULLA: questo
        # ramo parlava solo a chi aveva perso una disputa, e il
        # messaggio del ramo riuscito qui non arriva mai. E' l'unica
        # cosa che quella persona riceve, quindi porta anche la
        # maniglia — e qui la porta esiste davvero, perche' i sats sono
        # ancora nostri (sul ramo 'released' invece non si invita
        # nessuno a scrivere: la' sarebbe una porta che non si apre).
        # UNA volta sola, nel giro in cui l'ordine cambia stato
        # davvero, come la gemella qui sopra.
        if automatico and primo_giro:
            await notifica(
                o["compratore_id"],
                f"⏳ <b>L'acquisto si è chiuso da solo:</b> il tempo per "
                f"confermare o aprire una disputa è scaduto. I sats "
                f"<b>non sono ancora usciti</b> — il venditore non ci ha dato "
                f"un modo per riceverli — quindi sono ancora nel deposito di "
                f"garanzia. Se quello che hai comprato non ha funzionato, "
                f"scrivi ai moderatori col numero dell'ordine "
                f"(<b>#{ordine_id}</b>): finché i sats sono lì, il caso si "
                f"può ancora decidere.")
        bottone = None    # solo l'avviso dello swap automatico ha il tasto
        if ritenta:
            msg = _msg_ritentiamo(netto, taccuino)
        elif bolt11 and _fattura_di_swap(ordine_id, bolt11):
            # (26 ott 2026, swap tappa 4) LA FATTURA ERA QUELLA DELLO SWAP:
            # chi vende non ha incollato niente, e «dacci una fattura nuova»
            # sarebbe un gesto che non ha mai fatto. Si sceglie di nuovo.
            msg = _msg_swap_non_andato(netto)
        elif taccuino.get("ritentabile") and v and v["ln_address"]:
            # LA RESA: si e' provato e riprovato, e la strada non c'e'.
            # Adesso l'invito ad agire e' giusto, perche' da soli non
            # abbiamo piu' niente da tentare.
            msg = ("⚠️ <b>Non siamo riusciti a consegnarti i sats.</b> "
                   "Abbiamo riprovato piu' volte e la rete Lightning non ha "
                   "trovato una strada fino al tuo wallet. I "
                   f"<b>{_fmt_sats(netto)} sats</b> sono tuoi e sono al sicuro "
                   "nel deposito di garanzia: apri l'ordine nella Mini App e "
                   "incolla una invoice di esattamente quell'importo, oppure "
                   "cambia il Lightning address nel Profilo e ci riproviamo.")
        elif taccuino.get("ritentabile"):
            # La fattura incollata a mano, bruciata: dirgli «riprova»
            # senza dirgli «con una NUOVA» lo manderebbe a incollare la
            # stessa, che LNbits non ripaghera' mai.
            # ...e il PERCHE' e' quello vero (20 set 2026): a Pedro,
            # ordine #152, questa riga disse «la rete non ha trovato una
            # strada» di una fattura scaduta da quattro giorni.
            msg = _msg_fattura_nuova(netto, taccuino)
        elif aspetta_onchain:
            # (2 nov 2026, swap-auto) ha scelto on-chain: il suo gesto e'
            # un «Conferma», non una fattura
            bottone = _bottone_swap_auto(ordine_id)
            msg = (_msg_swap_auto_scegli if modo_ln == "ogni_volta"
                   else _msg_swap_auto_conferma)(
                netto, "⚖️ <b>La disputa è stata decisa a tuo favore!</b>"
                if o["disputata"] else "⏳ <b>Il tempo di conferma è scaduto!</b>"
                if automatico else
                "✅ <b>L'acquirente ha confermato la ricezione!</b>")
        elif o["invoice_venditore"] or (v and v["ln_address"]):
            # Un metodo c'era, ma al nodo non ci siamo nemmeno arrivati:
            # non si dichiara un fallimento che non e' stato osservato.
            msg = ("⏳ <b>I tuoi sats non sono ancora partiti.</b> Non siamo "
                   "riusciti a completare il pagamento, e i sats restano nel "
                   "deposito di garanzia: apri l'ordine nella Mini App per "
                   f"riprovare con una invoice da <b>{_fmt_sats(netto)} "
                   "sats</b>.")
        else:
            # Tre casi e non due: sul ramo del timer nessuno ha
            # confermato niente — e' scaduto il tempo — e dirgli che
            # l'acquirente ha confermato sarebbe falso.
            testa = ("⚖️ <b>La disputa è stata decisa a tuo favore!</b>"
                     if o["disputata"] else
                     "⏳ <b>Il tempo di conferma è scaduto!</b>"
                     if automatico else
                     "✅ <b>L'acquirente ha confermato la ricezione!</b>")
            # «TOCCA A TE» (21 set 2026): la fattura si incolla ADESSO,
            # che si paga subito — non esiste piu' una fattura messa
            # da parte prima. L'address resta la strada che chiude il
            # problema, e si dice perche': non scade.
            msg = (f"{testa} <b>Tocca a te:</b> per ricevere "
                   f"i tuoi <b>{_fmt_sats(netto)} sats</b> apri l'ordine nella Mini App e "
                   f"incolla una fattura di esattamente quell'importo, fatta "
                   f"adesso (la paghiamo subito). Oppure imposta il tuo "
                   f"Lightning address: non scade mai, e da lì in poi gli "
                   f"incassi sono automatici. 💰")
        # A CHI COMPRA, al primo giro: la sua parte e' finita. A chi
        # vende qui NON si dice «in arrivo»: sta per ricevere il suo
        # messaggio, quello sopra, che e' piu' preciso.
        if primo_passo:
            await _avvisa_in_pagamento(o, netto, automatico, False)
        # UN RITENTATIVO CHE FALLISCE UGUALE NON E' UNA NOTIZIA (set
        # 2026): mentre ci riproviamo da soli chi vende sente il motivo
        # UNA volta, non a ogni giro — senza tetto ai tentativi sarebbe
        # un messaggio all'ora per tutto il tempo del guasto. Dove
        # invece serve un suo gesto lo si dice sempre.
        # (il tasto solo quando c'e': chi chiama notifica senza, la
        # chiama come l'ha sempre chiamata)
        if (not ritenta or not gia_detto) and bottone:
            await notifica(o["venditore_id"], msg, bottone)
        elif not ritenta or not gia_detto:
            await notifica(o["venditore_id"], msg)
        return {"ok": False, "stato": "confirmed", "ritenta": ritenta,
                "motivo": taccuino.get("motivo") or "",
                "scaduta": taccuino.get("scaduta") or ""}


# ------------- IL RIMBORSO MENO LE SPESE DI SPEDIZIONE ----------------
# (13 ott 2026, cantiere indirizzo-giusto, secondo push.) Il caso: chi
# compra sbaglia l'indirizzo — o il punto — e il pacco torna indietro.
# Fin qui il moderatore poteva solo rimborsare tutto, rimborsare dopo
# il reso o dare tutto a chi vende: le spese di spedizione restavano
# sempre a chi aveva spedito. Il quarto esito le rende a lui e rimborsa
# il resto. Sono DUE uscite dallo stesso deposito, e fino a ieri un
# ordine ne aveva una sola: per questo le due righe di denaro sono
# SEPARATE — il rimborso resta sull'ordine, la quota di chi vende va
# nel registro «da riscuotere» — e ognuna ha il suo lucchetto, i suoi
# tentativi e il suo stato. Una che fallisce non ferma l'altra.
MOTIVO_SPESE_RESE = "spese_spedizione"


def _quota_e_codici(con, ordine_id: int) -> bool:
    """La riga «da riscuotere» di chi vende con il motivo delle spese e'
    la sua quota di una DIVISIONE DEI CODICI (16 nov 2026)? Lo dice
    l'ordine (`codici_venditore`), e serve solo alle parole: il denaro
    fa la stessa strada. Fail-safe: nel dubbio, le parole di ieri."""
    if not ordine_id:
        return False
    try:
        r = con.execute("SELECT codici_venditore FROM ordini WHERE id=?",
                        (ordine_id,)).fetchone()
    except sqlite3.Error:
        return False
    return bool(r and int(r[0] or 0) > 0)

MSG_MENO_SPESE_DECISO = ("Questa disputa è già decisa: rimborso meno le "
                         "spese di spedizione. La decisione è definitiva.")
MSG_MENO_SPESE_DOVE = ("Il rimborso meno le spese di spedizione si decide "
                       "su una disputa aperta o su un reso in corso")
MSG_NIENTE_SPESE = ("Su questo ordine non c'è una spesa di spedizione da "
                    "trattenere: usa una delle altre decisioni")
# (15 ott 2026) la guardia di risolvi_disputa sull'annullo del venditore
MSG_RESO_PAGAMENTO_IN_CORSO = (
    "Su questo ordine c'è un pagamento di cui non sappiamo ancora l'esito: "
    "il reso si decide quando si sa com'è finito. Guardalo in «🧊 Pagamenti "
    "da verificare» o riprova fra qualche minuto")
MSG_ANNULLO_NON_DISPUTA = ("Questo ordine l'ha annullato il venditore: non "
                           "è una disputa e non si decide. I sats tornano "
                           "all'acquirente con il rimborso dell'annullo.")


def spese_trattenibili(o) -> int:
    """QUANTO si puo' trattenere per le spese di spedizione, o 0.

    La cifra e' `spedizione_sats`: quel che chi compra ha pagato
    DAVVERO per la spedizione, scritto nell'ordine alla fattura (dopo
    la promessa «gratis sopra soglia», quindi 0 se gliel'avevamo
    regalata). Zero — e il bottone non compare — in tre casi:
    · non e' una spedizione (ritiro, codice online, servizio: `casa`
      e `punto` invece si', tutte e due);
    · la spedizione era inclusa nel prezzo o gratuita: non c'e' una
      cifra, e NON se ne inventa una (niente importi scritti a mano dal
      moderatore: sarebbe il rimborso parziale, che e' un'altra cosa);
    · la spedizione e' UGUALE O PIU' GRANDE del totale: a chi compra
      tornerebbe zero, o meno di zero. Non succede con un ordine sano
      (il totale contiene la spedizione piu' l'articolo), ed e' la
      cintura per il giorno che un dato e' storto — Andrea l'ha voluta
      scritta, e c'e' la prova."""
    if (_campo(o, "consegna_scelta") or "") != "spedizione":
        return 0
    sped = int(_campo(o, "spedizione_sats", 0) or 0)
    totale = int(_campo(o, "prezzo_sats", 0) or 0)
    return sped if 0 < sped < totale else 0


def importo_rimborso(o) -> int:
    """QUANTO TORNA A CHI COMPRA: il totale, meno le spese trattenute
    se il moderatore ha deciso cosi'. UN GIUDICE per i tre posti che
    devono dire la stessa cifra — chi paga (`_rimborsa_compratore`),
    chi controlla la fattura incollata (`deposita_invoice`) e la
    pagina — o uno dei tre un giorno direbbe il totale."""
    return (int(_campo(o, "prezzo_sats", 0) or 0)
            - int(_campo(o, "spese_rese_sats", 0) or 0))


def _msg_meno_spese_compratore(importo: int, spese: int, pagato: bool) -> str:
    testa = ("⚖️ <b>Disputa decisa: rimborso meno le spese di "
             "spedizione.</b> ")
    coda = (f" Le spese di spedizione ({_fmt_sats(spese)} sats) restano "
            f"a chi ha spedito.")
    if pagato:
        return (testa + f"<b>{_fmt_sats(importo)} sats</b> sono in arrivo "
                f"nel tuo wallet." + coda + " ⭐ Com'è andata? Apri "
                "l'ordine nella Mini App e lascia un feedback.")
    return (testa + f"Per ricevere <b>{_fmt_sats(importo)} sats</b>: apri "
            f"l'ordine nella Mini App e imposta il tuo Lightning "
            f"address, oppure incolla una invoice di esattamente "
            f"quell'importo." + coda)


def _msg_codici_compratore(importo: int, pezzi_v: int, n: int,
                           pagato: bool) -> str:
    """LA DIVISIONE DEI CODICI (16 nov 2026), le parole di chi compra:
    quanto gli torna e perche'. Mai «a tuo favore»: e' una divisione."""
    testa = "⚖️ <b>Disputa decisa sui codici.</b> "
    resto = n - pezzi_v
    coda = (" Sono i sats "
            + ("del codice non pagato" if resto == 1
               else f"dei {resto} codici non pagati")
            + "; "
            + ("il codice confermato resta pagato" if pezzi_v == 1
               else f"i {pezzi_v} codici confermati restano pagati")
            + " a chi vende.")
    if pagato:
        return (testa + f"<b>{_fmt_sats(importo)} sats</b> sono in arrivo "
                f"nel tuo wallet." + coda + " ⭐ Com'è andata? Apri "
                "l'ordine nella Mini App e lascia un feedback.")
    return (testa + f"Per ricevere <b>{_fmt_sats(importo)} sats</b>: apri "
            f"l'ordine nella Mini App e imposta il tuo Lightning "
            f"address, oppure incolla una invoice di esattamente "
            f"quell'importo." + coda)


def _msg_codici_venditore(quota: int, pezzi_v: int, n: int,
                          pagato: bool) -> str:
    resto = n - pezzi_v
    return ("⚖️ <b>Disputa decisa sui codici.</b> Ti "
            + ("è pagato 1 codice" if pezzi_v == 1
               else f"sono pagati {pezzi_v} codici")
            + f" su {n}: <b>{_fmt_sats(quota)} sats</b>, da incassare "
            f"nell'ordine, nella Mini App. I sats "
            + ("dell'altro codice tornano" if resto == 1
               else f"degli altri {resto} tornano")
            + " a chi compra."
            + (" Quei pezzi sono tornati disponibili nell'annuncio."
               if pagato else ""))


def _msg_meno_spese_venditore(spese: int, pagato: bool) -> str:
    return ("⚖️ <b>Disputa decisa: rimborso meno le spese di "
            "spedizione.</b> All'acquirente "
            + ("è tornato" if pagato else "torna")
            + f" il resto; le spese di spedizione, <b>{_fmt_sats(spese)} "
            f"sats</b>, sono tue: le trovi da incassare nell'ordine, "
            f"nella Mini App."
            + (" L'annuncio è tornato in vetrina." if pagato else ""))


async def _rimborsa_meno_spese(ordine_id: int,
                               pezzi_venditore: int = 0) -> dict:
    """IL QUARTO ESITO: rimborso meno le spese di spedizione.

    E LA DIVISIONE DEI CODICI (16 nov 2026, cantiere
    codici-uno-alla-volta): con `pezzi_venditore` la quota di chi vende
    non sono le spese ma i suoi codici confermati
    (`quota_codici_venditore`). Le due uscite, i lucchetti, il timbro e
    la ronda del libro mastro sono gli stessi parola per parola: la
    colonna `spese_rese_sats` dice sempre «quanto NON torna a chi
    compra», e `codici_venditore` dice di che si tratta, per le parole.

    LA DECISIONE SI SCRIVE IN UNA TRANSAZIONE, i pagamenti partono
    DOPO. Nella transazione: la cifra sull'ordine (col CAS su
    `spese_rese_sats=0` e sullo stato, cosi' due tocchi non decidono
    due volte), la riga «da riscuotere» di chi vende, e il timbro
    'da_riprovare' su TUTT'E DUE le uscite — che vuol dire «nessun sat
    si e' mosso, si puo' bussare». E' quel timbro a reggere il caso del
    server che cade a meta': al riavvio le due righe ci sono gia', e il
    giro dei pagamenti (`riprova_pagamenti_sospesi`) riprende quella
    che non era ancora partita. Senza, un ordine resterebbe in disputa
    con la decisione presa e nessuno a pagarla.

    POI I DUE PAGAMENTI, INDIPENDENTI: ognuno dalla sua strada di
    sempre, col suo lucchetto. Uno che fallisce — o che esplode — non
    ferma l'altro, e ognuno lascia la sua riga nello stato che la sua
    strada prevede: l'ordine in 'refund' se chi compra non ha un
    metodo, la riga «da riscuotere» se non ce l'ha chi vende.

    MAI PIU' DEL DEPOSITO: le due cifre sommate fanno il totale
    pagato, per costruzione (la riga porta `spese`, il rimborso
    `importo_rimborso` = totale − spese), e la ronda del libro mastro
    lo ricontrolla.

    IL LUCCHETTO DELL'ORDINE, attorno alla sola scrittura: chi paga
    quell'ordine (`_rimborsa_compratore`, `_sblocca_sats`) lo tiene per
    tutto il suo giro, e la cifra la legge all'INIZIO — un rimborso
    pieno gia' partito (un «reso ricevuto» premuto nello stesso
    istante, un altro moderatore) pagherebbe il TOTALE mentre qui si
    scrive che una parte va a chi vende. Aspettando il lucchetto, quel
    giro finisce prima: e a quel punto o l'ordine non e' piu' in uno
    dei tre stati, o il suo pagamento e' in volo, e il cancello della
    transazione risponde 409."""
    async with _lucchetti_ordine[ordine_id]:
        o, spese, rid = _scrivi_meno_spese(ordine_id, pezzi_venditore)
    esiti = {}
    for chi, strada, arg in (("compratore", _rimborsa_compratore, ordine_id),
                             ("venditore", _paga_rimborso, rid)):
        try:
            esiti[chi] = await strada(arg)
        except Exception as e:
            # una meta' che esplode NON ferma l'altra: la sua riga
            # resta 'da_riprovare' e ci torna il giro dei pagamenti
            print(f"⚠️ Ordine #{ordine_id}, rimborso meno le spese: la "
                  f"meta' di chi {'compra' if chi == 'compratore' else 'vende'} "
                  f"non e' partita ({type(e).__name__}: {e}) — la "
                  f"riprende il giro dei pagamenti", flush=True)
            esiti[chi] = {"ok": False, "sospeso": True}
    con = db()
    stato = con.execute("SELECT stato FROM ordini WHERE id=?",
                        (ordine_id,)).fetchone()["stato"]
    con.close()
    return {"ok": True, "stato": stato, "meno_spese": True,
            "spese_sats": spese, "codici_venditore": int(pezzi_venditore or 0),
            "compratore_pagato": bool(esiti["compratore"].get("ok")),
            "venditore_pagato": bool(esiti["venditore"].get("ok")),
            "non_chiesto": bool(esiti["compratore"].get("non_chiesto"))}


def _scrivi_meno_spese(ordine_id: int, pezzi_venditore: int = 0):
    """LA SCRITTURA del quarto esito: la cifra sull'ordine e la riga di
    chi vende, in UNA transazione. E' una `def` e non una `async def`
    APPOSTA: qui dentro non puo' entrarci un await, cioe' niente puo'
    infilarsi fra il timbro sull'ordine e la riga. Restituisce
    (ordine, spese, id della riga); alza se non si puo' decidere."""
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=?",
                    (ordine_id,)).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Questa disputa non esiste o è già chiusa")
    if pezzi_venditore:
        # la divisione dei codici: la quota e' quella dei contatori, e
        # la cintura e' la stessa delle spese — mai zero, mai il totale
        spese = quota_codici_venditore(o, pezzi_venditore)
        if not 0 < spese < int(o["prezzo_sats"] or 0):
            con.close()
            raise HTTPException(400, "La divisione dei codici non torna su "
                                     "questo ordine: usa il rimborso o i "
                                     "sats al venditore")
    else:
        spese = spese_trattenibili(o)
        if not spese:
            con.close()
            raise HTTPException(400, MSG_NIENTE_SPESE)
    adesso = int(time.time())
    # ANCHE 'uscito' FERMA LA PENNA (14 nov 2026, cantiere
    # audit-pagamenti-2, dal secondo audit di sicurezza): un ordine
    # ancora in disputa puo' portare il timbro di un payout gia' USCITO
    # (un rimborso partito e non ancora chiuso dal giro). Scriverci
    # sopra «meno le spese» aggiungerebbe la quota di chi vende a sats
    # gia' andati: piu' di quanti ne sono entrati. Stessa famiglia di
    # 'incerto' e 'in_volo': sats che si sono mossi non si ridecidono.
    cur = con.execute(
        "UPDATE ordini SET spese_rese_sats=?, payout_stato='da_riprovare', "
        "payout_verso='compratore', codici_venditore=? WHERE id=? "
        "AND COALESCE(spese_rese_sats,0)=0 "
        "AND stato IN ('dispute','return_pending','return_shipped') "
        "AND COALESCE(payout_stato,'') NOT IN ('incerto','in_volo','uscito')",
        (spese, int(pezzi_venditore or 0), ordine_id))
    if cur.rowcount != 1:
        con.rollback()
        con.close()
        raise HTTPException(409, "Questa disputa è cambiata nel frattempo: "
                                 "riapri l'ordine e ricontrolla")
    con.execute(
        "INSERT INTO rimborsi_asta(annuncio_id, tg_id, puntata_id, "
        "importo_sats, motivo, stato, ordine_id, cassaforte, "
        "payout_stato, payout_verso, creato, aggiornato) "
        "VALUES(0, ?, 0, ?, ?, 'da_riscuotere', ?, ?, 'da_riprovare', "
        "'puntatore', ?, ?)",
        (o["venditore_id"], spese, MOTIVO_SPESE_RESE, ordine_id,
         _cassaforte_uscita(o), adesso, adesso))
    rid = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    con.commit()
    con.close()
    print(f"⚖️ Ordine #{ordine_id}: deciso il rimborso meno "
          + (f"i codici pagati ({pezzi_venditore})" if pezzi_venditore
             else "le spese di spedizione")
          + f" — {_fmt_sats(spese)} sats a chi vende (riga "
          f"#{rid}), {_fmt_sats(int(o['prezzo_sats']) - spese)} a chi "
          f"compra", flush=True)
    return o, spese, rid


async def _rimborsa_compratore(ordine_id: int) -> dict:
    """Rimborsa integralmente l'acquirente (disputa decisa a suo
    favore), provando: 1. la sua invoice di rimborso, 2. il suo
    Lightning address. Se non c'e' un metodo, l'ordine va in 'refund'
    e l'acquirente viene invitato a fornirne uno nella Mini App.
    L'annuncio torna in vetrina."""
    async with _lucchetti_ordine[ordine_id]:
        con = db()
        o = con.execute("SELECT * FROM ordini WHERE id=?", (ordine_id,)).fetchone()
        if not o:
            con.close()
            return {"ok": False, "stato": "?"}
        if o["stato"] in ("refunded", "released", "creato", "annullato"):
            con.close()          # gia' risolto (o mai pagato): niente doppioni
            return {"ok": o["stato"] == "refunded", "stato": o["stato"]}
        if o["payout_stato"] in ("incerto", "in_volo"):
            con.close()          # gemello di _sblocca_sats: mai due uscite
            return {"ok": False, "stato": o["stato"], "incerto": True}
        # l'on-chain, gemello di `_sblocca_sats`: si chiude solo a
        # rimborso gia' partito con le due firme
        oc = (_onchain_uscita_fatta(con, o, "compratore")
              if (_campo(o, "cassaforte") or "") == "onchain" else None)
        if oc is False:
            con.close()
            return {"ok": False, "stato": o["stato"], "onchain": True}
        c_utente = con.execute("SELECT * FROM utenti WHERE tg_id=?",
                               (o["compratore_id"],)).fetchone()
        # L'ANNULLO DEL VENDITORE (1 ott 2026): se a chiudere l'ordine
        # e' stato chi vende, la merce e' gia' stata sistemata
        # all'annullo (annulla_vendita) e le parole non parlano di
        # disputa. Si legge con `keys()` e non con un aiutante: i banchi
        # che eseguono questo pezzo montano tabelle piu' strette di
        # quella vera, e li' la colonna non c'e'.
        annullo = bool("annullato_venditore_il" in o.keys()
                       and o["annullato_venditore_il"])
        # LA FATTURA ANNULLATA E PAGATA (13 ott 2026): l'ordine non e'
        # mai stato 'locked' — niente stock scalato, nessun «venduto» —
        # quindi qui non c'e' merce da rimettere a posto e a chi vende
        # non si dice niente: tornano i sats a chi ha pagato, e basta.
        # VINCE sull'annullo del venditore quando ci sono tutt'e due i
        # timbri (la lapide di un suo annullo, pagata dopo): il suo
        # ramo, piu' sotto, esce prima di quello dell'annullo. Si legge
        # con `_campo`, per la ragione dell'annullo qui sopra: i banchi
        # montano tabelle piu' strette, e li' la colonna non c'e'.
        tardiva = bool(_campo(o, "pagata_da_annullata_il", 0))
        # Rimborso integrale: articolo, spedizione e protezione tornano
        # tutti al compratore (l'affare e' saltato, la protezione non
        # si e' consumata) — e' il totale, zero commissioni.
        # ...TRANNE col quarto esito (13 ott 2026): `spese_rese_sats`
        # dice quanto il moderatore ha trattenuto per le spese di
        # spedizione, e quelle vanno a chi vende da un'altra riga. La
        # cifra la da' il giudice unico, lo stesso della fattura
        # incollata e della pagina.
        spese_rese = int(_campo(o, "spese_rese_sats", 0) or 0)
        importo = importo_rimborso(o)
        # LA DIVISIONE DEI CODICI (16 nov 2026): `spese_rese` qui sono i
        # codici pagati a chi vende, e le parole e lo stock lo sanno
        pezzi_v = int(_campo(o, "codici_venditore", 0) or 0)
        codici_n = int(_campo(o, "codici_n", 0) or 0)

        bolt11 = ""
        taccuino = {"etichetta": f"Rimborso al compratore sull'ordine "
                                 f"#{ordine_id}"}
        try:
            if o["payout_stato"] != "uscito" and not oc:
                bolt11 = o["invoice_rimborso"]
                if not bolt11 and c_utente and c_utente["ln_address"]:
                    bolt11 = await invoice_da_ln_address(c_utente["ln_address"],
                                                         importo)
            esito = (PAGATO if o["payout_stato"] == "uscito" or oc
                     else await paga_venditore(bolt11, importo, taccuino,
                                               cassaforte=_cassaforte_uscita(o),
                                               riga=("ordini", ordine_id,
                                                     "compratore"))
                     if bolt11 else NON_PAGATO)
        except LnbitsMuto as e:
            print(f"🔁 Rimborso sull'ordine #{ordine_id}: {e}")
            esito = NON_CHIESTO
        if esito == OCCUPATO:
            con.close()
            return {"ok": False, "stato": o["stato"], "in_volo": True}
        _timbra_pagamento(con, "ordini", ordine_id, taccuino)
        if esito == INCERTO:
            if (taccuino.get("risolvibile")
                    and (o["payout_tentativi"] or 0) < MAX_TENTATIVI_PAYOUT):
                _in_volo(con, "ordini", ordine_id, "compratore")
                return {"ok": False, "stato": o["stato"], "in_volo": True}
            await _congela_pagamento(
                con, "ordini", ordine_id, bolt11, "compratore",
                f"Rimborso al compratore sull'ordine #{ordine_id}: "
                f"<b>{_fmt_sats(importo)} sats</b>.",
                cassaforte=_cassaforte_uscita(o))
            return {"ok": False, "stato": o["stato"], "incerto": True}
        if esito == NON_CHIESTO:
            # Gemello del ramo di `_sblocca_sats`: la riga resta com'era
            # — `invoice_rimborso` compresa — e ci torna il giro.
            _sospendi_pagamento(con, "ordini", ordine_id, "compratore")
            return {"ok": False, "stato": o["stato"], "non_chiesto": True}

        if esito == PAGATO:
            # (14 nov 2026, terzo giro dell'audit) il timbro del pagamento
            # si chiude QUI: il cambio puo' chiedere a CoinGecko fino a 10
            # secondi, e con la scrittura aperta tutto il database
            # aspetterebbe con lui
            con.commit()
            cambio = await cambio_btc_eur()
            con.execute("UPDATE ordini SET stato='refunded', cambio_eur=?, "
                        "payout_stato='uscito', "
                        "aggiornato=? WHERE id=?",
                        (cambio, int(time.time()), ordine_id))
            if tardiva:
                # LA FATTURA ANNULLATA E PAGATA ESCE QUI, prima di ogni
                # riga che tocca la merce: l'ordine non e' mai stato
                # 'locked', quindi non c'e' stock da rimettere, ne' un
                # registro di negozio da pareggiare, ne' una piazza da
                # avvisare. Il perche' gliel'ha gia' detto l'avviso del
                # riacciuffo (`_avvisi_annullata_pagata`): qui si dice
                # che i sats sono partiti. Niente invito al feedback —
                # non c'e' stato un affare — e a chi vende NIENTE.
                titolo = html.escape(
                    _titolo_ordine(_righe_ordine(con, o))[:60])
                con.commit()
                con.close()
                await notifica(o["compratore_id"],
                               f"↩️ <b>Rimborso della fattura annullata:</b> "
                               f"<b>{_fmt_sats(importo)} sats</b> in arrivo nel "
                               f"tuo wallet, per intero.")
                await polso_ordini_admin(
                    f"↩️ <b>Fattura annullata pagata, rimborsata a chi ha "
                    f"pagato:</b> «{titolo}» — {_fmt_sats(importo)} sats "
                    f"(ordine #{ordine_id}). Nessuna vendita. Restano "
                    f"{{aperti}} ordini aperti.")
                return {"ok": True, "stato": "refunded"}
            # I pezzi rimborsati tornano nello stock e l'oggetto in
            # vetrina (incremento RELATIVO: se il venditore li aveva
            # gia' ricontati con la ricarica — che e' una scrittura
            # ASSOLUTA — corregge con la stessa ricarica). Il rimborso
            # e' sempre integrale, per l'ordine intero: il parziale
            # per-pezzo richiederebbe due mosse Lightning coordinate.
            # Nel SET tornano in vetrina TUTTI gli annunci, riga per
            # riga: il pacco e' tornato indietro intero.
            # Il massimo sale col MAX anche qui, e non e' teoria: chi
            # aveva 3 pezzi, li vende tutti e poi ricarica a 1 si
            # ritrova a 4 se una disputa gliene rimborsa 3 — cioe' sopra
            # il massimo di ieri. Chiudere la falla dove nasce vale piu'
            # che aspettare la scopa del riavvio.
            righe = _righe_ordine(con, o)
            # i codici pagati a chi vende NON tornano nello stock: sono
            # di chi li ha comprati. Tornano solo quelli mai pagati
            # (l'ordine a riquadri e' sempre di un annuncio solo)
            if pezzi_v and len(righe) == 1:
                righe = [dict(righe[0], quantita=max(
                    0, int(righe[0]["quantita"]) - pezzi_v))]
            magazzino = []
            # SU UN ORDINE ANNULLATO DAL VENDITORE LO STOCK NON SI TOCCA
            # (1 ott 2026): la merce non e' mai partita e chi vende l'ha
            # gia' sistemata all'annullo — gli esauriti in pausa, il
            # resto in vetrina. Rimetterla qui, magari giorni dopo dalla
            # fattura incollata, la conterebbe due volte.
            if not annullo:
                for r in righe:
                    con.execute("UPDATE annunci SET quantita=quantita+?, "
                                "quantita_max=MAX(quantita_max,quantita+?), "
                                "stato='attivo' WHERE id=?",
                                (r["quantita"], r["quantita"], r["annuncio_id"]))
                # IL REGISTRO VA RIMESSO IN PARI, o la vendita rimborsata
                # continuerebbe a sottrarre un pezzo fantasma A OGNI GIRO,
                # per sempre: il sync ricopre la giacenza dalla lettura
                # esterna e la pendente e' quel che la corregge. Se il
                # negozio non l'aveva ancora scalata le due si cancellano in
                # silenzio; se l'aveva gia' fatto, i pezzi vanno RIMESSI e
                # glielo si dice. Stessa transazione dello stock, per la
                # ragione del gemello in `_incassa_ordine`.
                magazzino = registra_uscita_negozio(con, ordine_id, righe,
                                                    "rimborso")
            con.commit()
            titolo = html.escape(_titolo_ordine(righe)[:60])
            con.close()
            for r in (righe if not annullo else []):
                # ...e torna disponibile anche sulla piazza Nostr
                asyncio.create_task(annuncio_su_nostr(r["annuncio_id"],
                                                      "active",
                                                      solo_aggiornamento=True))
                # ...e il post nel canale toglie il ✅ Venduto: l'oggetto
                # e' di nuovo in vetrina, il post non deve mentire
                asyncio.create_task(promo_venduto(r["annuncio_id"],
                                                  venduto=False))
            if annullo:
                # le parole dell'annullo: il motivo gliel'ha gia' detto
                # l'avviso di annulla_vendita, qui si dice che i sats
                # sono partiti
                await notifica(o["compratore_id"],
                               f"↩️ <b>Rimborso dell'ordine annullato:</b> "
                               f"<b>{_fmt_sats(importo)} sats</b> in arrivo nel "
                               f"tuo wallet, per intero. ⭐ Com'è andata? Apri "
                               f"l'ordine nella Mini App e lascia un feedback.")
                await notifica(o["venditore_id"],
                               "↩️ Ordine annullato: i sats sono tornati per "
                               "intero all'acquirente.")
            elif pezzi_v:
                await notifica(o["compratore_id"],
                               _msg_codici_compratore(importo, pezzi_v,
                                                      codici_n, True))
                await notifica(o["venditore_id"],
                               _msg_codici_venditore(spese_rese, pezzi_v,
                                                     codici_n, True)
                               + ("\n\n" + _coda_magazzino(magazzino)
                                  if magazzino else ""))
            elif spese_rese:
                # IL QUARTO ESITO: non e' «a tuo favore» per nessuno dei
                # due, e le parole lo dicono — a chi compra la cifra
                # che arriva e quella che resta a chi ha spedito, a chi
                # vende dove trova la sua
                await notifica(o["compratore_id"],
                               _msg_meno_spese_compratore(importo, spese_rese,
                                                          True))
                await notifica(o["venditore_id"],
                               _msg_meno_spese_venditore(spese_rese, True)
                               + ("\n\n" + _coda_magazzino(magazzino)
                                  if magazzino else ""))
            else:
                await notifica(o["compratore_id"],
                               f"↩️ <b>Disputa risolta a tuo favore:</b> il rimborso di "
                               f"<b>{_fmt_sats(importo)} sats</b> è in arrivo nel tuo wallet. "
                               f"⭐ Com'è andata? Apri l'ordine nella Mini App e "
                               f"lascia un feedback.")
                await notifica(o["venditore_id"],
                               "⚖️ La disputa è stata risolta a favore dell'acquirente: "
                               "i sats gli sono stati rimborsati e l'annuncio è tornato "
                               "in vetrina. ⭐ Puoi lasciare un feedback dall'ordine "
                               "nella Mini App."
                               + ("\n\n" + _coda_magazzino(magazzino)
                                  if magazzino else ""))
            # Il polso dei moderatori: anche gli esiti storti contano
            await polso_ordini_admin(
                f"↩️ <b>Ordine {'annullato dal venditore e ' if annullo else ''}"
                f"rimborsato al compratore:</b> «{titolo}» — "
                f"{_fmt_sats(importo)} sats. Restano {{aperti}} ordini aperti.")
            return {"ok": True, "stato": "refunded"}

        # Nessun metodo di rimborso disponibile: si mette in attesa
        primo_giro = o["stato"] != "refund"
        # Il gemello del ritentativo di `_sblocca_sats`, stesse ragioni
        ritenta = bool(taccuino.get("ritentabile") and c_utente
                       and c_utente["ln_address"]
                       and (o["payout_tentativi"] or 0) < MAX_TENTATIVI_PAYOUT)
        # ...e il verso col timbro, come di la' (14 nov 2026): senza,
        # dopo un «al venditore» rimasto a meta' il giro ripassava da
        # `_sblocca_sats`, che da 'refund' non parte, e spegneva il
        # timbro — il rimborso non ripartiva piu' da solo.
        con.execute("UPDATE ordini SET invoice_rimborso='', stato='refund', "
                    "payout_stato=?, payout_verso=?, aggiornato=? WHERE id=?",
                    ("da_riprovare" if ritenta else "", "compratore",
                     int(time.time()), ordine_id))
        con.commit()
        con.close()
        if (annullo or tardiva) and not ritenta:
            # L'ANNULLO DEL VENDITORE: l'avviso di annulla_vendita ha
            # gia' detto al compratore come ricevere i sats; qui si
            # parla solo se la strada automatica C'ERA e non ha pagato.
            # LA FATTURA ANNULLATA E PAGATA fa lo stesso: il suo avviso
            # (`_avvisi_annullata_pagata`) e' gia' partito.
            if c_utente and c_utente["ln_address"]:
                await notifica(
                    o["compratore_id"],
                    f"↩️ <b>Il rimborso di {_fmt_sats(importo)} sats non è "
                    f"partito</b> sul tuo Lightning address: apri l'ordine "
                    f"nella Mini App e incolla una invoice di esattamente "
                    f"quell'importo, o ricontrolla l'address nel Profilo.")
        else:
            await notifica(
                o["compratore_id"], _msg_ritentiamo(importo) if ritenta else
                _msg_codici_compratore(importo, pezzi_v, codici_n, False)
                if pezzi_v else
                _msg_meno_spese_compratore(importo, spese_rese, False)
                if spese_rese else
                f"⚖️ <b>Disputa risolta a tuo favore!</b> Per ricevere il "
                f"rimborso di <b>{_fmt_sats(importo)} sats</b>: apri l'ordine nella "
                f"Mini App e imposta il tuo Lightning address, oppure "
                f"incolla una invoice di esattamente quell'importo.")
        # Il gemello del ramo di sopra: anche qui chi ha perso deve
        # saperlo, e una volta sola
        if o["disputata"] and primo_giro:
            await notifica(
                o["venditore_id"],
                _msg_codici_venditore(spese_rese, pezzi_v, codici_n, False)
                if pezzi_v else
                _msg_meno_spese_venditore(spese_rese, False) if spese_rese
                else
                "⚖️ <b>La disputa è stata decisa a favore dell'acquirente.</b> "
                "I sats gli verranno rimborsati appena ci dà un modo per "
                "riceverli. Se pensi che ci sia stato un errore, scrivi ai "
                "moderatori.")
        return {"ok": False, "stato": "refund", "ritenta": ritenta}


@app.post("/api/admin/orders/{ordine_id}/risolvi")
async def risolvi_disputa(ordine_id: int, req: Request,
                          x_tg_init_data: str = Header(""),
                          barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: decide una disputa.
    - esito='venditore': i sats vanno al venditore (meno commissione)
    - esito='rimborso': rimborso immediato all'acquirente (es. oggetto
      mai arrivato)
    - esito='reso': rimborso PREVIA RESTITUZIONE: l'acquirente deve
      rispedire l'oggetto (con tracciamento); il rimborso parte solo
      quando il venditore conferma di averlo ricevuto.
    - esito='reso_venditore' (18 nov 2026): lo stesso reso, ma
      l'etichetta la paga chi vende — la manda nella chat dell'ordine.
    'venditore' e 'rimborso' funzionano anche come intervento d'ufficio
    su un reso che si e' incagliato.

    LA CODA GUARDA ANCHE OLTRE (ago 2026, audit): quando lo sblocco o
    il rimborso NON riescono a pagare, l'ordine passa in 'confirmed' o
    in 'refund' — che e' giusto («i sats spettano a qualcuno, manca il
    modo di dargliglieli») ma lo faceva sparire da questa query, e con
    lui la possibilita' di RIPENSARCI: un moderatore che aveva deciso
    male non poteva piu' rimborsare, e i sats restavano fermi senza
    rimedio. Ora `disputata=1` li tiene decidibili. E' anche la
    migrazione del pregresso: gli ordini gia' finiti in trappola
    tornano in coda da soli, senza toccare il database."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    d = await leggi_json(req)
    esito = d.get("esito", "")
    if esito not in ("venditore", "rimborso", "reso", "meno_spese",
                     "reso_venditore"):
        raise HTTPException(400, "Esito non valido")
    con = db()
    # LA PORTA DEL TIMER (ago 2026): un ordine digitale chiuso da uno
    # dei due timer corti, con un venditore senza metodo d'incasso,
    # finiva in 'confirmed' con `disputata` a 0 — cioe' fuori da questa
    # query e fuori da ogni altra: i sats erano ancora in cassaforte e
    # NESSUNO poteva piu' renderli, nemmeno un moderatore, mentre
    # deposita_invoice e sollecita_incassi continuavano a spingere
    # verso l'unica uscita rimasta, quella del venditore. Il difetto
    # non era che 'confirmed' fosse irreversibile: era che a decidere
    # era stata una MACCHINA. Per questo si apre SOLO su quel ramo —
    # chi ha confermato di persona resta chiuso, e nessuno puo'
    # riaprire da solo un affare concluso. Solo 'confirmed': a
    # 'refund' un timer non ci arriva. E la finestra non si tara:
    # appena il venditore incassa l'ordine passa a 'released' e la
    # porta si chiude da sola, cioe' esiste esattamente finche' i sats
    # sono ancora nostri.
    o = con.execute("SELECT * FROM ordini WHERE id=? AND ("
                    "  stato IN ('dispute','return_pending','return_shipped') "
                    "  OR (disputata=1 AND stato IN ('confirmed','refund')) "
                    "  OR (sbloccato_auto_il > 0 AND stato='confirmed'))",
                    (ordine_id,)).fetchone()
    con.close()
    if not o:
        raise HTTPException(400, "Questa disputa non esiste o è già chiusa")
    # L'ANNULLO DEL VENDITORE NON SI DECIDE (15 ott 2026, decisione di
    # Andrea). Il backfill di init_db lo marcava `disputata` a ogni avvio
    # (curato), e gli ordini marcati prima della cura restano marcati
    # finche' non si scrivono a mano: questa porta li troverebbe, e
    # «venditore» darebbe i sats proprio a chi aveva annullato. Un
    # annullo da 'locked' viene sempre DOPO la nascita dell'ordine, e da
    # li' una disputa non si apre piu'. La lapide di un annullo pagata
    # dopo e riacciuffata invece riparte con un `creato` nuovo e puo'
    # essere disputata DAVVERO: il confronto la lascia passare. Sta
    # prima di ogni altra guardia e di ogni esito: vale per tutti.
    ann = int(_campo(o, "annullato_venditore_il", 0) or 0)
    if ann and ann >= int(_campo(o, "creato", 0) or 0):
        raise HTTPException(400, MSG_ANNULLO_NON_DISPUTA)
    stato = o["stato"]
    # IL QUARTO ESITO E' DEFINITIVO APPENA PRESO (13 ott 2026), ed e' la
    # riga da non ammorbidire: dopo «meno le spese» l'ordine sta in
    # 'refund' con `disputata=1` — cioe' ESATTAMENTE la forma che il
    # ramo qui sotto riapre per far ridecidere — ma una delle due meta'
    # puo' essere gia' partita. Ridecidere «rimborso integrale» a spese
    # gia' incassate da chi vende farebbe uscire piu' sats di quanti ne
    # sono entrati. Questa guardia sta PRIMA della riapertura, e vale
    # per ogni esito.
    if int(_campo(o, "spese_rese_sats", 0) or 0) > 0:
        raise HTTPException(400, MSG_MENO_SPESE_DECISO)
    # L'ON-CHAIN (27 ott 2026, cantiere onchain-disputa): la decisione
    # che muove sats E' la firma di Barattolo (`_onchain_decide`), e la
    # seconda la mette il telefono di chi vince. Il reso fa la strada di
    # sempre: la firma arriva quando chi vende lo riceve.
    # UN MODERATORE NON DECIDE UN ORDINE IN CUI E' PARTE, ed e' il
    # perche' di Andrea per tenere la chiave sul VPS («altrimenti noi
    # admin possiamo gia' dare 2 firme e vincere ogni causa»): la sua
    # chiave di parte e quella di Barattolo, decisa da lui, sarebbero
    # proprio le due firme. Decide un altro moderatore.
    # E VALE PER OGNI ORDINE (14 nov 2026, cantiere audit-pagamenti-2, dal
    # secondo audit di sicurezza): sul Lightning custodial la guardia non
    # c'era, e un moderatore poteva decidere a proprio favore la disputa
    # di un ordine in cui era compratore o venditore. Sta PRIMA del ramo
    # on-chain; la frase on-chain resta la sua.
    if int(user["id"]) in (int(o["compratore_id"]), int(o["venditore_id"])):
        if (_campo(o, "cassaforte") or "") == "onchain":
            raise HTTPException(403, "Su un ordine on-chain in cui sei una "
                                     "delle parti decide un altro moderatore")
        raise HTTPException(403, "Sei una delle due parti: questa disputa "
                                 "la decide un altro moderatore")
    # CHI HA DECISO resta scritto nel journal: l'ordine non ha una colonna
    # per il moderatore, e la decisione non deve restare anonima.
    print(f"⚖️ Disputa #{ordine_id}: esito «{esito}» deciso dal "
          f"moderatore #{user['id']}", flush=True)
    if (_campo(o, "cassaforte") or "") == "onchain":
        if esito == "meno_spese":
            raise HTTPException(409, "Ordine on-chain: «meno le spese» non "
                                     "c'è ancora. Scegli il rimborso, il reso "
                                     "o i sats al venditore")
        if esito in ("venditore", "rimborso"):
            if o["stato"] not in ("dispute", "return_pending", "return_shipped"):
                raise HTTPException(400, "Questa disputa non esiste o è già chiusa")
            return await _onchain_decide(
                ordine_id, "venditore" if esito == "venditore" else "compratore",
                user["id"], "disputa")
    # UN CODICE ALLA VOLTA (16 nov 2026): la disputa sul codice k si
    # decide su quel codice soltanto, e i sats li dividono i contatori
    # (`pezzi_al_venditore`). Zero codici a chi vende e' il rimborso di
    # sempre, tutti e' lo sblocco di sempre: la divisione serve solo in
    # mezzo, e solo sulla disputa aperta (come «meno le spese»).
    pezzi_v = pezzi_al_venditore(o, esito)
    if 0 < pezzi_v < int(_campo(o, "codici_n", 0) or 0):
        if stato != "dispute":
            raise HTTPException(400, "La divisione dei codici si decide "
                                     "sulla disputa aperta")
        return await _poi_chat_mercatino(
            ordine_id, _rimborsa_meno_spese(ordine_id, pezzi_v))
    # ...e si prende solo dalla disputa aperta o dal reso in corso
    # (decisione di Andrea): non da un caso gia' deciso e incagliato,
    # che il ramo qui sotto riaprirebbe.
    if esito == "meno_spese":
        if stato not in ("dispute", "return_pending", "return_shipped"):
            raise HTTPException(400, MSG_MENO_SPESE_DOVE)
        return await _poi_chat_mercatino(ordine_id, _rimborsa_meno_spese(ordine_id))
    # IL RESO NON SCAVALCA UN PAGAMENTO (14 nov 2026, cantiere
    # audit-dispute, dal primo audit di sicurezza). «Reso» era l'unico
    # esito che non guardava il timbro del payout: «rimborso» e «al
    # venditore» si fermano da soli nelle due uscite, «meno le spese»
    # ha il suo UPDATE condizionato. Con un pagamento in volo, in
    # verifica o gia' uscito i sats POSSONO essere partiti: dire a chi
    # compra «rispedisci l'oggetto» vorrebbe dire rischiare che resti
    # senza oggetto e senza sats. Sta PRIMA della riapertura: un caso
    # che non si puo' ridecidere non si riapre nemmeno.
    # Il reso a spese del venditore e' un reso: stessa guardia.
    if esito in ("reso", "reso_venditore") and (_campo(o, "payout_stato")
                            in ("in_volo", "incerto", "uscito")):
        raise HTTPException(409, MSG_RESO_PAGAMENTO_IN_CORSO)
    if stato in ("confirmed", "refund"):
        # Il caso era gia' stato deciso e il pagamento non era riuscito:
        # per cambiare strada lo si RIAPRE, invece di allentare le
        # guardie delle due funzioni d'uscita — _sblocca_sats non parte
        # da 'refund' e _rimborsa_compratore non parte da 'refunded',
        # ed e' giusto che restino cosi'. Riaprire dice anche la
        # verita': il caso torna in mano al moderatore, e da li' si
        # decide come la prima volta.
        con = db()
        # `disputata=1` e' un no-op sul caso di ieri (era gia' 1) e
        # serve su quello del timer: senza, decidendo poi a favore del
        # venditore, _sblocca_sats cadrebbe nel suo `else` e direbbe al
        # venditore «L'acquirente ha confermato la ricezione» e al
        # compratore «Affare concluso, grazie» — due bugie. Con 1
        # prendono il ramo della disputa, che e' la verita': un
        # moderatore ha deciso il caso. IL PREZZO E' DICHIARATO
        # (decisione di Andrea): quel caso conta come disputa per lo
        # Specchiato e nel conteggio che il moderatore legge, cioe'
        # come se il compratore avesse disputato e perso — che e' in
        # sostanza quel che e' successo, e la verita' nelle notifiche
        # vale piu' della statistica.
        con.execute("UPDATE ordini SET stato='dispute', disputata=1, "
                    "aggiornato=? WHERE id=? AND stato=?",
                    (int(time.time()), ordine_id, stato))
        con.commit()
        con.close()
        stato = "dispute"
    if esito == "venditore":
        return await _poi_chat_mercatino(ordine_id, _sblocca_sats(ordine_id))
    if esito == "rimborso":
        return await _poi_chat_mercatino(ordine_id, _rimborsa_compratore(ordine_id))
    if esito in ("reso", "reso_venditore") and stato == "dispute":
        # IL TIMBRO DI PRIMA SE NE VA CON LA DECISIONE DI PRIMA. Un «al
        # venditore» che non era riuscito a pagare lascia sulla riga
        # 'da_riprovare' verso il venditore, e i due giri dell'orologio
        # seguono il timbro, non lo stato: a reso deciso pagavano chi
        # vende lo stesso, mentre chi compra rispediva l'oggetto
        # (riprodotto: `prove_disputa_cambia_strada`). 'da_riprovare'
        # vuol dire «nessun sat si e' mosso», quindi toglierlo e'
        # sicuro; gli altri tre timbri no, e l'UPDATE e' CONDIZIONATO.
        # SOTTO IL LUCCHETTO DELL'ORDINE, come le due uscite: il giro
        # che sta pagando in questo istante finisce prima, e qui si
        # trova l'ordine com'e' davvero — chiuso, e allora e' un 409.
        # A SPESE DEL VENDITORE (18 nov 2026) cambia solo chi paga
        # l'etichetta: lo dice `reso_venditore_il`, scritto nello STESSO
        # UPDATE condizionato — un reso deciso a meta' non esiste.
        adesso = int(time.time())
        reso_venditore_il = adesso if esito == "reso_venditore" else 0
        async with _lucchetti_ordine[ordine_id]:
            con = db()
            cur = con.execute(
                "UPDATE ordini SET stato='return_pending', payout_stato='', "
                "payout_verso='', aggiornato=?, reso_venditore_il=?, "
                "etichetta_mancante_il=0 WHERE id=? AND stato='dispute' "
                "AND COALESCE(payout_stato,'') "
                "NOT IN ('incerto','in_volo','uscito')",
                (adesso, reso_venditore_il, ordine_id))
            con.commit()
            con.close()
        if cur.rowcount != 1:
            raise HTTPException(409, "Questa disputa è cambiata nel "
                                     "frattempo: riapri l'ordine e ricontrolla")
        if reso_venditore_il:
            scade = _data_etichetta_reso(reso_venditore_il)
            await notifica(o["compratore_id"],
                           "⚖️ <b>Disputa decisa: reso a spese del "
                           "venditore.</b> Rispedirai l'oggetto, ma "
                           "l'etichetta la paga lui: te la manda nella chat "
                           f"dell'ordine entro il {scade}. <b>Non pagare "
                           "niente</b>: usa la sua etichetta, poi inserisci "
                           "il tracciamento nella Mini App. Il rimborso "
                           "partirà quando il venditore riceve l'oggetto.")
            await notifica(o["venditore_id"],
                           "⚖️ <b>Disputa decisa: reso a tue spese.</b> "
                           "Crea un'etichetta di reso prepagata (il "
                           "mittente è l'acquirente, il destinatario sei "
                           "tu) e <b>mandala nella chat dell'ordine entro "
                           f"il {scade}</b>. Quando ricevi l'oggetto, "
                           "confermalo nella Mini App e i sats verranno "
                           "rimborsati all'acquirente. Senza etichetta, un "
                           "moderatore può rimborsarlo subito.")
            return {"ok": True, "stato": "return_pending",
                    "reso_venditore_il": reso_venditore_il}
        await notifica(o["compratore_id"],
                       "⚖️ <b>Disputa decisa: rimborso previa restituzione.</b> "
                       "Rispedisci l'oggetto al venditore (accordatevi in chat "
                       "per l'indirizzo) e inserisci il tracciamento del reso "
                       "nella Mini App: il rimborso partirà alla consegna.")
        await notifica(o["venditore_id"],
                       "⚖️ <b>Disputa decisa: reso.</b> L'acquirente ti "
                       "rispedirà l'oggetto; quando lo ricevi, confermalo "
                       "nella Mini App e i sats gli verranno rimborsati.")
        return {"ok": True, "stato": "return_pending"}
    # Ci si arriva solo col 'reso' su un ordine che e' gia' oltre: il
    # messaggio lo dice, invece del generico «esito non valido» che
    # faceva pensare a un errore di battitura.
    raise HTTPException(400, "Il reso si può chiedere solo su una disputa "
                             "aperta: questo ordine è già in restituzione")


# I corrieri-sentinella non sono corrieri: sono il modo di dire «qui
# non c'e' nessun pacco» ('Consegna a mano', 'Ritiro in zona') o «il
# bene e' passato dentro Barattolo» ('Consegna digitale'). Un
# tracciamento non li riguarda, e trasformare un ritiro in una
# spedizione — o viceversa — a sats gia' in cassaforte cambierebbe la
# STORIA dell'ordine, non un dato di servizio.
CORRIERI_SENTINELLA = ("Consegna a mano", "Ritiro in zona",
                       "Consegna digitale")

# LA POSTA SENZA TRACCIAMENTO (16 nov 2026, dal feedback di un venditore
# che per spedire una busta senza codice aveva finto la consegna a mano):
# NON e' una sentinella — un pacco c'e', e viaggia — ma e' la spedizione
# che un codice non l'avra' mai. Il nome dice la mancanza da solo, quindi
# il client nasconde il campo del codice e il server rifiuta un codice
# accanto a lei. Il rischio di un pacco perso resta di chi spedisce
# (decisione di Andrea, stesso giorno: «lasciare com'e'»).
CORRIERE_SENZA_TRACCIA = "Posta senza tracciamento"


# GLI STATI IN CUI IL PACCO DEL VENDITORE E' GIA' PARTITO: da qui in poi
# un tracciamento c'e', e il venditore lo puo' correggere SEMPRE (ott
# 2026, parola di Andrea) — anche a ordine chiuso o in disputa, dove la
# fila di `tracking_storico` dice comunque com'era prima.
STATI_CON_SPEDIZIONE = ("shipped", "delivered", "confirmed", "released",
                        "dispute", "return_pending", "return_shipped",
                        "refund", "refunded")


def archivia_tracking(con, ordine_id: int, reso: bool, corriere: str,
                      tracking: str, ora: int, da: str):
    """Mette in fila il tracciamento che sta per essere sostituito.
    Niente commit: e' del chiamante, nella STESSA transazione
    dell'UPDATE — un codice nuovo scritto senza il vecchio in fila
    sarebbe proprio la riscrittura silenziosa che la fila esiste per
    impedire."""
    con.execute("INSERT INTO tracking_storico(ordine_id, reso, corriere, "
                "tracking, sostituito_il, da) VALUES(?,?,?,?,?,?)",
                (ordine_id, 1 if reso else 0, corriere or "",
                 tracking or "", ora, da))


@app.post("/api/orders/{ordine_id}/tracking")
async def correggi_tracking_venditore(ordine_id: int, req: Request,
                                      x_tg_init_data: str = Header(""),
                                      barattolo_sessione: str = Cookie("")):
    """IL VENDITORE CORREGGE IL PROPRIO TRACCIAMENTO (ott 2026).

    ROVESCIA UNA DECISIONE, e lo dice: ad ago 2026 la correzione era
    dei soli moderatori («un tracciamento riscrivibile a piacere non e'
    piu' una prova in disputa»). Andrea ha deciso che il venditore lo
    deve poter correggere SEMPRE — il caso dal campo resta quello
    dell'intermediario (Packlink, Sendcloud) che manda il codice vero
    solo dopo — e che il compratore ne sia avvisato. La prova si tiene
    in un altro modo: il codice di prima NON si cancella, va in
    `tracking_storico` nella stessa transazione, e l'ordine mostra la
    fila intera a tutt'e due e ai moderatori.

    Le guardie sono quelle della correzione del moderatore: niente
    corrieri-sentinella (una consegna a mano non diventa una
    spedizione, e viceversa), niente ordini senza pacco, e lo `stato`
    e `spedito_il` non si toccano (l'ancora dei promemoria). In piu'
    il codice uguale a quello di adesso si dice, invece di riempire la
    fila di doppioni.

    E AGGIUNGE (9 ott 2026, col tracciamento facoltativo): chi ha
    spedito senza codice passa da QUESTA porta per metterlo dopo. La
    differenza e' due righe: il vuoto non si mette in fila (la fila
    conserva codici, non vuoti) e l'avviso a chi compra dice «aggiunto»
    e non «corretto… prima era», che con un «prima» vuoto direbbe il
    falso."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    corriere = (d.get("corriere") or "").strip()[:40]
    tracking = (d.get("tracking") or "").strip()[:60]
    # LA POSTA SENZA TRACCIAMENTO (16 nov 2026) e' l'unico corriere che
    # passa di qui SENZA codice, ed e' l'unico che un codice non lo
    # accetta: e' la spedizione che non si puo' seguire, detta col suo
    # nome invece che con un vuoto.
    senza = corriere == CORRIERE_SENZA_TRACCIA
    if not corriere or (not tracking and not senza):
        raise HTTPException(400, "Servono corriere e numero di tracciamento")
    if senza and tracking:
        raise HTTPException(400, "Con la posta senza tracciamento non "
                                 "c'è un codice: se ce l'hai, scegli il "
                                 "corriere che l'ha stampato")
    if corriere in CORRIERI_SENTINELLA:
        raise HTTPException(400, "«" + corriere + "» non è un corriere: "
                                 "questa correzione cambierebbe la storia "
                                 "dell'ordine, non il suo tracciamento")
    con = db()
    try:
        o = con.execute(
            "SELECT * FROM ordini WHERE id=? AND venditore_id=? AND stato IN "
            f"({','.join('?' * len(STATI_CON_SPEDIZIONE))})",
            (ordine_id, user["id"], *STATI_CON_SPEDIZIONE)).fetchone()
        # (15 ott 2026) la fattura annullata e pagata e' in 'refund'/
        # 'refunded', due stati di questa lista: chi vende non la vede,
        # e qui ci scriverebbe un tracciamento (avvisando chi ha pagato)
        if o and _nascosto_a(o, user["id"]):
            raise HTTPException(400, "Operazione non permessa")
        if not o:
            raise HTTPException(400, "Questo ordine non ha un tracciamento "
                                     "che puoi correggere")
        # LA CONSEGNA A MANO CHE ERA UNA SPEDIZIONE (16 nov 2026, dal
        # feedback di un venditore: aveva spedito una busta senza codice
        # e, credendo il codice obbligatorio, aveva segnato «Consegna a
        # mano»). E' L'UNICA SENTINELLA CHE SI RADDRIZZA, e in un verso
        # solo: chi ha comprato aveva SCELTO la spedizione, quindi «a
        # mano» era la riga sbagliata e la spedizione e' la verita' che
        # l'ordine aspettava. Mai il contrario (una spedizione non
        # diventa una consegna a mano: toglierebbe il pacco a chi lo
        # aspetta), mai sugli altri due (il ritiro in zona e il digitale
        # sono strade scelte da chi compra), e solo finche' l'ordine
        # non e' confermato ne' in disputa: a quel punto la storia la
        # stanno gia' leggendo un compratore che ha deciso o un
        # moderatore. «Consegna a mano» non sparisce: va in fila, come
        # un codice di prima.
        da_mano = (o["corriere"] == "Consegna a mano"
                   and o["consegna_scelta"] == "spedizione"
                   and o["stato"] in ("shipped", "delivered"))
        if not da_mano and (o["corriere"] in CORRIERI_SENTINELLA
                            or o["consegna_scelta"] in ("ritiro",
                                                        "digitale")):
            raise HTTPException(400, "Questo ordine non è una spedizione: "
                                     "non c'è un tracciamento da correggere")
        if senza and o["tracking"]:
            # il codice c'e' gia': tornare alla posta senza tracciamento
            # vorrebbe dire dire a chi compra che non puo' piu' seguire
            # un pacco che invece si segue
            raise HTTPException(400, "Questo ordine ha già un codice di "
                                     "tracciamento: se è sbagliato, "
                                     "correggilo con quello giusto")
        if corriere == o["corriere"] and tracking == o["tracking"]:
            raise HTTPException(400, "È già questo il tracciamento "
                                     "dell'ordine")
        ora = int(time.time())
        # IL CODICE AGGIUNTO DOPO: niente da mettere in fila — un
        # «Codici di prima: Poste Italiane  (cambiato dal venditore…)»
        # col codice vuoto direbbe che un codice c'era. La consegna a
        # mano invece si', ed e' la sola riga della fila senza codice:
        # il suo nome e' tutto quel che c'era scritto.
        aggiunto = not o["tracking"] and not da_mano and not senza
        if da_mano:
            archivia_tracking(con, ordine_id, False, "Consegna a mano",
                              "", ora, "venditore")
        elif o["tracking"]:
            archivia_tracking(con, ordine_id, False, o["corriere"],
                              o["tracking"], ora, "venditore")
        con.execute("UPDATE ordini SET corriere=?, tracking=?, "
                    "tracking_corretto_il=? WHERE id=?",
                    (corriere, tracking, ora, ordine_id))
        con.commit()
    finally:
        con.close()
    if da_mano or senza:
        # LE DUE PRECISAZIONI SENZA CODICE NUOVO (16 nov 2026): la
        # consegna a mano che era una spedizione, e il corriere senza
        # codice che diventa «posta senza tracciamento». Chi aspetta
        # deve sapere com'e' partito davvero, e se lo puo' seguire.
        if senza:
            come = ("con la <b>posta senza tracciamento</b>, quindi non "
                    "si può seguire")
        else:
            come = (f"con <b>{html.escape(corriere)}</b>, tracciamento "
                    f"{codice_tracking_bot(tracking)}")
        prima = (" Non era una consegna a mano: «Consegna a mano» resta "
                 "scritto nella storia dell'ordine." if da_mano else "")
        await notifica(
            o["compratore_id"],
            f"📦 <b>Il venditore ha corretto la spedizione</b> "
            f"dell'ordine #{ordine_id}: il pacco è partito {come}."
            f"{prima}")
    elif aggiunto:
        # AVVISA CHI ASPETTA IL PACCO che adesso lo puo' seguire: la
        # spedizione gli era arrivata «senza numero di tracciamento».
        await notifica(
            o["compratore_id"],
            f"📦 <b>Il venditore ha aggiunto il tracciamento</b> "
            f"dell'ordine #{ordine_id}: <b>{html.escape(corriere)}</b>, "
            f"tracciamento {codice_tracking_bot(tracking)}. Ora puoi "
            f"seguire il pacco.")
    else:
        # AVVISA CHI ASPETTA IL PACCO, col codice di prima accanto: chi
        # l'ha gia' messo in un'app di tracciamento deve sapere che e'
        # cambiato.
        await notifica(
            o["compratore_id"],
            f"📦 <b>Il venditore ha corretto il tracciamento</b> dell'ordine "
            f"#{ordine_id}: ora è <b>{html.escape(corriere)}</b>, "
            f"tracciamento {codice_tracking_bot(tracking)}. Prima era "
            f"{html.escape(o['corriere'] or '')} "
            f"<b>{html.escape(o['tracking'] or '')}</b>: il codice di prima "
            f"resta scritto nell'ordine.")
    return {"ok": True, "corriere": corriere, "tracking": tracking,
            "corretto_il": ora, "aggiunto": aggiunto, "da_mano": da_mano,
            "senza": senza}


@app.get("/api/admin/orders/{ordine_id}/fotografia")
async def fotografia_ordine(ordine_id: int,
                            x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN (18 nov 2026, cantiere fotografia-annuncio): l'annuncio
    com'era al pagamento accanto a quello di oggi, coi campi cambiati.
    Una lettura e basta: si apre a mano dal riquadro del moderatore,
    mai in polling. Un ordine pagato prima del cantiere non ha
    fotografie, e la lista vuota lo dice."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    con = db()
    try:
        o = con.execute("SELECT id, pagato_il FROM ordini WHERE id=?",
                        (ordine_id,)).fetchone()
        if not o:
            raise HTTPException(404, "Ordine non trovato")
        fotografie = []
        for f in con.execute(
                "SELECT annuncio_id, dati, creato FROM ordine_fotografie "
                "WHERE ordine_id=? ORDER BY rowid", (ordine_id,)).fetchall():
            try:
                allora = json.loads(f["dati"])
            except (TypeError, ValueError):
                continue
            a = con.execute("SELECT * FROM annunci WHERE id=?",
                            (f["annuncio_id"],)).fetchone()
            oggi = _fotografia_di(a) if a else None
            fotografie.append({
                "annuncio_id": f["annuncio_id"], "il": f["creato"],
                "allora": allora, "oggi": oggi,
                "diversi": (_differenze_fotografia(allora, oggi)
                            if oggi is not None else [])})
    finally:
        con.close()
    return {"ordine_id": ordine_id, "pagato_il": o["pagato_il"] or 0,
            "attiva": ORDINE_FOTOGRAFIA_ATTIVA, "fotografie": fotografie}


@app.post("/api/admin/orders/{ordine_id}/tracking")
async def correggi_tracking(ordine_id: int, req: Request,
                            x_tg_init_data: str = Header(""),
                            barattolo_sessione: str = Cookie("")):
    """SOLO ADMIN: corregge corriere e numero di tracciamento di un
    ordine gia' spedito (`reso=1` per quello del reso).

    IL PERCHE' (ago 2026, caso vero dal campo): un venditore compra la
    spedizione da un intermediario (Packlink, Sendcloud) e inserisce
    il codice dell'ORDINE dell'intermediario invece di quello del
    corriere — che spesso gli arriva per email solo DOPO aver
    consegnato il pacco al punto di ritiro. `segna_spedito` filtra su
    stato='locked', quindi il tracciamento si scrive una volta sola e
    nessuno poteva piu' correggerlo: il compratore restava con un
    codice che nessun corriere conosce.

    PERCHE' NON LO PUO' FARE IL VENDITORE (decisione di Andrea): un
    tracciamento riscrivibile a piacere non e' piu' una prova in
    disputa. La correzione passa da un moderatore, e LASCIA TRACCIA —
    `tracking_corretto_il`, che entrambe le parti vedono nell'ordine.

    COSA NON SI TOCCA, ed e' il cuore della cosa: `spedito_il` e lo
    `stato`. Il primo e' l'ANCORA del promemoria di
    `sollecita_conferme_ferme`; riscriverlo farebbe ripartire da capo
    l'attesa del compratore a ogni correzione — la stessa trappola
    gia' pagata con `aggiornato` in `sollecita_venditori_fermi`. Per
    la stessa ragione non si tocca nemmeno `aggiornato`, che e'
    l'ancora dei solleciti fratelli su altri stati: qui non serve, e
    il quando lo dice gia' la colonna della traccia."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not e_admin(user["id"]):
        raise HTTPException(403, "Riservato ai moderatori")
    d = await leggi_json(req)
    reso = bool(d.get("reso"))
    corriere = (d.get("corriere") or "").strip()[:40]
    tracking = (d.get("tracking") or "").strip()[:60]
    if not corriere or not tracking:
        raise HTTPException(400, "Servono corriere e numero di tracciamento")
    if corriere in CORRIERI_SENTINELLA:
        raise HTTPException(400, "«" + corriere + "» non è un corriere: "
                                 "questa correzione cambierebbe la storia "
                                 "dell'ordine, non il suo tracciamento")
    # Gli stati sono quelli in cui un pacco e' DAVVERO in viaggio (o
    # appena arrivato): la correzione serve li'. Il reso ha il suo.
    stati = ("return_shipped",) if reso else ("shipped", "delivered")
    con = db()
    o = con.execute(
        "SELECT * FROM ordini WHERE id=? AND stato IN "
        f"({','.join('?' * len(stati))})", (ordine_id, *stati)).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Questo ordine non ha un tracciamento "
                                 "correggibile in questo stato")
    vecchio_c = o["corriere_reso"] if reso else o["corriere"]
    vecchio_t = o["tracking_reso"] if reso else o["tracking"]
    if vecchio_c in CORRIERI_SENTINELLA or o["consegna_scelta"] in (
            "ritiro", "digitale"):
        # L'altra direzione della stessa guardia: un ordine consegnato
        # a mano (o un codice online) non ha un pacco da tracciare, e
        # dargliene uno lo racconterebbe come una spedizione.
        con.close()
        raise HTTPException(400, "Questo ordine non è una spedizione: "
                                 "non c'è un tracciamento da correggere")
    ora = int(time.time())
    archivia_tracking(con, ordine_id, reso, vecchio_c, vecchio_t, ora,
                      "moderatore")
    if reso:
        con.execute("UPDATE ordini SET corriere_reso=?, tracking_reso=?, "
                    "tracking_reso_corretto_il=? WHERE id=?",
                    (corriere, tracking, ora, ordine_id))
    else:
        con.execute("UPDATE ordini SET corriere=?, tracking=?, "
                    "tracking_corretto_il=? WHERE id=?",
                    (corriere, tracking, ora, ordine_id))
    con.commit()
    con.close()
    registra_moderazione(
        "ordine", "tracking_corretto",
        f"#{ordine_id}{' (reso)' if reso else ''}: "
        f"{vecchio_c} {vecchio_t} → {corriere} {tracking}",
        titolo=f"ordine #{ordine_id}", deciso_da=user["id"])
    # Avvisa CHI ASPETTA IL PACCO: il compratore sulla spedizione, il
    # venditore sul reso (e' lui che sta aspettando indietro l'oggetto).
    # Il codice nuovo della SPEDIZIONE e' un link a @trackbot come
    # nell'app (codice_tracking_bot); quello del RESO resta testo,
    # perche' nell'app il codice del reso non apre trackbot.
    track_e = (f"<b>{html.escape(tracking)}</b>" if reso
               else codice_tracking_bot(tracking))
    await notifica(
        o["venditore_id"] if reso else o["compratore_id"],
        f"📦 <b>Un moderatore ha corretto il tracciamento</b>"
        f"{' del reso' if reso else ''} dell'ordine #{ordine_id}: ora è "
        f"<b>{html.escape(corriere)}</b>, tracciamento "
        f"{track_e}. Il codice di prima non era "
        f"quello del corriere.")
    return {"ok": True, "corriere": corriere, "tracking": tracking,
            "corretto_il": ora}


@app.post("/api/orders/{ordine_id}/reso-spedito")
async def reso_spedito(ordine_id: int, req: Request,
                       x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """L'acquirente ha rispedito l'oggetto: registra il tracciamento
    del reso e avvisa il venditore."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    d = await leggi_json(req)
    corriere = (d.get("corriere") or "").strip()[:40]
    tracking = (d.get("tracking") or "").strip()[:60]
    if corriere != "Consegna a mano" and not tracking:
        raise HTTPException(400, "Inserisci il numero di tracciamento del reso")
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND compratore_id=? "
                    "AND stato='return_pending'",
                    (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    con.execute("UPDATE ordini SET stato='return_shipped', corriere_reso=?, "
                "tracking_reso=?, aggiornato=? WHERE id=?",
                (corriere, tracking, int(time.time()), ordine_id))
    con.commit()
    con.close()
    # Gemello di segna_spedito: qui il testo e' del COMPRATORE e ad
    # aspettare e' il venditore, ma la trappola e' la stessa — un «<»
    # nel nome del corriere fa fallire il parse HTML di Telegram, e
    # l'avviso che il reso e' partito non arriva, in silenzio. Si
    # scappa QUI: nel database il tracciamento resta quello scritto,
    # ed e' anche una prova in disputa.
    dettaglio = (f"con <b>{html.escape(corriere)}</b>, tracciamento "
                 f"<b>{html.escape(tracking)}</b>"
                 if tracking else "in consegna a mano")
    await notifica(o["venditore_id"],
                   f"↩️ <b>Il reso è in viaggio</b> {dettaglio}. Quando ricevi "
                   f"l'oggetto, conferma nella Mini App: a quel punto "
                   f"l'acquirente verrà rimborsato.")
    return {"ok": True, "stato": "return_shipped"}


@app.post("/api/orders/{ordine_id}/reso-ricevuto")
async def reso_ricevuto(ordine_id: int, x_tg_init_data: str = Header(""),
                                        barattolo_sessione: str = Cookie("")):
    """Il venditore conferma di aver ricevuto il reso: parte il
    rimborso integrale all'acquirente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND venditore_id=? "
                    "AND stato='return_shipped'",
                    (ordine_id, user["id"])).fetchone()
    con.close()
    if not o:
        raise HTTPException(400, "Operazione non permessa")
    if (_campo(o, "cassaforte") or "") == "onchain":
        # l'on-chain (27 ott 2026): il reso l'ha deciso un moderatore, e
        # chi vende che lo riceve e' il via — Barattolo firma il rimborso,
        # la seconda firma e' del telefono di chi ha comprato
        return await _onchain_decide(ordine_id, "compratore", user["id"], "reso")
    return await _poi_chat_mercatino(ordine_id, _rimborsa_compratore(ordine_id))


MSG_ETICHETTA_NON_ANCORA = ("Il venditore ha {giorni} giorni per mandarti "
                            "l'etichetta: puoi avvisare i moderatori dal {scade}")


@app.post("/api/orders/{ordine_id}/reso-etichetta-mancante")
async def reso_etichetta_mancante(ordine_id: int,
                                  x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """IL RESO A SPESE DEL VENDITORE SENZA ETICHETTA (18 nov 2026,
    cantiere reso-spese-venditore). Passati i GIORNI_ETICHETTA_RESO,
    chi ha comprato avvisa i moderatori che l'etichetta non e' arrivata.
    E' SOLO UN AVVISO, ed e' la riga da non ammorbidire (decisione di
    Andrea): niente si sblocca e niente si rimborsa da qui — Barattolo
    non legge la chat cifrata, quindi non puo' sapere se l'etichetta
    c'e'. A decidere il «Rimborso» e' un moderatore, che la chat la
    puo' leggere. Una volta sola: `etichetta_mancante_il` lo ricorda,
    e un secondo tocco non fa suonare di nuovo il gruppo."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND compratore_id=? "
                    "AND stato='return_pending' "
                    "AND COALESCE(reso_venditore_il,0)>0",
                    (ordine_id, user["id"])).fetchone()
    if not o:
        con.close()
        raise HTTPException(400, "Operazione non permessa")
    deciso = int(o["reso_venditore_il"] or 0)
    adesso = int(time.time())
    if adesso < deciso + GIORNI_ETICHETTA_RESO * 86400:
        con.close()
        raise HTTPException(400, MSG_ETICHETTA_NON_ANCORA.format(
            giorni=GIORNI_ETICHETTA_RESO,
            scade=_data_etichetta_reso(deciso)))
    cur = con.execute("UPDATE ordini SET etichetta_mancante_il=? "
                      "WHERE id=? AND stato='return_pending' "
                      "AND COALESCE(etichetta_mancante_il,0)=0",
                      (adesso, ordine_id))
    con.commit()
    con.close()
    if cur.rowcount != 1:
        # gia' avvisati: il gesto e' riuscito, non si suona due volte
        return {"ok": True, "gia": True,
                "etichetta_mancante_il": int(o["etichetta_mancante_il"] or 0)}
    await notifica_admin(
        f"⏰ <b>Reso a spese del venditore senza etichetta</b> "
        f"sull'ordine #{ordine_id}. L'acquirente dice che in "
        f"{GIORNI_ETICHETTA_RESO} giorni il venditore non gli ha mandato "
        f"l'etichetta prepagata. Leggi la chat dell'ordine: se non c'è, "
        f"puoi decidere «Rimborso».", argomento="dispute")
    await notifica(o["venditore_id"],
                   "⏰ <b>L'acquirente non ha ricevuto l'etichetta del "
                   "reso</b> e ha avvisato i moderatori. Se non l'hai "
                   "ancora fatto, mandala subito nella chat dell'ordine: "
                   "senza etichetta un moderatore può rimborsarlo.")
    return {"ok": True, "etichetta_mancante_il": adesso}


@app.post("/api/orders/{ordine_id}/conferma")
async def conferma_ricezione(ordine_id: int, x_tg_init_data: str = Header(""),
                                             barattolo_sessione: str = Cookie("")):
    """L'acquirente conferma la ricezione: i sats vengono consegnati
    automaticamente al venditore (invoice depositata o Lightning
    address). Se nessun metodo e' disponibile, l'ordine va in
    'confirmed' e partiranno appena il venditore ne fornisce uno."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND compratore_id=? "
                    "AND stato IN ('locked','shipped','delivered')",
                    (ordine_id, user["id"])).fetchone()
    con.close()
    if not o:
        raise HTTPException(400, "Operazione non permessa")
    # LA CONFERMA E' DEFINITIVA E NON SI RIPETE (set 2026): se il payout
    # e' in volo, in verifica o sospeso l'ordine e' ancora 'shipped', e
    # un secondo tocco ripasserebbe dall'uscita scavalcando l'orologio.
    if _in_pagamento(o):
        raise HTTPException(409, _rifiuto_in_pagamento(o, "conferma"))
    return await _poi_chat_mercatino(ordine_id, _sblocca_sats(ordine_id))


@app.post("/api/orders/{ordine_id}/disputa")
async def apri_disputa(ordine_id: int, x_tg_init_data: str = Header(""),
                                       barattolo_sessione: str = Cookie("")):
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    con = db()
    o = con.execute("SELECT * FROM ordini WHERE id=? AND compratore_id=? "
                    "AND stato IN ('locked','shipped','delivered')",
                    (ordine_id, user["id"])).fetchone()
    if not o:
        raise HTTPException(400, "Operazione non permessa")
    # ...E NON SI ANNULLA: a payout sospeso lo stato era ancora
    # 'shipped', quindi chi aveva confermato poteva aprire una disputa —
    # e il giro dell'orologio, che segue `payout_verso`, pagava il
    # venditore lo stesso, a disputa aperta.
    if _in_pagamento(o):
        con.close()
        raise HTTPException(409, _rifiuto_in_pagamento(o, "disputa"))
    # UN CODICE ALLA VOLTA (16 nov 2026): a codici aperti la disputa e'
    # sul codice DI TURNO, e solo nelle sue ore — passate quelle conta
    # come buono (punto 5 della proposta). Prima di aprire il primo
    # (o su un ordine al campo unico) resta sull'ordine intero.
    codice_k = 0
    if int(_campo(o, "codici_n", 0) or 0) > 0 and o["stato"] == "delivered":
        codice_k = int(o["codici_aperti"] or 0)
        if (time.time() - int(o["codice_aperto_il"] or 0)
                > ORE_CONFERMA_DIGITALE * 3600):
            con.close()
            raise HTTPException(400, MSG_CODICE_SCADUTO.format(
                ore=ORE_CONFERMA_DIGITALE, k=codice_k))
    # disputata resta 1 per sempre, anche a disputa risolta: e' la
    # memoria su cui si giudica il distintivo Specchiato
    con.execute("UPDATE ordini SET stato='dispute', disputata=1, "
                "aggiornato=? WHERE id=?",
                (int(time.time()), ordine_id))
    if codice_k:
        # nella stessa transazione: il moderatore decide QUEL codice
        con.execute("UPDATE ordini SET codice_disputa=? WHERE id=?",
                    (codice_k, ordine_id))
    con.commit()
    # La memoria che scoraggia le dispute-fotocopia: sui beni digitali
    # il caso «riscattato e negato» e' irrisolvibile, quindi si rende
    # antieconomico — il moderatore vede subito quante dispute ha gia'
    # aperto questo compratore, e la regola dichiarata prima
    # dell'acquisto: a zero prove vince chi ha consegnato in
    # piattaforma. La regola segue il BENE, non il canale: un buono
    # spedito fisicamente e' riscattabile uguale. Barattolo non puo'
    # verificare i riscatti; il moderatore invece PUO' chiedere
    # all'emittente quando e dove il codice e' stato riscattato.
    nota_digitale = ""
    if o["consegna_scelta"] == "digitale":
        gia_aperte = con.execute(
            "SELECT COUNT(*) AS n FROM ordini WHERE compratore_id=? "
            "AND disputata=1", (o["compratore_id"],)).fetchone()["n"]
        rivelato = ("contenuto RIVELATO" if o["consegnato"]
                    else "contenuto non ancora rivelato")
        # la foto e le correzioni sono FATTI, come per la busta: dicono
        # se il venditore ha dato qualcosa di inquadrabile e se il
        # contenuto e' cambiato prima che venisse letto. Il contenuto
        # in se' il moderatore lo legge dal dettaglio, che qui e' la
        # differenza dichiarata con la busta.
        if o["contenuto_file"]:
            rivelato += ", con un'immagine allegata"
        n = o["contenuto_correzioni"]
        if n:
            quando = time.strftime("%d/%m/%Y %H:%M",
                                   time.localtime(o["contenuto_corretto_il"]))
            rivelato += (f"; corretto {n} volt{'a' if n == 1 else 'e'} "
                         f"prima della rivelazione (ultima il {quando})")
        nota_digitale = (
            f"\n💾 Bene DIGITALE ({rivelato}; il contenuto si legge "
            f"dal dettaglio ordine). Regola dichiarata all'acquisto: "
            f"a zero prove vince il venditore che ha consegnato in "
            f"piattaforma — e per i beni RISCATTABILI (codici, buoni) "
            f"vale qualunque sia la modalità di consegna, anche "
            f"spediti fisicamente: il rischio sta nel bene, non nel "
            f"canale. Barattolo non può verificare i riscatti, ma tu "
            f"puoi chiedere all'emittente quando/dove il codice è "
            f"stato riscattato."
            f"\n📊 Dispute aperte da questo compratore, in totale: "
            f"{gia_aperte}.")
        if int(_campo(o, "codici_n", 0) or 0) > 0:
            nota_digitale += _nota_codici_moderatore(o, codice_k)
    # Il gemello per la via del punto di ritiro (mutuamente esclusivo
    # col digitale: via_punto implica consegna 'spedizione'): SOLO
    # fatti — SE e QUANDO la busta e' stata depositata, e se e' stata
    # corretta dopo (magari proprio a disputa aperta: per questo le
    # correzioni si contano) — MAI il contenuto, che a differenza del
    # bene digitale nessun moderatore puo' leggere.
    nota_punto = ""
    if o["via_punto"] and o["punto_barattolo"]:
        # LA RETE DI CASA HA UNA NOTA SUA, e non e' una variante di
        # quella dei terzi: li' la busta la deposita il VENDITORE e
        # «mai depositate» e' un rimprovero a lui, qui la scrive la
        # PIATTAFORMA quando il punto prende in carico — quindi
        # riusare quelle parole direbbe il falso su chi ha fatto cosa,
        # che e' precisamente l'unica cosa che una nota al moderatore
        # non puo' sbagliare.
        #
        # ⚠️ E QUI SI SCRIVE LA REGOLA DI DEFAULT, che e' la ragione
        # per cui la strada B esiste: se il punto ha segnato, a zero
        # prove chi ha spedito ha consegnato. E' il gemello esatto del
        # codice digitale («a zero prove vince chi ha consegnato») ed
        # e' DICHIARATA PRIMA dell'acquisto in `sicu-limiti` — non e'
        # una decisione che il moderatore prende leggendo questa nota,
        # e' quella che gli si ricorda mentre decide.
        pnt = punto_barattolo(o["punto_barattolo"])
        nome_p = pnt.get("nome") or o["punto_barattolo"]
        if o["punto_preso_il"]:
            quando_p = time.strftime(
                "%d/%m/%Y %H:%M", time.localtime(o["punto_preso_il"]))
            nota_punto = (
                f"\n\U0001f3ea PUNTO DI BARATTOLO ({nome_p}): il punto ha "
                f"segnato di aver RICEVUTO il pacco il {quando_p}, e da "
                f"lì il codice di ritiro l'ha scritto la piattaforma — "
                f"non il venditore. È un fatto NOSTRO con una data, e la "
                f"regola dichiarata prima dell'acquisto dice che da qui "
                f"in poi, a zero prove, chi ha spedito ha consegnato. "
                f"Dal banco alla mano di chi ritira non c'è più niente "
                f"che possiamo verificare: è lo stesso limite del "
                f"ritiro a mano.")
        else:
            # IL CASO OPPOSTO E' ALTRETTANTO UTILE, ed e' la meta' che
            # una nota scritta di fretta perderebbe: «il pacco non e'
            # mai arrivato al punto» e «e' arrivato e non l'hanno
            # ritirato» sono due storie diverse, e senza la presa in
            # carico il moderatore non poteva distinguerle.
            nota_punto = (
                f"\n\U0001f3ea PUNTO DI BARATTOLO ({nome_p}): il punto "
                f"NON ha mai segnato di aver ricevuto il pacco, quindi "
                f"su questa rete il codice di ritiro non è mai esistito "
                f"— lo scrive la piattaforma alla presa in carico, mai "
                f"il venditore. Il tracciamento del corriere è l'unica "
                f"cosa che dice dove sia arrivato.")
        if o["punto_preso_da"]:
            nota_punto += (f" Codice negozio del punto: "
                           f"{o['punto_preso_da']}.")
    elif o["via_punto"]:
        if o["busta_il"]:
            quando = time.strftime("%d/%m/%Y %H:%M",
                                   time.localtime(o["busta_il"]))
            stato_busta = f"istruzioni di ritiro depositate il {quando}"
            # il documento e' un fatto quanto la data: al moderatore
            # dice se il venditore ha dato al compratore qualcosa di
            # inquadrabile o solo un codice a mano. Il contenuto no —
            # nemmeno di quello, e da nessuna strada.
            if o["busta_file"]:
                stato_busta += " (con un documento allegato)"
            n = o["busta_correzioni"]
            if n:
                ultima = time.strftime(
                    "%d/%m/%Y %H:%M", time.localtime(o["busta_corretta_il"]))
                stato_busta += (f", poi corrett{'a' if n == 1 else 'e'} "
                                f"{n} volt{'a' if n == 1 else 'e'} "
                                f"(ultima il {ultima})")
        elif o["busta_diretta_il"]:
            # LA BUSTA DIRETTA: «MAI depositate» qui direbbe il falso
            # — il venditore ha dichiarato che il codice arriva
            # direttamente all'acquirente. E' un FATTO con data, ma
            # e' una dichiarazione di PARTE, e la nota lo etichetta
            # cosi': il moderatore pesa, non crede sulla parola.
            quando_d = time.strftime(
                "%d/%m/%Y %H:%M", time.localtime(o["busta_diretta_il"]))
            stato_busta = (f"il venditore ha DICHIARATO (il {quando_d}) "
                           f"che il codice di ritiro arriva direttamente "
                           f"all'acquirente, recapiti suoi "
                           f"sull'etichetta — è una dichiarazione di "
                           f"parte, non un fatto verificato")
        else:
            stato_busta = "istruzioni di ritiro MAI depositate"
        nota_punto = (
            f"\n📦 Spedizione a un LOCKER/PUNTO DI RITIRO: {stato_busta}. "
            f"Il contenuto della busta lo leggono solo le parti: la "
            f"piattaforma non può verificarlo.")
    # E il gemello della spedizione a CASA: stessa regola, stessi
    # fatti — indicato o no, quando, e quante volte corretto (magari
    # proprio a disputa aperta: per questo si contano). MAI il
    # contenuto, che nessun moderatore puo' leggere da nessuna strada:
    # qui dentro non si decifra niente, e c'e' la sentinella che lo
    # verifica (attenzione: legge anche i commenti — il nome della
    # funzione che non si chiama non va scritto nemmeno qui).
    nota_indirizzo = ""
    if o["indirizzo_atteso"] or o["indirizzo_il"]:
        if o["indirizzo_il"]:
            quando_i = time.strftime("%d/%m/%Y %H:%M",
                                     time.localtime(o["indirizzo_il"]))
            stato_ind = f"indirizzo indicato il {quando_i}"
            ni = o["indirizzo_correzioni"]
            if ni:
                ultima_i = time.strftime(
                    "%d/%m/%Y %H:%M",
                    time.localtime(o["indirizzo_corretto_il"]))
                stato_ind += (f", poi corrett{'o' if ni == 1 else 'o'} "
                              f"{ni} volt{'a' if ni == 1 else 'e'} "
                              f"(ultima il {ultima_i})")
            # LA CONFERMA DI CHI COMPRA (13 ott 2026, cantiere
            # indirizzo-giusto): il FATTO e la data, come il resto —
            # e quando manca si dice perche' puo' mancare, o un ordine
            # nato prima della casella sembrerebbe una conferma
            # rifiutata. Si legge con `keys()`: i banchi che eseguono
            # questo pezzo montano tabelle piu' strette della vera.
            conf_il = (o["indirizzo_confermato_il"]
                       if "indirizzo_confermato_il" in o.keys() else 0)
            if conf_il:
                quando_c = time.strftime("%d/%m/%Y %H:%M",
                                         time.localtime(conf_il))
                stato_ind += (f". L'acquirente lo ha CONFERMATO il "
                              f"{quando_c} («se è sbagliato, le spese "
                              f"di spedizione restano a mio carico»)")
            else:
                stato_ind += (". NESSUNA conferma dell'acquirente su "
                              "questo indirizzo (gli ordini nati prima "
                              "del 13 ott 2026 non la chiedevano)")
        else:
            stato_ind = "indirizzo MAI indicato dall'acquirente"
        nota_indirizzo = (
            f"\n📦 Spedizione a un INDIRIZZO: {stato_ind}. L'indirizzo lo "
            f"leggono solo le parti: non è mostrato ai moderatori.")
    # L'EMAIL PER IL CORRIERE: il FATTO e la data, MAI il valore
    # (decisione di Andrea). Al moderatore serve sapere se il codice
    # e' stato consegnato, e quello lo legge dalla dichiarazione del
    # venditore qui sotto: un recapito non lo aiuta a decidere e gli
    # mette in mano un dato personale che non gli serve — il
    # precedente dell'indirizzo, alla lettera.
    # ⚠️ QUI DENTRO NON SI DECIFRA NIENTE, e la sentinella che lo
    # verifica legge anche i commenti: il nome della funzione che non
    # si chiama non va scritto nemmeno qui.
    nota_email = ""
    if o["email_corriere_il"]:
        quando_e = time.strftime("%d/%m/%Y %H:%M",
                                 time.localtime(o["email_corriere_il"]))
        stato_em = f"lasciata il {quando_e}"
        ne = o["email_corriere_correzioni"]
        if ne:
            stato_em += (f", poi corretta {ne} "
                         f"volt{'a' if ne == 1 else 'e'}")
        if not o["email_corriere"] and not o["email_corriere_purgata_il"]:
            stato_em += ", e poi TOLTA dall'acquirente"
        nota_email = (
            f"\n📧 L'acquirente aveva lasciato un'email per il "
            f"corriere ({stato_em}). Il valore non è mostrato ai "
            f"moderatori: serve a sapere SE la scorciatoia c'era.")
    # IL SERVIZIO (ago 2026): la lezione avviene su Meet, fuori — qui
    # dentro non c'e' NIENTE, e la regola dichiarata all'acquisto e'
    # che si giudicano le CONDIZIONI, non il fatto. I due fatti sono
    # l'appuntamento CONFERMATO e il collegamento depositato in tempo:
    # tutti e due nostri, tutti e due col loro quando. Del
    # collegamento si dice il SE e il QUANDO, mai il contenuto — il
    # patto della busta.
    # E IL TERZO NUMERO E' IL RIPETUTO, che e' la sola difesa vera che
    # abbiamo: un link morto non lo possiamo aprire per sapere se
    # funzionava, ma un venditore che accumula dispute su questa via
    # e' un fatto NOSTRO. Le dispute VINTE contano piu' delle perse —
    # cinquanta no-show a proprio favore sono il profilo, non la
    # sfortuna. ATTENZIONE: il ripetuto smaschera il recidivo e NON
    # l'ondata (chi incassa cinquanta lezioni lo fa prima che la
    # prima disputa sia decisa): a quella risponde SERVIZIO_MAX_APERTI.
    nota_servizio = ""
    if o["consegna_scelta"] == "servizio":
        if o["appuntamento_confermato_il"]:
            quando_a = _quando_appuntamento(o["appuntamento_il"])
            stato_app = f"appuntamento {quando_a}, CONFERMATO dall'acquirente"
        elif o["appuntamento_il"]:
            stato_app = (f"appuntamento {_quando_appuntamento(o['appuntamento_il'])}, "
                         f"MAI confermato dall'acquirente")
        else:
            stato_app = "appuntamento MAI proposto dal venditore"
        np = o["appuntamento_proposte"]
        if np > 1:
            stato_app += f" (spostato {np - 1} volt{'a' if np == 2 else 'e'})"
        if o["accesso_il"]:
            quando_l = time.strftime("%d/%m/%Y %H:%M",
                                     time.localtime(o["accesso_il"]))
            stato_link = f"collegamento lasciato il {quando_l}"
            nl = o["accesso_correzioni"]
            if nl:
                stato_link += (f", poi cambiato {nl} "
                               f"volt{'a' if nl == 1 else 'e'}")
        else:
            stato_link = "collegamento MAI lasciato"
        vinte = con.execute(
            "SELECT COUNT(*) AS n FROM ordini WHERE venditore_id=? "
            "AND disputata=1 AND stato='released'",
            (o["venditore_id"],)).fetchone()["n"]
        perse = con.execute(
            "SELECT COUNT(*) AS n FROM ordini WHERE venditore_id=? "
            "AND disputata=1 AND stato='refunded' "
            "AND COALESCE(spese_rese_sats,0)=0",
            (o["venditore_id"],)).fetchone()["n"]
        nota_servizio = (
            f"\n📅 SERVIZIO: {stato_app}; {stato_link} (il collegamento "
            f"lo leggono solo le parti: non è mostrato ai moderatori). "
            f"Regola dichiarata all'acquisto: Barattolo non può sapere "
            f"se la prestazione c'è stata — si giudica se le CONDIZIONI "
            f"c'erano."
            f"\n📊 Dispute di questo venditore: {vinte} decise a suo "
            f"favore, {perse} a favore di chi ha comprato.")
    # LA NOTA DEL COMPRATORE, e qui la regola SI ROVESCIA: di indirizzo
    # e busta il moderatore vede il SE e il QUANDO, di questa vede anche
    # il COSA — esce da /api/orders come ogni altra colonna, ed e' una
    # scelta dichiarata anche nella pagina «I tuoi dati». Il motivo e'
    # lo stesso del contenuto digitale: «avevo chiesto la taglia L» e'
    # una lite che senza leggerla non si decide.
    # Il testo comunque NON si interpola qui — si legge nell'ordine,
    # sotto esc() — e la variabile non si chiama nota_* come le vicine:
    # li' «nota» vuol dire «la riga PER il moderatore», e la cosa di cui
    # si parla si chiama a sua volta nota.
    avviso_nota = ""
    if o["nota_compratore"]:
        avviso_nota = ("\n📝 L'acquirente aveva lasciato una NOTA "
                       "sull'ordine: la LEGGI nel dettaglio — a "
                       "differenza dell'indirizzo e della busta.")
    con.close()
    # DALLA PORTA DI TUTTI GLI AVVISI DA ADMIN (12 ott 2026): era un
    # ciclo suo su ADMIN_IDS, l'unico che in collaudo non scriveva
    # all'identita' 999. Il testo e' quello di sempre.
    await notifica_admin(
        f"⚠️ <b>Disputa aperta</b> sull'ordine #{ordine_id}. "
        "I sats restano bloccati in attesa della tua "
        "decisione." + nota_digitale + nota_punto
        + nota_indirizzo + nota_email + nota_servizio
        + avviso_nota, argomento="dispute")
    await notifica(o["venditore_id"],
                   "⚠️ L'acquirente ha aperto una <b>disputa</b>. Un moderatore "
                   "vi contattera' entrambi. I sats restano nel deposito "
                   "di garanzia.")
    return {"ok": True}


def pulisci_ordini_fantasma(con):
    """La purga delle LAPIDI: solo righe che qualcuno ha gia' guardato.

    Fino all'ago 2026 di suo c'era anche un DELETE secco sugli ordini
    'creato' scaduti, col commento «nessun sat e' coinvolto, e' solo
    pulizia» — vero SOLO se qualcuno ha chiesto a LNbits, e a chiedere
    c'e' un poll che vive nel telefono del compratore. Chi pagava e
    chiudeva l'app prima che rispondesse lasciava una riga mai
    verificata, e il DELETE si portava via il payment_hash, cioe'
    l'unico filo verso quel pagamento: i sats restavano in cassaforte
    senza un ordine, e nemmeno LNbits sa a chi renderli. Era la stessa
    regola che le lapidi difendono da sempre («un saldo deve avere una
    riga su cui posarsi»), scavalcata dalla porta di servizio.
    Ora quello sguardo lo da' controlla_abbandonati nell'orologio, che
    e' async e a LNbits ci puo' parlare: qui si spazza solo cio' che
    lui ha gia' dichiarato morto. NIENTE torna a cancellare un
    'creato' da questa parte, o il buco si riapre in silenzio (c'e' la
    sentinella in prove.py).
    """
    # Le LAPIDI degli annulli espliciti (ago 2026): restano finche' un
    # pagamento potrebbe ancora atterrarci sopra (la invoice vive 15
    # minuti dalla NASCITA dell'ordine, quindi a un'ora dall'annullo il
    # rischio e' zero da un pezzo — margine largo perche' a spazzarle
    # prima del giro di controlla_annullati non si deve arrivare mai).
    # Copre anche gli 'annullato' storici di aste e rimozioni: mai
    # pagati per costruzione, stessa pulizia del reaper.
    soglia_lapidi = int(time.time()) - 3600
    con.execute("DELETE FROM ordine_righe WHERE ordine_id IN "
                "(SELECT id FROM ordini WHERE stato='annullato' "
                "AND aggiornato < ?)", (soglia_lapidi,))
    con.execute("DELETE FROM ordini WHERE stato='annullato' "
                "AND aggiornato < ?", (soglia_lapidi,))
    # E le lapidi delle fatture di puntata (vita 10 min, soglia 2x come
    # per gli ordini): utili finche' la fattura puo' ancora essere
    # pagata — vedi controlla_annullati. Via con loro la puntata mai
    # partita (versato 0, nessun rilancio rimasto), cosi' la riga
    # UNIQUE si libera e si puo' ripartire da capo. NON e' un ritiro:
    # nessun sat e' mai entrato.
    # I 'creato' NON si toccano piu', per la ragione degli ordini qui
    # sopra: a dichiararli morti — dopo aver guardato — e'
    # controlla_abbandonati, e da li' passano come lapidi.
    con.execute("DELETE FROM rilanci WHERE stato='annullato' AND creato < ?",
                (int(time.time()) - RILANCIO_STANTIO,))
    con.execute("DELETE FROM puntate WHERE stato='attiva' AND "
                "versato_sats=0 AND NOT EXISTS "
                "(SELECT 1 FROM rilanci r WHERE r.puntata_id=puntate.id)")


def _incasso_del_motivo(motivo: str):
    """A CHI VA L'INCASSO (set 2026): ogni `motivo` della tabella
    `pagamenti` ha la SUA funzione, e i due giri dell'orologio
    (`controlla_annullati`, `controlla_abbandonati`) lo chiedono QUI
    invece di saperlo a memoria.
    IL DIFETTO CHE L'HA FATTO NASCERE: i due giri erano stati scritti
    quando in tabella c'era il solo banner, e passavano ogni riga a
    `_incassa_sblocco` senza guardare il motivo. Il 15 set 2026 e'
    arrivato `negozio_slug` con le sue rotte e il suo incasso — ma chi
    pagava il link (5.000 sats) e chiudeva l'app prima del poll si
    sarebbe visto aprire la porta del BANNER (20.000) senza che il
    link si scrivesse. La tabella lo prometteva dal primo giorno
    («GENERICA CON UN TIPO»); i giri no.
    UN MOTIVO SCONOSCIUTO TORNA None, e chi chiama NON TOCCA la riga:
    ne' un incasso tirato a indovinare ne' una lapide su una fattura
    che magari e' pagata. A dirlo e' il libro mastro («pagamento con
    un motivo che nessuno sa incassare»), e prima ancora una sentinella
    di `prove.py` che conta i motivi scritti dalle INSERT contro
    questo elenco: un motivo nuovo non nasce senza la sua cassa.
    Il dizionario si costruisce ALLA CHIAMATA: i nomi si risolvono
    quando servono, e un banco puo' metterci le sue casse di cartone."""
    return {"banner": _incassa_sblocco,
            "negozio_slug": _incassa_slug_negozio}.get(motivo)


# ---------- LA GUARDIA DELLA LIQUIDITA' (11 ott 2026) ------------------
# DA DOVE SI PARTIVA. Sul nodo la guardia oraria (`ronda-liquidita.sh
# --acinq`) suonava quando l'entrata dei SOLI canali ACINQ scendeva
# sotto 300.000, e ripeteva ogni sei ore: con cinque milioni di entrata
# su un altro canale l'avviso arrivava di continuo, e un allarme che
# arriva di continuo e' tappezzeria. La frase che lo reggeva — «Phoenix
# paga solo dal canale ACINQ» — veniva da UN acquisto fallito, il 5
# ott, il giorno stesso in cui il canale LNBiG nasceva.
# LA DOMANDA VERA e' se il nodo puo' fare gli scambi, e sono tre (piu' una):
#  1) ENTRATA: sommando i canali in linea, ci sta la garanzia piu'
#     grossa? (`LIQUIDITA_SCAMBIO_MAX`, lo specchio di `max_order_amount`
#     del coordinatore.)
#  2) DA PHOENIX: chi paga da Phoenix parte dal nodo di ACINQ. Se il
#     canale diretto non basta (`LIQUIDITA_PHOENIX_MIN`), si CHIEDE a
#     LND una strada da ACINQ a noi che non passi di li', dentro quel
#     che Phoenix lascia spendere di rete (4 sat + 0,4 %); e l'ultimo
#     salto — un canale nostro — deve avere l'entrata VERA per reggerla.
#     Solo se non c'e' nemmeno quella, e' un problema.
#  3) USCITA: sommando i canali in linea, resta almeno
#     `LIQUIDITA_USCITA_MIN`? SPENTA di serie (0), ed e' voluto: i sats
#     che si pagano a chi compra al rilascio sono quelli della garanzia
#     appena incassata, quindi l'uscita di uno scambio se la porta lo
#     scambio. Un pavimento fisso suonerebbe proprio il giorno in cui
#     tutti i venditori sono stati pagati.
#  4) UN ORDINE AL TETTO ESCE DA UN CANALE SOLO? (15 ott 2026, richiesta
#     di Andrea, `LIQUIDITA_USCITA_CANALE`): il canale in linea con piu'
#     uscita spendibile regge DA SOLO un ordine P2P al tetto in euro
#     (`P2P_MAX_EURO`, al cambio di adesso)? E' una PRUDENZA e non un
#     muro: Mostro non passa `max_parts`, e LND legge lo zero come 16
#     pezzi (`DefaultMaxParts`, routerrpc della 0.19.3) quando la
#     fattura di chi riceve dichiara MPP; senza MPP il payout esce
#     intero da un canale. SPENTA di serie come l'uscita, e per lo
#     stesso motivo. Senza tetto in euro o senza cambio e' un «non so»,
#     mai un allarme.
#  5) IL TETTO DEGLI APPESI DI ACINQ (15 ott 2026, cantiere
#     phoenix-blocca-sats-2, `LIQUIDITA_ACINQ_TETTO`): Eclair non tiene
#     appesi verso di noi piu' del PIU' PICCOLO dei due tetti del canale,
#     il suo e il nostro (`max_pending_amt_msat` dei due lati: 450k sul
#     canale da 1M), e una garanzia resta appesa per tutto lo scambio. Il
#     posto e' il tetto meno gli HTLC in ARRIVO; quel che puo' entrare e'
#     il piu' piccolo fra il posto e l'entrata spendibile; si prende il
#     canale ACINQ migliore, contro `LIQUIDITA_PHOENIX_MIN`. Sotto, la
#     stessa strada da ACINQ della domanda 2 (chiesta UNA volta per giro):
#     se c'e', e' buona. Un canale ACINQ senza i due tetti e' un «non so».
#     SPENTA di serie.
# NIENTE RIPETIZIONI: un avviso quando una domanda passa da buona a
# cattiva, uno quando tornano tutte buone, e in mezzo al massimo un
# promemoria ogni `LIQUIDITA_PROMEMORIA_S`. Lo stato sta nei timbri
# (come il freno del ponte): un deploy non raddoppia un allarme.
# QUI E NON SUL NODO, perche' qui ci sono gia' il ponte verso LND, il
# macaroon di SOLA LETTURA (`offchain:read info:read`, lo stesso del
# controllo della fattura P2P) e il bot: nessun segreto nuovo, nessuno
# script da installare la'. `lncli queryroutes` poi non sa partire da un
# altro nodo; la REST si' (`source_pub_key`).
# QUEL CHE NON SA: LND non conosce i saldi degli altri. La strada da
# ACINQ esiste «sulla carta» (canali, capienze, tariffe); che il nodo di
# ACINQ la scelga davvero lo dice solo un pagamento vero.
