@app.get("/vendor/nostr.js")
def vendor_nostr():
    """La libreria nostr-tools, servita da casa nostra e mai da una CDN:
    nessun terzo deve poter cambiare il codice della pagina dove
    qualcuno puo' incollare una nsec. File singolo committato a
    versione bloccata, rotta esplicita: mai StaticFiles su una
    directory (regola ferrea 3). Si puo' tenere in cache: cambia solo
    quando aggiorniamo il file apposta (e col ?v= nel src si sveglia).
    Dal set 2026 il file NON e' il bundle di serie: e' nostr-tools
    2.23.12 con cinque export in piu' (`schnorr`, `sha256`, `hmac`,
    `hkdf`, `secp256k1`) aggiunti A MANO nel blocco degli export --
    funzioni che il bundle conteneva gia' e non esponeva. Le vuole il
    client Mostro: l'identity proof e' una firma su un hash nudo (che
    finalizeEvent non sa fare), e la chat fra pari deriva le sue
    chiavi da un ECDH grezzo -- la coordinata X, che nip44 tiene per
    se' perche' `getConversationKey` la restituisce gia' passata
    dall'extract, cioe' irreversibile. Un diff di dodici righe su un
    file da 250 KB, mai una ricostruzione: chi aggiorna la libreria
    rimette quelle righe, e prove_bundle_nostr le pretende.
    Dal 1 ott 2026 porta anche un INNESTO, `nip49` (la chiave di
    moderatore che esce solo cifrata): scrypt e pbkdf2 di @noble/hashes
    2.0.1 e nip49.ts di nostr-tools, copiati a byte uguali in fondo al
    file da `innesta_nip49.py`, con il loro export. Chi aggiorna la
    libreria rifa' anche l'innesto: prove_chiave_moderatore_portatile
    lo pretende sul vettore di prova della NIP."""
    return FileResponse("vendor/nostr.bundle.js",
                        media_type="application/javascript",
                        headers={"Cache-Control": "public, max-age=86400"})


# L'INDIRIZZO DELL'ORDINE ON-CHAIN (20 ott 2026, cantiere onchain-tappa2,
# piano approvato da Andrea). La tappa 2 dello studio: ogni ordine ha un
# indirizzo SUO, un 2-di-3 fra tre chiavi pubbliche — compratore,
# venditore, Barattolo —, ciascuna presa dalla «xpub dedicata» del suo
# proprietario col numero che questo server assegna UNA volta sola. Il
# server fa i conti con `embit` (Python puro, la libreria di Specter) e
# il telefono li RIFA' col suo codice (`onchainVerificaRiga`): l'indirizzo
# si mostra solo se le due parti combaciano.
# ⚠️ QUI NON ENTRA NESSUNA CHIAVE PRIVATA, e non e' una promessa: le
# rotte accettano solo meta' pubbliche, rifiutano un `xprv`/`tprv` prima
# ancora di leggerlo, e non lo ripetono mai (ne' nella risposta ne' nel
# journal). Da una xpub si ricavano solo chiavi pubbliche.
# ⚠️ EMBIT E' FACOLTATIVO ALL'AVVIO: se manca (un VPS a cui nessuno l'ha
# ancora installato) il server parte lo stesso, le rotte che fanno i
# conti rispondono 503 e il pannello delle leve lo dice. La lista delle
# dipendenze e' `requirements.txt`; il collaudo la installa da solo
# (`deploy/collaudo/segui.sh`), la produzione a mano (PRODUZIONE).
try:
    from embit import bip32 as _embit_bip32
    from embit.descriptor import Descriptor as _EmbitDescrittore
    from embit.descriptor.checksum import add_checksum as _embit_checksum
    from embit.networks import NETWORKS as _EMBIT_RETI
    EMBIT = True
except ImportError:
    EMBIT = False
# LA RETE A PAROLE E PER EMBIT (30 ott 2026, cantiere onchain-mainnet):
# `ONCHAIN_RETE` e' una leva («signet» di serie, «mainnet» sul VPS il
# giorno dei sats veri), e qui c'e' TUTTO quel che da lei discende — il
# nome con cui embit la conosce ("main", non "mainnet"), i prefissi
# delle chiavi estese e degli indirizzi che i messaggi nominano, le
# versioni BIP-32 delle chiavi di conto dei wallet (vpub/zpub). Chi
# scrive «tpub» o «tb1» in un testo passa da qui, mai a mano: il
# telefono ha la stessa tabella (`ONCHAIN_RETI` in miniapp.html).
ONCHAIN_RETE_EMBIT = {"signet": "signet", "testnet4": "test",
                      "mainnet": "main"}
ONCHAIN_PREFISSI = {
    "signet": {"xpub": "tpub", "indirizzo": "tb1", "conto": "vpub",
               "strada_wallet": "m/84'/1'/0'"},
    "testnet4": {"xpub": "tpub", "indirizzo": "tb1", "conto": "vpub",
                 "strada_wallet": "m/84'/1'/0'"},
    "mainnet": {"xpub": "xpub", "indirizzo": "bc1", "conto": "zpub",
                "strada_wallet": "m/84'/0'/0'"},
}
# la versione BIP-32 della chiave di CONTO di un wallet BIP-84 (quella
# che Sparrow mostra): vpub sulle reti di prova, zpub su mainnet
ONCHAIN_VERSIONE_CONTO = {"signet": b"\x04\x5f\x1c\xf6",
                          "testnet4": b"\x04\x5f\x1c\xf6",
                          "mainnet": b"\x04\xb2\x47\x46"}


def _onchain_rete():
    """La rete di embit per la leva di adesso: si rilegge a ogni chiamata,
    cosi' il collaudo la cambia a caldo come ogni altra leva."""
    return _EMBIT_RETI[ONCHAIN_RETE_EMBIT[ONCHAIN_RETE]]


def _onchain_rete_di_prova(rete: str) -> bool:
    """Signet e testnet4 sono tutt'e due «la prova»: stesse forme (tb1,
    tpub, coin type 1), sats che non valgono niente."""
    return rete != "mainnet"


def _onchain_prefisso(cosa: str) -> str:
    """Il prefisso di `cosa` («xpub», «indirizzo», «conto»...) sulla
    rete di adesso, per i messaggi e i controlli."""
    return ONCHAIN_PREFISSI[ONCHAIN_RETE][cosa]


# una xpub e' lunga 111 caratteri: il tetto ferma i corpi assurdi prima
# che arrivino alla libreria
ONCHAIN_XPUB_MAX = 200
# il numero di un ordine sta sotto il primo indice indurito del BIP-32
ONCHAIN_NUMERO_MAX = 2 ** 31 - 1


def _onchain_sembra_privata(s: str) -> bool:
    """`xprv`, `tprv` e cugine (yprv, zprv, Yprv...): il prefisso basta
    per dire di no SENZA decodificarla — una privata non si legge."""
    return s[1:4].lower() == "prv"


def onchain_xpub_motivo(testo) -> str:
    """'' se `testo` e' una xpub DEDICATA buona, sennò il perche' (mai
    con la chiave dentro). Buona vuol dire: pubblica, della rete di
    adesso (una `tpub` su signet, una `xpub` su mainnet), e il conto
    del 2-di-3 — profondita' 4, ultimo passo 2' (ONCHAIN_STRADA_CONTO). Una xpub del wallet della persona, o di
    un'altra strada, non e' dedicata e si rifiuta: gli indirizzi
    nascerebbero dove il suo wallet non li cerca."""
    s = str(testo or "").strip()
    if not s or len(s) > ONCHAIN_XPUB_MAX:
        return "manca la chiave pubblica"
    if _onchain_sembra_privata(s):
        return "questa è una chiave PRIVATA: qui non entra, e non va data a nessuno"
    try:
        k = _embit_bip32.HDKey.from_string(s)
    except Exception:
        return "non è una chiave estesa leggibile"
    if k.is_private:
        return "questa è una chiave PRIVATA: qui non entra, e non va data a nessuno"
    if k.version != _onchain_rete()["xpub"]:
        return (f"non è una chiave di {ONCHAIN_RETE} (deve cominciare per "
                f"{_onchain_prefisso('xpub')})")
    if k.depth != 4 or k.child_number != 0x80000002:
        return f"non è il conto del 2-di-3 ({ONCHAIN_STRADA_CONTO})"
    return ""


def onchain_xpub_barattolo() -> tuple:
    """(xpub, di_cartone) della TERZA chiave. Vuota → quella di cartone
    dei vettori BIP-32 — MA SOLO SU SIGNET (30 ott 2026, cantiere
    onchain-mainnet): su mainnet la cartone ha la privata pubblica, e un
    2-di-3 con lei dentro lo svuota chiunque con una firma sola in piu';
    quindi ValueError, e l'on-chain resta fermo finche' la chiave di
    Barattolo non nasce dal pannello. Piena → deve essere PUBBLICA e
    della rete di adesso: una `xpub` di mainnet finche' la rete e' di
    prova (o una `tpub` su mainnet) e' un errore di chi ha scritto il
    config, e si dice (ValueError) invece di calcolare indirizzi che
    mischiano due reti.
    DAL 27 OTT 2026 VINCE LA CHIAVE SUL VPS (`_onchain_chiave_vps`), se
    un admin l'ha creata: e se nel config c'e' anche una ONCHAIN_XPUB
    diversa, le terze chiavi sarebbero due — si dice, e non si calcola
    niente."""
    s = (ONCHAIN_XPUB or "").strip()
    vps = _onchain_chiave_vps()
    if vps:
        if s and s != vps["xpub"]:
            raise ValueError("ONCHAIN_XPUB nel config non e' la chiave di "
                             "Barattolo sul VPS: le terze chiavi sarebbero "
                             "due. Va tolta la riga dal config")
        return vps["xpub"], False
    if not s:
        if not _onchain_rete_di_prova(ONCHAIN_RETE):
            raise ValueError("su mainnet la terza chiave di cartone non si "
                             "usa: la chiave di Barattolo va creata dal "
                             "pannello admin («₿ Crea la chiave di "
                             "Barattolo») prima di qualunque ordine")
        return XPUB_CARTONE, True
    if _onchain_sembra_privata(s):
        raise ValueError("ONCHAIN_XPUB e' una chiave privata: va tolta "
                         "dal config, e ruotata")
    try:
        k = _embit_bip32.HDKey.from_string(s)
    except Exception:
        raise ValueError("ONCHAIN_XPUB non si legge")
    if k.is_private:
        raise ValueError("ONCHAIN_XPUB e' una chiave privata: va tolta "
                         "dal config, e ruotata")
    if k.version != _onchain_rete()["xpub"]:
        raise ValueError(f"ONCHAIN_XPUB non e' di {ONCHAIN_RETE} (una "
                         f"{_onchain_prefisso('xpub')})")
    return s, False


# ------------- LA CHIAVE DI BARATTOLO STA SUL VPS (27 ott 2026) -------------
# Decisione di Andrea, cantiere onchain-disputa: «barattolo deve stare su
# vps con un backup che gli admin possono vedere chiaramente;
# concettualmente quella chiave puo' stare solo nella vps, altrimenti noi
# admin possiamo gia' dare 2 firme e di fatto vincere ogni causa in
# autonomia». Rovescia lo studio («privata solo nel firmatario sul
# nodo, mai sul VPS»), e il perche' e' quello: una chiave in tasca a un
# admin che e' anche parte di un ordine fa due firme da solo; sul VPS
# firma SOLO il codice, e solo dopo una decisione scritta
# (`_onchain_decide`), verso una delle due parti, coi conti di
# `_onchain_psbt_giudica`. Il prezzo, dichiarato: chi prende il VPS ha
# la terza chiave — e da sola non sposta niente, serve ancora una parte.
# LA NASCITA E' UN GESTO: un admin preme «Crea la chiave di Barattolo»
# nel pannello (mai al deploy, mai da sola); il file nasce una volta e
# non si sovrascrive. Le dodici parole stanno solo nel file (0600, in
# `chiavi/` accanto al database, fuori da git) e nell'archivio age del
# backup fuori sede: nessuna risposta le ripete, nemmeno agli admin —
# vederle sarebbe tenerle. Il pannello mostra cosa c'e' (xpub,
# impronta, data) e se l'ultimo backup la contiene.
# Finche' non nasce, la terza chiave e' quella DI CARTONE dei vettori
# BIP-32 (signet: niente di vero), la cui privata e' pubblica: con lei
# il server firma lo stesso, ed e' cosi' che il collaudo prova tutto.
ONCHAIN_SEME_CARTONE = "000102030405060708090a0b0c0d0e0f"   # BIP-32, vettore 1


def _onchain_file_chiave() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(DB)), "chiavi",
                        "onchain-barattolo.json")


def _onchain_chiave_vps():
    """Il file della chiave di Barattolo letto, o None se non e' nato.
    Un file che c'e' e non si legge NON e' None: alza, perche' tornare
    alla chiave di cartone in silenzio farebbe nascere indirizzi nuovi
    su una chiave che tutti conoscono."""
    f = _onchain_file_chiave()
    if not os.path.exists(f):
        return None
    with open(f, encoding="utf-8") as h:
        d = json.load(h)
    if not d.get("parole") or not d.get("xpub"):
        raise ValueError("il file della chiave di Barattolo e' monco")
    # LA RETE DEL FILE (30 ott 2026, cantiere onchain-mainnet): la chiave
    # e' nata su una rete e con il conto di quella (coin type 1 o 0);
    # se la leva e' cambiata dopo, quel file non e' la terza chiave di
    # questa rete — e tornare alla cartone in silenzio, su mainnet,
    # sarebbe il modo di far nascere indirizzi che chiunque puo' svuotare.
    # Si dice, e non si calcola niente: la chiave di mainnet si crea dal
    # pannello DOPO aver spostato quel file (PRODUZIONE, «L'ON-CHAIN IN
    # MAINNET»). I file di prima del 30 ott dicevano "signet" gia' allora.
    # (3 nov 2026, cantiere onchain-testnet4) fra le due reti di prova la
    # chiave resta buona: signet e testnet4 hanno lo stesso conto (coin
    # type 1) e le stesse tpub, e la chiave del collaudo nata su signet
    # vale su testnet4 senza che nessuno debba spostare un file sulla VM.
    # Fra la prova e mainnet no, come prima.
    if (_onchain_rete_di_prova(d.get("rete") or "signet")
            != _onchain_rete_di_prova(ONCHAIN_RETE)):
        raise ValueError(f"la chiave di Barattolo sul VPS e' nata su "
                         f"{d.get('rete') or 'signet'}, ma la rete adesso e' "
                         f"{ONCHAIN_RETE}: non e' la terza chiave di questa "
                         f"rete")
    return d


def _onchain_radice_barattolo(parole: str):
    from embit import bip39
    return _embit_bip32.HDKey.from_seed(
        bip39.mnemonic_to_seed(parole),
        version=_onchain_rete()["xprv"])


def onchain_crea_chiave_barattolo(admin_id: int) -> dict:
    """Il gesto dell'admin: dodici parole nuove (os.urandom), il conto
    del 2-di-3, il file. Una volta sola: se c'e' gia', o se il config
    dice un'altra xpub, no (ValueError). Torna solo la parte pubblica."""
    if (ONCHAIN_XPUB or "").strip():
        raise ValueError("nel config c'e' gia' una ONCHAIN_XPUB: la terza "
                         "chiave e' quella")
    f = _onchain_file_chiave()
    if os.path.exists(f):
        raise ValueError("la chiave di Barattolo c'e' gia': non si rifà")
    from embit import bip39
    parole = bip39.mnemonic_from_bytes(os.urandom(16))
    radice = _onchain_radice_barattolo(parole)
    xpub = radice.derive(ONCHAIN_STRADA_CONTO).to_public().to_string(
        version=_onchain_rete()["xpub"])
    d = {"parole": parole, "strada": ONCHAIN_STRADA_CONTO,
         "rete": ONCHAIN_RETE, "xpub": xpub,
         "impronta": radice.my_fingerprint.hex(),
         "creata_il": int(time.time()), "creata_da": int(admin_id)}
    os.makedirs(os.path.dirname(f), mode=0o700, exist_ok=True)
    # O_EXCL: due admin che premono insieme non fanno due chiavi
    fd = os.open(f, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as h:
        json.dump(d, h)
    return {k: d[k] for k in ("xpub", "impronta", "creata_il", "strada")}


def onchain_stato_chiave_barattolo() -> dict:
    """Quel che il pannello mostra della terza chiave, mai le parole:
    di cartone, sul VPS, o solo pubblica dal config (e allora qui non si
    firma). Col backup: l'ultimo archivio fuori sede riuscito
    (`backup-fuori.sh` scrive `.ultimo-successo`) e se e' venuto dopo
    la nascita della chiave, cioe' se la contiene."""
    try:
        vps = _onchain_chiave_vps()
    except Exception as e:
        return {"dove": "rotta", "motivo": str(e)[:200]}
    ultimo = 0
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(DB)), "backup",
                               "fuori", ".ultimo-successo")) as h:
            ultimo = int(h.read().strip() or 0)
    except Exception:
        pass
    if vps:
        return {"dove": "vps", "xpub": vps["xpub"],
                "impronta": vps.get("impronta", ""),
                "strada": vps.get("strada", ONCHAIN_STRADA_CONTO),
                "creata_il": int(vps.get("creata_il") or 0),
                "file": _onchain_file_chiave(),
                "backup_ultimo": ultimo,
                "nel_backup": ultimo >= int(vps.get("creata_il") or 0) > 0}
    if (ONCHAIN_XPUB or "").strip():
        return {"dove": "config", "xpub": ONCHAIN_XPUB.strip()}
    return {"dove": "cartone", "xpub": XPUB_CARTONE}


def _onchain_terza_chiave_a_parole() -> str:
    """La riga del pannello delle leve: dove sta la terza chiave."""
    try:
        st = onchain_stato_chiave_barattolo()
    except Exception:
        return "illeggibile"
    if st["dove"] == "vps":
        return ("sul VPS (impronta " + st.get("impronta", "?") + ")"
                + ("" if st.get("nel_backup") else
                   " — ⚠️ non ancora in un backup fuori sede"))
    if st["dove"] == "config":
        return (f"vera ({_onchain_prefisso('xpub')}), solo pubblica dal "
                "config: qui non firma")
    if st["dove"] == "rotta":
        return "⚠️ file illeggibile: " + st.get("motivo", "")
    if not _onchain_rete_di_prova(ONCHAIN_RETE):
        # (30 ott 2026) su mainnet la cartone non si usa: l'on-chain e'
        # fermo finche' la chiave non nasce, e il pannello lo grida
        return ("⚠️ di cartone su MAINNET: l'on-chain è FERMO (503) finché "
                "un admin non preme «₿ Crea la chiave di Barattolo»")
    return "di cartone (vettori BIP-32: la privata è pubblica)"


def _onchain_privata_barattolo(xpub: str):
    """La chiave estesa PRIVATA che sta dietro `xpub` (quella fotografata
    nell'indirizzo dell'ordine), o ValueError: di cartone, o quella del
    file — e allora la si ricontrolla, perche' firmare con una chiave
    che non e' quella dell'ordine non servirebbe a niente."""
    if xpub == XPUB_CARTONE:
        return _embit_bip32.HDKey.from_seed(bytes.fromhex(ONCHAIN_SEME_CARTONE))
    vps = _onchain_chiave_vps()
    if not vps or vps["xpub"] != xpub:
        raise ValueError("la chiave di Barattolo di questo ordine non sta "
                         "su questo server")
    conto = _onchain_radice_barattolo(vps["parole"]).derive(
        vps.get("strada") or ONCHAIN_STRADA_CONTO)
    if conto.to_public().to_string(
            version=_onchain_rete()["xpub"]) != xpub:
        raise ValueError("le parole del file non danno la sua xpub")
    return conto


def onchain_chiave(xpub: str, numero: int) -> str:
    """La chiave PUBBLICA numero `numero` di una xpub: `/0/numero`, la
    stessa strada di `onchainFiglia` nel telefono. Esadecimale compresso."""
    if not 0 <= int(numero) <= ONCHAIN_NUMERO_MAX:
        raise ValueError("numero fuori misura")
    k = _embit_bip32.HDKey.from_string(xpub).derive([0, int(numero)])
    return k.key.sec().hex()


def onchain_descrittore(compratore: str, venditore: str, barattolo: str) -> str:
    """Il descrittore col checksum del BIP-380, con le chiavi
    nell'ordine compratore, venditore, Barattolo — lo stesso testo che
    scrive il telefono, byte per byte (lo pretende la prova doppia)."""
    return _embit_checksum(
        f"wsh(sortedmulti(2,{compratore},{venditore},{barattolo}))")


def onchain_indirizzo_da(descrittore: str) -> str:
    """L'indirizzo di un descrittore sulla rete di prova. Dalla parte
    PRIMA del `#`: il checksum lo giudica la prova, non la libreria."""
    corpo = descrittore.split("#", 1)[0]
    return _EmbitDescrittore.from_string(corpo).address(
        _onchain_rete())


def _onchain_prepara_tabelle(con):
    """Le due tabelle della tappa 2.
    `onchain_xpub`: la xpub dedicata di chi ha acceso l'on-chain, una per
    persona (rifarla dallo stesso seme da' la stessa: si sovrascrive).
    `onchain_indirizzi`: un indirizzo per ordine, con i TRE numeri e le
    tre chiavi pubbliche fotografate — un indirizzo non si ricalcola mai
    dopo: se domani cambia una xpub, quelli di ieri restano veri.
    `ordine_id` resta vuoto fino alla tappa 3 (il foglio di pagamento):
    oggi gli indirizzi nascono dal foglio di prova, fra due admin. I
    vincoli UNIQUE sono la cintura del numero «una volta sola»: anche un
    giorno che il conto sbagliasse, il database direbbe di no."""
    con.execute("""CREATE TABLE IF NOT EXISTS onchain_xpub(
        tg_id INTEGER PRIMARY KEY,
        xpub TEXT NOT NULL,
        creato INTEGER DEFAULT 0,
        aggiornato INTEGER DEFAULT 0)""")
    con.execute("""CREATE TABLE IF NOT EXISTS onchain_indirizzi(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ordine_id INTEGER,
        rete TEXT NOT NULL,
        compratore_id INTEGER NOT NULL,
        venditore_id INTEGER NOT NULL,
        xpub_compratore TEXT NOT NULL,
        numero_compratore INTEGER NOT NULL,
        xpub_venditore TEXT NOT NULL,
        numero_venditore INTEGER NOT NULL,
        xpub_barattolo TEXT NOT NULL,
        numero_barattolo INTEGER NOT NULL,
        chiave_compratore TEXT NOT NULL,
        chiave_venditore TEXT NOT NULL,
        chiave_barattolo TEXT NOT NULL,
        descrittore TEXT NOT NULL,
        indirizzo TEXT NOT NULL UNIQUE,
        creato INTEGER DEFAULT 0,
        UNIQUE(xpub_compratore, numero_compratore),
        UNIQUE(xpub_venditore, numero_venditore),
        UNIQUE(xpub_barattolo, numero_barattolo))""")
    # DOVE RICEVE CHI VENDE (27 ott 2026): una riga per chi ha scelto un
    # wallet suo invece del conto di Barattolo. `firma` e' la prova che
    # la scelta l'ha fatta il SUO seme (`onchain_firma_destinazione`).
    con.execute("""CREATE TABLE IF NOT EXISTS onchain_incasso(
        tg_id INTEGER PRIMARY KEY,
        tipo TEXT NOT NULL,
        valore TEXT NOT NULL,
        firma TEXT NOT NULL,
        creato INTEGER DEFAULT 0,
        aggiornato INTEGER DEFAULT 0)""")
    # COME RICEVE CHI VENDE (28 ott 2026, cantiere onchain-verso-lightning):
    # «onchain» (di serie, nessuna riga), «lightning» o «ogni_volta». Non
    # e' un segreto e non sposta sats da solo: la destinazione vera la
    # firma sempre il seme di chi vende, al momento.
    con.execute("""CREATE TABLE IF NOT EXISTS onchain_modo(
        tg_id INTEGER PRIMARY KEY,
        modo TEXT NOT NULL,
        aggiornato INTEGER DEFAULT 0)""")


def _onchain_db():
    con = db()
    _onchain_prepara_tabelle(con)
    return con


def _onchain_prossimo(con, xpub: str) -> int:
    """Il prossimo numero di una xpub di PERSONA: uno dopo il piu' alto
    mai usato, da compratore O da venditore — la stessa persona fa
    tutt'e due le parti, e i suoi numeri sono una fila sola. Niente
    contatore da tenere in pari: la verita' sono le righe."""
    r = con.execute(
        "SELECT MAX(n) FROM ("
        " SELECT numero_compratore AS n FROM onchain_indirizzi"
        "  WHERE xpub_compratore=?"
        " UNION ALL"
        " SELECT numero_venditore FROM onchain_indirizzi"
        "  WHERE xpub_venditore=?)", (xpub, xpub)).fetchone()
    return 0 if r[0] is None else int(r[0]) + 1


def _onchain_prossimo_barattolo(con, xpub: str) -> int:
    r = con.execute("SELECT MAX(numero_barattolo) FROM onchain_indirizzi "
                    "WHERE xpub_barattolo=?", (xpub,)).fetchone()
    return 0 if r[0] is None else int(r[0]) + 1


def onchain_nuovo_indirizzo(con, compratore_id: int, venditore_id: int,
                            adesso: int) -> int:
    """Nasce l'indirizzo di un ordine: i tre numeri, le tre chiavi, il
    descrittore, l'indirizzo, e la riga. Torna l'id della riga.
    TUTTO DENTRO UNA TRANSAZIONE IMMEDIATE: due ordini nello stesso
    istante leggerebbero lo stesso «prossimo numero», e due ordini con
    la stessa chiave sono proprio il legame in catena che la chiave per
    ordine esiste per togliere. Con IMMEDIATE il secondo aspetta il
    primo; e se un giorno qualcuno la togliesse, i vincoli UNIQUE
    direbbero di no al posto suo.
    ValueError col motivo, detto a parole, se manca un pezzo."""
    if int(compratore_id) == int(venditore_id):
        raise ValueError("compratore e venditore sono la stessa persona")
    xb, _ = onchain_xpub_barattolo()
    con.execute("BEGIN IMMEDIATE")
    try:
        xp = {r["tg_id"]: r["xpub"] for r in con.execute(
            "SELECT tg_id, xpub FROM onchain_xpub WHERE tg_id IN (?, ?)",
            (int(compratore_id), int(venditore_id)))}
        xc, xv = xp.get(int(compratore_id)), xp.get(int(venditore_id))
        if not xc:
            raise ValueError("chi compra non ha ancora acceso l'on-chain")
        if not xv:
            raise ValueError("chi vende non ha ancora acceso l'on-chain")
        if xc == xv:
            # lo stesso seme su due conti: due chiavi uguali in un
            # 2-di-3 vorrebbero dire una persona sola con due firme
            raise ValueError("compratore e venditore hanno la stessa chiave")
        nc, nv = _onchain_prossimo(con, xc), _onchain_prossimo(con, xv)
        nb = _onchain_prossimo_barattolo(con, xb)
        kc, kv = onchain_chiave(xc, nc), onchain_chiave(xv, nv)
        kb = onchain_chiave(xb, nb)
        desc = onchain_descrittore(kc, kv, kb)
        indirizzo = onchain_indirizzo_da(desc)
        cur = con.execute(
            "INSERT INTO onchain_indirizzi(rete, compratore_id, venditore_id,"
            " xpub_compratore, numero_compratore, xpub_venditore,"
            " numero_venditore, xpub_barattolo, numero_barattolo,"
            " chiave_compratore, chiave_venditore, chiave_barattolo,"
            " descrittore, indirizzo, creato)"
            " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (ONCHAIN_RETE, int(compratore_id), int(venditore_id), xc, nc,
             xv, nv, xb, nb, kc, kv, kb, desc, indirizzo, int(adesso)))
        con.commit()
        return cur.lastrowid
    except Exception:
        con.rollback()
        raise


def onchain_riga_per(riga, tg_id: int, nome_altro: str = "") -> dict:
    """Un indirizzo d'ordine come lo vede UNA delle due parti: il suo
    ruolo, il suo numero (per rifare la sua chiave), le tre chiavi
    PUBBLICHE, descrittore e indirizzo. Le xpub NON escono: con la xpub
    dell'altro si leggerebbero in catena tutte le sue altre vendite — e'
    la decisione dello studio, «il descrittore porta le chiavi
    dell'ordine, non le xpub»."""
    da_compratore = int(riga["compratore_id"]) == int(tg_id)
    return {
        "id": riga["id"],
        "ruolo": "compratore" if da_compratore else "venditore",
        "mio_numero": riga["numero_compratore" if da_compratore
                           else "numero_venditore"],
        "controparte": nome_altro or "?",
        "chiavi": {"compratore": riga["chiave_compratore"],
                   "venditore": riga["chiave_venditore"],
                   "barattolo": riga["chiave_barattolo"]},
        "cartone": riga["xpub_barattolo"] == XPUB_CARTONE,
        "descrittore": riga["descrittore"],
        "indirizzo": riga["indirizzo"],
        "rete": riga["rete"],
        "creato": riga["creato"],
    }


def _onchain_indirizzo_pubblico(con, o) -> dict:
    """L'indirizzo di un ordine on-chain com'e' scritto in catena: tre
    chiavi pubbliche, descrittore, indirizzo. Lo vede chiunque veda
    l'ordine (anche il moderatore): e' quel che l'explorer gia' mostra
    quando i sats escono."""
    i = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                    (o["indirizzo_id"],)).fetchone()
    if not i:
        return {}
    return {"indirizzo": i["indirizzo"], "descrittore": i["descrittore"],
            "chiavi": {"compratore": i["chiave_compratore"],
                       "venditore": i["chiave_venditore"],
                       "barattolo": i["chiave_barattolo"]}}


def _onchain_nome(con, tg_id) -> str:
    r = con.execute("SELECT nome FROM utenti WHERE tg_id=?",
                    (int(tg_id),)).fetchone()
    return (r["nome"] if r and r["nome"] else "") or f"utente {tg_id}"


def _onchain_serve_embit():
    """503 se `embit` manca: la funzione esiste, la libreria no."""
    if not EMBIT:
        raise HTTPException(503, "Su questo server manca la libreria "
                                 "embit (requirements.txt)")


@app.get("/api/onchain/prova")
async def onchain_prova(x_tg_init_data: str = Header(""),
                        barattolo_sessione: str = Cookie("")):
    """LA PRIMA PORTA DELL'ON-CHAIN, e l'unica di questa tappa: dice al
    browser la TERZA chiave del 2-di-3 (l'xpub di Barattolo) e su che
    rete si sta giocando. Non scrive niente, non legge il database, non
    sa chi compra o chi vende: e' il foglio «₿ On-chain (prova)» del
    Profilo, dove si guardano le chiavi e si prova il ripristino.

    PASSA DAL CANCELLO, che e' il motivo per cui il cancello esisteva
    prima di lei (`onchain_ammesso`): leva spenta → 404, e un 404 e'
    piu' onesto di un 403 su una funzione che per il mondo non esiste
    ancora. Oggi vuol dire Andrea e Alan, e nessun altro.

    QUEL CHE NON C'E' QUI DENTRO, e si vede: nessuna chiave privata,
    nessun seme, nessun indirizzo. Il seme nasce e muore nel browser
    (regola ferrea 2 dal lato dei soldi), e l'indirizzo lo calcola il
    telefono con le tre meta' pubbliche. Il server non e' in grado di
    spendere niente, e non e' una promessa: e' che non ha i pezzi."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    # LA TERZA CHIAVE COME LA VEDE IL GIUDICE (30 ott 2026, cantiere
    # onchain-mainnet): fino a ieri qui si leggeva il solo config, e una
    # chiave nata sul VPS dal pannello (27 ott) il foglio la chiamava
    # ancora «di cartone». Adesso risponde `onchain_xpub_barattolo`, lo
    # stesso che decide gli indirizzi degli ordini; se dice di no (la
    # cartone su mainnet, il file nato su un'altra rete, due terze
    # chiavi) il foglio lo scrive in `ferma` e non disegna indirizzi.
    ferma = ""
    try:
        xpub_barattolo, cartone = onchain_xpub_barattolo()
    except ValueError as e:
        xpub_barattolo, cartone, ferma = XPUB_CARTONE, True, str(e)
    # LA TAPPA 2 (20 ott 2026): la mia xpub dedicata se l'ho gia' data,
    # con chi posso fare un indirizzo di prova (gli altri ammessi che
    # l'hanno data), e i miei ultimi indirizzi. Si legge anche senza
    # embit: i conti sono gia' fatti e fotografati nelle righe.
    con = _onchain_db()
    try:
        r = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                        (user["id"],)).fetchone()
        mia_xpub = r["xpub"] if r else ""
        # dove ricevo quando vendo (27 ott 2026): la riga com'e', firma
        # compresa — il telefono la rilegge col suo seme prima di dirla
        # «attiva», e una firma che non torna la dice vecchia
        d = con.execute("SELECT tipo, valore, firma FROM onchain_incasso "
                        "WHERE tg_id=?", (user["id"],)).fetchone()
        incasso = dict(d) if d else None
        controparti = [
            {"id": x["tg_id"], "nome": _onchain_nome(con, x["tg_id"])}
            for x in con.execute("SELECT tg_id FROM onchain_xpub "
                                 "WHERE tg_id != ? ORDER BY aggiornato DESC",
                                 (user["id"],))
            if onchain_ammesso(x["tg_id"])]
        indirizzi = []
        for x in con.execute(
                "SELECT * FROM onchain_indirizzi WHERE compratore_id=? "
                "OR venditore_id=? ORDER BY id DESC LIMIT 5",
                (user["id"], user["id"])):
            altro = (x["venditore_id"] if x["compratore_id"] == user["id"]
                     else x["compratore_id"])
            indirizzi.append(onchain_riga_per(x, user["id"],
                                              _onchain_nome(con, altro)))
    finally:
        con.close()
    return {
        "xpub": xpub_barattolo,
        # il VENDITORE dell'ordine finto: sempre di cartone, in questa
        # tappa non esiste un venditore vero da cui prendere un'xpub
        "xpub_venditore": XPUB_CARTONE_VENDITORE,
        # «di cartone» il foglio lo scrive a schermo: chi prova deve
        # sapere che quella terza chiave non e' di nessuno
        "cartone": cartone,
        # (30 ott 2026) il motivo per cui su questa rete non nasce
        # nessun indirizzo, o vuoto: il foglio lo mostra al posto
        # dell'esempio, e la cassa risponde 503 con le stesse parole
        "ferma": ferma,
        "rete": ONCHAIN_RETE,
        # la strada del CONTO del 2-di-3 (BIP-48), cosi' il client non
        # inventa numeri suoi e due dispositivi dello stesso seme fanno
        # lo STESSO indirizzo — che e' esattamente quel che la prova del
        # ripristino deve poter confrontare. L'ordine finto e' il numero
        # 0 di quel conto (`/0/0`), dalla tappa 2 (prima: `m/0/0`)
        "strada": ONCHAIN_STRADA_CONTO,
        # la tappa 2: senza embit il foglio lo dice, e i gesti nuovi no
        "embit": EMBIT,
        "mia_xpub": mia_xpub,
        "incasso": incasso,
        "quota_sats": onchain_quota_sats(),
        "controparti": controparti,
        "indirizzi": indirizzi,
    }


async def _avvisa_xpub_cambiata(tg_id: int):
    """La chiave on-chain di un account e' cambiata (14 nov 2026, terzo
    giro dell'audit): il journal e i moderatori lo sanno. Riceve solo il
    numero dell'account, mai la xpub: quella non si scrive da nessuna
    parte fuori dalla sua tabella (la regola della rotta)."""
    print(f"🔑 On-chain: la chiave di #{tg_id} e' cambiata, la vecchia "
          f"resta nello storico", flush=True)
    try:
        await notifica_admin(
            f"🔑 <b>On-chain: l'account #{tg_id} ha cambiato la sua "
            f"chiave.</b> Succede con un telefono nuovo o un ripristino; "
            f"gli ordini già nati tengono la chiave di prima, i prossimi "
            f"useranno la nuova. Se l'utente non ne sa niente, qualcuno ha "
            f"usato la sua sessione.", argomento="moderazione")
    except Exception as e:
        print(f"⚠️ Avviso ai moderatori non partito: {e}")


@app.post("/api/onchain/xpub")
async def onchain_xpub(req: Request, x_tg_init_data: str = Header(""),
                       barattolo_sessione: str = Cookie("")):
    """«ACCENDI L'ON-CHAIN» (20 ott 2026, tappa 2): il telefono manda la
    meta' PUBBLICA del conto del 2-di-3 (`m/48'/1'/0'/2'`), la «xpub
    dedicata». Da lei il server ricava le chiavi pubbliche degli ordini
    anche a telefono spento — e nient'altro: con una xpub non si spende.
    PASSA DAL CANCELLO, come ogni porta on-chain. Una privata si rifiuta
    prima di leggerla, e la risposta non ripete MAI quel che e' arrivato.
    Lo stesso seme da' la stessa xpub (un secondo telefono, un
    ripristino): si riscrive la riga e i numeri gia' usati restano suoi.
    Un seme DIVERSO da' un'altra xpub: gli indirizzi di ieri restano
    veri (le chiavi sono fotografate nelle righe), quelli di domani
    nascono dalla nuova."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    # il freno DOPO il cancello (a leva spenta la porta non esiste, e
    # non consuma niente) e prima di tutto il resto: anche un no conta
    _frena("onchain_xpub", user["id"])
    _onchain_serve_embit()
    d = await leggi_json(req)
    xpub = str(d.get("xpub") or "").strip()
    motivo = onchain_xpub_motivo(xpub)
    if motivo:
        raise HTTPException(400, motivo)
    adesso = int(time.time())
    con = _onchain_db()
    cambiata = ""
    try:
        # LO STORICO DELLA CHIAVE (14 nov 2026, terzo giro dell'audit):
        # una xpub DIVERSA da quella di prima cambia la chiave di chi vende
        # in tutti gli ordini on-chain che nasceranno. Per l'utente non
        # cambia niente (un telefono nuovo, un ripristino); dietro le
        # quinte la vecchia resta scritta, il journal lo dice e i
        # moderatori lo sanno, cosi' una sessione rubata non sostituisce
        # la chiave in silenzio.
        prima = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                            (user["id"],)).fetchone()
        if prima and prima[0] and prima[0] != xpub:
            cambiata = prima[0]
            con.execute("CREATE TABLE IF NOT EXISTS onchain_xpub_storia("
                        "tg_id INTEGER NOT NULL, xpub TEXT NOT NULL, "
                        "sostituita INTEGER NOT NULL)")
            con.execute("INSERT INTO onchain_xpub_storia(tg_id, xpub, "
                        "sostituita) VALUES (?,?,?)",
                        (user["id"], cambiata, adesso))
        con.execute(
            "INSERT INTO onchain_xpub(tg_id, xpub, creato, aggiornato) "
            "VALUES (?,?,?,?) ON CONFLICT(tg_id) DO UPDATE SET "
            "xpub=excluded.xpub, aggiornato=excluded.aggiornato",
            (user["id"], xpub, adesso, adesso))
        # un seme nuovo non sa piu' firmare la destinazione di quello
        # vecchio: la scelta si rifa' (fino ad allora, il conto di serie)
        d = con.execute("SELECT * FROM onchain_incasso WHERE tg_id=?",
                        (user["id"],)).fetchone()
        if d and not onchain_firma_valida(xpub, d["tipo"], d["valore"],
                                          d["firma"]):
            con.execute("DELETE FROM onchain_incasso WHERE tg_id=?",
                        (user["id"],))
        con.commit()
    finally:
        con.close()
    if cambiata:
        await _avvisa_xpub_cambiata(user["id"])
    return {"ok": True}


@app.post("/api/onchain/incasso")
async def onchain_incasso_scegli(req: Request, x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """«DOVE RICEVI I SATS» (27 ott 2026): chi vende sceglie un wallet
    suo. {tipo: 'indirizzo'|'xpub', valore, firma} lo scrive; {tipo:
    'barattolo'} torna al conto di serie (`/1/n` del 2-di-3), che il seme
    rifa' da se' e non ha bisogno di firme. La firma e' del seme del
    venditore (chiave `/2/0` del conto) e il server la controlla con la
    xpub dedicata: senza l'on-chain acceso non c'e' niente con cui
    controllarla. Gli ordini gia' nati tengono la destinazione di
    allora (fotografata alla cassa): vale dai prossimi."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_incasso", user["id"])
    _onchain_serve_embit()
    d = await leggi_json(req)
    tipo = str(d.get("tipo") or "")
    valore = str(d.get("valore") or "").strip()
    firma = str(d.get("firma") or "").strip().lower()
    con = _onchain_db()
    try:
        if tipo == "barattolo":
            con.execute("DELETE FROM onchain_incasso WHERE tg_id=?",
                        (user["id"],))
            con.commit()
            return {"ok": True}
        r = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                        (user["id"],)).fetchone()
        if not r:
            raise HTTPException(400, "Prima accendi l'on-chain")
        motivo = onchain_destinazione_motivo(tipo, valore, r["xpub"])
        if motivo:
            raise HTTPException(400, motivo)
        if tipo == "indirizzo":
            valore = onchain_indirizzo_esterno(tipo, valore, 0)
        if not onchain_firma_valida(r["xpub"], tipo, valore, firma):
            raise HTTPException(400, "La scelta non è firmata dal tuo seme: "
                                     "rifalla da questo telefono")
        if tipo == "xpub":
            # fin dove il wallet l'ha gia' usata (3 nov 2026): PRIMA di
            # riempire gli ordini in attesa, che prendono il prossimo indice
            await onchain_xpub_aggiorna_base(valore)
        adesso = int(time.time())
        con.execute(
            "INSERT INTO onchain_incasso(tg_id, tipo, valore, firma, creato,"
            " aggiornato) VALUES (?,?,?,?,?,?) ON CONFLICT(tg_id) DO UPDATE "
            "SET tipo=excluded.tipo, valore=excluded.valore, "
            "firma=excluded.firma, aggiornato=excluded.aggiornato",
            (user["id"], tipo, valore, firma, adesso, adesso))
        con.commit()
        # le vendite gia' fatte senza destinazione la prendono adesso
        # (27 ott 2026): l'ordine e' nato col 2-di-3, l'uscita si sceglie qui
        _onchain_prepara_ordini(con)
        riempiti = _onchain_riempi_incassi(con, user["id"])
        # ...e gli scambi P2P on-chain presi senza destinazione (30 ott 2026)
        riempiti_p2p = _p2p_onchain_riempi_incassi(con, user["id"])
        # ...e i RIMBORSI di quando ha messo lui i sats (10 nov 2026)
        _p2p_onchain_prepara(con)
        _onchain_riempi_rimborsi(con, user["id"])
        # ...e chi aspettava quell'indirizzo per rinunciare lo sa (17 nov)
        sbloccate = _p2p_onchain_rinunce_sbloccate(con, user["id"])
        con.commit()
    finally:
        con.close()
    await _p2p_onchain_avvisa_rinunce(sbloccate)
    # chi ha depositato lo sa (17 nov 2026, cantiere avviso-indirizzo)
    await _p2p_onchain_avvisa_riempiti(riempiti_p2p)
    for o in riempiti:
        if o["rilascio_chiesto_il"]:
            await notifica(o["compratore_id"],
                f"₿ <b>{html.escape(o['titolo'][:40])}:</b> chi vende ha "
                "scelto dove ricevere. Apri la Mini App: il tuo telefono firma "
                "il rilascio che avevi confermato, e i sats partono.")
    return {"ok": True, "ordini_aggiornati": len(riempiti)}


@app.post("/api/onchain/incasso/controlla")
async def onchain_incasso_controlla(req: Request,
                                    x_tg_init_data: str = Header(""),
                                    barattolo_sessione: str = Cookie("")):
    """IL CONTROLLO DI QUEL CHE SI INCOLLA (27 ott 2026, Andrea: «con
    controllo che indichi se va bene e se non è già stato usato»). Due
    domande, prima di firmare: e' una destinazione buona (lo stesso
    giudice del salvataggio, `onchain_destinazione_motivo`)? E, se e' un
    indirizzo, la rete l'ha gia' visto passare? Un indirizzo usato non e'
    un no — funziona — ma riusarlo lega le vendite fra loro agli occhi
    di chiunque guardi l'explorer, e va detto. Una chiave di conto
    (xpub) da' un indirizzo nuovo a ogni vendita: li' la domanda non
    c'e'. `usato` None = mempool muto, si dice «non so». Non scrive
    niente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_incasso_guarda", user["id"])
    _onchain_serve_embit()
    d = await leggi_json(req)
    tipo = str(d.get("tipo") or "")
    valore = str(d.get("valore") or "").strip()
    con = _onchain_db()
    try:
        r = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                        (user["id"],)).fetchone()
    finally:
        con.close()
    motivo = onchain_destinazione_motivo(tipo, valore, r["xpub"] if r else "")
    if motivo:
        return {"ok": False, "motivo": motivo, "usato": None, "tx": 0}
    if tipo != "indirizzo":
        # la chiave di conto: il primo `/0/i` mai usato (3 nov 2026), e
        # None se la rete e' muta. Non scrive: la base nasce al «salva»
        con = db()
        try:
            base = _onchain_xpub_base(con, valore)
        finally:
            con.close()
        primo = await onchain_xpub_scruta(valore, base)
        return {"ok": True, "motivo": "", "usato": False, "tx": 0,
                "indice": primo,
                "indirizzo": (onchain_indirizzo_esterno(tipo, valore, primo)
                              if primo is not None else "")}
    dove = onchain_indirizzo_esterno(tipo, valore, 0)
    try:
        j = await onchain_mempool_indirizzo(dove)
        tx = (int((j.get("chain_stats") or {}).get("tx_count") or 0)
              + int((j.get("mempool_stats") or {}).get("tx_count") or 0))
    except Exception:
        return {"ok": True, "motivo": "", "usato": None, "tx": 0}
    return {"ok": True, "motivo": "", "usato": tx > 0, "tx": tx}


@app.post("/api/onchain/prova/indirizzo")
async def onchain_prova_indirizzo(req: Request,
                                  x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """UN INDIRIZZO VERO FRA DUE AMMESSI (20 ott 2026, tappa 2): chi
    chiama e' il compratore, `venditore_id` e' un altro che ha acceso
    l'on-chain. Nascono i tre numeri, le tre chiavi e l'indirizzo
    (`onchain_nuovo_indirizzo`, embit), e il telefono li rifa' da se'
    prima di mostrarli. Nessun ordine dietro: e' il banco della tappa 2,
    l'ordine vero arriva con la tappa 3. Signet: i sats non valgono.
    PASSA DAL CANCELLO due volte: per chi chiama e per l'altro — un
    indirizzo con qualcuno che l'on-chain non lo vede sarebbe un
    indirizzo che lui non sa di avere."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_indirizzo", user["id"])
    _onchain_serve_embit()
    d = await leggi_json(req)
    try:
        venditore = int(d.get("venditore_id"))
    except (TypeError, ValueError):
        raise HTTPException(400, "Con chi? Manca la controparte")
    if not onchain_ammesso(venditore):
        raise HTTPException(400, "La controparte non può usare l'on-chain")
    try:
        onchain_xpub_barattolo()
    except ValueError as e:
        # la TERZA chiave storta e' un guasto del config, non di chi chiama
        raise HTTPException(503, str(e))
    con = _onchain_db()
    try:
        try:
            nuovo = onchain_nuovo_indirizzo(con, user["id"], venditore,
                                            int(time.time()))
        except ValueError as e:
            raise HTTPException(400, str(e))
        riga = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                           (nuovo,)).fetchone()
        return onchain_riga_per(riga, user["id"],
                                _onchain_nome(con, venditore))
    finally:
        con.close()


# ============ L'ORDINE ON-CHAIN: PAGARE, VEDERE, LIBERARE (23 ott 2026,
# cantiere onchain-tappa3, richiesta di Alan: «implementiamo tutto, poi
# faccio i test») ============
# Le tappe 3, 4 e 5 dello studio in un giro solo, sul collaudo e in
# signet. L'ordine on-chain vive in una tabella SUA (`onchain_ordini`) e
# non in `ordini`: le ronde del Lightning — la fattura che scade, l'auto-
# sblocco a 10 giorni, il payout verso una bolt11 — su un ordine che non
# ha ne' fattura ne' cassaforte farebbero la cosa sbagliata, e il
# principio dello studio e' «niente ibridi». Il prezzo d'uscita e' che
# questo ordine non passa (ancora) da spedito/consegnato: si paga, i
# sats restano nel 2-di-3, e si liberano con due firme.
# IL GIRO: la cassa crea l'indirizzo (le tre chiavi della tappa 2) e il
# prezzo piu' un margine per la rete; la ronda chiede a mempool se i
# sats sono arrivati con una conferma (→ 'pagato', lo stock scala); chi
# compra firma nel telefono «Libera i sats» (un PSBT verso l'incasso del
# venditore, il resto del margine torna a lui), e il telefono del
# venditore CO-FIRMA da solo appena si apre, dopo aver controllato che
# i sats vadano davvero a una chiave sua. Il rimborso e' lo stesso gesto
# a parti invertite. Il server non firma niente: legge, controlla e
# trasmette.
# GLI INCASSI NON SI CHIEDONO A NESSUNO: ciascuno riceve su una chiave
# del suo stesso seme, `/1/n` del conto del 2-di-3 (la catena «resto»,
# col numero dell'ordine). Il server la ricava dalla xpub, il telefono
# di chi incassa la rifa' dal seme prima di firmare: un indirizzo che
# non e' suo non lo co-firma.
# DAL 27 OTT 2026 chi vende puo' scegliere un wallet SUO (una vpub o un
# indirizzo): la scelta e' firmata dal suo seme e il suo telefono la
# rilegge prima di co-firmare («L'INCASSO SU UN WALLET PROPRIO», sotto).
try:
    from config import ONCHAIN_MEMPOOL_API
except ImportError:
    ONCHAIN_MEMPOOL_API = ""
ONCHAIN_MEMPOOL_DI_SERIE = {"signet": "https://mempool.space/signet/api",
                            "testnet4": "https://mempool.space/testnet4/api",
                            "mainnet": "https://mempool.space/api"}
# quanto vive un indirizzo che aspetta i sats: un bonifico on-chain non
# e' un tocco, e un giorno copre chi paga da un wallet che non ha sotto
# mano. Prenota lo stock per tutto quel tempo (`_riservati`).
ONCHAIN_ORE_ATTESA = 24
# IL MARGINE PER LA RETE: chi compra manda il prezzo PIU' questo, e
# all'uscita la commissione di rete si paga da qui; quel che avanza
# torna a lui nella stessa transazione. Tre volte la tariffa di
# mezz'ora su una transazione d'uscita tipica (un ingresso 2-di-3, due
# uscite: ~180 vbyte), mai meno del pavimento.
# IL PAVIMENTO E' 500 (28 ott 2026, Andrea, dopo un oggetto da 3.000 sats
# che ne chiedeva 4.000): con la rete scarica l'avanzo resta sotto la
# polvere (546) e va tutto alla rete, come una commissione fissa; con la
# rete cara comanda il triplo della tariffa, e l'avanzo torna a chi compra.
ONCHAIN_VBYTE_USCITA = 180
ONCHAIN_MARGINE_X = 3
ONCHAIN_MARGINE_MIN_SATS = 500
ONCHAIN_POLVERE = 546       # sotto, un'uscita costa piu' di quel che porta
_ONCHAIN_TARIFFA = {"sat_vb": 0.0, "quando": 0.0}


def onchain_mempool_api() -> str:
    e = str(ONCHAIN_MEMPOOL_API or "").strip().rstrip("/")
    return e or ONCHAIN_MEMPOOL_DI_SERIE.get(ONCHAIN_RETE, "")


async def onchain_mempool_utxo(indirizzo: str) -> list:
    """Le monete di un indirizzo, come le dice mempool: [{txid, vout,
    value, status: {confirmed, ...}}]. Solleva se la rete non risponde:
    chi chiama decide cosa dire."""
    async with httpx.AsyncClient(timeout=10) as cl:
        r = await cl.get(f"{onchain_mempool_api()}/address/{indirizzo}/utxo")
        r.raise_for_status()
        return r.json()


async def onchain_mempool_indirizzo(indirizzo: str) -> dict:
    """La scheda di un indirizzo, come la dice mempool: chain_stats e
    mempool_stats, con tx_count. Solleva se la rete non risponde."""
    async with httpx.AsyncClient(timeout=10) as cl:
        r = await cl.get(f"{onchain_mempool_api()}/address/{indirizzo}")
        r.raise_for_status()
        return r.json()


async def onchain_mempool_tariffa() -> float:
    """sat/vbyte per entrare in mezz'ora, tenuta dieci minuti. Muta → 2:
    signet e' quasi sempre vuota, e un margine si calcola lo stesso."""
    adesso = time.time()
    if _ONCHAIN_TARIFFA["sat_vb"] and adesso - _ONCHAIN_TARIFFA["quando"] < 600:
        return _ONCHAIN_TARIFFA["sat_vb"]
    try:
        async with httpx.AsyncClient(timeout=10) as cl:
            r = await cl.get(f"{onchain_mempool_api()}/v1/fees/recommended")
            r.raise_for_status()
            v = float(r.json().get("halfHourFee") or 0)
    except Exception:
        v = 0
    v = min(max(v, 1.0), 500.0) if v else 2.0
    _ONCHAIN_TARIFFA.update(sat_vb=v, quando=adesso)
    return v


async def onchain_mempool_invia(tx_hex: str) -> str:
    """Trasmette una transazione firmata; torna il txid. Il rifiuto della
    rete torna come ValueError col testo di mempool, che dice il perche'
    (commissione, firma, moneta gia' spesa)."""
    async with httpx.AsyncClient(timeout=15) as cl:
        r = await cl.post(f"{onchain_mempool_api()}/tx", content=tx_hex)
        if r.status_code >= 300:
            raise ValueError((r.text or "rifiutata")[:200])
        return r.text.strip()


def onchain_margine(sat_vb: float) -> int:
    return max(ONCHAIN_MARGINE_MIN_SATS,
               math.ceil(sat_vb * ONCHAIN_VBYTE_USCITA * ONCHAIN_MARGINE_X))


def onchain_incasso(xpub: str, numero: int) -> str:
    """L'indirizzo d'incasso di una persona per un ordine: `/1/numero`
    della sua xpub dedicata, a una firma (p2wpkh). Il telefono lo rifa'
    dal seme con la stessa strada (`onchainIncassoMio`)."""
    from embit.script import p2wpkh
    k = _embit_bip32.HDKey.from_string(xpub).derive([1, int(numero)])
    return p2wpkh(k.key).address(_onchain_rete())


# ============ L'INCASSO SU UN WALLET PROPRIO (27 ott 2026, cantiere
# onchain-incasso-esterno, richiesta di Andrea: «il venditore può
# comunque definire una xpub dalle impostazioni o inserire un indirizzo
# di un proprio wallet in cui ricevere») ============
# Di serie chi vende incassa su `/1/n` del suo conto di Barattolo
# (`onchain_incasso`), e il suo telefono lo rifa' dal seme prima di
# co-firmare. Ora puo' scegliere un wallet SUO: un indirizzo fisso, o la
# chiave pubblica di un conto (una `vpub` o `tpub` di Sparrow, BIP-84,
# profondita' 3), da cui ogni vendita prende un indirizzo nuovo `/0/i`.
# IL PERICOLO NUOVO, e la sua cura: un indirizzo che il seme non sa
# rifare e' un indirizzo che un server manomesso potrebbe cambiare, e il
# telefono co-firmerebbe un rilascio verso il ladro. Per questo la
# scelta si FIRMA col seme del venditore, con la chiave `/2/0` del conto
# del 2-di-3 (una catena che non serve a nient'altro): il server la
# verifica con la xpub dedicata che ha gia', e soprattutto la verifica
# il telefono del venditore prima della seconda firma, con la chiave che
# rifa' da se'. Chi non ha il seme non sa firmare una destinazione.
ONCHAIN_DESTINAZIONE_MAX = 120


def onchain_messaggio_destinazione(tipo: str, valore: str) -> bytes:
    """Il testo che il seme firma, lo stesso byte per byte nel telefono
    (`onchainMessaggioDestinazione`). La rete dentro: una firma di
    signet non vale il giorno della mainnet."""
    return (f"barattolo/onchain/incasso/v1\n{ONCHAIN_RETE}\n{tipo}\n"
            f"{valore}").encode("utf-8")


def onchain_firma_valida(xpub_dedicata: str, tipo: str, valore: str,
                         firma_hex: str) -> bool:
    """La firma (64 byte, r||s, quella di @scure/bip32) e' della chiave
    `/2/0` della xpub dedicata? Il testo e' quello della destinazione."""
    return onchain_firma_valida_testo(
        xpub_dedicata, onchain_messaggio_destinazione(tipo, valore), firma_hex)


def onchain_messaggio_ricevuto(oid: int, indirizzo: str) -> bytes:
    """«HO RICEVUTO», FIRMATO (28 ott 2026, cantiere onchain-verso-lightning):
    il testo che il seme di chi compra firma quando conferma prima che
    l'uscita ci sia. Il suo telefono lo rilegge prima di firmare DA SOLO
    il rilascio: una riga del server da sola non basta piu'. Lo stesso
    byte per byte nel telefono (`onchainMessaggioRicevuto`)."""
    return (f"barattolo/onchain/ricevuto/v1\n{ONCHAIN_RETE}\n{int(oid)}\n"
            f"{indirizzo}").encode("utf-8")


def onchain_firma_valida_testo(xpub_dedicata: str, messaggio: bytes,
                               firma_hex: str) -> bool:
    """La firma di `messaggio` (64 byte, r||s) e' della chiave `/2/0` della
    xpub dedicata? embit vuole il DER: lo si compone qui."""
    from embit import ec
    try:
        grezza = bytes.fromhex(str(firma_hex or ""))
        if len(grezza) != 64:
            return False

        def intero(b):
            b = b.lstrip(b"\x00") or b"\x00"
            return b"\x00" + b if b[0] & 0x80 else b
        r, s = intero(grezza[:32]), intero(grezza[32:])
        der = (b"\x30" + bytes([len(r) + len(s) + 4]) + b"\x02"
               + bytes([len(r)]) + r + b"\x02" + bytes([len(s)]) + s)
        chiave = _embit_bip32.HDKey.from_string(xpub_dedicata).derive([2, 0]).key
        h = hashlib.sha256(messaggio).digest()
        return bool(chiave.verify(ec.Signature.parse(der), h))
    except Exception:
        return False


def onchain_destinazione_motivo(tipo: str, valore: str,
                                xpub_dedicata: str = "") -> str:
    """'' se la destinazione e' buona, sennò il perche' a parole. Mai
    con la chiave dentro (come `onchain_xpub_motivo`)."""
    s = str(valore or "").strip()
    if not s or len(s) > ONCHAIN_DESTINAZIONE_MAX:
        return "manca l'indirizzo o la chiave"
    rete = _onchain_rete()
    if tipo == "indirizzo":
        from embit.script import address_to_scriptpubkey
        # un bech32 si puo' scrivere tutto maiuscolo (i QR lo fanno):
        # embit lo vuole minuscolo, e minuscolo si firma e si salva
        pref = _onchain_prefisso("indirizzo")
        s = s.lower() if s[:3].lower() == pref else s
        try:
            if address_to_scriptpubkey(s).address(rete) != s:
                raise ValueError
        except Exception:
            return f"non è un indirizzo di {ONCHAIN_RETE} (comincia per {pref})"
        return ""
    if tipo != "xpub":
        return "tipo di destinazione sconosciuto"
    if _onchain_sembra_privata(s):
        return "questa è una chiave PRIVATA: qui non entra, e non va data a nessuno"
    try:
        k = _embit_bip32.HDKey.from_string(s)
    except Exception:
        return "non è una chiave estesa leggibile"
    if k.is_private:
        return "questa è una chiave PRIVATA: qui non entra, e non va data a nessuno"
    if k.version not in (rete["xpub"], ONCHAIN_VERSIONE_CONTO[ONCHAIN_RETE]):
        return (f"non è una chiave di {ONCHAIN_RETE} (deve cominciare per "
                f"{_onchain_prefisso('conto')} o {_onchain_prefisso('xpub')})")
    if xpub_dedicata and s == xpub_dedicata:
        return "questa è la chiave del 2-di-3, non quella di un tuo wallet"
    if k.depth != 3:
        return ("serve la chiave del CONTO del tuo wallet (in Sparrow: "
                f"Impostazioni → «Keystore», {_onchain_prefisso('strada_wallet')})")
    return ""


def onchain_indirizzo_esterno(tipo: str, valore: str, indice: int) -> str:
    """L'indirizzo d'incasso da una destinazione scelta: l'indirizzo
    stesso, oppure `/0/indice` della chiave del conto (p2wpkh, BIP-84)."""
    if tipo == "indirizzo":
        s = str(valore).strip()
        return s.lower() if s[:3].lower() == _onchain_prefisso("indirizzo") else s
    from embit.script import p2wpkh
    if not 0 <= int(indice) <= ONCHAIN_NUMERO_MAX:
        raise ValueError("numero fuori misura")
    k = _embit_bip32.HDKey.from_string(valore).derive([0, int(indice)])
    return p2wpkh(k.key).address(_onchain_rete())


def _onchain_destinazione_viva(con, tg_id: int, xpub_dedicata: str):
    """La riga della destinazione di chi vende, SOLO se la sua firma
    vale ancora con la xpub dedicata di adesso (un seme nuovo la rende
    vecchia: si torna al conto di Barattolo). None = il conto di serie."""
    r = con.execute("SELECT * FROM onchain_incasso WHERE tg_id=?",
                    (int(tg_id),)).fetchone()
    if not r or not onchain_firma_valida(xpub_dedicata, r["tipo"],
                                         r["valore"], r["firma"]):
        return None
    return r


def _onchain_rimborsi_usati(con, tg_id: int, valore: str) -> int:
    """Uno dopo il piu' alto `/0/i` di `valore` gia' dato come RIMBORSO a
    questa persona, nel mercatino e nel P2P (0 = nessuno). Le tabelle e
    le colonne che non ci sono ancora valgono «nessuno»."""
    alto = 0
    for tab, chi in (("onchain_ordini", "compratore_id"),
                     ("p2p_onchain_ordini", "depositante_id"),
                     # (17 nov 2026) i depositi di garanzia delle raccolte
                     ("raccolta_depositi", "compratore_id")):
        try:
            r = con.execute(f"SELECT MAX(rimborso_indice) FROM {tab} WHERE "
                            f"{chi}=? AND rimborso_tipo='xpub' AND "
                            f"rimborso_valore=?", (int(tg_id), valore)).fetchone()
        except sqlite3.OperationalError:
            continue
        if r and r[0] is not None:
            alto = max(alto, int(r[0]) + 1)
    return alto


def _onchain_rimborso_di(con, tg_id: int, xpub_dedicata: str) -> tuple:
    """DOVE TORNA IL RIMBORSO di chi mette i sats (10 nov 2026, cantiere
    rimborso-wallet, scelta di Andrea: «aspettano il suo wallet»): il
    wallet SUO, firmato dal suo seme (`onchain_incasso`, la stessa
    scelta di quando vende), o niente — e allora resta vuoto finche' non
    sceglie (`_onchain_riempi_rimborsi`). Mai piu' il `/1/n` del seme di
    Barattolo: le 12 parole servono solo a firmare, e li' non deve mai
    esserci un sats. Torna (indirizzo, tipo, valore, firma, indice)."""
    dest = _onchain_destinazione_viva(con, tg_id, xpub_dedicata)
    if not dest:
        return "", "", "", "", 0
    indice = (_p2p_onchain_prossimo_esterno(con, tg_id, dest["valore"])
              if dest["tipo"] == "xpub" else 0)
    return (onchain_indirizzo_esterno(dest["tipo"], dest["valore"], indice),
            dest["tipo"], dest["valore"], dest["firma"], indice)


def _onchain_riempi_rimborsi(con, tg_id: int) -> list:
    """IL RIMBORSO SCELTO DOPO, gemello di `_onchain_riempi_incassi`: gli
    ordini e gli scambi in cui questa persona ha messo i sats, nati senza
    un suo wallet, prendono quello vivo di adesso — se non c'e' ancora
    una proposta firmata (un PSBT firmato non si cambia sotto i piedi).
    Torna quante righe ha riempito."""
    r = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                    (int(tg_id),)).fetchone()
    if not r or not _onchain_destinazione_viva(con, tg_id, r["xpub"]):
        return 0
    fatti = 0
    for tab, chi, stati in (
            ("onchain_ordini", "compratore_id", ("attesa", "pagato")),
            ("p2p_onchain_ordini", "depositante_id",
             ("preso", "depositato", "euro_inviati", "disputa"))):
        try:
            righe = con.execute(
                f"SELECT id FROM {tab} WHERE {chi}=? AND rimborso='' AND "
                f"proposta_psbt='' AND stato IN ({','.join('?' * len(stati))}) "
                "ORDER BY id", (int(tg_id), *stati)).fetchall()
        except sqlite3.OperationalError:
            continue
        for o in righe:
            ind, tipo, valore, firma, indice = _onchain_rimborso_di(
                con, tg_id, r["xpub"])
            if not ind:
                break
            fatti += con.execute(
                f"UPDATE {tab} SET rimborso=?, rimborso_tipo=?, "
                "rimborso_valore=?, rimborso_firma=?, rimborso_indice=?, "
                "aggiornato=? WHERE id=? AND rimborso='' AND proposta_psbt=''",
                (ind, tipo, valore, firma, indice, int(time.time()),
                 o["id"])).rowcount
    return fatti


def _onchain_prossimo_esterno(con, venditore_id: int, valore: str) -> int:
    """Il prossimo `/0/i` di una chiave di conto esterna: uno dopo il
    piu' alto gia' dato a un ordine di questo venditore con quella
    chiave. Una fila sua, staccata dai numeri del 2-di-3: cosi' i buchi
    restano pochi e il wallet ritrova le vendite (il limite di 20
    indirizzi vuoti di fila dei wallet)."""
    r = con.execute("SELECT MAX(incasso_indice) FROM onchain_ordini WHERE "
                    "venditore_id=? AND incasso_tipo='xpub' AND "
                    "incasso_valore=?", (int(venditore_id), valore)).fetchone()
    nostro = 0 if r[0] is None else int(r[0]) + 1
    # (10 nov 2026) la stessa chiave riceve anche i RIMBORSI di quando la
    # persona compra: una fila sola, o due ordini avrebbero lo stesso
    # indirizzo
    nostro = max(nostro, _onchain_rimborsi_usati(con, venditore_id, valore))
    # (15 nov 2026, cassa-negozio) ...e gli indirizzi dati alla CASSA IN
    # NEGOZIO: stessa chiave, stessa fila. La tabella nasce col primo
    # conto battuto: dove non c'e', non c'e' niente da contare.
    try:
        r = con.execute("SELECT MAX(oc_indice) FROM cassa_vendite WHERE "
                        "venditore_id=? AND oc_tipo='xpub' AND oc_valore=?",
                        (int(venditore_id), valore)).fetchone()
        if r and r[0] is not None and int(r[0]) >= 0:
            nostro = max(nostro, int(r[0]) + 1)
    except sqlite3.OperationalError:
        pass
    # (17 nov 2026, cantiere raccolta) ...e gli incassi dei depositi di
    # garanzia delle RACCOLTE di questa persona: stessa chiave, stessa fila
    try:
        r = con.execute("SELECT MAX(incasso_indice) FROM raccolta_depositi WHERE "
                        "venditore_id=? AND incasso_tipo='xpub' AND "
                        "incasso_valore=?", (int(venditore_id), valore)).fetchone()
        if r and r[0] is not None:
            nostro = max(nostro, int(r[0]) + 1)
    except sqlite3.OperationalError:
        pass
    # ...e mai sotto l'ultimo indirizzo che la RETE ha gia' visto usato
    # (3 nov 2026, `onchain_xpub_base`)
    return max(nostro, _onchain_xpub_base(con, valore))


# GLI INDIRIZZI GIA' USATI FUORI DA BARATTOLO (3 nov 2026, Andrea:
# «l'xpub deve dare indirizzi mai usati, invece suggerisce il primo con
# indice 0 che però è già stato usato»). La fila di `_onchain_prossimo_
# esterno` contava solo quel che Barattolo aveva dato: una chiave di
# conto che il wallet usava gia' ripartiva da `/0/0`. Adesso la rete dice
# fin dove la chiave e' stata usata: si leggono gli indirizzi `/0/i` su
# mempool, uno dopo l'altro, e ci si ferma a `ONCHAIN_XPUB_VUOTI` vuoti di
# fila (il limite di 20 dei wallet, lo stesso che usano per ritrovarsi le
# monete). La base = uno dopo l'ultimo usato, scritta in
# `onchain_xpub_base` (chiave PUBBLICA → numero: niente di segreto) alla
# scelta della destinazione, e riletta dalla ronda on-chain ogni
# `ONCHAIN_XPUB_RILEGGI` secondi, perche' il wallet continua a vivere fuori
# di qui. La rete muta non ferma niente: resta la base di prima.
ONCHAIN_XPUB_VUOTI = 20
ONCHAIN_XPUB_LETTURE_MAX = 200
ONCHAIN_XPUB_RILEGGI = 6 * 3600


def _onchain_xpub_base_prepara(con):
    con.execute("CREATE TABLE IF NOT EXISTS onchain_xpub_base ("
                "valore TEXT PRIMARY KEY, base INTEGER NOT NULL DEFAULT 0, "
                "letto INTEGER NOT NULL DEFAULT 0)")


def _onchain_xpub_base(con, valore: str) -> int:
    """La base scritta per questa chiave di conto, o 0."""
    try:
        r = con.execute("SELECT base FROM onchain_xpub_base WHERE valore=?",
                        (str(valore),)).fetchone()
    except sqlite3.OperationalError:
        return 0                      # la tabella non e' ancora nata
    return int(r[0]) if r and r[0] is not None else 0


async def onchain_xpub_scruta(valore: str, da: int = 0):
    """Il primo indice dopo l'ultimo `/0/i` che la rete ha visto usato,
    partendo da `da`; None se la rete non risponde (nessuna base nuova)."""
    ultimo, vuoti, i, letture = -1, 0, max(int(da), 0), 0
    while vuoti < ONCHAIN_XPUB_VUOTI and letture < ONCHAIN_XPUB_LETTURE_MAX:
        dove = onchain_indirizzo_esterno("xpub", valore, i)
        try:
            j = await onchain_mempool_indirizzo(dove)
        except Exception:
            return None
        letture += 1
        tx = (int((j.get("chain_stats") or {}).get("tx_count") or 0)
              + int((j.get("mempool_stats") or {}).get("tx_count") or 0))
        if tx > 0:
            ultimo, vuoti = i, 0
        else:
            vuoti += 1
        i += 1
    return max(int(da), ultimo + 1)


async def onchain_xpub_aggiorna_base(valore: str):
    """Rilegge la rete per questa chiave e alza la base (mai la abbassa).
    Torna la base di adesso, o None se la rete e' muta."""
    con = db()
    try:
        _onchain_xpub_base_prepara(con)
        prima = _onchain_xpub_base(con, valore)
    finally:
        con.close()
    nuova = await onchain_xpub_scruta(valore, prima)
    if nuova is None:
        return None
    con = db()
    try:
        _onchain_xpub_base_prepara(con)
        con.execute("INSERT INTO onchain_xpub_base(valore, base, letto) "
                    "VALUES (?,?,?) ON CONFLICT(valore) DO UPDATE SET "
                    "base=MAX(base, excluded.base), letto=excluded.letto",
                    (str(valore), int(nuova), int(time.time())))
        con.commit()
        return _onchain_xpub_base(con, valore)
    finally:
        con.close()


async def _onchain_xpub_rileggi_tutte():
    """La ronda: le chiavi di conto scelte come destinazione, lette da
    piu' di `ONCHAIN_XPUB_RILEGGI` secondi (o mai). Una alla volta; un
    errore salta quella e basta."""
    con = db()
    try:
        _onchain_prepara_tabelle(con)
        _onchain_xpub_base_prepara(con)
        valori = [r[0] for r in con.execute(
            "SELECT DISTINCT i.valore FROM onchain_incasso i LEFT JOIN "
            "onchain_xpub_base b ON b.valore=i.valore WHERE i.tipo='xpub' "
            "AND COALESCE(b.letto, 0) < ?",
            (int(time.time()) - ONCHAIN_XPUB_RILEGGI,))]
    finally:
        con.close()
    for v in valori:
        try:
            await onchain_xpub_aggiorna_base(v)
        except Exception as e:
            print(f"⚠️ On-chain: chiave di conto non riletta "
                  f"({type(e).__name__})", flush=True)


def _onchain_incasso_mio(tg_id: int) -> str:
    """'indirizzo' | 'xpub' se chi vende ha una destinazione viva (firmata
    dal seme di adesso), sennò ''. Muto sui guasti: e' una voce del
    profilo, non un giudizio — quello lo da' la cassa."""
    if not EMBIT:
        return ""
    try:
        con = _onchain_db()
        try:
            r = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                            (int(tg_id),)).fetchone()
            dest = (_onchain_destinazione_viva(con, tg_id, r["xpub"])
                    if r else None)
        finally:
            con.close()
    except Exception:
        return ""
    return dest["tipo"] if dest else ""


ONCHAIN_MSG_SENZA_DESTINAZIONE = (
    "Chi vende non ha ancora scelto dove ricevere on-chain: i sats restano "
    "al sicuro nel 2-di-3, ed escono appena lo fa")


def _onchain_riempi_incassi(con, venditore_id: int) -> list:
    """L'INCASSO SCELTO DOPO (27 ott 2026): gli ordini on-chain di chi vende
    nati senza destinazione (incasso vuoto), ancora in attesa o pagati e
    senza proposta, prendono quella viva di adesso — con la sua firma,
    che il telefono di chi vende rilegge prima della seconda firma. Torna
    le righe riempite (per gli avvisi). Senza destinazione viva: niente."""
    r = con.execute("SELECT xpub FROM onchain_xpub WHERE tg_id=?",
                    (int(venditore_id),)).fetchone()
    dest = _onchain_destinazione_viva(con, venditore_id, r["xpub"]) if r else None
    # (28 ott 2026) chi riceve in Lightning, o sceglie ogni volta, decide
    # ordine per ordine allo sblocco: niente incassi riempiti da soli.
    # (9 nov 2026) il modo e' quello di OGNI ordine: l'annuncio vince sul
    # Profilo, quindi si guarda riga per riga
    if not dest:
        return []
    righe = [x for x in con.execute(
        "SELECT * FROM onchain_ordini WHERE venditore_id=? AND incasso='' "
        "AND stato IN ('attesa','pagato') AND proposta_psbt='' ORDER BY id",
        (int(venditore_id),)).fetchall()
             if onchain_modo_ordine(con, x) == "onchain"]
    fatti = []
    for o in righe:
        indice = (_onchain_prossimo_esterno(con, venditore_id, dest["valore"])
                  if dest["tipo"] == "xpub" else 0)
        cur = con.execute(
            "UPDATE onchain_ordini SET incasso=?, incasso_tipo=?,"
            " incasso_valore=?, incasso_firma=?, incasso_indice=?,"
            " aggiornato=? WHERE id=? AND incasso='' AND proposta_psbt=''",
            (onchain_indirizzo_esterno(dest["tipo"], dest["valore"], indice),
             dest["tipo"], dest["valore"], dest["firma"], indice,
             int(time.time()), o["id"]))
        if cur.rowcount:
            fatti.append(o)
    return fatti


def onchain_quota_sats() -> int:
    """La quota fissa viva: pannello, sennò config, sennò codice."""
    return int(leva_scrivibile("ONCHAIN_QUOTA_FISSA_SATS") or 0)


def _onchain_prepara_ordini(con):
    """L'ordine on-chain: la cassa (prezzo, margine, importo), l'indirizzo
    (riga di `onchain_indirizzi`), i due incassi, le monete viste, la
    proposta d'uscita firmata da una parte e la transazione che chiude.
    `dettagli` e' la fotografia della consegna scelta alla cassa (JSON),
    come le colonne gemelle di `ordini`."""
    con.execute("""CREATE TABLE IF NOT EXISTS onchain_ordini(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        indirizzo_id INTEGER NOT NULL UNIQUE,
        annuncio_id INTEGER NOT NULL,
        compratore_id INTEGER NOT NULL,
        venditore_id INTEGER NOT NULL,
        quantita INTEGER NOT NULL DEFAULT 1,
        titolo TEXT NOT NULL DEFAULT '',
        prezzo_sats INTEGER NOT NULL,
        margine_sats INTEGER NOT NULL,
        importo_sats INTEGER NOT NULL,
        incasso TEXT NOT NULL,
        rimborso TEXT NOT NULL,
        dettagli TEXT NOT NULL DEFAULT '{}',
        stato TEXT NOT NULL DEFAULT 'attesa',
        -- attesa | pagato | rilasciato | rimborsato | scaduto | annullato
        visti_sats INTEGER DEFAULT 0,
        ricevuti_sats INTEGER DEFAULT 0,
        utxo TEXT DEFAULT '[]',
        pagato_il INTEGER DEFAULT 0,
        proposta_verso TEXT DEFAULT '',
        proposta_psbt TEXT DEFAULT '',
        proposta_da INTEGER DEFAULT 0,
        proposta_il INTEGER DEFAULT 0,
        txid_uscita TEXT DEFAULT '',
        chiuso_il INTEGER DEFAULT 0,
        scade INTEGER NOT NULL,
        creato INTEGER NOT NULL,
        aggiornato INTEGER NOT NULL)""")
    # 27 ott 2026: la destinazione scelta dal venditore, fotografata
    # alla cassa (vuota = il suo conto di Barattolo, `/1/n`), e la quota
    # fissa di Barattolo col suo indirizzo. Le colonne si aggiungono a
    # una tabella che esiste gia' dal 23 ott.
    gia = {r[1] for r in con.execute("PRAGMA table_info(onchain_ordini)")}
    for col, tipo in (("incasso_tipo", "TEXT DEFAULT ''"),
                      ("incasso_valore", "TEXT DEFAULT ''"),
                      ("incasso_firma", "TEXT DEFAULT ''"),
                      ("incasso_indice", "INTEGER DEFAULT 0"),
                      ("quota_sats", "INTEGER DEFAULT 0"),
                      ("quota_indirizzo", "TEXT DEFAULT ''"),
                      # 27 ott 2026, la strada A: l'ordine di sempre in
                      # `ordini` che nasce quando i sats arrivano (0 =
                      # un ordine on-chain di prima, che vive solo qui)
                      ("ordine_id", "INTEGER DEFAULT 0"),
                      # 27 ott 2026, cantiere onchain-disputa: chi ha
                      # deciso che Barattolo firmasse (un moderatore, o
                      # chi vende ricevendo il reso), quando e perche'
                      # ('disputa' | 'reso'). Con la decisione la
                      # proposta e' di Barattolo: `proposta_da` resta 0
                      ("decisione_da", "INTEGER DEFAULT 0"),
                      ("decisione_il", "INTEGER DEFAULT 0"),
                      ("decisione_perche", "TEXT DEFAULT ''"),
                      # 27 ott 2026 sera: chi compra ha confermato quando
                      # chi vende non aveva ancora scelto dove ricevere;
                      # il suo telefono firma appena l'incasso c'e'
                      ("rilascio_chiesto_il", "INTEGER DEFAULT 0"),
                      # 28 ott 2026, cantiere onchain-verso-lightning: la
                      # conferma firmata dal seme di chi compra
                      # (`onchain_messaggio_ricevuto`), e il cambio in
                      # Lightning di chi vende (JSON delle parti pubbliche:
                      # fornitore, id, quanto, la scadenza della fattura)
                      ("rilascio_firma", "TEXT DEFAULT ''"),
                      ("cambio", "TEXT DEFAULT ''"),
                      # 9 nov 2026: chi vende sa gia' del pagamento visto
                      # nel mempool (l'avviso «in arrivo», una volta sola)
                      ("visto_avvisato", "INTEGER DEFAULT 0"),
                      # 10 nov 2026, cantiere rimborso-wallet (Andrea: i
                      # sats non stanno mai nel seme di Barattolo): il
                      # rimborso di chi mette i sats va al wallet SUO,
                      # con la firma del suo seme, come l'incasso. Vuoto =
                      # aspetta la sua scelta
                      ("rimborso_tipo", "TEXT DEFAULT ''"),
                      ("rimborso_valore", "TEXT DEFAULT ''"),
                      ("rimborso_firma", "TEXT DEFAULT ''"),
                      ("rimborso_indice", "INTEGER DEFAULT 0"),
                      # 16 nov 2026, cantiere payjoin: la porta del
                      # PayJoin di questo ordine (`/api/payjoin/<gettone>`),
                      # a caso e una per ordine — il numero dell'ordine
                      # si indovina, questa no. Vuota = un ordine di prima
                      ("payjoin_gettone", "TEXT DEFAULT ''"),
                      # 17 nov 2026, cantiere onchain-grossi-uscita: 1 se
                      # alla nascita l'ordine stava sopra la soglia degli
                      # acquisti grossi (`onchain_consigliato`). Fissato
                      # QUI e non rifatto col cambio di domani: chi vende
                      # riceve on-chain anche se aveva scelto Lightning
                      # (`onchain_modo_ordine`). 0 = un ordine di prima
                      ("grosso", "INTEGER DEFAULT 0")):
        if col not in gia:
            con.execute(f"ALTER TABLE onchain_ordini ADD COLUMN {col} {tipo}")


# ------------- L'ORDINE ON-CHAIN E' UN ORDINE DI SEMPRE -------------
# (27 ott 2026, cantiere onchain-ordini, la strada A scelta da Andrea:
# «il concetto e' deposito sats, LN o on-chain… gli step devono essere
# uguali, cambia solo il metodo di pagamento: per l'utente e' un QR».)
# Rovescia «PERCHE' UNA TABELLA SUA» della tappa 3, ma a meta': la
# tabella `onchain_ordini` resta, ed e' la CASSAFORTE dell'ordine — il
# suo indirizzo, le sue monete, le sue firme — come LNbits lo e' per il
# Lightning. Quando i sats arrivano nasce la riga in `ordini` con
# cassaforte 'onchain', e da li' l'ordine fa la strada di tutti:
# `_incassa_ordine` (stock, avvisi, offerte, carrello), «Ordini», la
# spedizione, la chat, il feedback.
# 'onchain' NON sta in CASSAFORTI, apposta: ogni tubo del Lightning che
# provasse a pagare da qui alza in `_chiavi_cassaforte` (fail-closed).
# Le due uscite di sempre, `_sblocca_sats` e `_rimborsa_compratore`, lo
# riconoscono prima e aspettano le due firme (`_onchain_uscita_fatta`).
# PERCHE' L'ORDINE NASCE AL PAGAMENTO E NON ALLA CASSA: un indirizzo
# vive 24 ore, una fattura 15 minuti, e sulla riga 'creato' di `ordini`
# lavorano il reaper, la prenotazione dello stock e la ripresa della
# fattura, tutti col tempo del Lightning. Fino al pagamento l'ordine si
# segue dalla pagina On-chain, col suo QR.
CASSAFORTE_ONCHAIN = "onchain"


def _onchain_nasce_ordine(con, o) -> int:
    """La riga di `ordini` di un ordine on-chain appena pagato, ancora
    'creato': la passa a 'locked' `_incassa_ordine`, come per il
    Lightning. Stessa transazione dello 'pagato' (il chiamante
    committa). Le colonne sono quelle della cassa (`compra`), dai
    `dettagli` fotografati all'acquisto; la fattura non c'e'."""
    d = json.loads(o["dettagli"] or "{}")
    adesso = int(time.time())
    ind = d.get("indirizzo") or ""
    con.execute(
        "INSERT INTO ordini(cassaforte,annuncio_id,compratore_id,venditore_id,"
        "prezzo_sats,stato,payment_hash,invoice,creato,aggiornato,"
        "cambio_ordine,consegna_scelta,punto_ritiro,via_punto,rete_punto,"
        "tipo_punto,punto_barattolo,zona_sped,paese_sped,domestico_sped,"
        "nota_compratore,email_corriere,email_corriere_il,indirizzo,"
        "indirizzo_il,indirizzo_atteso,spedizione_sats,protezione_sats,"
        "quantita) "
        "VALUES(?,?,?,?,?,'creato','','',?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (CASSAFORTE_ONCHAIN, o["annuncio_id"], o["compratore_id"],
         o["venditore_id"], o["prezzo_sats"], o["creato"], adesso,
         int(d.get("cambio_ordine") or 0) or cambio_noto_ora(),
         d.get("consegna") or "", d.get("punto_ritiro") or "",
         int(d.get("via_punto") or 0), d.get("rete_punto") or "",
         d.get("tipo_punto") or "", d.get("punto_barattolo") or "",
         d.get("zona") or "", d.get("paese") or "", d.get("domestico") or "",
         d.get("nota") or "", d.get("email_corriere") or "",
         o["creato"] if d.get("email_corriere") else 0,
         ind, o["creato"] if ind else 0, int(d.get("indirizzo_atteso") or 0),
         int(d.get("spedizione_sats") or 0), int(d.get("protezione_sats") or 0),
         o["quantita"] or 1))
    oid = con.execute("SELECT last_insert_rowid() AS i").fetchone()["i"]
    if d.get("indirizzo_confermato_il"):
        con.execute("UPDATE ordini SET indirizzo_confermato_il=? WHERE id=?",
                    (int(d["indirizzo_confermato_il"]), oid))
    # le risposte alle domande del venditore (6 nov 2026), gia' cifrate
    # alla cassa: con un UPDATE a parte, il patto della conferma qui sopra
    if d.get("risposte"):
        con.execute("UPDATE ordini SET risposte=?, risposte_il=? "
                    "WHERE id=?", (d["risposte"], o["creato"], oid))
    con.execute("UPDATE onchain_ordini SET ordine_id=? WHERE id=?",
                (oid, o["id"]))
    return oid


def _onchain_di_ordine(con, ordine_id: int):
    """La cassaforte on-chain di un ordine di sempre, o None. La tabella
    nasce col primo gesto on-chain: dove non c'e', non c'e' niente."""
    try:
        return con.execute("SELECT * FROM onchain_ordini WHERE ordine_id=? "
                           "AND ordine_id>0", (int(ordine_id),)).fetchone()
    except sqlite3.OperationalError:
        return None


def _onchain_uscita_fatta(con, o, verso: str):
    """Il giudice delle due uscite per un ordine con cassaforte
    'onchain': None se l'ordine non e' on-chain (si va per il
    Lightning); altrimenti la riga on-chain se la transazione di quel
    verso e' gia' partita con le due firme, o False se no — e allora
    non si paga niente da nessuna parte: i sats escono solo dai due
    telefoni."""
    if (o["cassaforte"] or "") != CASSAFORTE_ONCHAIN:
        return None
    oc = _onchain_di_ordine(con, o["id"])
    fatto = "rilasciato" if verso == "venditore" else "rimborsato"
    return oc if oc and oc["stato"] == fatto else False


def _onchain_db_ordini():
    con = _onchain_db()
    _onchain_prepara_ordini(con)
    _payjoin_prepara(con)      # 16 nov 2026: le tabelle del PayJoin
    return con


def _onchain_compra_ammesso(tg_id):
    """Il cancello della cassa: per chi compra si guarda qui, per chi
    vende quando si sa chi e' (`_onchain_compra`). 400 e non 404: la
    cassa esiste per tutti, e' la via on-chain che non c'e'."""
    if not onchain_ammesso(tg_id):
        raise HTTPException(400, "Il pagamento on-chain non è disponibile")
    _onchain_serve_embit()


async def _onchain_compra(user, a, richiesti: int, prezzo: int,
                          dettagli: dict) -> dict:
    """La coda della cassa on-chain: tutti i conti e i no di `compra`
    sono gia' passati, `prezzo` e' il totale che col Lightning sarebbe
    stato la fattura. Qui nascono l'indirizzo e l'ordine."""
    venditore = a["venditore_id"]
    if not onchain_ammesso(venditore):
        raise HTTPException(400, "Questo venditore non riceve on-chain")
    try:
        onchain_xpub_barattolo()
    except ValueError as e:
        raise HTTPException(503, str(e))
    # l'unico await, PRIMA di ogni scrittura: da qui all'ultimo commit
    # il blocco e' atomico, come nella cassa del Lightning
    margine = onchain_margine(await onchain_mempool_tariffa())
    # il tetto della beta, sul prezzo (27 ott 2026): prima di ogni
    # scrittura, come il resto dei no
    cambio = await cambio_btc_eur()
    troppo = onchain_sopra_il_tetto(prezzo, cambio)
    if troppo:
        raise HTTPException(400, troppo)
    # L'ACQUISTO GROSSO ESCE ON-CHAIN ANCHE VERSO CHI VENDE (17 nov 2026,
    # cantiere onchain-grossi-uscita, Andrea: «se vuole ricevere in
    # lighting, sì, bisogna mettere anche verso di lui il limite»): sopra la
    # soglia il cambio in Lightning a fine ordine non regge, quindi
    # l'ordine nasce col segno `grosso` e riceve on-chain. Col cambio di
    # ADESSO, e fissato: lo stesso cambio che ha deciso il tetto
    grosso = 1 if onchain_consigliato(prezzo, cambio) else 0
    # la quota fissa di Barattolo (0 di serie): la paga chi compra, e
    # l'ha vista alla cassa (`/api/onchain/pronto`)
    quota = onchain_quota_sats()
    adesso = int(time.time())
    con = _onchain_db_ordini()
    try:
        r = con.execute("SELECT stato, quantita, titolo FROM annunci "
                        "WHERE id=?", (a["id"],)).fetchone()
        if (not r or r["stato"] != "attivo"
                or richiesti > r["quantita"] - _riservati(con, a["id"])):
            raise HTTPException(409, "Qualcun altro ti ha preceduto su "
                                     "questo annuncio: riprova tra poco")
        try:
            ind_id = onchain_nuovo_indirizzo(con, user["id"], venditore,
                                             adesso)
        except ValueError as e:
            raise HTTPException(400, str(e))
        ind = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                          (ind_id,)).fetchone()
        # DOVE RICEVE CHI VENDE: SOLO il wallet suo, scelto e firmato dal
        # suo seme (27 ott 2026, Andrea: «il venditore non deve mai
        # ricevere i fondi nel wallet autogenerato da barattolo»). MA SI
        # PAGA LO STESSO (stessa sera, Andrea: «un utente paga, perché
        # chi riceve deve prima aver settato il wallet? quello è solo
        # l'output finale, può definirlo in un secondo momento»): il
        # 2-di-3 nasce con le tre chiavi di sempre, e l'incasso resta
        # VUOTO finche' chi vende non sceglie. Vuoto vuol dire che verso
        # di lui non esce niente — nessuna proposta, nessuna firma di
        # Barattolo — e alla scelta `_onchain_riempi_incassi` lo scrive.
        # Il conto `/1/n` di serie non e' piu' una strada.
        dest = _onchain_destinazione_viva(con, venditore,
                                          ind["xpub_venditore"])
        # (28 ott 2026) chi vende in Lightning, o che sceglie ogni volta,
        # decide allo sblocco: l'incasso resta vuoto anche se ha un wallet
        # (9 nov 2026) il modo dell'ORDINE: la scelta dell'annuncio vince
        if onchain_modo_ordine(con, {"venditore_id": venditore,
                                     "annuncio_id": a["id"],
                                     "grosso": grosso}) != "onchain":
            dest = None
        if dest:
            d_tipo, d_valore, d_firma = dest["tipo"], dest["valore"], dest["firma"]
            d_indice = (_onchain_prossimo_esterno(con, venditore, d_valore)
                        if d_tipo == "xpub" else 0)
            incasso = onchain_indirizzo_esterno(d_tipo, d_valore, d_indice)
        else:
            d_tipo = d_valore = d_firma = incasso = ""
            d_indice = 0
        # IL RIMBORSO DI CHI COMPRA (10 nov 2026, rimborso-wallet): al suo
        # wallet, o vuoto finche' non lo sceglie — come l'incasso di chi
        # vende. Mai il `/1/n` del seme di Barattolo
        rimborso, r_tipo, r_valore, r_firma, r_indice = _onchain_rimborso_di(
            con, user["id"], ind["xpub_compratore"])
        # la quota va a Barattolo su `/1/n` della SUA xpub, col numero di
        # Barattolo di questo ordine: una fila che non si ripete mai
        quota_dove = (onchain_incasso(ind["xpub_barattolo"],
                                      ind["numero_barattolo"])
                      if quota else "")
        cur = con.execute(
            "INSERT INTO onchain_ordini(indirizzo_id, annuncio_id,"
            " compratore_id, venditore_id, quantita, titolo, prezzo_sats,"
            " margine_sats, importo_sats, incasso, rimborso, dettagli,"
            " scade, creato, aggiornato, incasso_tipo, incasso_valore,"
            " incasso_firma, incasso_indice, quota_sats, quota_indirizzo,"
            " rimborso_tipo, rimborso_valore, rimborso_firma, rimborso_indice,"
            " payjoin_gettone, grosso)"
            " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (ind_id, a["id"], user["id"], venditore, richiesti,
             r["titolo"] or "", prezzo, margine, prezzo + quota + margine,
             incasso, rimborso,
             json.dumps(dettagli, ensure_ascii=False),
             adesso + ONCHAIN_ORE_ATTESA * 3600, adesso, adesso,
             d_tipo, d_valore, d_firma, d_indice, quota, quota_dove,
             r_tipo, r_valore, r_firma, r_indice,
             # la porta del PayJoin (16 nov 2026): nasce sempre, anche a
             # leva spenta, cosi' riaccenderla vale per gli ordini aperti
             secrets.token_urlsafe(18), grosso))
        con.execute("UPDATE onchain_indirizzi SET ordine_id=? WHERE id=?",
                    (cur.lastrowid, ind_id))
        con.commit()
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (cur.lastrowid,)).fetchone()
        return {"onchain": _onchain_ordine_per(con, o, user["id"])}
    finally:
        con.close()


def _onchain_ordine_per(con, o, tg_id: int) -> dict:
    """Un ordine on-chain come lo vede UNA delle due parti. L'indirizzo
    passa da `onchain_riga_per` (niente xpub), e la proposta c'e' intera:
    chi deve co-firmare ha bisogno del PSBT, chi l'ha proposta di sapere
    che aspetta."""
    ind = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                      (o["indirizzo_id"],)).fetchone()
    da_compratore = int(o["compratore_id"]) == int(tg_id)
    altro = o["venditore_id"] if da_compratore else o["compratore_id"]
    proposta = None
    if o["proposta_psbt"]:
        proposta = {"verso": o["proposta_verso"], "psbt": o["proposta_psbt"],
                    "mia": int(o["proposta_da"]) == int(tg_id),
                    "il": o["proposta_il"],
                    # firmata da Barattolo dopo una decisione: 'disputa' o
                    # 'reso' ('' = la proposta di una delle due parti)
                    "barattolo": (o["decisione_perche"] or "disputa")
                                 if o["decisione_da"] else ""}
    return {
        "id": o["id"], "annuncio_id": o["annuncio_id"], "titolo": o["titolo"],
        "ruolo": "compratore" if da_compratore else "venditore",
        "stato": o["stato"], "quantita": o["quantita"],
        "prezzo_sats": o["prezzo_sats"], "margine_sats": o["margine_sats"],
        "importo_sats": o["importo_sats"],
        "visti_sats": o["visti_sats"], "ricevuti_sats": o["ricevuti_sats"],
        "utxo": json.loads(o["utxo"] or "[]"),
        "incasso": o["incasso"], "rimborso": o["rimborso"],
        # (10 nov 2026, rimborso-wallet) dove torna il rimborso di chi
        # mette i sats, con la firma del SUO seme: il suo telefono la
        # rilegge prima di firmare. None = vecchio /1/n o ancora vuoto
        "destinazione_rimborso": ({"tipo": o["rimborso_tipo"],
                                   "valore": o["rimborso_valore"],
                                   "firma": o["rimborso_firma"],
                                   "indice": o["rimborso_indice"]}
                                  if _p2p_onchain_campo(o, "rimborso_tipo", "") else None),
        # la destinazione scelta da chi vende, con la firma del suo seme:
        # il suo telefono la rilegge prima della seconda firma. Vuota =
        # il conto di Barattolo (`/1/n`), che il seme rifa' da se'
        "destinazione": ({"tipo": o["incasso_tipo"],
                          "valore": o["incasso_valore"],
                          "firma": o["incasso_firma"],
                          "indice": o["incasso_indice"]}
                         if o["incasso_tipo"] else None),
        "quota_sats": o["quota_sats"] or 0,
        "quota_indirizzo": o["quota_indirizzo"] or "",
        # le risposte alle domande del venditore NON escono da qui (6
        # nov 2026): si leggono solo da /api/orders/{id}/risposte
        "dettagli": {k: v for k, v in
                     json.loads(o["dettagli"] or "{}").items()
                     if k != "risposte"},
        "indirizzo": onchain_riga_per(ind, tg_id, _onchain_nome(con, altro)),
        "proposta": proposta, "txid_uscita": o["txid_uscita"],
        # l'ordine di sempre, dalla strada A (0 = un ordine di prima)
        "ordine_id": int(o["ordine_id"] or 0),
        # chi compra ha confermato, e aspetta la scelta di chi vende
        "rilascio_chiesto_il": int(o["rilascio_chiesto_il"] or 0),
        # (28 ott 2026) la conferma firmata dal seme di chi compra: il suo
        # telefono la rilegge prima di firmare da solo; e il cambio in
        # Lightning di chi vende (le sole parti pubbliche), e come riceve
        "rilascio_firma": o["rilascio_firma"] or "",
        "cambio": _onchain_cambio_letto(o),
        "modo_venditore": onchain_modo_ordine(con, o),
        # (17 nov 2026) chi vende avrebbe ricevuto in Lightning, ma la cifra
        # e' grossa e riceve on-chain: la pagina glielo dice
        "grosso_ln_tolto": _onchain_grosso(o) and _onchain_modo_scelto(con, o) != "onchain",
        "scade": o["scade"], "creato": o["creato"],
        "pagato_il": o["pagato_il"], "chiuso_il": o["chiuso_il"],
        "tariffa": _ONCHAIN_TARIFFA["sat_vb"] or 2.0,
        "esploratore": onchain_mempool_api().rsplit("/api", 1)[0],
        # (16 nov 2026, cantiere payjoin) la porta del PayJoin, solo a chi
        # paga e solo finche' serve: '' = il link di ieri, senza `pj=`
        "payjoin": _payjoin_link(con, o) if da_compratore else "",
    }


async def onchain_controlla(oid: int) -> str:
    """LA SORVEGLIANZA (tappa 4): chiede a mempool le monete
    dell'indirizzo di un ordine in attesa. Con una conferma e almeno
    l'importo → 'pagato' (lo stock scala, le due parti lo sanno). Scaduto
    senza aver visto niente → 'scaduto' e lo stock torna libero. Visto
    ma non ancora confermato, o arrivato meno del dovuto: si aspetta, e
    lo si dice. Torna lo stato. Le monete NON confermate non contano
    mai: in mempool una transazione si puo' ancora sostituire."""
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT o.*, i.indirizzo AS dove FROM onchain_ordini o"
                        " JOIN onchain_indirizzi i ON i.id=o.indirizzo_id"
                        " WHERE o.id=?", (int(oid),)).fetchone()
    finally:
        con.close()
    if not o or o["stato"] != "attesa":
        return o["stato"] if o else ""
    utxo = await onchain_mempool_utxo(o["dove"])
    buone = [{"txid": str(u["txid"]), "vout": int(u["vout"]),
              "value": int(u["value"])}
             for u in utxo if (u.get("status") or {}).get("confirmed")]
    visti = sum(int(u["value"]) for u in utxo)
    ricevuti = sum(u["value"] for u in buone)
    adesso = int(time.time())
    nuovo_ordine = 0
    in_arrivo = False
    tardi = 0
    con = _onchain_db_ordini()
    try:
        con.execute("UPDATE onchain_ordini SET visti_sats=?, ricevuti_sats=?,"
                    " utxo=?, aggiornato=? WHERE id=? AND stato='attesa'",
                    (visti, ricevuti, json.dumps(buone), adesso, o["id"]))
        stato = "attesa"
        # IL PAGAMENTO IN ARRIVO (9 nov 2026, Andrea nella prova da 5 €:
        # «servirebbe una notifica subito dove almeno si avvisa che
        # l'ordine e' stato preso»). L'ordine di sempre nasce solo alla
        # prima conferma, e fino ad allora chi vende non sapeva niente.
        # Visto tutto nel mempool e non ancora confermato: lo si dice
        # UNA volta (la colonna e' il lucchetto, la ronda e il tocco
        # «Controlla» possono passare insieme). Non e' un «venduto»:
        # in mempool un pagamento si puo' ancora sostituire.
        if visti >= o["importo_sats"] and ricevuti < o["importo_sats"]:
            in_arrivo = bool(con.execute(
                "UPDATE onchain_ordini SET visto_avvisato=1 WHERE id=? AND"
                " stato='attesa' AND COALESCE(visto_avvisato,0)=0",
                (o["id"],)).rowcount)
        if ricevuti >= o["importo_sats"]:
            cur = con.execute("UPDATE onchain_ordini SET stato='pagato',"
                              " pagato_il=? WHERE id=? AND stato='attesa'",
                              (adesso, o["id"]))
            if cur.rowcount:
                stato = "pagato"
                # (14 nov 2026, audit) pagato DOPO la scadenza del prezzo:
                # si accetta come prima (i sats sono gia' nel 2-di-3), ma i
                # moderatori lo sanno — il cambio e' quello dell'acquisto
                tardi = adesso - int(o["scade"] or 0)
                # LA STRADA A (27 ott 2026): nasce l'ordine di sempre, e
                # da qui lo stock, le offerte, il carrello e gli avvisi
                # li fa `_incassa_ordine`, come per il Lightning. Lo
                # stock scalato qui e i due avvisi «⛓️ Venduto on-chain»
                # di prima sono morti con lui: sarebbero stati doppi.
                nuovo_ordine = _onchain_nasce_ordine(con, o)
        elif not utxo and adesso > o["scade"]:
            cur = con.execute("UPDATE onchain_ordini SET stato='scaduto',"
                              " chiuso_il=? WHERE id=? AND stato='attesa'",
                              (adesso, o["id"]))
            stato = "scaduto" if cur.rowcount else stato
        con.commit()
    finally:
        con.close()
    if stato == "pagato" and tardi > 3600:
        await notifica_admin(
            f"⏰ <b>Ordine on-chain #{int(o['id'])}</b> pagato "
            f"{tardi // 3600} ore dopo la scadenza del prezzo: vale il cambio "
            "del momento dell'acquisto. Se l'annuncio era in euro e il "
            "bitcoin si è mosso, guardatelo.", argomento="moderazione")
    if in_arrivo:
        await notifica(o["venditore_id"],
            f"₿ <b>Pagamento in arrivo:</b> {html.escape(o['titolo'][:40])}. "
            "Il compratore ha pagato on-chain e ora la rete deve confermarlo "
            "(di solito fra dieci minuti e un'ora). L'oggetto è prenotato per "
            "lui. <b>Non spedire e non consegnare ancora</b>: ti avviso io "
            "alla conferma, con l'ordine.")
    if nuovo_ordine:
        # niente await fra il commit qui sopra e il CAS di
        # `_incassa_ordine`: la riga 'creato' non resta a meta'. Se
        # qualcosa la' dentro si rompe, la ronda la riprende
        # (`_onchain_riprendi_incassi`).
        await _incassa_ordine(nuovo_ordine)
        # venduto senza aver detto dove ricevere (27 ott 2026): i sats
        # sono al sicuro nel 2-di-3, e chi vende lo sa subito
        if not o["incasso"]:
            await notifica(o["venditore_id"],
                f"₿ <b>Hai venduto on-chain:</b> {html.escape(o['titolo'][:40])}. "
                "I sats sono al sicuro nel 2-di-3. Scegli dove riceverli "
                "(Profilo → «Incassi on-chain»: un tuo indirizzo o la chiave "
                "del conto del tuo wallet): senza, al momento del rilascio non "
                "possono uscire.")
    return stato


def _onchain_incasso_sats(o) -> int:
    """QUANTO ARRIVA ALL'INCASSO di un rilascio: il prezzo, meno la meta'
    della commissione di chi riceve sugli scambi P2P on-chain (16 nov 2026,
    cantiere p2p-onchain-commissione). Una riga del mercatino quella
    colonna non ce l'ha: il prezzo intero, come ieri. PURA."""
    return int(o["prezzo_sats"]) - int(
        _p2p_onchain_campo(o, "quota_ricevente_sats", 0) or 0)


def _onchain_psbt_giudica(o, verso: str, psbt_b64: str,
                          chiave_firmatario: str, decisa: bool = False) -> None:
    """Il server legge la proposta prima di passarla all'altro, e dice di
    no se non e' l'uscita che l'ordine permette. Non e' l'unica guardia —
    il telefono di chi co-firma rifa' gli stessi conti — ma e' quella che
    non lascia arrivare a nessuno un PSBT storto. ValueError col motivo.
    - spende ESATTAMENTE le monete dell'ordine;
    - verso il venditore: a lui il prezzo esatto, il resto solo al
      rimborso di chi compra; verso chi compra: tutto al suo rimborso;
    - nessuna uscita sotto la polvere, e la commissione di rete sta
      dentro il margine;
    - chi propone ha gia' firmato ogni ingresso.
    `decisa` (14 nov 2026, audit): e' l'uscita firmata da Barattolo per
    una disputa decisa da un moderatore. Verso il venditore non aspetta il
    wallet di chi compra (la regola scritta: «la disputa no»): senza
    rimborso la transazione e' senza resto, e il resto va in commissione."""
    from embit.psbt import PSBT
    try:
        p = PSBT.from_string(psbt_b64)
    except Exception:
        raise ValueError("la transazione proposta non si legge")
    monete = json.loads(o["utxo"] or "[]")
    if sorted((v.txid.hex(), v.vout) for v in p.tx.vin) != sorted(
            (m["txid"], m["vout"]) for m in monete):
        raise ValueError("non spende esattamente i sats dell'ordine")
    rete = _onchain_rete()
    uscite = [(u.script_pubkey.address(rete), u.value) for u in p.tx.vout]
    if verso == "venditore":
        # (10 nov 2026, Andrea: «il rilascio aspetta il suo wallet») il
        # resto del margine torna al wallet di chi ha messo i sats: finche'
        # non c'e', i sats restano nel 2-di-3
        if not o["rimborso"] and not decisa:
            raise ValueError("chi ha messo i sats non ha ancora scelto dove "
                             "ricevere il resto: il rilascio aspetta il suo "
                             "wallet")
        if [v for d, v in uscite if d == o["incasso"]] != [_onchain_incasso_sats(o)]:
            raise ValueError("al venditore deve andare esattamente il prezzo")
        permessi = (o["incasso"], o["rimborso"])
        # la quota di Barattolo, se l'ordine ne ha una: esatta, una volta
        quota = int(o["quota_sats"] or 0)
        if quota:
            if [v for d, v in uscite if d == o["quota_indirizzo"]] != [quota]:
                raise ValueError("a Barattolo deve andare esattamente la "
                                 "quota dell'ordine")
            permessi += (o["quota_indirizzo"],)
    else:
        if not o["rimborso"]:
            raise ValueError("chi ha messo i sats non ha ancora scelto dove "
                             "riceverli: il rimborso aspetta il suo wallet")
        permessi = (o["rimborso"],)
    # un rimborso vuoto non e' mai un indirizzo permesso (il resto di chi
    # non ha ancora un wallet suo non ha dove andare)
    permessi = tuple(d for d in permessi if d)
    if not uscite or any(d not in permessi for d, _ in uscite):
        raise ValueError("c'è un'uscita verso un indirizzo che l'ordine "
                         "non conosce")
    if any(v < ONCHAIN_POLVERE for _, v in uscite):
        # la rete non trasmette uscite sotto la polvere: meglio dirlo qui
        # che dopo la seconda firma
        raise ValueError("un'uscita è troppo piccola (polvere): lasciala "
                         "alla commissione")
    rete_sats = sum(m["value"] for m in monete) - sum(v for _, v in uscite)
    # la commissione di rete sta nel margine; col rimborso la quota torna
    # a chi ha comprato insieme al resto, e dal margine non si tocca.
    # (14 nov 2026, audit) PIU' I POCHI SATS VERSATI IN PIU': sotto la
    # polvere non possono tornare indietro (la rete non trasmette l'uscita),
    # e senza questo un deposito di qualche sats in piu' bloccava ogni
    # uscita verso il venditore, anche quella decisa da un moderatore
    tetto = int(o["margine_sats"]) + min(_onchain_sats_in_piu(o, monete),
                                         ONCHAIN_POLVERE - 1)
    if not 0 < rete_sats <= tetto:
        raise ValueError("la commissione di rete non sta nel margine")
    for i in p.inputs:
        if chiave_firmatario not in {k.sec().hex() for k in i.partial_sigs}:
            raise ValueError("manca la tua firma")


def _onchain_sats_in_piu(o, monete) -> int:
    """(14 nov 2026, audit) Quanti sats chi compra ha versato OLTRE la
    cifra chiesta (`importo_sats`); 0 se la riga non la porta."""
    try:
        chiesto = int(o["importo_sats"] or 0)
    except (IndexError, KeyError):
        return 0
    if chiesto <= 0:
        return 0
    return max(0, sum(int(m["value"]) for m in monete) - chiesto)


def _onchain_ordine_permette(con, o, verso: str) -> None:
    """Un ordine on-chain nato in `ordini` (strada A) segue le regole
    dell'ordine di sempre: i sats al venditore si liberano negli stati
    in cui chi compra puo' confermare (`conferma_ricezione`), il
    rimborso dopo «Annulla la vendita» ('refund'). Una disputa ferma
    tutt'e due: la decide un moderatore. Gli ordini on-chain di prima
    (senza `ordine_id`) restano con le regole di prima."""
    if not o["ordine_id"]:
        return
    r = con.execute("SELECT stato FROM ordini WHERE id=?",
                    (o["ordine_id"],)).fetchone()
    stato = r["stato"] if r else ""
    if verso == "venditore" and stato not in ("locked", "shipped",
                                              "delivered"):
        raise HTTPException(409, "Su questo ordine i sats adesso non si "
                                 "liberano (" + (stato or "?") + ")")
    if verso == "compratore" and stato != "refund":
        raise HTTPException(409, "Il rimborso on-chain parte da «Annulla "
                                 "la vendita», nell'ordine")


# ------------- LA DISPUTA ON-CHAIN: DECIDE UN MODERATORE, FIRMA BARATTOLO -------------
# (27 ott 2026, cantiere onchain-disputa, Andrea: «un admin deve poter
# decidere se rilasciare i sats verso il venditore o verso il
# compratore. Se scelgo il compratore, questo aprendo Barattolo potra'
# firmare a favore suo, idem il caso del venditore».)
# Il 2-di-3 vuole due firme: una la mette QUI la chiave di Barattolo
# (sul VPS, vedi «LA CHIAVE DI BARATTOLO STA SUL VPS»), l'altra il
# telefono di chi ha vinto, da solo quando apre l'app — la stessa
# seconda firma di sempre, col suo telefono che rifa' i conti
# (`onchainCofirma`) e firma solo se gli arriva quel che gli spetta.
# Il PSBT lo scrive il server: le uscite sono quelle che l'ordine
# conosce (il prezzo a chi vende col resto e la quota, o tutto a chi
# compra), la commissione dalla tariffa del momento dentro il margine,
# e prima di conservarlo passa dallo stesso giudice delle proposte.
# UNA FIRMA DATA NON SI RITIRA, ed e' la riga da non ammorbidire: chi
# ha vinto ha in mano un PSBT con la firma di Barattolo, e puo'
# finirlo e trasmetterlo anche senza di noi (con Sparrow). Quindi una
# decisione on-chain e' definitiva davvero, e una seconda di verso
# diverso si rifiuta — ridecidere vorrebbe dire due firme di Barattolo
# in giro, una per parte.
def _onchain_psbt_barattolo(con, oc, verso: str) -> str:
    """Il PSBT d'uscita di `oc` verso `verso`, firmato dalla chiave di
    Barattolo e gia' giudicato; base64. ValueError col motivo."""
    from embit import script
    from embit.ec import PublicKey
    from embit.psbt import PSBT
    from embit.transaction import (Transaction, TransactionInput,
                                   TransactionOutput)
    ind = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                      (oc["indirizzo_id"],)).fetchone()
    figlia = _onchain_privata_barattolo(ind["xpub_barattolo"]).derive(
        [0, int(ind["numero_barattolo"])])
    if figlia.key.get_public_key().sec().hex() != ind["chiave_barattolo"]:
        raise ValueError("la chiave di Barattolo non e' quella dell'indirizzo")
    pubs = sorted((PublicKey.parse(bytes.fromhex(ind["chiave_" + k]))
                   for k in ("compratore", "venditore", "barattolo")),
                  key=lambda k: k.sec())
    ws = script.multisig(2, pubs)
    monete = json.loads(oc["utxo"] or "[]")
    if not monete:
        raise ValueError("l'ordine non ha monete")
    tot = sum(int(m["value"]) for m in monete)
    tariffa = max(1.0, float(_ONCHAIN_TARIFFA["sat_vb"] or 2.0))

    def rete(uscite):
        # la misura di `onchainProponi`, e mai oltre il margine
        return min(int(oc["margine_sats"]),
                   math.ceil((11 + 105 * len(monete) + 31 * uscite) * tariffa))

    if verso == "venditore":
        if not oc["incasso"]:
            raise ValueError("chi vende non ha ancora scelto dove ricevere: "
                             "decidi di nuovo quando l'ha fatto")
        quota = int(oc["quota_sats"] or 0)
        uscite = [(oc["incasso"], _onchain_incasso_sats(oc))]
        if quota:
            uscite.append((oc["quota_indirizzo"], quota))
        resto = tot - _onchain_incasso_sats(oc) - quota - rete(3 if quota else 2)
        if resto >= ONCHAIN_POLVERE and oc["rimborso"]:
            uscite.append((oc["rimborso"], resto))
    else:
        if not oc["rimborso"]:
            raise ValueError("chi ha messo i sats non ha ancora scelto dove "
                             "riceverli: decidi di nuovo quando l'ha fatto")
        uscite = [(oc["rimborso"], tot - rete(1))]
    tx = Transaction(
        vin=[TransactionInput(bytes.fromhex(m["txid"]), int(m["vout"]))
             for m in monete],
        vout=[TransactionOutput(v, script.address_to_scriptpubkey(d))
              for d, v in uscite])
    p = PSBT(tx)
    for i, m in zip(p.inputs, monete):
        i.witness_utxo = TransactionOutput(int(m["value"]), script.p2wsh(ws))
        i.witness_script = ws
    if p.sign_with(figlia.key) < len(monete):
        raise ValueError("la chiave di Barattolo non firma queste monete")
    b64 = p.to_string()
    _onchain_psbt_giudica(oc, verso, b64, ind["chiave_barattolo"], decisa=True)
    return b64


async def _onchain_decide(ordine_id: int, verso: str, chi_id: int,
                          perche: str) -> dict:
    """Barattolo mette la sua firma sull'uscita `verso` ('venditore' o
    'compratore') dell'ordine di sempre `ordine_id`, e la lascia come
    proposta: la seconda e' del telefono di chi vince. Torna la risposta
    per il moderatore (o per chi vende, dal reso). Rifirmare lo stesso
    verso non fa niente; un verso diverso e' un 409 (la firma non si
    ritira)."""
    _onchain_serve_embit()
    con = _onchain_db_ordini()
    try:
        oc = _onchain_di_ordine(con, ordine_id)
        if not oc or oc["stato"] != "pagato":
            raise HTTPException(409, "Nella cassaforte on-chain di questo "
                                     "ordine non ci sono sats da muovere")
        if oc["decisione_da"]:
            if oc["proposta_verso"] == verso:
                return {"ok": True, "stato": "dispute", "onchain": True,
                        "attesa_firma": verso, "gia_firmata": True}
            raise HTTPException(409, "Barattolo ha già firmato questa "
                                     "decisione a favore " + (
                                         "del venditore" if oc["proposta_verso"] == "venditore"
                                         else "di chi ha comprato")
                                     + ": una firma data non si ritira")
        try:
            psbt = _onchain_psbt_barattolo(con, oc, verso)
        except ValueError as e:
            raise HTTPException(409, f"Barattolo non può firmare: {e}")
        adesso = int(time.time())
        cur = con.execute("UPDATE onchain_ordini SET proposta_verso=?,"
                          " proposta_psbt=?, proposta_da=0, proposta_il=?,"
                          " decisione_da=?, decisione_il=?, decisione_perche=?,"
                          " aggiornato=? WHERE id=? AND decisione_da=0",
                          (verso, psbt, adesso, int(chi_id), adesso, perche,
                           adesso, oc["id"]))
        con.commit()
        if not cur.rowcount:
            # due moderatori nello stesso istante: vince il primo, e la
            # firma del secondo non esce da qui
            raise HTTPException(409, "Un altro moderatore ha appena deciso: "
                                     "riapri l'ordine")
        r = con.execute("SELECT stato FROM ordini WHERE id=?",
                        (ordine_id,)).fetchone()
        stato = r["stato"] if r else "dispute"
        tit = html.escape(oc["titolo"][:40])
        vince = oc["venditore_id"] if verso == "venditore" else oc["compratore_id"]
        perde = oc["compratore_id"] if verso == "venditore" else oc["venditore_id"]
    finally:
        con.close()
    if perche == "reso":
        await notifica(vince, f"↩️ <b>Reso ricevuto:</b> {tit}. Barattolo ha "
                              "firmato il tuo rimborso on-chain: apri la Mini "
                              "App e il tuo telefono mette la seconda firma.")
    else:
        await notifica(vince, f"⚖️ <b>Disputa decisa a tuo favore:</b> {tit}. "
                              "Barattolo ha firmato: apri la Mini App e il tuo "
                              "telefono mette la seconda firma, poi i sats "
                              "partono.")
        await notifica(perde, f"⚖️ <b>Disputa decisa:</b> {tit}. Il moderatore "
                              "ha dato ragione all'altra parte, e Barattolo ha "
                              "firmato. Se pensi che ci sia un errore, scrivi "
                              "ai moderatori.")
    # la trasparenza di Andrea: ogni firma di Barattolo si dice agli admin,
    # con chi l'ha decisa
    await notifica_admin(argomento="dispute", testo=
        f"₿ <b>Barattolo ha firmato</b> l'ordine on-chain #{ordine_id} "
        f"({tit}) a favore " + ("del venditore" if verso == "venditore"
                                else "di chi ha comprato")
        + (f", dal reso ricevuto da {int(chi_id)}" if perche == "reso"
           else f", deciso dal moderatore {int(chi_id)}") + ".")
    return {"ok": True, "stato": stato, "onchain": True, "attesa_firma": verso}


def _onchain_parte(o, tg_id) -> str:
    if int(o["compratore_id"]) == int(tg_id):
        return "compratore"
    if int(o["venditore_id"]) == int(tg_id):
        return "venditore"
    # 404 e non 403, come altrove: chi non c'entra non sa nemmeno che c'e'
    raise HTTPException(404, "Ordine non trovato")


@app.get("/api/onchain/ordini")
async def onchain_ordini(x_tg_init_data: str = Header(""),
                         barattolo_sessione: str = Cookie("")):
    """I miei ordini on-chain, da compratore e da venditore, gli ultimi
    trenta. Si legge senza embit: i conti sono nelle righe."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    con = _onchain_db_ordini()
    try:
        righe = con.execute(
            "SELECT * FROM onchain_ordini WHERE compratore_id=? OR "
            "venditore_id=? ORDER BY id DESC LIMIT 30",
            (user["id"], user["id"])).fetchall()
        return {"ordini": [_onchain_ordine_per(con, o, user["id"])
                           for o in righe]}
    finally:
        con.close()


@app.get("/api/onchain/pronto/{venditore_id}")
async def onchain_pronto(venditore_id: int, sats: int = 0,
                         x_tg_init_data: str = Header(""),
                         barattolo_sessione: str = Cookie("")):
    """La cassa chiede se a QUESTO venditore si puo' pagare on-chain,
    prima di mostrare la scelta: si o no, e il perche' a parole. Non
    dice la xpub di nessuno, solo se c'e'."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    # L'ON-CHAIN CONSIGLIATO PER GLI ACQUISTI GROSSI (17 nov 2026): detto in
    # OGNI risposta, anche nei no, perche' a on-chain impossibile la cassa
    # avvisi almeno che una cifra cosi' in Lightning spesso non passa
    # col cambio che si sa ADESSO, senza la rete: la domanda a CoinGecko
    # resta dov'era, solo per il tetto (17 nov 2026 sera, la gabbia)
    sopra = {"consigliato": sats > 0 and onchain_consigliato(int(sats), cambio_noto_ora()),
             "consigliato_sopra_euro": _onchain_soglia_consiglio()}
    if not EMBIT:
        return {**sopra, "pronto": False, "motivo": "manca la libreria embit"}
    # (30 ott 2026, cantiere onchain-mainnet) la terza chiave che manca o
    # non e' di questa rete spegne la porta ⛓️ PRIMA del tocco, con le
    # parole del giudice: su mainnet senza la chiave di Barattolo non
    # nasce nessun indirizzo
    try:
        onchain_xpub_barattolo()
    except ValueError as e:
        return {**sopra, "pronto": False, "motivo": str(e)}
    if not onchain_ammesso(venditore_id):
        return {**sopra, "pronto": False, "motivo": "questo venditore non riceve on-chain"}
    con = _onchain_db()
    try:
        x = {r["tg_id"] for r in con.execute(
            "SELECT tg_id FROM onchain_xpub WHERE tg_id IN (?,?)",
            (user["id"], int(venditore_id)))}
    finally:
        con.close()
    if int(venditore_id) not in x:
        # si accende da solo all'apertura dell'app (27 ott 2026): chi
        # non ce l'ha e' chi non l'ha ancora aperta da allora
        return {**sopra, "pronto": False,
                "motivo": "il venditore non ha ancora aperto Barattolo da "
                          "quando l'on-chain c'e': si accende da solo appena "
                          "lo apre"}
    # (chi vende senza un wallet suo si paga lo stesso, 27 ott 2026: la
    # scelta serve solo all'uscita, e la fa dopo)
    # e il tetto della beta, se la cassa dice la cifra (`sats`, il totale
    # che col Lightning sarebbe la fattura): la porta ⛓️ si spegne PRIMA
    # del tocco, invece di chiudere la fattura e poi dire di no
    if sats > 0:
        troppo = onchain_sopra_il_tetto(int(sats), await cambio_btc_eur())
        if troppo:
            return {**sopra, "pronto": False, "motivo": troppo}
    # la quota fissa di Barattolo, detta PRIMA di pagare (regola ferrea
    # 10): la cassa la scrive accanto al margine per la rete
    return {**sopra, "pronto": True, "motivo": "", "io_acceso": user["id"] in x,
            "quota_sats": onchain_quota_sats()}


@app.post("/api/onchain/ordini/{oid}/controlla")
async def onchain_ordine_controlla(oid: int, x_tg_init_data: str = Header(""),
                                   barattolo_sessione: str = Cookie("")):
    """«Ho pagato, guarda adesso»: la stessa domanda della ronda, subito.
    La rete muta non e' un errore dell'ordine: 503 e si riprova."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_controlla", user["id"])
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (oid,)).fetchone()
        if not o:
            raise HTTPException(404, "Ordine non trovato")
        _onchain_parte(o, user["id"])
    finally:
        con.close()
    try:
        await onchain_controlla(oid)
    except Exception:
        raise HTTPException(503, "mempool non risponde: riprova fra poco")
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (oid,)).fetchone()
        return _onchain_ordine_per(con, o, user["id"])
    finally:
        con.close()


@app.post("/api/onchain/ordini/{oid}/annulla")
async def onchain_ordine_annulla(oid: int, x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """Chi compra ci ripensa PRIMA di pagare: l'ordine si chiude e lo
    stock torna libero. Se mempool ha gia' visto anche un sats, no: quei
    sats sono nel 2-di-3 e ne escono solo con un rimborso."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (oid,)).fetchone()
        if not o:
            raise HTTPException(404, "Ordine non trovato")
        if _onchain_parte(o, user["id"]) != "compratore":
            raise HTTPException(403, "Lo annulla chi compra")
    finally:
        con.close()
    # PRIMA SI GUARDA LA RETE (27 ott 2026, la cassa che passa da ⛓️ a
    # ⚡): `visti_sats` lo scrive la ronda ogni due minuti, e chi ha
    # appena mandato i sats e poi tocca ⚡ non deve trovarsi l'ordine
    # chiuso coi sats in viaggio. Rete muta = non si annulla alla cieca.
    if o["stato"] == "attesa":
        try:
            await onchain_controlla(oid)
        except Exception:
            raise HTTPException(503, "mempool non risponde: non annullo alla "
                                     "cieca, riprova fra poco")
    con = _onchain_db_ordini()
    try:
        cur = con.execute(
            "UPDATE onchain_ordini SET stato='annullato', chiuso_il=?,"
            " aggiornato=? WHERE id=? AND stato='attesa' AND visti_sats=0",
            (int(time.time()), int(time.time()), oid))
        con.commit()
        if not cur.rowcount:
            ora = con.execute("SELECT stato FROM onchain_ordini WHERE id=?",
                              (oid,)).fetchone()
            if ora and ora["stato"] in ("annullato", "scaduto"):
                return {"ok": True}
            if ora and ora["stato"] == "pagato":
                raise HTTPException(409, "Il pagamento on-chain è arrivato: "
                                         "l'ordine è andato avanti, lo trovi "
                                         "nei tuoi Ordini")
            raise HTTPException(409, "Ci sono già dei sats su questo "
                                     "indirizzo: ora si esce solo con un "
                                     "rimborso")
        return {"ok": True}
    finally:
        con.close()


@app.post("/api/onchain/ordini/{oid}/rilascio-chiesto")
async def onchain_rilascio_chiesto(oid: int, req: Request,
                                   x_tg_init_data: str = Header(""),
                                   barattolo_sessione: str = Cookie("")):
    """«HO RICEVUTO» PRIMA CHE CHI VENDE ABBIA SCELTO DOVE RICEVERE (27 ott
    2026). La firma di chi compra deve dire a CHI vanno i sats, e l'uscita
    non c'e' ancora: si scrive la sua conferma, si avvisa chi vende, e il
    telefono di chi compra firma da solo alla prima apertura dopo la
    scelta (`onchainCofirmeInAttesa`). Nessuna firma di Barattolo: la
    regola delle due firme resta delle due parti.
    LA CONFERMA SI FIRMA (28 ott 2026, cantiere onchain-verso-lightning):
    `firma` e' la chiave `/2/0` del seme di chi compra sul testo
    `onchain_messaggio_ricevuto`. Il server la controlla con la sua xpub
    dedicata, e il SUO telefono la rilegge prima di firmare da solo: cosi'
    una riga scritta da un server manomesso non libera niente. E con
    chi vende in Lightning e' anche il permesso alla PRIMA firma di chi
    vende (il cambio nasce adesso, e la fattura scade)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _onchain_serve_embit()
    d = await leggi_json(req)
    firma = str(d.get("firma") or "").strip().lower()
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (oid,)).fetchone()
        if not o:
            raise HTTPException(404, "Ordine non trovato")
        if _onchain_parte(o, user["id"]) != "compratore":
            raise HTTPException(403, "Lo conferma chi compra")
        # (10 nov 2026, Andrea: «il rilascio aspetta il suo wallet») si
        # aspetta anche quando manca il wallet di chi compra, dove torna
        # il resto del margine
        if (o["stato"] != "pagato" or (o["incasso"] and o["rimborso"])
                or o["proposta_psbt"]):
            raise HTTPException(409, "Su questo ordine non c'è niente da "
                                     "mettere in attesa")
        _onchain_ordine_permette(con, o, "venditore")
        ind = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                          (o["indirizzo_id"],)).fetchone()
        if not onchain_firma_valida_testo(
                ind["xpub_compratore"],
                onchain_messaggio_ricevuto(o["id"], ind["indirizzo"]), firma):
            raise HTTPException(400, "La conferma non è firmata dal tuo seme: "
                                     "rifalla da questo telefono")
        gia = bool(o["rilascio_chiesto_il"])
        # una conferma di prima, senza firma, si puo' ridare: stavolta firmata
        con.execute("UPDATE onchain_ordini SET rilascio_chiesto_il=CASE WHEN"
                    " rilascio_chiesto_il=0 THEN ? ELSE rilascio_chiesto_il"
                    " END, rilascio_firma=?, aggiornato=? WHERE id=? AND"
                    " (rilascio_chiesto_il=0 OR rilascio_firma='')",
                    (int(time.time()), firma, int(time.time()), oid))
        con.commit()
        modo = onchain_modo_ordine(con, o)
    finally:
        con.close()
    if not gia and not o["incasso"]:
        tit = html.escape(o['titolo'][:40])
        await notifica(o["venditore_id"],
            f"₿ <b>{tit}:</b> chi ha comprato ha confermato di averlo "
            "ricevuto. Scegli dove ricevere i sats (Profilo → «Incassi "
            "on-chain») e partono." + (
                " Per una cifra così ricevi on-chain, anche se avevi scelto "
                "Lightning." if _onchain_grosso(o) else "")
            if modo == "onchain" else
            f"⚡ <b>{tit}:</b> chi ha comprato ha confermato di averlo "
            "ricevuto. Apri l'ordine: ti mostriamo quanto costa lo swap "
            "in Lightning e, se confermi, i sats partono."
            + (" Puoi anche riceverli on-chain." if modo == "ogni_volta" else ""))
    return {"ok": True, "aspetta_wallet": not o["rimborso"],
            "aspetta_incasso": not o["incasso"]}


@app.post("/api/onchain/ordini/{oid}/proposta")
async def onchain_ordine_proposta(oid: int, req: Request,
                                  x_tg_init_data: str = Header(""),
                                  barattolo_sessione: str = Cookie("")):
    """LA PRIMA FIRMA (tappa 5): un PSBT gia' firmato da chi propone.
    `verso: venditore` lo manda chi compra («Libera i sats»), `verso:
    compratore` lo manda chi vende (il rimborso). Il server lo giudica
    (`_onchain_psbt_giudica`), lo conserva, e avvisa l'altro: sara' il
    suo telefono a co-firmare. Una proposta nuova prende il posto della
    vecchia — nessuno dei due spende da solo, quindi l'ultima parola e'
    sempre di chi co-firma."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_firma", user["id"])
    _onchain_serve_embit()
    d = await leggi_json(req)
    verso = str(d.get("verso") or "")
    psbt_b64 = str(d.get("psbt") or "").strip()
    if verso not in ("venditore", "compratore") or not psbt_b64:
        raise HTTPException(400, "Proposta incompleta")
    if len(psbt_b64) > 20000:
        raise HTTPException(400, "Proposta troppo grande")
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (oid,)).fetchone()
        if not o:
            raise HTTPException(404, "Ordine non trovato")
        parte = _onchain_parte(o, user["id"])
        ind = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                          (o["indirizzo_id"],)).fetchone()
        # (28 ott 2026) LA PRIMA FIRMA DI CHI VENDE: solo dopo la conferma
        # FIRMATA di chi compra, e solo per chi sceglie allo sblocco (la
        # sua strada on-chain dell'«ogni volta»; il cambio in Lightning ha
        # la sua porta, `onchain_cambio_nasce`)
        prima_di_chi_vende = (verso == "venditore" and parte == "venditore"
                              and o["incasso_tipo"] != "cambio"
                              and _onchain_puo_firmare_prima(con, o, ind))
        if verso == "venditore" and parte != "compratore" \
                and not prima_di_chi_vende:
            raise HTTPException(403, "I sats al venditore li libera chi compra")
        if verso == "compratore" and parte != "venditore":
            raise HTTPException(403, "Il rimborso lo propone chi vende")
        if o["stato"] != "pagato" and not (
                verso == "compratore" and o["stato"] == "attesa"
                and o["ricevuti_sats"] > 0 and time.time() > o["scade"]):
            raise HTTPException(409, "Su questo ordine non c'è niente da "
                                     "liberare adesso")
        _onchain_ordine_permette(con, o, verso)
        if verso == "venditore" and not o["incasso"]:
            raise HTTPException(409, ONCHAIN_MSG_SENZA_DESTINAZIONE)
        if verso == "venditore" and o["incasso_tipo"] == "cambio":
            # il cambio in Lightning ha gia' la prima firma, quella di chi
            # vende: un'altra proposta verso di lui non lo sostituisce
            raise HTTPException(409, "Chi vende ha già firmato lo swap in "
                                     "Lightning: manca solo la seconda firma")
        if o["decisione_da"]:
            # la proposta di Barattolo non si sostituisce: e' la decisione
            raise HTTPException(409, "Su questo ordine ha già firmato "
                                     "Barattolo: manca solo la seconda firma")
        try:
            _onchain_psbt_giudica(o, verso, psbt_b64,
                                  ind["chiave_" + parte])
        except ValueError as e:
            raise HTTPException(400, f"Proposta rifiutata: {e}")
        adesso = int(time.time())
        con.execute("UPDATE onchain_ordini SET proposta_verso=?,"
                    " proposta_psbt=?, proposta_da=?, proposta_il=?,"
                    " aggiornato=? WHERE id=?",
                    (verso, psbt_b64, user["id"], adesso, adesso, oid))
        con.commit()
        altro = o["venditore_id"] if parte == "compratore" else o["compratore_id"]
        tit = html.escape(o["titolo"][:40])
    finally:
        con.close()
    await notifica(altro, (
        f"₿ <b>{tit}:</b> chi vende ha scelto dove ricevere. Apri la Mini "
        "App: il tuo telefono firma il rilascio che avevi confermato, e i "
        "sats partono."
        if prima_di_chi_vende else
        f"₿ <b>Sats liberati:</b> {tit}. Apri la Mini App: il tuo "
        "telefono mette la seconda firma e i sats partono."
        if verso == "venditore" else
        f"₿ <b>Rimborso proposto:</b> {tit}. Apri la Mini App: il tuo "
        "telefono mette la seconda firma e i sats tornano a te."))
    return {"ok": True}


@app.post("/api/onchain/ordini/{oid}/firma")
async def onchain_ordine_firma(oid: int, req: Request,
                               x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """LA SECONDA FIRMA: l'altra parte manda la transazione COMPLETA
    (hex), firmata e finalizzata nel suo telefono. Il server controlla
    che sia proprio quella proposta — stesso txid, che in segwit non
    dipende dalle firme — e la trasmette. Mai chi ha proposto: le due
    firme devono essere di due persone."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_firma", user["id"])
    _onchain_serve_embit()
    from embit.psbt import PSBT
    from embit.transaction import Transaction
    d = await leggi_json(req)
    tx_hex = str(d.get("tx") or "").strip()
    if not tx_hex or len(tx_hex) > 40000:
        raise HTTPException(400, "Manca la transazione")
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (oid,)).fetchone()
        if not o:
            raise HTTPException(404, "Ordine non trovato")
        _onchain_parte(o, user["id"])
        if not o["proposta_psbt"] or o["stato"] not in ("pagato", "attesa"):
            raise HTTPException(409, "Non c'è niente da co-firmare")
        if int(o["proposta_da"]) == int(user["id"]):
            raise HTTPException(409, "La seconda firma è dell'altra parte")
        # l'ordine di sempre puo' essere cambiato fra le due firme (una
        # disputa aperta dopo «Libera i sats»): si ricontrolla qui. Sulla
        # proposta di Barattolo, invece, la disputa e' il posto giusto:
        # e' lei che l'ha decisa
        if o["decisione_da"]:
            r = con.execute("SELECT stato FROM ordini WHERE id=?",
                            (o["ordine_id"],)).fetchone()
            if not r or r["stato"] not in ("dispute", "return_pending",
                                           "return_shipped"):
                raise HTTPException(409, "Non c'è niente da co-firmare")
        else:
            _onchain_ordine_permette(con, o, o["proposta_verso"])
        try:
            atteso = PSBT.from_string(o["proposta_psbt"]).tx.txid().hex()
            arrivato = Transaction.from_string(tx_hex).txid().hex()
        except Exception:
            raise HTTPException(400, "La transazione non si legge")
        if atteso != arrivato:
            raise HTTPException(400, "Non è la transazione proposta")
        verso = o["proposta_verso"]
    finally:
        con.close()
    if verso == "venditore" and o["incasso_tipo"] == "cambio":
        # (28 ott 2026) IL CAMBIO E' ANCORA VIVO? Prima di mandare i bitcoin
        # al fornitore: lo swap aspetta ancora i bitcoin e la fattura di
        # chi vende ha davanti il tempo di una conferma. Sennò non parte
        # niente, il cambio si toglie e chi vende lo rifa'. Il fornitore
        # muto non e' un si': non si manda alla cieca.
        perche = await onchain_cambio_perche_morto(o)
        if perche is None:
            raise HTTPException(503, "SATS Routing ora non risponde: riprova "
                                     "fra poco, non è partito niente")
        if perche:
            await _onchain_cambio_togli(o, perche)
            raise HTTPException(409, "Lo swap di chi vende è scaduto prima "
                                     "che partissero i sats: gli abbiamo "
                                     "chiesto di rifarlo. Non è partito niente")
    try:
        txid = await onchain_mempool_invia(tx_hex)
    except ValueError as e:
        raise HTTPException(400, f"La rete l'ha rifiutata: {e}")
    except Exception:
        raise HTTPException(503, "mempool non risponde: riprova fra poco")
    stato = "rilasciato" if verso == "venditore" else "rimborsato"
    adesso = int(time.time())
    con = _onchain_db_ordini()
    try:
        con.execute("UPDATE onchain_ordini SET stato=?, txid_uscita=?,"
                    " chiuso_il=?, aggiornato=? WHERE id=?",
                    (stato, txid or arrivato, adesso, adesso, oid))
        con.commit()
    finally:
        con.close()
    if o["ordine_id"]:
        # LA STRADA A: l'ordine di sempre si chiude per la porta di
        # sempre, che adesso trova la transazione partita e fa conti,
        # XP e avvisi come per un Lightning riuscito
        if verso == "venditore":
            await _sblocca_sats(int(o["ordine_id"]))
        else:
            await _rimborsa_compratore(int(o["ordine_id"]))
        return {"ok": True, "stato": stato, "txid": txid or arrivato,
                "ordine_id": int(o["ordine_id"])}
    tit = html.escape(o["titolo"][:40])
    testo = (f"₿ <b>Sats partiti:</b> {tit} — "
             + ("al venditore." if verso == "venditore" else "rimborso a chi ha comprato.")
             + f" Transazione {(txid or arrivato)[:12]}…")
    for chi in (o["compratore_id"], o["venditore_id"]):
        await notifica(chi, testo)
    return {"ok": True, "stato": stato, "txid": txid or arrivato}


# ============ CHI VENDE ON-CHAIN RICEVE IN LIGHTNING (28 ott 2026,
# cantiere onchain-verso-lightning; la via di Alan: «quando il compratore
# paga on chain, se il venditore li vuole LN, internamente dobbiamo
# direzionare l'invio verso satsrouting, il venditore deve impostare
# solamente una invoice LN»; piano in dieci righe approvato da Andrea)
# ============
# Il 2-di-3 non cambia: chi compra paga lo stesso indirizzo, e allo
# sblocco il prezzo esce verso UN'ALTRA uscita, l'indirizzo del cambio
# bitcoin → Lightning («submarine») di SATS Routing. Il cambio lo crea il
# TELEFONO DI CHI VENDE, con la SUA fattura e la SUA chiave di rimborso
# (le 12 parole di riserva della pagina «Cambio», tappa 3): il fornitore
# paga la fattura quando vede i bitcoin, e se non la paga i bitcoin
# tornano a chi vende dal suo telefono. Il server non vede mai chiavi.
# L'ORDINE DEI GESTI, ed e' la riga che conta: la fattura scade, quindi
# il cambio nasce il piu' tardi possibile — DOPO la conferma di chi
# compra, che e' FIRMATA dal suo seme (`onchain_messaggio_ricevuto`).
# Chi vende crea il cambio, lo firma come destinazione col seme e mette
# la PRIMA firma; il telefono di chi compra mette la seconda alla prima
# apertura, dopo aver riletto la sua conferma. Prima di trasmettere il
# server chiede al fornitore se il cambio e' ancora vivo: sennò non parte
# niente e chi vende lo rifa'.
# LE TRE SCELTE di chi vende (Profilo → «Incassi on-chain»): «onchain»
# (di serie, il mondo di ieri), «lightning» (la fattura dal suo
# Lightning address), «ogni_volta» (allo sblocco sceglie lui, e la
# fattura la incolla). La parola «swap» all'utente non si dice: e' «il
# cambio, fatto da SATS Routing», col costo scritto prima.
ONCHAIN_MODI = ("onchain", "lightning", "ogni_volta")
# La rete del fornitore che va bene per ogni rete dell'on-chain: signet
# ha le forme di testnet (tb1…, lntb…), e la mainnet vuole bitcoin.
# testnet4 (3 nov 2026) va con un fornitore di testnet4, che oggi non c'e'
# (la "testnet" dei fornitori e' la testnet3): il cambio resta fermo.
ONCHAIN_RETE_DEL_CAMBIO = {"signet": "testnet", "testnet": "testnet",
                           "testnet4": "testnet4",
                           "mainnet": "bitcoin", "bitcoin": "bitcoin"}
# Quanto deve restare alla fattura di chi vende quando i bitcoin partono:
# il fornitore paga dopo una conferma, e una conferma puo' metterci ore.
ONCHAIN_CAMBIO_VITA_MIN_S = 2 * 3600
# ...e quanto le si chiede alla nascita: la incollata deve durare un
# giorno (chi compra puo' aprire l'app domani, come nel P2P), quella del
# Lightning address almeno tre ore.
ONCHAIN_CAMBIO_VITA_INCOLLATA_S = 23 * 3600
ONCHAIN_CAMBIO_VITA_ADDRESS_S = 3 * 3600


def onchain_ln_rete_ok(fornitore: dict | None = None) -> bool:
    """La rete dell'on-chain e quella del fornitore sono la stessa? Oggi
    no (signet e bitcoin), e la strada resta ferma anche a leva accesa:
    dei bitcoin di prova non si cambiano in Lightning vero."""
    f = fornitore or swap_fornitori()[0]
    return ONCHAIN_RETE_DEL_CAMBIO.get(ONCHAIN_RETE) == f.get("rete")


def onchain_ln_per(tg_id) -> bool:
    """IL CAMBIO IN LIGHTNING C'E' PER CHI VENDE? La leva, sopra il
    cancello dell'on-chain e quello dello swap (il telefono che fa il
    cambio), la strada bitcoin → Lightning accesa, e le reti giuste."""
    return bool(ONCHAIN_INCASSO_LN_ATTIVO and onchain_ammesso(tg_id)
                and swap_per(tg_id) and "btc-ln" in cambio_strade()
                and onchain_ln_rete_ok())


def _onchain_modo_salvato(con, tg_id: int) -> str:
    r = con.execute("SELECT modo FROM onchain_modo WHERE tg_id=?",
                    (int(tg_id),)).fetchone()
    return r["modo"] if r and r["modo"] in ONCHAIN_MODI else "onchain"


def onchain_modo_vivo(con, tg_id: int) -> str:
    """Come riceve ADESSO chi vende: la sua scelta, ma solo se il cambio
    c'e' per lui; a leva spenta tutti tornano «onchain», come ieri."""
    if not onchain_ln_per(tg_id):
        return "onchain"
    return _onchain_modo_salvato(con, tg_id)


def onchain_modo_ordine(con, o) -> str:
    """UN ORDINE PAGATO ON-CHAIN, COME RICEVE CHI VENDE (9 nov 2026,
    cantiere incasso-annuncio): la scelta dell'annuncio vince sul
    Profilo — 'ln' diventa «lightning», 'onchain' resta — ma solo se il
    cambio c'e' per lui; a leva spenta «onchain», come ieri. `o` ha
    `venditore_id` e `annuncio_id`."""
    if _onchain_grosso(o):
        return "onchain"
    return _onchain_modo_scelto(con, o)


def _onchain_grosso(o) -> bool:
    """L'ordine e' nato sopra la soglia degli acquisti grossi (17 nov
    2026)? `o` puo' essere la riga o il dizionario della cassa; senza la
    chiave (un banco di prima) no."""
    try:
        return bool(int(o["grosso"] or 0))
    except (KeyError, IndexError, TypeError, ValueError):
        return False


def _onchain_modo_scelto(con, o) -> str:
    """Come VORREBBE ricevere chi vende, senza il segno dell'acquisto
    grosso: la scelta dell'annuncio, sennò quella del Profilo, e solo se
    il cambio c'e' per lui."""
    if not onchain_ln_per(o["venditore_id"]):
        return "onchain"
    a = incasso_annuncio(con, o["annuncio_id"])
    if a:
        return "lightning" if a == "ln" else "onchain"
    return _onchain_modo_salvato(con, o["venditore_id"])


def onchain_ln_busta(tg_id: int) -> dict:
    """La busta di `/api/me`: il cancello, il modo scelto, il minimo."""
    attivo = onchain_ln_per(tg_id)
    modo = "onchain"
    if attivo:
        con = _onchain_db()
        try:
            modo = _onchain_modo_salvato(con, tg_id)
        finally:
            con.close()
    return {"attivo": attivo, "modo": modo,
            "minimo": int(SWAP_MIN_SATS or 0), "fornitore": "SATS Routing"}


def _onchain_cambio_letto(o) -> dict | None:
    """Il cambio di un ordine (le sole parti pubbliche), o None."""
    try:
        c = json.loads(o["cambio"] or "{}")
    except (ValueError, TypeError, IndexError, KeyError):
        return None
    if not isinstance(c, dict) or not c.get("id"):
        return None
    return {k: c.get(k) for k in ("fornitore", "id", "lockup", "ricevi",
                                  "mandi", "scade_fattura", "timeout", "il")}


def preventivo_sub_da_mandare(mandi: int, tariffa: dict, minimo=0,
                              massimo=0) -> dict:
    """IL CONTO ROVESCIATO DI `preventivo_sub`, puro: chi vende ha `mandi`
    sats nel 2-di-3 (il prezzo dell'ordine), e riceve in Lightning il
    massimo `ricevi` per cui il fornitore chiede di mandare non piu' di
    `mandi`. L'avanzo dell'arrotondamento (0 o 1 sat) resta nella stessa
    uscita, che porta sempre il prezzo esatto (il giudice delle proposte
    non cambia). Sotto il minimo o sopra il tetto: ok False col motivo."""
    mandi = int(mandi)
    millesimi = round(float(tariffa["percento"]) * 1000)
    rete = int(tariffa["rete"])

    def costo(r):
        return r + -(-r * millesimi // 100_000) + rete
    ricevi = max(0, (mandi - rete) * 100_000 // (100_000 + millesimi))
    while ricevi > 0 and costo(ricevi) > mandi:
        ricevi -= 1
    while costo(ricevi + 1) <= mandi:
        ricevi += 1
    p = preventivo_sub(ricevi, tariffa, minimo, massimo)
    p["prezzo"] = mandi
    if p.get("ok"):
        p["avanzo"] = mandi - p["mandi"]
        p["costo"] = mandi - ricevi
    return p


def _onchain_puo_firmare_prima(con, o, ind) -> bool:
    """CHI VENDE PUO' METTERE LA PRIMA FIRMA verso di se'? Solo dopo la
    conferma di chi compra FIRMATA dal suo seme, su un ordine pagato e
    senza decisioni di Barattolo, e solo se chi vende sceglie allo
    sblocco (Lightning, o ogni volta)."""
    return bool(
        o["stato"] == "pagato" and o["rilascio_chiesto_il"]
        and o["rilascio_firma"] and not o["decisione_da"]
        and onchain_modo_ordine(con, o) != "onchain"
        and onchain_firma_valida_testo(
            ind["xpub_compratore"],
            onchain_messaggio_ricevuto(o["id"], ind["indirizzo"]),
            o["rilascio_firma"]))


def _onchain_da_sbloccare(con, oid: int, tg_id: int):
    """L'ordine su cui chi vende sceglie adesso come ricevere: suo, pagato,
    confermato da chi compra con la firma, senza uscita ne' proposta.
    Torna (riga, indirizzo) o alza col perche'."""
    o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                    (int(oid),)).fetchone()
    if not o:
        raise HTTPException(404, "Ordine non trovato")
    if _onchain_parte(o, tg_id) != "venditore":
        raise HTTPException(403, "Come ricevere lo sceglie chi vende")
    if o["stato"] != "pagato" or o["incasso"] or o["proposta_psbt"]:
        raise HTTPException(409, "Su questo ordine non c'è niente da "
                                 "scegliere adesso")
    _onchain_ordine_permette(con, o, "venditore")
    # l'acquisto grosso esce on-chain (17 nov 2026): niente cambio in
    # Lightning, e lo si dice invece di «non ha ancora confermato»
    if _onchain_grosso(o):
        raise HTTPException(409, "Per una cifra così ricevi on-chain: scegli "
                                 "dove in Profilo → «Incassi on-chain»")
    ind = con.execute("SELECT * FROM onchain_indirizzi WHERE id=?",
                      (o["indirizzo_id"],)).fetchone()
    if not _onchain_puo_firmare_prima(con, o, ind):
        raise HTTPException(409, "Chi compra non ha ancora confermato di "
                                 "averlo ricevuto")
    return o, ind


async def swap_stato_di(fornitore: dict, swap_id: str) -> str | None:
    """Lo stato di uno swap come lo dice il fornitore (`GET /v2/swap/<id>`).
    None = non risponde (o in collaudo non si esce dal computer); uno
    swap che il fornitore non conosce e' «swap.sconosciuto»."""
    base = str(fornitore.get("api") or "").rstrip("/")
    if not base or not _SWAP_ID_FORMA.match(str(swap_id or "")) \
            or swap_lettura_simulata(base):
        return None
    try:
        async with httpx.AsyncClient(timeout=8) as c:
            r = await c.get(f"{base}/v2/swap/{swap_id}")
        if r.status_code == 404:
            return "swap.sconosciuto"
        if r.status_code != 200:
            return None
        return str((r.json() or {}).get("status") or "") or None
    except Exception:
        return None


async def onchain_cambio_perche_morto(o) -> str | None:
    """'' se il cambio di un ordine e' vivo (aspetta i bitcoin, e la
    fattura ha davanti almeno due ore), sennò il perche'; None se il
    fornitore non risponde e non si sa."""
    c = _onchain_cambio_letto(o) or {}
    if not c.get("id"):
        return "manca il cambio"
    if int(c.get("scade_fattura") or 0) - time.time() < ONCHAIN_CAMBIO_VITA_MIN_S:
        return "la fattura scade troppo presto"
    f = swap_fornitore(str(c.get("fornitore") or "satsrouting"))
    if f is None:
        return "fornitore sconosciuto"
    stato = await swap_stato_di(f, str(c["id"]))
    if stato is None:
        return None
    if stato != "invoice.set":
        return f"lo swap è «{stato}»"
    return ""


async def _onchain_cambio_togli(o, perche: str, avvisa: bool = True) -> bool:
    """Il cambio di un ordine se ne va prima che partano i sats: l'uscita e
    la proposta tornano vuote, e chi vende lo rifa' dall'ordine (o sceglie
    l'on-chain). Torna True se c'era da togliere."""
    con = _onchain_db_ordini()
    try:
        cur = con.execute(
            "UPDATE onchain_ordini SET incasso='', incasso_tipo='',"
            " incasso_valore='', incasso_firma='', incasso_indice=0,"
            " cambio='', proposta_verso='', proposta_psbt='', proposta_da=0,"
            " proposta_il=0, aggiornato=? WHERE id=? AND incasso_tipo='cambio'"
            # (14 nov 2026, audit) ...mai sopra una decisione firmata da
            # Barattolo: quella non si sostituisce (come a /proposta)
            " AND stato='pagato' AND COALESCE(decisione_da, 0)=0",
            (int(time.time()), o["id"]))
        con.commit()
        tolto = bool(cur.rowcount)
    finally:
        con.close()
    if tolto and avvisa:
        await notifica(o["venditore_id"],
            f"⚡ <b>{html.escape(o['titolo'][:40])}:</b> lo swap in "
            f"Lightning non è partito ({html.escape(perche)}). Non si è "
            "mosso niente: apri l'ordine e rifallo, o ricevi on-chain.")
    return tolto


@app.post("/api/onchain/incasso/modo")
async def onchain_incasso_modo(req: Request, x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """«COME RICEVI QUANDO VENDI ON-CHAIN» (28 ott 2026): {modo: 'onchain' |
    'lightning' | 'ogni_volta'}. Vale dalle vendite dopo, e per quelle che
    aspettano ancora la scelta; tornando a «onchain» le vendite senza
    uscita prendono il wallet scelto, come quando lo si salva."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_incasso", user["id"])
    d = await leggi_json(req)
    modo = str(d.get("modo") or "")
    if modo not in ONCHAIN_MODI:
        raise HTTPException(400, "Scelta sconosciuta")
    if modo != "onchain" and not onchain_ln_per(user["id"]):
        raise HTTPException(403, "Lo swap in Lightning non è disponibile")
    riempiti, riempiti_p2p = [], []
    con = _onchain_db()
    try:
        if modo == "onchain":
            con.execute("DELETE FROM onchain_modo WHERE tg_id=?", (user["id"],))
        else:
            con.execute("INSERT INTO onchain_modo(tg_id, modo, aggiornato) "
                        "VALUES (?,?,?) ON CONFLICT(tg_id) DO UPDATE SET "
                        "modo=excluded.modo, aggiornato=excluded.aggiornato",
                        (user["id"], modo, int(time.time())))
        con.commit()
        if modo == "onchain":
            _onchain_prepara_ordini(con)
            riempiti = _onchain_riempi_incassi(con, user["id"])
            riempiti_p2p = _p2p_onchain_riempi_incassi(con, user["id"])   # gli scambi P2P (30 ott)
            con.commit()
    finally:
        con.close()
    await _p2p_onchain_avvisa_riempiti(riempiti_p2p)   # (17 nov 2026, avviso-indirizzo)
    for o in riempiti:
        if o["rilascio_chiesto_il"]:
            await notifica(o["compratore_id"],
                f"₿ <b>{html.escape(o['titolo'][:40])}:</b> chi vende ha "
                "scelto dove ricevere. Apri la Mini App: il tuo telefono firma "
                "il rilascio che avevi confermato, e i sats partono.")
    return {"ok": True, "modo": modo, "ordini_aggiornati": len(riempiti)}


async def _onchain_preventivo_cambio(sats: int) -> dict:
    """Il preventivo del cambio per `sats` nel 2-di-3, col primo fornitore."""
    f = swap_fornitori()[0]
    busta = {"fornitore": f["id"], "fornitore_nome": f["nome"],
             "prezzo": int(sats)}
    tariffa = await leggi_tariffa_sub(f)
    if tariffa is None:
        return dict(busta, ok=False, motivo="non_risponde")
    # il tetto e' solo quello del fornitore: SWAP_MAX_SATS guarda i sats
    # che Barattolo paga dalla cassaforte, e qui la cassaforte non c'e'
    return dict(busta, **preventivo_sub_da_mandare(sats, tariffa, SWAP_MIN_SATS))


@app.get("/api/onchain/cambio/esempio")
async def onchain_cambio_esempio(sats: int = 100_000,
                                 x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """L'esempio del Profilo: su `sats` venduti on-chain, quanti ne
    arriverebbero in Lightning col cambio di adesso. Non crea niente."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ln_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_cambio", user["id"])
    return await _onchain_preventivo_cambio(max(1, min(int(sats), 21_000_000 * 100_000_000)))


@app.get("/api/onchain/ordini/{oid}/cambio/preventivo")
async def onchain_cambio_preventivo(oid: int, x_tg_init_data: str = Header(""),
                                    barattolo_sessione: str = Cookie("")):
    """IL PREVENTIVO DEL CAMBIO DI UN ORDINE, per chi vende: il prezzo
    esce tutto verso il fornitore, e in Lightning arriva `ricevi`. Con le
    soglie della fattura e il suo Lightning address, se c'e'."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ln_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_cambio", user["id"])
    _onchain_serve_embit()
    con = _onchain_db_ordini()
    try:
        o, _ = _onchain_da_sbloccare(con, oid, user["id"])
        modo = onchain_modo_ordine(con, o)
        u = con.execute("SELECT ln_address FROM utenti WHERE tg_id=?",
                        (user["id"],)).fetchone()
    finally:
        con.close()
    p = await _onchain_preventivo_cambio(o["prezzo_sats"])
    return dict(p, modo=modo, ln_address=bool(u and (u["ln_address"] or "").strip()),
                vita_incollata_s=ONCHAIN_CAMBIO_VITA_INCOLLATA_S,
                vita_address_s=ONCHAIN_CAMBIO_VITA_ADDRESS_S)


@app.post("/api/onchain/ordini/{oid}/cambio/fattura")
async def onchain_cambio_fattura(oid: int, req: Request,
                                 x_tg_init_data: str = Header(""),
                                 barattolo_sessione: str = Cookie("")):
    """LA FATTURA DAL LIGHTNING ADDRESS DI CHI VENDE («sempre Lightning»):
    la chiede il server, come per gli incassi Lightning di sempre
    (`invoice_da_ln_address`). LIMITE DICHIARATO nel piano: un server
    manomesso potrebbe dare una fattura sua; con la fattura incollata
    no. Il telefono la rilegge (importo, rete, scadenza) prima del cambio."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ln_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_cambio", user["id"])
    _frena("ln_address", user["id"])
    d = await leggi_json(req)
    try:
        sats = int(d.get("sats") or 0)
    except (TypeError, ValueError):
        sats = 0
    con = _onchain_db_ordini()
    try:
        o, _ = _onchain_da_sbloccare(con, oid, user["id"])
        u = con.execute("SELECT ln_address FROM utenti WHERE tg_id=?",
                        (user["id"],)).fetchone()
    finally:
        con.close()
    if not 0 < sats < int(o["prezzo_sats"]):
        raise HTTPException(400, "Cifra della fattura fuori misura")
    ln = (u["ln_address"] if u else "") or ""
    if not ln.strip():
        raise HTTPException(409, "Nel tuo profilo non c'è un Lightning "
                                 "address: incolla una fattura")
    try:
        pr = await invoice_da_ln_address(ln, sats)
    except LnbitsMuto:
        raise HTTPException(503, "Adesso non riusciamo a leggere la fattura: "
                                 "riprova fra poco, o incollane una")
    if not pr:
        raise HTTPException(409, f"Il tuo Lightning address non ha dato una "
                                 f"fattura da {_fmt_sats(sats)} sats: "
                                 "incollane una")
    return {"ok": True, "fattura": pr}


@app.post("/api/onchain/ordini/{oid}/cambio")
async def onchain_cambio_nasce(oid: int, req: Request,
                               x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """IL CAMBIO NASCE SULL'ORDINE: il telefono di chi vende porta le parti
    pubbliche del cambio (fornitore, id, l'indirizzo dove mandare, quanto,
    la scadenza della fattura), la firma del SUO seme su quell'indirizzo
    (`onchain_firma_valida`, tipo «cambio», valore «<ordine>:<indirizzo>»)
    e la PRIMA firma del rilascio verso quell'indirizzo, col prezzo
    esatto. Il server giudica tutto con le regole di sempre e lo scrive in
    un colpo solo; chi compra mette la seconda firma quando apre l'app."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ln_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    _frena("onchain_cambio", user["id"])
    _frena("onchain_firma", user["id"])
    _onchain_serve_embit()
    d = await leggi_json(req)
    c = d.get("cambio") if isinstance(d.get("cambio"), dict) else {}
    firma = str(d.get("firma") or "").strip().lower()
    psbt_b64 = str(d.get("psbt") or "").strip()
    if not psbt_b64 or len(psbt_b64) > 20000:
        raise HTTPException(400, "Manca la prima firma")
    lockup = str(c.get("lockup") or "").strip()
    swap_id = str(c.get("id") or "").strip()
    try:
        ricevi, mandi = int(c.get("ricevi") or 0), int(c.get("mandi") or 0)
        scade = int(c.get("scade_fattura") or 0)
        timeout = int(c.get("timeout") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "Lo swap non si legge")
    fornitore = swap_fornitore(str(c.get("fornitore") or "satsrouting"))
    if fornitore is None or not onchain_ln_rete_ok(fornitore):
        raise HTTPException(400, "Fornitore sconosciuto")
    if not _SWAP_ID_FORMA.match(swap_id) or timeout <= 0:
        raise HTTPException(400, "Lo swap non si legge")
    # l'indirizzo del cambio: un taproot della rete dell'on-chain
    from embit.script import address_to_scriptpubkey
    rete = _onchain_rete()
    try:
        sc = address_to_scriptpubkey(lockup)
        buono = sc.script_type() == "p2tr" and sc.address(rete) == lockup
    except Exception:
        buono = False
    if not buono:
        raise HTTPException(400, "L'indirizzo dello swap non è della rete "
                                 "giusta")
    if scade - time.time() < ONCHAIN_CAMBIO_VITA_MIN_S:
        raise HTTPException(400, "La fattura scade troppo presto: creane "
                                 "una che duri di più")
    con = _onchain_db_ordini()
    try:
        o, ind = _onchain_da_sbloccare(con, oid, user["id"])
        if not 0 < ricevi < mandi <= int(o["prezzo_sats"]):
            raise HTTPException(400, "Le cifre dello swap non tornano col "
                                     "prezzo dell'ordine")
        valore = f"{o['id']}:{lockup}"
        if not onchain_firma_valida(ind["xpub_venditore"], "cambio", valore,
                                    firma):
            raise HTTPException(400, "Lo swap non è firmato dal tuo seme: "
                                     "rifallo da questo telefono")
        giudicato = dict(o)
        giudicato["incasso"] = lockup
        try:
            _onchain_psbt_giudica(giudicato, "venditore", psbt_b64,
                                  ind["chiave_venditore"])
        except ValueError as e:
            raise HTTPException(400, f"Proposta rifiutata: {e}")
        adesso = int(time.time())
        cambio = json.dumps({"fornitore": fornitore["id"], "id": swap_id,
                             "lockup": lockup, "ricevi": ricevi,
                             "mandi": mandi, "scade_fattura": scade,
                             "timeout": timeout, "il": adesso})
        cur = con.execute(
            "UPDATE onchain_ordini SET incasso=?, incasso_tipo='cambio',"
            " incasso_valore=?, incasso_firma=?, incasso_indice=0, cambio=?,"
            " proposta_verso='venditore', proposta_psbt=?, proposta_da=?,"
            " proposta_il=?, aggiornato=? WHERE id=? AND incasso='' AND"
            " proposta_psbt='' AND stato='pagato'",
            (lockup, valore, firma, cambio, psbt_b64, user["id"], adesso,
             adesso, o["id"]))
        con.commit()
        if not cur.rowcount:
            raise HTTPException(409, "L'ordine è cambiato nel frattempo: "
                                     "riaprilo")
    finally:
        con.close()
    await notifica(o["compratore_id"],
        f"₿ <b>{html.escape(o['titolo'][:40])}:</b> chi vende ha scelto di "
        "ricevere in Lightning. Apri la Mini App: il tuo telefono firma il "
        "rilascio che avevi confermato, e i sats partono.")
    return {"ok": True}


@app.post("/api/onchain/ordini/{oid}/cambio/togli")
async def onchain_cambio_togli(oid: int, x_tg_init_data: str = Header(""),
                               barattolo_sessione: str = Cookie("")):
    """Chi vende toglie il suo cambio prima che partano i sats (per
    rifarlo, o per ricevere on-chain)."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ammesso(user["id"]):
        raise HTTPException(404, "Non esiste")
    con = _onchain_db_ordini()
    try:
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (oid,)).fetchone()
        if not o:
            raise HTTPException(404, "Ordine non trovato")
        if _onchain_parte(o, user["id"]) != "venditore":
            raise HTTPException(403, "Lo swap lo toglie chi vende")
    finally:
        con.close()
    if not await _onchain_cambio_togli(o, "tolto da chi vende", avvisa=False):
        raise HTTPException(409, "Su questo ordine non c'è uno swap da togliere")
    return {"ok": True}


@app.post("/api/onchain/ordini/{oid}/incasso-ora")
async def onchain_incasso_ora(oid: int, x_tg_init_data: str = Header(""),
                              barattolo_sessione: str = Cookie("")):
    """«RICEVI ON-CHAIN» ALLO SBLOCCO (28 ott 2026): chi sceglie ogni volta,
    o chi sta sotto il minimo del cambio, prende per QUESTO ordine il suo
    wallet on-chain (la destinazione firmata dal seme, come alla cassa).
    Torna l'ordine: il suo telefono rilegge la destinazione e mette la
    prima firma (`/proposta`), chi compra la seconda."""
    user = verifica_utente(x_tg_init_data, barattolo_sessione)
    if not onchain_ln_per(user["id"]):
        raise HTTPException(404, "Non esiste")
    _onchain_serve_embit()
    con = _onchain_db_ordini()
    try:
        o, ind = _onchain_da_sbloccare(con, oid, user["id"])
        dest = _onchain_destinazione_viva(con, user["id"], ind["xpub_venditore"])
        if not dest:
            raise HTTPException(409, "Prima scegli dove ricevere on-chain "
                                     "(Profilo → «Incassi on-chain»)")
        indice = (_onchain_prossimo_esterno(con, user["id"], dest["valore"])
                  if dest["tipo"] == "xpub" else 0)
        cur = con.execute(
            "UPDATE onchain_ordini SET incasso=?, incasso_tipo=?,"
            " incasso_valore=?, incasso_firma=?, incasso_indice=?,"
            " aggiornato=? WHERE id=? AND incasso='' AND proposta_psbt=''",
            (onchain_indirizzo_esterno(dest["tipo"], dest["valore"], indice),
             dest["tipo"], dest["valore"], dest["firma"], indice,
             int(time.time()), o["id"]))
        con.commit()
        if not cur.rowcount:
            raise HTTPException(409, "L'ordine è cambiato nel frattempo: "
                                     "riaprilo")
        o = con.execute("SELECT * FROM onchain_ordini WHERE id=?",
                        (o["id"],)).fetchone()
        return {"ok": True, "onchain": _onchain_ordine_per(con, o, user["id"])}
    finally:
        con.close()


